/*!50106 set global event_scheduler = 1*/;

/* Event structure for event `AutoKillSleepingConnections` */

/*!50106 DROP EVENT IF EXISTS `AutoKillSleepingConnections`*/;

DELIMITER $$

/*!50106 CREATE DEFINER=`root`@`localhost` EVENT `AutoKillSleepingConnections` ON SCHEDULE EVERY 5 MINUTE STARTS '2024-12-05 00:56:32' ON COMPLETION NOT PRESERVE ENABLE DO CALL spKillSleepingConnections() */$$
DELIMITER ;

/* Event structure for event `CheckAndUpdateSNStatus` */

/*!50106 DROP EVENT IF EXISTS `CheckAndUpdateSNStatus`*/;

DELIMITER $$

/*!50106 CREATE DEFINER=`root`@`localhost` EVENT `CheckAndUpdateSNStatus` ON SCHEDULE EVERY 60 MINUTE STARTS '2025-03-08 01:41:45' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE var_id INT;
    DECLARE var_sn VARCHAR(45);
    DECLARE var_description VARCHAR(45);
    DECLARE v_ClientID INT;
    DECLARE v_LocationID INT;
    DECLARE v_StatusID INT;
    DECLARE cur CURSOR FOR SELECT ID, SN, Description FROM event_status_update_sn;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    SET v_ClientID = 21;
    SET v_LocationID = 18;
    SET v_StatusID = 7;

    -- Ensure the table exists
    CREATE TABLE IF NOT EXISTS event_log_message_update_sn (ID INT AUTO_INCREMENT PRIMARY KEY,Message VARCHAR(255),EventTime TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS event_status_update_sn (ID INT, SN VARCHAR(45), Description VARCHAR(45));

    -- Debug: Log event execution
    INSERT INTO event_log_message_update_sn (Message) VALUES (CONCAT('Event started at ', NOW()));
   
    -- Clear previous data
    DELETE FROM event_status_update_sn;

    -- Populate temporary table based on search type
    INSERT INTO event_status_update_sn (ID, SN, Description)
        SELECT td.TerminalID, td.TerminalSN, "Terminal" 
        FROM tblterminaldetail td 
	LEFT JOIN tblfsrdetail fsr ON td.TerminalID = fsr.TerminalID AND fsr.JobType = 1 AND fsr.ActionMade = 'SUCCESS'
	LEFT JOIN tblservicingdetail svc ON td.TerminalID = svc.TerminalID AND svc.JobType = 1 AND svc.JobTypeStatusDescription = 'COMPLETED'
	WHERE
	td.ClientID = v_ClientID 
	AND td.TerminalStatus != v_StatusID
	AND td.LocationID = v_LocationID
	ORDER BY fsr.FSRNo
	LIMIT 1;

    INSERT INTO event_status_update_sn (ID, SN, Description)
        SELECT td.SIMID, td.SIMSN, "SIM" 
        FROM tblsimdetail td
        LEFT JOIN tblfsrdetail fsr ON td.SIMID = fsr.SIMID AND fsr.JobType = 1 AND fsr.ActionMade = 'SUCCESS'
	LEFT JOIN tblservicingdetail svc ON td.SIMID = svc.SIMID AND svc.JobType = 1 AND svc.JobTypeStatusDescription = 'COMPLETED'
	WHERE
	td.ClientID = v_ClientID 
	AND td.SIMStatus != v_StatusID
	AND td.LocationID = v_LocationID
	ORDER BY fsr.FSRNo
	LIMIT 1;

    -- Debug: Log inserted data count
    #INSERT INTO event_log_message_update_sn (Message) VALUES (CONCAT('Inserted ', ROW_COUNT(), ' rows into event_status_update_sn'));

    -- Open cursor
    OPEN cur;

    -- Loop through cursor
    read_loop: LOOP
        FETCH cur INTO var_id, var_sn, var_description;
        IF done THEN 
            LEAVE read_loop;
        END IF;

        -- Debug: Log fetched data
        SET @message = CONCAT('Processing ID: ', var_id, '|',
			      'SN: ', var_sn, '|',
			      'Description: ', var_description);
        INSERT INTO event_log_message_update_sn (Message) VALUES (@message);

        -- Update query based on search type
        IF var_description = 'Terminal' THEN
            SET @QUERY = CONCAT('UPDATE tblterminaldetail SET TerminalStatus = 7, TerminalStatusDescription = "INSTALLED" WHERE TerminalID = ', var_id, ';');
        ELSEIF var_description = 'SIM' THEN
            SET @QUERY = CONCAT('UPDATE tblsimdetail SET SIMStatus = 7, SIMStatusDescription = "INSTALLED" WHERE SIMID = ', var_id, ';');
        END IF;

        -- Execute update query 
              
        IF (var_id IS NOT NULL && LENGTH(var_description) > 0) THEN
        
	    SET @message = CONCAT("Update executed > ", @QUERY);
	    INSERT INTO event_log_message_update_sn (Message) VALUES (@message);
	    
            PREPARE QUERY FROM @QUERY;
            EXECUTE QUERY;
            DEALLOCATE PREPARE QUERY;
        END IF;
        
        
    END LOOP;

    -- Close cursor
    CLOSE cur;

    -- Debug: Log event completion
    INSERT INTO event_log_message_update_sn (Message) VALUES ('Event execution completed');

END */$$
DELIMITER ;

