/* Event structure for event `GetInstalledTerminals` */

/*!50106 DROP EVENT IF EXISTS `GetInstalledTerminals`*/;

DELIMITER $$

/*!50106 CREATE DEFINER=`root`@`localhost` EVENT `GetInstalledTerminals` ON SCHEDULE EVERY 1 MONTH STARTS '2024-11-01 17:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK; -- Rollback if any error occurs
    END;

    START TRANSACTION;

    TRUNCATE tblbilling_terminals;

    INSERT INTO tblbilling_terminals(
        Ir_ID, Merchant_ID, TID, MID, Terminal_ID, Sim_ID, 
        Service_ID, Client_ID, Service_Date, Coverage_Date, Created_Date
    )
    SELECT
        ir.IRIDNo,
        ir.MerchantID,
        ir.TID,
        ir.MID,
        td.TerminalID AS Terminal_ID,
        COALESCE(si.Sim_ID, 0) AS Sim_ID,
        jo.Service_ID,
        td.ClientID,
        jo.Service_Date,
        LAST_DAY(DATE_SUB(CURDATE(), INTERVAL 1 MONTH)) AS Coverage_Date,
        CURDATE() AS Created_Date
    FROM tblterminaldetail td
    LEFT JOIN tblirdetail ir ON ir.TerminalID = td.TerminalID
    LEFT JOIN vw_sim_info si ON si.Sim_ID = ir.SIMID
    LEFT JOIN (
        SELECT DISTINCT
            a.IRIDNo,
            MAX(a.ServiceNo) AS Service_ID,
            b.FSRDate AS Service_Date
        FROM tblservicingdetail a
        LEFT JOIN tblfsrdetail b ON b.ServiceNo = a.ServiceNo
        WHERE
            a.JobType IN (1, 7)  -- INSTALLATION/REPLACEMENT
            AND a.ServiceStatus = 7  -- INSTALLED
            AND a.ClientID = 21
            AND a.JobTypeStatusDescription = 'COMPLETED'
            AND b.ActionMade = 'SUCCESS'
        GROUP BY a.IRIDNo
    ) jo ON jo.IRIDNo = ir.IRIDNo
    WHERE td.TerminalStatus = 7;  -- Installed

    CALL spBillingProcess(21); -- Generate Billing

    COMMIT; -- Commit the transaction if all operations succeed
END */$$
DELIMITER ;

/* Function  structure for function  `ADD_DOUBLEQUOTE` */

