/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `ADD_DOUBLEQUOTE`( pValue TEXT ) RETURNS text CHARSET utf8mb3
BEGIN

   DECLARE v_Temp TEXT;

   SET v_Temp = '';

   SET v_Temp = IFNULL(pValue, '-');

   

   RETURN CONCAT('"', v_Temp, '"');

END */$$
