/* Function  structure for function  `fnGetAttempts` */

/*!50003 DROP FUNCTION IF EXISTS `fnGetAttempts` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `fnGetAttempts`(
    p_IRIDNo VARCHAR(50), 
    p_JobType VARCHAR(50), 
    p_IRNo VARCHAR(50), 
    p_Attempt INT, 
    p_column_name VARCHAR(50)
) RETURNS longtext CHARSET utf8mb3
BEGIN
    DECLARE result_value LONGTEXT;
    
    -- If p_Attempt is 0, return the total number of attempts
    IF p_Attempt = 0 THEN
        SELECT COUNT(*) INTO result_value
        FROM tblfsrdetail
        WHERE IRIDNo = p_IRIDNo 
            AND JobType = p_JobType 
            AND IRNo = p_IRNo;
    ELSE
        -- Get the requested column for the specified attempt
        SELECT CASE 
            WHEN p_column_name = 'Reason' THEN Reason
            WHEN p_column_name = 'FSRDate' THEN FSRDate
            WHEN p_column_name = 'ActionMade' THEN ActionMade
            WHEN p_column_name = 'ActionTaken' THEN ActionTaken
				WHEN p_column_name = 'ProblemReported' THEN ProblemReported
            WHEN p_column_name = 'ActualProblemReported' THEN ActualProblemReported
            WHEN p_column_name = 'isBillable' THEN isBillable
        END INTO result_value
        FROM (
            SELECT 
                Reason, FSRDate, ActionMade, ActionTaken, ProblemReported, ActualProblemReported, isBillable, @row_number := @row_number + 1 AS AttemptNo
            FROM tblfsrdetail, (SELECT @row_number := 0) AS rn
            WHERE IRIDNo = p_IRIDNo 
                AND JobType = p_JobType 
                AND IRNo = p_IRNo
            ORDER BY FSRDate
        ) AS attempts
        WHERE AttemptNo = p_Attempt
        LIMIT 1;
    END IF;

    RETURN IFNULL(result_value, null);  -- Ensure NULL values return as empty strings
END */$$
DELIMITER ;

/* Function  structure for function  `fnJsonExtract` */

/*!50003 DROP FUNCTION IF EXISTS `fnJsonExtract` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `fnJsonExtract`(JSON_VALUE TEXT, key_path TEXT) RETURNS text CHARSET utf8mb3
BEGIN

    DECLARE extracted_value TEXT;

    

    -- Extract the value of the specified key from the JSON string

    SET extracted_value = JSON_UNQUOTE(JSON_EXTRACT(JSON_VALUE, key_path));

     -- Check if the extracted value is NULL or empty and return NULL if so
    IF extracted_value IS NULL OR extracted_value = '' THEN
        RETURN NULL;
    END IF;

    RETURN extracted_value;

END */$$
DELIMITER ;

/* Function  structure for function  `funcAddWorkingDays` */

/*!50003 DROP FUNCTION IF EXISTS `funcAddWorkingDays` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcAddWorkingDays`(
    p_start DATE,
    p_days INT
) RETURNS date
    DETERMINISTIC
BEGIN
    DECLARE v_date DATE;
    DECLARE v_count INT DEFAULT 0;

    SET v_date = p_start;

    WHILE v_count < p_days DO
        SET v_date = DATE_ADD(v_date, INTERVAL 1 DAY);

        IF WEEKDAY(v_date) NOT IN (5,6)
           AND NOT EXISTS (
                SELECT 1
                FROM tblholiday h
                WHERE h.isActive = 1
                  AND DATE_FORMAT(v_date, '%m-%d') = h.HolidayDate
           )
        THEN
            SET v_count = v_count + 1;
        END IF;

    END WHILE;

    RETURN v_date;
END */$$
DELIMITER ;

/* Function  structure for function  `funcComputeTAT` */

/*!50003 DROP FUNCTION IF EXISTS `funcComputeTAT` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcComputeTAT`(startDate DATE, endDate DATE) RETURNS int
BEGIN

DECLARE totalDays INT;
DECLARE totalWeekends INT;
DECLARE totalHoliday INT;
DECLARE totalNonWorkingDays INT;
DECLARE p_out INT;

-- Calculate the total number of days between startDate and endDate (absolute value to handle date order)
SET totalDays = 0;
SET totalDays = ABS(DATEDIFF(startDate, endDate)); -- Include both startDate and endDate

-- Call the funcCountWeekends function to calculate total weekends in the range
SET totalWeekends = 0;
SET totalWeekends = funcCountWeekends(LEAST(startDate, endDate), GREATEST(startDate, endDate));

-- Call the funcCountHoliday to get the holiday count
SET totalHoliday = 0;
SET totalHoliday = funcCountHoliday(LEAST(startDate, endDate), GREATEST(startDate, endDate));

SET totalNonWorkingDays = totalWeekends + totalHoliday;

-- Subtract weekends from total days to compute TAT (excluding weekends)
SET p_out = totalDays - totalNonWorkingDays;

-- Add a sign to p_out based on the order of startDate and endDate
IF (startDate > endDate) THEN
	SET p_out = -p_out; -- Make the result negative if startDate is after endDate
END IF;
    
RETURN p_out;

END */$$
DELIMITER ;

/* Function  structure for function  `funcContainsWord` */

/*!50003 DROP FUNCTION IF EXISTS `funcContainsWord` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcContainsWord`(
    pText TEXT,
    pWord VARCHAR(255)
) RETURNS tinyint
    READS SQL DATA
BEGIN

    DECLARE vText TEXT;
    DECLARE vWord TEXT;

    DECLARE vToken VARCHAR(255);

    DECLARE vSearch TEXT;

    DECLARE vPos INT DEFAULT 1;
    DECLARE vNext INT;

    /*---------------------------------------
      Validate
    ---------------------------------------*/

    IF pText IS NULL
       OR pWord IS NULL
       OR TRIM(pText) = ''
       OR TRIM(pWord) = '' THEN

        RETURN 0;

    END IF;

    /*---------------------------------------
      Normalize once
    ---------------------------------------*/

    SET vText =
        CONCAT(
            ' ',
            funcNormalizeLocation(pText),
            ' '
        );

    SET vWord =
        funcNormalizeLocation(pWord);

    /*---------------------------------------
      No Slash
    ---------------------------------------*/

    IF INSTR(vWord,'/') = 0 THEN

        SET vSearch =
            CONCAT(
                ' ',
                TRIM(vWord),
                ' '
            );

        IF INSTR(vText,vSearch)=0 THEN
            RETURN 0;
        END IF;

        IF INSTR(vText,CONCAT(' __BRGY__ ',TRIM(vWord),' '))>0 THEN
            RETURN 0;
        END IF;

        IF INSTR(vText,CONCAT(' __SITIO__ ',TRIM(vWord),' '))>0 THEN
            RETURN 0;
        END IF;

        IF INSTR(vText,CONCAT(' __PUROK__ ',TRIM(vWord),' '))>0 THEN
            RETURN 0;
        END IF;

        RETURN 1;

    END IF;

    /*---------------------------------------
      Slash Support

      Example

      PASIG/ORTIGAS

      becomes

      PASIG
      ORTIGAS
    ---------------------------------------*/

    SET vWord =
        CONCAT(
            REPLACE(vWord,'/',' / '),
            ' '
        );

    SET vPos = 1;

    slash_loop:
    LOOP

        SET vNext = LOCATE('/',vWord,vPos);

        IF vNext = 0 THEN
            SET vNext = LOCATE(' ',vWord,vPos);

            IF vNext = 0 THEN
                LEAVE slash_loop;
            END IF;
        END IF;

        SET vToken =
            TRIM
            (
                SUBSTRING
                (
                    vWord,
                    vPos,
                    vNext-vPos
                )
            );

        IF vToken<>'' THEN

            SET vSearch =
                CONCAT(
                    ' ',
                    vToken,
                    ' '
                );

            IF INSTR(vText,vSearch)>0 THEN

                IF INSTR(vText,CONCAT(' __BRGY__ ',vToken,' '))=0
                AND INSTR(vText,CONCAT(' __SITIO__ ',vToken,' '))=0
                AND INSTR(vText,CONCAT(' __PUROK__ ',vToken,' '))=0 THEN

                    RETURN 1;

                END IF;

            END IF;

        END IF;

        SET vPos = vNext + 1;

        IF vPos > LENGTH(vWord) THEN
            LEAVE slash_loop;
        END IF;

        IF SUBSTRING(vWord,vPos,1)='/' THEN
            SET vPos = vPos + 1;
        END IF;

    END LOOP;

    RETURN 0;

END */$$
DELIMITER ;

/* Function  structure for function  `funcCountHoliday` */

/*!50003 DROP FUNCTION IF EXISTS `funcCountHoliday` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcCountHoliday`(startDate DATE, endDate DATE) RETURNS int
BEGIN
    DECLARE cnt INT DEFAULT 0;
    DECLARE actualStart DATE;
    DECLARE actualEnd DATE;

    -- Determine correct order of dates
    IF (startDate > endDate) THEN
        SET actualStart = endDate;
        SET actualEnd = startDate;
    ELSE
        SET actualStart = startDate;
        SET actualEnd = endDate;
    END IF;

    -- Count holidays by comparing MM-DD parts
    SELECT COUNT(*)
    INTO cnt
    FROM (
        SELECT DATE_FORMAT(DATE_ADD(actualStart, INTERVAL n DAY), '%m-%d') AS md
        FROM (
            SELECT a.N + b.N * 10 AS n
            FROM (
                SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
                UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9
            ) a,
            (
                SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
                UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9
            ) b
        ) AS seq
        WHERE DATE_ADD(actualStart, INTERVAL n DAY) <= actualEnd
    ) AS date_list
    JOIN tblholiday h ON h.HolidayDate = date_list.md;

    RETURN cnt;
END */$$
DELIMITER ;

/* Function  structure for function  `funcCountWeekends` */

/*!50003 DROP FUNCTION IF EXISTS `funcCountWeekends` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcCountWeekends`(startDate DATE, endDate DATE) RETURNS int
BEGIN
    DECLARE weekendCount INT DEFAULT 0;
    DECLARE tempDate DATE;
    DECLARE totalDays INT;

    -- Swap dates if startDate > endDate
    IF (startDate > endDate) THEN
        SET tempDate = startDate;
        SET startDate = endDate;
        SET endDate = tempDate;
    END IF;

    SET totalDays = DATEDIFF(endDate, startDate);

    -- Count weekends between startDate and endDate (inclusive)
    SELECT COUNT(*) INTO weekendCount
    FROM (
        SELECT DATE_ADD(startDate, INTERVAL seq DAY) AS day
        FROM (
            SELECT a.N + b.N * 10 + c.N * 100 AS seq
            FROM (SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 
                  UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a
            CROSS JOIN (SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 
                        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b
            CROSS JOIN (SELECT 0 AS N UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 
                        UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c
        ) seq
        WHERE seq.seq <= totalDays
    ) AS dates
    WHERE DAYOFWEEK(dates.day) IN (1, 7); -- 1 = Sunday, 7 = Saturday

    RETURN weekendCount;
END */$$
DELIMITER ;

/* Function  structure for function  `funcDebugSplitString` */

/*!50003 DROP FUNCTION IF EXISTS `funcDebugSplitString` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcDebugSplitString`(
    p_SearchValue TEXT,
    p_Delimiter CHAR(1)
) RETURNS text CHARSET utf8mb3
    DETERMINISTIC
BEGIN
    DECLARE v_Result TEXT DEFAULT '';
    DECLARE v_Counter INT DEFAULT 1;
    DECLARE v_Part TEXT;
    DECLARE v_PartCount INT;

    -- Number of parts = number of delimiters + 1
    SET v_PartCount =
        LENGTH(p_SearchValue) - LENGTH(REPLACE(p_SearchValue, p_Delimiter, '')) + 1;

    debug_loop: LOOP

        -- Stop only when all parts have been processed
        IF v_Counter > v_PartCount THEN
            LEAVE debug_loop;
        END IF;

        SET v_Part = TRIM(SPLIT_STRING(
            p_SearchValue,
            p_Delimiter,
            v_Counter
        ));

        SET v_Result = CONCAT(
            v_Result,
            'Index ', v_Counter, ': ',
            IF(v_Part IS NULL OR v_Part = '', '[EMPTY]', v_Part),
            CHAR(10)
        );

        SET v_Counter = v_Counter + 1;

        -- Safety limit
        IF v_Counter > 50 THEN
            LEAVE debug_loop;
        END IF;

    END LOOP debug_loop;

    RETURN v_Result;
END */$$
DELIMITER ;

