/* Function  structure for function  `funcGetCount` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetCount` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetCount`( p_StatementType VARCHAR(30), p_SearchBy VARCHAR(255), p_SearchValue TEXT ) RETURNS int
BEGIN
DECLARE v_ID INT;
DECLARE v_Name TEXT;
DECLARE v_Return INT;
DECLARE v_Description TEXT;
DECLARE v_ServiceNo INT;
DECLARE v_FSRNo INT;
DECLARE v_ClientID INT;
DECLARE v_TerminalTypeID INT;
DECLARE v_TerminalModelID INT;
DECLARE v_StatusID INT;
DECLARE v_LocationID INT;
DECLARE v_CarrierID INT;

DECLARE v_JobType INT;
DECLARE v_ActionMade VARCHAR(255);
DECLARE v_Year VARCHAR(45);
DECLARE v_Month VARCHAR(45);
DEcLARE v_JobTypeStatusDescription VARCHAR(255);
DECLARE v_JobTypeList VARCHAR(45);
DECLARE v_ActionMadeList VARCHAR(45);
DECLARE v_RegionList VARCHAR(45);

DECLARE v_RequestType int;
DECLARE v_Region VARCHAR(45);

DECLARE p_out INT;
	IF (p_StatementType = 'Search')

	THEN

		IF (p_SearchBy = 'Gender')

		THEN

			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SELECT COUNT(*) INTO v_Return 

			FROM 

			tblparticular a 

			WHERE a.Gender = v_Name;
			
		ELSEIF (p_SearchBy = 'Incoming Job Order Count')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			IF (v_ID > 0)

			THEN

				SELECT 

				SUM(CASE WHEN b.JobTypeStatusDescription = v_Description THEN 1 ELSE 0 END) INTO v_Return

				FROM 

				tblservicetype a

				LEFT JOIN tblservicingdetail AS b ON a.JobType = b.JobType

				WHERE a.isActive > 0 AND a.FEID = v_ID

				GROUP BY 

				a.JobType;

			ELSE

				SELECT 

				SUM(CASE WHEN b.JobTypeStatusDescription = v_Description THEN 1 ELSE 0 END) INTO v_Return

				FROM 

				tblservicetype a

				LEFT JOIN tblservicingdetail AS b ON a.JobType = b.JobType

				WHERE a.isActive > 0

				GROUP BY 

				a.JobType;

			END IF;
		ELSEIF (p_SearchBy = 'Merchant Service Count')

		THEN													
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT COUNT(*) INTO v_Return 

			FROM 

			tblservicingdetail a 

			WHERE a.IRIDNo = v_ID;
			
		ELSEIF (p_SearchBy = 'SN Service Count')

		THEN													
			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			IF (v_Description = 'Terminal')

			THEN

				SELECT COUNT(*) INTO v_Return 

				FROM 

				tblservicingdetail a 

				WHERE a.TerminalID = v_ID || a.ReplaceTerminalID = v_ID;
				
			ELSEIF (v_Description = 'SIM')

			then

				SELECT COUNT(*) INTO v_Return 

				FROM 

				tblservicingdetail a 

				WHERE a.SIMID = v_ID || a.ReplaceSIMID = v_ID;			

			end if;
		ELSEIF (p_SearchBy = 'SN FSR Count')

		THEN													
			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			IF (v_Description = 'Terminal')

			THEN

				SELECT COUNT(*) INTO v_Return 

				FROM 

				tblfsrdetail a 

				WHERE a.TerminalID = v_ID;
			ELSEIF (v_Description = 'SIM')

			THEN

				SELECT COUNT(*) INTO v_Return 

				FROM 

				tblfsrdetail a 

				WHERE a.SIMID = v_ID;			

			END IF;
		ELSEIF (p_SearchBy = 'Diagnostic Detail')
		THEN
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SELECT 
			COUNT(*) INTO v_Return
			FROM tbldiagnosticdetail a
			WHERE 
			a.ServiceNo = v_ServiceNo 
			AND a.TypeID = 3;	
		
		ELSEIF (p_SearchBy = 'Inventory Terminal Count')
		THEN
			#SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			#SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			#SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT 
			COUNT(*) INTO v_Return
			FROM tblterminaldetail a
			WHERE 
			#a.ClientID = v_ClientID 
			#AND a.TerminalStatus = v_StatusID
			#AND a.LocationID = v_LocationID
			a.TerminalTypeID = v_TerminalTypeID
			AND a.TerminalModelID = v_TerminalModelID;
			
		ELSEIF (p_SearchBy = 'Inventory SIM Count')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_CarrierID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			
			SELECT 
			COUNT(*) INTO v_Return
			FROM tblSIMdetail a
			WHERE a.ClientID = v_ClientID 
			AND a.SIMStatus = v_StatusID
			AND a.LocationID = v_LocationID
			AND a.CarrierID = v_CarrierID;
			
		ELSEIF (p_SearchBy = 'Service Count')
		THEN
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_Year = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_Month = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			
			SELECT
			COUNT(*) INTO v_Return
			FROM
			tblfsrdetail a
			WHERE
			a.JobType = v_JobType
			AND a.ActionMade = v_ActionMade
			AND YEAR(a.FSRDate) = v_Year
			AND MONTH(a.FSRDate) = v_Month;
			
		ELSEIF (p_SearchBy = 'Generate FSR Count')
		THEN
			SELECT 
			COUNT(*) INTO v_Return		
			FROM
			tblfsrdetail a
			LEFT JOIN tblparticular AS b ON a.MerchantID = b.ParticularID AND b.ParticularTypeID = 1
			LEFT JOIN tblservicetype AS c ON a.JobType = c.JobType
			LEFT JOIN tblparticular AS d ON a.FEID = d.ParticularID AND d.ParticularTypeID = 3
			WHERE (a.isActive > 0 AND a.isPDF != 1 AND a.isDiagnostic != 1 AND a.MobileID > 0);
			
		ELSEIF (p_SearchBy = 'Failed Service Count')
		THEN
			SELECT
			COUNT(*) INTO v_Return
			FROM 
			tblservicingdetail a
			LEFT JOIN tblfsrdetail b ON a.ServiceNo = b.ServiceNo
			WHERE 
			a.JobTypeStatusDescription = 'COMPLETED'
			AND b.ServiceNo IS NULL;
			
		ELSEIF (p_SearchBy = 'Import Master Count')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			COUNT(*) INTO v_Return
			FROM
			tblimportmaster a
			WHERE
			a.ControlNo = v_ID;
			
		ELSEIF (p_SearchBy = 'Service RequestID')
		THEN
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT
			COUNT(*) INTO v_Return
			FROM 
			tblservicingdetail a
			WHERE 
			a.JobType = v_JobType
			AND a.IRIDNo = v_ID
			AND a.IRNo = v_Name;
			
		ELSEIF (p_SearchBy = 'Pending Service Count')
		THEN
			SET v_JobTypeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_RegionList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_Year = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_Month = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			
			SELECT
			COUNT(*) INTO v_Return
			FROM
			tblservicingdetail a
			WHERE
			FIND_IN_SET(a.JobType, v_JobTypeList)
			AND FIND_IN_SET(a.JobTypeStatusDescription, 'PENDING,PROCESSING')
			AND YEAR(a.ReqInstallationDate) = v_Year
			AND MONTH(a.ReqInstallationDate) = v_Month;
			
		ELSEIF (p_SearchBy = 'Completed Service Count')
		THEN
			SET v_JobTypeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_ActionMadeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_RegionList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_Year = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_Month = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			
			SELECT
			COUNT(*) INTO v_Return
			FROM
			tblfsrdetail a
			WHERE
			FIND_IN_SET(a.JobType, v_JobTypeList)
			AND FIND_IN_SET(a.ActionMade, v_ActionMadeList)
			AND YEAR(a.FSRDate) = v_Year
			AND MONTH(a.FSRDate) = v_Month;
			
		ELSEIF (p_SearchBy = 'Terminal Used Count')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT 
				COUNT(*) INTO v_Return
			FROM 
				tblservicingdetail a
				LEFT JOIN tblfsrdetail b ON a.ServiceNo = b.ServiceNo
			WHERE 
				a.JobType IN (1,7) 
				AND a.JobTypeStatusDescription = 'COMPLETED'
				AND (a.TerminalID = v_ID OR a.ReplaceTerminalID = v_ID)
				AND b.ActionMade = 'SUCCESS'
				AND a.TerminalSN != '-'
			GROUP BY 
				a.MerchantID, 
				a.TerminalID, 
				a.TerminalSN,
				a.JobType
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Request Type Count') THEN

		    SET v_ClientID    = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
		    SET v_RequestType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);
		    SET v_Year        = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
		    SET v_Month       = TRIM(SPLIT_STRING(p_SearchValue, '|', 4));
		    SET v_Region      = TRIM(SPLIT_STRING(p_SearchValue, '|', 5));

		    SET @RegionType = funcGetID("Search", "Region", v_Region);

		    -- Reprogramming, request type
		    IF (v_RequestType = 9) THEN
			SET @JobType = '3,7';
		    ELSE
			SET @JobType = '1';
		    END IF;

		    SELECT
			    COUNT(*) INTO v_Return
			FROM (
			    SELECT 
			    svc.IRNo
			    FROM tblservicingdetail svc
			    LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo
			    LEFT JOIN tblirdetail ir ON svc.IRIDNo = ir.IRIDNo
			    LEFT JOIN tblparticular pr ON svc.MerchantID = pr.ParticularID
			    WHERE
				svc.ClientID = v_ClientID
				AND YEAR(svc.ServiceDate) = v_Year
				AND MONTH(svc.ServiceDate) = v_Month
				AND (v_RequestType = 9 OR ir.RequestTypeID = v_RequestType)
				AND FIND_IN_SET(svc.JobType, @JobType) AND (svc.JobType != 7 OR fsr.ReasonID = 60)
				AND (v_Region = '[NOT SPECIFIED]' OR v_Region = '0' OR pr.RegionType = @RegionType)
				AND (
				    funcGetDesc("Search", "Daily Service Status", CONCAT(svc.ServiceStatus, "|", IFNULL(fsr.ActionMade, "")))
				    IN ('CANCELLED', 'HOLD', 'PENDING', 'NEGATIVE', 'RESOLVED')
				)							
				AND svc.isActive = 1				
			    GROUP BY svc.IRNo
			) AS grouped;
			
		ELSEIF (p_SearchBy = 'Service Status Count')
		THEN
			SET @ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET @Status = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @Year = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @Month = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET @JobTypeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET @RegionType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			
			IF (@Status = 'RESOLVED') THEN
				SET @Status = 'SUCCESS';
			END IF;
			
			IF (@JobTypeList = '1,3') THEN
			
				SELECT COUNT(*) INTO v_Return
				FROM (
				    SELECT s.IRNo
				    FROM tblservicingdetail s
				    LEFT JOIN tblfsrdetail f ON s.ServiceNo = f.ServiceNo
				    LEFT JOIN tblparticular p ON s.MerchantID = p.ParticularID
				    LEFT JOIN tblregion r ON p.RegionType = r.RegionID
				    WHERE
					s.ClientID = @ClientID
					AND YEAR(s.ReqInstallationDate) = @Year
					AND MONTH(s.ReqInstallationDate) = @Month
					AND (
					    FIND_IN_SET(s.JobType, @JobTypeList) > 0
					    OR (f.JobType = 7 AND f.ReasonID IN (60))
					)
					AND r.Region = @RegionType
				    GROUP BY s.IRNo
				    HAVING 
					(
					    @Status = 'SUCCESS'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'SUCCESS' THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'NEGATIVE'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'SUCCESS' THEN 1 ELSE 0 END) = 0
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'NEGATIVE' THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'CANCELLED'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus = 10 THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'HOLD'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus = 9 THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'PENDING'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus NOT IN (9,10) THEN 1 ELSE 0 END) > 0
					)
				) AS t;	
				
			ELSEIF (@JobTypeList = '6,7') THEN
			
				SELECT COUNT(*) INTO v_Return
				FROM (
				    SELECT s.IRNo
				    FROM tblservicingdetail s
				    LEFT JOIN tblfsrdetail f ON s.ServiceNo = f.ServiceNo
				    LEFT JOIN tblparticular p ON s.MerchantID = p.ParticularID
				    LEFT JOIN tblregion r ON p.RegionType = r.RegionID
				    WHERE
					s.ClientID = @ClientID
					AND YEAR(s.ReqInstallationDate) = @Year
					AND MONTH(s.ReqInstallationDate) = @Month
					AND (
					    FIND_IN_SET(s.JobType, @JobTypeList) > 0
					    AND f.ReasonID NOT IN (60)
					)
					AND r.Region = @RegionType
				    GROUP BY s.IRNo
				    HAVING 
					(
					    @Status = 'SUCCESS'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'SUCCESS' THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'NEGATIVE'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'SUCCESS' THEN 1 ELSE 0 END) = 0
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'NEGATIVE' THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'CANCELLED'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus = 10 THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'HOLD'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus = 9 THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'PENDING'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus NOT IN (9,10) THEN 1 ELSE 0 END) > 0
					)
				) AS t;	
				
			ELSE
				SELECT COUNT(*) INTO v_Return
				FROM (
				    SELECT s.IRNo
				    FROM tblservicingdetail s
				    LEFT JOIN tblfsrdetail f ON s.ServiceNo = f.ServiceNo
				    LEFT JOIN tblparticular p ON s.MerchantID = p.ParticularID
				    LEFT JOIN tblregion r ON p.RegionType = r.RegionID
				    WHERE
					s.ClientID = @ClientID
					AND YEAR(s.ReqInstallationDate) = @Year
					AND MONTH(s.ReqInstallationDate) = @Month
					AND (
					    FIND_IN_SET(s.JobType, @JobTypeList) > 0
					)
					AND r.Region = @RegionType
				    GROUP BY s.IRNo
				    HAVING 
					(
					    @Status = 'SUCCESS'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'SUCCESS' THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'NEGATIVE'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'SUCCESS' THEN 1 ELSE 0 END) = 0
					    AND SUM(CASE WHEN s.JobTypeStatusDescription = 'COMPLETED' AND f.ActionMade = 'NEGATIVE' THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'CANCELLED'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus = 10 THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'HOLD'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus = 9 THEN 1 ELSE 0 END) > 0
					)
					OR
					(
					    @Status = 'PENDING'
					    AND SUM(CASE WHEN s.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') AND s.ServiceStatus NOT IN (9,10) THEN 1 ELSE 0 END) > 0
					)
				) AS t;	
			END IF;
		ELSEIF (p_SearchBy = 'Remaining Service-Field Engineer')
		THEN
			SET @FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			COUNT(*) INTO v_Return
			FROM 
			tblservicingdetail a			
			WHERE
			a.isActive 
			AND a.JobTypeStatusDescription != 'COMPLETED'
			AND a.ServiceStatus = 8
			AND a.FEID = @FEID; # DISPATCH
				
		END IF;
	END IF;
	
   IF (ISNULL(v_Return))
   THEN
	SET v_Return = 0;
   END IF;
   
   SET p_out = v_Return;
  
   RETURN p_out;
END */$$
DELIMITER ;

/* Function  structure for function  `funcGetDaysOverDue` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetDaysOverDue` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetDaysOverDue`(
    p_StatementType VARCHAR(30),
    p_SearchBy VARCHAR(255),
    p_SearchValue TEXT
) RETURNS int
    DETERMINISTIC
BEGIN

    DECLARE v_Return INT DEFAULT 0;
    DECLARE v_ServiceNo INT DEFAULT 0;

    DECLARE v_RequestDate DATE;
    DECLARE v_CompletionDate DATE;

    DECLARE v_Current DATE;
    DECLARE v_EndDate DATE;

    DECLARE v_Days INT DEFAULT 0;
    DECLARE v_Sign INT DEFAULT 1;

    IF p_StatementType = 'Search' THEN

        IF p_SearchBy = 'Days OverDue' THEN

            SET v_ServiceNo = CAST(
                TRIM(SPLIT_STRING(p_SearchValue,'|',1))
                AS UNSIGNED
            );

            SELECT
                NULLIF(a.ServiceReqDate,'0000-00-00'),
                CASE
                    WHEN b.FSRDate IS NULL
                      OR b.FSRDate='0000-00-00'
                    THEN CURDATE()
                    ELSE b.FSRDate
                END
            INTO
                v_RequestDate,
                v_CompletionDate
            FROM tblservicingdetail a
            LEFT JOIN tblfsrdetail b
                   ON a.ServiceNo=b.ServiceNo
            WHERE a.ServiceNo=v_ServiceNo
            LIMIT 1;

            IF v_RequestDate IS NOT NULL
               AND v_CompletionDate IS NOT NULL THEN

                /* Same day */
                IF v_RequestDate = v_CompletionDate THEN
                    RETURN 0;
                END IF;

                /* Determine direction */
                IF v_CompletionDate > v_RequestDate THEN

                    SET v_Current = DATE_ADD(v_RequestDate,INTERVAL 1 DAY);
                    SET v_EndDate = v_CompletionDate;
                    SET v_Sign = 1;

                ELSE

                    SET v_Current = DATE_ADD(v_CompletionDate,INTERVAL 1 DAY);
                    SET v_EndDate = v_RequestDate;
                    SET v_Sign = -1;

                END IF;

                SET v_Days = 0;

                WHILE v_Current <= v_EndDate DO

                    /* Weekend */
                    IF DAYOFWEEK(v_Current) NOT IN (1,7) THEN

                        /* Always count Completion Date */
                        IF v_Current = v_CompletionDate THEN

                            SET v_Days = v_Days + 1;

                        /* Otherwise exclude holidays */
                        ELSEIF NOT EXISTS
                        (
                            SELECT 1
                            FROM tblholiday h
                            WHERE h.IsActive = 1
                              AND h.HolidayDate = DATE_FORMAT(v_Current,'%m-%d')
                        ) THEN

                            SET v_Days = v_Days + 1;

                        END IF;

                    END IF;

                    SET v_Current = DATE_ADD(v_Current,INTERVAL 1 DAY);

                END WHILE;

                SET v_Return = v_Days * v_Sign;

            END IF;

        END IF;

    END IF;

    RETURN IFNULL(v_Return,0);

END */$$
DELIMITER ;

/* Function  structure for function  `funcGetDesc` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetDesc` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetDesc`( p_StatementType VARCHAR(30), p_SearchBy VARCHAR(255), p_SearchValue TEXT ) RETURNS longtext CHARSET utf8mb3
BEGIN
DECLARE v_ID INT;
DECLARE v_Name TEXT;
DECLARE v_Return LONGTEXT;
DECLARE p_out LONGTEXT;

DECLARE v_ServiceNo INT;
DECLARE v_FSRNo INT;
DECLARE v_TypeID INT;
DECLARE v_SelectionID INT;
DECLARE v_ClientID INT;
DECLARE v_TerminalID INT;
DECLARE v_IRIDNo INT;
DECLARE v_IRNo VARCHAR(255);
DECLARE v_JobType INT;
DECLARE v_ActionMade VARCHAR(45);
DECLARE v_Month VARCHAR(45);
DECLARE v_TWithInSLA INT;
DECLARE v_TOverAllRequest INT;
DECLARE v_StorageType INT;
DECLARE v_Title VARCHAR(45);
DECLARE v_Description VARCHAR(45);
DECLARE v_Temp VARCHAR(45);
DECLARE v_StatusID INT;

DECLARE v_DateFrom VARCHAR(45);
DECLARE v_DateTo VARCHAR(45);
DECLARE years INT;
DECLARE months INT;
DECLARE days INT;
DECLARE effective_end DATE;
DECLARE temp_date DATE;
			
	IF (p_StatementType = 'Search')
	THEN
		IF (p_SearchBy = 'Particular')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Name INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.ParticularID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'IR Detail')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.IRNo INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.IRIDNo = v_ID
			LIMIT 1;	
			
		ELSEIF (p_SearchBy = 'Terminal Detail')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.TerminalSN INTO v_Return 
			FROM 
			tblterminaldetail a 
			WHERE a.TerminalID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Terminal Type')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tblterminaltype a 
			WHERE a.TerminalTypeID = v_ID;
			
		ELSEIF (p_SearchBy = 'Terminal Model')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tblterminalmodel a 
			WHERE a.TerminalModelID = v_ID
			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'Terminal Brand')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tblterminalbrand a 
			WHERE a.TerminalBrandID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Terminal Status' || p_SearchBy = 'SIM Status' || p_SearchBy = 'Service Status')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tblterminalstatus a 
			WHERE a.TerminalStatusID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'SIM Detail')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.SIMSN INTO v_Return 
			FROM 
			tblsimdetail a 
			WHERE a.SIMID = v_ID
			LIMIT 1;	
			
		ELSEIF (p_SearchBy = 'SIM Carrier')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tbltype a 
			WHERE a.TypeID = v_ID AND a.Type = 1
			LIMIT 1;	
			
		ELSEIF (p_SearchBy = 'IR TID')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.TID INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.IRIDNo = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'IR MID')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.MID INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.IRIDNo = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Location')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tbllocation a 
			WHERE a.LocationID = v_ID
			LIMIT 1;
			
	    ELSEIF (p_SearchBy = 'Position')
		THEN
		
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tblposition a 
			WHERE a.PositionID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Department')
		THEN
		
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tbldepartment a 
			WHERE a.DepartmentID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Category')
		THEN
		
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tblcategory a 
			WHERE a.CategoryID = v_ID
			LIMIT 1;
			
		-- ROCKY -- : ADD CITY LOOKUP
		ELSEIF (p_SearchBy = 'City')
		THEN
		
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.City INTO v_Return 
			FROM 
			tblcity a 
			WHERE a.CityID = v_ID
			LIMIT 1;

			
		ELSEIF (p_SearchBy = 'Terminal Model Price')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Price INTO v_Return 
			FROM 
			tblterminalmodel a 
			WHERE a.TerminalTypeID = v_ID;

			

		ELSEIF (p_SearchBy = 'TerminalID Status')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT b.Description INTO v_Return 

			FROM 

			tblterminaldetail a 

			LEFT JOIN tblterminalstatus AS b ON a.TerminalStatus = b.TerminalStatusID

			WHERE a.TerminalID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'SIMID Status')

		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT b.Description INTO v_Return 

			FROM 

			tblsimdetail a 

			LEFT JOIN tblterminalstatus AS b ON a.SIMStatus = b.TerminalStatusID

			WHERE a.SIMID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'TerminalID Location')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT b.Description INTO v_Return 

			FROM 

			tblterminaldetail a 

			LEFT JOIN tbllocation AS b ON a.LocationID = b.LocationID

			WHERE a.TerminalID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'SIMID Location')

		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT b.Description INTO v_Return 

			FROM 

			tblsimdetail a 

			LEFT JOIN tbllocation AS b ON a.LocationID = b.LocationID

			WHERE a.SIMID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'TerminalID Type')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT b.Description INTO v_Return 

			FROM 

			tblterminaldetail a 

			LEFT JOIN tblterminaltype AS b ON a.TerminalTypeID = b.TerminalTypeID

			WHERE a.TerminalID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'TerminalID Model')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT b.Description INTO v_Return 

			FROM 

			tblterminaldetail a 

			LEFT JOIN tblterminalmodel AS b ON a.TerminalModelID = b.TerminalModelID

			WHERE a.TerminalID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'SIMID Carrier')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT b.Description INTO v_Return 

			FROM 

			tblsimdetail a 

			LEFT JOIN tbltype AS b ON a.CarrierID = b.TypeID AND b.Type = 1 #(Type = 1 for SIM Carrier)

			WHERE a.SIMID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'Service JobType Description')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.ServiceJobTypeDescription INTO v_Return 

			FROM 

			tblservicetype a 

			WHERE a.JobType = v_ID

			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Service Code')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.Code INTO v_Return 

			FROM 

			tblservicetype a 

			WHERE a.JobType = v_ID

			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'JobType Description')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.JobTypeDescription INTO v_Return 

			FROM 

			tblservicetype a 

			WHERE a.JobType = v_ID

			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Service Status Description')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.ServiceStatusDescription INTO v_Return 

			FROM 

			tblservicetype a 

			WHERE a.JobType = v_ID

			LIMIT 1;

		ELSEIF (p_SearchBy = 'Region')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.Region INTO v_Return 

			FROM 

			tblregion a 

			WHERE a.RegionID = v_ID

			LIMIT 1;

			

		ELSEIF (p_SearchBy = 'Region Detail')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.Province INTO v_Return 

			FROM 

			tblregiondetail a 

			WHERE a.RegionID = v_ID

			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'AppVersion')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.AppVersion INTO v_Return 

			FROM 

			tblterminalmodel a 

			WHERE a.TerminalModelID = v_ID

			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'AppCRC')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.AppCRC INTO v_Return 

			FROM 

			tblterminalmodel a 

			WHERE a.TerminalModelID = v_ID

			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Reason')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.Description INTO v_Return 

			FROM 

			tblreason a
			WHERE a.ReasonID = v_ID

			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Diagnostic Detail')
		THEN

			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_TypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_SelectionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			
			SELECT a.SelectedValue INTO v_Return 
			FROM 
			tbldiagnosticdetail a
			WHERE a.ServiceNo = v_ServiceNo AND a.FSRNo = v_FSRNo AND a.TypeID = v_TypeID AND a.SelectionID = v_SelectionID
			LIMIT 1;
			
			IF (v_Return = '-') THEN
				SET v_Return = '0';
			END IF;
			
		ELSEIF (p_SearchBy = 'Address')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Address INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.ParticularID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Field Engineer Email')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Email INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.ParticularID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Client Email')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Email INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.ParticularID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Recipient Email')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Email INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.ParticularID = v_ID
			LIMIT 1;
		
		ELSEIF (p_SearchBy = 'Mobile Terminal ID')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.TerminalID INTO v_Return 
			FROM 
			tblterminal a 
			WHERE a.TID = v_ID
			LIMIT 1;
				
		ELSEIF (p_SearchBy = 'Mobile Terminal Name')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.TerminalName INTO v_Return 
			FROM 
			tblterminal a 
			WHERE a.TID = v_ID
			LIMIT 1;
		
		ELSEIF (p_SearchBy = 'Terminal 1st Installation Date')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			
			SELECT a.FSRDate INTO v_Return 
			FROM tblfsrdetail a 
			LEFT JOIN tblservicingdetail b ON a.ServiceNo = b.ServiceNo
			WHERE
			a.ClientID = v_ClientID
			AND a.JobType = v_JobType
			AND a.IRIDNo = v_IRIDNo
			AND (b.TerminalID = v_TerminalID OR b.ReplaceTerminalID = v_TerminalID)
			AND a.ActionMade = 'SUCCESS'
			HAVING MIN(a.FSRNo);
				
		ELSEIF (p_SearchBy = 'Merchant 1st Installation Date')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SELECT a.FSRDate INTO v_Return 
			FROM tblfsrdetail a 
			WHERE
			a.ClientID = v_ClientID
			AND a.JobType = v_JobType
			AND a.IRIDNo = v_IRIDNo
			AND a.ActionMade = 'SUCCESS'
			HAVING MIN(a.FSRNo);
			
		ELSEIF (p_SearchBy = 'Type')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Description INTO v_Return 
			FROM 
			tbltype a 
			WHERE a.TypeID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Type-Remarks')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.Remarks INTO v_Return 
			FROM 
			tbltype a 
			WHERE a.TypeID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Billable')
		THEN
			SET v_ID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SET v_Return = IF(UPPER(v_ID) IN ('1', 'YES'), 'YES', 'NO');
			
		ELSEIF (p_SearchBy = 'Enabled/Disabled')
		THEN
			SET v_ID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SET v_Return = IF(UPPER(v_ID) IN ('1', 'YES'), 'ENABLED', 'DISABLED');
			
		ELSEIF (p_SearchBy = 'Yes/No')
		THEN
			SET v_ID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SET v_Return = IF(UPPER(v_ID) IN ('1', 'YES'), 'YES', 'NO');
			
		ELSEIF (p_SearchBy = 'AreaCode')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.AreaCode INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.ParticularID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Merchant Operational Period')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SELECT MAX(a.FSRDate) INTO v_Return
			FROM tblfsrdetail a 
			WHERE
			a.ClientID = v_ClientID
			AND a.JobType = v_JobType
			AND a.IRIDNo = v_IRIDNo
			AND a.ActionMade = 'SUCCESS';
					
		ELSEIF (p_SearchBy = 'Date Diff YMD')
		THEN
			SET v_DateFrom  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			-- Handle invalid or missing end_date
			IF v_DateTo IS NULL OR v_DateTo = '0000-00-00' OR v_DateTo = '-' THEN
				SET effective_end = CURDATE();
			ELSE
				SET effective_end = v_DateTo;
			END IF;

			-- If start_date is invalid, return '-'
			IF v_DateFrom IS NULL OR v_DateFrom = '0000-00-00' OR v_DateFrom = '-' THEN
				SET v_Return = '-';
			ELSE
				-- Calculate the difference
				SET years = TIMESTAMPDIFF(YEAR, v_DateFrom, effective_end);
				SET months = TIMESTAMPDIFF(MONTH, v_DateFrom, effective_end) - (years * 12);

				-- Correct way to add multiple intervals
				SET temp_date = DATE_ADD(v_DateFrom, INTERVAL years YEAR);
				SET temp_date = DATE_ADD(temp_date, INTERVAL months MONTH);
				SET days = DATEDIFF(effective_end, temp_date);

				SET v_Return = CONCAT(years, ' Years, ', months, ' Months, ', days, ' Days');
			END IF;
			
		ELSEIF (p_SearchBy = 'Daily Service Status')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ActionMade  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_Description  = COALESCE(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)), '');
			
			IF (v_ID = 9) THEN
				SET v_Return = 'HOLD';
			ELSEIF (v_ID = 10) THEN
				SET v_Return = 'CANCELLED';
			ELSEIF (v_ID = 2) THEN
				SET v_Return = 'PENDING';
			ELSEIF (v_ID = 8) THEN				
				IF (v_ActionMade = 'NEGATIVE' || v_ActionMade IS NULL || v_ActionMade = '') THEN
					IF (v_Description = 'PENDING' || v_Description = 'PROCESSING') THEN
						SET v_Return = 'PENDING';
					ELSE
						SET v_Return = 'NEGATIVE';
					END IF;
					
				ELSE
					SET v_Return = 'PENDING';
				END IF;	
			ELSE
				IF (v_ActionMade = 'SUCCESS') THEN
					SET v_Return = 'RESOLVED';
				ELSEIF (v_ActionMade = 'NEGATIVE') THEN
					SET v_Return = 'NEGATIVE';
				ELSE
					SET v_Return = 'PENDING';
				END IF;
			END IF;
			
		ELSEIF (p_SearchBy = 'Terminal FSR Date')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			
			SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT IFNULL_GET_DATE(MAX(fsr.FSRDate)) INTO v_Return
			FROM tblterminaldetail td 
			LEFT JOIN tblfsrdetail fsr ON td.TerminalID = fsr.TerminalID AND fsr.ActionMade = 'SUCCESS'
			LEFT JOIN tblservicingdetail svc ON td.TerminalID = svc.TerminalID AND svc.JobTypeStatusDescription = 'COMPLETED'
			WHERE
			td.ClientID = v_ClientID
			AND svc.TerminalID = v_TerminalID OR svc.ReplaceTerminalID = v_TerminalID
		        AND svc.JobType IN (1, 7)		        
			ORDER BY fsr.ServiceNo DESC
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Get SLA')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
				funcGetID("Search", "SLA", CONCAT(a.RegionType, "|", a.RegionID)) INTO @SLA
			FROM
				tblparticular a
			WHERE
			a.ParticularID = v_ID;
			
			SET v_Return = COALESCE(@SLA,0);
			
		ELSEIF (p_SearchBy = 'Get NetworkDays')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.ServiceStatus INTO @ServiceStatus FROM tblservicingdetail a WHERE a.ServiceNo = v_ID;
			
			IF (@ServiceStatus = 9 OR @ServiceStatus = 10)
			THEN
				SET @NetworkDays = 0;
			ELSE
				SELECT
				IFNULL_NUMERIC(b.FSRNo),
				a.ReqInstallationDate,
				a.ServiceReqDate,
				b.FSRDate,
				a.JobTypeStatusDescription,
				CASE
					WHEN a.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') THEN
						funcComputeTAT(a.ServiceReqDate, CURRENT_DATE())
					WHEN  (a.ServiceReqDate > b.FSRDate) THEN
						funcComputeTAT(b.FSRDate, a.ServiceReqDate)
					ELSE						
						funcComputeTAT(a.ServiceReqDate, b.FSRDate)
						
				END INTO @FSRNo, @RequestDate, @ServiceReqDate, @ServicedDate, @JobTypeStatusDescription, @NetworkDays
				FROM
					tblservicingdetail a
				LEFT JOIN tblfsrdetail b ON a.ServiceNo = b.ServiceNo
				WHERE
				a.ServiceNo = v_ID;
			END IF;
			
			SET v_Return = COALESCE(@NetworkDays,0);
			
		ELSEIF (p_SearchBy = 'Get DaysOverDue')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT a.ServiceStatus INTO @ServiceStatus FROM tblservicingdetail a WHERE a.ServiceNo = v_ServiceNo;
			
			IF (@ServiceStatus = 9 OR @ServiceStatus = 10)
			THEN
				SET v_Return = 0;
			ELSE
				# get SLA
				SELECT
					funcGetID("Search", "SLA", CONCAT(a.RegionType, "|", a.RegionID)) INTO @SLA
				FROM
				tblparticular a
				LEFT JOIN tblirdetail b ON a.ParticularID = b.MerchantID
				WHERE
					b.IRActive > 0
					AND a.isActive > 0
					AND b.IRIDNo = v_ID
				LIMIT 1;			
				SET @SLA = COALESCE(@SLA, 0);
				
				SELECT
					IFNULL_NUMERIC(b.FSRNo),
					a.ReqInstallationDate,  # RequestDate
					a.ServiceReqDate,	# ScheduleDate
					b.FSRDate,		# ServicedDate
					a.JobTypeStatusDescription,
					CASE
						WHEN a.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') THEN
							funcComputeTAT(a.ServiceReqDate, CURRENT_DATE())
						WHEN  (a.ServiceReqDate > b.FSRDate) THEN
							funcComputeTAT(b.FSRDate, a.ServiceReqDate)
						ELSE						
							funcComputeTAT(a.ServiceReqDate, b.FSRDate)
					END INTO @FSRNo, @RequestDate, @ScheduleDate, @ServicedDate, @JobTypeStatusDescription, @DaysOverDue
				FROM
					tblservicingdetail a
				LEFT JOIN tblfsrdetail b ON a.ServiceNo = b.ServiceNo
				WHERE
				a.ServiceNo = v_ServiceNo;
				
				IF (@ServicedDate = '0000-00-00') THEN
					SET v_Return = 0;
				ELSE
					IF @ServicedDate BETWEEN @RequestDate AND @ScheduleDate THEN
						SET v_Return = 0;
					ELSE
						IF (@ScheduleDate > @ServicedDate) THEN
							SET v_Return = (@DaysOverDue + 1) - @SLA;
						ELSE
							SET v_Return = @DaysOverDue;
						END IF;
					END IF;
				END IF;
			end if;
			
			SET v_Return = COALESCE(v_Return, 0);
			
		ELSEIF (p_SearchBy = 'Get TAT Status')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS SIGNED);
			
			IF (v_ID > 0) THEN
				SET v_Return = 'BEYOND TAT';
			ELSE
				SET v_Return = 'WITHIN TAT';
			END IF;
			
		ELSEIF (p_SearchBy = 'FSR ActionMade')
		THEN
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS SIGNED);
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS SIGNED);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS SIGNED);
			SET v_IRNo  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SELECT
			MAX(a.ActionMade) INTO v_Return
			FROM
			tblfsrdetail a
			WHERE 
			a.JobType = v_JobType
			AND (a.ServiceNo = v_ServiceNo OR v_ServiceNo = 0)
			AND a.IRIDNo = v_IRIDNo
			AND a.IRNo = v_IRNo;
			
		ELSEIF (p_SearchBy = 'FSR ServiceDate')
		THEN
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS SIGNED);
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS SIGNED);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS SIGNED);
			SET v_IRNo  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SELECT
			MAX(a.FSRDate) INTO v_Return
			FROM
			tblfsrdetail a
			WHERE 
			a.JobType = v_JobType
			AND (a.ServiceNo = v_ServiceNo OR v_ServiceNo = 0)
			AND a.IRIDNo = v_IRIDNo
			AND a.IRNo = v_IRNo;
			
		ELSEIF (p_SearchBy = 'Compute Grand Total SLA')
		THEN
			SET v_Month  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			CASE v_Month
			    WHEN 'January' THEN
				SELECT SUM(January) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(January) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';
				
			    WHEN 'February' THEN
				SELECT SUM(February) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(February) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'March' THEN
				SELECT SUM(March) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(March) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'April' THEN
				SELECT SUM(April) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(April) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'May' THEN
				SELECT SUM(May) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(May) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'June' THEN
				SELECT SUM(June) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(June) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'July' THEN
				SELECT SUM(July) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(July) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'August' THEN
				SELECT SUM(August) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(August) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'September' THEN
				SELECT SUM(September) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(September) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'October' THEN
				SELECT SUM(October) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(October) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'November' THEN
				SELECT SUM(November) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(November) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';

			    WHEN 'December' THEN
				SELECT SUM(December) INTO @TWithInSLA FROM tblreportdatastorage WHERE StorageType = 4 AND Description = 'TOTAL';
				SELECT SUM(December) INTO @TOverAllRequest FROM tblreportdatastorage WHERE StorageType = 3 AND Description = 'TOTAL';
			    ELSE
				SET v_Return = 0;
			END CASE;
			
			SET v_Return = LEAST(COALESCE(FLOOR(ROUND((COALESCE(@TWithInSLA, 0) / NULLIF(COALESCE(@TOverAllRequest, 0), 0)) * 100,2)),0),100);
			
		ELSEIF (p_SearchBy = 'Compute Report Data Storage Total')
		THEN
			SET v_StorageType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS SIGNED);	
			SET v_Title  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_Month  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			CASE v_Month
			    WHEN 'January' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.January) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.January INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.January) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'February' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.February) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.February INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.February) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'March' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.March) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.March INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.March) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'April' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.April) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.April INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.April) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'May' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.May) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.May INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.May) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'June' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.June) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.June INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.June) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'July' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.July) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.July INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.July) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'August' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.August) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.August INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.August) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'September' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.September) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.September INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.September) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'October' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.October) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.October INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.October) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'November' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.November) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.November INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.November) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    WHEN 'December' THEN
				IF (v_Title = 'GRAND TOTAL') THEN
				    IF (v_StorageType = 3) THEN
					SELECT SUM(a.December) INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				    ELSE
					SELECT a.December INTO v_Return
					FROM tblreportdatastorage a
					WHERE a.StorageType = v_StorageType AND a.Title = v_Title;
				    END IF;
				ELSE
				    SELECT SUM(a.December) INTO v_Return
				    FROM tblreportdatastorage a
				    WHERE a.StorageType = v_StorageType AND a.Title = v_Title AND REPLACE(a.Description, '_', '') IN ('PENDING', 'RESOLVED', 'NEGATIVE');
				END IF;

			    ELSE
				SET v_Return = 0;
			END CASE;

			SET v_Return = FORMAT(COALESCE(v_Return, 0.00), 0);
		
		ELSEIF (p_SearchBy = 'Terminal Operational Status')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SELECT 
				CASE
					WHEN MAX(a.FSRDate) IS NULL OR MAX(a.FSRDate) = '1980-09-11' OR MAX(a.FSRDate) = '0000-00-00' OR MAX(a.FSRDate) = '-' THEN '-'
					WHEN DATEDIFF(CURDATE(), MAX(a.FSRDate)) < 365 THEN 'NEW'
					WHEN DATEDIFF(CURDATE(), MAX(a.FSRDate)) BETWEEN 365 AND 1095 THEN 'MID-LIFE'
					ELSE 'OLD'
				END INTO v_Return			
			FROM tblfsrdetail a 
			WHERE
			a.ClientID = v_ClientID
			AND a.JobType = v_JobType
			AND a.IRIDNo = v_IRIDNo
			AND a.ActionMade = 'SUCCESS';
			
		ELSEIF (p_SearchBy = 'Inventory Aging' || p_SearchBy = 'Operational Aging')
		THEN
			SET v_Temp  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			IF (v_Temp IS NULL OR v_Temp = '1980-09-11' OR v_Temp = '0' OR v_Temp = '-' OR v_Temp = '' OR v_Temp = '0000-00-00')
			THEN
				SET v_Return = 'Received date not set';
			ELSE
				-- Use COALESCE to handle NULL or invalid date
				SET v_Return = CAST(
				    DATEDIFF(
					CURDATE(), 
					COALESCE(NULLIF(v_Temp, '0000-00-00'), CURDATE()) -- fallback to CURDATE() if invalid
				    ) AS CHAR
				);
			END IF;
			
		ELSEIF (p_SearchBy = 'Terminal Storage Duration')
		THEN
			SET v_DateFrom  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			IF (v_DateFrom IS NULL OR v_DateFrom = '1980-09-11' OR v_DateFrom = '0' OR v_DateFrom = '-') THEN
				SET v_Return = 'Installed date not set';
			ELSEIF (v_DateTo IS NULL OR v_DateTo = '1980-09-11' OR v_DateTo = '0' OR v_DateTo = '-') THEN			
				SET v_Return = 'Received date not set';
			ELSE
				 -- Safely calculate the difference using COALESCE to avoid invalid dates
				SET v_Return = CAST(
				    DATEDIFF(
					COALESCE(NULLIF(v_DateFrom, '0000-00-00'), CURDATE()), 
					COALESCE(NULLIF(v_DateTo, '0000-00-00'), CURDATE())
				    ) AS CHAR
				);
			END IF;
			
		ELSEIF (p_SearchBy = 'Terminal 1st Installation')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT a.FSRDate INTO v_Return 
			FROM tblfsrdetail a 
			LEFT JOIN tblservicingdetail b ON a.ServiceNo = b.ServiceNo
			WHERE
			a.ClientID = v_ClientID
			AND a.JobType IN (1, 7)
			AND (b.TerminalID = v_TerminalID OR b.ReplaceTerminalID = v_TerminalID)
			AND a.ActionMade = 'SUCCESS'
			HAVING MIN(a.FSRNo);
			
		ELSEIF (p_SearchBy = 'Additional Remarks 2')
		THEN
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS SIGNED);
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS SIGNED);
			
			SELECT
			 CASE
			  WHEN MAX(a.ServiceStatus) IN (9, 10) THEN a.Remarks
			  ELSE b.AnyComments
			 END INTO v_Return 
			FROM
			tblservicingdetail a
			LEFT JOIN tblfsrdetail b ON a.ServiceNo = b.ServiceNo
			WHERE 
			a.JobType = v_JobType
			AND (a.ServiceNo = v_ServiceNo);
			
		ELSEIF (p_SearchBy = 'Description By Service Status')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT a.ServiceStatusDescription INTO v_Return 

			FROM 
			tblservicetype a 
			WHERE a.ServiceStatus = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Get SLA 2' || p_SearchBy = 'Get NetworkDays 2' || p_SearchBy = 'Get DaysOverDue 2')
		THEN
			IF (p_SearchBy = 'Get SLA 2') THEN
				SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
				SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
				
				SET @ServiceNo = v_ServiceNo;
			ELSEIF (p_SearchBy = 'Get NetworkDays 2') THEN
				SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
				
				SET @ServiceNo = v_ID;		
			ELSEIF (p_SearchBy = 'Get DaysOverDue 2') THEN
				SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
				SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
				
				SET @ServiceNo = v_ServiceNo;
			END IF;
			
			# get ServiceStatus, Code
			SELECT 
				a.ServiceStatus,
				b.Code,
				b.ServiceStatusDescription INTO @ServiceStatus, @ServiceCode, @ServiceStatusDescription
			FROM
				tblservicingdetail a
				LEFT JOIN tblservicetype b ON a.ServiceStatus = b.ServiceStatus
			WHERE
				a.ServiceNo = @ServiceNo;
				
			# 9  - HOLD SERVICE,   Code = 1001
			# 10 - CANCEL SERVICE, Code = 1002
			IF (@ServiceStatus = 9) THEN
				SET v_Return = 'HOLD';
			ELSEIF (@ServiceStatus = 10) THEN
				SET v_Return = 'CANCELLED';
			ELSE
				# Get SLA
				IF (p_SearchBy = 'Get SLA 2' || p_SearchBy = 'Get DaysOverDue 2') THEN
										
					SELECT
						funcGetID("Search", "SLA", CONCAT(a.RegionType, "|", a.RegionID)) INTO @SLA
					FROM
					tblparticular a
					LEFT JOIN tblirdetail b ON a.ParticularID = b.MerchantID
					WHERE
						b.IRActive > 0
						AND a.isActive > 0
						AND b.IRIDNo = v_ID
					LIMIT 1;
					
					SET v_Return = COALESCE(@SLA, 0);
				END IF;
				
				IF (p_SearchBy = 'Get NetworkDays 2') THEN
				
					SELECT
						IFNULL_NUMERIC(b.FSRNo),
						a.ReqInstallationDate,
						a.ServiceReqDate,
						b.FSRDate,
						a.JobTypeStatusDescription,
						CASE
							WHEN a.JobTypeStatusDescription IN ('PENDING', 'PROCESSING') THEN
								funcComputeTAT(a.ServiceReqDate, CURRENT_DATE())
							WHEN  (a.ServiceReqDate > b.FSRDate) THEN
								funcComputeTAT(b.FSRDate, a.ServiceReqDate)
							ELSE						
								funcComputeTAT(a.ServiceReqDate, b.FSRDate)
								
						END INTO @FSRNo, @RequestDate, @ServiceReqDate, @ServicedDate, @JobTypeStatusDescription, @NetworkDays
					FROM
						tblservicingdetail a
						LEFT JOIN tblfsrdetail b ON a.ServiceNo = b.ServiceNo
					WHERE
						a.ServiceNo = @ServiceNo;
					
					SET v_Return = COALESCE(@NetworkDays,'0');
					
				ELSEIF (p_SearchBy = 'Get DaysOverDue 2') THEN
					
					SELECT
					    IFNULL_NUMERIC(b.FSRNo),
					    a.ReqInstallationDate,
					    a.ServiceReqDate,
					    b.FSRDate,
					    a.JobTypeStatusDescription,

					    -- DueDate (NOW holiday-aware)
					    @DueDate := funcAddWorkingDays(a.ReqInstallationDate, @SLA) AS DueDate,

					    -- DaysOverDue
					    CASE
						    WHEN b.FSRDate IS NULL 
							 AND CURRENT_DATE() <= @DueDate THEN 0

						    WHEN b.FSRDate IS NULL THEN
							funcWorkingDays(@DueDate, CURRENT_DATE())

						    WHEN b.FSRDate <= @DueDate THEN 0

						    ELSE
							funcWorkingDays(@DueDate, b.FSRDate)
						END AS DaysOverDue,

					    -- NetworkDays
					    funcWorkingDays(
						DATE_ADD(a.ReqInstallationDate, INTERVAL 1 DAY),
						a.ServiceReqDate
					    ) AS NetworkDays,

					    -- SLA Status
					    CASE
						WHEN b.FSRDate IS NULL AND CURRENT_DATE() <= @DueDate THEN 'WITHIN TAT'
						WHEN b.FSRDate IS NULL THEN 'BEYOND TAT'
						WHEN b.FSRDate <= @DueDate THEN 'WITHIN TAT'
						ELSE 'BEYOND TAT'
					    END AS SLAStatus

					INTO 
					    @FSRNo, 
					    @RequestDate, 
					    @ScheduleDate, 
					    @ServicedDate, 
					    @JobTypeStatusDescription, 
					    @DueDate,
					    @DaysOverDue,
					    @NetworkDays,
					    @SLAStatus

					FROM
					    tblservicingdetail a
					    LEFT JOIN tblfsrdetail b ON a.ServiceNo = b.ServiceNo
					WHERE
					    a.ServiceNo = @ServiceNo;
					    
					SET v_Return = COALESCE(@DaysOverDue,'0');
    
				END IF;
			END IF;
			
		ELSEIF (p_SearchBy = 'Get TAT Status 2')
		THEN
			SET v_Temp  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			# 9  - HOLD SERVICE,   Code = 1001
			# 10 - CANCEL SERVICE, Code = 1002
			IF (v_Temp REGEXP '^-?[0-9]+$') THEN
			    IF (CAST(v_Temp AS SIGNED) > 0) THEN
				SET v_Return = 'BEYOND TAT';
			    ELSE
				SET v_Return = 'WITHIN TAT';
			    END IF;

			ELSEIF (v_Temp = 'HOLD' OR v_Temp = 'CANCELLED') THEN
			    SET v_Return = v_Temp;
			ELSE
			    SET v_Return = 'INVALID';
			END IF;
			
		ELSEIF (p_SearchBy = 'FSR Mode')
		THEN
			SET v_Temp  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			IF (v_Temp = 'AUTO') THEN
				SET v_Return = 'DIGITAL FSR';
			ELSEIF (v_Temp = 'MANUAL') THEN
				SET v_Return = 'MANUAL FSR';
			ELSE
				SET v_Return = 'UNDEFINED';
			END IF;
			
		ELSEIF (p_SearchBy = 'Merchant Region')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT b.Region INTO v_Return 
			FROM 
			tblparticular a
			LEFT JOIN tblregion b ON a.RegionType = b.RegionID 
			WHERE a.ParticularID = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'CleanUp MerchantName')
		THEN
			SET v_Name  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SET v_Return = TRIM(
			    REPLACE(
				REPLACE(
				    REPLACE(
					REPLACE(
					    REPLACE(
						REPLACE(
						    REPLACE(
							REPLACE(
							    REPLACE(
								REPLACE(v_Name,
								    '(CREDIT)', ''),
								'( CREDIT )', ''),
							    '(DEBIT)', ''),
							'( DEBIT )', ''),
						    '(QRPAY)', ''),
						'( QRPAY )', ''),
					    '(QRPH)', ''),
					'( QRPH )', ''),
				    '(BANCNET)', ''),
				'( BANCNET )', '')
			);
			
		ELSEIF (p_SearchBy = 'Original Installation Date')
		THEN
			SET @IRNo  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			-- Step 1: Derive combined values into variables (one row only)
			SELECT 
			    -- Prioritize SUCCESS over NEGATIVE
			    CASE
				WHEN SUM(a.ActionMade = 'SUCCESS') > 0 THEN 'SUCCESS'
				WHEN SUM(a.ActionMade = 'NEGATIVE') > 0 THEN 'NEGATIVE'
				ELSE NULL
			    END AS FinalAction,
			    
			    -- Latest FSRDate for SUCCESS if any,
			    -- otherwise latest for NEGATIVE
			    MAX(a.FSRDate) AS FinalFSRDate
			INTO 
			    @ActionMade,
			    @FSRDate
			FROM tblfsrdetail a
			WHERE a.IRNo = @IRNo AND a.JobType = 1;

			SELECT 
			    CASE
				WHEN @ActionMade IS NULL THEN 'NO INSTALLATION YET'
				WHEN @ActionMade = 'SUCCESS' AND @FSRDate IS NOT NULL THEN DATE_FORMAT(@FSRDate, '%Y-%m-%d')
				WHEN @ActionMade = 'SUCCESS' AND @FSRDate IS NULL THEN 'NO INSTALLATION YET'
				WHEN @ActionMade = 'NEGATIVE' THEN 'FAILED INSTALLATION'
				ELSE 'NO INSTALLATION YET'
			    END INTO v_Return;
			    
		ELSEIF (p_SearchBy = 'Return Ticket Status')
		THEN
			SET @Value  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			IF (@Value = 'SUCCESS') THEN
				SET @Value = 'RESOLVED';
			END IF;
			
			SET v_Return = @Value;
			
		ELSEIF (p_SearchBy = 'Return Service Status')
		THEN
			SET @Value  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			IF (@Value = 'PENDING') THEN
				SET @Value = 'ALLOCATED';
			ELSEIF (@Value = 'PROCESSING') THEN
				SET @Value = 'DISPATCH';
			END IF;
			
			SET v_Return = @Value;
			
		ELSEIF (p_SearchBy = 'Service Ticket Status')
		THEN
		    SET @TicketStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS SIGNED INTEGER);
		    SET @ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS SIGNED INTEGER);
		    SET @ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));

		    IF (@ServiceStatus = 2) THEN
			SET @Value = 'OPEN';
		    ELSEIF (@TicketStatus = 0 AND UPPER(@ActionMade) IN ('SUCCESS', 'NEGATIVE')) THEN
			SET @Value = 'FOR VERIFICATION';
		    ELSEIF (@TicketStatus = 1) THEN
			SET @Value = 'CLOSED';
		    ELSE
			SET @Value = 'OPEN';
		    END IF;

		    SET v_Return = @Value;
			
		ELSEIF (p_SearchBy = 'ZoneName')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.ZoneName INTO v_Return 
			FROM 
			tblzoning a 
			WHERE a.ZoneID = v_ID
			LIMIT 1;
        
		 ELSEIF (p_SearchBy = "ExpenseDesc")
		 THEN 
		    SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		    
		    SELECT a.Description INTO v_Return 
				FROM 
				tblexpenses a 
				WHERE a.ExpensesID = v_ID
				LIMIT 1;
				
		ELSEIF (p_SearchBy = "Service Remarks") 
		THEN  

		    SET v_ID = CAST(
			TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) 
			AS UNSIGNED INTEGER
		    ); 

		    SELECT  
			CONCAT(
			    'Problem Report: ',
			    COALESCE(NULLIF(TRIM(a.ProblemReported), ''), '-'),
			    '\n\n',
			    'RM Instruction: ',
			    COALESCE(NULLIF(TRIM(a.RMInstruction), ''), '-')
			)
		    INTO v_Return 
		    FROM tblservicingdetail a 
		    WHERE a.ServiceNo = v_ID 
		    LIMIT 1;
				
		ELSEIF (p_SearchBy = "Service Owner") 
		THEN 
			SET @Owner  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER); 
			SET @ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 3)) AS UNSIGNED INTEGER); 			
			
			SET @ActivityID = 0;
			IF (@Owner = 'Request') THEN
				SET @ActivityID = 1;
			ELSEIF (@Owner = 'Job Orders') THEN
				SET @ActivityID = 2;
			ELSEIF (@Owner = 'Inventory') THEN
				SET @ActivityID = 3;
			ELSEIF (@Owner = 'Terminal Prep') THEN
				SET @ActivityID = 4;
			ELSEIF (@Owner = 'Dispatcher') THEN
				SET @ActivityID = 5;
			ELSEIF (@Owner = 'Field Engineer') THEN
				SET @ActivityID = 6;
			ELSEIF (@Owner = 'Closer') THEN
				SET @ActivityID = 7;
			ELSEIF (@Owner = 'Completed') THEN
				SET @ActivityID = 8;
			ELSEIF (@Owner = 'Negative') THEN
				SET @ActivityID = 9;
			ELSEIF (@Owner = 'Within') THEN
				SET @ActivityID = 10;	
			ELSEIF (@Owner = 'Beyond') THEN
				SET @ActivityID = 11;	
			ELSEIF (@Owner = 'Profiling') THEN
				SET @ActivityID = 12;
			END IF;
			
			set @ParticularID = 0;
			SET @Name = '';
			#SELECT a.ParticularID INTO @ParticularID FROM tblservicingactivitydetail a WHERE a.ActivityID = @ActivityID AND a.ServiceNo = @ServiceNo ORDER BY a.ServiceNo DESC LIMIT 1;
			SELECT a.ParticularName INTO @Name FROM tblservicingactivitydetail a WHERE a.ActivityID = @ActivityID AND a.ServiceNo = @ServiceNo ORDER BY a.ServiceNo DESC LIMIT 1;
			#IF (@ParticularID > 0) THEN
			IF (LENGTH(@Name) > 0) THEN
				#SELECT a.Name into @Name FROM tblparticular a WHERE a.ParticularID = @ParticularID LIMIT 1;	
				SET v_Return = @Name;			
			ELSE
				SELECT a.Name INTO @Name FROM tblparticular a WHERE a.ParticularID = @ID LIMIT 1;
				IF (LENGTH(@Name) > 0) THen
					SET v_Return = @Name;
				else
					SELECT a.ProcessedBy INTO @Name FROM tblservicingdetail a WHERE a.ServiceNo = @ServiceNo order by a.ServiceNo LIMIT 1;
					SET v_Return = @Name;
				end if;
			END IF;
			
		END IF;
	END IF;
	
   IF (ISNULL(v_Return))
   THEN
	SET v_Return = "-";
   END IF;
   
   SET p_out = v_Return;
  
   RETURN p_out;
END */$$
DELIMITER ;

/* Function  structure for function  `funcGetGeneralActionTaken` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetGeneralActionTaken` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetGeneralActionTaken`(p_JobType INT, p_IRIDNo INT, p_IRNo VARCHAR(255)) RETURNS longtext CHARSET utf8mb3
BEGIN
    DECLARE v_Return LONGTEXT DEFAULT '';
    
    -- Concatenate results manually without GROUP_CONCAT()
    # 1 = INSTALLATION, 3 = REPROGRAMMING, 4 = PULLOUT, 6 = SERVICING, 7 = REPLACEMENT
    if (p_JobType = 1 OR p_JobType = 3 OR p_JobType = 4) THEN
		SELECT GROUP_CONCAT(
		CONCAT(
		    'Attempt #', AttemptNumber, '\n',
		    'Date: ', DATE_FORMAT(FSRDate, '%b-%d-%Y'), '\n',
		    'AT: ', TIME_FORMAT(TimeArrived, '%h:%i %p'), '\n',
		    'ST: ', TIME_FORMAT(TimeStart, '%h:%i %p'), '\n',
		    'ET: ', TIME_FORMAT(TimeEnd, '%h:%i %p'), '\n',
		    'Assigned Engineer: ', `Name`, '\n',
		    'Work Log: ', ActionTaken, '\n',
		    'TID: ', TID, '\n',
		    'MID: ', `MID`, '\n',
		    'Remarks: ', pPullOut, '\n',
		    'Received By: ', MerchantRepresentative, '\n\n'
		) SEPARATOR ''  -- Use ### as a separator to avoid truncation
	    ) INTO v_Return
	    FROM (
		SELECT 
		    @attempt := @attempt + 1 AS AttemptNumber,
		    a.FSRDate, a.TimeArrived, a.TimeStart, a.TimeEnd,
		    a.FEID, a.ActionTaken, IF(LENGTH(a.Remarks) > 0, a.Remarks, a.AnyComments) as pPullOut, a.MerchantRepresentative,
		    b.TID, b.MID, c.Name
		FROM (SELECT @attempt := 0) AS init, tblfsrdetail a
		LEFT JOIN tblirdetail b ON a.IRIDNo = b.IRIDNo
		LEFT JOIN tblparticular c ON a.FEID = c.ParticularID
		WHERE a.IRIDNo = p_IRIDNo 
		AND a.IRNo = p_IRNo 
		AND (a.JobType = p_JobType OR a.ReasonID = 60)
		ORDER BY a.FSRNo ASC 
		LIMIT 5
	    ) AS xTable;
    ELSE
	    	SELECT GROUP_CONCAT(
		CONCAT(
		    'Attempt #', AttemptNumber, '\n',
		    #'Job Type: ', JobTypeDescription, '\n',
		    #'Request ID: ', IRNo, '\n',
		    'Date: ', DATE_FORMAT(FSRDate, '%b-%d-%Y'), '\n',
		    'AT: ', TIME_FORMAT(TimeArrived, '%h:%i %p'), '\n',
		    'ST: ', TIME_FORMAT(TimeStart, '%h:%i %p'), '\n',
		    'ET: ', TIME_FORMAT(TimeEnd, '%h:%i %p'), '\n',
		    'Assigned Engineer: ', `Name`, '\n',
		    'TID: ', TID, '\n',
		    'MID: ', `MID`, '\n',
		    'Problem Reported: ', ProblemReported, '\n',
		    'Problem Found: ', ActualProblemReported, '\n',
		    'Action Taken: ', ActionTaken, '\n',
		    'Received By: ', MerchantRepresentative, '\n\n'
		) SEPARATOR ''  -- Use ### as a separator to avoid truncation
	    ) INTO v_Return
	    FROM (
		SELECT 
		    @attempt := @attempt + 1 AS AttemptNumber,
		    #a.JobTypeDescription, a.IRNo, 
		    a.FSRDate, a.TimeArrived, a.TimeStart, a.TimeEnd,
		    a.FEID, a.ProblemReported, a.ActualProblemReported, a.ActionTaken, a.MerchantRepresentative,
		    b.TID, b.MID, c.Name
		FROM (SELECT @attempt := 0) AS init, tblfsrdetail a
		LEFT JOIN tblirdetail b ON a.IRIDNo = b.IRIDNo
		LEFT JOIN tblparticular c ON a.FEID = c.ParticularID
		WHERE a.IRIDNo = p_IRIDNo AND a.IRNo = p_IRNo
		ORDER BY a.FSRNo ASC 
		LIMIT 5
	    ) AS xTable;

    END IF;
    
    

    -- Return the full result
    RETURN v_Return;
END */$$
DELIMITER ;

/* Function  structure for function  `funcGetID` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetID` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetID`( p_StatementType VARCHAR(30), p_SearchBy VARCHAR(255), p_SearchValue TEXT ) RETURNS int
BEGIN

DECLARE v_ID INT;
DECLARE v_Name TEXT;
DECLARE v_Return INT;

DECLARE v_JobType INT;
DECLARE v_RegionType INT;
DECLARE v_RegionID INT;

DECLARE v_ServiceNo INT;
DECLARE v_IRIDNo INT;
DECLARE v_JobTypeStatusDescription VARCHAR(100); # eg. PENDING/PROCESSING/COMPLETED

DECLARE v_TID TEXT;
DECLARE v_MID TEXT;

DECLARE p_out INT;

	IF (p_StatementType = 'Search')
	THEN
		IF (p_SearchBy = 'Particular')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.ParticularID INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.Name = v_Name
			LIMIT 1;
			
		elseif (p_SearchBy = 'IR Detail')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.IRIDNo INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.IRNo = v_Name
			LIMIT 1;	
			
		ELSEIF (p_SearchBy = 'Terminal Detail')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TerminalID INTO v_Return 
			FROM 
			tblterminaldetail a 
			WHERE a.TerminalSN = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Terminal Type')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TerminalTypeID INTO v_Return 
			FROM 
			tblterminaltype a 
			WHERE a.Description = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Terminal Model')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TerminalModelID INTO v_Return 
			FROM 
			tblterminalmodel a 
			WHERE a.Description = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Terminal Brand')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TerminalBrandID INTO v_Return 
			FROM 
			tblterminalbrand a 
			WHERE a.Description = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Terminal Status')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TerminalStatusID INTO v_Return 
			FROM 
			tblterminalstatus a 
			WHERE a.Description = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'SIM Detail')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.SIMID INTO v_Return 
			FROM 
			tblsimdetail a 
			WHERE a.SIMSN = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'SIM Status')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TerminalStatusID INTO v_Return 
			FROM 
			tblterminalstatus a 
			WHERE a.Description = v_Name
			LIMIT 1;	
			
		ELSEIF (p_SearchBy = 'SIM Carrier')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TypeID INTO v_Return 
			FROM 
			tbltype a 
			WHERE a.Description = v_Name AND a.Type = 1
			LIMIT 1;	
			
		ELSEIF (p_SearchBy = 'Location')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.LocationID INTO v_Return 
			FROM 
			tbllocation a 
			WHERE a.Description = v_Name
			LIMIT 1;
			
			
		ELSEIF (p_SearchBy = 'FSRNo')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT a.FSRNo INTO v_Return 
			FROM 
			tblfsrdetail a 
			WHERE a.ServiceNo = v_ID
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Reason')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.ReasonID INTO v_Return 
			FROM 
			tblreason a 
			WHERE a.Description = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Region Detail')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.RegionID INTO v_Return 
			FROM 
			tblregiondetail a 
			WHERE a.Province = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Region')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.RegionID INTO v_Return 
			FROM 
			tblregion a 
			WHERE a.Region = v_Name
			LIMIT 1;
		
		ELSEIF (p_SearchBy = 'Particular By TID')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.MerchantID INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.TID = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'SLA by Region')
		THEN
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT COALESCE(a.SLA,0) INTO v_Return 
			FROM 
			tblsladetail a 
			WHERE 
			a.RegionType = v_RegionType
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'SLA')
		THEN
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT COALESCE(a.SLA,0) INTO v_Return 
			FROM 
			tblsladetail a 
			WHERE 
			a.RegionType = v_RegionType
			AND a.RegionID = v_RegionID
			LIMIT 1;
			
			IF (ISNULL(v_Return) || v_Return <= 0)
			THEN
				SET v_Return = 0;
				
				SELECT a.SLA INTO v_Return 
				FROM 
				tblsladetail a 
				WHERE 
				a.RegionType = v_RegionType
				AND a.RegionID = 0
				LIMIT 1;
			END IF;
			
		ELSEIF (p_SearchBy = 'Service DispatchID')
		THEN
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT
				CASE
				WHEN a.JobTypeStatusDescription = 'PENDING' THEN a.FEID
				WHEN a.JobTypeStatusDescription = 'PROCESSING' THEN a.DispatchID
				ELSE a.DispatchID
				END INTO v_Return
			FROM
			tblservicingdetail a
			WHERE
			a.ServiceNo = v_ServiceNo
			AND a.IRIDNo = v_IRIDNo;
			
		ELSEIF (p_SearchBy = 'Address')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.ParticularID INTO v_Return 
			FROM 
			tblparticular a 
			WHERE a.Address = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'IRIDNo By TID')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.IRIDNo INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.TID = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'IRIDNo By TerminalSN')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.IRIDNo INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.TerminalSN = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'IRIDNo By SIMSN')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.IRIDNo INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.SIMSN = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Type')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.TypeID INTO v_Return 
			FROM 
			tbltype a 
			WHERE a.Description = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'IRIDNo By TID And MID')
		THEN
			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT a.IRIDNo INTO v_Return 
			FROM 
			tblirdetail a 
			WHERE a.TID = v_TID AND a.MID = v_MID AND a.IRActive > 0
			ORDER BY a.IRIDNo DESC
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Service Job Type Description')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
						
			SELECT a.JobType INTO v_Return 
			FROM 
			tblservicetype a 
			WHERE a.ServiceJobTypeDescription = v_Name
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Terminal State')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT a.StateID INTO v_Return 
			FROM 
			tblterminalstate a 
			WHERE a.Description = v_Name
			LIMIT 1;
															
		END IF;
	END IF;
	
   IF (ISNULL(v_Return))
   THEN
	SET v_Return = 0;
   END IF;
   SET p_out = v_Return;
  
   RETURN p_out;
END */$$
DELIMITER ;

/* Function  structure for function  `funcGetJSON` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetJSON` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetJSON`( p_StatementType VARCHAR(30), p_SearchBy VARCHAR(255), p_SearchValue TEXT ) RETURNS longtext CHARSET utf8mb3
BEGIN
DECLARE v_ID INT;
DECLARE v_Name VARCHAR(255);
DECLARE v_JobType INT;
DECLARE v_ServiceNo INT;
DECLARE v_IRIDNo INT;
DECLARE v_IRNo VARCHAR(255);
DECLARE v_Return LONGTEXT;
DECLARE p_out LONGTEXT;
			
	IF (p_StatementType = 'Search')
	THEN
		IF (p_SearchBy = 'Stock Detail Info')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			JSON_OBJECT(
			'StockID', IFNULL_NUMERIC(a.StockID),
			'ItemID', IFNULL_NUMERIC(a.ItemID),
			'ClientID', IFNULL_NUMERIC(a.ClientID),
			'ClientName', IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.ClientID)),
			'LocationID', IFNULL_NUMERIC(a.LocationID),
			'Location', IFNULL_STRING_ONLY(funcGetDesc("Search", "Location", a.LocationID)),
			'TerminalTypeID', IFNULL_NUMERIC(a.TerminalTypeID),
			'TerminalType', IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Type", a.TerminalTypeID)),
			'TerminalModelID', IFNULL_NUMERIC(a.TerminalModelID),
			'TerminalModel', IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Model", a.TerminalModelID)),
			'TerminalBrandID', IFNULL_NUMERIC(a.TerminalBrandID),
			'TerminalBrand', IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Brand", a.TerminalBrandID)),
			'StockStatus', IFNULL_NUMERIC(a.StockStatus),	
			'StockStatusDescription', IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Status", a.StockStatus)),	
			'SerialNo', IFNULL_STRING_ONLY(a.SerialNo),
			'DeliveryDate', IFNULL_STRING_ONLY(a.DeliveryDate),
			'ReceiveDate', IFNULL_STRING_ONLY(a.ReceiveDate),
			'ReleaseDate', IFNULL_STRING_ONLY(a.ReleaseDate),
			'Allocation', IFNULL_STRING_ONLY(a.Allocation),
			'AssetType', IFNULL_STRING_ONLY(a.AssetType),
			'PONo', IFNULL_STRING_ONLY(a.PONo),
			'InvNo', IFNULL_STRING_ONLY(a.InvNo),
			'PartNo', IFNULL_STRING_ONLY(a.PartNo),
			'Remarks', IFNULL_STRING_ONLY(a.Remarks)
			) 
			INTO v_Return
			FROM
			tblstockdetail a
			WHERE (a.ItemID = v_ID);
			
		ELSEIF (p_SearchBy = 'Profile Config Info')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			profile_config_info INTO v_Return
			FROM
			tblparticular a
			WHERE
			a.ParticularID = v_ID;
			
		ELSEIF (p_SearchBy = 'Service Attempt')
		THEN
		    SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		    SET v_IRIDNo  = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		    SET v_IRNo    = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		    SET @rn := 0;

		    SELECT
		    JSON_OBJECT(
			'FSRDate1', COALESCE(MAX(CASE WHEN rn = 1 THEN FSRDate END), '-'),
			'isBillable1', COALESCE(MAX(CASE WHEN rn = 1 THEN isBillable END), '-'),
			'Reason1', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 1 THEN Reason END), '-')),
			'StatusReason1', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 1 THEN StatusReason END), '-')),
			'Status', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 1 THEN Reason END), '-')),
			'Remarks1', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 1 THEN Remarks END), '-')),
			'ActionMade1', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 1 THEN ActionMade END), '-')),

			'FSRDate2', COALESCE(MAX(CASE WHEN rn = 2 THEN FSRDate END), '-'),
			'isBillable2', COALESCE(MAX(CASE WHEN rn = 2 THEN isBillable END), '-'),
			'Reason2', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 2 THEN Reason END), '-')),
			'StatusReason2', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 2 THEN StatusReason END), '-')),
			'Remarks2', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 2 THEN Remarks END), '-')),
			'ActionMade2', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 2 THEN ActionMade END), '-')),

			'FSRDate3', COALESCE(MAX(CASE WHEN rn = 3 THEN FSRDate END), '-'),
			'isBillable3', COALESCE(MAX(CASE WHEN rn = 3 THEN isBillable END), '-'),
			'Reason3', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 3 THEN Reason END), '-')),
			'StatusReason3', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 3 THEN StatusReason END), '-')),
			'Remarks3', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 3 THEN Remarks END), '-')),
			'ActionMade3', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 3 THEN ActionMade END), '-')),

			'FSRDate4', COALESCE(MAX(CASE WHEN rn = 4 THEN FSRDate END), '-'),
			'isBillable4', COALESCE(MAX(CASE WHEN rn = 4 THEN isBillable END), '-'),
			'Reason4', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 4 THEN Reason END), '-')),
			'StatusReason4', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 4 THEN StatusReason END), '-')),
			'Remarks4', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 4 THEN Remarks END), '-')),
			'ActionMade4', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 4 THEN ActionMade END), '-')),

			'FSRDate5', COALESCE(MAX(CASE WHEN rn = 5 THEN FSRDate END), '-'),
			'isBillable5', COALESCE(MAX(CASE WHEN rn = 5 THEN isBillable END), '-'),
			'Reason5', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 5 THEN Reason END), '-')),
			'StatusReason5', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 5 THEN StatusReason END), '-')),
			'Remarks5', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 5 THEN Remarks END), '-')),
			'ActionMade5', IFNULL_STRING_ONLY2(COALESCE(MAX(CASE WHEN rn = 5 THEN ActionMade END), '-'))
		    ) INTO v_Return
		    FROM (
			SELECT
			    (@rn := @rn + 1) AS rn,
			    IFNULL_FORMAT_DATE(COALESCE(r.FSRDate, '0000-00-00')) AS FSRDate,
			    funcGetDesc('Search','Yes/No', r.isBillable) AS isBillable,
			    funcGetDesc('Search','Reason', r.ReasonID) AS Reason,
			    funcGetDesc('Search','Type', r.StatusReasonID) AS StatusReason,
			    r.Remarks,
			    r.ActionMade
			FROM (
			    SELECT a.FSRNo, a.FSRDate, a.isBillable, a.ReasonID, a.StatusReasonID, a.Remarks, a.ActionMade
			    FROM tblfsrdetail a
			    WHERE a.IRIDNo = v_IRIDNo
			      AND a.IRNo   = v_IRNo
			      AND a.JobType = v_JobType
			    ORDER BY a.FSRNo DESC
			    LIMIT 5
			) AS r
			ORDER BY r.FSRNo ASC
		    ) sub;
		END IF;

	END IF;
	
   IF (ISNULL(v_Return))
   THEN
	SET v_Return = "-";
   END IF;
   
   SET p_out = v_Return;
  
   RETURN p_out;
END */$$
DELIMITER ;

/* Function  structure for function  `funcGetNetworkDays` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetNetworkDays` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetNetworkDays`(
    p_StatementType VARCHAR(30), 
    p_SearchBy VARCHAR(255), 
    p_SearchValue TEXT
) RETURNS int
    DETERMINISTIC
BEGIN

    DECLARE v_Return INT DEFAULT 0;

    DECLARE v_ServiceNo INT DEFAULT 0;
    DECLARE v_RequestDate DATE;
    DECLARE v_CompletionDate DATE;

    DECLARE v_Current DATE;
    DECLARE v_Days INT DEFAULT 0;

    IF p_StatementType = 'Search' THEN    
    
        IF p_SearchBy = 'Network Days' THEN

            SET v_ServiceNo = CAST(
                TRIM(SPLIT_STRING(p_SearchValue, '|', 1))
                AS UNSIGNED
            );

            SELECT 
                NULLIF(a.ServiceDate, '0000-00-00'),
                CASE
                    WHEN b.FSRDate IS NULL
                         OR b.FSRDate = '0000-00-00'
                    THEN CURDATE()
                    ELSE b.FSRDate
                END
            INTO 
                v_RequestDate,
                v_CompletionDate
            FROM tblservicingdetail a
            LEFT JOIN tblfsrdetail b
                ON a.ServiceNo = b.ServiceNo
            WHERE a.ServiceNo = v_ServiceNo
            LIMIT 1;

            IF v_RequestDate IS NOT NULL
		   AND v_CompletionDate IS NOT NULL THEN

		    -- Start AFTER Request Date
		    SET v_Current = DATE_ADD(v_RequestDate, INTERVAL 1 DAY);

		    SET v_Days = 0;

		    WHILE v_Current <= v_CompletionDate DO

			IF DAYOFWEEK(v_Current) NOT IN (1,7)
			THEN

			    -- Always count the completion date
			    IF v_Current = v_CompletionDate THEN
				SET v_Days = v_Days + 1;

			    ELSEIF NOT EXISTS (
				SELECT 1
				FROM tblholiday h
				WHERE h.IsActive = 1
				  AND h.HolidayDate = DATE_FORMAT(v_Current,'%m-%d')
			    ) THEN
				SET v_Days = v_Days + 1;
			    END IF;

			END IF;

			SET v_Current = DATE_ADD(v_Current, INTERVAL 1 DAY);

		    END WHILE;

		    /*
		      Business Rule:
		      If completion happened after request date
		      but all intervening days are weekends/holidays,
		      count as 1 Network Day.
		    */
		    IF v_CompletionDate > v_RequestDate
		       AND v_Days = 0 THEN

			SET v_Days = 1;

		    END IF;

		    SET v_Return = v_Days;

		END IF;

        END IF;

    END IF;

    RETURN IFNULL(v_Return, 0);

END */$$
DELIMITER ;

/* Function  structure for function  `funcGetSLA` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetSLA` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetSLA`( p_StatementType VARCHAR(30), p_SearchBy VARCHAR(255), p_SearchValue TEXT ) RETURNS int
BEGIN

DECLARE v_ID INT;
DECLARE v_Name TEXT;
DECLARE v_Return INT;

DECLARE p_out INT;

	IF (p_StatementType = 'Search')
	THEN	
		IF (p_SearchBy = 'SLA-Region')
		THEN
			SET @ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED);

			    SELECT
				a.JobType, b.RegionType, b.ZoneID 
			    INTO @JobType, @RegionType, @ZoneID     
			    FROM tblservicingdetail a
			    LEFT JOIN tblparticular b 
				ON a.MerchantID = b.ParticularID 			
			    WHERE a.ServiceNo = @ServiceNo;

			    SET v_Return = 0;
			    
			    IF (@ZoneID > 0)
			    THEN
				SELECT
				COALESCE(SLA,0) 
				    INTO v_Return 
				    FROM tblzoning
				    WHERE ZoneID = @ZoneID 				      
				    LIMIT 1;
			    END IF;			    
			    
		ELSEIF (p_SearchBy = 'SLA-Region-Province')
		THEN
			SET @ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED);

			    SELECT
				a.JobType, b.RegionType, b.RegionID 
			    INTO @JobType, @RegionType, @RegionID     
			    FROM tblservicingdetail a
			    LEFT JOIN tblparticular b 
				ON a.MerchantID = b.ParticularID 			
			    WHERE a.ServiceNo = @ServiceNo;

			    SELECT
				COALESCE(SLA,0) 
			    INTO v_Return 
			    FROM tblsladetail
			    WHERE RegionType = @RegionType 
			      AND JobType = @JobType
			      AND RegionID = @RegionID
			    LIMIT 1;
															
		END IF;
	END IF;
	
   IF (ISNULL(v_Return))
   THEN
	SET v_Return = 0;
   END IF;
   SET p_out = v_Return;
  
   RETURN p_out;
END */$$
DELIMITER ;

/* Function  structure for function  `funcGetTATStatus` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetTATStatus` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetTATStatus`(
    p_StatementType VARCHAR(30),
    p_SearchBy VARCHAR(255),
    p_SearchValue TEXT
) RETURNS varchar(20) CHARSET utf8mb3
    DETERMINISTIC
BEGIN

    DECLARE v_ServiceNo INT DEFAULT 0;
    DECLARE v_ScheduleDate DATE;
    DECLARE v_ServicedDate DATE;
    DECLARE v_DaysOverDue INT DEFAULT 0;
    DECLARE v_SLA INT DEFAULT 0;
    DECLARE v_Status VARCHAR(20) DEFAULT 'WITHIN TAT';

    IF p_StatementType = 'Search' THEN

        IF p_SearchBy = 'TAT Status' THEN

	    SET v_ServiceNo = CAST(
                TRIM(SPLIT_STRING(p_SearchValue, '|', 1))
                AS UNSIGNED
            );
            
            SELECT
                NULLIF(a.ServiceReqDate, '0000-00-00'),
                NULLIF(b.FSRDate, '0000-00-00')
            INTO
                v_ScheduleDate,
                v_ServicedDate
            FROM tblservicingdetail a
            LEFT JOIN tblfsrdetail b
                   ON a.ServiceNo = b.ServiceNo
            WHERE a.ServiceNo = v_ServiceNo
            LIMIT 1;

            IF v_ServicedDate IS NOT NULL AND v_ScheduleDate IS NOT NULL THEN
		IF v_ServicedDate > v_ScheduleDate THEN
                    SET v_Status = 'BEYOND TAT';
                ELSE
                    SET v_Status = 'WITHIN TAT';
                END IF;
            ELSE
		     SET v_DaysOverDue = IFNULL(
			funcGetDaysOverDue(
			    'Search',
			    'Days OverDue',
			    p_SearchValue
			),
			0
		    );
		    
		     SET v_SLA = IFNULL(
			funcGetSLA(
			    'Search',
			    'SLA-Region',
			    p_SearchValue
			),
			0
		    );
            
		    IF v_SLA = 0 THEN
			SET v_Status = 'NO SLA SET'; 
		    ELSEIF v_DaysOverDue > v_SLA THEN
			SET v_Status = 'BEYOND TAT';
		    ELSE
			SET v_Status = 'WITHIN TAT';
		    END IF;
            END IF;

        END IF;

    END IF;

    RETURN v_Status;

END */$$
DELIMITER ;

/* Function  structure for function  `funcGetValidData` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetValidData` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetValidData`( p_StatementType VARCHAR(30), p_SearchBy VARCHAR(255), p_SearchValue TEXT ) RETURNS text CHARSET utf8mb3
BEGIN







DECLARE v_ID INT;



DECLARE v_Counter INTEGER;



DECLARE v_TLoop INTEGER;



DECLARE v_Temp TEXT;



DECLARE v_Replace TEXT;



DECLARE v_Data TEXT;







DECLARE v_Return TEXT;







DECLARE p_out TEXT;







IF (p_StatementType = 'Search')



THEN



	IF (p_SearchBy = 'Data')



	THEN



		SET v_Counter = 0;



		SET v_TLoop = LENGTH(p_SearchValue);



		SET p_SearchValue = UCASE(p_SearchValue);



		SET v_Return = p_SearchValue;



		



		WHILE (v_TLoop >= v_Counter) DO



			



			SET v_Temp = SUBSTRING(p_SearchValue, v_Counter, 1);



			



			IF (LENGTH(v_Temp) > 0)



			THEN



				IF (v_Temp = ",")



				THEN



					SET v_Replace = "";



				ELSEIF (v_Temp = "(")



				THEN



					SET v_Replace = "";



				ELSEIF (v_Temp = ")")



				THEN	



					SET v_Replace = "";				



				ELSEIF (v_Temp = "[")



				THEN



					SET v_Replace = "";				



				ELSEIF (v_Temp = "]")



				THEN



					SET v_Replace = "";				



				ELSEIF (v_Temp = "{")



				THEN



					SET v_Replace = "";				



				ELSEIF (v_Temp = "}")



				THEN



					SET v_Replace = "";				



				ELSEIF (v_Temp = "'")



				THEN



					SET v_Replace = "";				



				ELSEIF (v_Temp = "ÃƒÆ’Ã¢â‚¬Ëœ")



				THEN



					SET v_Replace = "N";



				ELSE



					SET v_Temp = "";



				END IF;



				



				SET v_Return = REPLACE(v_Return, v_Temp, v_Replace);



				



			END IF;



			SET v_Counter = v_Counter + 1;



		END WHILE;



															



	END IF;



END IF;



	



IF (ISNULL(v_Return))



THEN



	SET v_Return = "-";



END IF;







SET p_out = v_Return;







RETURN p_out;



END */$$
DELIMITER ;

/* Function  structure for function  `funcGetZoneID` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetZoneID` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetZoneID`(
    pSearch TEXT
) RETURNS int
    DETERMINISTIC
BEGIN
    DECLARE vZoneID INT DEFAULT 0;
    DECLARE vAddress TEXT;
    DECLARE vRegion TEXT;
    DECLARE vDone INT DEFAULT 0;
    DECLARE vAlias VARCHAR(255);
    DECLARE vOfficial VARCHAR(255);

    DECLARE cAlias CURSOR FOR
        SELECT AliasName, OfficialName
        FROM tblzoningalias
        WHERE IsActive=1
        ORDER BY Priority DESC;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET vDone=1;

    SET vAddress = funcNormalizeLocation(SUBSTRING_INDEX(pSearch,'###',1));
    SET vRegion  = funcNormalizeLocation(
                      SUBSTRING_INDEX(SUBSTRING_INDEX(pSearch,'###',2),'###',-1));

    OPEN cAlias;
    alias_loop: LOOP
        FETCH cAlias INTO vAlias,vOfficial;
        IF vDone=1 THEN
            LEAVE alias_loop;
        END IF;

        IF LOCATE(CONCAT(' ',vAlias,' '),CONCAT(' ',vAddress,' '))>0 THEN
            SET vAddress=REPLACE(vAddress,vAlias,vOfficial);
        END IF;

        IF LOCATE(CONCAT(' ',vAlias,' '),CONCAT(' ',vRegion,' '))>0 THEN
            SET vRegion=REPLACE(vRegion,vAlias,vOfficial);
        END IF;
    END LOOP;
    CLOSE cAlias;

    SELECT ZoneID
      INTO vZoneID
    FROM
    (
        SELECT
            z.ZoneID,
            (
                CASE WHEN LOCATE(CONCAT(' ',funcNormalizeLocation(z.CityMunicipal),' '),CONCAT(' ',vRegion,' '))>0 THEN 5000 ELSE 0 END +
                CASE WHEN LOCATE(CONCAT(' ',funcNormalizeLocation(z.CityMunicipal),' '),CONCAT(' ',vAddress,' '))>0 THEN 4000 ELSE 0 END +
                CASE WHEN LOCATE(CONCAT(' ',funcNormalizeLocation(z.Area),' '),CONCAT(' ',vAddress,' '))>0 THEN 600 ELSE 0 END +
                CASE WHEN LOCATE(CONCAT(' ',funcNormalizeLocation(z.ZoneName),' '),CONCAT(' ',vAddress,' '))>0 THEN 300 ELSE 0 END +
                CASE WHEN REGEXP_LIKE(CONCAT(' ',vAddress,' '),
                     CONCAT(' ',funcNormalizeLocation(z.CityMunicipal),' (AVE|AVENUE|RD|ROAD|ST|STREET|HWY|HIGHWAY|BLVD|BOULEVARD)'))
                     THEN -5000 ELSE 0 END
            ) Score,
            LOCATE(CONCAT(' ',funcNormalizeLocation(z.CityMunicipal),' '),CONCAT(' ',vAddress,' ')) Pos,
            CHAR_LENGTH(z.CityMunicipal) LenCity,
            CHAR_LENGTH(z.ZoneName) LenZone
        FROM tblzoning z
    ) X
    WHERE Score>0
    ORDER BY Score DESC,
             CASE WHEN Pos>0 THEN Pos ELSE 999999 END DESC,
             LenCity DESC,
             LenZone DESC,
             ZoneID ASC
    LIMIT 1;

    RETURN IFNULL(vZoneID,0);
END */$$
DELIMITER ;

/* Function  structure for function  `funcGetZoneIDv2` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetZoneIDv2` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetZoneIDv2`(
    pSearch TEXT
) RETURNS int
    DETERMINISTIC
BEGIN

    DECLARE vZoneID INT DEFAULT 0;

    DECLARE vAddress TEXT;
    DECLARE vRegion TEXT;

    DECLARE vMatchedArea VARCHAR(150);

    /*--------------------------------------------
      Parse Search
    ---------------------------------------------*/

    SET vAddress = funcNormalizeLocation(
        SUBSTRING_INDEX(pSearch,'###',1)
    );

    SET vRegion = funcNormalizeLocation(
        SUBSTRING_INDEX(
            SUBSTRING_INDEX(pSearch,'###',2),
            '###',
            -1
        )
    );

    /*--------------------------------------------
      STEP 1
      Detect Area
    ---------------------------------------------*/

    SET vMatchedArea = NULL;

    SELECT
        Area
    INTO
        vMatchedArea
    FROM
        tblzoning
    WHERE
           funcContainsWord(vRegion, Area) = 1
        OR funcContainsWord(vAddress, Area) = 1
    GROUP BY
        Area
    ORDER BY
        LENGTH(Area) DESC
    LIMIT 1;

    /*--------------------------------------------
	  STEP 2
	  Find Best Zone
	---------------------------------------------*/

	SELECT
    ZoneID
INTO
    vZoneID
FROM
    tblzoning
WHERE
       funcContainsWord(vAddress, CityMunicipal)=1
    OR funcContainsWord(vRegion, CityMunicipal)=1
ORDER BY 
	ZoneID DESC
LIMIT 1;

    RETURN COALESCE(vZoneID,0);

END */$$
DELIMITER ;

/* Function  structure for function  `funcGetZoneIDv3` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetZoneIDv3` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetZoneIDv3`(
    pSearch TEXT
) RETURNS int
    DETERMINISTIC
BEGIN

    DECLARE vZoneID INT DEFAULT 0;

    DECLARE vAddress TEXT;
    DECLARE vRegion TEXT;

    DECLARE vMatchedArea VARCHAR(150) DEFAULT NULL;

    /*--------------------------------------------
      Parse Search
    ---------------------------------------------*/

    SET vAddress = funcNormalizeLocation(
        SUBSTRING_INDEX(pSearch,'###',1)
    );

    SET vRegion = funcNormalizeLocation(
        SUBSTRING_INDEX(
            SUBSTRING_INDEX(pSearch,'###',2),
            '###',
            -1
        )
    );

    /*--------------------------------------------
      STEP 1
      Detect Area
    ---------------------------------------------*/

    SELECT
        Area
    INTO
        vMatchedArea
    FROM
        tblzoning
    WHERE
           funcContainsWord(vRegion, Area)=1
        OR funcContainsWord(vAddress, Area)=1
    GROUP BY
        Area
    ORDER BY
        CHAR_LENGTH(Area) DESC
    LIMIT 1;

    /*--------------------------------------------
      STEP 2
      Find Best Zone
    ---------------------------------------------*/

    SELECT
        z.ZoneID
    INTO
        vZoneID
    FROM
        tblzoning z
    WHERE
        (
            vMatchedArea IS NULL
            OR z.Area = vMatchedArea
        )
        AND
        (
               funcContainsWord(vRegion , z.CityMunicipal)=1
            OR funcContainsWord(vAddress, z.CityMunicipal)=1
            OR funcContainsWord(vAddress, z.ZoneName)=1
        )

    ORDER BY

        (
            CASE
                WHEN funcContainsWord(vRegion,z.CityMunicipal)=1
                THEN 3000
                ELSE 0
            END

            +

            CASE
                WHEN funcContainsWord(vAddress,z.CityMunicipal)=1
                THEN 2000
                ELSE 0
            END

            +

            CASE
                WHEN funcContainsWord(vAddress,z.ZoneName)=1
                THEN 100
                ELSE 0
            END
        ) DESC,

        /* Prefer longer city names */
        CHAR_LENGTH(z.CityMunicipal) DESC,

        /* Prefer longer zone names */
        CHAR_LENGTH(z.ZoneName) DESC,

        /* Stable ordering */
        z.ZoneID ASC

    LIMIT 1;

    RETURN COALESCE(vZoneID,0);

END */$$
DELIMITER ;

/* Function  structure for function  `funcGetZoneIDv4` */

/*!50003 DROP FUNCTION IF EXISTS `funcGetZoneIDv4` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcGetZoneIDv4`(
    pSearch TEXT
) RETURNS int
    DETERMINISTIC
BEGIN

    DECLARE vZoneID INT DEFAULT 0;

    DECLARE vAddress TEXT;
    DECLARE vRegion TEXT;

    DECLARE vMatchedArea VARCHAR(150) DEFAULT NULL;

    /*--------------------------------------------
      Parse Search
    ---------------------------------------------*/

    SET vAddress = funcNormalizeLocation(
        SUBSTRING_INDEX(pSearch,'###',1)
    );

    SET vRegion = funcNormalizeLocation(
        SUBSTRING_INDEX(
            SUBSTRING_INDEX(pSearch,'###',2),
            '###',
            -1
        )
    );

    /*--------------------------------------------
      STEP 1
      Detect Area
    ---------------------------------------------*/

    SELECT
        Area
    INTO
        vMatchedArea
    FROM
        tblzoning
    WHERE
           funcContainsWord(vRegion, Area)=1
        OR funcContainsWord(vAddress, Area)=1
    GROUP BY
        Area
    ORDER BY
        CHAR_LENGTH(Area) DESC
    LIMIT 1;

    /*--------------------------------------------
      STEP 2
      Find Best Zone
    ---------------------------------------------*/

    SELECT
        ZoneID
    INTO
        vZoneID
    FROM
        tblzoning
    WHERE
        (
            vMatchedArea IS NULL
            OR Area = vMatchedArea
        )
        AND
        (
               funcContainsWord(vRegion, CityMunicipal)=1
            OR funcContainsWord(vAddress, CityMunicipal)=1
            OR funcContainsWord(vAddress, ZoneName)=1
        )

    ORDER BY

        CASE
            WHEN funcContainsWord(vRegion, CityMunicipal)=1 THEN 3
            WHEN funcContainsWord(vAddress, CityMunicipal)=1 THEN 2
            WHEN funcContainsWord(vAddress, ZoneName)=1 THEN 1
            ELSE 0
        END DESC,

        CHAR_LENGTH(CityMunicipal) DESC,
        CHAR_LENGTH(ZoneName) DESC,
        ZoneID ASC

    LIMIT 1;

    RETURN COALESCE(vZoneID,0);

END */$$
DELIMITER ;

