/* Function  structure for function  `funcHolidayDays` */

/*!50003 DROP FUNCTION IF EXISTS `funcHolidayDays` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcHolidayDays`(
    p_start DATE,
    p_end DATE
) RETURNS int
    DETERMINISTIC
BEGIN
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_date DATE;

    IF p_start IS NULL OR p_end IS NULL THEN
        RETURN 0;
    END IF;

    IF p_start > p_end THEN
        SET v_date = p_end;
        SET p_end = p_start;
        SET p_start = v_date;
    END IF;

    SET v_date = p_start;

    WHILE v_date < p_end DO

        IF WEEKDAY(v_date) NOT IN (5,6)
           AND EXISTS (
                SELECT 1
                FROM tblholiday h
                WHERE h.isActive = 1
                  AND DATE_FORMAT(v_date, '%m-%d') = h.HolidayDate
           )
        THEN
            SET v_count = v_count + 1;
        END IF;

        SET v_date = DATE_ADD(v_date, INTERVAL 1 DAY);

    END WHILE;

    RETURN v_count;
END */$$
DELIMITER ;

