/* Function  structure for function  `funcNormalizeLocation` */

/*!50003 DROP FUNCTION IF EXISTS `funcNormalizeLocation` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcNormalizeLocation`(
    pValue TEXT
) RETURNS text CHARSET utf8mb3
    READS SQL DATA
BEGIN

    DECLARE vText TEXT DEFAULT '';

    DECLARE vAliasName VARCHAR(150);
    DECLARE vOfficialName VARCHAR(150);

    DECLARE vDone INT DEFAULT 0;

    DECLARE vWord VARCHAR(200);
    DECLARE vPrevWord VARCHAR(200) DEFAULT '';
    DECLARE vResult TEXT DEFAULT '';

    DECLARE vPos INT DEFAULT 1;
    DECLARE vNext INT;

    DECLARE curAlias CURSOR FOR
        SELECT
            UPPER(TRIM(AliasName)),
            UPPER(TRIM(OfficialName))
        FROM tblzoningalias
        WHERE IsActive = 1
        ORDER BY
            Priority DESC,
            CHAR_LENGTH(AliasName) DESC;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET vDone = 1;

    /*--------------------------------------------------
      Initial Normalize
    --------------------------------------------------*/

    SET vText = UPPER(IFNULL(TRIM(pValue), ''));

    /*--------------------------------------------------
      Replace punctuation with space
    --------------------------------------------------*/

    SET vText = REGEXP_REPLACE(
                    vText,
                    '[[:punct:]]',
                    ' '
                );

    /*--------------------------------------------------
      Compress spaces
    --------------------------------------------------*/

    SET vText = REGEXP_REPLACE(
                    vText,
                    '[[:space:]]+',
                    ' '
                );

    SET vText = CONCAT(' ', TRIM(vText), ' ');

    /*--------------------------------------------------
      Apply Aliases
    --------------------------------------------------*/

    OPEN curAlias;

    alias_loop:
    LOOP

        FETCH curAlias
        INTO
            vAliasName,
            vOfficialName;

        IF vDone = 1 THEN
            LEAVE alias_loop;
        END IF;

        SET vText =
            REPLACE(
                vText,
                CONCAT(' ', vAliasName, ' '),
                CONCAT(' ', vOfficialName, ' ')
            );

    END LOOP;

    CLOSE curAlias;

    /*--------------------------------------------------
      Compress spaces again
    --------------------------------------------------*/

    SET vText = REGEXP_REPLACE(
                    vText,
                    '[[:space:]]+',
                    ' '
                );

    /*--------------------------------------------------
      Remove duplicate consecutive words

      Example:

      RODRIGUEZ RODRIGUEZ
      -> RODRIGUEZ

      BAGUIO BAGUIO
      -> BAGUIO
    --------------------------------------------------*/

    SET vText = CONCAT(TRIM(vText), ' ');

    SET vPrevWord = '';
    SET vResult = '';
    SET vPos = 1;

    word_loop:
    LOOP

        SET vNext = LOCATE(' ', vText, vPos);

        IF vNext = 0 THEN
            LEAVE word_loop;
        END IF;

        SET vWord =
            SUBSTRING(
                vText,
                vPos,
                vNext - vPos
            );

        IF vWord <> '' THEN

            IF vWord <> vPrevWord THEN

                SET vResult =
                    CONCAT(
                        vResult,
                        vWord,
                        ' '
                    );

                SET vPrevWord = vWord;

            END IF;

        END IF;

        SET vPos = vNext + 1;

        IF vPos > LENGTH(vText) THEN
            LEAVE word_loop;
        END IF;

    END LOOP;

    SET vText = TRIM(vResult);

    /*--------------------------------------------------
      Final Compress
    --------------------------------------------------*/

    SET vText = REGEXP_REPLACE(
                    vText,
                    '[[:space:]]+',
                    ' '
                );

    RETURN TRIM(vText);

END */$$
DELIMITER ;

/* Function  structure for function  `funcWeekendDays` */

/*!50003 DROP FUNCTION IF EXISTS `funcWeekendDays` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcWeekendDays`(
    p_start DATE,
    p_end DATE
) RETURNS int
    DETERMINISTIC
BEGIN
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_date DATE;

    IF p_start IS NULL OR p_end IS NULL THEN
        RETURN 0;
    END IF;

    IF p_start > p_end THEN
        SET v_date = p_end;
        SET p_end = p_start;
        SET p_start = v_date;
    END IF;

    SET v_date = p_start;

    WHILE v_date < p_end DO

        IF WEEKDAY(v_date) IN (5,6) THEN
            SET v_count = v_count + 1;
        END IF;

        SET v_date = DATE_ADD(v_date, INTERVAL 1 DAY);

    END WHILE;

    RETURN v_count;
END */$$
DELIMITER ;

/* Function  structure for function  `funcWorkingDays` */

/*!50003 DROP FUNCTION IF EXISTS `funcWorkingDays` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `funcWorkingDays`(
    p_start DATE,
    p_end DATE
) RETURNS int
    DETERMINISTIC
BEGIN
    DECLARE v_count INT DEFAULT 0;
    DECLARE v_date DATE;

    -- handle NULLs
    IF p_start IS NULL OR p_end IS NULL THEN
        RETURN 0;
    END IF;

    -- ensure start <= end
    IF p_start > p_end THEN
        SET v_date = p_end;
        SET p_end = p_start;
        SET p_start = v_date;
    END IF;

    SET v_date = p_start;

    WHILE v_date < p_end DO

        IF WEEKDAY(v_date) NOT IN (5,6) -- not Sat/Sun
           AND NOT EXISTS (
                SELECT 1
                FROM tblholiday h
                WHERE h.isActive = 1
                  AND DATE_FORMAT(v_date, '%m-%d') = h.HolidayDate
           )
        THEN
            SET v_count = v_count + 1;
        END IF;

        SET v_date = DATE_ADD(v_date, INTERVAL 1 DAY);

    END WHILE;

    RETURN v_count;
END */$$
DELIMITER ;

