    RETURN
        IF(
            pValue IS NULL
            OR pValue = ''
            OR pValue = '-'
            OR pValue = '0'
            OR LEFT(pValue, 10) = '0000-00-00',
            '00-00-0000',
            DATE_FORMAT(LEFT(pValue, 10), '%m-%d-%Y')
