/* Function  structure for function  `IFNULL_STRING` */

/*!50003 DROP FUNCTION IF EXISTS `IFNULL_STRING` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `IFNULL_STRING`( pValue TEXT ) RETURNS longtext CHARSET utf8mb3
BEGIN

SET pValue = UPPER(pValue);
SET pValue = REPLACE(pValue, 'Ã‘', 'N');
SET @input := pValue;
#SET @pattern := '[^a-zA-Z0-9 \-:_,]';
SET @pattern := '[^a-zA-Z0-9 .\\-:_,]/';
SET @cleaned_string := '';
SET @i := 1;
WHILE @i <= LENGTH(@input) 
DO
SET @char := SUBSTRING(@input, @i, 1);
IF @char REGEXP @pattern THEN
SET @cleaned_string := CONCAT(@cleaned_string, '');
ELSE
SET @cleaned_string := CONCAT(@cleaned_string, @char);
END IF;
SET @i := @i + 1;
END WHILE;

   SET pValue = @cleaned_string;
   if (LENGTH(pValue) > 0) 
   THEN
	SET pValue = @cleaned_string;
   ELSE
        SET pValue = '-';
   END IF;
   
   RETURN pValue;

END */$$
DELIMITER ;

/* Function  structure for function  `IFNULL_STRING_NORMAL` */

/*!50003 DROP FUNCTION IF EXISTS `IFNULL_STRING_NORMAL` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `IFNULL_STRING_NORMAL`( pValue TEXT ) RETURNS varchar(1000) CHARSET utf8mb3
BEGIN

   SET pValue = IF((LENGTH(pValue) <= 0 OR ISNULL(pValue)), "-", pValue);
   SET pValue = REPLACE(pValue, '\n', '');
   SET pValue = REPLACE(pValue, '\r', '');
   SET pValue = REPLACE(pValue, '"', '');
   SET pValue = REPLACE(pValue, 'Ñ', 'N');
   SET pValue = REPLACE(pValue, 'ñ', 'N');
   RETURN pValue;
END */$$
DELIMITER ;

/* Function  structure for function  `IFNULL_STRING_ONLY` */

/*!50003 DROP FUNCTION IF EXISTS `IFNULL_STRING_ONLY` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `IFNULL_STRING_ONLY`(pValue TEXT) RETURNS longtext CHARSET utf8mb3
    DETERMINISTIC
BEGIN
  SET pValue = UPPER(pValue);
  SET pValue = REPLACE(pValue, 'Ã‘', 'N');
  SET @input := pValue;
  #SET @pattern := '[^a-zA-Z0-9 \\-:_,]';
  SET @pattern := '[^a-zA-Z0-9 .\\-:_,]/';
  SET @cleaned_string := '';
  SET @i := 1;

  WHILE @i <= LENGTH(@input) DO
    SET @char := SUBSTRING(@input, @i, 1);
    IF @char REGEXP @pattern THEN
      SET @cleaned_string := CONCAT(@cleaned_string, '');
    ELSE
      SET @cleaned_string := CONCAT(@cleaned_string, @char);
    END IF;
    SET @i := @i + 1;
  END WHILE;

  SET pValue = @cleaned_string;

  IF (LENGTH(pValue) = 0 OR ISNULL(pValue) OR pValue = 'NULL') THEN
    SET pValue = '-';
  END IF;

  RETURN pValue;
END */$$
DELIMITER ;

