/* Procedure structure for procedure `spBillingProcess` */

/*!50003 DROP PROCEDURE IF EXISTS  `spBillingProcess` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spBillingProcess`(
    IN vID INT
)
BEGIN
    -- Error handling for rollback
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK; -- Roll back transaction in case of error for secure data insertion
    END;

    START TRANSACTION;
    
	 INSERT INTO tblbilling(Type_ID, Ir_Id, Merchant_ID, TID, MID, Terminal_ID, Sim_ID, Service_ID, Client_ID, Status_ID, Service_Date, Coverage_Date, Created_Date)
	 SELECT
		1 AS Type_ID,
		Ir_ID,
		Merchant_ID,
		TID,
		MID,
		Terminal_ID,
		Sim_ID,
		Service_ID, 
		Client_ID, 
		Status_ID, 
		Service_Date, 
		Coverage_Date,
		Created_Date
	 FROM tblbilling_temp;

    TRUNCATE TABLE tblbilling_temp;

    INSERT INTO tblbilling_temp(Ir_ID, Merchant_ID, TID, MID, Terminal_ID, Sim_ID, Service_ID, Client_ID, Status_ID, Service_Date, Coverage_Date, Created_Date)
    SELECT
        Ir_ID,
        Merchant_ID,
        TID, 
        MID, 
        Terminal_ID,
        Sim_ID,
        Service_ID,
        Client_ID,
        '7',
        Service_Date,
        Coverage_Date,
        NOW() AS Created_Date
    FROM tblbilling_terminals
    WHERE MONTH(Coverage_Date) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
    AND YEAR(Coverage_Date) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
    AND Client_ID = vID;

    INSERT INTO tblbilling_temp(Ir_ID, Merchant_ID, TID, MID, Terminal_ID, Sim_ID, Service_ID, Client_ID, Status_ID, Service_Date, Coverage_Date, Created_Date)
    SELECT
        sd.IRIDNo,
        sd.MerchantID,
        ir.TID,
        ir.MID,
        sd.TerminalID AS Terminal_ID,
        COALESCE(sd.SIMID, 0) AS Sim_ID,
        sd.ServiceNo,
        sd.ClientID,
        sd.ServiceStatus AS Status_ID,
        fd.FSRDate,
        LAST_DAY(DATE_SUB(CURDATE(), INTERVAL 1 MONTH)) AS Coverage_Date,
        NOW() AS Created_Date
    FROM tblservicingdetail sd
    LEFT JOIN tblfsrdetail fd ON fd.ServiceNo = sd.ServiceNo
    LEFT JOIN tblirdetail ir ON ir.IRIDNo = sd.IRIDNo
    WHERE sd.ClientID = vID
    AND sd.JobType = 4
    AND sd.ServiceStatus = 11
    AND sd.JobTypeStatusDescription = 'COMPLETED'
    AND fd.ActionMade = 'SUCCESS'
    AND MONTH(fd.FSRDate) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
    AND YEAR(fd.FSRDate) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
    GROUP BY sd.ServiceNo
    ON DUPLICATE KEY UPDATE
        Status_ID = VALUES(Status_ID);

    COMMIT;
END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckAndUpdateSNStatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckAndUpdateSNStatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckAndUpdateSNStatus`(  
    IN p_StatementType VARCHAR(30), 
    IN p_SearchBy VARCHAR(50), 
    IN p_SearchValue VARCHAR(50) -- Expected format: "ClientID|LocationID|StatusID"
)
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE var_id INT; 
    DECLARE v_ClientID INT;
    DECLARE v_LocationID INT;
    DECLARE v_StatusID INT;

    -- Declare cursor
    DECLARE cur CURSOR FOR SELECT ID FROM temp_result;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    -- Extract values from `p_SearchValue`
    SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
    SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
    
    -- Create temporary table for cursor processing
    CREATE TEMPORARY TABLE temp_result (ID INT);

    -- Populate temporary table based on search type
    IF p_SearchBy = 'Terminal' THEN
        INSERT INTO temp_result (ID)
        SELECT TerminalID FROM tblterminaldetail 
        WHERE ClientID = v_ClientID 
          AND TerminalStatus != 7 -- NOT INSTALLED
          AND LocationID = v_LocationID;
    ELSEIF p_SearchBy = 'SIM' THEN
        INSERT INTO temp_result (ID)
        SELECT SIMID FROM tblsimdetail 
        WHERE ClientID = v_ClientID 
          AND SIMStatus != 7 -- NOT INSTALLED
          AND LocationID = v_LocationID;
    END IF;

    -- Open cursor
    OPEN cur;

    -- Loop through cursor
    read_loop: LOOP
        FETCH cur INTO var_id;
        IF done THEN 
            LEAVE read_loop;
        END IF;

        -- Update query based on search type
        IF p_SearchBy = 'Terminal' THEN
            SET @QUERY = CONCAT('UPDATE tblterminaldetail SET TerminalStatus = 7, TerminalStatusDescription = "INSTALLED" WHERE TerminalID = ', var_id, ';');
        ELSEIF p_SearchBy = 'SIM' THEN
            SET @QUERY = CONCAT('UPDATE tblsimdetail SET SIMStatus = 7, SIMStatusDescription = "INSTALLED" WHERE SIMID = ', var_id, ';');
        END IF;

	-- debugging
	#SELECT @QUERY;
	
        -- Execute update query
        IF (var_id > 0) THEN
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
        END IF;
        
    END LOOP;

    -- Close cursor and drop temp table
    CLOSE cur;
    DROP TEMPORARY TABLE IF EXISTS temp_result;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckControlID` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckControlID` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckControlID`(  

	IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(255) /* = NULL */ ,

	OUT p_outID INTEGER

)
BEGIN

    DECLARE v_ID INTEGER;

    DECLARE v_TerminalSerialNo VARCHAR(45);

    DECLARE v_TID VARCHAR(45);

    DECLARE v_MID VARCHAR(45);

    DECLARE v_IDNo VARCHAR(45);

    DECLARE p_WHERE LONGTEXT;    

    DECLARE p_SQL LONGTEXT;       

    DECLARE p_ORDERBY LONGTEXT;

    DECLARE p_GROUPBY LONGTEXT;

    DECLARE p_TempQuery LONGTEXT;

    DECLARE p_INSERT LONGTEXT;

    IF (p_StatementType = 'Search')

    THEN

	IF (p_SearchBy = 'TA')

        THEN

		SET v_TerminalSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		

		SELECT TAIDNo INTO v_ID

		FROM tblterminalallocation		

		WHERE (TerminalSN = v_TerminalSerialNo AND TID = v_TID AND `MID` = v_MID)

		LIMIT 1;

			

	ELSEIF (p_SearchBy = 'SIM Master')

	THEN		

		SELECT SIID INTO v_ID

		FROM tblsimmaster		

		ORDER BY SIID DESC

		LIMIT 1;

		

	ELSEIF (p_SearchBy = 'Terminal Master')

	THEN		

		SELECT TIID INTO v_ID

		FROM tblterminalmaster		

		ORDER BY TIID DESC

		LIMIT 1;

	

	ELSEIF (p_SearchBy = 'IR Detail')

	THEN		

		SELECT IRIDNo INTO v_ID

		FROM tblirdetail		

		ORDER BY IRIDNo DESC

		LIMIT 1;

		

	ELSEIF (p_SearchBy = 'SC Detail')

	THEN		

		SELECT SCNo INTO v_ID

		FROM tblservicecalldetail		

		ORDER BY SCNo DESC

		LIMIT 1;

	

	ELSEIF (p_SearchBy = 'Servicing Detail')

	THEN		

		SELECT ServiceNo INTO v_ID

		FROM tblservicingdetail

		ORDER BY ServiceNo DESC

		LIMIT 1;

	

	ELSEIF (p_SearchBy = 'FSR Detail')

	THEN		

		SELECT FSRNo INTO v_ID

		FROM tblfsrdetail

		ORDER BY FSRNo DESC

		LIMIT 1;

			

	ELSEIF (p_SearchBy = 'Reason')

	THEN		

		SELECT ReasonID INTO v_ID

		FROM tblreason

		ORDER BY ReasonID DESC

		LIMIT 1;

	

	ELSEIF (p_SearchBy = 'IDNo')

	THEN		

		SET v_IDNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		

		SELECT ParticularID INTO v_ID

		FROM tblparticular		

		WHERE (IDNo = v_IDNo)

		LIMIT 1;

		

	ELSEIF (p_SearchBy = 'Terminal Movement Master')

	THEN		

		SELECT TransNo INTO v_ID

		FROM tblterminalmovementmaster		

		ORDER BY TransNo DESC

		LIMIT 1;

		

	ELSEIF (p_SearchBy = 'SIM Movement Master')

	THEN		

		SELECT TransNo INTO v_ID

		FROM tblsimmovementmaster		

		ORDER BY TransNo DESC

		LIMIT 1;

		

	ELSEIF (p_SearchBy = 'Invoice Master')

	THEN		

		SELECT InvoiceID INTO v_ID

		FROM tblpr_invoicesmaster		

		ORDER BY InvoiceID DESC

		LIMIT 1;
		
	ELSEIF (p_SearchBy = 'Stock Master')

	THEN		

		SELECT StockID INTO v_ID

		FROM tblstockmaster		

		ORDER BY StockID DESC

		LIMIT 1;	
		
	ELSEIF (p_SearchBy = 'Stock Detail')

	THEN		

		SELECT ItemID INTO v_ID

		FROM tblstockdetail		

		ORDER BY ItemID DESC

		LIMIT 1;
		
	ELSEIF (p_SearchBy = 'MSP Master')

	THEN		

		SELECT MSPNo INTO v_ID

		FROM tblmspmaster		

		ORDER BY MSPNo DESC

		LIMIT 1;			

	ELSEIF (p_SearchBy = 'Helpdesk-Master-ID')
	THEN		
		SELECT AssistNo INTO v_ID
		FROM tblhdmaster
		ORDER BY AssistNo DESC
		LIMIT 1;
  	ELSEIF (p_SearchBy = 'Helpdesk-Request-ID')
	THEN		
		SELECT ProblemNo INTO v_ID
		FROM tblhddetail
		ORDER BY ProblemNo DESC
		LIMIT 1;
		
	ELSEIF (p_SearchBy = 'Expenses-FSR')
	THEN		
		SELECT ExpensesNo INTO v_ID
		FROM tblexpensestransmaster
		ORDER BY ExpensesNo DESC
		LIMIT 1;

	END IF;         

    END IF; 

    

    SET p_outID = IFNULL(v_ID, 0);

    

    IF (p_outID > 0)

    THEN

	SET p_outID = p_outID + 1;

    ELSE

	SET p_outID = 1;

    END IF;	

    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckDuplicateCity` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckDuplicateCity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckDuplicateCity`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

DECLARE var_sql_statement VARCHAR(1000);

DECLARE v_finished INT DEFAULT 0;

DECLARE v_ID INT;    

DECLARE v_SystemDate DATE;

DECLARE v_SystemTime TIME;

DECLARE sQuery VARCHAR(1000);

DECLARE C1 CURSOR FOR

	SELECT CONCAT("DELETE FROM tblcity WHERE CityID=",temp.MaxID,";") AS exec_sql FROM

	(SELECT MAX(u.CityID) AS MaxID, IF(MIN(u.CityID)=MAX(u.CityID),"","DUPLICATE") AS STATUS

	FROM 	tblcity AS u

	GROUP BY u.City) temp

	WHERE temp.`status`='DUPLICATE';

DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

SET v_SystemDate = CURDATE();

SET v_SystemTime = CURTIME();

START TRANSACTION;

IF (p_StatementType = 'Search')

THEN

	IF (p_SearchBy = 'Duplicate')

	THEN

		OPEN C1;

		GET_RECORD: LOOP

			FETCH C1 INTO var_sql_statement;                

			#SELECT (CONCAT('var_sql_statement=', var_sql_statement));

			

			SET @QUERY = var_sql_statement;					                

			IF (v_finished = 1)

			THEN

				LEAVE GET_RECORD;

			END IF;

			

			# Execute Query (Delete)

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;			

			

			# Save Duplicate as repository

			SET sQuery = "";

			SET sQuery = CONCAT("(", "'", var_sql_statement, "',", "'", 'Import City', "',", "'", v_SystemDate, "',", "'", v_SystemTime, "'", ")");				

			CALL spInsertCollectionDetail("Insert", "", "","Duplicate Detail", sQuery, @p_outErrorMessage, @p_outLastInsertID);				 

		END LOOP GET_RECORD;

		CLOSE C1;

	END IF;     

END IF; 

COMMIT;   

       

END */$$
