/* Procedure structure for procedure `spCheckDuplicateSIM` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckDuplicateSIM` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckDuplicateSIM`(  

IN p_StatementType VARCHAR(30) /* = NULL */ ,

IN p_SearchBy VARCHAR(50) /* = NULL */ ,

IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

DECLARE var_sql_statement VARCHAR(1000);

DECLARE v_finished INT DEFAULT 0;

DECLARE v_ID INT;    

DECLARE v_SystemDate DATE;

DECLARE v_SystemTime TIME;

DECLARE sQuery VARCHAR(1000);



DECLARE v_DupID INT;

DECLARE v_ControlNo INT;  

DECLARE v_SerialNo VARCHAR(45);

DECLARE v_Query VARCHAR(1000);

DECLARE C1 CURSOR FOR

		/* SELECT CONCAT("DELETE FROM tblsimdetail WHERE SIMID=",temp.MaxID,";") AS exec_sql FROM

		(SELECT MAX(u.SIMID) AS MaxID, IF(MIN(u.SIMID)=MAX(u.SIMID),"","DUPLICATE") AS STATUS

		FROM 	tblsimdetail AS u

		GROUP BY u.SerialNo) temp

		WHERE temp.`status`='DUPLICATE'; */

		

		SELECT CONCAT(t1.SIID, "|", t1.SIMID, "|", t2.SerialNo, "|", "DELETE FROM tblsimdetail WHERE SIMID=",t1.SIMID,";") AS exec_sql

		FROM tblsimdetail t1

		INNER JOIN (

		SELECT MIN(SIMID) AS min_id, SerialNo, SIID

		FROM tblsimdetail

		GROUP BY SerialNo

		HAVING COUNT(*) > 1 )

		t2 ON t1.SerialNo = t2.SerialNo AND t1.SIMID > t2.min_id;

		

    

DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

SET v_SystemDate = CURDATE();

SET v_SystemTime = CURTIME();

START TRANSACTION;

IF (p_StatementType = 'Search')

THEN

	IF (p_SearchBy = 'Duplicate')

THEN

		

		CALL spDeleteCollectionDetail("Delete", "", "Import SIM", "Duplicate Detail");

					

		OPEN C1;

		GET_RECORD: LOOP

			FETCH C1 INTO var_sql_statement;                

			#SELECT (CONCAT('var_sql_statement=', var_sql_statement));

			

			SET v_DupID = CAST(TRIM(SPLIT_STRING(var_sql_statement, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ControlNo = CAST(TRIM(SPLIT_STRING(var_sql_statement, '|' ,2)) AS UNSIGNED INTEGER);	

			SET v_SerialNo = TRIM(SPLIT_STRING(var_sql_statement, '|' ,3));

			SET v_Query = TRIM(SPLIT_STRING(var_sql_statement, '|' ,4));

			              

			SET @QUERY = v_Query;					                

			IF (v_finished = 1)

			THEN

				LEAVE GET_RECORD;

			END IF;

			# Execute Query (Delete)

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

			# Save Duplicate as repository

			SET sQuery = "";

			SET sQuery = CONCAT("(", "'", v_DupID, "',", "'", v_ControlNo, "',", "'", v_SerialNo, "',", "'", v_Query, "',", "'", 'Import SIM', "',", "'", v_SystemDate, "',", "'", v_SystemTime, "'", ")");				

			CALL spInsertCollectionDetail("Insert", "", "","Duplicate Detail2", sQuery, @p_outErrorMessage, @p_outLastInsertID);

	

		END LOOP GET_RECORD;

		CLOSE C1;

END IF;     

END IF;    

COMMIT;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckDuplicateTerminal` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckDuplicateTerminal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckDuplicateTerminal`(  

IN p_StatementType VARCHAR(30) /* = NULL */ ,

IN p_SearchBy VARCHAR(50) /* = NULL */ ,

IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

DECLARE var_sql_statement VARCHAR(1000);

DECLARE v_finished INT DEFAULT 0;

DECLARE v_ID INT;  

DECLARE v_SystemDate DATE;

DECLARE v_SystemTime TIME;

DECLARE sQuery VARCHAR(1000);

DECLARE v_DupID INT;

DECLARE v_ControlNo INT;  

DECLARE v_SerialNo VARCHAR(45);

DECLARE v_Query VARCHAR(1000);

DECLARE C1 CURSOR FOR

		SELECT CONCAT(t1.TIID, "|", t1.TerminalID, "|", t2.SerialNo, "|", "DELETE FROM tblterminaldetail WHERE TerminalID =",t1.TerminalID,";") AS exec_sql

		FROM tblterminaldetail t1

		INNER JOIN (

		SELECT MIN(TerminalID) AS min_id, SerialNo, TIID

		FROM tblterminaldetail

		GROUP BY SerialNo

		HAVING COUNT(*) > 1 )

		t2 ON t1.SerialNo = t2.SerialNo AND t1.TerminalID > t2.min_id;

    

DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

SET v_SystemDate = CURDATE();

SET v_SystemTime = CURTIME();

START TRANSACTION;

IF (p_StatementType = 'Search')

THEN

	IF (p_SearchBy = 'Duplicate')

THEN

		CALL spDeleteCollectionDetail("Delete", "", "Import Terminal", "Duplicate Detail");

		

		OPEN C1;

		GET_RECORD: LOOP

			FETCH C1 INTO var_sql_statement;                

			#SELECT (CONCAT('var_sql_statement=', var_sql_statement));  

			

			SET v_DupID = CAST(TRIM(SPLIT_STRING(var_sql_statement, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ControlNo = CAST(TRIM(SPLIT_STRING(var_sql_statement, '|' ,2)) AS UNSIGNED INTEGER);	

			SET v_SerialNo = TRIM(SPLIT_STRING(var_sql_statement, '|' ,3));

			SET v_Query = TRIM(SPLIT_STRING(var_sql_statement, '|' ,4));

			              

			SET @QUERY = v_Query;					                

			IF (v_finished = 1)

			THEN

				LEAVE GET_RECORD;

			END IF;

			# Execute Query (Delete)

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

			# Save Duplicate as repository

			SET sQuery = "";

			SET sQuery = CONCAT("(", "'", v_DupID, "',", "'", v_ControlNo, "',", "'", v_SerialNo, "',", "'", v_Query, "',", "'", 'Import Terminal', "',", "'", v_SystemDate, "',", "'", v_SystemTime, "'", ")");				

			CALL spInsertCollectionDetail("Insert", "", "","Duplicate Detail2", sQuery, @p_outErrorMessage, @p_outLastInsertID);

	

		END LOOP GET_RECORD;

		CLOSE C1;

END IF;     

END IF;    

COMMIT;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckDuplicateTimeSheet` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckDuplicateTimeSheet` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckDuplicateTimeSheet`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE var_sql_statement VARCHAR(1000);

	DECLARE v_finished INT DEFAULT 0;

    DECLARE v_ID INT;    

    DECLARE v_SystemDate DATE;

	DECLARE v_SystemTime TIME;

	DECLARE sQuery VARCHAR(1000);

	

    DECLARE C1 CURSOR FOR

			SELECT CONCAT("DELETE FROM tbltimesheetdetail WHERE TimeSheetID=",temp.MaxID,";") AS exec_sql FROM

			(SELECT MAX(u.TimeSheetID) AS MaxID, IF(MIN(u.TimeSheetID)=MAX(u.TimeSheetID),"","DUPLICATE") AS STATUS

			FROM 	tbltimesheetdetail AS u

			GROUP BY u.ParticularID, `Date`, TimeIn) temp

			WHERE temp.`status`='DUPLICATE';

            

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

    

    SET v_SystemDate = CURDATE();

    SET v_SystemTime = CURTIME();

    

    IF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Duplicate')

        THEN

			OPEN C1;

			GET_RECORD: LOOP

				FETCH C1 INTO var_sql_statement;                

				#SELECT (CONCAT('var_sql_statement=', var_sql_statement));

				

				SET @QUERY = var_sql_statement;					                

				IF (v_finished = 1)

				THEN

					LEAVE GET_RECORD;

				END IF;

				

				# Execute Query (Delete)

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;			

				

			END LOOP GET_RECORD;

			CLOSE C1;

       END IF;     

    END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckRecordExist` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckRecordExist` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckRecordExist`(  

	IN p_StatementType VARCHAR(50) /* = NULL */ ,

	IN p_SearchBy VARCHAR(500) /* = NULL */ ,

	IN p_SearchValue LONGTEXT /* = NULL */ ,

	OUT p_outCount INTEGER

)
BEGIN

DECLARE v_Count INT;

DECLARE v_TCount INT;

DECLARE v_ID INT;

DECLARE v_Region VARCHAR(50);

DECLARE v_Province VARCHAR(50);

DECLARE v_City VARCHAR(50);

DECLARE v_SerialNo VARCHAR(50);

DECLARE v_ParticularName VARCHAR(255);

DECLARE v_UserName VARCHAR(255);

DECLARE v_Password VARCHAR(255);

DECLARE v_TID VARCHAR(50);

DECLARE v_MID VARCHAR(50);

DECLARE v_ParticularID INT;

DECLARE v_MerchantID INT;

DECLARE v_ClientID INT;

DECLARE v_Status INT;

DECLARE v_RequestNo VARCHAR(45);

DECLARE v_IRNo VARCHAR(45);

DECLARE v_TerminalID INT;

DECLARE v_SIMID INT;

DECLARE v_Temp VARCHAR(255);

DECLARE v_LeaveTypeID INT;

DECLARE v_LeaveDate VARCHAR(50);

DECLARE v_Date VARCHAR(50);

DECLARE v_ComputerName VARCHAR(50);

DECLARE v_IRIDNo INT;

DECLARE v_JobType INT;

DECLARE v_ServiceNo INT;

DECLARE v_TerminalType VARCHAR(50);

DECLARE v_TerminalModel VARCHAR(50);

DECLARE v_TerminalBrand VARCHAR(50);

DECLARE v_SIMCarrier VARCHAR(50);

DECLARE v_FSRNo INT;

DECLARE v_RegionType INT;
DECLARE v_RegionID INT;
DECLARE v_Address LONGTEXT;

#Privacy Detail

DECLARE v_PrivacyID INT;

DECLARE v_UserID INT;

DECLARE v_FunctionID INT;

DECLARE v_FunctionType VARCHAR(45);

DECLARE v_ReferenceNo VARCHAR(45);

DECLARE v_Name VARCHAR(255);

DECLARE v_Type INT;

DECLARE v_TableName VARCHAR(255);
DECLARE v_FieldName VARCHAR(255);
DECLARE v_FieldValue VARCHAR(255);

DECLARE p_WHERE LONGTEXT;    

DECLARE p_SQL LONGTEXT;       

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_TempQuery LONGTEXT;

DECLARE p_INSERT LONGTEXT;

    

    SET v_Count = 0;

    

	IF (p_StatementType = 'Search')

	THEN

		IF (p_SearchBy = 'SerialNo Check/TA')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblterminalallocation

				WHERE       (TerminalSN LIKE p_SearchValue);

		    

		ELSEIF (p_SearchBy = 'SerialNo Check')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT      DISTINCT   						

				COUNT(*) INTO v_Count

				FROM        tblterminaldetail

				WHERE       (SerialNo LIKE p_SearchValue);

		    

		ELSEIF (p_SearchBy = 'IRNo Check/IR Detail')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblirdetail

				WHERE       (IRNo LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'IRNo Check/IR Import Detail')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblinstallationrequestdetail

				WHERE       (MCC_INSTALLATION_REQUEST_ID LIKE p_SearchValue);

		    

		ELSEIF (p_SearchBy = 'IR Import')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblinstallationrequestmaster

				WHERE       (FileName LIKE p_SearchValue);	

		

		ELSEIF (p_SearchBy = 'FSR Import')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblfsrmaster

				WHERE       (FileName LIKE p_SearchValue);	         

		

		ELSEIF (p_SearchBy = 'Terminal Import')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblterminalmaster

				WHERE       (FileName LIKE p_SearchValue);	         

		 

		ELSEIF (p_SearchBy = 'SIM Import')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblsimmaster

				WHERE       (FileName LIKE p_SearchValue);

				 

		ELSEIF (p_SearchBy = 'Request ID')

		THEN

				SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblinstallationrequestdetail

				WHERE       (MCC_INSTALLATION_REQUEST_ID LIKE p_SearchValue);

		    

		ELSEIF (p_SearchBy = 'User Already Login')

		THEN

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tbluser

				WHERE       (LogStatus = 1 AND UserID = v_ID);

				   

		ELSEIF (p_SearchBy = 'Service Type Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblservicetype;

		

		ELSEIF (p_SearchBy = 'Terminal Status Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblterminalstatus;					

                

                ELSEIF (p_SearchBy = 'Merchant Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblparticular

				WHERE    ParticularTypeID = '1';

		

		ELSEIF (p_SearchBy = 'Client Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblparticular

				WHERE    ParticularTypeID = '2'; 

				

		ELSEIF (p_SearchBy = 'Field Engineer Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblparticular

				WHERE    ParticularTypeID = '3';

		

		ELSEIF (p_SearchBy = 'Supplier Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblparticular

				WHERE    ParticularTypeID = '4';	

				

		ELSEIF (p_SearchBy = 'Service Provider Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblparticular

				WHERE    ParticularTypeID = '5';	

		

		ELSEIF (p_SearchBy = 'Terminal Detail Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblterminaldetail;

				

		ELSEIF (p_SearchBy = 'Terminal Type Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblterminaltype;

		

		ELSEIF (p_SearchBy = 'Terminal Model Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblterminalmodel;	

				

		ELSEIF (p_SearchBy = 'Terminal Brand Count')

		THEN	

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblterminalbrand;

				

		ELSEIF (p_SearchBy = 'Region Detail Check')

		THEN											

			SET v_Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_Province = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblregiondetail a

			LEFT JOIN tblregion AS b ON a.RegionType = b.RegionID

			WHERE a.Province = v_Province AND b.Region = v_Region;

		

		ELSEIF (p_SearchBy = 'Terminal Detail Check')

		THEN											

			SET v_SerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblterminaldetail a			

			WHERE a.SerialNo = v_SerialNo;

			

		ELSEIF (p_SearchBy = 'SIM Detail Check')

		THEN											

			SET v_SerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblsimdetail a			

			WHERE a.SerialNo = v_SerialNo;

			

		ELSEIF (p_SearchBy = 'IR Detail Check')

		THEN											

			SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

						

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblirdetail a			

			WHERE a.TID = v_TID AND a.MID = v_MID AND a.MerchantID = v_MerchantID AND a.ClientID = v_ClientID;

			

		ELSEIF (p_SearchBy = 'Particular Name')

		THEN	

				SET v_ParticularName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
				SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
				SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
				SET v_Address = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
												
				SELECT         						
				COUNT(*) INTO v_Count
				FROM tblparticular a
				WHERE a.Name = ADD_SINGLEQUOTE(v_ParticularName) AND a.RegionType = v_RegionType AND a.RegionID = v_RegionID AND a.Address = ADD_SINGLEQUOTE(v_Address);						

		

		ELSEIF (p_SearchBy = 'Check UserName')

		THEN	

				SET v_UserName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

				

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tbluser

				WHERE    UserName = v_UserName;

		

		ELSEIF (p_SearchBy = 'RequestNo Check')

		THEN

				SET v_RequestNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

				

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblservicingdetail

				WHERE    RequestNo = v_RequestNo;

				

		ELSEIF (p_SearchBy = 'IRNo Check')

		THEN

				SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

				

				SELECT         						

				COUNT(*) INTO v_Count

				FROM        tblirdetail

				WHERE    IRNo = v_IRNo;	

		

		ELSEIF (p_SearchBy = 'Terminal Available Check')

		THEN											

			SET v_SerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblterminaldetail a			

			WHERE a.SerialNo = v_SerialNo AND TerminalStatus = 1;

			

		ELSEIF (p_SearchBy = 'SIM Available Check')

		THEN											

			SET v_SerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblsimdetail a			

			WHERE a.SerialNo = v_SerialNo AND SIMStatus = 1;

			

		ELSEIF (p_SearchBy = 'Particular Leave Date')

		THEN											

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_LeaveDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblleavemovement a			

			WHERE a.ParticularID = v_ParticularID AND (v_LeaveDate BETWEEN DateFrom AND DateTo);	

		

		ELSEIF (p_SearchBy = 'Incomplete Service')

		THEN											

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			

			

			SELECT

			COUNT(*) INTO v_Count

			FROM 

			tblservicingdetail a

			WHERE 

			a.JobTypeStatusDescription != 'COMPLETED' AND a.ServiceStatus NOT IN (9, 10)

			AND 

			a.IRIDNo = v_ID;

			

		ELSEIF (p_SearchBy = 'TerminalID')

		THEN

				SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

				

				SELECT 

				COUNT(*) INTO v_Count

				FROM tblterminal a			

				WHERE a.TerminalID = v_TID AND Active = 1;

				

		ELSEIF (p_SearchBy = 'Particular Work Arrangement Date')

		THEN											

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_Date = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblworkarrangement a			

			WHERE a.ParticularID = v_ParticularID AND (v_Date BETWEEN DateFrom AND DateTo);

			

		ELSEIF (p_SearchBy = 'Particular Computer Name')

		THEN											

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ComputerName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblparticular a			

			WHERE a.ParticularID = v_ParticularID AND ComputerName = v_ComputerName;	

		

		ELSEIF (p_SearchBy = 'Merchant Installation Success Count')
		THEN	
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			/*
			SELECT
			COUNT(*) INTO v_Count
			FROM
			tblirdetail ir
			LEFT JOIN (SELECT b.IRIDNo, b.JobType, b.ActionMade FROM tblfsrdetail b) fsr
			ON ir.IRIDNo = fsr.IRIDNo AND fsr.JobType = 1 AND fsr.ActionMade = 'SUCCESS'
			WHERE
			ir.IRIDNo = v_IRIDNo;
			*/
			
			SELECT COUNT(*) INTO v_Count 
			FROM tblfsrdetail a
			WHERE a.IRIDNo = v_IRIDNo AND
			a.JobType = 1 AND 
			a.ActionMade = 'SUCCESS';

		ELSEIF (p_SearchBy = 'Merchant Pending Service Count')

		THEN	

			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SELECT COUNT(*) INTO v_Count 

			FROM tblservicingdetail 

			WHERE IRIDNo = v_IRIDNo AND JobType = v_JobType AND

			(JobTypeStatusDescription = 'PROCESSING' OR JobTypeStatusDescription = 'PENDING') AND (isCancelled = 0);	

		

		ELSEIF (p_SearchBy = 'Merchant Delete Service Count')
		THEN
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SELECT COUNT(*) INTO v_Count 
			FROM tblservicingdetail a 
			WHERE a.ServiceNo = v_ServiceNo AND a.IRIDNo = v_IRIDNo;
	
		ELSEIF (p_SearchBy = 'User Privacy Detail')

		THEN	

			SET v_UserID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	

			SET v_FunctionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);	

			SET v_FunctionType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));	

			

			IF (STRCMP(v_FunctionType, "Add/New") = 0)

			THEN				

				SELECT COUNT(*) INTO v_Count 

				FROM 

				tblprivacymaster AS a

				LEFT JOIN tblprivacydetail AS b ON a.PrivacyID = b.PrivacyID

				WHERE 

				(a.FunctionID = v_FunctionID AND b.UserID = v_UserID AND b.isAdd > 0 AND a.isActive > 0 AND b.isActive > 0);

				

			ELSEIF (STRCMP(v_FunctionType, "Delete") = 0)

			THEN

				SELECT COUNT(*) INTO v_Count 

				FROM 

				tblprivacymaster AS a

				LEFT JOIN tblprivacydetail AS b ON a.PrivacyID = b.PrivacyID

				WHERE 

				(a.FunctionID = v_FunctionID AND b.UserID = v_UserID AND b.isDelete > 0 AND a.isActive > 0 AND b.isActive > 0);

			

			ELSEIF (STRCMP(v_FunctionType, "Save/Update") = 0)

			THEN

				SELECT COUNT(*) INTO v_Count 

				FROM 

				tblprivacymaster AS a

				LEFT JOIN tblprivacydetail AS b ON a.PrivacyID = b.PrivacyID

				WHERE 

				(a.FunctionID = v_FunctionID AND b.UserID = v_UserID AND b.isUpdate > 0 AND a.isActive > 0 AND b.isActive > 0);

			

			ELSEIF (STRCMP(v_FunctionType, "View/Access") = 0)

			THEN

				SELECT COUNT(*) INTO v_Count 

				FROM 

				tblprivacymaster AS a

				LEFT JOIN tblprivacydetail AS b ON a.PrivacyID = b.PrivacyID

				WHERE 

				(a.FunctionID = v_FunctionID AND b.UserID = v_UserID AND b.isView > 0 AND a.isActive > 0 AND b.isActive > 0);

			ELSEIF (STRCMP(v_FunctionType, "Print/Report") = 0)

			THEN

				SELECT COUNT(*) INTO v_Count 

				FROM 

				tblprivacymaster AS a

				LEFT JOIN tblprivacydetail AS b ON a.PrivacyID = b.PrivacyID

				WHERE 

				(a.FunctionID = v_FunctionID AND b.UserID = v_UserID AND b.isPrint > 0 AND a.isActive > 0 AND b.isActive > 0);

			

			END IF; 

			

		ELSEIF (p_SearchBy = 'TimeSheet')

		THEN

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_Date = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS DATE);

			

			SELECT COUNT(*) INTO v_Count 

			FROM tbltimesheetdetail a 

			WHERE a.ParticularID = v_ParticularID AND a.Date = v_Date;	

			

		ELSEIF (p_SearchBy = 'RequestID')

		THEN

			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			

			SELECT COUNT(*) INTO v_Count 

			FROM tblirdetail a

			WHERE a.IRIDNo != v_IRIDNo AND a.IRNo = v_IRNo;

			

		ELSEIF (p_SearchBy = 'Terminal Type/Model Check')

		THEN											

			SET v_TerminalType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_TerminalModel = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblterminaltype a

			LEFT JOIN tblterminalmodel b on a.TerminalTypeID = b.TerminalTypeID	

			WHERE a.Description = v_TerminalType AND b.Description = v_TerminalModel;

			

		ELSEIF (p_SearchBy = 'SIM Carrier Check')

		THEN											

			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tbltype a

			WHERE a.Description = v_SIMCarrier AND a.Type = 1;

			

		ELSEIF (p_SearchBy = 'eFSR Email')

		THEN											

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblfsrdetail a

			WHERE a.ServiceNo = v_ID AND a.FSRNo = v_FSRNo AND a.isPDF > 0;

			

		ELSEIF (p_SearchBy = 'eFSR User')

		THEN											

			SET v_UserName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_Password = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tbluser a

			WHERE (a.UserName = v_UserName AND a.MD5Password = v_Password);

			

		ELSEIF (p_SearchBy = 'eFSR Email/Diagnostic')

		THEN											

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblfsrdetail a

			WHERE a.ServiceNo = v_ID AND a.FSRNo = v_FSRNo AND a.isPDF > 0 AND a.isDiagnostic > 0;

			

		ELSEIF (p_SearchBy = 'eFSR Diagnostic')

		THEN											

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblfsrdetail a

			WHERE a.ServiceNo = v_ID AND a.FSRNo = v_FSRNo AND LENGTH(a.diagnostic_info) > 0;

			

		ELSEIF (p_SearchBy = 'eFSR Registration')

		THEN											

			SET v_Temp = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblregistration a

			WHERE a.IMEID = v_Temp;

			

		ELSEIF (p_SearchBy = 'Valid SN Location')

		THEN											

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tbllocation a

			WHERE a.LocationID = v_ID AND a.isReleased > 0;
			
		ELSEIF (p_SearchBy = 'Service ReferenceNo')

		THEN											

			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_ReferenceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			

			SELECT 

			COUNT(*) INTO v_Count

			FROM tblservicingdetail a

			WHERE 
			a.IRIDNo = v_IRIDNo AND 
			a.JobType = v_JobType AND 
			a.ReferenceNo = v_ReferenceNo and
			((SELECT MAX(a.ServiceNo) FROm tblfsrdetail a WHERE a.IRIDNo = v_IRIDNo and a.JobType = v_JobType AND a.ActionMade = 'SUCCESS') >  0);
			
		ELSEIF (p_SearchBy = 'Service RequestID')
		THEN

		    SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
		    SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);
		    SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));

		    SELECT COUNT(*)
		    INTO v_Count
		    FROM
		    (
			SELECT
			    s.ServiceNo,
			    s.JobType,
			    UPPER(IFNULL(f.ActionMade, '')) AS ActionMade
			FROM tblservicingdetail s
			LEFT JOIN tblfsrdetail f
			    ON f.ServiceNo = s.ServiceNo
			   AND f.IRIDNo = s.IRIDNo
			   AND f.IRNo = s.IRNo
			   AND f.JobType = s.JobType
			WHERE s.IRIDNo = v_IRIDNo
			  AND s.IRNo = v_IRNo
			  AND s.isActive > 0
			  AND s.isCancelled = 0

			ORDER BY s.ServiceNo DESC
			LIMIT 1
		    ) latest_service
		    WHERE NOT (
			latest_service.JobType = v_JobType
			AND latest_service.ActionMade = 'NEGATIVE'
		    );
			
		ELSEIF (p_SearchBy = 'Region')

		THEN											

			SET v_Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));


			SELECT 

			COUNT(*) INTO v_Count

			FROM tblregion a

			WHERE a.Region = v_Region AND a.isActive > 0;
			
		ELSEIF (p_SearchBy = 'Province')

		THEN											

			SET v_Province = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));


			SELECT 

			COUNT(*) INTO v_Count

			FROM tblregiondetail a

			WHERE a.Province = v_Province;
			
		ELSEIF (p_SearchBy = 'City')

		THEN											

			SET v_City = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));


			SELECT 

			COUNT(*) INTO v_Count

			FROM tblcity a

			WHERE a.City = v_City;
			
		ELSEIF (p_SearchBy = 'Region Detail')

		THEN											

			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));


			SELECT 

			COUNT(*) INTO v_Count

			FROM tblregiondetail a

			WHERE a.Province = v_Name;


		ELSEIF (p_SearchBy = 'Diagnostic Detail')
		THEN											
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			#SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SELECT 
			COUNT(*) INTO v_Count
			FROM tbldiagnosticdetail a
			WHERE 
			a.ServiceNo = v_ServiceNo 
			AND a.TypeID = 3;	
			
		ELSEIF (p_SearchBy = 'TerminalSN From IRDetail')
		THEN											
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a
			WHERE a.IRIDNo = v_IRIDNo AND a.TerminalID = v_ID;
			
		ELSEIF (p_SearchBy = 'SIMSN From IRDetail')
		THEN											
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a
			WHERE a.IRIDNo = v_IRIDNo AND a.SIMID = v_ID;	
			
		ELSEIF (p_SearchBy = 'TID/MID')
		THEN	
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a			
			WHERE 
			a.TID = v_TID 
			AND a.MID = v_MID 
			AND a.ClientID = v_ClientID
			AND a.IRNo = v_IRNo
			AND a.IRActive > 0;
			
		ELSEIF (p_SearchBy = 'TerminalSN')
		THEN
				SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
				
				SELECT   						
				COUNT(*) INTO v_Count
				FROM        tblterminaldetail
				WHERE       (TerminalSN = v_Name);
				
		ELSEIF (p_SearchBy = 'SIMSN')
		THEN
				SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
				
				SELECT   						
				COUNT(*) INTO v_Count
				FROM        tblsimdetail
				WHERE       (SIMSN = v_Name);
				
		ELSEIF (p_SearchBy = 'Merchant TID/MID')
		THEN	
			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_ParticularName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			# get merchant id
			SELECT COUNT(*) INTO @TCount FROm tblirdetail a WHERE a.TID = v_TID AND a.MID = v_MID AND a.MerchantName = v_ParticularName;
			
			IF (@TCount > 0) THEN
				SET v_Count = 1;
			ELSE
				SET v_Count = 0;
			END IF;
			
			/*
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a			
			WHERE 
			a.TID = v_TID 
			AND a.MID = v_MID
			*/
			
		ELSEIF (p_SearchBy = 'Merchant Installed')
		THEN			
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a			
			WHERE 
			a.IRIDNo = v_ID 
			AND a.TerminalID > 0;
			
		ELSEIF (p_SearchBy = 'Duplicate Assign TerminalSN')
		THEN	
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a
			WHERE a.TerminalID = v_ID;
			
		ELSEIF (p_SearchBy = 'Duplicate Assign SIMSN')
		THEN	
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a
			WHERE a.SIMID = v_ID;
			
		ELSEIF (p_SearchBy = 'MSP Merchant')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblparticular a
			WHERE a.Name = v_Name;
			
		ELSEIF (p_SearchBy = 'Import Master')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_Type = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblimportmaster a
			WHERE a.ControlNo = v_ID AND a.FileType = v_Type;
			
		ELSEIF (p_SearchBy = 'IR RawData Info')
		THEN
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a
			WHERE a.IRIDNo = v_IRIDNo AND a.TID = v_TID AND a.MID = v_MID AND (a.rawdata_info IS NOT NULL OR LENGTH(a.rawdata_info) > 0);
			
		ELSEIF (p_SearchBy = 'IR Profile Info')
		THEN
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblirdetail a
			WHERE a.IRIDNo = v_IRIDNo AND a.TID = v_TID AND a.MID = v_MID AND (a.profile_info IS NOT NULL OR LENGTH(a.profile_info) > 0);
			
		ELSEIF (p_SearchBy = 'Dynamic Search')
		THEN		
			SET v_TableName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_FieldName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_FieldValue = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SET @QUERY = CONCAT('SELECT COUNT(*) INTO @v_Count FROM ', v_TableName, ' WHERE ', v_FieldName, ' = ', v_FieldValue, ';');
			
			PREPARE stmt FROM @QUERY;
			EXECUTE stmt;
			DEALLOCATE PREPARE stmt;
			
			SELECT @v_Count INTO v_Count;
			
		ELSEIF (p_SearchBy = 'Daily Log Email')
		THEN
			SET v_Date = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT 
			COUNT(*) INTO v_Count
			FROM tbllogemail a
			WHERE a.SentDate = v_Date;
			
		ELSEIF (p_SearchBy = 'Holiday')
		THEN
		    SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
		    SET @Date = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));

		    SELECT COUNT(*)
		    INTO v_Count
		    FROM tblholiday a
		    WHERE a.HolidayDate = @Date
		      AND a.Description = @Description;
			
		ELSEIF (p_SearchBy = 'Report Status')
		THEN
			SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblreportstatus a
			WHERE a.ReportDesc = @Description;
			
		ELSEIF (p_SearchBy = 'Merchant Assign SN')
		THEN
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SET v_Count = 0;
			IF EXISTS (
				SELECT 1
				FROM tblfsrdetail
				WHERE IRIDNo = v_IRIDNo
				  AND FSRNo = (
				      SELECT MAX(FSRNo)
				      FROM tblfsrdetail
				      WHERE IRIDNo = v_IRIDNo
				      AND JobType IN (1, 7)
				      AND ServiceStatus = 7
				      AND ActionMade = 'SUCCESS'
				  )
				LIMIT 1
			    ) THEN
				SET v_Count = 1;
			    END IF;
			    
		ELSEIF (p_SearchBy = 'Changes Service')
		THEN
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT COUNT(*) INTO v_Count
			FROM tblservicechangesdetail a 
			WHERE
			a.isActive > 0
			AND a.ServiceNo = v_ServiceNo 
			AND a.IRIDNo = v_IRIDNo;
			
		ELSEIF (p_SearchBy = 'Merchant-Address')
		THEN	
			SET @Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @Address = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @Province = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			# get merchant
			SELECT COUNT(*) INTO @TCount FROM tblparticular a WHERE a.Name = @Name AND a.Address = @Address AND a.Region = @Region AND a.Province = @Province;
			
			IF (@TCount > 0) THEN
				SET v_Count = 1;
			ELSE
				SET v_Count = 0;
			END IF;
			
		/*Raiden*/
		ELSEIF p_SearchBy = 'Override-Service Check SIMID' THEN

		    SET @SIMID  = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
		    SET @IRIDNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
		    SET v_Count = 0;

			IF (@SIMID > 0) then
			
				SELECT COUNT(*)
				    INTO v_Count
				    FROM tblfsrdetail fsr
				    WHERE fsr.SIMID = @SIMID
				      AND fsr.ActionMade = 'SUCCESS'
				      AND fsr.JobType = 1
				      AND NOT EXISTS (
					  SELECT 1
					  FROM tblfsrdetail rel
					  WHERE rel.SIMID = @SIMID
					    AND rel.ActionMade = 'SUCCESS'
					    AND rel.JobType IN (4, 7)
					    AND rel.FSRNo > fsr.FSRNo
					    AND EXISTS (
						SELECT 1
						FROM tblservicingdetail relsvc
						WHERE relsvc.ServiceNo = rel.ServiceNo
						  AND relsvc.IRIDNo = rel.IRIDNo
						  AND relsvc.JobType = rel.JobType
						  AND relsvc.JobTypeStatusDescription = 'COMPLETED'
						  AND relsvc.isCancelled = 0
						  AND relsvc.isActive > 0
					    )
				      );
				      
			END IF;	      


		    IF v_Count = 0 THEN
			SELECT COUNT(*)
			INTO v_Count
			FROM tblirdetail
			WHERE IRIDNo = @IRIDNo
			  AND SIMID = @SIMID;
		    END IF;			
		    
		    IF v_Count = 0 THEN
			SELECT COUNT(*)
			INTO v_Count
			FROM tblsimdetail
			WHERE SIMID = @SIMID
			  AND SIMStatus = 7;
		    END IF;
			
		/*Raiden*/
		ELSEIF (p_SearchBy = 'Check Preinstalled Terminal')
		THEN
		    SET @ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		    SET @IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		    SET @MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);		    
		    SET @TID = TRIM(SPLIT_STRING(p_SearchValue, '|', 4));
		    SET @MID = TRIM(SPLIT_STRING(p_SearchValue, '|', 5));
		    
		    SET v_Count = 0;
		    
		    SELECT COUNT(*) INTO v_Count
		    FROM tblirdetail ir
		    WHERE ir.TID = @TID
		      AND ir.TerminalID IS NOT NULL AND ir.TerminalID > 0		      
		      AND EXISTS (
			    SELECT 1
			    FROM tblservicingdetail svd
			    WHERE svd.IRIDNo = ir.IRIDNo
			      AND svd.JobType = 1
			      AND svd.JobTypeStatusDescription = 'COMPLETED'
		      )
		      AND EXISTS (
			    SELECT 1 
			    FROM tblfsrdetail fsr
			    WHERE fsr.IRIDNo = ir.IRIDNo
			      AND fsr.JobType = 1
			      AND fsr.ActionMade = 'SUCCESS'
		      );
		      
		ELSEIF (p_SearchBy = 'Zoning')
		THEN
			SET @Cluster = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));		
			SET @Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));		
			SET @Area = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));		
			SET @CityMunicipal = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));		
			SET @ZoneName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			
			SELECT COUNT(*) INTO v_Count
			FROM tblzoning a
			WHERE
				Cluster = @Cluster 
				AND Region = @Region 
				AND `Area` = @Area
				AND CityMunicipal = @CityMunicipal
				AND ZoneName = @ZoneName;	
				
		ELSEIF (p_SearchBy = 'Location')
		THEN
		    SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));

		    SELECT COUNT(*) INTO v_Count
		    FROM tbllocation a
		    WHERE a.isActive > 0
		      AND (
			    a.Description = @Description
			  );			
		      
		ELSEIF (p_SearchBy = 'Terminal Status')
		THEN	
				SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));

				SELECT         						
				COUNT(*) INTO v_Count
				FROM        tblterminalstatus a
				WHERE a.Description = @Description;
				
		ELSEIF (p_SearchBy = 'Terminal Type')
		THEN	
				SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));

				SELECT         						
				COUNT(*) INTO v_Count
				FROM        tblterminaltype a
				WHERE a.Description = @Description;
				
		ELSEIF (p_SearchBy = 'Terminal Model')
		THEN	
				SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));

				SELECT         						
				COUNT(*) INTO v_Count
				FROM        tblterminalmodel a
				WHERE a.Description = @Description;
				
		ELSEIF (p_SearchBy = 'Terminal Brand')
		THEN	
				SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));

				SELECT         						
				COUNT(*) INTO v_Count
				FROM        tblterminalbrand a
				WHERE a.Description = @Description;
				
		ELSEIF (p_SearchBy = 'Asset Type')
		THEN											
				SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

				SELECT 
				COUNT(*) INTO v_Count
				FROM tbltype a
				WHERE a.Description = @Description AND a.Type = 5;
				
		ELSEIF (p_SearchBy = 'Request Type')
		THEN											
				SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

				SELECT 
				COUNT(*) INTO v_Count
				FROM tbltype a
				WHERE a.Description = @Description AND a.Type = 2;
				
		ELSEIF (p_SearchBy = 'Zoning Matching')
		THEN
				SET @Address = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
				SET @Area = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
				SET @CityMunicipal = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
				
				SET @search = CONCAT(@Address, ',', @CityMunicipal);				
				SET @ZoneID = COALESCE(funcGetZoneID(@search),0);
				
				IF (@ZoneID > 0)					
				THEN
					SET v_Count = 1;
				ELSE
					SET v_Count = 0;
				END IF;	
				
		ELSEIF (p_SearchBy = 'Zoning CityMunicipal')
		THEN			
				SET @CityMunicipal = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
				
				SELECT 
				COUNT(*) INTO v_Count
				FROM tblzoning a
				WHERE a.CityMunicipal = @CityMunicipal;
				
		ELSEIF (p_SearchBy = 'Zoning Alias')
		THEN
			    SET @AliasName = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
			    SET @OfficialName = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));

			    SELECT COUNT(*) INTO v_Count
			    FROM tblzoningalias a
			    WHERE a.AliasName = @AliasName
			      AND a.OfficialName = @OfficialName;
			      
		/*terminal import - raiden -- newly changed*/
		ELSEIF (p_SearchBy = 'TerminalID Active Installed')
		THEN
		    SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);

		    SELECT COUNT(*)
		    INTO v_Count
		    FROM (
			SELECT
			    CASE
				WHEN (
				    svc.ReplaceTerminalID = v_ID
				    AND svc.ReplaceTerminalID > 0
				    AND svc.JobType = 7
				    AND svc.ServiceStatus = 7
				)
				THEN 1

				WHEN (
				    svc.TerminalID = v_ID
				    AND svc.JobType IN (1, 3, 6)
				    AND svc.ServiceStatus = 7
				)
				THEN 1

				ELSE 0
			    END AS IsInstalled
			FROM tblfsrdetail fsr
			INNER JOIN tblservicingdetail svc
			  ON svc.ServiceNo = fsr.ServiceNo
			 AND svc.IRIDNo = fsr.IRIDNo
			 AND svc.JobType = fsr.JobType
			WHERE svc.JobTypeStatusDescription = 'COMPLETED'
			  AND svc.isActive > 0
			  AND svc.isCancelled = 0
			  AND fsr.FSRStatus = 1
			  AND fsr.isActive > 0
			  AND fsr.isCancelled = 0
			  AND fsr.ActionMade = 'SUCCESS'
			  AND (
				(
				    svc.TerminalID = v_ID
				    AND svc.JobType IN (1, 3, 4, 6)
				)
				OR
				(
				    svc.ReplaceTerminalID = v_ID
				    AND svc.ReplaceTerminalID > 0
				    AND svc.JobType = 7
				)
				OR
				(
				    svc.TerminalID = v_ID
				    AND svc.ReplaceTerminalID > 0
				    AND svc.ReplaceTerminalID <> svc.TerminalID
				    AND svc.JobType = 7
				)
			  )
			ORDER BY fsr.FSRNo DESC
			LIMIT 1
		    ) last_terminal_event
		    WHERE last_terminal_event.IsInstalled = 1;
	    
		ELSEIF (p_SearchBy = 'TerminalID Dispatch Available')
		THEN
		    SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);

		    SELECT COUNT(*)
		    INTO v_Count
		    FROM (
			SELECT svc.ServiceNo
			FROM tblservicingdetail svc
			WHERE svc.TerminalID = v_ID
			  AND svc.ServiceStatus = 8
			  AND svc.JobTypeStatusDescription = 'PROCESSING'
			  AND svc.isActive > 0
			  AND svc.isCancelled = 0

			UNION

			SELECT svc.ServiceNo
			FROM tblservicingdetail svc
			WHERE svc.ReplaceTerminalID = v_ID
			  AND svc.ReplaceTerminalID > 0
			  AND svc.ServiceStatus = 8
			  AND svc.JobTypeStatusDescription = 'PROCESSING'
			  AND svc.isActive > 0
			  AND svc.isCancelled = 0
		    ) active_dispatch;
		    
		/*sim import - raiden -- newly changed*/
		ELSEIF (p_SearchBy = 'SIMID Active Installed')
		THEN
		    SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);

		    SELECT COUNT(*)
		    INTO v_Count
		    FROM (
			SELECT
			    CASE
				WHEN (
					(
					    ir.IRActive > 0
					    AND ir.SIMID = v_ID
					    AND svc.SIMID = v_ID
					    AND svc.JobType IN (1, 3, 6)
					    AND svc.ServiceStatus = 7
					)
					OR
					(
					    svc.ReplaceSIMID = v_ID
					    AND svc.ReplaceSIMID > 0
					    AND svc.JobType = 7
					    AND svc.ServiceStatus = 7
					)
				     )
				THEN 1
				ELSE 0
			    END AS IsInstalled
			FROM tblfsrdetail fsr
			JOIN tblservicingdetail svc
			  ON svc.ServiceNo = fsr.ServiceNo
			 AND svc.IRIDNo = fsr.IRIDNo
			 AND svc.JobType = fsr.JobType
			LEFT JOIN tblirdetail ir
			  ON ir.IRIDNo = fsr.IRIDNo
			WHERE svc.JobTypeStatusDescription = 'COMPLETED'
			  AND svc.isActive > 0
			  AND svc.isCancelled = 0
			  AND fsr.FSRStatus = 1
			  AND fsr.isActive > 0
			  AND fsr.isCancelled = 0
			  AND fsr.ActionMade = 'SUCCESS'
			  AND (
				(
				    ir.IRActive > 0
				    AND svc.SIMID = v_ID
				    AND svc.JobType IN (1, 3, 6)
				    AND svc.ServiceStatus = 7
				)
				OR
				(
				    svc.ReplaceSIMID = v_ID
				    AND svc.ReplaceSIMID > 0
				    AND svc.JobType = 7
				    AND svc.ServiceStatus = 7
				)
				OR
				(
				    svc.SIMID = v_ID
				    AND svc.JobType = 4
				    AND svc.ServiceStatus = 11
				)
				OR
				(
				    svc.SIMID = v_ID
				    AND svc.ReplaceSIMID > 0
				    AND svc.ReplaceSIMID <> svc.SIMID
				    AND svc.JobType = 7
				    AND svc.ServiceStatus = 7
				)
			  )
			ORDER BY fsr.FSRNo DESC
			LIMIT 1
		    ) last_sim_event
		    WHERE last_sim_event.IsInstalled = 1;
		
		ELSEIF (p_SearchBy = 'SIMID Dispatch Available')
		THEN
		    SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1))AS UNSIGNED INTEGER);

		    SELECT COUNT(*) INTO v_Count
		    FROM (
			SELECT svc.ServiceNo
			FROM tblservicingdetail svc
			WHERE svc.SIMID = v_ID
			  AND svc.JobType = 1
			  AND svc.ServiceStatus = 8
			  AND svc.ServiceStatusDescription = 'DISPATCH'
			  AND svc.JobTypeStatusDescription IN ('PENDING', 'PROCESSING')
			  AND svc.isActive > 0
			  AND svc.isCancelled = 0

			UNION ALL

			SELECT svc.ServiceNo
			FROM tblservicingdetail svc
			WHERE svc.ReplaceSIMID = v_ID
			  AND svc.ReplaceSIMID > 0
			  AND svc.JobType = 7
			  AND svc.ServiceStatus = 8
			  AND svc.ServiceStatusDescription = 'DISPATCH'
			  AND svc.JobTypeStatusDescription IN ('PENDING', 'PROCESSING')
			  AND svc.isActive > 0
			  AND svc.isCancelled = 0
		    ) active_dispatch;
		    
		ELSEIF (p_SearchBy = 'Merchant IR Status')
		THEN
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1))AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2))AS UNSIGNED INTEGER);
			
			SELECT COUNT(*) INTO v_Count
			FROM
			tblservicingdetail svc
			WHERE svc.IRIDNo = v_IRIDNo
			      AND svc.JobType = v_JobType
			      AND svc.ServiceStatus = 8
			      AND svc.ServiceStatusDescription = 'DISPATCH'
			      AND svc.JobTypeStatusDescription IN ('PENDING', 'PROCESSING')
			      AND svc.isActive > 0
			      AND svc.isCancelled = 0;
		
        ELSEIF (p_SearchBy = 'Service ExpenseID Check')
        THEN
            SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
            SET @ExpenseID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);

            SELECT COUNT(*)
            INTO v_Count
            FROM tblexpensestransdetail
            WHERE ServiceNo = v_ServiceNo
              AND ExpensesID = @ExpenseID;
		
		END IF;

    END IF;

    

#SELECT(CONCAT('v_Count=',v_Count));

	

IF (v_Count > 0)

THEN

	SET p_outCount = v_Count;

ELSE

	SET p_outCount = 0;

END IF;

    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckSerialNo` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckSerialNo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckSerialNo`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */ ,

    OUT p_outCount INTEGER

)
BEGIN

	DECLARE v_Count INT;

    

	IF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'SerialNo')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   						

                        COUNT(*) INTO v_Count

			FROM        tblmasterfile

			WHERE       (SerialNo LIKE p_SearchValue);										

		 END IF;

         

	END IF;

    

    SET p_outCount = v_Count;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCheckUpdateFSRDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckUpdateFSRDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckUpdateFSRDetail`(  

	p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

				

	DECLARE var_sql_statement VARCHAR(1000);

	DECLARE v_finished INT DEFAULT 0;

	DECLARE v_ID INT;

	DECLARE v_FSRStatus INT;    

	DECLARE C1 CURSOR FOR			

			

	SELECT CONCAT("UPDATE tblfsrdetail SET TAIDNo=", xTable.xTAIDNo, ",", 

	"ClientID=", xTable.xClientID, ",", 

	"ClientName=", "'", xTable.xClientName, "'", ",", 

	"IRNo=", "'", xTable.xIRNo, "'", ",",

	"FSRStatus=", "1", ",",

	"FSRStatusDescription=", "'VALID FSR'", ",",

	"ServiceStatus=", xTable.xServiceStatus, ",",

	"ServiceStatusDescription=", "'", xTable.xServiceStatusDescription, "'", ",", 

	"ProcessType=", "'AUTO'", 

	" WHERE FSRNo=", xTable.xFSRNo, ";") AS exec_sql  

	FROM

	(SELECT b.TAIDNo AS xTAIDNo, a.FSRNo  AS xFSRNo, b.IRNo AS xIRNo, c.ClientID AS xClientID, c.ClientName AS xClientName, 

	d.ServiceStatus AS xServiceStatus, d.ServiceStatusDescription AS xServiceStatusDescription

	FROM 

	tblfsrdetail AS a

	LEFT JOIN tblterminalallocation AS b ON a.TerminalSN = b.TerminalSN AND a.TID = b.TID AND a.MID = b.MID

	LEFT JOIN tblirdetail AS c ON b.ClientID = c.ClientID

	LEFT JOIN tblservicetype AS d ON a.FSR = d.Code

	WHERE (a.TerminalSN = b.TerminalSN AND a.TID = b.TID AND a.MID = b.MID AND IFNULL(a.TAIDNo, 0) = 0)

	GROUP BY a.TerminalSN, a.TID, b.MID) AS xTable;

	DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

	IF (p_StatementType = 'Search')

	THEN

		IF (p_SearchBy = 'Update')

		THEN

			OPEN C1;

			GET_RECORD: LOOP

				FETCH C1 INTO var_sql_statement;                

				SELECT (CONCAT('var_sql_statement', var_sql_statement));                

				SET @QUERY = var_sql_statement;					                

				IF (v_finished = 1)

				THEN

					LEAVE GET_RECORD;

				END IF;

				# Execute Query (Delete)

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

		

			END LOOP GET_RECORD;

			CLOSE C1;

		END IF;     

	END IF;    

END */$$
DELIMITER ;

