/* Procedure structure for procedure `spCheckVoidSalesERM` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCheckVoidSalesERM` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCheckVoidSalesERM`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE var_sql_statement VARCHAR(1000);

	DECLARE v_finished INT DEFAULT 0;

    DECLARE v_ID INT;    

    DECLARE v_SystemDate DATE;

	DECLARE v_SystemTime TIME;

	DECLARE sQuery VARCHAR(1000);

	

    DECLARE C1 CURSOR FOR   

	SELECT CONCAT("DELETE FROM tblermdetailtemp WHERE AuthCode=", "'", temp.AuthCode, "'",  

	                                                " AND RefNo=", "'", temp.RefNo, "'", 

	                                                " AND TxnAmt=", "'", temp.TxnAmt, "'",

	                                                " AND BatchNo=", "'", temp.BatchNo, "'",

	                                                " AND InvoiceNo=", "'", temp.InvoiceNo, "'",

	                                                " AND TID=", "'", temp.TID, "'",

	                                                " AND `MID`=", "'", temp.`MID`, "'", 

	                                                ";") AS exec_sql FROM	

	(SELECT u.TxnType, u.FSRNo, u.TID, u.`MID`, u.BatchNo, u.InvoiceNo, u.AuthCode, u.RefNo, u.TxnAmt

	FROM tblermdetailtemp AS u 

	WHERE TxnType = 'VOID SALES'

	GROUP BY u.FSRNo) temp;

            

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

    

    SET v_SystemDate = CURDATE();

    SET v_SystemTime = CURTIME();

    

    #SET max_sp_recursion_depth=255;

    IF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Duplicate')

		THEN

			OPEN C1;

			SET var_sql_statement = "";

			

			GET_RECORD: LOOP

			FETCH C1 INTO var_sql_statement;                

			#SELECT (CONCAT('var_sql_statement=>', var_sql_statement));                

			

			IF (LENGTH(var_sql_statement) <= 0) THEN

				SET v_finished = 1;

			ELSE

				SET @QUERY = var_sql_statement;

			END IF;

				

			IF (v_finished = 1)

			THEN

				LEAVE GET_RECORD;

			END IF;

			# Execute Query (Delete)

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

			# Save Duplicate as repository

			SET sQuery = "";

			SET sQuery = CONCAT("(", "'", var_sql_statement, "',", "'", 'Void Sales', "',", "'", v_SystemDate, "',", "'", v_SystemTime, "'", ")");				

			CALL spInsertCollectionDetail("Insert", "", "","Duplicate Detail", sQuery, @p_outErrorMessage, @p_outLastInsertID);

			END LOOP GET_RECORD;

			CLOSE C1;

			

		END IF;				  

    END IF;

    

     

END */$$
DELIMITER ;

