/* Procedure structure for procedure `spCleanupLocationLogs` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCleanupLocationLogs` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCleanupLocationLogs`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE vUserID INT;
    DECLARE vParticularID INT;
    DECLARE vParamString VARCHAR(50);

    DECLARE cur CURSOR FOR
        SELECT UserID, ParticularID
        FROM tbllogservicelocation
        GROUP BY UserID, ParticularID;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO vUserID, vParticularID;
        IF done THEN
            LEAVE read_loop;
        END IF;

        SET vParamString = CONCAT(vUserID, '|', vParticularID);

        CALL spDeleteCollectionDetail('Delete', '', vParamString, 'Log Service Location');
    END LOOP;

    CLOSE cur;
END */$$
DELIMITER ;

/* Procedure structure for procedure `spClientInsertUpdate` */

