/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spClientInsertUpdate`(  

p_ClientID INTEGER,  

p_Name VARCHAR(100),

p_Address VARCHAR(100),

p_CityID INT,

p_City VARCHAR(100),

p_ContactPerson VARCHAR(100),

p_ContactNo VARCHAR(100),

p_StatementType NVARCHAR(20) /* = NULL */

