 IF p_StatementType = 'Update'  

	THEN      

		UPDATE tblclient SET  

					   ClientID = p_ClientID, 

                       NAME = p_Name, 

                       Address = p_Address, 

                       CityID = p_CityID,

                       City = p_City,  

                       ContactPerson = p_ContactPerson, 

                       ContactNo = p_ContactNo                       

		WHERE ClientID = p_ClientID;  

	END IF;  

END */$$
