/* Procedure structure for procedure `spCreateTemporaryTable` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCreateTemporaryTable` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCreateTemporaryTable`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

    IN p_SearchBy VARCHAR(30) /* = NULL */ ,

    IN p_SearchValue VARCHAR(30) /* = NULL */

)
BEGIN    	

DECLARE p_WHERE LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

DECLARE p_TempQuery LONGTEXT;

DECLARE p_INSERT LONGTEXT;



	IF (p_StatementType = 'Create')

	THEN		

		IF (p_SearchBy = 'Servicing Temp Detail')

		THEN

		

			DROP TEMPORARY TABLE tblservicingdetailtemp;

			

			SET p_TempQuery = '';

			SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE `tblservicingdetailtemp` (

						  `IDNo` int(11) NOT NULL AUTO_INCREMENT,

						  `ServiceNo` int(11) DEFAULT NULL,

						  `TAIDNo` int(11) DEFAULT NULL,

						  `IRIDNo` int(11) DEFAULT NULL,

						  `IRNo` varchar(45) DEFAULT NULL,

						  `TerminalID` int(11) DEFAULT NULL,

						  `TerminalSN` varchar(45) DEFAULT NULL,

						  `TerminalStatusDescription` varchar(45) DEFAULT NULL,

						  `Type` varchar(45) DEFAULT NULL,

						  `Model` varchar(45) DEFAULT NULL,

						  `Brand` varchar(45) DEFAULT NULL,

						  `IRDate` varchar(45) DEFAULT NULL,

						  `InstallationDate` varchar(45) DEFAULT NULL,

						  `MerchantName` varchar(45) DEFAULT NULL,

						  `TID` varchar(45) DEFAULT NULL,

						  `MID` varchar(45) DEFAULT NULL,

						  `Region` varchar(45) DEFAULT NULL,

						  `Province` varchar(45) DEFAULT NULL,

						  `IRStatusDescription` varchar(45) DEFAULT NULL,

						  `ServiceDateTime` varchar(45) DEFAULT NULL,

						  `ServiceReqDate` varchar(45) DEFAULT NULL,

						  `ServiceReqTime` varchar(45) DEFAULT NULL,

						  `RequestNo` varchar(45) DEFAULT NULL,

						  `ReferenceNo` varchar(45) DEFAULT NULL,

						  `CustomerName` varchar(45) DEFAULT NULL,

						  `CustomerContactNo` varchar(45) DEFAULT NULL,

						  `ClientName` varchar(45) DEFAULT NULL,

						  `FEName` varchar(45) DEFAULT NULL,

						  `TerminalSNTemp` varchar(45) DEFAULT NULL,

						  `SIMSN` varchar(45) DEFAULT NULL,

						  `SIMCarrier` varchar(45) DEFAULT NULL,

						  `DockSN` varchar(45) DEFAULT NULL,

						  `ReplaceTerminalSN` varchar(45) DEFAULT NULL,

						  `ReplaceSIMSN` varchar(45) DEFAULT NULL,

						  `ReplaceDockSN` varchar(45) DEFAULT NULL,

						  `JobTypeDescription` varchar(45) DEFAULT NULL,

						  `JobTypeStatusDescription` varchar(45) DEFAULT NULL,

						  `ActionMade` varchar(45) DEFAULT NULL,

						  `FSRDate` varchar(45) DEFAULT NULL,

						  `FSRTime` varchar(45) DEFAULT NULL,

						  `TimeArrived` varchar(45) DEFAULT NULL,

						  `TimeStart` varchar(45) DEFAULT NULL,

						  `TimeEnd` varchar(45) DEFAULT NULL,

						  `Remarks` varchar(1000) DEFAULT NULL,

						  `ProblemReported` varchar(1000) DEFAULT NULL,

						  `ActualProblemReported` varchar(1000) DEFAULT NULL,

						  `ActionTaken` varchar(1000) DEFAULT NULL,

						  `AnyComments` varchar(1000) DEFAULT NULL,

						  `MerchantRepresentative` varchar(200) DEFAULT NULL,

						  `MerchantContactNo` varchar(200) DEFAULT NULL,

						  PRIMARY KEY (`IDNo`),

						  KEY `TAIDNo` (`TAIDNo`),

						  KEY `IRIDNo` (`IRIDNo`),

						  KEY `TerminalID` (`TerminalID`)

						) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;');

			SET @QUERY = p_TempQuery;

			

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'IR Pending Temp Detail')

		THEN	

			DROP TEMPORARY TABLE tblirdetailtemp;

			

			SET p_TempQuery = '';

			SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE `tblirdetailtemp` (

						  `IDNo` int(11) NOT NULL AUTO_INCREMENT,						  

						  `IRNo` varchar(45) DEFAULT NULL,

						  `InstallationDate` varchar(45) DEFAULT NULL,

						  `iSubDate` varchar(45) DEFAULT NULL

						  PRIMARY KEY (`IDNo`)						  

						) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;');

			SET @QUERY = p_TempQuery;

			

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'ERM Temp Detail Type')

		THEN	

			DROP TABLE tblermdetailtype;

			

			SET p_TempQuery = '';

			SET p_TempQuery = CONCAT('CREATE TABLE `tblermdetailtype` (

						  `FSRNo` int(11) NOT NULL,						  

						  `Merchant` varchar(255) DEFAULT NULL

						  PRIMARY KEY (`FSRNo`)						  

						) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=latin1;');

			SET @QUERY = p_TempQuery;

			

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	
			
		elseIF (p_SearchBy = 'Report Data Storage') 
		THEN
		
			DROP TABLE IF EXISTS `tbltempreportdatastorage`;
			
			SET p_TempQuery = '';
			SET p_TempQuery = CONCAT("CREATE TABLE `tbltempreportdatastorage` (
				  `ID` int(11) NOT NULL AUTO_INCREMENT,
				  `StorageType` int(2) DEFAULT '0',
				  `Title` varchar(255) DEFAULT '0',
				  `Description` varchar(255) DEFAULT '0',
				  `January` varchar(45) DEFAULT '0',
				  `February` varchar(45) DEFAULT '0',
				  `March` varchar(45) DEFAULT '0',
				  `April` varchar(45) DEFAULT '0',
				  `May` varchar(45) DEFAULT '0',
				  `June` varchar(45) DEFAULT '0',
				  `July` varchar(45) DEFAULT '0',
				  `August` varchar(45) DEFAULT '0',
				  `September` varchar(45) DEFAULT '0',
				  `October` varchar(45) DEFAULT '0',
				  `November` varchar(45) DEFAULT '0',
				  `December` varchar(45) DEFAULT '0',
				  `TCount` int(11) DEFAULT '0',
				  `TTotal` int(11) DEFAULT '0',
				  `isActive` tinyint(1) DEFAULT '1',
				  PRIMARY KEY (`ID`),
				  KEY `StorageType` (`StorageType`)
				) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb3;");
				
			SET @QUERY = p_TempQuery;

			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;	

		END IF;

	END IF;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spCreateTempTable` */

/*!50003 DROP PROCEDURE IF EXISTS  `spCreateTempTable` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spCreateTempTable`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_TableName VARCHAR(50) /* = NULL */

)
BEGIN    

	DECLARE p_TempQuery LONGTEXT;

		

	IF (p_StatementType = 'Create')

	THEN		

			IF (p_TableName = 'ERM Temp Detail Type')

			THEN	
				DROP TABLE IF EXISTS tblermdetailtype;
				

				SET p_TempQuery = '';

				SET p_TempQuery = CONCAT('CREATE TABLE `tblermdetailtype` (

						  `FSRNo` int(11),

						  `No` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `Merchant` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `MID` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `TID` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `InvoiceNo` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `BatchNo` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `PAN` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `FSRDate` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `FSRTime` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `TxnType` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `TxnAmt` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `AuthCode` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `RefNo` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `PhoneNo` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `Email` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `NRIC` varchar(255) CHARACTER SET latin1 DEFAULT NULL,

						  `AddInfo` varchar(255) CHARACTER SET latin1 DEFAULT NULL,
						  
						  KEY (`FSRNo`),
						  KEY `idx_MID` (`MID`),
						  KEY `idx_TID` (`TID`),
						  KEY `idx_BatchNo` (`BatchNo`),
						  KEY `idx_Invoice` (`InvoiceNo`),
						  KEY `idx_AuthCode` (`AuthCode`),
						  KEY `idx_RefNo` (`RefNo`)						  

						) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

						;');

									

				SET @QUERY = p_TempQuery;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;	

				

			ELSEIF (p_TableName = 'TimeSheet Temp Detail')

			THEN	

				DROP TABLE IF EXISTS tbltimesheetdetailtemp;
				
				SET p_TempQuery = '';

				SET p_TempQuery = CONCAT("CREATE TABLE `tbltimesheetdetailtemp` (

						  `TSID` int(11) NOT NULL AUTO_INCREMENT,

						  `TimeSheetDate` date DEFAULT NULL,

						  `TimeSheetID` int(11) DEFAULT '0',

						  `ParticularID` int(11) DEFAULT '0',

						  `WorkTypeID` int(11) DEFAULT '0',

						  `LeaveTypeID` int(11) DEFAULT '0',

						  `DepartmentID` int(11) DEFAULT '0',

						  `Department` varchar(40) DEFAULT NULL,						  

						  `PositionID` int(11) DEFAULT '0',

						  `FullName` varchar(100) DEFAULT NULL,

						  `TerminalID` varchar(10) DEFAULT '0',

						  `TSDate` date DEFAULT NULL,

						  `TimeIn` time DEFAULT NULL,

						  `TimeOut` time DEFAULT NULL,

						  `THours` varchar(20) DEFAULT NULL,

						  `TTime` int(11) DEFAULT '0',

						  `TimeStatus` varchar(45) DEFAULT NULL,

						  `Holiday` varchar(45) DEFAULT NULL,

						  `WorkType` varchar(45) DEFAULT NULL,

						  `LeaveType` varchar(45) DEFAULT NULL,

						  `DeviceIn` varchar(45) DEFAULT NULL,

						  `DeviceOut` varchar(45) DEFAULT NULL,						  

						  `ProcessedBy` varchar(45) DEFAULT NULL,

						  `ProcessedDateTime` varchar(45) DEFAULT NULL,

						  `ModifiedBy` varchar(45) DEFAULT NULL,

						  `ModifiedDateTime` varchar(45) DEFAULT NULL,

						  `TSTerminalIDList` varchar(45) DEFAULT NULL,	

						  `CountryID` int(11) DEFAULT '0',

						  `Country` varchar(45) DEFAULT NULL,						 

						  PRIMARY KEY (`TSID`,`TimeSheetID`,`ParticularID`,`WorkTypeID`,`LeaveTypeID`,`DepartmentID`,`PositionID`,`TerminalID`),
						  KEY `TSID` (`TSID`),
						  KEY `TimeSheetID` (`TimeSheetID`),
						  KEY `ParticularID` (`ParticularID`),
						  KEY `WorkTypeID` (`WorkTypeID`),
						  KEY `LeaveTypeID` (`LeaveTypeID`),
						  KEY `DepartmentID` (`DepartmentID`),
						  KEY `PositionID` (`PositionID`),
						  KEY `TerminalID` (`TerminalID`)

						) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

						;");

								

				SET @QUERY = p_TempQuery;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

				

			ELSEIF (p_TableName = 'FSR Client Temp')

			THEN	

				DROP TABLE IF EXISTS tblfsrclient;
				
				SET p_TempQuery = '';

				SET p_TempQuery = CONCAT("CREATE TABLE `tblfsrclient` (

							`FSRNo` int(11) DEFAULT '0',

							`IRIDNo` int(11) DEFAULT '0',

							`ClientID` int(11) DEFAULT '0',

							`MerchantID` int(11) DEFAULT '0',

							`ServiceNo` int(11) DEFAULT '0',

							`JobType` int(11) DEFAULT '0',					 

							`JobTypeDescription` varchar(45) DEFAULT NULL,

							`ServiceStatus` int(11) DEFAULT '0',

							`ServiceStatusDescription` varchar(45) DEFAULT NULL,

							`ActionMade` varchar(45) DEFAULT NULL,

							`FSRDate` varchar(45) DEFAULT NULL,

							`TerminalSN` varchar(45) DEFAULT NULL,

							`SIMSN` varchar(45) DEFAULT NULL,

							`IRStatus` int(11) DEFAULT '0',

							`RegionType` int(11) DEFAULT '0',

							`RegionID` int(11) DEFAULT '0',

							`Attempt` int(11) DEFAULT '0',

							`IncludeBillable` varchar(45) DEFAULT NULL,

							`MobileID` int(11) DEFAULT '0',	

							`MobileTerminalID` varchar(45) DEFAULT NULL								  

							) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

							;");							

				

				SET @QUERY = p_TempQuery;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

				

			ELSEIF (p_TableName = 'Terminal Summary')

			THEN	

				DROP TABLE IF EXISTS tblterminalsummary;
				
				SET p_TempQuery = '';

				SET p_TempQuery = CONCAT("CREATE TABLE `tblterminalsummary` (

							`LocationID` int(11) DEFAULT '0',

							`Location` varchar(45) DEFAULT NULL,

							`TerminalTypeID` int(11) DEFAULT '0',

							`TerminalType` varchar(45) DEFAULT NULL,

							`TerminalModelID` int(11) DEFAULT '0',

							`TerminalModel` varchar(45) DEFAULT NULL,

							`TAvailable` int(11) DEFAULT '0',

							`TInstalled` int(11) DEFAULT '0',

							`TAllocated` int(11) DEFAULT '0',

							`TDispatch` int(11) DEFAULT '0',

							`TPullout` int(11) DEFAULT '0',

							`TBorrow` int(11) DEFAULT '0',

							`TLost` int(11) DEFAULT '0',

							`TDefective` int(11) DEFAULT '0',

							`TTotal` int(11) DEFAULT '0'								  

							) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

							;");							

				

				SET @QUERY = p_TempQuery;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

				

			ELSEIF (p_TableName = 'SIM Summary')

			THEN	

				DROP TABLE IF EXISTS tblsimsummary;

				SET p_TempQuery = '';

				SET p_TempQuery = CONCAT("CREATE TABLE `tblsimsummary` (

							`LocationID` int(11) DEFAULT '0',

							`Location` varchar(45) DEFAULT NULL,

							`TypeID` int(11) DEFAULT '0',

							`Carrier` varchar(45) DEFAULT NULL,

							`TAvailable` int(11) DEFAULT '0',

							`TInstalled` int(11) DEFAULT '0',

							`TAllocated` int(11) DEFAULT '0',

							`TDispatch` int(11) DEFAULT '0',

							`TPullout` int(11) DEFAULT '0',

							`TBorrow` int(11) DEFAULT '0',

							`TLost` int(11) DEFAULT '0',

							`TDefective` int(11) DEFAULT '0',

							`TTotal` int(11) DEFAULT '0'									  

							) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

							;");							

				

				SET @QUERY = p_TempQuery;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;	

				

			ELSEIF (p_TableName = 'Installation Request Summary')

			THEN	

				DROP TABLE IF EXISTS tblinstallationsummary;
				
				SET p_TempQuery = '';

				SET p_TempQuery = CONCAT("CREATE TABLE `tblinstallationsummary` (

							`RegionType` int(11) DEFAULT '0',

							`Region` varchar(45) DEFAULT NULL,

							`RegionID` int(11) DEFAULT '0',							

							`TerminalTypeID` int(11) DEFAULT '0',

							`TerminalType` varchar(45) DEFAULT NULL,

							`TerminalModelID` int(11) DEFAULT '0',

							`TerminalModel` varchar(45) DEFAULT NULL,

							`JobType` int(11) DEFAULT '0',

							`jobTypeDescription` varchar(45) DEFAULT NULL,

							`TSuccess` int(11) DEFAULT '0',

							`TNegative` int(11) DEFAULT '0',

							`TTotal` int(11) DEFAULT '0'								  

							) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

							;");							

				

				SET @QUERY = p_TempQuery;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;		
				
			ELSEIF (p_TableName = 'Daily Report-Installation')
			THEN			
				DROP TABLE IF EXISTS tbltemp_installation;				
				SET p_TempQuery = '';
				SET p_TempQuery = CONCAT("CREATE TABLE `tbltemp_installation` (
							`IRIDNo` int(11) DEFAULT '0',
							`MerchantID` int(11) DEFAULT '0',
							`RegionType` int(11) DEFAULT '0',
							`RequestDate` date DEFAULT NULL,	
							`IRNo` varchar(45) DEFAULT NULL,						
							`TID` varchar(45) DEFAULT NULL,
							`MID` varchar(45) DEFAULT NULL,
							`RequestTypeID` int(11) DEFAULT '0',
							`Status` int(11) DEFAULT '0',	
							`isActive` int(11) DEFAULT '0'							  
							) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

							;");							

				SET @QUERY = p_TempQuery;				

				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;	

			ELSE			

				/* Drop table when exist */

				SET @sql = CONCAT('DROP TABLE IF EXISTS ', p_TableName);            

				PREPARE s FROM @sql;

				EXECUTE s;

				DEALLOCATE PREPARE s;

		    

				/* Create Table*/

				SET @sql = CONCAT('CREATE TABLE ', p_TableName,' LIKE  tablename_template$');            

				PREPARE s FROM @sql;

				EXECUTE s;

				DEALLOCATE PREPARE s;



			END IF;				          

	END IF;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spDashboardClient` */

/*!50003 DROP PROCEDURE IF EXISTS  `spDashboardClient` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spDashboardClient`(  

	IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(255) /* = NULL */

)
BEGIN    

    DECLARE var_sql_statement VARCHAR(1000);

    DECLARE v_finished INT DEFAULT 0;

    DECLARE v_ParticularID INT;

    DECLARE v_Name VARCHAR(45);

    DECLARE v_Temp VARCHAR(45);

    DECLARE v_ClientName VARCHAR(45);

    DECLARE v_ClientIDList VARCHAR(45);

    DECLARE v_ClientKey VARCHAR(45);

    DECLARE p_outCount INT;

    

    DECLARE p_TAvailable INT;

    DECLARE p_TAllocated INT;

    DECLARE p_TDispatch INT;

    DECLARE p_TInstalled INT;

    DECLARE p_TWithinTAT INT;

    DECLARE p_TBeyondTAT INT;

    DECLARE p_TNegative INT;

    DECLARE p_TLastMonthInstalled INT;

    DECLARE p_TThisMonthInstalled INT;

     

    DECLARE C1 CURSOR FOR

    		

			SELECT

			IFNULL(a.ParticularID, 0) AS ParticularID,

			IFNULL(a.Name, "-") AS ClientName

			FROM 

			tblparticular a

			WHERE a.isActive > 0 AND a.ParticularTypeID = 2 AND (IF((p_SearchValue = "CASTLES" || p_SearchValue = "CITAS"), (a.Name IN ('METROBANK', 'BDO CLG', 'WEEPAY')), (a.Name IN (p_SearchValue))))

			ORDER BY a.Name;			

            

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

        

    IF (p_StatementType = 'Search')

    THEN

			# Clear table data

			DELETE FROM tbldashboardclient; 

			

			#Client

			#SET v_ClientName = p_SearchValue;

			SET v_ClientIDList = p_SearchValue;

			#SELECT CONCAT("v_ClientIDList=", v_ClientIDList) AS x_ClientIDList;

				

			OPEN C1;

			GET_RECORD: LOOP

				FETCH C1 INTO v_ParticularID, v_Name;                

				

				#SELECT CONCAT("v_ParticularID=", v_ParticularID) AS x_ParticularID;

				#SELECT CONCAT("v_Name=", v_Name) as x_Name;

				

				# Count Available

				SET v_Temp = CONCAT(v_ParticularID, '|', 'AVAILABLE');

				CALL spViewCount('Search', 'Client Status Count', v_Temp, @p_outCount);

				SET p_TAvailable = @p_outCount;

				

				# Count Allocated

				SET v_Temp = CONCAT(v_ParticularID, '|', 'ALLOCATED');

				CALL spViewCount('Search', 'Client Status Count', v_Temp, @p_outCount);

				SET p_TAllocated = @p_outCount;

				

				# Count Dispatch

				SET v_Temp = CONCAT(v_ParticularID, '|', 'DISPATCH');

				CALL spViewCount('Search', 'Client Status Count', v_Temp, @p_outCount);

				SET p_TDispatch = @p_outCount;

				

				# Count Installed

				SET v_Temp = CONCAT(v_ParticularID, '|', 'INSTALLED');

				CALL spViewCount('Search', 'Client Status Count', v_Temp, @p_outCount);

				SET p_TInstalled = @p_outCount;

				

				# Count Negative

				SET v_Temp = CONCAT(v_ParticularID, '|', 'NEGATIVE');

				CALL spViewCount('Search', 'Client Status Count', v_Temp, @p_outCount);

				SET p_TNegative = @p_outCount;

				

				# Count Last Month

				SET v_Temp = CONCAT(v_ParticularID, '|', 'INSTALLED');

				CALL spViewCount('Search', 'Client Last Month Count', v_Temp, @p_outCount);

				SET p_TLastMonthInstalled = @p_outCount;

				

				# Count This Month

				SET v_Temp = CONCAT(v_ParticularID, '|', 'INSTALLED');

				CALL spViewCount('Search', 'Client This Month Count', v_Temp, @p_outCount);

				SET p_TThisMonthInstalled = @p_outCount;

				

				# Insert record to tbldashboardregion

				SET @QUERY = CONCAT('INSERT INTO tbldashboardclient (ParticularID, Name, TAvailable, TAllocated, TDispatch, TInstalled, TNegative, TLastMonthInstalled, TThisMonthInstalled) VALUES(',v_ParticularID, ',', 

										     "'", v_Name, "'", ',', 

										     p_TAvailable, ',', 

										     p_TAllocated, ',', 

										     p_TDispatch, ',', 

										     p_TInstalled, ',',

										     p_TNegative, ',',

										     p_TLastMonthInstalled, ',',

										     p_TThisMonthInstalled, 

										     ')');  

				# SELECT @QUERY;

				

				# SET @QUERY = var_sql_statement;					                

				IF (v_finished = 1)

				THEN

					LEAVE GET_RECORD;

				END IF;

				# Execute Query

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;				

		

			END LOOP GET_RECORD;

			CLOSE C1;			

						  

    END IF;

    

     

END */$$
DELIMITER ;

/* Procedure structure for procedure `spDashboardRegion` */

/*!50003 DROP PROCEDURE IF EXISTS  `spDashboardRegion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spDashboardRegion`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(255) /* = NULL */

)
BEGIN    

    DECLARE var_sql_statement VARCHAR(1000);

    DECLARE v_finished INT DEFAULT 0;

    DECLARE v_RegionID INT;

    DECLARE v_ClientID INT;

    DECLARE v_Region VARCHAR(45);

    DECLARE v_ClientName VARCHAR(45);

    DECLARE v_ServiceStatus VARCHAR(45);

    DECLARE v_Temp VARCHAR(45);

    DECLARE p_outCount INT;

    

    DECLARE p_TAvailable INT;

    DECLARE p_TAllocated INT;

    DECLARE p_TDispatch INT;

    DECLARE p_TInstalled INT;

    DECLARE p_TWithinTAT INT;

    DECLARE p_TBeyondTAT INT;

    DECLARE p_TNegative INT;

    DECLARE p_TLastMonthInstalled INT;

    DECLARE p_TThisMonthInstalled INT;

        

    DECLARE C1 CURSOR FOR

			SELECT 

			IFNULL(a.RegionID, 0) AS RegionID, 

			IFNULL(a.Region, "-") AS Region

			FROM

			tblregion a

			WHERE isActive > 0

			ORDER BY a.SequenceDisplay;

            

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

        

    IF (p_StatementType = 'Search')

    THEN

			# Clear table data

			DELETE FROM tbldashboardregion; 

			

			# Client

			SET v_ClientName = '';

			IF (p_SearchValue = 'CASTLES' || p_SearchValue = 'CITAS')

			THEN

				SET v_ClientName = CONCAT("'", "METROBANK", "'", ",", "'", "BDO CLG", "'", ",", "'", "WEEPAY", "'");

			ELSE

				SET v_ClientName = CONCAT("'", p_SearchValue, "'") ;

			END IF;

			#SELECT CONCAT("v_ClientName=",v_ClientName);

				

			OPEN C1;

			GET_RECORD: LOOP

				FETCH C1 INTO v_RegionID, v_Region;                

				

				#SELECT CONCAT("v_RegionID=",v_RegionID);

				#SELECT CONCAT("v_Region=",v_Region);

				

				# Count Available				

				SET v_Temp = CONCAT(v_RegionID, '|', 'AVAILABLE', '|', v_ClientName);				

				CALL spViewCount('Search', 'Region Status Count', v_Temp, @p_outCount);

				SET p_TAvailable = @p_outCount;				

				

				# Count Allocated				

				SET v_Temp = CONCAT(v_RegionID, '|', 'ALLOCATED', '|', v_ClientName);				

				CALL spViewCount('Search', 'Region Status Count', v_Temp, @p_outCount);

				SET p_TAllocated = @p_outCount;

				

				# Count Dispatch				

				SET v_Temp = CONCAT(v_RegionID, '|', 'DISPATCH', '|', v_ClientName);				

				CALL spViewCount('Search', 'Region Status Count', v_Temp, @p_outCount);

				SET p_TDispatch = @p_outCount;

				

				# Count Installed				

				SET v_Temp = CONCAT(v_RegionID, '|', 'INSTALLED', '|', v_ClientName);				

				CALL spViewCount('Search', 'Region Status Count', v_Temp, @p_outCount);

				SET p_TInstalled = @p_outCount;

				

				# Count Negative

				SET v_Temp = CONCAT(v_RegionID, '|', 'NEGATIVE', '|', v_ClientName);				

				CALL spViewCount('Search', 'Region Status Count', v_Temp, @p_outCount);

				SET p_TNegative = @p_outCount;

				

				# Count Last Month				

				SET v_Temp = CONCAT(v_RegionID, '|', 'INSTALLED', '|', v_ClientName);				

				CALL spViewCount('Search', 'Region Last Month Count', v_Temp, @p_outCount);

				SET p_TLastMonthInstalled = @p_outCount;

				

				# Count This Month				

				SET v_Temp = CONCAT(v_RegionID, '|', 'INSTALLED', '|', v_ClientName);

				CALL spViewCount('Search', 'Region This Month Count', v_Temp, @p_outCount);

				SET p_TThisMonthInstalled = @p_outCount;

				

				# Insert record to tbldashboardregion

				SET @QUERY = CONCAT('INSERT INTO tbldashboardregion (RegionID, Region, TAvailable, TAllocated, TDispatch, TInstalled, TNegative, TLastMonthInstalled, TThisMonthInstalled) VALUES(',v_RegionID, ',', 

										     "'", v_Region, "'", ',', 

										     p_TAvailable, ',', 

										     p_TAllocated, ',', 

										     p_TDispatch, ',', 

										     p_TInstalled, ',',

										     p_TNegative, ',',

										     p_TLastMonthInstalled, ',',

										     p_TThisMonthInstalled, 

										     ')');  

				# SELECT @QUERY;

				

				# SET @QUERY = var_sql_statement;					                

				IF (v_finished = 1)

				THEN

					LEAVE GET_RECORD;

				END IF;

				# Execute Query

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;				

		

			END LOOP GET_RECORD;

			CLOSE C1;

									 

    END IF;

    

     

END */$$
DELIMITER ;

/* Procedure structure for procedure `spDashboardTerminal` */

/*!50003 DROP PROCEDURE IF EXISTS  `spDashboardTerminal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spDashboardTerminal`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(255) /* = NULL */

)
BEGIN    

    DECLARE var_sql_statement VARCHAR(1000);

    DECLARE v_finished INT DEFAULT 0;

    DECLARE v_TerminalTypeID INT;

    DECLARE v_TerminalModelID INT;

    DECLARE v_TypeDescription VARCHAR(45);

    DECLARE v_ModelDescription TEXT;

    DECLARE v_ClientName VARCHAR(45);

    

    DECLARE v_Temp VARCHAR(255);

    DECLARE p_outCount INT;

    DECLARE p_outInfo TEXT;

    

    DECLARE p_TOriginalStock INT;

    DECLARE p_TAvailableStock INT;

    DECLARE p_TInstalled INT;    

    DECLARE p_TAllocated INT;

    DECLARE p_TDispatch INT;

    DECLARE p_TRepair INT;

    DECLARE p_TLoanBorrow INT;

    DECLARE p_TDefective INT;

    DECLARE p_TWithinTAT INT;

    DECLARE p_TBeyondTAT INT;

    DECLARE p_TNegative INT;

    DECLARE p_TLastMonthInstalled INT;

    DECLARE p_TThisMonthInstalled INT;

    DECLARE v_ServiceStatusDescription VARCHAR(45);

    

    DECLARE p_ModelArray VARCHAR(1000);

    DECLARE p_Element VARCHAR(1000);

    DECLARE p_SQL LONGTEXT;

        

    DECLARE C1 CURSOR FOR

			

			SELECT

			IFNULL(a.TerminalTypeID, 0) AS TerminalTypeID,

			IFNULL(a.Description, 0) AS TypeDescription

			FROM

			tblterminaltype a

			WHERE a.Description IN('MP200', 'V3 NT', 'V3 TOUCH', 'V5S', 'V3000', 'ANDROID', 'V5000') AND (a.isActive > 0)

			ORDER BY a.Description;

            

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

    

    SET p_outCount = 0;

    SET p_TOriginalStock = 0;

    SET p_TAvailableStock = 0;

    SET p_TInstalled = 0;    

    SET p_TAllocated = 0;

    SET p_TDispatch = 0;

    SET p_TRepair = 0;

    SET p_TLoanBorrow = 0;

    SET p_TDefective = 0;

    SET p_TLastMonthInstalled = 0;

    SET p_TThisMonthInstalled = 0;

    

    IF (p_StatementType = 'View')					

    THEN

	IF (p_SearchBy = 'ServiceStatus')	

	THEN

		SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		

		IF (v_ServiceStatusDescription = 'AVAILABLE')

		THEN

			SELECT 

			IFNULL_STRING(a.IRNo) AS IRNo, 

			IFNULL_STRING(a.MerchantName) AS Merchant, 

			IFNULL_STRING(a.TID) AS TID, 

			IFNULL_STRING(a.`MID`) AS `MID`,

			IFNULL_STRING(d.Region) AS Region,

			IFNULL_STRING(c.Province) AS Province,

			"-" AS TerminalSN,

			"-" AS TypeDescription,

			"-" AS ModelDescription,

			"-" AS SIMSN,

			"-" AS Carrier

			FROM 

			tblirdetail a

			LEFT JOIN tblparticular AS b ON a.MerchantID = b.ParticularID AND b.ParticularTypeID = 1

			LEFT JOIN tblregiondetail AS c ON b.RegionID = c.RegionID

			LEFT JOIN tblregion AS d ON b.RegionType = d.RegionID	

			WHERE 

			a.IRStatusDescription = v_ServiceStatusDescription AND

			a.ClientName = v_ClientName

			ORDER BY a.MerchantName;

			

		ELSEIF (v_ServiceStatusDescription = 'LASTMONTHINSTALLED')

		THEN

			SELECT 

			IFNULL_STRING(a.IRNo) AS IRNo, 

			IFNULL_STRING(b.MerchantName) AS Merchant, 

			IFNULL_STRING(b.TID) AS TID, 

			IFNULL_STRING(b.`MID`) AS `MID`,

			IFNULL_STRING(f.Region) AS Region,

			IFNULL_STRING(e.Province) AS Province,

			IFNULL_STRING(g.SerialNo) AS TerminalSN,

			IFNULL_STRING(h.Description) AS TypeDescription,

			IFNULL_STRING(i.Code) AS ModelDescription,

			IFNULL_STRING(j.SerialNo) AS SIMSN,

			IFNULL_STRING(j.Carrier) AS Carrier

			FROM 

			tblservicingdetail a

			LEFT JOIN tblirdetail AS b ON a.IRNo = b.IRNo	

			LEFT JOIN tblfsrdetail AS c ON a.ServiceNo = c.ServiceNo				

			LEFT JOIN tblparticular AS d ON b.MerchantID = d.ParticularID AND d.ParticularTypeID = 1

			LEFT JOIN tblregiondetail AS e ON d.RegionID = e.RegionID

			LEFT JOIN tblregion AS f ON d.RegionType = f.RegionID	

			LEFT JOIN tblterminaldetail AS g ON a.TerminalID = g.TerminalID

			LEFT JOIN tblterminaltype AS h ON g.TerminalTypeID = h.TerminalTypeID

			LEFT JOIN tblterminalmodel AS i ON g.TerminalModelID = i.TerminalModelID		

			LEFT JOIN tblsimdetail AS j ON a.SIMID = j.SIMID

			

			WHERE 

			a.ActionMade = 'SUCCESS' AND

			b.ClientName = v_ClientName AND

			(LEFT(c.FSRDate, 7) = LEFT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), 7))

			ORDER BY b.MerchantName;

			

		ELSEIF (v_ServiceStatusDescription = 'THISMONTHINSTALLED')

		THEN

			SELECT 

			IFNULL_STRING(a.IRNo) AS IRNo, 

			IFNULL_STRING(b.MerchantName) AS Merchant, 

			IFNULL_STRING(b.TID) AS TID, 

			IFNULL_STRING(b.`MID`) AS `MID`,

			IFNULL_STRING(f.Region) AS Region,

			IFNULL_STRING(e.Province) AS Province,

			IFNULL_STRING(g.SerialNo) AS TerminalSN,

			IFNULL_STRING(h.Description) AS TypeDescription,

			IFNULL_STRING(i.Code) AS ModelDescription,

			IFNULL_STRING(j.SerialNo) AS SIMSN,

			IFNULL_STRING(j.Carrier) AS Carrier 

			FROM 

			tblservicingdetail a

			LEFT JOIN tblirdetail AS b ON a.IRNo = b.IRNo

			LEFT JOIN tblfsrdetail AS c ON a.ServiceNo = c.ServiceNo				

			LEFT JOIN tblparticular AS d ON b.MerchantID = d.ParticularID AND d.ParticularTypeID = 1

			LEFT JOIN tblregiondetail AS e ON d.RegionID = e.RegionID

			LEFT JOIN tblregion AS f ON d.RegionType = f.RegionID

			LEFT JOIN tblterminaldetail AS g ON a.TerminalID = g.TerminalID

			LEFT JOIN tblterminaltype AS h ON g.TerminalTypeID = h.TerminalTypeID

			LEFT JOIN tblterminalmodel AS i ON g.TerminalModelID = i.TerminalModelID		

			LEFT JOIN tblsimdetail AS j ON a.SIMID = j.SIMID

				

			WHERE 

			a.ActionMade = 'SUCCESS' AND

			b.ClientName = v_ClientName AND

			(LEFT(c.FSRDate, 7) = LEFT(CURDATE(), 7))

			ORDER BY b.MerchantName;

		ELSE

			SELECT 

			IFNULL_STRING(a.IRNo) AS IRNo, 

			IFNULL_STRING(b.MerchantName) AS Merchant, 

			IFNULL_STRING(b.TID) AS TID, 

			IFNULL_STRING(b.`MID`) AS `MID`,

			IFNULL_STRING(f.Region) AS Region,

			IFNULL_STRING(e.Province) AS Province,

			IFNULL_STRING(g.SerialNo) AS TerminalSN,

			IFNULL_STRING(h.Description) AS TypeDescription,

			IFNULL_STRING(i.Code) AS ModelDescription,

			IFNULL_STRING(j.SerialNo) AS SIMSN,

			IFNULL_STRING(j.Carrier) AS Carrier 

			FROM 

			tblservicingdetail a

			LEFT JOIN tblirdetail AS b ON a.IRNo = b.IRNo				

			LEFT JOIN tblparticular AS d ON b.MerchantID = d.ParticularID AND d.ParticularTypeID = 1

			LEFT JOIN tblregiondetail AS e ON d.RegionID = e.RegionID

			LEFT JOIN tblregion AS f ON d.RegionType = f.RegionID

			LEFT JOIN tblterminaldetail AS g ON a.TerminalID = g.TerminalID

			LEFT JOIN tblterminaltype AS h ON g.TerminalTypeID = h.TerminalTypeID

			LEFT JOIN tblterminalmodel AS i ON g.TerminalModelID = i.TerminalModelID		

			LEFT JOIN tblsimdetail AS j ON a.SIMID = j.SIMID

				

			WHERE 

			a.ServiceStatusDescription = v_ServiceStatusDescription AND

			b.ClientName = v_ClientName

			ORDER BY b.MerchantName;

		END IF;

	END IF;

    

    ELSEIF (p_StatementType = 'Search')

    THEN

			# Clear table data

			DELETE FROM tbldashboardterminal;

			

			# Client

			SET v_ClientName = '';

			IF (p_SearchValue = 'CASTLES' || p_SearchValue = 'CITAS')

			THEN

				SET v_ClientName = CONCAT("'", "METROBANK", "'", ",", "'", "BDO CLG", "'", ",", "'", "WEEPAY", "'");

			ELSE

				SET v_ClientName = CONCAT("'", p_SearchValue, "'") ;

			END IF;

			#SELECT CONCAT("v_ClientName=",v_ClientName); 

			

			OPEN C1;

			GET_RECORD: LOOP

				FETCH C1 INTO v_TerminalTypeID, v_TypeDescription;                

				

				IF (v_TypeDescription = 'MP200')

				THEN

				

				  SET p_ModelArray = 'MP200';	

				  							

				ELSEIF (v_TypeDescription = 'V3 NT' OR v_TypeDescription = 'V3 TOUCH' OR v_TypeDescription = 'V5S' OR v_TypeDescription = 'V3000' OR v_TypeDescription = 'V5000')

				THEN

				

				  SET p_ModelArray = 'V300 MOBILE NON TOUCH,V3 COUNTERTOP NON-TOUCH CL,V3 MOBILE TOUCH CL,V300 MOBILE TOUCH CL - WIFI,V3 COUNTERTOP TOUCH CL,V300 MOBILE TOUCH CL';	

				 

				ELSEIF (v_TypeDescription = 'ANDROID')

				THEN

				

				  SET p_ModelArray = 'S1F1,S1F2';

				    

				END IF;

								

				IF (v_finished = 1)

				THEN

					LEAVE GET_RECORD;

				END IF;

				

				# Loop

				WHILE (p_ModelArray != '')

				DO

					

					SET p_Element = SUBSTRING_INDEX(p_ModelArray, ',', 1);

								  

					IF LOCATE(',', p_ModelArray) > 0 

					THEN

						SET p_ModelArray = SUBSTRING(p_ModelArray, LOCATE(',', p_ModelArray) + 1);

					ELSE

						SET p_ModelArray = '';

					END IF;

										

					# Count Original Stock

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', '0');						

					CALL spViewCount('Search', 'TypeAndModel Original Stock Count', v_Temp, @p_outCount);				

					SET p_TOriginalStock = @p_outCount;					

																		

					# Count Available Stock

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'AVAILABLE', '|', '0');									

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TAvailableStock = @p_outCount;

													

					# Count Installed

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'INSTALLED', '|', v_ClientName);				

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TInstalled = @p_outCount;

					

					# Count Allocated

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'ALLOCATED', '|', v_ClientName);

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TAllocated = @p_outCount;

					

					# Count Dispatch

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'DISPATCH', '|', v_ClientName);

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TDispatch = @p_outCount;

					

					# Count Repair

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'FOR REPAIR', '|', '0');

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TRepair = @p_outCount;

					

					# Count LoanBorrow

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'LOAN/BORROW', '|', '0');				

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TLoanBorrow = @p_outCount;

					

					# Count Defective

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'DEFECTIVE', '|', '0');				

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TDefective = @p_outCount;

					

					# Count Negative

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'NEGATIVE', '|', '0');				

					CALL spViewCount('Search', 'TypeAndModel Status Count', v_Temp, @p_outCount);				

					SET p_TNegative = @p_outCount;

										

					# Count Last Month

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'INSTALLED', '|', v_ClientName);				

					CALL spViewCount('Search', 'TypeAndModel Last Month Count', v_Temp, @p_outCount);				

					SET p_TLastMonthInstalled = @p_outCount;

					# Count This Month

					SET p_outCount = 0;

					SET p_TThisMonthInstalled = 0;

					SET v_Temp = CONCAT(v_TerminalTypeID, '|', p_Element, '|', 'INSTALLED', '|', v_ClientName);

					CALL spViewCount('Search', 'TypeAndModel This Month Count', v_Temp, @p_outCount);				

					SET p_TThisMonthInstalled = @p_outCount;					

					

					#SELECT CONCAT('v_Temp = ', v_Temp, '|v_TypeDescription=', v_TypeDescription);

					

					#SELECT CONCAT("p_Element=", p_Element);

					

					# Get Terminal Model Code

					CALL spViewInfo("Search", "Get Terminal Model Code", p_Element, @p_outInfo);

					SET v_ModelDescription = @p_outInfo;

					

					#SELECT CONCAT("p_Element=", p_Element);

					#SELECT CONCAT("v_ModelDescription=", v_ModelDescription);

					

					# Insert record to tbldashboardterminal

					SET @QUERY = CONCAT('INSERT INTO tbldashboardterminal (TypeDescription, ModelDescription, TOriginalStock, TAvailableStock, TInstalled, TAllocated, TDispatch, TRepair, TLoanBorrow, TDefective, TNegative, TLastMonthInstalled, TThisMonthInstalled) VALUES(',"'", v_TypeDescription, "'", ',', 

										     "'", v_ModelDescription, "'", ',',

										     p_TOriginalStock, ',',

										     p_TAvailableStock, ',',

										     p_TInstalled, ',',

										     p_TAllocated, ',',

										     p_TDispatch, ',',

										     p_TRepair, ',',

										     p_TLoanBorrow, ',',

										     p_TDefective, ',',

										     p_TNegative, ',',

										     p_TLastMonthInstalled, ',',

										     p_TThisMonthInstalled,										     

										     ')');  

										     

					SET p_SQL = '';

					SET p_SQL = @QUERY;

					#SELECT CONCAT('p_SQL = ', p_SQL);

					

					# Execute Query

					PREPARE QUERY FROM @QUERY;

					EXECUTE QUERY;				

								

				END WHILE;

				

			END LOOP GET_RECORD;

			CLOSE C1;	

						  

    END IF;

    

     

END */$$
DELIMITER ;

/* Procedure structure for procedure `spDeleteCollectionDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spDeleteCollectionDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spDeleteCollectionDetail`(

    IN p_StatementType VARCHAR(255),

    IN p_SearchBy VARCHAR(255),

    IN p_SearchValue LONGTEXT,

    IN p_MaintenanceType VARCHAR(255)

)
BEGIN  

DECLARE v_TerminalID INT;

DECLARE v_SIMID INT;

DECLARE v_DockID INT;

DECLARE v_IRIDNo INT;

DECLARE v_TAIDNo INT;

DECLARE v_FSRNo INT;

DECLARE v_UserID INT;

DECLARE v_ServiceNo INT;

DECLARE v_NotifID INT;

DECLARE v_ParticularID INT;

DECLARE v_Date DATE;

DECLARE v_WorkArrangementID INT;

DECLARE v_LeaveNo INT;

DECLARE v_DupType VARCHAR(45);

DECLARE v_TableName VARCHAR(45);

DECLARE v_TypeID INT;

DECLARE v_ID INT;

DECLARE v_MSPNo INT;

DECLARE p_WHERE LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

DECLARE p_TempQuery LONGTEXT;



START TRANSACTION;

IF (p_StatementType = 'Delete') 

THEN  		

	IF (p_MaintenanceType = 'FSR Temp Data')

	THEN

		SET @QUERY = 'DELETE FROM tblfsrdetailtempdata';	

		

	ELSEIF (p_MaintenanceType = 'FSR Detail Null IRNo')

	THEN

		SET @QUERY = 'DELETE FROM tblfsrdetail WHERE TAIDNo = 0';

		

	ELSEIF (p_MaintenanceType = 'IR Detail')

	THEN

		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblirdetail WHERE ", "IRIDNo = ", v_IRIDNo);

	

	ELSEIF (p_MaintenanceType = 'Installation Request Detail')

	THEN

		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblinstallationrequestdetail WHERE ", "IRIDNo = ", v_IRIDNo);

	

	ELSEIF (p_MaintenanceType = 'TA Detail')

	THEN

		SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblterminalallocation WHERE ", "TAIDNo = ", v_TAIDNo);

	

	ELSEIF (p_MaintenanceType = 'Terminal Detail')

	THEN

		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblterminaldetail WHERE ", "TerminalID = ", v_TerminalID);

		

	ELSEIF (p_MaintenanceType = 'Terminal Dock Detail')

	THEN

		SET v_DockID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblterminaldetail WHERE ", "TerminalID = ", v_DockID);	

	

	ELSEIF (p_MaintenanceType = 'SIM Detail')

	THEN

		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblsimdetail WHERE ", "SIMID = ", v_SIMID);

	

	ELSEIF (p_MaintenanceType = 'FSR Detail')

	THEN

		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblfsrdetail WHERE ", "FSRNo = ", v_FSRNo);

	

	ELSEIF (p_MaintenanceType = 'User Log')

	THEN	

		SET v_UserID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tbluserlog WHERE ", "UserID = ", v_UserID);

	

	ELSEIF (p_MaintenanceType = 'Servicing Detail')

	THEN

		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblservicingdetail WHERE ", "FSRNo = ", v_ServiceNo);

		

	ELSEIF (p_MaintenanceType = 'ERM Temp Detail')

	THEN	

		-- tblermdetailx
		-- Delete record
		SET @QUERY = "TRUNCATE TABLE tblermdetailx";		
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
	
		-- tblermdetailrepo
		-- Delete record
		SET @QUERY = "TRUNCATE TABLE tblermdetailrepo";		
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;

		-- tblermdetailtemp
		-- Delete record
		SET @QUERY = "TRUNCATE TABLE tblermdetailtemp";		
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
		
		SET @QUERY =  '';

	ELSEIF (p_MaintenanceType = 'ERM Temp Detail Header')

	THEN

	

		SET @QUERY = "DELETE FROM tblermdetailtemp WHERE FSRNo IN ('1')";

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

	

		SET @QUERY = CONCAT("ALTER TABLE tblermdetailtemp AUTO_INCREMENT = 1;");

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		SET @QUERY = "DELETE FROM tblermdetailrepo WHERE FSRNo IN ('1')";

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

	

		SET @QUERY = CONCAT("ALTER TABLE tblermdetailrepo AUTO_INCREMENT = 1;");

						

	ELSEIF (p_MaintenanceType = 'ERM Temp Detail CleanUp')
	THEN
																	
		SET @QUERY = CONCAT("DELETE FROM tblermdetailtemp WHERE ", "(", "Merchant = 'TEST' OR Merchant LIKE '% TEST' OR Merchant LIKE 'TEST %' OR Merchant LIKE '% TEST %' OR Merchant LIKE '%TEST/%')", ";");
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
		
		SET @QUERY = CONCAT("DELETE FROM tblermdetailtemp WHERE ", "(", "Merchant = 'EMV' OR Merchant LIKE '% EMV' OR Merchant LIKE 'EMV %' OR Merchant LIKE '% EMV %')", ";");
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
	
		SET @QUERY = CONCAT("DELETE FROM tblermdetailtemp WHERE ", "(", "AddInfo = 'TEST' OR AddInfo LIKE '% TEST' OR AddInfo LIKE 'TEST %' OR AddInfo LIKE '% TEST %' OR AddInfo LIKE '%TEST/%')", ";");
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
	
		SET @QUERY = CONCAT("DELETE FROM tblermdetailtemp WHERE ", "(", "AddInfo = 'EMV' OR AddInfo LIKE '% EMV' OR AddInfo LIKE 'EMV %' OR AddInfo LIKE '% EMV %')", ";");
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;

		SET @QUERY = "DELETE FROM tblermdetailtemp WHERE AddInfo IN ('00001/CITAS TEST', 
									     'EMV TESTCARD/N Q', 
									     '136 339/TEST CARD', 
								             'CTI 40/TEST CARD', 
								             'CON 1/MC DEB TEST', 
								             'CON 2/MC DEB TEST', 
									     'BDO TEST CARD/VISA EMV 8', 
									     'CTI TEST/J C TELAN', 
									     'EMV TEST/D JABIAN',
									     'EMV TESTCARD/L SY', 
									     '136 010/TEST CARD', 
									     'MALATE/JOSEPH M',
									     'TEST CARD/BDO', 
									     'UNIONPAY TESTCARD 01',
									     'CTI EMV/N BERMAS',
									     'ANGOS M1 EMV/JB',
									     'EMV/CBC TELLER 1124 0010',
									     'EMV/CBC TELLER 1310 0007',
									     'EMV/CBC TELLER 1312 0008',
									     'EMV/CBC TELLER 1318 0014',
									     'EMV/CBC TELLER 1323 0002',
									     'EMV/CBC ATM 6079 001507',
									     'EMV/CBC ATM 6086 000920'
									     'EMV/CBC ATM 6163 000777'
									     'EMV/CBC ATM 6264 001867',
									     'EMV/OKS 1407 000196',
									     'M1 EMV/R LUNDOD',
									     'MADLANGBAYAN EMV/R'
									     'VERDE EMV/JEROME')";		

		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
		
		# -----------------------------------------
		# delete without prefix
		# prepare the pattern
		# -----------------------------------------
		SELECT
		  REPLACE(
		    REPLACE(
		      GROUP_CONCAT(
			REPLACE(REPLACE(TRIM(TRAILING '^' FROM a.QueryString), '(', '\\\\('), ')', '\\\\)')
			SEPARATOR '^'
		      ),
		      '^',
		      '|'
		    ),
		    '||',
		    '|'
		  ) AS pattern
		INTO @regex_pattern
		FROM tbltype a
		WHERE a.Type = 4;

		-- Wrap pattern in quotes and build the DELETE query
		SET @QUERY = CONCAT("DELETE FROM tblermdetailtemp WHERE Merchant NOT REGEXP '", @regex_pattern, "';");
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
		# -----------------------------------------
		
		SET @QUERY = "DELETE FROM tblermdetailtemp WHERE TxnAmt < '10.00'";	

	ELSEIF (p_MaintenanceType = 'FSR Temp Detail')
	THEN
		SET @QUERY = CONCAT("TRUNCATE TABLE tblfsrdetailtemp");
		
	ELSEIF (p_MaintenanceType = 'FSR Temp Detail Header')

	THEN

	

		SET @QUERY = "DELETE FROM tblfsrdetailtemp WHERE FSRNo IN ('1')";

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

	

		SET @QUERY = CONCAT("ALTER TABLE tblfsrdetailtemp AUTO_INCREMENT = 1;");

			

	ELSEIF (p_MaintenanceType = 'FSR Temp Detail CleanUp')

	THEN		

		SET @QUERY = "DELETE FROM tblfsrdetailtemp WHERE FSRNo IN ('1')";

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		SET @QUERY = "DELETE FROM tblfsrdetailtemp WHERE Merchant IN ('FIELD SERVICE REPORT', 

		                                                              'DCC - FSR', 

									      'Merchant_Debit_Test', 

									      'Merchant_DebitTes1',

									      'Merchant_DebitTest1_Hyatt',

									      'Merchant_DebitTest2_Hyatt',

									      'Merchant_DebitTest2')";

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		/* Delete Merchant with TEST value*/

		SET @QUERY = CONCAT("DELETE FROM tblfsrdetailtemp WHERE Merchant", " LIKE ", "%TEST");

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		/* Delete Additional Info with TEST value*/

		SET @QUERY = CONCAT("DELETE FROM tblfsrdetailtemp WHERE AddInfo", " LIKE ", "%TEST");

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

				

		SET @QUERY = "DELETE FROM tblfsrdetailtemp WHERE PAN NOT IN ('5555', '3333', '2222', '7777')";

		

	ELSEIF (p_MaintenanceType = 'Dummy Filter Date')

	THEN		

		SET @QUERY = CONCAT("DELETE FROM tbldummy");

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

	

		SET @QUERY = CONCAT("ALTER TABLE tbldummy AUTO_INCREMENT = 1;");

		

	ELSEIF (p_MaintenanceType = 'Servicing Detail Temp')

	THEN		

		SET @QUERY = CONCAT("DELETE FROM tblservicingdetailtemp");

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

	

		SET @QUERY = CONCAT("ALTER TABLE tblservicingdetailtemp AUTO_INCREMENT = 1;");	

	

	ELSEIF (p_MaintenanceType = 'Email Notify')

	THEN

		SET v_NotifID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblnotifyemail WHERE ", "NotifID = ", v_NotifID);

		

	ELSEIF (p_MaintenanceType = 'SMS Notify')

	THEN

		SET v_NotifID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblnotifysms WHERE ", "NotifID = ", v_NotifID);

        

    ELSEIF (p_MaintenanceType = 'ERM Temp Detail CleanUp Client')

	THEN	

		SET p_TempQuery = '';

		SET p_TempQuery = CONCAT("SELECT `No`,Merchant,`MID`,TID,InvoiceNo,BatchNo,PAN,FSRDate,FSRTime,TxnType,TxnAmt,AuthCode,RefNo,PhoneNo,Email,NRIC,AddInfo FROM tblermdetailtemp WHERE ", "(", p_SearchValue, ")", ";");			

		

		#SELECT p_TempQuery;

		

		# SELECT(tblermdetailtemp) and INSERT INTO(tblermdetailx)

		SET @QUERY = CONCAT("INSERT INTO tblermdetailx(`No`,Merchant,`MID`,TID,InvoiceNo,BatchNo,PAN,FSRDate,FSRTime,TxnType,TxnAmt,AuthCode,RefNo,PhoneNo,Email,NRIC,AddInfo)", p_TempQuery);

		#SELECT @QUERY;

		

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		#SET @QUERY = CONCAT("TRUNCATE TABLE tblermdetailtemp", ";");

		# Execute Query 

		#PREPARE QUERY FROM @QUERY;

		#EXECUTE QUERY;

		

		-- Delete record

		SET @QUERY = "TRUNCATE TABLE tblermdetailtemp";		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

			

		SET p_TempQuery = '';

		SET p_TempQuery = CONCAT("SELECT FSRNo,`No`,Merchant,`MID`,TID,InvoiceNo,BatchNo,PAN,FSRDate,FSRTime,TxnType,TxnAmt,AuthCode,RefNo,PhoneNo,Email,NRIC,AddInfo FROM tblermdetailx", ";");			

		

		# SELECT(tblermdetailx) and INSERT INTO(tblermdetailtemp)

		SET @QUERY = CONCAT("INSERT INTO tblermdetailtemp(FSRNo,`No`,Merchant,`MID`,TID,InvoiceNo,BatchNo,PAN,FSRDate,FSRTime,TxnType,TxnAmt,AuthCode,RefNo,PhoneNo,Email,NRIC,AddInfo)", p_TempQuery);

		#SELECT @QUERY;

		

		# Drop temporary table

		#DROP TEMPORARY TABLE IF EXISTS tblermdetailx;

        

	ELSEIF (p_MaintenanceType = 'DTR Temp Detail')

	THEN	

		DROP TABLE IF EXISTS tbldtrdetailrepo;		

		SET @QUERY = CONCAT('CREATE TABLE `tbldtrdetailrepo` (

				  `DTRID` int(11) NOT NULL AUTO_INCREMENT,

		      `No` varchar(45) DEFAULT NULL,

		      `Date` datetime NOT NULL,

				  `DTRDate` varchar(45) DEFAULT NULL,

				  `WeekDay` varchar(45) DEFAULT NULL,

				  `ParticularID` int(11) NOT NULL,

				  `IDNo` varchar(45) DEFAULT NULL,

		      `FullName` varchar(45) DEFAULT NULL,

				  `CheckIn` varchar(45) DEFAULT NULL,

				  `CheckOut` varchar(45) DEFAULT NULL,

				  `TCheckInOut` varchar(45) DEFAULT NULL,

				  `OvertimeIn` varchar(45) DEFAULT NULL,

				  `OvertimeOut` varchar(45) DEFAULT NULL,

				  `TOvertime` varchar(45) DEFAULT NULL,

				  `Remarks` varchar(200) DEFAULT NULL,

				  PRIMARY KEY (`DTRID`)

				) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb3;

				');

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

								

		DROP TABLE IF EXISTS tbldtrdetailtemp;		

		SET @QUERY = CONCAT('CREATE TABLE `tbldtrdetailtemp` (

				  `DTRID` int(11) NOT NULL AUTO_INCREMENT,

		      `No` varchar(45) DEFAULT NULL,

		      `Date` datetime NOT NULL,

				  `DTRDate` varchar(45) DEFAULT NULL,

				  `WeekDay` varchar(45) DEFAULT NULL,

				  `ParticularID` int(11) NOT NULL,

				  `IDNo` varchar(45) DEFAULT NULL,

		      `FullName` varchar(45) DEFAULT NULL,

				  `CheckIn` varchar(45) DEFAULT NULL,

				  `CheckOut` varchar(45) DEFAULT NULL,

				  `TCheckInOut` varchar(45) DEFAULT NULL,

				  `OvertimeIn` varchar(45) DEFAULT NULL,

				  `OvertimeOut` varchar(45) DEFAULT NULL,

				  `TOvertime` varchar(45) DEFAULT NULL,

				  `Remarks` varchar(200) DEFAULT NULL,

				  PRIMARY KEY (`DTRID`)

				) ENGINE=InnoDB AUTO_INCREMENT=0 DEFAULT CHARSET=utf8mb3;

				');

				

	ELSEIF (p_MaintenanceType = 'Leave Assignment')

	THEN

		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		SET @QUERY = CONCAT("DELETE FROM tblleaveassignment WHERE ", "ParticularID = ", v_ParticularID);

		

	ELSEIF (p_MaintenanceType = 'TimeSheet')

	THEN

		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_Date = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS DATE);

		

		SET @QUERY = CONCAT("DELETE FROM tbltimesheetdetail WHERE ", "ParticularID = ", v_ParticularID, " AND ", "`Date` = ", ADD_SINGLEQUOTE(v_Date));

		

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		SET @QUERY = '';

		#SET @QUERY = CONCAT("DELETE FROM tbltimesheetdetailrepo WHERE ", "ParticularID = ", v_ParticularID, " AND ", "`Date` = ", ADD_SINGLEQUOTE(v_Date));

		

	ELSEIF (p_MaintenanceType = 'Work Arrangement')

	THEN

		SET v_WorkArrangementID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);		

		

		SET @QUERY = CONCAT("DELETE FROM tblworkarrangement WHERE ", "WorkArrangementID = ", v_WorkArrangementID, " AND ", "ParticularID = ", v_ParticularID);

		

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

	ELSEIF (p_MaintenanceType = 'Leave Movement')

	THEN

		SET v_LeaveNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);		

		

		SET @QUERY = CONCAT("DELETE FROM tblleavemovement WHERE ", "LeaveNo = ", v_LeaveNo, " AND ", "ParticularID = ", v_ParticularID);

		

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

						

	ELSEIF (p_MaintenanceType = 'Privacy Detail')

	THEN		

		SET v_UserID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			

		

		SET @QUERY = CONCAT("DELETE FROM tblprivacydetail WHERE ", "UserID = ", v_UserID);

		

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

	ELSEIF (p_MaintenanceType = 'Duplicate Detail')

	THEN

		SET v_DupType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		

		SET @QUERY = CONCAT("DELETE FROM tblduplicatedetail WHERE ", "DupType = ", "'", v_DupType, "'");

	

	ELSEIF (p_MaintenanceType = 'Diagnostic Detail')

	THEN

		SET v_FSRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET v_ServiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		

		SET @QUERY = CONCAT("DELETE FROM tbldiagnosticdetail WHERE ", "FSRNo=", ADD_SINGLEQUOTE(v_FSRNo), " AND ", "ServiceNo=", ADD_SINGLEQUOTE(v_ServiceNo));
		
	ELSEIF (p_MaintenanceType = 'Manual Diagnostic Detail')

	THEN

		SET v_FSRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET v_ServiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		
		SET v_TypeID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		

		SET @QUERY = CONCAT("DELETE FROM tbldiagnosticdetail WHERE ", "FSRNo=", ADD_SINGLEQUOTE(v_FSRNo), " AND ", "ServiceNo=", ADD_SINGLEQUOTE(v_ServiceNo), " AND ", "TypeID=", ADD_SINGLEQUOTE(v_TypeID));

			

	ELSEIF (p_MaintenanceType = 'Drop Temp Table')

	THEN

		SET v_TableName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		

		SET @QUERY = CONCAT("DROP TABLE ", v_TableName, ";");

        

        #SELECT CONCAT("QUERY=", @QUERY);

        

        ELSEIF (p_MaintenanceType = 'Service Changes Detail')

	THEN

		SET v_ServiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET v_IRIDNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		

		SET @QUERY = CONCAT("DELETE FROM tblservicechangesdetail WHERE ", "ServiceNo=", ADD_SINGLEQUOTE(v_ServiceNo), " AND ", "IRIDNo=", ADD_SINGLEQUOTE(v_IRIDNo));

							
	ELSEIF (p_MaintenanceType = 'Stock Movement Detail')
	THEN
		SET v_ServiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_IRIDNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		
		SET @QUERY = CONCAT("DELETE FROM tblstockmovementdetail WHERE ", "ServiceNo=", ADD_SINGLEQUOTE(v_ServiceNo), " AND ", "IRIDNo=", ADD_SINGLEQUOTE(v_IRIDNo));
		
	ELSEIF (p_MaintenanceType = 'Import Master')
	THEN
		SET v_ID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_MSPNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		
		SET @QUERY = CONCAT("DELETE FROM tblimportmaster WHERE ", "TransNo=", ADD_SINGLEQUOTE(v_ID), " AND ", "ControlNo=", ADD_SINGLEQUOTE(v_MSPNo));
		
	ELSEIF (p_MaintenanceType = 'Report Data Storage')
	THEN
		SET @QUERY = CONCAT("TRUNCATE TABLE tblreportdatastorage");
		
	ELSEIF (p_MaintenanceType = 'Log Service Location')
	THEN
		SET v_ID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_ParticularID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		
		SET @QUERY = CONCAT('
		    DELETE FROM tbllogservicelocation
		    WHERE UserID = ', v_ID, '
		    AND ParticularID = ', v_ParticularID, '
		    AND ID NOT IN (
			SELECT ID FROM (
			    SELECT ID FROM tbllogservicelocation
			    WHERE UserID = ', v_ID, '
			    AND ParticularID = ', v_ParticularID, '
			    ORDER BY ID DESC
			    LIMIT 10
			) AS xTable
		    )
		');
		
	ELSEIF (p_MaintenanceType = 'Helpdesk-Ticket')
	THEN
		SET @IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET @AssistNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET @ProblemNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET @ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
		SET @FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);	
		
		IF (@ProblemNo > 0) THEN
			SET @QUERY = CONCAT("DELETE FROM tblhddetail WHERE ", "ProblemNo =", @ProblemNo, ";");
			
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;	
			DEALLOCATE PREPARE QUERY;
		END IF;
		
		IF (@ServiceNo > 0) THEN
			SET @QUERY = CONCAT("DELETE FROM tblservicingdetail WHERE ", "ServiceNo =", @ServiceNo, " AND AssistNo =", @AssistNo, " AND ProblemNo =", @ProblemNo, ";");
			
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;	
			DEALLOCATE PREPARE QUERY;
		END IF;
		
		IF (@FSRNo > 0) THEN
			SET @QUERY = CONCAT("DELETE FROM tblfsrdetail WHERE ", "ServiceNo =", @ServiceNo, " AND FSRNo =", @FSRNo, ";");
			
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;	
			DEALLOCATE PREPARE QUERY;
		END IF;
		
		IF (@AssistNo > 0) THEN
			SELECT COUNT(*) INTO @TCount FROM tblhddetail a WHERE a.AssistNo = @AssistNo;
			IF (@TCount <= 0) THEN
				SET @QUERY = CONCAT("DELETE FROM tblhdmaster WHERE ", "AssistNo =", @AssistNo, " AND IRIDNo = ", @IRIDNo, ";");
			END IF;
		END IF;
	
	ELSEIF (p_MaintenanceType = 'ERM Settlement Report')
	THEN
		SET @QUERY = CONCAT("TRUNCATE TABLE tbltempsettlement");
		
	ELSEIF (p_MaintenanceType = 'Inventory Deletion')
	THEN
		SET @InventoryType = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
		SET @SNList = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
		
		-- Convert CSV to rows using JSON trick
		SET @json = CONCAT('["', REPLACE(@SNList, ',', '","'), '"]');
		
		DELETE a
		    FROM tblterminaldetail a
		    INNER JOIN JSON_TABLE(@json, '$[*]' COLUMNS (
			sn VARCHAR(50) PATH '$'
		    )) t
			ON a.TerminalSN = t.sn;
			
		SET @QUERY = '';
		
	ELSEIF (p_MaintenanceType = 'Clear Merchant Testing')
	THEN	
	    SET @DeleteMerchants = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
	    SET @DeleteTrans = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
	    SET @MerchantNames = REPLACE(TRIM(SPLIT_STRING(p_SearchValue, '|', 3)), ', ', ',');
	    
	    # -------------------------------------------------------------
	    # Initialize variables
	    # -------------------------------------------------------------
	    SET @QUERY = '';	    
	    SET @ParticularIDs = NULL;
	    SET @IRIDNos = NULL;
	    SET @TerminalIDs = NULL;
	    SET @SIMIDs = NULL;
	    SET @ServiceNos = NULL;
	    SET @AssistNos = NULL;
	    # -------------------------------------------------------------
	    # CLEAR TEST DATA
	    # -------------------------------------------------------------
	    # Merchant
	    # -------------------------------------------------------------

	    IF COALESCE(@MerchantNames, '') = '' THEN
		SET @MerchantNames = 'ABC MERCH,XYZ MERCH';
	    END IF;

	    SELECT GROUP_CONCAT(a.ParticularID)
	    INTO @ParticularIDs
	    FROM tblparticular a
	    WHERE
		(@MerchantNames LIKE '%ABC MERCH%' AND a.Name LIKE 'ABC MERCH%')
		OR
		(@MerchantNames LIKE '%XYZ MERCH%' AND a.Name LIKE 'XYZ MERCH%');

	    IF COALESCE(@ParticularIDs, '') <> '' THEN

		# tblirdetail
		SELECT GROUP_CONCAT(a.IRIDNo)
		INTO @IRIDNos
		FROM tblirdetail a
		WHERE FIND_IN_SET(a.MerchantID, @ParticularIDs);
		
	    END IF;

	    IF COALESCE(TRIM(@IRIDNos), '') <> '' THEN

		# Update IR
		UPDATE tblirdetail
		SET
		    IRStatus = 1,
		    IRStatusDescription = 'AVAILABLE',
		    TerminalID = 0,
		    TerminalSN = '',
		    SIMID = 0,
		    SIMSN = ''
		WHERE FIND_IN_SET(IRIDNo, @IRIDNos) > 0;

		# View
		SELECT *
		FROM tblirdetail a
		WHERE FIND_IN_SET(a.IRIDNo, @IRIDNos);

	    END IF;

	    # -------------------------------------------------------------
	    # Terminal
	    # -------------------------------------------------------------
	    SELECT GROUP_CONCAT(a.TerminalID)
	    INTO @TerminalIDs
	    FROM tblterminaldetail a
	    WHERE a.TerminalSN LIKE '%100000000%';

	    IF COALESCE(TRIM(@TerminalIDs), '') <> '' THEN

		UPDATE tblterminaldetail
		SET
		    LocationID = 2,
		    Location = 'CITAS F.E',
		    ClientID = 0,
		    ClientName = '',
		    TerminalStatus = 1,
		    TerminalStatusDescription = 'AVAILABLE',
		    LastServiceNo = 0,
		    LastIRIDNo = 0
		WHERE FIND_IN_SET(TerminalID, @TerminalIDs) > 0;

		SELECT *
		FROM tblterminaldetail a
		WHERE FIND_IN_SET(a.TerminalID, @TerminalIDs);

	    END IF;

	    # -------------------------------------------------------------
	    # SIM
	    # -------------------------------------------------------------
	    SELECT GROUP_CONCAT(a.SIMID)
	    INTO @SIMIDs
	    FROM tblsimdetail a
	    WHERE a.SIMSN LIKE '%200000000%';

	    IF COALESCE(TRIM(@SIMIDs), '') <> '' THEN

		UPDATE tblsimdetail
		SET
		    LocationID = 2,
		    Location = 'CITAS F.E',
		    ClientID = 0,
		    ClientName = '',
		    SIMStatus = 1,
		    SIMStatusDescription = 'AVAILABLE',
		    LastServiceNo = 0,
		    LastIRIDNo = 0
		WHERE FIND_IN_SET(SIMID, @SIMIDs) > 0;

		SELECT *
		FROM tblsimdetail a
		WHERE FIND_IN_SET(a.SIMID, @SIMIDs);

	    END IF;

	    # -------------------------------------------------------------
	    # JO / FSR / EXPENSES
	    # -------------------------------------------------------------
	    IF COALESCE(TRIM(@IRIDNos), '') <> '' THEN

		SELECT GROUP_CONCAT(a.ServiceNo)
		INTO @ServiceNos
		FROM tblservicingdetail a
		WHERE FIND_IN_SET(a.IRIDNo, @IRIDNos);

	    END IF;

	    IF COALESCE(TRIM(@ServiceNos), '') <> '' THEN

		if (@DeleteTrans = 1) THEN
			DELETE FROM tblservicingdetail
			WHERE FIND_IN_SET(ServiceNo, @ServiceNos) > 0;

			DELETE FROM tblfsrdetail
			WHERE FIND_IN_SET(ServiceNo, @ServiceNos) > 0;
			
			DELETE FROM tblexpensestransmaster
			WHERE FIND_IN_SET(ServiceNo, @ServiceNos) > 0;
			
			DELETE FROM tblexpensestransdetail
			WHERE FIND_IN_SET(ServiceNo, @ServiceNos) > 0;
			
			DELETE FROM tblservicingactivitydetail
			WHERE FIND_IN_SET(ServiceNo, @ServiceNos) > 0;

			SELECT *
			FROM tblservicingdetail a
			WHERE FIND_IN_SET(a.ServiceNo, @ServiceNos);

			SELECT *
			FROM tblfsrdetail a
			WHERE FIND_IN_SET(a.ServiceNo, @ServiceNos);
			
			SELECT *
			FROM tblexpensestransmaster a
			WHERE FIND_IN_SET(a.ServiceNo, @ServiceNos);
			
			SELECT *
			FROM tblexpensestransdetail a
			WHERE FIND_IN_SET(a.ServiceNo, @ServiceNos);
			
			SELECT *
			FROM tblservicingactivitydetail a
			WHERE FIND_IN_SET(a.ServiceNo, @ServiceNos);
			
		END IF;	

	    END IF;
	    
	    # ------------------------------------------------------------
	    # Delete Merchants
	    # ------------------------------------------------------------
	    IF COALESCE(@ParticularIDs, '') <> '' THEN

		if (@DeleteMerchants = 1) THEN
			# tblirdetail
			DELETE FROM tblirdetail
			WHERE FIND_IN_SET(MerchantID, @ParticularIDs) > 0;
			
			# tblparticular
			DELETE FROM tblparticular
			WHERE FIND_IN_SET(ParticularID, @ParticularIDs) > 0;			
			
		END IF;

	    END IF;

	    # -------------------------------------------------------------
	    # Helpdesk
	    # -------------------------------------------------------------
	    IF COALESCE(TRIM(@IRIDNos), '') <> '' THEN

		SELECT GROUP_CONCAT(a.AssistNo)
		INTO @AssistNos
		FROM tblhdmaster a
		WHERE FIND_IN_SET(a.IRIDNo, @IRIDNos);

	    END IF;

	    IF COALESCE(TRIM(@AssistNos), '') <> '' THEN

		IF (@DeleteTrans = 1) THEN
			DELETE FROM tblhddetail
			WHERE FIND_IN_SET(AssistNo, @AssistNos) > 0;
		END IF;	

	    END IF;

	    IF COALESCE(TRIM(@IRIDNos), '') <> '' THEN

		IF (@DeleteTrans = 1) THEN	
			DELETE FROM tblhdmaster
			WHERE FIND_IN_SET(IRIDNo, @IRIDNos) > 0;

			SELECT *
			FROM tblhdmaster a
			WHERE FIND_IN_SET(a.IRIDNo, @IRIDNos);

			SELECT *
			FROM tblhddetail a
			WHERE FIND_IN_SET(a.AssistNo, @AssistNos);
		END IF;	

	    END IF;
        
    ELSEIF (p_MaintenanceType = 'Delete Service Expense')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);

		UPDATE tblexpensestransmaster
		SET
			TotalAmount =
			(
				SELECT COALESCE(SUM(Amount), 0)
				FROM tblexpensestransdetail
				WHERE ServiceNo = v_ServiceNo
				  AND DetailID <> v_ID
			),
			UpdatedDate = NOW()
		WHERE ServiceNo = v_ServiceNo;

		SET @QUERY = CONCAT(
			'DELETE FROM tblexpensestransdetail ',
			'WHERE ServiceNo = ', v_ServiceNo,
			' AND DetailID = ', v_ID
		);

	END IF;          

	# Execute Query 

	IF (LENGTH(@QUERY) > 0)
	then
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;	
	end if;

END IF; 

COMMIT;

       

END */$$
DELIMITER ;

/* Procedure structure for procedure `spDeleteInventoryDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spDeleteInventoryDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spDeleteInventoryDetail`(

	IN p_StatementType VARCHAR(50),

    IN p_MaintenanceType VARCHAR(50),

    IN p_SearchBy VARCHAR(50),

    IN p_SearchValue VARCHAR(50),

    OUT p_outErrorMessage VARCHAR(200))
BEGIN  

DECLARE v_ID INTEGER;

DECLARE EXIT HANDLER FOR SQLEXCEPTION

SET p_outErrorMessage = 'SQLException invoked';

DECLARE EXIT HANDLER FOR 1062

SET p_outErrorMessage = 'MySQL error code 1062 invoked';

DECLARE EXIT HANDLER FOR SQLSTATE '23000'

SET p_outErrorMessage = 'MySQL 23000 invoked';

START TRANSACTION;

IF (p_StatementType = 'Delete') 

THEN  

	IF (p_MaintenanceType = 'Request Form')

THEN 

		IF (p_SearchBy = 'RequestID')

    THEN

	SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER); 

			SET @QUERY = CONCAT('DELETE FROM tblrequestformdetail

						 WHERE RequestID = ', v_ID);

     END IF;                

 

 ELSEIF (p_MaintenanceType = 'Request Service Type')

 THEN

		IF (p_SearchBy = 'RequestID')

    THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER); 

		    SET @QUERY = CONCAT('DELETE FROM tblreqservicetypedetail

				 WHERE RequestID = ', v_ID);

    END IF;           

	   

 ELSEIF (p_MaintenanceType = 'Request Equipment Used')

 THEN   

		IF (p_SearchBy = 'RequestID')

    THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER); 

		    SET @QUERY = CONCAT('DELETE FROM tblreqequipmentdetail

				 WHERE RequestID = ', v_ID);

    END IF;

			 

 END IF;          

 

# Execute Query 

	PREPARE QUERY FROM @QUERY;

	EXECUTE QUERY;

	

SET p_outErrorMessage = '';

END IF; 

COMMIT;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spEquipmentInsertUpdate` */

