p_EquipmentID INTEGER,  

p_Description VARCHAR(100),

p_StatementType NVARCHAR(20) /* = NULL */

)
BEGIN  

 

 IF p_StatementType = 'Update'  

	THEN      

		UPDATE tblequipment SET  

					   Description = p_Description                   

		WHERE EquipmentID = p_EquipmentID;  

	END IF;  

END */$$
