/* Procedure structure for procedure `spGenerateInstallationSummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGenerateInstallationSummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGenerateInstallationSummary`(  



    IN p_StatementType VARCHAR(30) /* = NULL */ ,



    IN p_SearchBy VARCHAR(50) /* = NULL */ ,



    IN p_SearchValue VARCHAR(50) /* = NULL */



)
BEGIN



DECLARE var_sql_statement VARCHAR(1000);



DECLARE v_finished INT DEFAULT 0;



DECLARE v_ID INT;



DECLARE v_LocationID INT;



DECLARE v_Location VARCHAR(45);



DECLARE v_LocationTemp VARCHAR(45);







DECLARE v_TypeCnt INT;



DECLARE v_ModelCnt INT;



DECLARE v_StatusCnt INT;



DECLARE v_TypeID INT;



DECLARE v_Type VARCHAR(45);



DECLARE v_TypeTemp VARCHAR(45);







DECLARE v_ModelID INt;



DECLARE v_Model VARCHAR(45);



DECLARE v_ModelTemp VARCHAR(45);







DECLARE v_StatusID INT;



DECLARE v_Status VARCHAR(45);







DECLARE v_TCount INT;



DECLARE TAvailable INT;



DECLARE TInstalled INT;



DECLARE TAllocated INT;



DECLARE TDispatch INT;



DECLARE TPullout INT;



DECLARE TBorrow INT;



DECLARE TLost INT;



DECLARE TDefective INT;







DECLARE v_RegionID INT;



DECLARE v_Region VARCHAR(45);



DECLARE v_RegionTemp VARCHAR(45);







DECLARE v_JobType INT;



DECLARE v_JobTypeDescription VARCHAR(45);



DECLARE v_JobTypeTemp VARCHAR(45);



DECLARE TSuccess INT;



DECLARE TNegative INT;







DECLARE TTotal INT;



DECLARE v_SearchValue VARCHAR(45);







DECLARE sQuery LONGTEXT;



DECLARE p_SQL_Select LONGTEXT;



DECLARE p_SQL_Insert LONGTEXT;	







DECLARE _rec INT;



DECLARE done1 INT DEFAULT 0;



DECLARE out_cursor1 VARCHAR(255);



DECLARE out_cursor2 VARCHAR(255);



DECLARE out_cursor3 VARCHAR(255);







DECLARE v_Count1 INT;



DECLARE v_Loop1 INT DEFAULT 0;







DECLARE v_Count2 INT;



DECLARE v_Loop2 INT DEFAULT 0;







DECLARE v_Count3 INT;



DECLARE v_Loop3 INT DEFAULT 0;







DECLARE Cursor1 CURSOR FOR



	SELECT



	CONCAT(IFNULL_NUMERIC(b.TerminalTypeID), "^", IFNULL_STRING_ONLY(b.Description), "|", 



	IFNULL_NUMERIC(c.TerminalModelID), "^", IFNULL_STRING_ONLY(c.Description)) AS sTemp



	FROM



	tblterminaldetail a



	LEFT JOIN tblterminaltype b ON a.TerminalTypeID = b.TerminalTypeID



	LEFT JOIN tblterminalmodel c ON a.TerminalModelID = c.TerminalModelID



	WHERE (a.isActive > 0 AND b.isActive > 0 AND c.isActive > 0)



	GROUP BY a.TerminalTypeID, a.TerminalModelID;



	



DECLARE Cursor2 CURSOR FOR



	SELECT



	CONCAT(IFNULL_NUMERIC(a.RegionID), "^", IFNULL_STRING_ONLY(a.Region)) as sRegion 



	FROM 



	tblregion a 



	WHERE isActive > 0;



	



DECLARE Cursor3 CURSOR FOR



	SELECT



	CONCAT(IFNULL_NUMERIC(a.JobType), "^", IFNULL_STRING_ONLY(a.ServiceJobTypeDescription)) AS sServiceType 



	FROM 



	tblservicetype a 



	WHERE isActive > 0;	







DECLARE CONTINUE HANDLER FOR NOT FOUND SET done1 = 1;   







#SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);







START TRANSACTION;







IF (p_StatementType = 'Generate')



THEN



	IF (p_SearchBy = 'Installation Request Summary')



	THEN



		CALL spCreateTempTable("Create", "Installation Request Summary");



		



		OPEN Cursor1;



		



		REPEAT



		



		SET out_cursor1 = "";



		SET v_LocationTemp = "";



		SET v_TypeTemp = "";



		SET v_ModelTemp = "";



		



		SET v_Count2 = 0;



		SET v_Loop2 = 0;







		SET v_Count3 = 0;



		SET v_Loop3 = 0;		



		



		SELECT COUNT(*) INTO v_Count2 FROM tblregion WHERE isActive > 0; # get region total count



			



		FETCH Cursor1 INTO out_cursor1;



		#SELECT CONCAT("out_cursor1=", out_cursor1);







			IF (LENGTH(out_cursor1) > 0)



			THEN



				#3^ANDROID|7^S1F1



				SET v_TypeTemp = TRIM(SPLIT_STRING(out_cursor1, '|' ,1));



				SET v_TypeID = CAST(TRIM(SPLIT_STRING(v_TypeTemp, '^' ,1)) AS UNSIGNED INTEGER);



				SET v_Type = TRIM(SPLIT_STRING(v_TypeTemp, '^' ,2));



				#SELECT (CONCAT('v_TypeTemp=', v_TypeTemp, ",v_TypeID=", v_TypeID, ",v_Type=",v_Type));



				



				SET v_ModelTemp = TRIM(SPLIT_STRING(out_cursor1, '|' ,2));



				SET v_ModelID = CAST(TRIM(SPLIT_STRING(v_ModelTemp, '^' ,1)) AS UNSIGNED INTEGER);



				SET v_Model = TRIM(SPLIT_STRING(v_ModelTemp, '^' ,2));



				#SELECT (CONCAT('v_ModelTemp=', v_ModelTemp, ",v_ModelID=", v_ModelID, ",v_Model=",v_Model));



				



				IF NOT done1 



				THEN



					SELECT COUNT(*) INTO v_Count3 FROM tblservicetype WHERE isActive > 0; # get service type total count



					



					 OPEN Cursor2;



					



					     REPEAT



					     SET out_cursor2 = "";						     					     



					     SET v_RegionTemp = "";



					     set v_Loop3 = 0;



						



					     FETCH Cursor2 INTO out_cursor2;				     



					     #SELECT CONCAT("out_cursor2=", out_cursor2, ",v_Loop2=", v_Loop2, ",v_Count2=",v_Count2);



					     SET v_Loop2 = v_Loop2 + 1;



					     



					     #4|METRO MANILA					    



					     SET v_RegionID = CAST(TRIM(SPLIT_STRING(out_cursor2, '^' ,1)) AS UNSIGNED INTEGER);



					     SET v_Region = TRIM(SPLIT_STRING(out_cursor2, '^' ,2));



					     #SELECT (CONCAT("v_RegionID=", v_RegionID, ",v_Region=",v_Region));



					     



					     IF (LENGTH(out_cursor2) > 0)



					     THEN



						     IF (v_Count2 >= v_Loop2) 



						     THEN														



												



							OPEN Cursor3;							



							     



							     REPEAT



							     SET out_cursor3 = "";							    					    



							     						     



							     FETCH Cursor3 INTO out_cursor3;



							     #SELECT CONCAT("out_cursor3=", out_cursor3);



							     SET v_Loop3 = v_Loop3 + 1;



							     	    



							     IF (LENGTH(out_cursor3) > 0)



							     THEN



								   #SELECT CONCAT("out_cursor3=", out_cursor3, ",v_Loop3=", v_Loop3, ",v_Count3=",v_Count3);



								



								   IF (v_Count3 >= v_Loop3) 



								   THEN



									   #1^INSTALLATION				    



									   SET v_JobType = CAST(TRIM(SPLIT_STRING(out_cursor3, '^' ,1)) AS UNSIGNED INTEGER);



									   SET v_JobTypeDescription = TRIM(SPLIT_STRING(out_cursor3, '^' ,2));



									   #SELECT (CONCAT("v_JobType=", v_JobType, ",v_JobTypeDescription=",v_JobTypeDescription));



									   	



									   # Success count							   



									   SET TSuccess = 0;



									   SET v_SearchValue = CONCAT(v_RegionID, "|", v_TypeID, "|", v_ModelID, "|", v_JobType, "|", "SUCCESS");



									   #SELECT (CONCAT("TSuccess,v_SearchValue=", v_SearchValue));



									   CALL spViewCount("Search", "Installation Count By Service JobType", v_SearchValue, @p_outCount);



									   SET TSuccess = @p_outCount;



									   



									   # Negative count



									   SET TNegative = 0;



									   SET v_SearchValue = CONCAT(v_RegionID, "|", v_TypeID, "|", v_ModelID, "|", v_JobType, "|", "NEGATIVE");



									    #SELECT (CONCAT("TNegative,v_SearchValue=", v_SearchValue));



									    CALL spViewCount("Search", "Installation Count By Service JobType", v_SearchValue, @p_outCount);



									    SET TNegative = @p_outCount;



									   



									    # Insert statement	



									    #SELECT (CONCAT("v_JobType=", v_JobType, ",v_TypeID=",v_TypeID, ",v_ModelID=",v_ModelID,"v_RegionID=", v_RegionID, ",v_Region=",v_Region));								   														



									    IF (v_JobType > 0 && v_TypeID > 0 && v_ModelID > 0)



									     THEN



											SET TTotal = TSuccess + TNegative;



											



											# Select/Insert



											SET sQuery = "";



											SET sQuery = CONCAT("(", 



											"'", v_RegionID, "',", 



											"'", v_Region, "',",



											"'", v_RegionID, "',", 	



											"'", v_TypeID, "',",			



											"'", v_Type, "',", 	



											"'", v_ModelID, "',", 			



											"'", v_Model, "',", 



											"'", v_JobType, "',", 



											"'", v_JobTypeDescription, "',", 



											"'", TSuccess, "',", 



											"'", TNegative, "',", 					



											"'", TTotal, "'", ")"



											);



											



											#SELECT (CONCAT('Insert->sQuery=', sQuery));



												



											SET @QUERY = "";



											SET @QUERY = CONCAT('INSERT INTO tblinstallationsummary(RegionType, Region, RegionID, TerminalTypeID, TerminalType, TerminalModelID, TerminalModel, 



																		JobType, JobTypeDescription, TSuccess, TNegative, TTotal)



											    VALUES ', sQuery);



											



											#SELECT (CONCAT('@QUERY=', @QUERY));   



											    



											# Execute Query 



											PREPARE QUERY FROM @QUERY;



											EXECUTE QUERY;



										END IF;



									   



								     END IF;



								     				     



							     END IF;



							     					     



							     UNTIL v_Loop3 >= v_Count3 END REPEAT;







							  



							  CLOSE Cursor3; 



							



						     END IF;					     



						     



					     END IF;



					     



					     UNTIL v_Loop2 >= v_Count2 END REPEAT;					  



					  



					  CLOSE Cursor2;







				 END IF;



				 



			 END IF;



			 



		 UNTIL done1 END REPEAT;



		 



		 CLOSE Cursor1;



	END IF;     



END IF; 







COMMIT;   



       



END */$$
DELIMITER ;

/* Procedure structure for procedure `spGenerateSIMSummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGenerateSIMSummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGenerateSIMSummary`(  



    IN p_StatementType VARCHAR(30) /* = NULL */ ,



    IN p_SearchBy VARCHAR(50) /* = NULL */ ,



    IN p_SearchValue VARCHAR(50) /* = NULL */



)
BEGIN



DECLARE var_sql_statement VARCHAR(1000);



DECLARE v_finished INT DEFAULT 0;



DECLARE v_ID INT;



DECLARE v_LocationID INT;



DECLARE v_Location VARCHAR(45);



DECLARE v_LocationTemp VARCHAR(45);







DECLARE v_TypeCnt INT;



DECLARE v_ModelCnt INT;



DECLARE v_StatusCnt INT;



DECLARE v_TypeID INT;



DECLARE v_Type VARCHAR(45);



DECLARE v_TypeTemp VARCHAR(45);







DECLARE v_StatusID INT;



DECLARE v_Status VARCHAR(45);







DECLARE v_TCount INT;



DECLARE TAvailable INT;



DECLARE TInstalled INT;



DECLARE TAllocated INT;



DECLARE TDispatch INT;



DECLARE TPullout INT;



DECLARE TBorrow INT;



DECLARE TLost INT;



DECLARE TDefective INT;



DECLARE TTotal INT;



DECLARE v_SearchValue VARCHAR(45);







DECLARE sQuery LONGTEXT;



DECLARE p_SQL_Select LONGTEXT;



DECLARE p_SQL_Insert LONGTEXT;	







DECLARE C1 CURSOR FOR



	SELECT



	CONCAT(IFNULL_NUMERIC(a.LocationID), "^", IFNULL_STRING_ONLY(a.Description), "|", 



	IFNULL_NUMERIC(c.TypeID), "^", IFNULL_STRING_ONLY(c.Description)) AS sTemp



	FROM



	tbllocation a



	LEFT JOIN tblsimdetail b ON a.Description = b.Location



	LEFT JOIN tbltype c ON b.Carrier = c.Description AND c.Type = 1



	WHERE (a.isActive > 0 AND c.Active > 0)



	GROUP BY a.LocationID, c.TypeID;







DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      







#SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);







START TRANSACTION;







IF (p_StatementType = 'Generate')



THEN



	IF (p_SearchBy = 'Inventory Summary')



	THEN



		CALL spCreateTempTable("Create", "SIM Summary");



		



		OPEN C1;



		GET_RECORD: LOOP



			



			SET var_sql_statement = "";



			SET v_LocationTemp = "";



			SET v_TypeTemp = "";			



			SET TTotal = 0;



			



			FETCH C1 INTO var_sql_statement;



			#SELECT (CONCAT('var_sql_statement=', "[", var_sql_statement, "]"));



			



			IF (LENGTH(var_sql_statement) > 0)



			THEN



				#1^OFFICE 616|3^TNS SIM



				SET v_LocationTemp = TRIM(SPLIT_STRING(var_sql_statement, '|' ,1));



				SET v_LocationID = CAST(TRIM(SPLIT_STRING(v_LocationTemp, '^' ,1)) AS UNSIGNED INTEGER);



				SET v_Location = TRIM(SPLIT_STRING(v_LocationTemp, '^' ,2));



				#SELECT (CONCAT('v_LocationTemp=', v_LocationTemp, ",v_LocationID=", v_LocationID, ",v_Location=",v_Location));



				



				SET v_TypeTemp = TRIM(SPLIT_STRING(var_sql_statement, '|' ,2));



				SET v_TypeID = CAST(TRIM(SPLIT_STRING(v_TypeTemp, '^' ,1)) AS UNSIGNED INTEGER);



				SET v_Type = TRIM(SPLIT_STRING(v_TypeTemp, '^' ,2));



				#SELECT (CONCAT('v_TypeTemp=', v_TypeTemp, ",v_TypeID=", v_TypeID, ",v_Type=",v_Type));



				



				# AVAILABLE



				SET TAvailable = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 1);



				CALL spViewCount("Search", "SIM Count By Status", v_SearchValue, @p_outCount);



				SET TAvailable = @p_outCount;



				



				# INSTALLED



				SET TInstalled = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 7);



				CALL spViewCount("Search", "SIM Count By Status", v_SearchValue, @p_outCount);



				SET TInstalled = @p_outCount;



				



				# ALLOCATED



				SET TAllocated = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 2);



				CALL spViewCount("Search", "SIM Count By Status", v_SearchValue, @p_outCount);



				SET TAllocated = @p_outCount;



				



				# DISPATCH



				SET TDispatch = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 8);



				CALL spViewCount("Search", "SIM Count By Status", v_SearchValue, @p_outCount);



				SET TDispatch = @p_outCount;



				



				# DEFECTIVE



				SET TDefective = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 4);



				CALL spViewCount("Search", "SIM Count By Status", v_SearchValue, @p_outCount);



				SET TDefective = @p_outCount;



				



				# LOST



				SET TLost = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 5);



				CALL spViewCount("Search", "SIM Count By Status", v_SearchValue, @p_outCount);



				SET TLost = @p_outCount;



				



				# LOAN/BORROW



				SET TBorrow = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 6);



				CALL spViewCount("Search", "SIM Count By Status", v_SearchValue, @p_outCount);



				SET TBorrow = @p_outCount;



				



				# PULLOUT



				SET TPullout = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_Type, "|", 4, "|", "SUCCESS");



				CALL spViewCount("Search", "SIM Count By Service JobType", v_SearchValue, @p_outCount);



				SET TPullout = @p_outCount;



				



				IF (v_LocationID > 0 && v_TypeID > 0)



				THEN



					SET TTotal = TAvailable + TInstalled + TAllocated + TDispatch + TDefective + TLost + TBorrow;



					



					# Select/Insert



					SET sQuery = "";



					SET sQuery = CONCAT("(", 



					"'", v_LocationID, "',", 



					"'", v_Location, "',",	



					"'", v_TypeID, "',",			



					"'", v_Type, "',", 						



					"'", TAvailable, "',", 



					"'", TInstalled, "',", 



					"'", TAllocated, "',", 



					"'", TDispatch, "',", 



					"'", TPullout, "',", 



					"'", TBorrow, "',",



					"'", TLost, "',", 



					"'", TDefective, "',", 							



					"'", TTotal, "'", ")"



					);



					



					#SELECT (CONCAT('Insert->sQuery=', sQuery));



						



					SET @QUERY = "";



					SET @QUERY = CONCAT('INSERT INTO tblsimsummary(LocationID, Location, TypeID, Carrier, TAvailable, TInstalled, 



											   TAllocated, TDispatch, TPullout, TBorrow, TLost, TDefective, TTotal)



					    VALUES ', sQuery);



					



					#SELECT (CONCAT('@QUERY=', @QUERY));   



					    



					# Execute Query 



					PREPARE QUERY FROM @QUERY;



					EXECUTE QUERY;



				end if;								



			END IF;	







			IF (v_finished = 1)



			THEN



				LEAVE GET_RECORD;



			END IF;



			



		END LOOP GET_RECORD;



		



		CLOSE C1;



	END IF;     



END IF; 







COMMIT;   



       



END */$$
DELIMITER ;

/* Procedure structure for procedure `spGenerateTerminalSummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGenerateTerminalSummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGenerateTerminalSummary`(  



    IN p_StatementType VARCHAR(30) /* = NULL */ ,



    IN p_SearchBy VARCHAR(50) /* = NULL */ ,



    IN p_SearchValue VARCHAR(50) /* = NULL */



)
BEGIN







DECLARE var_sql_statement VARCHAR(1000);



DECLARE v_finished INT DEFAULT 0;



DECLARE v_ID INT;



DECLARE v_LocationID INT;



DECLARE v_Location VARCHAR(45);



DECLARE v_LocationTemp VARCHAR(45);







DECLARE v_TypeCnt INT;



DECLARE v_ModelCnt INT;



DECLARE v_StatusCnt INT;



DECLARE v_TypeID INT;



DECLARE v_Type VARCHAR(45);



DECLARE v_TypeTemp VARCHAR(45);







DECLARE v_ModelID INt;



DECLARE v_Model VARCHAR(45);



DECLARE v_ModelTemp VARCHAR(45);







DECLARE v_StatusID INT;



DECLARE v_Status VARCHAR(45);







DECLARE v_TCount INT;



DECLARE TAvailable INT;



DECLARE TInstalled INT;



DECLARE TAllocated INT;



DECLARE TDispatch INT;



DECLARE TPullout INT;



DECLARE TBorrow INT;



DECLARE TLost INT;



DECLARE TDefective INT;



DECLARE TTotal INT;



DECLARE v_SearchValue VARCHAR(45);







DECLARE v_TerminalTypeID INT;



DECLARE v_TerminalModelID INT;



DECLARE v_ClientID INT;







DECLARE sQuery LONGTEXT;



DECLARE p_SQL_Select LONGTEXT;



DECLARE p_SQL_Insert LONGTEXT;	







DECLARE C1 CURSOR FOR



	SELECT



	CONCAT(IFNULL_NUMERIC(a.LocationID), "^", IFNULL_STRING_ONLY(a.Description), "|", 



	IFNULL_NUMERIC(c.TerminalTypeID), "^", IFNULL_STRING_ONLY(c.Description), "|", 



	IFNULL_NUMERIC(d.TerminalModelID), "^", IFNULL_STRING_ONLY(d.Description)) as sTemp



	FROM



	tbllocation a



	LEFT JOIN tblterminaldetail b ON a.Description = b.Location



	LEFT JOIN tblterminaltype c ON b.TerminalTypeID = c.TerminalTypeID



	LEFT JOIN tblterminalmodel d ON b.TerminalModelID = d.TerminalModelID



	WHERE (a.isActive > 0 AND c.isActive > 0 AND d.isActive > 0)



	GROUP BY a.LocationID, b.TerminalTypeID, b.TerminalModelID;







DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      







START TRANSACTION;







IF (p_StatementType = 'Generate')



THEN



	IF (p_SearchBy = 'Inventory Summary')



	THEN



		SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);



		SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INT);



		SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INT);



		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INT);







		CALL spCreateTempTable("Create", "Terminal Summary");



		



		OPEN C1;



		GET_RECORD: LOOP



			



			SET var_sql_statement = "";



			SET v_LocationTemp = "";



			SET v_TypeTemp = "";



			SET v_ModelTemp = "";



			SET TTotal = 0;



			



			FETCH C1 INTO var_sql_statement;



			#SELECT (CONCAT('var_sql_statement=', "[", var_sql_statement, "]"));



			



			IF (LENGTH(var_sql_statement) > 0)



			THEN



				#1^OFFICE 616|3^ANDROID|7^S1F1



				SET v_LocationTemp = TRIM(SPLIT_STRING(var_sql_statement, '|' ,1));



				SET v_LocationID = CAST(TRIM(SPLIT_STRING(v_LocationTemp, '^' ,1)) AS UNSIGNED INTEGER);



				SET v_Location = TRIM(SPLIT_STRING(v_LocationTemp, '^' ,2));



				#SELECT (CONCAT('v_LocationTemp=', v_LocationTemp, ",v_LocationID=", v_LocationID, ",v_Location=",v_Location));



				



				SET v_TypeTemp = TRIM(SPLIT_STRING(var_sql_statement, '|' ,2));



				SET v_TypeID = CAST(TRIM(SPLIT_STRING(v_TypeTemp, '^' ,1)) AS UNSIGNED INTEGER);



				SET v_Type = TRIM(SPLIT_STRING(v_TypeTemp, '^' ,2));



				#SELECT (CONCAT('v_TypeTemp=', v_TypeTemp, ",v_TypeID=", v_TypeID, ",v_Type=",v_Type));



				



				SET v_ModelTemp = TRIM(SPLIT_STRING(var_sql_statement, '|' ,3));



				SET v_ModelID = CAST(TRIM(SPLIT_STRING(v_ModelTemp, '^' ,1)) AS UNSIGNED INTEGER);



				SET v_Model = TRIM(SPLIT_STRING(v_ModelTemp, '^' ,2));



				#SELECT (CONCAT('v_ModelTemp=', v_ModelTemp, ",v_ModelID=", v_ModelID, ",v_Model=",v_Model));



			



				# AVAILABLE



				SET TAvailable = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 1, "|", "0");



				CALL spViewCount("Search", "Terminal Count By Status", v_SearchValue, @p_outCount);



				SET TAvailable = @p_outCount;



				



				# INSTALLED



				SET TInstalled = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 7, "|", v_ClientID);



				CALL spViewCount("Search", "Terminal Count By Status", v_SearchValue, @p_outCount);



				SET TInstalled = @p_outCount;



				



				# ALLOCATED



				SET TAllocated = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 2, "|", "0");



				CALL spViewCount("Search", "Terminal Count By Status", v_SearchValue, @p_outCount);



				SET TAllocated = @p_outCount;



				



				# DISPATCH



				SET TDispatch = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 8, "|", '0');



				CALL spViewCount("Search", "Terminal Count By Status", v_SearchValue, @p_outCount);



				SET TDispatch = @p_outCount;



				



				# DEFECTIVE



				SET TDefective = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 4, "|", "0");



				CALL spViewCount("Search", "Terminal Count By Status", v_SearchValue, @p_outCount);



				SET TDefective = @p_outCount;



				



				# LOST



				SET TLost = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 5, "|", "0");



				CALL spViewCount("Search", "Terminal Count By Status", v_SearchValue, @p_outCount);



				SET TLost = @p_outCount;



				



				# LOAN/BORROW



				SET TBorrow = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 6, "|", "0");



				CALL spViewCount("Search", "Terminal Count By Status", v_SearchValue, @p_outCount);



				SET TBorrow = @p_outCount;



				



				# PULLOUT



				SET TPullout = 0;



				SET v_SearchValue = CONCAT(v_Location, "|", v_TypeID, "|", v_ModelID, "|", 4, "|", "SUCCESS");



				CALL spViewCount("Search", "Terminal Count By Service JobType", v_SearchValue, @p_outCount);



				SET TPullout = @p_outCount;



				



				IF (v_LocationID > 0 && v_TypeID > 0 && v_ModelID > 0)



				THEN



					SET TTotal = TAvailable + TInstalled + TAllocated + TDispatch + TDefective + TLost + TBorrow;



					



					# Select/Insert



					SET sQuery = "";



					SET sQuery = CONCAT("(", 



					"'", v_LocationID, "',", 



					"'", v_Location, "',",	



					"'", v_TypeID, "',",			



					"'", v_Type, "',", 	



					"'", v_ModelID, "',", 			



					"'", v_Model, "',", 



					"'", TAvailable, "',", 



					"'", TInstalled, "',", 



					"'", TAllocated, "',", 



					"'", TDispatch, "',", 



					"'", TPullout, "',", 



					"'", TBorrow, "',",



					"'", TLost, "',", 



					"'", TDefective, "',", 							



					"'", TTotal, "'", ")"



					);



					



					#SELECT (CONCAT('Insert->sQuery=', sQuery));



						



					SET @QUERY = "";



					SET @QUERY = CONCAT('INSERT INTO tblterminalsummary(LocationID, Location, TerminalTypeID, TerminalType, TerminalModelID, TerminalModel, TAvailable, TInstalled, 



											   TAllocated, TDispatch, TPullout, TBorrow, TLost, TDefective, TTotal)



					    VALUES ', sQuery);



					



					#SELECT (CONCAT('@QUERY=', @QUERY));   



					    



					# Execute Query 



					PREPARE QUERY FROM @QUERY;



					EXECUTE QUERY;



				end if;								



			END IF;	







			IF (v_finished = 1)



			THEN



				LEAVE GET_RECORD;



			END IF;



			



		END LOOP GET_RECORD;



		



		CLOSE C1;



	END IF;     



END IF; 







COMMIT;   



       



END */$$
DELIMITER ;

/* Procedure structure for procedure `spGenerateTimeSheetDate` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGenerateTimeSheetDate` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGenerateTimeSheetDate`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

    IN p_SearchBy VARCHAR(50) /* = NULL */ ,

    IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

DECLARE var_sql_statement VARCHAR(1000);

DECLARE v_finished INT DEFAULT 0;

DECLARE v_ID INT;

DECLARE v_ParticularID INT;

DECLARE v_DepartmentID INT;

DECLARE v_Department VARCHAR(40);

DECLARE v_PositionID INT;

DECLARE v_FullName VARCHAR(100);



DECLARE v_TimeSheetID INT;

DECLARE v_TerminalID VARCHAR(10);

DECLARE v_Date TIME;

DECLARE v_TimeIn TIME;

DECLARE v_TimeOut TIME;

DECLARE v_THours VARCHAR(20);



DECLARE v_TTime INT;

DECLARE v_TimeStatus VARCHAR(40);



DECLARE v_HolidayID INT;

DECLARE v_Holiday VARCHAR(40);



DECLARE v_WorkTypeID INT;

DECLARE v_WorkType VARCHAR(40);

DECLARE v_isCheckTimeSheet INT;



DECLARE v_LeaveTypeID INT;

DECLARE v_LeaveType VARCHAR(40);



DECLARE v_ComputerName VARCHAR(40);

DECLARE v_DeviceIn VARCHAR(40);

DECLARE v_DeviceOut VARCHAR(40);



DECLARE v_ProcessedBy VARCHAR(45);    

DECLARE v_ProcessedDateTime VARCHAR(45);    



DECLARE v_outTSTerminalIDList VARCHAR(45);



DECLARE sQuery VARCHAR(1000);



DECLARE v_HoldDate DATE;

DECLARE v_StartDate DATE;

DECLARE v_EndDate DATE;



DECLARE v_DateFrom DATE;

DECLARE v_DateTo DATE;

DECLARE v_Day INT;

DECLARE v_isValidDate INT;

DECLARE v_outDateFlag INT;

DECLARE v_isExist INT;

DECLARE v_MissingTimeSheet INT;



DECLARE C1 CURSOR FOR

	SELECT

	ParticularID

	FROM 

	tblparticular 

	WHERE 

	(isActive = 1 AND isTimeSheet = 1);



DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      



SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);

SET v_TerminalID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INT);

SET v_StartDate = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS DATE);

SET v_EndDate = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS DATE);

SET v_MissingTimeSheet = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INT);



SET v_HoldDate = v_StartDate;



#SELECT (CONCAT('v_StartDate=', v_StartDate));

#SELECT (CONCAT('v_EndDate=', v_EndDate));



START TRANSACTION;



IF (p_StatementType = 'Generate')

THEN

	IF (p_SearchBy = 'TimeSheet')

	THEN

		OPEN C1;

		GET_RECORD: LOOP

			

			SET var_sql_statement = "";

			SET v_isValidDate = 0;

			FETCH C1 INTO var_sql_statement;

			#SELECT (CONCAT('var_sql_statement=', var_sql_statement));



			IF (LENGTH(var_sql_statement) > 0)

			THEN

				WHILE (v_StartDate <= v_EndDate) DO

					

					#SELECT (CONCAT("Loop:v_StartDate=", v_StartDate));

					

					# --------------------------------------------------------------------

					# Check here for valid day within a month. eg. oct 1-31, nov 1-30 ... 

					# --------------------------------------------------------------------

					SET v_Day = DAY(v_StartDate);					

					IF (v_Day > 25)

					THEN

						SET v_DateFrom = CAST(CONCAT(YEAR(v_StartDate), "-", MONTH(v_StartDate), "-", DAY(v_StartDate)) AS DATE);

						SET v_DateTo = CAST(CONCAT(YEAR(v_StartDate), "-", MONTH(v_StartDate), "-", DAY(LAST_DAY(v_StartDate))) AS DATE);

						

						SELECT (IF(v_StartDate BETWEEN v_DateFrom AND v_DateTo, 1, 0)) INTO v_outDateFlag;

						SET v_isValidDate = v_outDateFlag;

					ELSE

						SET v_isValidDate = 1;

					END IF;

					

					IF (v_isValidDate > 0)

					THEN

						# ------------------------------------------------------------

						# Get Particular Info

						# ------------------------------------------------------------

						CALL spGetInfoDetail("Search", "Particular", var_sql_statement, @p_outResult);

						#SELECT (CONCAT("spGetInfoDetail->Particular=", @p_outResult));

						

						SET v_ParticularID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,1)) AS UNSIGNED INTEGER);

						SET v_FullName = TRIM(SPLIT_STRING(@p_outResult, '|' ,2));

						SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,3)) AS UNSIGNED INTEGER);

						SET v_Department = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));

						SET v_PositionID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,5)) AS UNSIGNED INTEGER);					

						

						# ------------------------------------------------------------	

						# Get TimeSheet Info

						# ------------------------------------------------------------

						CALL spGetInfoDetail("Search", "TimeSheet", (CONCAT(v_ParticularID, "|", v_StartDate)), @p_outResult);

						#SELECT (CONCAT("spGetInfoDetail->TimeSheet=", @p_outResult));

						IF (LENGTH(@p_outResult) > 0)

						THEN						

							

							#SET v_ParticularID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,1)) AS UNSIGNED INTEGER);

							SET v_TimeSheetID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

							SET v_TerminalID = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));

							SET v_Date = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,4)) AS DATE);

							SET v_TimeIn = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,5)) AS TIME);

							SET v_TimeOut = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,6)) AS TIME);

							SET v_THours = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));

							SET v_TTime = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,8)) AS UNSIGNED INTEGER);

							SET v_DeviceIn = TRIM(SPLIT_STRING(@p_outResult, '|' ,9));

							SET v_DeviceOut = TRIM(SPLIT_STRING(@p_outResult, '|' ,10));

							SET v_ProcessedBy = TRIM(SPLIT_STRING(@p_outResult, '|' ,11));

							SET v_ProcessedDateTime = TRIM(SPLIT_STRING(@p_outResult, '|' ,12));

							SET v_outTSTerminalIDList = TRIM(SPLIT_STRING(@p_outResult, '|' ,13));

						ELSE

							SET v_TimeSheetID = 0;

							SET v_TerminalID = 0;

							SET v_Date = 0;

							SET v_TimeIn = 0;

							SET v_TimeOut = 0;

							SET v_THours = "-";

							SET v_TTime = 0;

							SET v_DeviceIn = "-";

							SET v_DeviceOut = "-";

							SET v_ProcessedBy = "-";

							SET v_ProcessedDateTime = "-";

							SET v_outTSTerminalIDList = "-";

						END IF;

						

						# ------------------------------------------------------------	

						# Get Leave Info

						# ------------------------------------------------------------

						CALL spGetInfoDetail("Search", "Particular Leave", (CONCAT(v_ParticularID, "|", v_StartDate)), @p_outResult);

						#SELECT (CONCAT("spGetInfoDetail->Particular Leave=", @p_outResult));

						IF (LENGTH(@p_outResult) > 0)

						THEN																	

							SET v_LeaveTypeID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,1)) AS UNSIGNED INTEGER);

							SET v_LeaveType = TRIM(SPLIT_STRING(@p_outResult, '|' ,2));

							SET v_ProcessedBy = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));

							SET v_ProcessedDateTime = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));

							

						ELSE

							SET v_LeaveTypeID = 0;						

							SET v_LeaveType = "-";	

											

						END IF;

						

						# ------------------------------------------------------------	

						# Get Work Arrangement Info

						# ------------------------------------------------------------

						CALL spGetInfoDetail("Search", "Particular Work Arrangement", (CONCAT(v_ParticularID, "|", v_StartDate)), @p_outResult);

						#SELECT (CONCAT("spGetInfoDetail->Particular Work Arrangement=", @p_outResult));

						IF (LENGTH(@p_outResult) > 0)

						THEN																	

							SET v_WorkTypeID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,1)) AS UNSIGNED INTEGER);

							SET v_WorkType = TRIM(SPLIT_STRING(@p_outResult, '|' ,2));

							SET v_isCheckTimeSheet = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,3)) AS UNSIGNED INTEGER);

							

						ELSE

							SET v_WorkTypeID = 0;						

							SET v_WorkType = "-";	

							SET v_isCheckTimeSheet = 0;					

						END IF;

							

						# ------------------------------------------------------------

						# Get Holiday Info

						# ------------------------------------------------------------

						CALL spGetInfoDetail("Search", "Holiday", v_StartDate, @p_outResult);

						#SELECT (CONCAT("spGetInfoDetail->Holiday=", @p_outResult));

						IF (LENGTH(@p_outResult) > 0)					

						THEN

						    SET v_HolidayID = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,1)) AS UNSIGNED INTEGER);

						    SET v_Holiday = TRIM(SPLIT_STRING(@p_outResult, '|' ,2));

						ELSE

						    SET v_HolidayID = 0;

						    SET v_Holiday = "-";

						END IF;

						

						# Check Time Status					

						#SELECT (CONCAT("v_TTime=", v_TTime, ", v_WorkTypeID=", v_WorkTypeID));		

						SET v_TimeStatus = "-";					

						IF (v_LeaveTypeID > 0)

						THEN

							SET v_TimeStatus = "-";

							SET v_WorkTypeID = v_LeaveTypeID;						

							SET v_WorkType = v_LeaveType;

						ELSE

							IF (v_WorkTypeID > 0)

							THEN

								# include for missing timesheet

								IF (v_isCheckTimeSheet > 0)

								THEN

									SET v_WorkTypeID = 0;

								END IF;

								

							END IF;

							

							# check for time status

							IF (v_TTime >= 8)

							THEN

								SET v_TimeStatus = "-";

							ELSE

								IF (v_TimeIn > 0 AND v_TimeOut > 0)

								THEN

									SET v_TimeStatus = "UNDERTIME";

								ELSE

									SET v_TimeStatus = "-";

								END IF;

							END IF;

							

							

						END IF;

						

						IF (v_TimeIn = v_TimeOut)

						THEN

							SET v_TimeStatus = "-";

							SET v_TimeOut = 0;

							SET v_THours = "-";

							SET v_TTime = 0;

						END IF;

																

						SET sQuery = "";

						SET sQuery = CONCAT("(", 

						"'", v_StartDate, "',", 

						"'", v_ParticularID, "',", 

						"'", v_FullName, "',", 

						"'", v_DepartmentID, "',", 

						"'", v_Department, "',", 

						"'", v_PositionID, "',", 

						"'", v_TerminalID, "',", 

						"'", v_TimeIn, "',", 

						"'", v_TimeOut, "',", 

						"'", v_THours, "',",

						"'", v_TTime, "',", 

						"'", v_TimeStatus, "',", 

						"'", v_Holiday, "',",

						"'", v_WorkTypeID, "',",

						"'", v_WorkType, "',", 

						"'", v_TimeSheetID, "',", 

						"'", v_DeviceIn, "',", 

						"'", v_DeviceOut, "',", 

						"'", v_ProcessedBy, "',", 

						"'", v_ProcessedDateTime, "',", 

						"'", v_outTSTerminalIDList, "',", 				

						"'", v_StartDate, "'", ")"

						);

						

						#SELECT (CONCAT('Insert->sQuery=', sQuery));

						

						SET @QUERY = "";

						SET @QUERY = CONCAT('INSERT INTO tbltimesheetdetailtemp(TimeSheetDate, ParticularID, FullName, DepartmentID, Department, PositionID, 

								      TerminalID, TimeIn, TimeOut, THours, TTime, TimeStatus,

								      Holiday, 

								      WorkTypeID, WorkType,

								      TimeSheetID, 

								      DeviceIn, DeviceOut,

								      ProcessedBy, ProcessedDateTime,

								      TSTerminalIDList,							   

								      TSDate)

						    VALUES ', sQuery);

						#SELECT (CONCAT('@QUERY=', @QUERY));   

						    

						# Execute Query 

						PREPARE QUERY FROM @QUERY;

						EXECUTE QUERY;

					

					END IF;

							

					SET v_StartDate = DATE_ADD(v_StartDate, INTERVAL 1 DAY);

					

					#SELECT (CONCAT('Loop:v_Date=', v_Date));

					#SELECT (CONCAT('Loop:v_StartDate=', v_StartDate));



				END WHILE;

				

				SET v_StartDate = v_HoldDate;

			END IF;	



			IF (v_finished = 1)

			THEN

				LEAVE GET_RECORD;

			END IF;

			

		END LOOP GET_RECORD;

		CLOSE C1;

	END IF;     

END IF; 



COMMIT;   

       

END */$$
DELIMITER ;

/* Procedure structure for procedure `spGenerateZoneUpdate` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGenerateZoneUpdate` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGenerateZoneUpdate`()
BEGIN

    ##--------------------------------------------------------------------
    -- Variables
    ##--------------------------------------------------------------------
    DECLARE vDone INT DEFAULT 0;

    DECLARE vParticularID INT;
    DECLARE vAddress TEXT;
    DECLARE vRegion VARCHAR(255);
    DECLARE vProvince VARCHAR(255);

    DECLARE vZoneID INT;

    ##--------------------------------------------------------------------
    -- Cursor
    ##--------------------------------------------------------------------
    DECLARE cur CURSOR FOR
        SELECT
            ParticularID,
            Address,
            Region,
            Province
        FROM tblparticular
        WHERE ParticularTypeID = 1
          AND isActive = 1
        ORDER BY ParticularID;

    #--------------------------------------------------------------------
    -- Handler
    #--------------------------------------------------------------------
    DECLARE CONTINUE HANDLER FOR NOT FOUND
        SET vDone = 1;

    #--------------------------------------------------------------------
    -- Temporary Table
    #--------------------------------------------------------------------
    DROP TEMPORARY TABLE IF EXISTS tmpUpdates;

    CREATE TEMPORARY TABLE tmpUpdates
    (
        LineNo INT AUTO_INCREMENT PRIMARY KEY,
        pUpdate LONGTEXT
    );

    #--------------------------------------------------------------------
    -- Start Cursor
    #--------------------------------------------------------------------
    OPEN cur;

    read_loop: LOOP

        FETCH cur INTO
            vParticularID,
            vAddress,
            vRegion,
            vProvince;

        IF vDone THEN
            LEAVE read_loop;
        END IF;

        SET @search = funcNormalizeLocation(
            CONCAT(
                IFNULL(vAddress,''),
                ',',
                IFNULL(vRegion,''),
                ',',
                IFNULL(vProvince,'')
            )
        );

        SET vZoneID = NULL;

        SELECT
            z.ZoneID
        INTO
            vZoneID
        FROM tblzoning z
        WHERE
               funcContainsWord(@search, z.CityMunicipal)
            OR funcContainsWord(@search, z.Area)
            OR funcContainsWord(@search, z.ZoneName)
        ORDER BY

              (
                    IF(funcContainsWord(@search, z.CityMunicipal),100,0)
                  + IF(funcContainsWord(@search, z.Area),50,0)
                  + IF(funcContainsWord(@search, z.ZoneName),25,0)
              ) DESC,

              funcContainsWord(@search, z.CityMunicipal) DESC,
              funcContainsWord(@search, z.Area) DESC,
              funcContainsWord(@search, z.ZoneName) DESC,

              LENGTH(funcNormalizeLocation(z.CityMunicipal)) DESC,

              z.ZoneID
        LIMIT 1;

        IF vZoneID IS NOT NULL THEN

            INSERT INTO tmpUpdates(pUpdate)
            VALUES
            (
                CONCAT(
                    'UPDATE tblparticular ',
                    'SET ZoneID = ',
                    vZoneID,
                    ' WHERE ParticularID = ',
                    vParticularID,
                    ';'
                )
            );

        END IF;

    END LOOP;

    CLOSE cur;

    ##--------------------------------------------------------------------
    -- Result
    ##--------------------------------------------------------------------
    SELECT
        pUpdate
    FROM
        tmpUpdates
    ORDER BY
        LineNo;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spGetCount` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGetCount` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGetCount`(  
    IN p_StatementType VARCHAR(30) /* = NULL */ ,
    IN p_SearchBy VARCHAR(255) /* = NULL */ ,
    IN p_SearchValue VARCHAR(255) /* = NULL */ ,
    OUT p_outID INTEGER
)
BEGIN
DECLARE v_ID INT;
DECLARE v_ClientID INT;
DECLARE v_Name VARCHAR(45);

DECLARE v_JobType INT;
DECLARE v_ActionMade VARCHAR(30);
DECLARE v_Year VARCHAR(30);
DECLARE v_Month VARCHAR(30);

DECLARE v_ServiceResult VARCHAR(100); # eg. SUCCESS/NEGATIVE
DECLARE v_IncludeBillable VARCHAR(45);
DECLARE v_FSRMode VARCHAR(45);

DECLARE p_WHERE LONGTEXT;
DECLARE p_ORDERBY LONGTEXT;
DECLARE p_GROUPBY LONGTEXT;
DECLARE p_SQL LONGTEXT;
DECLARE p_TempQuery LONGTEXT;
DECLARE p_INSERT LONGTEXT;
    
SET v_ID = 0;
SET p_outID = 0;
IF (p_StatementType = 'Search')
THEN
	IF (p_SearchBy = 'Service Count')
	THEN
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_FSRMode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_Year = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_Month = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
			
			SET p_WHERE = '';
			SET p_SQL = '';
			
			SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
				    'COUNT(*) AS v_ID ',
				    'FROM tblfsrdetail AS a '
				    );
			
			IF (v_JobType > 0)
			THEN
				SET p_SQL = CONCAT(
						p_SQL, 'WHERE', ' ',
						'a.JobType = ', v_JobType, ' '
					    );
			END IF;
			
			IF (v_ClientID > 0)
			THEN
				SET p_SQL = CONCAT(
						p_SQL,
						'AND a.ClientID = ', v_ClientID, ' '
					    );
			END IF;
			    
			IF v_ServiceResult != '[NOT SPECIFIED]'
			THEN
				SET p_SQL = CONCAT(
						p_SQL,
						'AND a.ActionMade = ', ADD_SINGLEQUOTE(v_ServiceResult), ' '
					    ); 
			END IF;
			
			IF (LENGTH(v_IncludeBillable) > 0 && v_IncludeBillable != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_IncludeBillable, "BILLABLE") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND a.isBillable > 0', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND a.isBillable = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (LENGTH(v_FSRMode) > 0 && v_FSRMode != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_FSRMode, "DIGITAL FSR") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND a.MobileID > 0', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND a.MobileID = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (LENGTH(v_Year) > 0)
			THEN
				SET p_SQL = CONCAT(
				p_SQL,
				'AND YEAR(a.FSRDate) = ', v_Year, ' '
				); 
			END IF;
			
			IF (LENGTH(v_Month) > 0)
			THEN
				SET p_SQL = CONCAT(
				p_SQL,
				'AND MONTH(a.FSRDate) = ', v_Month, ' '
				); 
			END IF;
			
			# End with ;
			SET p_SQL = CONCAT(p_SQL,';'); 
			
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			DROP TEMPORARY TABLE IF EXISTS tbltemp;
			SET p_TempQuery = '';
			SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltemp (xID VARCHAR(45) NOT NULL)');
			SET @QUERY = p_TempQuery;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
	END IF;
	
	SET p_INSERT = '';
	SET p_INSERT = 'INSERT INTO tbltemp (xID)';
	SET @QUERY = '';	
	SET @QUERY = CONCAT(p_INSERT, p_SQL);
	# Execute Query 
	PREPARE QUERY FROM @QUERY;
	EXECUTE QUERY;
	SELECT xID INTO v_ID 
	FROM tbltemp;
	
	IF (v_ID > 0)
	THEN
		SET p_outID = v_ID;
	ELSE
		SET p_outID = 0;
	END IF;
		
END IF;
        
END */$$
DELIMITER ;

/* Procedure structure for procedure `spGetID` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGetID` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGetID`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

    IN p_SearchBy VARCHAR(255) /* = NULL */ ,

    IN p_SearchValue VARCHAR(255) /* = NULL */ ,

    OUT p_outID INTEGER

)
BEGIN

DECLARE v_ID INT;

DECLARE v_Name VARCHAR(45);

DECLARE p_WHERE LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

DECLARE p_TempQuery LONGTEXT;

DECLARE p_INSERT LONGTEXT;

    

SET v_ID = 0;

SET p_outID = 0;

IF (p_StatementType = 'Search')

THEN

	IF (p_SearchBy = 'ClientID')

	THEN

		SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET p_SQL = '';	

		SET p_SQL = CONCAT(p_SQL, 'SELECT');

		SET p_SQL = CONCAT(p_SQL, ' ', 'ParticularID AS v_ID FROM tblparticular WHERE ParticularTypeID = 2 AND `Name`=', v_Name);				

		DROP TEMPORARY TABLE IF EXISTS tbltemp;

		SET p_TempQuery = '';

		SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltemp (xID VARCHAR(45) NOT NULL)');

		SET @QUERY = p_TempQuery;

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

	ELSEIF (p_SearchBy = 'TerminalModelID')	

	THEN	

		SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET p_SQL = '';	

		SET p_SQL = CONCAT(p_SQL, 'SELECT');

		SET p_SQL = CONCAT(p_SQL, ' ', 'TerminalModelID AS v_ID FROM tblterminalmodel WHERE `Description`=', v_Name);				

		DROP TEMPORARY TABLE IF EXISTS tbltemp;

		SET p_TempQuery = '';

		SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltemp (xID VARCHAR(45) NOT NULL)');

		SET @QUERY = p_TempQuery;

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

	END IF;

	

	SET p_INSERT = '';

	SET p_INSERT = 'INSERT INTO tbltemp (xID)';

	SET @QUERY = '';	

	SET @QUERY = CONCAT(p_INSERT, p_SQL);

	# Execute Query 

	PREPARE QUERY FROM @QUERY;

	EXECUTE QUERY;

	SELECT xID INTO v_ID 

	FROM tbltemp;

	

	IF (v_ID > 0)

	THEN

		SET p_outID = v_ID;

	ELSE

		SET p_outID = 0;

	END IF;

		

END IF;

        

END */$$
DELIMITER ;

/* Procedure structure for procedure `spGetInfoDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGetInfoDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGetInfoDetail`(  

IN p_StatementType VARCHAR(30) /* = NULL */ ,

IN p_SearchBy VARCHAR(300) /* = NULL */ ,

IN p_SearchValue LONGTEXT /* = NULL */ ,

OUT p_outResult LONGTEXT



)
BEGIN

DECLARE v_ID INTEGER;

DECLARE v_Date DATE;

DECLARE v_outResult LONGTEXT;

DECLARE v_HolidayDate VARCHAR(40);

DECLARE v_ParticularID INTEGER;  

DECLARE v_Name VARCHAR(255);

DECLARE v_Description VARCHAR(40);

DECLARE v_ClientID INTEGER;

DECLARE v_MerchantID INTEGER;

DECLARE v_IRIDNo INTEGER;

DECLARE v_ServiceNo INTEGER;

DECLARE v_FSRNo INTEGER;

DECLARE v_JobType INTEGER;

DECLARE v_IRNo VARCHAR(40);

DECLARE v_TID VARCHAR(40);

DECLARE v_MID VARCHAR(40);

DECLARE v_RegionType INT;

DECLARE v_RegionID INT;

DECLARE v_DateFrom VARCHAR(45);

DECLARE v_DateTo VARCHAR(45);

DECLARE v_ActionMade VARCHAR(45);

DECLARE v_outTimeSheetTimeIn INTEGER;

DECLARE v_outTimeIn VARCHAR(20); 

DECLARE v_ouTimeSheetTimeOut INTEGER;

DECLARE v_outTimeOut VARCHAR(20); 

DECLARE v_outTerminalID VARCHAR(45); 

DECLARE v_outComputerName VARCHAR(45); 

DECLARE v_outDeviceIn VARCHAR(45);

DECLARE v_outDeviceOut VARCHAR(45);

DECLARE v_outProcessedBy VARCHAR(45);    

DECLARE v_TempProcessedBy VARCHAR(45);    

DECLARE v_outProcessedDateTime VARCHAR(45);

DECLARE v_TempProcessedDateTime VARCHAR(45);

DECLARE v_outTSTerminalIDIn VARCHAR(45);

DECLARE v_outTSTerminalIDOut VARCHAR(45);

DECLARE v_outTSTerminalIDList VARCHAR(45);

DECLARE v_outDateFrom VARCHAR(45);

DECLARE v_outDateTo VARCHAR(45); 

DECLARE v_Mode VARCHAR(45);

   

DECLARE v_SystemDate DATE;

DECLARE v_SystemTime TIME;



DECLARE v_UserName VARCHAR(45);

DECLARE v_Password VARCHAR(45);



DECLARE v_AuthKey VARCHAR(40);



# GetValue

DECLARE v_TableName TEXT;

DECLARE v_FieldName TEXT;

DECLARE v_FieldSearchKey TEXT;

DECLARE v_FieldSearchValue TEXT;

DECLARE v_UserID INTEGER;
DECLARE v_PrivacyID INTEGER;

DECLARE v_MSPNo INTEGER;

DECLARE p_WHERE LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

DECLARE p_TempQuery LONGTEXT;

DECLARE p_INSERT LONGTEXT;



IF (p_StatementType = 'Search')

THEN

IF (p_SearchBy = 'Particular')

    THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	#SELECT (CONCAT("spGetInfoDetail->v_ID=", v_ID));

	

	SELECT   

	CONCAT(
	a.ParticularID, "|", 

	a.`Name`, "|", 

	a.DepartmentID, "|", 

	b.Description, "|", 

	a.PositionID, "|",

	IFNULL(a.Email,"-"), "|",
	
	IFNULL(a.Mobile,"-"), "|",
	
	IFNULL(c.Description,"-")
	
	) INTO v_outResult

	FROM tblparticular a

	LEFT JOIN tbldepartment AS b ON a.DepartmentID = b.DepartmentID
	LEFT JOIN tblposition AS c ON a.PositionID = c.PositionID		

	WHERE (a.ParticularID = v_ID);



ELSEIF (p_SearchBy = 'Particular By Name')

    THEN

	SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

	

	#SELECT (CONCAT("spGetInfoDetail->v_ID=", v_ID));

	

	SELECT   

	CONCAT(a.ParticularID, "|", 

	a.`Name`, "|", 

	a.DepartmentID, "|", 

	b.Description, "|", 

	a.PositionID, "|",

	IFNULL(a.Email,"-")) INTO v_outResult

	FROM tblparticular a

	LEFT JOIN tbldepartment AS b ON a.DepartmentID = b.DepartmentID		

	WHERE (a.`Name` = v_Name);

		

ELSEIF (p_SearchBy = 'TimeSheet')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	SET v_Date = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS DATE);

		

	#SELECT (CONCAT("spGetInfoDetail->v_ID=", v_ID, ",v_Date=",v_Date));	

	#SELECT (CONCAT("spGetInfoDetail->v_ID=", v_ID));

	#SELECT (CONCAT("spGetInfoDetail->v_Date=", v_Date));

	

	SELECT 

	TimeSheetID, `TimeIn`, IFNULL(Device, "-") AS Device, IFNULL(ProcessedBy, "-") AS ProcessedBy, IFNULL(ProcessedDateTime, "-") AS ProcessedDateTime, TerminalID

	INTO v_outTimeSheetTimeIn, v_outTimeIn, v_outDeviceIn, v_outProcessedBy, v_outProcessedDateTime, v_outTSTerminalIDIn

	FROM tbltimesheetdetail

	WHERE TimeSheetID = (SELECT MIN(TimeSheetID) FROM tbltimesheetdetail WHERE ParticularID = v_ID AND `Date` = v_Date) LIMIT 1;

	

	SELECT 

	TimeSheetID, `TimeIn`, IFNULL(Device, "-") AS Device, IFNULL(ProcessedBy, "-") AS ProcessedBy, IFNULL(ProcessedDateTime, "-") AS ProcessedDateTime, TerminalID

	INTO v_outTimeSheetTimeIn, v_outTimeOut, v_outDeviceOut, v_outProcessedBy, v_outProcessedDateTime, v_outTSTerminalIDOut

	FROM tbltimesheetdetail

	WHERE TimeSheetID = (SELECT MAX(TimeSheetID) FROM tbltimesheetdetail WHERE ParticularID = v_ID AND `Date` = v_Date) LIMIT 1;

	

	SET v_outTSTerminalIDList = CONCAT(v_outTSTerminalIDIn, "^", v_outTSTerminalIDOut);

	#SELECT (CONCAT("v_outTSTerminalIDList=", v_outTSTerminalIDList));

	#SELECT (CONCAT("v_outTimeIn=", v_outTimeIn));

	#SELECT (CONCAT("v_outTimeOut=", v_outTimeOut));

	

	#SELECT (CONCAT("v_outProcessedBy=", v_outProcessedBy));

	#SELECT (CONCAT("v_outProcessedDateTime=", v_outProcessedDateTime));

	

	IF (LENGTH(v_outProcessedBy) > 5)

	THEN			

		SET v_TempProcessedBy = v_outProcessedBy;

	ELSE	

		SET v_TempProcessedBy = "-";

	END IF;

	

	IF (LENGTH(v_outProcessedDateTime) > 5)

	THEN			

		SET v_TempProcessedDateTime = v_outProcessedDateTime;

	ELSE

		SET v_TempProcessedDateTime = "-";

	END IF;

	

	#SELECT (CONCAT("v_TempProcessedBy=", v_TempProcessedBy));

	#SELECT (CONCAT("v_TempProcessedDateTime=", v_TempProcessedDateTime));

	

	IF ((LENGTH(v_outTimeIn) > 0) OR (LENGTH(v_outTimeOut) > 0))

	THEN

		SET v_outResult = CONCAT(v_ID, "|", "0", "|", "x", "|", v_Date, "|", v_outTimeIn, "|", v_outTimeOut, "|",

					(CONCAT(MOD(HOUR(TIMEDIFF(v_outTimeIn,v_outTimeOut)), 24), 'h', ' ', MINUTE(TIMEDIFF(v_outTimeIn,v_outTimeOut)), 'm')),

	                               "|", (MOD(HOUR(TIMEDIFF(v_outTimeIn,v_outTimeOut)), 24)), "|", v_outDeviceIn, "|", v_outDeviceOut, "|", v_TempProcessedBy, "|", v_TempProcessedDateTime, "|", v_outTSTerminalIDList);

	                               

	        #SELECT CONCAT("v_outResult=", v_outResult);

	END IF;

			

ELSEIF (p_SearchBy = 'Holiday')

THEN		

	SET v_HolidayDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

	SET v_HolidayDate = SUBSTRING(v_HolidayDate, 6, 5);

					

	#SELECT (CONCAT("spGetInfoDetail->v_HolidayDate=", v_HolidayDate));

	

	SELECT   

	CONCAT(HolidayID, "|", 

	      DESCRIPTION

	) INTO v_outResult

	FROM tblholiday

	WHERE (isActive = 1 AND HolidayDate = v_HolidayDate) LIMIT 1;

	

ELSEIF (p_SearchBy = 'Particular Work Arrangement')

THEN



	SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	SET v_Date = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			





	SELECT 

	CONCAT(b.WorkTypeID, "|", 		      

	      b.Description, "|",

	      b.isCheckTimeSheet

	) INTO v_outResult

	FROM tblworkarrangement a

	LEFT JOIN tblworktype AS b ON a.WorkTypeID = b.WorkTypeID

	WHERE a.ParticularID = v_ParticularID AND (v_Date BETWEEN a.DateFrom AND a.DateTo) LIMIT 1;

	

ELSEIF (p_SearchBy = 'Particular Leave')

THEN



	SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	SET v_Date = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			





	SELECT 

	CONCAT(b.LeaveTypeID, "|", 		      	      IFNULL_STRING_ONLY(b.Description), "|",	      IFNULL_STRING_ONLY(a.ProcessedBy), "|",		      IFNULL_STRING_ONLY(a.ProcessedDateTime)

	) INTO v_outResult

	FROM tblleavemovement a

	LEFT JOIN tblleavetype AS b ON a.LeaveTypeID = b.LeaveTypeID

	WHERE a.ParticularID = v_ParticularID AND (v_Date BETWEEN a.DateFrom AND a.DateTo) LIMIT 1;

	

ELSEIF (p_SearchBy = 'Server Date/Time')

THEN



	SET v_SystemDate = CURRENT_DATE;

	SET v_SystemTime = IF(HOUR(CURRENT_TIME) > 12, (DATE_SUB(CURRENT_TIME, INTERVAL 12 HOUR)), CURRENT_TIME);





	SET v_outResult = CONCAT(v_SystemDate, "|", v_SystemTime);		



ELSEIF (p_SearchBy = 'ERM Date Range')

THEN	

	SELECT FSRDate INTO v_outDateFrom FROM tblermdetailtemp ORDER BY FSRNo ASC LIMIT 1;

	SELECT FSRDate INTO v_outDateTo FROM  tblermdetailtemp ORDER BY FSRNo DESC LIMIT 1;

	

	SET v_outResult = CONCAT(v_outDateFrom, "|", v_outDateTo);



ELSEIF (p_SearchBy = 'Merchant Info')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

	

	IF (v_IRIDNo > 0) THEN # ROCKY -- ADD CHECKING FOR PARTICULAR RETRIEVAL

								

		SELECT   

		CONCAT(a.ParticularID, "|", 

		IFNULL_STRING_ONLY(a.`Name`), "|", 

		IFNULL_STRING_ONLY(a.Address), "|", 

		IFNULL_STRING_ONLY(funcGetDesc("Search", "Region Detail", a.RegionID)), "|", 

		IFNULL_STRING_ONLY(funcGetDesc("Search", "Region", a.RegionType)), "|", 

		IFNULL_STRING_ONLY(funcGetDesc("Search", "City", a.CityID)), "|", 

		IFNULL_STRING_ONLY(a.ContactPerson), "|",

		IFNULL_STRING_ONLY(a.TelNo), "|",

		IFNULL_STRING_ONLY(a.Mobile), "|",

		IFNULL(a.Email,"-"), "|",

		IFNULL_STRING_ONLY(b.TID), "|",

		IFNULL_STRING_ONLY(b.MID), "|",

		IFNULL_STRING_ONLY(b.PrimaryNum), "|",

		IFNULL_STRING_ONLY(b.SecondaryNum), "|",

		IFNULL_STRING_ONLY(b.AppVersion), "|",

		IFNULL_STRING_ONLY(b.AppCRC), "|",

		IFNULL_NUMERIC(b.IRIDNo), "|",

		IFNULL_STRING_ONLY(b.IRNo), "|",

		IFNULL_FORMAT_DATE(b.IRDate), "|",

		IFNULL_FORMAT_DATE(b.InstallationDate), "|",

		IFNULL_STRING_ONLY(b.POS_TYPE), "|",

		IFNULL_STRING_ONLY(b.OTHER_SPECIAL_INSTRUCTION), "|",

		IFNULL_NUMERIC((SELECT xTable.RentalFeeID FROM tblpr_rentalfee xTable WHERE xTable.QueryString = b.POS_TYPE LIMIT 1)), "|",

		IFNULL_STRING_ONLY((SELECT xTable.Description FROM tblpr_rentalfee xTable WHERE xTable.QueryString = b.POS_TYPE LIMIT 1)), "|",

		IFNULL_DECIMAL((SELECT xTable.RentalFee FROM tblpr_rentalfee xTable WHERE xTable.QueryString = b.POS_TYPE LIMIT 1)), "|", 

		IFNULL_STRING_ONLY(b.SET_UP), "|",

		IFNULL_STRING_ONLY(b.REQUEST_FOR), "|",

		IFNULL_STRING_ONLY(b.AnyComments), "|",

		IFNULL_STRING_ONLY(b.Remarks), "|",

		JSON_OBJECT('profile_info', b.profile_info), "|",

		JSON_OBJECT('rawdata_info', b.rawdata_info), "|",
		
		IFNULL_NUMERIC(b.IRStatus), "|",
	
		IFNULL_STRING_ONLY(funcGetDesc("Search", "Service Status", b.IRStatus)), "|",
		
		IFNULL_STRING_ONLY(b.REQUESTOR), "|",
		
		JSON_OBJECT('profile_config_info', a.profile_config_info), "|",
		
		IFNULL_STRING_ONLY(funcGetDesc("Search", "Type", b.RequestTypeID)), "|",
		
		IFNULL_NUMERIC(a.ZoneID), "|", 
		
		IFNULL_NUMERIC(b.ClientID), "|", 
		
		IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", b.ClientID))

		) INTO v_outResult

		FROM tblparticular a

		LEFT JOIN tblirdetail AS b ON a.ParticularID = b.ParticularID	

		WHERE (a.ParticularID = v_ID AND b.IRIDNo = v_IRIDNo);

	

	ELSE

	

		SELECT   

		CONCAT(a.ParticularID, "|", 

		IFNULL_STRING_ONLY(a.`Name`), "|", 

		IFNULL_STRING_ONLY(a.Address), "|", 

		IFNULL_STRING_ONLY(a.Province), "|", 

		IFNULL_STRING_ONLY(a.Region), "|", 

		IFNULL_STRING_ONLY(funcGetDesc("Search", "City", a.CityID)), "|",

		IFNULL_STRING_ONLY(a.ContactPerson), "|",

		IFNULL_STRING_ONLY(a.TelNo), "|",

		IFNULL_STRING_ONLY(a.Mobile), "|",

		IFNULL(a.Email,"-")) INTO v_outResult

		FROM tblparticular a	

		WHERE (a.ParticularID = v_ID);

		

	END IF;



ELSEIF (p_SearchBy = 'Client Info')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT   

	CONCAT(a.ParticularID, "|", 

	IFNULL_STRING_ONLY(a.`Name`), "|", 

	IFNULL_STRING_ONLY(a.Address), "|", 

	IFNULL_STRING_ONLY(a.Province), "|", 

	IFNULL_STRING_ONLY(a.Region), "|", 

	IFNULL_STRING_ONLY(funcGetDesc("Search", "City", a.CityID)), "|", 

	IFNULL_STRING_ONLY(a.ContactPerson), "|",

	IFNULL_STRING_ONLY(a.TelNo), "|",

	IFNULL_STRING_ONLY(a.Mobile), "|",

	IFNULL(a.Email,"-"), "|",

	IFNULL(a.profile_config_info,"-"), "|",
	
	IFNULL(a.Code,"-")) INTO v_outResult

	FROM tblparticular a

	WHERE (a.ParticularID = v_ID);



ELSEIF (p_SearchBy = 'Service Provider Info')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT   

	CONCAT(a.ParticularID, "|", 

	IFNULL_STRING_ONLY(a.`Name`), "|", 

	IFNULL_STRING_ONLY(a.Address), "|", 

	IFNULL_STRING_ONLY(a.Province), "|", 

	IFNULL_STRING_ONLY(a.Region), "|", 

	IFNULL_STRING_ONLY(funcGetDesc("Search", "City", a.CityID)), "|",  

	IFNULL_STRING_ONLY(a.ContactPerson), "|",

	IFNULL_STRING_ONLY(a.TelNo), "|",

	IFNULL_STRING_ONLY(a.Mobile), "|",

	IFNULL(a.Email,"-")) INTO v_outResult

	FROM tblparticular a

	WHERE (a.ParticularID = v_ID);

	

ELSEIF (p_SearchBy = 'FE Info')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT   

	CONCAT(a.ParticularID, "|", 

	IFNULL_STRING_ONLY(a.`Name`), "|", 

	IFNULL_STRING_ONLY(a.Address), "|", 

	IFNULL_STRING_ONLY(a.Province), "|", 

	IFNULL_STRING_ONLY(a.Region), "|", 

	IFNULL_STRING_ONLY(funcGetDesc("Search", "City", a.CityID)), "|", 

	IFNULL_STRING_ONLY(a.ContactPerson), "|",

	IFNULL_STRING_ONLY(a.TelNo), "|",

	IFNULL_STRING_ONLY(a.Mobile), "|",

	IFNULL(a.Email,"-")) INTO v_outResult

	FROM tblparticular a

	WHERE (a.ParticularID = v_ID);	



ELSEIF (p_SearchBy = 'Service Type Info')

THEN

	SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

	

	SELECT   

	CONCAT(a.ServiceTypeID, "|", 

	a.Description, "|", 

	a.Code, "|", 

	a.ServiceStatus, "|", 

	a.ServiceStatusDescription, "|", 

	a.JobType, "|", 

	a.JobTypeDescription, "|",

	a.ServiceJobTypeDescription) INTO v_outResult

	FROM tblservicetype a			

	WHERE (a.ServiceJobTypeDescription = v_Description);

	

ELSEIF (p_SearchBy = 'Terminal SN Info')

THEN	

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT   

	CONCAT(a.TerminalID, "|", 

	a.TerminalTypeID, "|", 

	a.TerminalModelID, "|", 

	a.TerminalBrandID, "|", 

	a.TerminalStatus, "|", 

	IFNULL_STRING_ONLY(a.TerminalStatusDescription), "|", 		

	IFNULL_STRING_ONLY(a.SerialNo), "|",

	IFNULL_STRING_ONLY(c.Code), "|",  

	IFNULL_STRING_ONLY(b.Description), "|", 

	IFNULL_STRING_ONLY(c.Description), "|", 

	IFNULL_STRING_ONLY(d.Description), "|", 

	IFNULL_STRING_ONLY(a.DeliveryDate), "|", 

	IFNULL_STRING_ONLY(a.ReceiveDate), "|", 

	IFNULL_STRING_ONLY(a.Location), "|", 

	IFNULL_STRING_ONLY(a.Allocation), "|", 

	IFNULL_STRING_ONLY(a.AssetType), "|", 

	IFNULL_STRING_ONLY(a.PONo), "|", 

	IFNULL_STRING_ONLY(a.InvNo), "|",

	IFNULL_STRING_ONLY(a.PartNo), "|",

	IFNULL_STRING_ONLY(a.Remarks), "|", 

	IFNULL_NUMERIC(a.LastServiceNo), "|",

	IFNULL_NUMERIC(a.LastIRIDNo), "|", 

	IFNULL_STRING_ONLY(a.DeliveryDate), "|", 

	IFNULL_STRING_ONLY(a.ReceiveDate), "|", 

	IFNULL_STRING_ONLY(a.ReleaseDate), "|", 

	IFNULL_NUMERIC(a.ParticularID), "|", 

	IFNULL_NUMERIC(e.isTerminalReleased), "|",

	IFNULL_NUMERIC(a.ClientID), "|",

	IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.ClientID)), "|",

	IFNULL_NUMERIC(a.TerminalStatus), "|", 

	IFNULL_STRING_ONLY(f.Description), "|", 
	
	IFNULL_STRING_ONLY(a.UpdatedAt), "|", 
	
	IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.UpdatedID)), "|",
	
	IFNULL_NUMERIC(a.LocationID), "|",
	
	IFNULL_STRING_ONLY(funcGetDesc("Search", "Location", a.LocationID))

	) INTO v_outResult

	FROM tblterminaldetail a

	LEFT JOIN tblterminaltype AS b ON a.TerminalTypeID = b.TerminalTypeID

	LEFT JOIN tblterminalmodel AS c ON a.TerminalModelID = c.TerminalModelID

	LEFT JOIN tblterminalbrand AS d ON a.TerminalBrandID = d.TerminalBrandID

	LEFT JOIN tbllocation AS e ON a.Location = e.Description

	LEFT JOIN tblterminalstatus AS f ON a.TerminalStatus = f.TerminalStatusID

	WHERE (a.TerminalID = v_ID);



ELSEIF (p_SearchBy = 'SIM SN Info')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT   

	CONCAT(a.SIMID, "|", 		

	a.SIMStatus, "|", 

	IFNULL_STRING_ONLY(a.SIMStatusDescription), "|", 		

	IFNULL_STRING_ONLY(a.SerialNo), "|",

	IFNULL_STRING_ONLY(funcGetDesc("Search", "SIMID Carrier", a.SIMID)), "|",

	IFNULL_STRING_ONLY(a.DeliveryDate), "|", 

	IFNULL_STRING_ONLY(a.ReceiveDate), "|", 

	IFNULL_STRING_ONLY(a.Location), "|", 

	IFNULL_STRING_ONLY(a.Allocation), "|", 

	IFNULL_STRING_ONLY(a.Remarks), "|", 

	IFNULL_NUMERIC(a.LastServiceNo), "|",

	IFNULL_NUMERIC(a.LastIRIDNo), "|",

	IFNULL_STRING_ONLY(a.DeliveryDate), "|", 

	IFNULL_STRING_ONLY(a.ReceiveDate), "|",  

	IFNULL_STRING_ONLY(a.ReleaseDate), "|",

	IFNULL_STRING_ONLY(a.ParticularID), "|",  		

	IFNULL_STRING_ONLY(b.isSIMReleased), "|",

	IFNULL_NUMERIC(a.SIMStatus), "|", 

	IFNULL_STRING_ONLY(c.Description), "|",
	
	IFNULL_NUMERIC(a.ClientID), "|",

	IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.ClientID)), "|",
	
	IFNULL_STRING_ONLY(a.UpdatedAt), "|", 
	
	IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.UpdatedID)), "|",
	
	IFNULL_NUMERIC(a.LocationID), "|",
	
	IFNULL_STRING_ONLY(funcGetDesc("Search", "Location", a.LocationID))

	) INTO v_outResult

	FROM tblsimdetail a

	LEFT JOIN tbllocation AS b ON a.Location = b.Description

	LEFT JOIN tblterminalstatus AS c ON a.SIMStatus = c.TerminalStatusID

	WHERE (a.SIMID = v_ID);



ELSEIF (p_SearchBy = 'Servicing SN Info')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT   

	CONCAT(a.ServiceNo, "|", 		

	IFNULL_NUMERIC(a.TerminalID), "|", 

	IFNULL_STRING_ONLY(a.TerminalSN), "|",

	IFNULL_NUMERIC(a.SIMID), "|", 

	IFNULL_STRING_ONLY(a.SIMSerialNo), "|",

	IFNULL_NUMERIC(a.ReplaceTerminalID), "|", 

