	IFNULL_FORMAT_DATE(a.DateCoveredTo), "|", 

	IFNULL_FORMAT_DATE(a.DateDue), "|", 

	IFNULL_DECIMAL(a.TAmtDue), "|", 

	IFNULL_STRING_ONLY(a.ProcessedBy), "|",

	IFNULL_STRING_ONLY(a.ProcessedDateTime), "|",

	IFNULL_STRING_ONLY(a.ModifiedBy), "|",

	IFNULL_STRING_ONLY(a.ModifiedDateTime), "|",

	IFNULL_NUMERIC(a.ModeOfPayment), "|", 

	IFNULL_STRING_ONLY(a.NoteToCustomer), "|",

	IFNULL_STRING_ONLY(a.NoteToSelf), "|", 

	(SELECT IFNULL_STRING_ONLY(xTable.Description) FROM tbltype xTable WHERE xTable.TypeID = b.RentalType), "|",

	(SELECT IFNULL_STRING_ONLY(xTable.Description) FROM tbltype xTable WHERE xTable.TypeID = b.RentalTerms)) INTO v_outResult

	FROM tblpr_invoicesmaster a	

	LEFT JOIN tblparticular b ON a.ParticularID = b.ParticularID		

	WHERE (a.InvoiceID = v_ID);	



ELSEIF (p_SearchBy = 'Rental Fee Info')

