ELSEIF (p_SearchBy = 'Staff Info Detail')

    THEN

    

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	#SELECT (CONCAT("spGetInfoDetail->v_ID=", v_ID));

	

	SELECT

	 CONCAT(

    '{',

    '"ParticularID":', IFNULL(a.ParticularID, 0), ', ',

    '"JobDescription":"', IFNULL_STRING_ONLY(a.JobDescription), '", ',

    '"OnBoardDate":"', IFNULL_STRING_ONLY(a.OnBoardDate), '", ',

    '"TINNo":"', IFNULL_STRING_ONLY(a.TINNo), '", ',

    '"PhilhealthNo":"', IFNULL_STRING_ONLY(a.PhilhealthNo), '", ',

    '"SSSNo":"', IFNULL_STRING_ONLY(a.SSSNo), '", ',

    '"HDMFNo":"', IFNULL_STRING_ONLY(a.HDMFNo), '", ',

    '"EducLevel":"', IFNULL_STRING_ONLY(a.EducLevel), '", ',

    '"PresentID":"', IFNULL_STRING_ONLY(a.PresentID), '", ',

    '"BirthDate":"', IFNULL_STRING_ONLY(a.BirthDate), '", ',

    '"Gender":"', IFNULL_STRING_ONLY(a.Gender), '", ',

    '"ResignDate":"', IFNULL_STRING_ONLY(a.ResignDate), '", ',

    '"PresentIDNo":"', IFNULL_STRING_ONLY(a.PresentIDNo), '", ',

	'"AccountInfo":"', IFNULL_STRING_ONLY(a.AccountInfo), '", ',

	

	'"NbiReq":"', IFNULL_STRING_ONLY(a.NbiReq), '", ',

	'"SchoolReq":"', IFNULL_STRING_ONLY(a.SchoolReq), '", ',

	'"AppFormReq":"', IFNULL_STRING_ONLY(a.AppFormReq), '", ',

	'"WaiverReq":"', IFNULL_STRING_ONLY(a.WaiverReq), '", ',

	

    '"TenureYears":"', IFNULL_STRING_ONLY(

        CONCAT(

            FLOOR(DATEDIFF(CURDATE(), IFNULL_STRING_ONLY(a.OnBoardDate)) / 365), '.',

            LPAD(FLOOR((DATEDIFF(CURDATE(), IFNULL_STRING_ONLY(a.OnBoardDate)) % 365) / 30.44), 2, '0' ) )), '", ',

    '"Age":"', FORMAT(

        CONCAT(

            FLOOR(DATEDIFF(CURDATE(), IFNULL_STRING_ONLY(a.BirthDate)) / 365), '.',

            LPAD(FLOOR((DATEDIFF(CURDATE(), IFNULL_STRING_ONLY(a.BirthDate)) % 365) / 30.44), 2, '0' )), 2), '"}', ''

            

            

	) AS JSON_OBJECT





	INTO v_outResult

	FROM

	tblparticular a

	WHERE (a.ParticularID = v_ID);

	

ELSEIF (p_SearchBy = 'ParticularID Info')

