	SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

						

	SELECT

	JSON_OBJECT(

	'ParticularID', IFNULL_NUMERIC(funcGetID("Search", "Particular", v_Name))

	) 

