ELSEIF (p_SearchBy = 'User Credential')

        THEN

		SET v_UserName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET v_Password = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		

		#SELECT (CONCAT("spGetInfoDetail->v_ID=", v_ID));

		

		SELECT

		JSON_OBJECT(

		'ParticularID', IFNULL_NUMERIC(b.ParticularID), 
		
		'UserID', IFNULL_NUMERIC(a.UserID),

		'UserName', IFNULL_STRING_ONLY(a.UserName), 

		'Name', IFNULL_STRING_ONLY(b.Name), 	

		'Mobile', IFNULL_STRING_ONLY(b.Mobile), 

		'Email', IFNULL(b.Email,"-"), 

		'Address', IFNULL_STRING_ONLY(b.Address),

		'ParticularTypeID', IFNULL_STRING_ONLY(b.ParticularTypeID),

		'MobileID', IFNULL_STRING_ONLY(a.MobileID),

		'MobileTerminalID', IFNULL_STRING_ONLY(c.TerminalID),

		'MobileTerminalName', IFNULL_STRING_ONLY(c.TerminalName)

		) 

