		FROM tbluser a

		LEFT JOIN tblparticular AS b ON a.ParticularID = b.ParticularID

		LEFT JOIN tblterminal AS c ON a.MobileID = c.TID

		WHERE (a.UserName = v_UserName AND a.MD5Password = v_Password);	

		

ELSEIF (p_SearchBy = 'Terminal Info')

