	WHERE (a.ParticularID = v_ID);

	

ELSEIF (p_SearchBy = 'Merchant SN Info')

THEN

	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

	SELECT
	JSON_OBJECT(
	'IRIDNo', IFNULL_NUMERIC(a.IRIDNo),
	'ServiceNo', IFNULL_NUMERIC(c.ServiceNo),
	'FSRNo', IFNULL_NUMERIC(d.FSRNo),
	'MerchantName', funcGetDesc("Search", "Particular", a.MerchantID),
	'TID', IFNULL_STRING_ONLY(a.TID),
	'MID', IFNULL_STRING_ONLY(a.MID),
	'TerminalSN', IFNULL_STRING_ONLY(a.TerminalSN),
	'SIMSN', IFNULL_STRING_ONLY(a.SIMSN),
	'Region', funcGetDesc("Search", "Region", b.RegionType),
	'IRNo', IFNULL_STRING_ONLY(a.IRNo),
	'ReferenceNo', IFNULL_STRING_ONLY(c.ReferenceNo),
	'FSRRefNo', IFNULL_STRING_ONLY(d.FSRRefNo)
	) 
	INTO v_outResult
	FROM
	tblirdetail a
	LEFT JOIN tblparticular AS b ON a.MerchantID = b.ParticularID
	LEFT JOIN tblservicingdetail AS c ON a.IRIDNo = c.IRIDNo
	LEFT JOIN tblfsrdetail AS d ON c.ServiceNo = d.ServiceNo
	#WHERE (a.IRIDNo = v_IRIDNo AND c.ServiceNo = v_ServiceNo);
	WHERE (c.ServiceNo = v_ServiceNo);

	

ELSEIF (p_SearchBy = 'Mobile Info')

THEN

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT 

	JSON_OBJECT('MobileID', IFNULL_STRING_ONLY(a.TID),

	'MobileTerminalID', IFNULL_STRING_ONLY(a.TerminalID),

	'MobileTerminalName', IFNULL_STRING_ONLY(a.TerminalName),

	'UserID', IFNULL_STRING_ONLY(b.UserID),

	'ParticularID', IFNULL_STRING_ONLY(c.ParticularID),

	'FullName', IFNULL_STRING_ONLY(c.Name)

	) INTO v_outResult

	FROM tblterminal a

	LEFT JOIN tbluser AS b ON a.TID = b.MobileID

	LEFT JOIN tblparticular AS c ON b.ParticularID = c.ParticularID 

	WHERE

	a.TID = v_ID;	

	

ELSEIF (p_SearchBy = 'Merchant Service Info')

THEN

	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	

	SELECT

	JSON_OBJECT(

	'IRIDNo', IFNULL_NUMERIC(a.IRIDNo),

	'TerminalID', IFNULL_NUMERIC(a.TerminalID),

	'TerminalSN', funcGetDesc("Search", "Terminal Detail", a.TerminalID),
	
	'TerminalType', funcGetDesc("Search", "TerminalID Type", a.TerminalID),
	
	'TerminalModel', funcGetDesc("Search", "TerminalID Model", a.TerminalID),
	
	'TerminalStatus', funcGetDesc("Search", "TerminalID Status ", a.TerminalID),
	
	'TerminalLocation', funcGetDesc("Search", "TerminalID Location ", a.TerminalID),

	'SIMID', IFNULL_NUMERIC(a.SIMID),

	'SIMSN', funcGetDesc("Search", "SIM Detail", a.SIMID),
	
	'SIMCarrier', funcGetDesc("Search", "SIMID Carrier", a.SIMID),
	
	'SIMStatus', funcGetDesc("Search", "SIMID Status ", a.SIMID),
	
	'SIMLocation', funcGetDesc("Search", "SIMID Location ", a.SIMID),

	'IRStatus', IFNULL_NUMERIC(a.IRStatus),

	'IRStatusDescription', funcGetDesc("Search", "Terminal Status", a.IRStatus),

	'ServiceCount', funcGetCount("Search", "Merchant Service Count", a.IRIDNo)

	)

	INTO v_outResult

	FROM

	tblirdetail a

	WHERE (a.IRIDNo = v_IRIDNo);

	

ELSEIF (p_SearchBy = 'Get Info By Field')

THEN

	SET v_TableName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

	SET v_FieldName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

	SET v_FieldSearchKey = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

	SET v_FieldSearchValue = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

	

	#SELECT CONCAT('v_TableName = ', v_TableName);

	#SELECT CONCAT('v_FieldName = ', v_FieldName);

	#SELECT CONCAT('v_FieldSearchKey = ', v_FieldSearchKey);

	#SELECT CONCAT('v_FieldSearchValue = ', v_FieldSearchValue);

	

	SET p_SQL = '';	

	SET p_SQL = CONCAT('SELECT');

	SET p_SQL = CONCAT(p_SQL, ' ', v_FieldName);

	SET p_SQL = CONCAT(p_SQL, ' ', 'INTO');

	SET p_SQL = CONCAT(p_SQL, ' ', '@v_outResult');

	SET p_SQL = CONCAT(p_SQL, ' ', 'FROM');

	SET p_SQL = CONCAT(p_SQL, ' ', v_TableName);

	SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

	SET p_SQL = CONCAT(p_SQL, ' ', v_FieldSearchKey);

	SET p_SQL = CONCAT(p_SQL, ' ', '=');

	SET p_SQL = CONCAT(p_SQL, ' ', v_FieldSearchValue);

	SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT 1');

	

	#SELECT CONCAT('p_SQL = ', p_SQL);

					

	SET @QUERY = p_SQL;

	PREPARE QUERY FROM @QUERY;

	EXECUTE QUERY;

		

	#SELECT CONCAT('@v_outResult = ', @v_outResult);

	#SET v_outResult = @v_outResult;

	

	SELECT

	JSON_OBJECT(

	'TableName', v_TableName,

	'FieldName', v_FieldName,

	'FieldSearchKey', v_FieldSearchKey,

	'FieldSearchValue', v_FieldSearchValue,

	'outValue', @v_outResult

	) INTO v_outResult;

	

ELSEIF (p_SearchBy = 'Last ControlNo Info')

THEN

	SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

	

	IF (v_Description = 'Terminal')

	THEN

		SELECT

		JSON_OBJECT(

		'TerminalID', IFNULL_NUMERIC(MAX(a.TerminalID)),

		'TerminalSN', funcGetDesc("Search", "Terminal Detail", a.TerminalID),

		'FSRNo', IFNULL_NUMERIC(MAX(a.FSRNo)),

		'ServiceNo', IFNULL_NUMERIC(MAX(a.ServiceNo)),

		'IRIDNo', IFNULL_NUMERIC(MAX(a.IRIDNo)),

		'MerchantID', IFNULL_NUMERIC(MAX(a.MerchantID)),

		'ClientID', IFNULL_NUMERIC(MAX(a.ClientID)),

		'FEID', IFNULL_NUMERIC(MAX(a.FEID)),

		'ServiceCount', funcGetCount("Search", "SN Service Count", CONCAT('Terminal', '|', a.TerminalID)),

		'FSRCount', funcGetCount("Search", "SN FSR Count", CONCAT('Terminal', '|', a.TerminalID))

		) 

		INTO v_outResult

		FROM

		tblfsrdetail a

		WHERE

		a.TerminalID = v_ID AND

		a.ActionMade = 'SUCCESS'

		ORDER BY

		MAX(a.FSRNo) DESC;

		

	ELSEIF (v_Description = 'SIM')

	THEN

		SELECT

		JSON_OBJECT(

		'SIMID', IFNULL_NUMERIC(MAX(a.SIMID)),

		'SIMSN', funcGetDesc("Search", "SIM Detail", a.SIMID),

		'FSRNo', IFNULL_NUMERIC(MAX(a.FSRNo)),

		'ServiceNo', IFNULL_NUMERIC(MAX(a.ServiceNo)),

		'IRIDNo', IFNULL_NUMERIC(MAX(a.IRIDNo)),

		'MerchantID', IFNULL_NUMERIC(MAX(a.MerchantID)),

		'ClientID', IFNULL_NUMERIC(MAX(a.ClientID)),

		'FEID', IFNULL_NUMERIC(MAX(a.FEID)),

		'ServiceCount', funcGetCount("Search", "SN Service Count", CONCAT('SIM', '|', a.SIMID)),

		'FSRCount', funcGetCount("Search", "SN FSR Count", CONCAT('SIM', '|', a.SIMID))

		) 

		INTO v_outResult

		FROM

		tblfsrdetail a

		WHERE

		a.SIMID = v_ID AND

		a.ActionMade = 'SUCCESS'

		ORDER BY

		MAX(a.FSRNo) DESC;

	

	END IF;

	

ELSEIF (p_SearchBy = 'SN MIN/MAX Service Info')
THEN
	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
	SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

	IF (v_Description = 'Terminal')
	THEN
		SELECT JSON_OBJECT(
		    'ServiceNo', IFNULL_NUMERIC(sd.ServiceNo),
		    'JobType', IFNULL_STRING_ONLY(sd.JobType),
		    'JobTypeStatusDescription', IFNULL_STRING_ONLY(sd.JobTypeStatusDescription),
		    'TerminalID', IFNULL_NUMERIC(sd.TerminalID),
		    'TerminalSN', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Terminal Detail', sd.TerminalID)),
		    'ReplaceTerminalID', IFNULL_NUMERIC(sd.ReplaceTerminalID),
		    'ReplaceTerminalSN', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Terminal Detail', sd.ReplaceTerminalID)),
		    'ServiceStatus', IFNULL_NUMERIC(sd.ServiceStatus),
		    'ServiceStatusDescription', IFNULL_STRING_ONLY(st.ServiceStatusDescription),
		    'JobTypeDescription', IFNULL_STRING_ONLY(st.JobTypeDescription),
		    'ServiceJobTypeDescription', IFNULL_STRING_ONLY(st.ServiceJobTypeDescription),
		    'ActionMade', IFNULL_STRING_ONLY(fd.ActionMade)
		) INTO v_outResult
		FROM (
		    SELECT *
		    FROM tblservicingdetail
		    WHERE TerminalID = v_ID OR ReplaceTerminalID = v_ID
		    ORDER BY 
			CASE WHEN v_Name = 'MIN' THEN ServiceNo END ASC,
			CASE WHEN v_Name = 'MAX' THEN ServiceNo END DESC
		    LIMIT 1
		) sd
		LEFT JOIN tblservicetype st ON sd.JobType = st.JobType
		LEFT JOIN tblfsrdetail fd ON sd.ServiceNo = fd.ServiceNo;

	ELSEIF (v_Description = 'SIM')
	THEN
		SELECT JSON_OBJECT(
		    'ServiceNo', IFNULL_NUMERIC(sd.ServiceNo),
		    'JobType', IFNULL_STRING_ONLY(sd.JobType),
		    'JobTypeStatusDescription', sd.JobTypeStatusDescription,
		    'SIMID', IFNULL_NUMERIC(sd.SIMID),
		    'SIMSN', IFNULL_STRING_ONLY(funcGetDesc('Search', 'SIM Detail', sd.SIMID)),
		    'ReplaceSIMID', IFNULL_NUMERIC(sd.ReplaceSIMID),
		    'ReplaceSIMSN', IFNULL_STRING_ONLY(funcGetDesc('Search', 'SIM Detail', sd.ReplaceSIMID)),
		    'ServiceStatus', IFNULL_NUMERIC(sd.ServiceStatus),
		    'ServiceStatusDescription', IFNULL_STRING_ONLY(st.ServiceStatusDescription),
		    'JobTypeDescription', IFNULL_STRING_ONLY(st.JobTypeDescription),
		    'ServiceJobTypeDescription', IFNULL_STRING_ONLY(st.ServiceJobTypeDescription),
		    'ActionMade', IFNULL_STRING_ONLY(fd.ActionMade)
		) INTO v_outResult
		FROM (
		    SELECT *
		    FROM tblservicingdetail
		    WHERE SIMID = v_ID OR ReplaceSIMID = v_ID
		    ORDER BY 
			CASE WHEN v_Name = 'MIN' THEN ServiceNo END ASC,
			CASE WHEN v_Name = 'MAX' THEN ServiceNo END DESC
		    LIMIT 1
		) sd
		LEFT JOIN tblservicetype st ON sd.JobType = st.JobType
		LEFT JOIN tblfsrdetail fd ON sd.ServiceNo = fd.ServiceNo;
	END IF;

	

ELSEIF (p_SearchBy = 'Application Version/CRC Info')

THEN

	SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

	

	SELECT

	JSON_OBJECT(

	'TerminalTypeID', a.TerminalTypeID,

	'TerminalModelID', a.TerminalModelID,

	'AppVersion', a.AppVersion,

	'AppCRC', a.AppCRC

	) INTO v_outResult

	FROM

	tblterminalmodel a

	WHERE

	a.Description = v_Description;

	

ELSEIF (p_SearchBy = 'Service Geometric Location Info')

THEN

	SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

	

	SELECT

	JSON_OBJECT(

	'geoLatitude', IFNULL_STRING_ONLY(a.geoLatitude),

	'geoLongitude', IFNULL_STRING_ONLY(a.geoLongitude),

	'geoCountry', IFNULL_STRING_ONLY(a.geoCountry),

	'geoLocality', IFNULL_STRING_ONLY(a.geoLocality),

	'geoAddress', IFNULL_STRING_ONLY(a.geoAddress)

	) INTO v_outResult

	FROM

	tblfsrdetail a

	WHERE

	a.FSRNo = v_FSRNo AND a.ServiceNo = v_ServiceNo;
	
ELSEIF (p_SearchBy = 'Merchant Last ControlNo')
THEN
	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	
	SELECT
	    JSON_OBJECT(
	    'JobType', IFNULL_NUMERIC(MAX(svc.JobType)),
	    'JobTypeDescription', IFNULL_STRING_ONLY(MAX(svc.JobTypeDescription)),
	    'InstallationServiceNo', IFNULL_NUMERIC(MAX((CASE WHEN svc.JobType = 1 THEN svc.ServiceNo ELSE 0 END))),
	    'ReplacementServiceNo', IFNULL_NUMERIC(MAX((CASE WHEN svc.JobType = 7 THEN svc.ServiceNo ELSE 0 END)))
	    ) INTO v_outResult
	FROM 
	    tblservicingdetail svc
	WHERE
	    svc.IRIDNo = v_IRIDNo AND
	    svc.JobType IN (1, 7) AND
	    svc.JobTypeStatusDescription = 'COMPLETED';	
	    
ELSEIF (p_SearchBy = 'Merchant Current SN')
THEN	
	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	
	SELECT
	JSON_OBJECT
	(
	  'TerminalID', IFNULL_NUMERIC(ir.TerminalID),
	  'TerminalSN', IFNULL_STRING_ONLY(funcGetDesc("Search", 'Terminal Detail', ir.TerminalID)),
	  'TerminalStatus', IFNULL_NUMERIC(tr.TerminalStatus),
	  'TerminalStatusDescription', IFNULL_STRING_ONLY(funcGetDesc("Search", 'Terminal Status', tr.TerminalStatus)),
	  'SIMID', IFNULL_NUMERIC(ir.SIMID),
	  'SIMSN', IFNULL_STRING_ONLY(funcGetDesc("Search", 'SIM Detail', ir.SIMID)),
	  'SIMStatus', IFNULL_NUMERIC(sm.SIMStatus),
	  'SIMStatusDescription', IFNULL_STRING_ONLY(funcGetDesc("Search", 'SIM Status', sm.SIMStatus))
	) INTO v_outResult
	FROM
	tblirdetail ir
	LEFT JOIN tblterminaldetail AS tr ON ir.TerminalID = tr.TerminalID
	LEFT JOIN tblsimdetail AS sm ON ir.SIMID = sm.SIMID
	WHERE
	ir.IRIDNo = v_IRIDNo;
	
ELSEIF (p_SearchBy = 'Primary IRNo')
THEN
	SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

	SELECT
	JSON_OBJECT(
	'JobType', IFNULL_NUMERIC(a.JobType),
	'ServiceNo', IFNULL_NUMERIC(a.ServiceNo),
	'IRIDNo', IFNULL_NUMERIC(a.IRIDNo),
	'IRNo', IFNULL_STRING_ONLY(a.IRNo)
	) INTO v_outResult
	FROM
	tblservicingdetail a
	WHERE
