	'DispatcherEmail', (funcGetDesc("Search", "Field Engineer Email", svc.DispatchID)),
	
	'isDiagnostic', IFNULL_NUMERIC(funcGetCount("Search", "Diagnostic Detail", CONCAT(svc.ServiceNo, "|", fsr.FSRNo))),
	'isBillable', IFNULL_NUMERIC(svc.isBillable),
	
	'ClientID', IFNULL_NUMERIC(svc.ClientID),
	'ClientName', IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", svc.ClientID)),
	'ClientEmail', (funcGetDesc("Search", "Client Email", svc.ClientID)),
	
	'SourceID', IFNULL_NUMERIC(svc.SourceID),
