	tblservicingdetail svc
	LEFT JOIN tblirdetail AS ir ON svc.IRIDNo = ir.IRIDNo
	LEFT JOIN tblparticular AS pr ON svc.MerchantID = pr.ParticularID
	LEFT JOIN tblfsrdetail AS fsr ON svc.ServiceNo = fsr.ServiceNo
	LEFT JOIN tbltype AS t ON t.TypeID = svc.BillingTypeID
	WHERE 
	    svc.ServiceNo = v_ServiceNo
	    AND (
		v_IRIDNo = 0
		OR svc.IRIDNo = v_IRIDNo
	    );
	
