		'ReferralType', funcGetDesc('Search', 'Type', IFNULL_NUMERIC(a.ReferralTypeID)),
		'CategoryTypeID', IFNULL_NUMERIC(a.CategoryTypeID),
		'Category', funcGetDesc('Search', 'Type', IFNULL_NUMERIC(a.CategoryTypeID)),
		
		'MDRCreditTypeID', IFNULL_NUMERIC(a.MDRCreditTypeID),
		'MDRCreditType', funcGetDesc('Search', 'Type', IFNULL_NUMERIC(a.MDRCreditTypeID)),
		'MDRDebitTypeID', IFNULL_NUMERIC(a.MDRDebitTypeID),
		'MDRDebitType', funcGetDesc('Search', 'Type', IFNULL_NUMERIC(a.MDRDebitTypeID)),
