		'MSPStatus', IFNULL_NUMERIC(a.MSPStatus),
		'MSPStatusDesc', funcGetDesc('Search', 'Type', IFNULL_NUMERIC(a.MSPStatus)),
		'NoOfPOS', IFNULL_STRING_ONLY(a.NoOfPOS),
		'NoOfYear', IFNULL_STRING_ONLY(a.NoOfYear),
		'RentalAmt', IFNULL_STRING_ONLY(a.RentalAmt),
