		'BankReferring', IFNULL_STRING_ONLY(a.BankReferring),
		'Remarks', IFNULL_STRING_ONLY(a.Remarks),
		
		'NoOfDocument', IFNULL_NUMERIC(funcGetCount('Search', 'Import Master Count', IFNULL_NUMERIC(a.MSPNo)))
								
		) INTO v_outResult
		FROM
		tblmspmaster a
		WHERE
