ELSEIF (p_SearchBy = 'MSP Detail Info')
THEN	
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		SELECT
		JSON_OBJECT
		(
		'ControlNo', IFNULL_NUMERIC(a.ControlNo),
		'MSPNo', IFNULL_NUMERIC(a.MSPNo),
		'ClientID', IFNULL_NUMERIC(a.ClientID),		
		'MerchantID', IFNULL_NUMERIC(a.MerchantID),
		'CreatedID', IFNULL_NUMERIC(a.CreatedID),
		'CreatedAt', IFNULL_FORMAT_DATE(a.CreatedAt),
		'CreatedBy', funcGetDesc('Search', 'Particular', IFNULL_NUMERIC(a.CreatedID)),
		'SubmitAt', IFNULL_FORMAT_DATE(a.SubmitAt),
		'ResultStatus', IFNULL_NUMERIC(a.ResultStatus),
		'ResultStatusDesc', funcGetDesc('Search', 'Type', IFNULL_NUMERIC(a.ResultStatus)),
		'Remarks', IFNULL_STRING_ONLY(a.Remarks)	
							
		) INTO v_outResult
		FROM
		tblmspdetail a
		WHERE
		a.ControlNo = v_ID;
		
ELSEIF (p_SearchBy = 'Service RequestID Count')
THEN
		SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		
		SELECT
		JSON_OBJECT
		(
		'TCount', funcGetCount("Search", "Service RequestID", CONCAT(v_JobType, "|", v_ID, "|", v_IRNo))					
		) INTO v_outResult;
		
ELSEIF (p_SearchBy = 'Helpdesk-Details')
THEN	
	   SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SELECT 
			 JSON_OBJECT(
			  'ID', IFNULL(a.ProblemNo, 0),
			  'AssistNo', IFNULL(a.AssistNo, 0),
			  'MerchantID', IFNULL(ir.MerchantID, 0),
			  'ClientID', IFNULL(ir.ClientID, 0),
			  'IRIDNo', IFNULL(b.IRIDNo, 0),
			  'HelpdeskID', IFNULL(a.HelpdeskID, 0),
			  'HelpdeskName', funcGetDesc('Search', 'Particular', IFNULL(a.HelpdeskID, 0)),        
			  'TeamLeadID', IFNULL(a.TeamLeadID, 0),
			  'TeamLeadName', funcGetDesc('Search', 'Particular', IFNULL(a.TeamLeadID, 0)),
			  'CreatedDate', IFNULL(a.CreatedDate, ''),
			  'ReasonID', IFNULL(a.ReasonID, 0),
			  'Reason', funcGetDesc('Search', 'Reason', IFNULL(a.ReasonID, 0)),
			  'ContactPerson', IFNULL(a.ContactPerson, ''),
			  'ContactNo', IFNULL(a.ContactNo, ''),
			  'ContactPosition', IFNULL(a.ContactPosition, ''),
			  'ContactEmail', IFNULL(a.ContactEmail, ''),
			  'TerminalSN', IFNULL(a.TerminalSN, ''),            
			  'SIMSN', IFNULL(a.SIMSN, ''),    
			  'DockerSN', IFNULL(a.DockerSN, ''),
			  'ProblemReported', IFNULL(a.ProblemReported, ''),
			  'RemarksService', IFNULL(a.RemarksService, ''),
			  'RemarksHelpDesk', IFNULL(a.RemarksHelpDesk, ''),
			  'Status', 		IFNULL(a.Status, ''),
			  'isActive', 		IFNULL(a.isActive, 0),
			  'ReferenceNo', 	IFNULL(b.ReferenceNo, 0),
			  'RequestID', 	IFNULL(a.RequestID, 0),
			  'SourceID', IFNULL(a.SourceID, 0),
			  'Source', 		IFNULL_STRING_ONLY(src.Description),
			  'CategoryID', IFNULL(a.CategoryID, 0),
			  'Category', 		IFNULL_STRING_ONLY(ctg.Description),
			  'SubCategoryID', IFNULL(a.SubCategoryID, 0),
			  'SubCategory', IFNULL_STRING_ONLY(sctg.Description),
			  'RequestDate', IFNULL(a.RequestDate, ''),
			  'CreatedID', IFNULL(a.CreatedID, 0),  
			  'CreatedBy', IFNULL(cb.Name, 0),
			  'CreatedAt', IFNULL(DATE_FORMAT(a.CreatedDate, '%b %d, %Y'), ''), 
			  'UpdatedBy', IFNULL(ub.Name, 0),
			  'UpdatedAt', IFNULL(DATE_FORMAT(a.CreatedAt, '%b %d, %Y'), ''),
			  'TimeAssisted', IFNULL(a.TimeAssisted, ''),
			  'TimeStart', IFNULL(a.TimeStart, ''),
			  'TimeEnd', IFNULL(a.TimeEnd, ''),
			  'JobType', IFNULL(b.JobType, ''),
			   'TerminalID', IFNULL(a.TerminalID, ''),
			   'SIMID', IFNULL(a.SIMID, ''),
			   'Representative', IFNULL(a.Representative, ''),
			   'RequestedBy', IFNULL(a.RequestedBy, ''),
			   'ActualProblem', IFNULL(a.ActualProblem, ''),
			   'AppVersion', IFNULL(a.AppVersion, ''),
			   'AppCrc', IFNULL(a.AppCrc, ''),
			   'ProblemID', IFNULL(a.ProblemID, ''),
			   'DependencyID', IFNULL(a.DependencyID, ''),
			   'StatusReasonID', IFNULL(a.StatusReasonID, ''),
			   'Dependency', funcGetDesc('Search', 'Type', a.DependencyID),
			   'StatusReason', funcGetDesc('Search', 'Type', a.StatusReasonID),
			   'ProblemNo', IFNULL_NUMERIC(a.ProblemNo),
			   'ServiceNo', IFNULL_NUMERIC(svc.ServiceNo),
		           'FSRNo', IFNULL_NUMERIC(fsr.FSRNo),
		           'IssueCategory', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Type', a.IssueCategoryID))
          
		)	INTO v_outResult
		
		FROM tblhddetail a
		LEFT JOIN tblhdmaster b ON b.AssistNo 		= a.AssistNo
		LEFT JOIN tblirdetail ir ON ir.IRIDNo 		= b.IRIDNo
		JOIN tbltype 		src ON src.TypeID 		= a.SourceID
		JOIN tbltype 		ctg ON ctg.TypeID 		= a.CategoryID
		JOIN tbltype 	  sctg ON sctg.TypeID 		= a.SubCategoryID
		JOIN tblparticular cb ON cb.ParticularID 	= a.CreatedID
		JOIN tblparticular ub ON ub.ParticularID 	= a.HelpdeskID
		LEFT JOIN tblservicingdetail svc ON a.AssistNo = svc.AssistNo AND a.ProblemNo = svc.ProblemNo
		LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo
		
		WHERE a.ProblemNo = v_ID;
		
ELSEIF (p_SearchBy = 'Helpdesk-Reason')
THEN	
	   SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		SELECT 
			 JSON_OBJECT(
				  'ReasonID', IFNULL(a.ReasonID, 0),
				  'Description', IFNULL(a.Description, ''))	
		INTO v_outResult
		FROM tblreason a
		WHERE 
		#a.isActive = 1
		a.ReasonID = v_ID;
		
ELSEIF (p_SearchBy = 'Helpdesk-Problem')
THEN	
	   SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		SELECT 
			 JSON_OBJECT(
				  'ReasonID', IFNULL(a.ReasonID, 0),
				  'Description', IFNULL(a.ProblemReported, ''))	
		INTO v_outResult
		FROM tblhddetail a
		WHERE a.isActive = 1
		AND a.ProblemNo = v_ID;
		
ELSEIF (p_SearchBy = 'Helpdesk-Users')
THEN	
	   SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		SELECT 
			 JSON_OBJECT(
				  'ParticularID', IFNULL(a.ParticularID, 0),
				  'Name', IFNULL(a.Name, ''),
				  'Address', IFNULL(a.Address, ''),
				  'Address', IFNULL(a.Address, ''),
				  'ContactPerson', IFNULL(a.ContactPerson, ''),
				  'ContactPosition', IFNULL(a.ContactPosition, ''),
				  'ContactNumber', IFNULL(a.ContactNumber, ''),
				  'TelNo', IFNULL(a.TelNo, ''),
				  'Mobile', IFNULL(a.Mobile, ''),
				  'Fax', IFNULL(a.Fax, ''),
				  'Email', IFNULL(a.Email, ''),
				  'Region', IFNULL(a.Region, ''),
				  'Province', IFNULL(a.Province, ''))	
		INTO v_outResult
		FROM tblparticular a
		WHERE a.isActive = 1
		AND a.ParticularID = v_ID;
		
ELSEIF (p_SearchBy = 'Helpdesk-Master-Checker')
THEN	
		SET @IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SELECT JSON_OBJECT('Result', IF(R.Status = 'PENDING', 1, 0)) 
		INTO v_outResult
		FROM (SELECT 1) AS dt
		LEFT JOIN (
			 SELECT
				  b.Status
			 FROM tblhdmaster a
			 JOIN tblhddetail b ON b.AssistNo = a.AssistNo
			 WHERE a.IRIDNo = @IRIDNo
			 ORDER BY b.ProblemNo DESC
			 LIMIT 1
		) AS R ON 1 = 1;
		
ELSEIF (p_SearchBy = 'Helpdesk-Request-Checker')
THEN	
		SET @RequestID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

	    SELECT JSON_OBJECT(
	      'Exists', IF(COUNT(a.RequestID) > 0, 1, 0)
	    ) INTO v_outResult
	    FROM tblhddetail a
	    WHERE a.RequestID = @RequestID
	      AND a.`STATUS` = 'SUCCESS'
	    LIMIT 1;
	    
ELSEIF (p_SearchBy = 'Helpdesk-Attempt')
THEN	
		SET @AssistNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET @RequestID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET @Status = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		SELECT 
		  JSON_OBJECT('Result', COALESCE(COUNT(*), 0))
		INTO v_outResult
		FROM tblhddetail a
		WHERE a.RequestID = @RequestID
		  AND (
				 (
					(@AssistNo IS NULL OR @AssistNo = '')
					AND a.Status = 'SUCCESS'
				 )
				OR
				 (
					(@AssistNo IS NOT NULL AND @AssistNo != '')
					AND a.AssistNo = @AssistNo
					AND (
					  @Status IS NULL OR @Status = '' OR a.Status = @Status
					)
				 )
				);
		
ELSEIF (p_SearchBy = 'Merchant Basic Info')
THEN
	SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
	SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
	SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
	
	SELECT 
		JSON_OBJECT(
		  'IRIDNo', a.IRIDNo,
		  'MerchantID', a.MerchantID,
		  'IRNo', IFNULL_STRING_ONLY2(a.IRNo),
		  'IRStatusDescription', IFNULL_STRING_ONLY2(a.IRStatusDescription),
		  'TerminalSN', IFNULL_STRING_ONLY2(b.TerminalSN),
		  'TerminalType', IFNULL_STRING_ONLY2(e.Description),
		  'TerminalModel', IFNULL_STRING_ONLY2(f.Description),
		  'SIMSN', IFNULL_STRING_ONLY2(c.SIMSN),
		  'SIMCarrier', IFNULL_STRING_ONLY2(d.Description),
		  'Region', funcGetDesc('Search', 'Region', g.RegionType),
		  'Province', funcGetDesc('Search', 'Region Detail', g.RegionID),
		  'profile_info', COALESCE(a.profile_info, '-'),
		  'rawdata_info', COALESCE(a.rawdata_info, '-')
		  )	
		INTO v_outResult
		FROM tblirdetail a
		LEFT JOIN tblterminaldetail b ON a.TerminalID = b.TerminalID
		LEFT JOIN tblsimdetail c ON a.SIMID = c.SIMID
		LEFT JOIN tbltype d ON c.CarrierID = d.TypeID AND d.Type = 1
		LEFT JOIN tblterminaltype e ON b.TerminalTypeID = e.TerminalTypeID
		LEFT JOIN tblterminalmodel f ON b.TerminalModelID = f.TerminalModelID
		LEFT JOIN tblparticular g ON a.MerchantID = g.ParticularID AND g.ParticularTypeID = 1
		WHERE 
		#a.IRActive > 0
		a.TID = v_TID
		AND a.MID = v_MID
		ORDER BY a.IRIDNo DESC		
		LIMIT 1;
		
ELSEIF (p_SearchBy = 'Merchant Basic Info 2')
THEN
	SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
	SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
	SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
	
	SELECT 
		JSON_OBJECT(
		  'IRIDNo', a.IRIDNo,
		  'MerchantID', a.MerchantID,
		  'ParticularID', b.ParticularID,
		  'RegionType', b.RegionType,
		  'RegionID', b.RegionID,
		  'IRNo', a.IRNo,
		  'MerchantName', b.Name,
		  'Address', b.Address,
		  'Region', funcGetDesc('Search', 'Region', b.RegionType),
		  'Province', funcGetDesc('Search', 'Region Detail', b.RegionID),
		  'AreaCode', b.AreaCode
		  )	
		INTO v_outResult
		FROM tblirdetail a
		LEFT JOIN tblparticular b ON a.MerchantID = b.ParticularID
		WHERE 
		a.IRActive = 1
		AND a.TID = v_TID
		AND a.MID = v_MID	
		ORDER BY a.IRIDNo DESC	
		LIMIT 1;
		
ELSEIF (p_SearchBy = 'GetID Info')
    THEN
        SET @SearchBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
	SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
	
	SELECT
	JSON_OBJECT(
	'ID', IFNULL_NUMERIC(funcGetID("Search", @SearchBy, v_Name))
	) 

	INTO v_outResult;
	
ELSEIF (p_SearchBy = 'GetDesc Info')
    THEN
	SET @SearchBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
	SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
	
	SELECT
	JSON_OBJECT(
	'Description', IFNULL_STRING_ONLY(funcGetDesc("Search", @SearchBy, v_ID))
	) 

	INTO v_outResult;
	
ELSEIF (p_SearchBy = 'Report Status Info')
THEN
	SET @SearchBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
	
	# timeout in minutes
	SET @Timeout = 1;  
	
	SELECT JSON_OBJECT
	(
		'ID', a.ID,
		'ReportDesc', a.ReportDesc,
		'StatusID', a.StatusID,
		'Status', a.Status,		
		'ProcessedAt', IFNULL_FORMAT_DATETIME(a.ProcessedAt),
		'ProcessedBy', a.ProcessedBy,
		'DateTimeStamp', IFNULL_FORMAT_DATETIME(a.DateTimeStamp),
		'isReset',
			CASE 
				WHEN a.StatusID = 2 
				     AND TIMESTAMPDIFF(MINUTE, a.ProcessedAt, NOW()) > @Timeout 
				THEN 1
				ELSE 0
			END
	) 
	INTO v_outResult
	FROM tblreportstatus a
	WHERE a.ReportDesc = @SearchBy
	LIMIT 1;
	
ELSEIF (p_SearchBy = 'Merchant IR Info')
THEN
	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	SELECT
	JSON_OBJECT(
	'IRIDNo', IFNULL_NUMERIC(a.IRIDNo),
	'IRNo', IFNULL_STRING_ONLY(a.IRNo),
	'RequestDate', IFNULL_STRING_ONLY(a.IRDate),
	'ReqInstallationDate', IFNULL_STRING_ONLY(a.InstallationDate),
	'MerchantID', IFNULL_NUMERIC(a.MerchantID),
	'MerchantName', funcGetDesc("Search", "Particular", a.MerchantID),
	'TID', IFNULL_STRING_ONLY(a.TID),
	'MID', IFNULL_STRING_ONLY(a.MID),
	'ClientID', IFNULL_NUMERIC(a.ClientID),
	'ClientName', funcGetDesc("Search", "Particular", a.ClientID),
	'TerminalID', IFNULL_NUMERIC(a.TerminalID),
	'TerminalSN', funcGetDesc("Search", "Terminal Detail", a.TerminalID),
	'TerminalType', funcGetDesc("Search", "Terminal Type", b.TerminalTypeID),
	'TerminalModel', funcGetDesc("Search", "Terminal Model", b.TerminalModelID),
	'TerminalStatus', funcGetDesc("Search", "Terminal Status", b.TerminalStatus),
	'TerminalLocation', funcGetDesc("Search", "Location", b.LocationID),
	'SIMID', IFNULL_NUMERIC(a.SIMID),
	'SIMSN', funcGetDesc("Search", "SIM Detail", a.SIMID),
	'SIMCarrier', funcGetDesc("Search", "Type", c.CarrierID),
	'SIMStatus', funcGetDesc("Search", "SIM Status", c.SIMStatus),
	'SIMLocation', funcGetDesc("Search", "Location", c.LocationID),
	'IRStatus', IFNULL_NUMERIC(a.IRStatus),
	'IRStatusDescription', funcGetDesc("Search", "Terminal Status", a.IRStatus),
	'ProcessedAt', IFNULL_STRING_ONLY(a.ProcessedDateTime),
	'ProcessedBy', IFNULL_STRING_ONLY(a.ProcessedBy),
	'ModifiedBy', IFNULL_STRING_ONLY(a.ModifiedBy),
	'ModifiedAt', IFNULL_STRING_ONLY(a.ModifiedDateTime),
	'RequestTypeID', IFNULL_NUMERIC(a.RequestTypeID),
	'RequestType', funcGetDesc("Search", "Type", a.RequestTypeID),
	'ProcessType', IFNULL_STRING_ONLY(a.ProcessType),
	'Requestor', IFNULL_STRING_ONLY(a.REQUESTOR),
	'DateTimeStamp', IFNULL_STRING_ONLY(a.DateTimeStamp),
	'IRActive', IFNULL_NUMERIC(a.IRActive)
	) 

	INTO v_outResult
	FROM
	tblirdetail a
	LEFT JOIN tblterminaldetail b ON a.TerminalID = b.TerminalID
	LEFT JOIN tblsimdetail c ON a.SIMID = c.SIMID
	WHERE (a.IRIDNo = v_IRIDNo);
	
ELSEIF (p_SearchBy = 'Merchant Last Service')
THEN
	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

	SELECT
	JSON_OBJECT(
	'IRIDNo', IFNULL_NUMERIC(a.IRIDNo),
	'ServiceNo', IFNULL_NUMERIC(a.ServiceNo),
	'FSRNo', IFNULL_NUMERIC(a.FSRNo),
	'IRNo', IFNULL_STRING_ONLY(a.IRNo),
	'ActionMade', IFNULL_STRING_ONLY(a.ActionMade)
	) 

	INTO v_outResult
	FROM
	tblfsrdetail a
	WHERE 
	a.isActive > 0
	AND a.IRIDNo = v_IRIDNo
	#AND a.ActionMade = v_ActionMade
	ORDER BY a.ServiceNo DESC
	LIMIT 1;
	
ELSEIF (p_SearchBy = 'Report Info')
THEN
	SET @ReportID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	
	SELECT
	JSON_OBJECT(
	'ReportID', IFNULL_NUMERIC(a.ReportID),	
	'ReportDesc', IFNULL_STRING_ONLY(a.ReportDesc)
	) 

	INTO v_outResult
	FROM
	tblreport a
	WHERE 
	a.ReportID = @ReportID;
	
ELSEIF (p_SearchBy = 'First Service Transmission')
THEN
	SET @JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	SET @MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
	
	SELECT 
	JSON_OBJECT(
	  'TCount', x.RecordCount,
	  'ServiceNo', a.ServiceNo,
	  'IRNo', a.IRNo,
	  'Merchant', a.Merchant,
	  'TID', a.TID,
	  'MID', a.MID,
	  'FSRDate', a.FSRDate,
	  'FSRTime', a.FSRTime,
	  'TimeArrived', a.TimeArrived,
	  'TimeStart', a.TimeStart,
	  'TimeEnd', a.TimeEnd,
	  'MerchantContactNo', a.MerchantContactNo,
	  'MerchantRepresentative', a.MerchantRepresentative,
	  'MerchantRepresentativePosition', a.MerchantRepresentativePosition,
	  'MerchantRepresentativeEmail', a.MerchantRepresentativeEmail,
	  'ReasonID', a.ReasonID,
	  'Reason', a.Reason,
	  'ClientID', a.ClientID,
	  'ClientName', a.ClientName,
	  'ActionMade', a.ActionMade,
	  'ProblemReported', a.ProblemReported,
	  'ActualProblemReported', a.ActualProblemReported,
	  'ActionTaken', a.ActionTaken,
	  'AnyComments', a.AnyComments,
	  'Remarks', a.Remarks,
	  'geoLatitude', a.geoLatitude,
	  'geoLongitude', a.geoLongitude,
	  'geoCountry', a.geoCountry,
	  'geoLocality', a.geoLocality,
	  'diagnostic_info', a.diagnostic_info
	) INTO v_outResult
	FROM tblfsrdetail a
	CROSS JOIN (
	    SELECT COUNT(*) AS RecordCount
	    FROM tblfsrdetail
	    WHERE 
		isActive > 0
		AND MID = @MID
		AND JobType = @JobType
		AND ActionMade = 'SUCCESS'
	) X
	WHERE 
	    a.isActive > 0
	    AND a.MID = @MID
	    AND a.JobType = @JobType
	    AND a.ActionMade = 'SUCCESS'
	ORDER BY a.DateTimeStamp ASC
	LIMIT 1;
	
ELSEIF (p_SearchBy = 'Total SN Installed')
THEN
	SELECT SUM(TInstalled) INTO v_outResult
	FROM (
	    SELECT
		uniq.RegionID,
		COUNT(*) AS TInstalled
	    FROM (
		SELECT
		  td.TerminalID,
		  MIN(r.RegionID) AS RegionID
		FROM tblregion r
		LEFT JOIN tblparticular p
		  ON p.RegionType = r.RegionID
		LEFT JOIN tblirdetail ir
		  ON ir.MerchantID = p.ParticularID
		LEFT JOIN tblterminaldetail td
		  ON td.TerminalID = ir.TerminalID
		WHERE
		  r.isActive > 0
		  AND td.isActive > 0
		  AND td.LocationID = 18
		  AND td.TerminalStatus = 7
		GROUP BY
		  td.TerminalID
	    ) AS uniq
	    GROUP BY
	      uniq.RegionID
	) AS region_summary;
	
ELSEIF (p_SearchBy = 'Multi Merchant SN Info')
THEN
	    -- Expect p_SearchValue as comma-separated TID|MID, e.g. 'TID1|MID1,TID2|MID2,TID3|MID3'
    
WITH pairs AS (
    SELECT 
        TRIM(SUBSTRING_INDEX(j.value, '|', 1)) AS TID,
        TRIM(SUBSTRING_INDEX(j.value, '|', -1)) AS MID
    FROM JSON_TABLE(CONCAT('["', REPLACE(p_SearchValue, ',', '","'), '"]'), '$[*]' COLUMNS(VALUE VARCHAR(255) PATH '$')) AS j
),
agg AS (
    SELECT 
        a.TID,
        a.MID,
        MAX(a.IRIDNo) AS IRIDNo,
        MAX(a.MerchantID) AS MerchantID,
        MAX(a.IRNo) AS IRNo,
        MAX(a.IRStatusDescription) AS IRStatusDescription,
        MAX(b.TerminalSN) AS TerminalSN,
        MAX(e.Description) AS TerminalType,
        MAX(f.Description) AS TerminalModel,
        MAX(c.SIMSN) AS SIMSN,
        MAX(d.Description) AS SIMCarrier,
        MAX(funcGetDesc('Search', 'Region', g.RegionType)) AS Region,
        MAX(funcGetDesc('Search', 'Region Detail', g.RegionID)) AS Province
    FROM pairs p
    LEFT JOIN tblirdetail a ON a.TID = p.TID AND a.MID = p.MID AND a.IRActive > 0
    LEFT JOIN tblterminaldetail b ON a.TerminalID = b.TerminalID
    LEFT JOIN tblsimdetail c ON a.SIMID = c.SIMID
    LEFT JOIN tbltype d ON c.CarrierID = d.TypeID AND d.Type = 1
    LEFT JOIN tblterminaltype e ON b.TerminalTypeID = e.TerminalTypeID
    LEFT JOIN tblterminalmodel f ON b.TerminalModelID = f.TerminalModelID
    LEFT JOIN tblparticular g ON a.MerchantID = g.ParticularID AND g.ParticularTypeID = 1
    GROUP BY a.TID, a.MID
)
SELECT JSON_ARRAYAGG(
    JSON_OBJECT(
        'IRIDNo', IRIDNo,
        'MerchantID', MerchantID,
        'IRNo', IRNo,
        'IRStatusDescription', IRStatusDescription,
        'TerminalSN', TerminalSN,
        'TerminalType', TerminalType,
        'TerminalModel', TerminalModel,
        'SIMSN', SIMSN,
        'SIMCarrier', SIMCarrier,
        'Region', Region,
        'Province', Province,
        'TID', TID,
        'MID', MID
    )
) INTO v_outResult
FROM agg;

ELSEIF (p_SearchBy = 'Last Service Attempt') 
THEN	
    SET v_JobType  = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
    SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED);
    SET v_IRIDNo     = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 3)) AS UNSIGNED);
    SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 4));
    
	SELECT
	    JSON_OBJECT(
		'ServiceNo', IFNULL_NUMERIC(a.ServiceNo),
		'IRNo', a.IRNo,
		'ReasonID', IFNULL_NUMERIC(a.ReasonID),
		'FunctionID', IFNULL_NUMERIC(c.FunctionID),
		'ActionMade', a.ActionMade,
		'Remarks', IFNULL_STRING_NORMAL(a.Remarks),
		'Reason', IFNULL_STRING_NORMAL(funcGetDesc('Search', 'Reason', a.ReasonID)),
		'Dependency', IFNULL_STRING_NORMAL(funcGetDesc('Search', 'Type', a.DependencyID)),
		'StatusReason', IFNULL_STRING_NORMAL(funcGetDesc('Search', 'Type', a.StatusReasonID)),
		'FSRDate', IFNULL_FORMAT_DATE(a.FSRDate),
		'ScheduleDate', IFNULL_FORMAT_DATE(b.ServiceReqDate),
		'RequestDate', IFNULL_FORMAT_DATE(b.ReqInstallationDate),

		-- New Fields
		'MinScheduleDate',
		IFNULL_FORMAT_DATE(COALESCE(d.MinServiceReqDate, '0000-00-00')),

		'MaxScheduleDate',
		IFNULL_FORMAT_DATE(COALESCE(d.MaxServiceReqDate, '0000-00-00'))
	    ) INTO v_outResult
	FROM tblfsrdetail a
	LEFT JOIN tblservicingdetail b
	    ON a.ServiceNo = b.ServiceNo
	LEFT JOIN tblreason c
	    ON a.ReasonID = c.ReasonID
	LEFT JOIN
	(
	    SELECT
		IRIDNo,
		MIN(ServiceReqDate) AS MinServiceReqDate,
		MAX(ServiceReqDate) AS MaxServiceReqDate
	    FROM tblservicingdetail
	    GROUP BY IRIDNo
	) d
	    ON a.IRIDNo = d.IRIDNo
	WHERE a.JobType = v_JobType
	  AND a.MerchantID = v_MerchantID
	  AND a.IRIDNo = v_IRIDNo
	  AND (b.IRNo = v_IRNo OR v_IRNo = '')
	ORDER BY a.FSRNo DESC
	LIMIT 1;
	
ELSEIF (p_SearchBy = 'Zoning-City-Municipal')
THEN
	SET @Search = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
	
	SELECT
        JSON_OBJECT(
            'ZoneID', ZoneID,
            'Zone', IFNULL_STRING_NORMAL(ZoneName),
            'Region', IFNULL_STRING_NORMAL(Region),
            'Area', IFNULL_STRING_NORMAL(AREA),
            'CityMunicipal', IFNULL_STRING_NORMAL(CityMunicipal)
        ) INTO v_outResult
    FROM tblzoning
    WHERE CityMunicipal LIKE CONCAT('%', @Search, '%')
    ORDER BY CityMunicipal
    LIMIT 1;
    
ELSEIF (p_SearchBy = 'Zoning Detail')
THEN
	SET v_ID  = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
	
	SELECT
        JSON_OBJECT(
            'ZoneID', ZoneID,
            'Zone', IFNULL_STRING_NORMAL(ZoneName),
            'Cluster', IFNULL_STRING_NORMAL(Cluster),
            'Region', IFNULL_STRING_NORMAL(Region),
            'Area', IFNULL_STRING_NORMAL(AREA),
            'CityMunicipal', IFNULL_STRING_NORMAL(CityMunicipal),
            'SLA', IFNULL_NUMERIC(SLA)
        ) INTO v_outResult
    FROM tblzoning
    WHERE
    ZoneID = v_ID;

ELSEIF (p_SearchBy = 'System Info')
THEN
	SELECT
        JSON_OBJECT(
            'ServerDateTime', DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'),
            'ServerDate', DATE_FORMAT(CURDATE(), '%Y-%m-%d'),
            'ServerTime', DATE_FORMAT(CURTIME(), '%H:%i:%s'),
            'ServerTimeZone', @@system_time_zone,
            'DatabaseVersion', VERSION(),
            'BusinessDate', DATE_FORMAT(CURDATE(), '%Y-%m-%d'),
            'IsOnline', TRUE
        ) INTO v_outResult;
 
ELSEIF (p_SearchBy = 'Service Audit Info')
THEN
	SET v_ID  = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
	
	SELECT
	JSON_OBJECT(
	    'svcProcessedBy',        COALESCE(a.ProcessedBy, ''),
	    'svcProcessedDate',      COALESCE(IFNULL_GET_DATE(a.ProcessedDateTime), ''),
	    'svcModifiedBy',         COALESCE(a.ModifiedBy, ''),
	    'svcModifiedDate',        COALESCE(IFNULL_GET_DATE(a.ModifiedDateTime), ''),
	    'svcDispatchBy',         COALESCE(funcGetDesc('Search', 'Particular', a.DispatchID), ''),
	    'svcDispatchDate',       COALESCE(IFNULL_GET_DATE(a.DispatchDateTime), ''),
	    'fsrProcessedBy',        COALESCE(b.ProcessedBy, ''),
	    'fsrProcessedDate',      COALESCE(IFNULL_GET_DATE(b.ProcessedDateTime), ''),
	    'fsrModifiedBy',         COALESCE(b.ModifiedBy, ''),
	    'fsrModifiedDate',       COALESCE(IFNULL_GET_DATE(b.ModifiedDateTime), ''),
	    'fsrServicedBy',         COALESCE(funcGetDesc('Search', 'Particular', b.FEID), ''),
	    'fsrServicedDate',       COALESCE(IFNULL_GET_DATE(b.FSRDate), ''),
	    'svcClosedTicketBy',     COALESCE(funcGetDesc('Search', 'Particular', a.TicketID), ''),
	    'svcClosedTicketDate',   COALESCE(IFNULL_GET_DATE(a.TicketDateTime), '')
	) INTO v_outResult
	FROM tblservicingdetail a
	LEFT JOIN tblfsrdetail b
	    ON a.ServiceNo = b.ServiceNo
	WHERE a.ServiceNo = v_ID;

ELSEIF (p_SearchBy = 'Successor JO')
THEN
	SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
	SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
	SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
	SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
	
	SELECT
		JSON_OBJECT(
		    'newJO', IF(COUNT(c.ServiceNo) > 0, 1, 0),
		    'newJOServiceNo', IFNULL_NUMERIC(MIN(c.ServiceNo)),
		    'ticketStatus', IFNULL_NUMERIC(MAX(a.TicketStatus))
		)
	INTO v_outResult
	FROM tblservicingdetail a
	LEFT JOIN tblfsrdetail b
		ON a.ServiceNo = b.ServiceNo
	LEFT JOIN tblservicingdetail c
		ON c.isActive > 0
		AND IFNULL(c.isCancelled, 0) = 0
		AND c.JobType = a.JobType
		AND c.MerchantID = a.MerchantID
		AND c.IRIDNo = a.IRIDNo
		AND c.IRNo = a.IRNo
		AND c.ServiceNo > a.ServiceNo
		WHERE a.ServiceNo = v_ServiceNo
		AND a.JobType = v_JobType
		AND a.MerchantID = v_MerchantID
		AND a.IRIDNo = v_IRIDNo
		AND a.IRNo = v_IRNo;

ELSEIF (p_SearchBy = 'Check JO TAT')
THEN
    SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
    SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED);
    SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
    SET v_Date = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 4)) AS DATE);

    SET v_outResult = JSON_OBJECT(
        'found', 0,
        'TATStatus', 'UNAVAILABLE'
    );

    SELECT
        JSON_OBJECT(
            'found', 1,
            'FSRNo',                IFNULL_NUMERIC(fsr.FSRNo),
            'ServiceNo',            IFNULL_NUMERIC(fsr.ServiceNo),
            'IRNo',                 IFNULL_STRING_NORMAL(svc.IRNo),
            'FunctionID',           IFNULL_NUMERIC(r.FunctionID),
            'ActionMade',           IFNULL_STRING_NORMAL(fsr.ActionMade),
            'Reason',               IFNULL_STRING_NORMAL(funcGetDesc('Search', 'Reason', fsr.ReasonID)),
            'FSRDate',              IFNULL_FORMAT_DATE(fsr.FSRDate),
            'RequestDate',          IFNULL_FORMAT_DATE(svc.ReqInstallationDate),
            'LastScheduleDate',     IFNULL_FORMAT_DATE(svc.ServiceReqDate),
            'NewScheduleDate',      IFNULL_FORMAT_DATE(v_Date),
            'SLA',                  IFNULL_NUMERIC(funcGetSLA('Search', 'SLA-Region', fsr.ServiceNo)),
            'NetworkDays',          IFNULL_NUMERIC(funcComputeTAT(svc.ReqInstallationDate, v_Date)),
            'TATDueDate',           IFNULL_FORMAT_DATE(funcAddWorkingDays(svc.ReqInstallationDate, funcGetSLA('Search', 'SLA-Region', fsr.ServiceNo))),
            
		'LastAttemptTATStatus',
		CASE
		WHEN fsr.FSRDate IS NULL
		  OR svc.ReqInstallationDate IS NULL
		  OR funcGetSLA('Search', 'SLA-Region', fsr.ServiceNo) <= 0
		THEN 'UNAVAILABLE'

		WHEN fsr.FSRDate > funcAddWorkingDays(svc.ReqInstallationDate, funcGetSLA('Search', 'SLA-Region', fsr.ServiceNo))
		THEN 'BEYOND TAT'
		ELSE 'WITHIN TAT'
		
		END,

		'TATStatus',
		CASE
		    WHEN v_Date IS NULL OR svc.ServiceReqDate IS NULL
		    THEN 'UNAVAILABLE'
		    WHEN v_Date > svc.ServiceReqDate
		
		    THEN 'BEYOND TAT'
		    ELSE 'WITHIN TAT'
		    
		END,

            'Remarks',
            IFNULL_STRING_NORMAL(fsr.Remarks)
        )
    INTO v_outResult
    FROM tblfsrdetail fsr
    INNER JOIN tblservicingdetail svc
        ON svc.ServiceNo = fsr.ServiceNo
    LEFT JOIN tblreason r
        ON r.ReasonID = fsr.ReasonID
    WHERE fsr.JobType = v_JobType
      AND fsr.MerchantID = v_MerchantID
      AND svc.IRNo = v_IRNo
      AND fsr.isActive = 1
      AND IFNULL(fsr.isCancelled, 0) = 0
      AND svc.isActive = 1
      AND IFNULL(svc.isCancelled, 0) = 0
    ORDER BY fsr.FSRNo DESC
    LIMIT 1;
    
ELSEIF (p_SearchBy = 'Search Zoning Info') THEN    
    SET @Address = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
    SET @City = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
    
    SET @search = CONCAT(@Address,",",@City);
    SELECT funcGetZoneID(@search) INTO @ZoneID;
    
    SELECT
        JSON_OBJECT(
            'ZoneID', ZoneID,
            'Zone', IFNULL_STRING_NORMAL(ZoneName),
            'Cluster', IFNULL_STRING_NORMAL(Cluster),
            'Region', IFNULL_STRING_NORMAL(Region),
            'Area', IFNULL_STRING_NORMAL(AREA),
            'CityMunicipal', IFNULL_STRING_NORMAL(CityMunicipal),
            'SLA', IFNULL_NUMERIC(SLA)
        ) INTO v_outResult
    FROM tblzoning
    WHERE
    ZoneID = @ZoneID;  
    
ELSEIF (p_SearchBy = 'Merchant Apps Version-CRC')
THEN
    SET @JobType         = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
    SET @ServiceNo       = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
    SET @IRIDNo          = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
    SET @MerchantID      = TRIM(SPLIT_STRING(p_SearchValue, '|', 4));
    SET @TerminalType  = TRIM(SPLIT_STRING(p_SearchValue, '|', 5));
    SET @TerminalModel = TRIM(SPLIT_STRING(p_SearchValue, '|', 6));

    -- Get latest successful service record
    SET @ServiceNo  = 0;
    SET @AppVersion = NULL;
    SET @AppCRC     = NULL;

    SELECT
    JSON_OBJECT(
        'TerminalTypeID', tt.TerminalTypeID,
        'TerminalModelID', tm.TerminalModelID,
        'AppVersion', COALESCE(sd.AppVersion, tm.AppVersion),
        'AppCRC', COALESCE(sd.AppCRC, tm.AppCRC)
    )
INTO v_outResult
FROM tblterminaltype tt
INNER JOIN tblterminalmodel tm
    ON tt.TerminalTypeID = tm.TerminalTypeID
LEFT JOIN
(
    SELECT
        a.AppVersion,
        a.AppCRC
    FROM tblservicingdetail a
    INNER JOIN tblfsrdetail b
        ON a.ServiceNo = b.ServiceNo
    WHERE a.IRIDNo = @IRIDNo
      AND b.ActionMade = 'SUCCESS'
    ORDER BY a.ServiceNo DESC
    LIMIT 1
) sd ON 1=1
WHERE tt.Description = @TerminalType
  AND tm.Description = @TerminalModel;

ELSEIF (p_SearchBy = 'Expenses Detail') 
THEN
    SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
    SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED);
    SELECT
        a.ExpensesID AS ID,

        JSON_OBJECT(
            'ServiceNo', a.ServiceNo,
            'TAIDNo', a.TAIDNo,
            'IRIDNo', a.IRIDNo,
            'ExpensesID', a.ExpensesID,
            'ExpenseType', IFNULL_STRING_ONLY(b.Description),
            'ExpensesDescription', a.ExpensesDescription,
            'ExpensesAmount', a.ExpensesAmount,
            'ExpensesDate', a.ExpensesDate  
        ) AS detail_info

    FROM tblserviceexpensesdetail a
    LEFT JOIN tblexpenses b
    ON b.ExpensesID = a.ExpensesID

    WHERE a.ServiceNo = v_ServiceNo AND a.IRIDNo = v_IRIDNo
    ORDER BY
        a.ExpensesDate DESC;

ELSEIF (p_SearchBy = 'Expense Reference Sequence')
THEN
    SELECT
        COALESCE(
            MAX(
                CAST(
                    RIGHT(TRIM(ExpensesReferenceNo), 6)
                    AS UNSIGNED INTEGER
                )
            ),
            0
        )
    INTO v_outResult
    FROM tblexpensestransdetail
    WHERE TRIM(ExpensesReferenceNo)
        REGEXP '^EXP-[0-9]{8}-[0-9]{6}$';
	
ELSEIF (p_SearchBy = 'QR Delivery') 
THEN

    SET @tid = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
    SET @mid = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
    SET @merchantName = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
    SET @merchantAddress = TRIM(SPLIT_STRING(p_SearchValue, '|', 4));
    SET @terminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|', 5));
    SET @simSN = TRIM(SPLIT_STRING(p_SearchValue, '|', 6));
    SET @serviceNo = CAST(
    NULLIF(
        TRIM(SPLIT_STRING(p_SearchValue, '|', 7)),
        ''
    )
    AS UNSIGNED
);


    SET v_outResult = NULL;


    /* 1. NORMAL LOOKUP Exact TID + MID */

    SELECT JSON_OBJECT(

        'ServiceNo',
            IFNULL_NUMERIC(b.ServiceNo),

        'IRIDNo',
            IFNULL_NUMERIC(a.IRIDNo),

        'MerchantID',
            IFNULL_NUMERIC(a.MerchantID),

        'MerchantName',
            IFNULL_STRING_ONLY(c.Name),

        'MerchantAddress',
            IFNULL_STRING_ONLY(c.Address),

        'TID',
            IFNULL_STRING_ONLY(a.TID),

        'MID',
            IFNULL_STRING_ONLY(a.MID),

        'JobType',
            IFNULL_NUMERIC(b.JobType),

        'JobTypeDescription',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'Service JobType Description',
                    b.JobType
                )
            ),

        'JobTypeStatusDescription',
            IFNULL_STRING_ONLY(b.JobTypeStatusDescription),

        'TerminalID',
            IFNULL_NUMERIC(b.TerminalID),

        'TerminalSN',
            IFNULL_STRING_ONLY(b.TerminalSN),

        'TerminalStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'Terminal Status',
                    b.TerminalID
                )
            ),

        'pTerminalStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'Terminal Status',
                    b.TerminalID
                )
            ),

        'ReplaceTerminalID',
            IFNULL_NUMERIC(b.ReplaceTerminalID),

        'ReplaceTerminalSN',
            IFNULL_STRING_ONLY(b.ReplaceTerminalSN),

        'ReplaceTerminalStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'Terminal Status',
                    b.ReplaceTerminalID
                )
            ),

        'pReplaceTerminalStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'Terminal Status',
                    b.ReplaceTerminalID
                )
            ),

        'SIMID',
            IFNULL_NUMERIC(b.SIMID),

        'SIMSerialNo',
            IFNULL_STRING_ONLY(b.SIMSerialNo),

        'SIMSN',
            IFNULL_STRING_ONLY(b.SIMSerialNo),

        'SIMStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'SIM Status',
                    b.SIMID
                )
            ),

        'pSIMStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'SIM Status',
                    b.SIMID
                )
            ),

        'ReplaceSIMID',
            IFNULL_NUMERIC(b.ReplaceSIMID),

        'ReplaceSIMSN',
            IFNULL_STRING_ONLY(b.ReplaceSIMSN),

        'ReplaceSIMStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'SIM Status',
                    b.ReplaceSIMID
                )
            ),

        'pReplaceSIMStatus',
            IFNULL_STRING_ONLY(
                funcGetDesc(
                    'Search',
                    'SIM Status',
                    b.ReplaceSIMID
                )
            )

    )
    INTO v_outResult

    FROM tblirdetail a

    INNER JOIN tblservicingdetail b
        ON a.IRIDNo = b.IRIDNo
       AND b.JobType IN (1, 7)

    LEFT JOIN tblparticular c
        ON a.MerchantID = c.ParticularID

    WHERE
(
    /* History search: exact saved ServiceNo */
    (
        @serviceNo IS NOT NULL
        AND @serviceNo > 0
        AND b.ServiceNo = @serviceNo
    )

    OR

    /* Normal scan: find using TID and MID */
    (
        (@serviceNo IS NULL OR @serviceNo = 0)
        AND a.TID = @tid
        AND a.MID = @mid
    )
)

ORDER BY
    CASE
        /* Exact historical ServiceNo gets highest priority */
        WHEN @serviceNo IS NOT NULL
             AND @serviceNo > 0
             AND b.ServiceNo = @serviceNo
        THEN 0

        /* For normal scans, prioritize matching terminal */
        WHEN @terminalSN <> ''
             AND
             (
                 b.TerminalSN = @terminalSN
                 OR b.ReplaceTerminalSN = @terminalSN
             )
        THEN 1

        /* Next priority is matching SIM */
        WHEN @simSN <> ''
             AND
             (
                 b.SIMSerialNo = @simSN
                 OR b.ReplaceSIMSN = @simSN
             )
        THEN 2

        ELSE 3
    END,

    b.ServiceNo DESC

LIMIT 1;


    /*2. RECOVERY LOOKUP - Only execute when exact TID + MID was NOT found*/

    IF v_outResult IS NULL
    AND (@serviceNo IS NULL OR @serviceNo = 0)
    AND @merchantName <> ''
 THEN

        SELECT JSON_OBJECT(

            'ServiceNo',
                IFNULL_NUMERIC(b.ServiceNo),

            'IRIDNo',
                IFNULL_NUMERIC(a.IRIDNo),

            'MerchantID',
                IFNULL_NUMERIC(a.MerchantID),

            'MerchantName',
                IFNULL_STRING_ONLY(c.Name),

            'MerchantAddress',
                IFNULL_STRING_ONLY(c.Address),

            'TID',
                IFNULL_STRING_ONLY(a.TID),

            'MID',
                IFNULL_STRING_ONLY(a.MID),

            'JobType',
                IFNULL_NUMERIC(b.JobType),

            'JobTypeDescription',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'Service JobType Description',
                        b.JobType
                    )
                ),

            'JobTypeStatusDescription',
                IFNULL_STRING_ONLY(b.JobTypeStatusDescription),

            'TerminalID',
                IFNULL_NUMERIC(b.TerminalID),

            'TerminalSN',
                IFNULL_STRING_ONLY(b.TerminalSN),

            'TerminalStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'Terminal Status',
                        b.TerminalID
                    )
                ),

            'pTerminalStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'Terminal Status',
                        b.TerminalID
                    )
                ),

            'ReplaceTerminalID',
                IFNULL_NUMERIC(b.ReplaceTerminalID),

            'ReplaceTerminalSN',
                IFNULL_STRING_ONLY(b.ReplaceTerminalSN),

            'ReplaceTerminalStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'Terminal Status',
                        b.ReplaceTerminalID
                    )
                ),

            'pReplaceTerminalStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'Terminal Status',
                        b.ReplaceTerminalID
                    )
                ),

            'SIMID',
                IFNULL_NUMERIC(b.SIMID),

            'SIMSerialNo',
                IFNULL_STRING_ONLY(b.SIMSerialNo),

            'SIMSN',
                IFNULL_STRING_ONLY(b.SIMSerialNo),

            'SIMStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'SIM Status',
                        b.SIMID
                    )
                ),

            'pSIMStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'SIM Status',
                        b.SIMID
                    )
                ),

            'ReplaceSIMID',
                IFNULL_NUMERIC(b.ReplaceSIMID),

            'ReplaceSIMSN',
                IFNULL_STRING_ONLY(b.ReplaceSIMSN),

            'ReplaceSIMStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'SIM Status',
                        b.ReplaceSIMID
                    )
                ),

            'pReplaceSIMStatus',
                IFNULL_STRING_ONLY(
                    funcGetDesc(
                        'Search',
                        'SIM Status',
                        b.ReplaceSIMID
                    )
                )

        )
        INTO v_outResult

        FROM tblirdetail a

        INNER JOIN tblservicingdetail b
            ON a.IRIDNo = b.IRIDNo
           AND b.JobType IN (1, 7)

        INNER JOIN tblparticular c
            ON a.MerchantID = c.ParticularID

        WHERE c.Name = @merchantName

          AND
          (
                (
                    @terminalSN <> ''
                    AND
                    (
                        b.TerminalSN = @terminalSN
                        OR b.ReplaceTerminalSN = @terminalSN
                    )
                )

                OR

                (
                    @simSN <> ''
                    AND
                    (
                        b.SIMSerialNo = @simSN
                        OR b.ReplaceSIMSN = @simSN
                    )
                )
          )

        ORDER BY
            CASE

                WHEN @terminalSN <> ''
                     AND
                     (
                         b.TerminalSN = @terminalSN
                         OR b.ReplaceTerminalSN = @terminalSN
                     )
                THEN 1

                WHEN @simSN <> ''
                     AND
                     (
                         b.SIMSerialNo = @simSN
                         OR b.ReplaceSIMSN = @simSN
                     )
                THEN 2

                ELSE 3

            END,

            b.ServiceNo DESC

        LIMIT 1;

    END IF;
	
ELSEIF (p_SearchBy = 'Expenses Master') 
THEN
    SET @ExpensesNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
    
    SELECT       

        JSON_OBJECT(
            -- 'ExpensesID', IFNULL_NUMERIC(a.ExpensesID),            
            'ServiceNo', IFNULL_NUMERIC(a.ServiceNo),
            'IRIDNo', IFNULL_NUMERIC(a.IRIDNo),
            'MerchantID', IFNULL_NUMERIC(a.MerchantID),
            'MerchantName', funcGetDesc("Search", "Particular", a.MerchantID),
            'ClientID', IFNULL_NUMERIC(a.ClientID),
            'ClientName', funcGetDesc("Search", "Particular", a.ClientID),
            'FEID', IFNULL_NUMERIC(a.FEID),
            'FEName', funcGetDesc("Search", "Particular", a.FEID),
            'ReferenceNo', IFNULL_STRING_ONLY(a.ReferenceNo),
            'CreatedBy', IFNULL_STRING_ONLY(a.CreatedBy),
            'CreatedDate', IFNULL_FORMAT_DATETIME(a.CreatedDate),
            'UpdatedBy', IFNULL_STRING_ONLY(a.UpdatedBy),
            'UpdatedDate', IFNULL_FORMAT_DATETIME(a.UpdatedDate),
            'ServiceNoList', IFNULL_STRING_ONLY2(a.ServiceNoList),
            'IRNoList', IFNULL_STRING_ONLY(a.IRNoList),
            'ReceiptList', IFNULL_STRING_ONLY(a.ReceiptList),
            'ReceiptDateList', IFNULL_STRING_ONLY(a.ReceiptDateList),
            'ReceiptAmountList', IFNULL_STRING_ONLY(a.ReceiptAmountList),
            'TAmount', a.TotalAmount,
            'DateTimeStamp', IFNULL_FORMAT_DATE(a.DateTimeStamp)
        ) INTO v_outResult

    FROM tblexpensestransmaster a    

    WHERE 
    a.ExpensesNo = @ExpensesNo;
					
END IF;


#SELECT CONCAT("v_outResult=",v_outResult);

END IF; 

IF (LENGTH(v_outResult) > 0)
THEN
	SET p_outResult = v_outResult;
ELSE
	SET p_outResult = "";
END IF;

#SELECT(CONCAT("p_outResult=", p_outResult));





END */$$
DELIMITER ;

/* Procedure structure for procedure `spGetLastControlID` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGetLastControlID` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGetLastControlID`(  
IN p_StatementType VARCHAR(30) /* = NULL */	,
IN p_TableName VARCHAR(20) /* = NULL */ , 	
OUT p_outLastControlID INTEGER
)
BEGIN
DECLARE v_ControlID INT;

IF (p_StatementType = 'Search')
THEN
	IF (p_TableName = 'Request Form')
	THEN
		SELECT RequestID INTO v_ControlID 
		FROM tblrequestformmaster 
		ORDER BY RequestID DESC;            
	END IF;		
END IF;

IF (v_ControlID > 0)
THEN
	SET p_outLastControlID = v_ControlID + 1;
ELSE
	SET p_outLastControlID = 1;
END IF;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spGetLastInsertID` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGetLastInsertID` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGetLastInsertID`(  
IN p_StatementType VARCHAR(30) /* = NULL */ ,	
IN p_SearchBy VARCHAR(50) /* = NULL */ ,
IN p_SearchValue VARCHAR(50) /* = NULL */ ,
OUT p_outLastInsertID INTEGER
)
BEGIN
DECLARE v_LastID INT;
SET v_LastID = 0;
IF (p_StatementType = 'View')
THEN    		
SELECT LAST_INSERT_ID() INTO p_outLastInsertID;
END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `spGetQueryString` */

/*!50003 DROP PROCEDURE IF EXISTS  `spGetQueryString` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spGetQueryString`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */ ,

    OUT p_outQueryString LONGTEXT

)
BEGIN

	DECLARE v_ID INTEGER;

    DECLARE v_QueryString LONGTEXT;

    	

    IF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Particular')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			

			SELECT   

			QueryString INTO v_QueryString

			FROM tblparticular

			WHERE (ParticularID = v_ID)

            LIMIT 1;		

		 END IF;

         

	END IF; 

    

    SET p_outQueryString = v_QueryString;

    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spInsertCollectionDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spInsertCollectionDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spInsertCollectionDetail`(IN p_StatementType VARCHAR(50),
    IN p_SearchBy VARCHAR(50),
    IN p_SearchValue VARCHAR(50),
    IN p_MaintenanceType VARCHAR(50),
    IN p_SQL longtext,
    OUT p_outErrorMessage VARCHAR(200),
    OUT p_outLastInsertID INT)
BEGIN  

DECLARE v_LastID INT;
DECLARE v_SystemDate DATE;
DECLARE v_SystemTime TIME;

DECLARE EXIT HANDLER FOR SQLEXCEPTION
SET p_outErrorMessage = 'SQLException invoked';
DECLARE EXIT HANDLER FOR 1062
SET p_outErrorMessage = 'MySQL error code 1062 invoked';
DECLARE EXIT HANDLER FOR SQLSTATE '23000'
SET p_outErrorMessage = 'MySQL 23000 invoked';

#SELECT (CONCAT('p_StatementType=', p_StatementType));
#SELECT (CONCAT('p_MaintenanceType=', p_MaintenanceType));

SET v_SystemDate = CURDATE();
SET v_SystemTime = CURTIME();

#SELECT (CONCAT('v_SystemDate=', v_SystemDate, ",v_SystemTime=", v_SystemTime));

START TRANSACTION;

IF (p_StatementType = 'Insert') 
THEN  		

	IF (p_MaintenanceType = 'FSR Import Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblfsrdetail(FSRID, `No`, Merchant, `MID`, TID, TimeArrived, 
		InvoiceNo, TimeStart, BatchNo, FSR, FSRDate, FSRTime, TxnAmt, TimeEnd, TerminalSN, 
		MerchantContactNo, MerchantRepresentative, FEName, Remarks, SerialNo, FSRStatus, FSRStatusDescription, 
		ServiceStatus, ServiceStatusDescription, ReasonID, ClientID, ClientName, ProcessType, TAIDNo, IRNo)
		VALUES ', p_SQL);
	
	ELSEIF (p_MaintenanceType = 'FSR Import Detail Dummy')	
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblfsrdetaildummy(FSRID, `No`, Merchant, `MID`, TID, TimeArrived, 
		InvoiceNo, TimeStart, BatchNo, FSR, FSRDate, FSRTime, TxnAmt, TimeEnd, TerminalSN, 
		MerchantContactNo, MerchantRepresentative, FEName, Remarks, SerialNo, FSRStatus, FSRStatusDescription, 
		ServiceStatus, ServiceStatusDescription, ReasonID, ClientID, ClientName, ProcessType, TAIDNo, IRNo)
		VALUES ', p_SQL);	
		
	ELSEIF (p_MaintenanceType = 'Terminal Import Detail')
	THEN        
		SET @QUERY = CONCAT('INSERT INTO tblterminaldetail(TIID, `No`, TerminalSN, SerialNo, Type, Model, Brand, 
		DeliveryDate, ReceiveDate, TerminalTypeID, TerminalModelID, TerminalBrandID, PartNo, PONo, InvNo, 
		LocationID, Location, ParticularID, Allocation, AssetType,
		Remarks, ClientName, ClientID, TerminalStatusDescription, TerminalStatus)
		VALUES ', p_SQL);
	
	ELSEIF (p_MaintenanceType = 'SIM Import Detail')
	THEN        
		SET @QUERY = CONCAT('INSERT INTO tblsimdetail(FEID, BatchNo, SIMSN, SerialNo, CarrierID, Carrier, AssignedTo, 
		LocationID, Location, ParticularID, Allocation,
		Remarks, DeliveryDate, ReceiveDate, ClientID, ClientName, SIMStatus, SIMStatusDescription)
		VALUES ', p_SQL);	
		
	ELSEIF (p_MaintenanceType = 'IR Import Master')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblinstallationrequestdetail(IRID,IR_No,MCC_INSTALLATION_REQUEST_ID,DATE_REQUEST,VENDOR,RM,SET_UP,TERMINAL_TYPE,REQUEST_FOR,INSTALLATION_DATE,
		Time_of_Deployment,PULL_OUT_DATE,OTHER_SPECIAL_INSTRUCTION,MERCHANT_DBA_NAME,ADDRESS_1,ADDRESS_2,ADDRESS_3,
		ADDRESS_4,MERCH_DBA_CITY,LOCATION,CONTACT_PERSON,Email,Voice,SMS,PRIME_TID_01,PRIME_MID_01,PRIME_TID_02,PRIME_MID_02,RETAIL,ZERO_INSTALLMENT,ZERO_TENOR,
		REDUCED_INSTALLMENT,REDUCED_TENOR,REGULAR_INSTALLMENT,REGULAR_TENOR,SNPL_INSTALLMENT,
		SNPL_TENOR,RTR,ABENSON_TID,ABENSON_MID,EGC_TID,EGC_MID,SHOP_CARD_TID,SHOP_CARD_MID,DEBIT_TID,DEBIT_MID,ALIPAY_TID,ALIPAY_MID,DINERS_STRAIGHT_TID,DINERS_STRAIGHT_MID,
		DINERS_0_3_24_MOS_TID,DINERS_0_3_24_MOS_MID,DINERS_REDUCE_3_12_MOS_TID,DINERS_REDUCE_3_12_MOS_MID,
		DINERS_REGULAR_TID,DINERS_REGULAR_MID,SBC_MC_REGULAR_TID,SBC_MC_REGULAR_MID,SBC_MC_REDUCE_3_12_MOS_TID,SBC_MC_REDUCE_3_12_MOS_MID,SBC_MC_0_3_24_MOS_TID,SBC_MC_0_3_24_MOS_MID,
		BANK,MERCHANT,STORE,HAPPY_PLUS_TID,HAPPY_PLUS_MID,SAM_ID,PASSWORD,STATUS,
		STATUS_DATE,SERIAL_NUMBER,BASED_SERIAL_NUMBER,Remarks,REPORT_DATE)
		VALUES ', p_SQL);    
		
	ELSEIF (p_MaintenanceType = 'IR Import Detail')
	THEN        
		SET @QUERY = CONCAT('INSERT INTO tblirdetail(IRID, ParticularID, MerchantID, 
		IRNo, IRDate, InstallationDate, MerchantName, Name, 
		TID, `MID`, IRStatus, IRStatusDescription, ClientID, ClientName,
		POS_TYPE, REQUEST_FOR, SET_UP, Remarks, AnyComments, OTHER_SPECIAL_INSTRUCTION,
		ProcessType, ProcessedDateTime, ModifiedDateTime, ProcessedBy, ModifiedBy)
		VALUES ', p_SQL);  		#SELECT (CONCAT("@QUERY=", @QUERY));
	ELSEIF (p_MaintenanceType = 'Service Call Detail')
	THEN        
		SET @QUERY = CONCAT('INSERT INTO tblservicecalldetail(TAIDNo, ClientID, MerchantID, 
		ClientName, MerchantName, IRIDNo, IRNo, TerminalID, TerminalSN, SIMID, SIMSerialNo, 
		AttemptNo, ReferralID, SCDateTime, SCDate, SCTime, SCReqDate, SCReqTime, SCShipDate, 
		SCShipTime, CustomerName, CustomerContactNo, ReportedProblem, ArrangementMade, TrackingNo, 
		SCStatus)
		VALUES ', p_SQL);	
		
	ELSEIF (p_MaintenanceType = 'Servicing Detail')
	THEN        
		SET @QUERY = CONCAT('INSERT INTO tblservicingdetail(TAIDNo, 
		ClientID, MerchantID, FEID,
		ClientName, MerchantName, FEName, 
		IRIDNo, IRNo,
		TerminalID, TerminalSN, SIMID, SIMSerialNo, DockID, DockSN, 
		CounterNo, RequestNo, ServiceDateTime, ServiceDate, ServiceTime, CustomerName, 
		CustomerContactNo, CustomerPosition, CustomerEmail, Remarks, ServiceReqDate, ServiceReqTime, LastServiceRequest, 
		NewServiceRequest, 
		ReplaceTerminalID, ReplaceTerminalSN, ReplaceSIMID, ReplaceSIMSN, ReplaceDockID, ReplaceDockSN, 
		JobType, 
		JobTypeDescription, JobTypeSubDescription, JobTypeStatusDescription, ReferenceNo, RegionID, RegionType, isBillable, isPrimary,
		AppVersion, AppCRC, DispatchID, DispatchBy, DispatchDateTime, DispatchDate, DispatchTime,
		ProcessedBy, ModifiedBy, ProcessedDateTime, ModifiedDateTime,
		ReqInstallationDate, ProblemReported, RMInstruction, SourceID, CategoryID, SubCategoryID, Vendor, Requestor, BillingTypeID)
		VALUES ', p_SQL);
		
		#SELECT (CONCAT("@QUERY=", @QUERY));
		
	ELSEIF (p_MaintenanceType = 'Terminal Allocation')
        THEN        			
		SET @QUERY = CONCAT('INSERT INTO tblterminalallocation(TAID, ClientID, ServiceProviderID, FEID, IRID, IRIDNo, IRNo, MerchantID, TerminalID, TerminalSN, TerminalTypeID, 
	        TerminalModelID, TerminalBrandID, ServiceTypeID, OtherServiceTypeID, TADateTime, ProcessedBy, ModifiedBy, 
	        ProcessedDateTime, ModifiedDateTime, Remarks, Comments, TID, `MID`, SIMID, SIMSerialNo, RegionID, Region, 
	        ServiceTypeStatus, ServiceTypeStatusDescription, DockID, DockSN, 
	        JobType, JobTypeDescription, JobTypeSubDescription, JobTypeStatusDescription, RegionType)
		VALUES ', p_SQL); 
	
	ELSEIF (p_MaintenanceType = 'FSR Manual Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblfsrdetail(FSRID, `No`, MerchantID, Merchant, `MID`, TID, MobileID, MobileTerminalID, MobileVersion, TimeArrived, 
		InvoiceNo, TimeStart, BatchNo, FSR, FSRDate, FSRTime, TxnAmt, TimeEnd, TerminalID, TerminalSN, SIMID, SIMSN,
		MerchantContactNo, MerchantRepresentative, MerchantRepresentativePosition, FEID, FEName, Remarks, SerialNo, FSRStatus, FSRStatusDescription, 
		ServiceStatus, ServiceStatusDescription, ReasonID, Reason, ClientID, ClientName, ProcessType, TAIDNo, IRIDNo, IRNo, ServiceNo, ServiceCode, FSRRefNo,
		ActionMade, JobType, JobTypeDescription, ProblemReported, ActualProblemReported, ActionTaken, AnyComments,
		ProcessedBy, ModifiedBy, 
	        ProcessedDateTime, ModifiedDateTime, 
	        geoLatitude, geoLongitude, geoCountry, geoLocality, geoAddress)
		VALUES ', p_SQL);
		
		#SELECT CONCAT("QUERY=",@QUERY);
	
	ELSEIF (p_MaintenanceType = 'FSR Manual Detail Dummy')	
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblfsrdetaildummy(FSRID, `No`, Merchant, `MID`, TID, TimeArrived, 
		InvoiceNo, TimeStart, BatchNo, FSR, FSRDate, FSRTime, TxnAmt, TimeEnd, TerminalSN, 
		MerchantContactNo, MerchantRepresentative, FEName, Remarks, SerialNo, FSRStatus, FSRStatusDescription, 
		ServiceStatus, ServiceStatusDescription, ReasonID, ClientID, ClientName, ProcessType, TAIDNo, IRIDNo, IRNo, ActionMade, JobTypeDescription, ProblemReported, ActualProblemReported, ActionTaken)
		VALUES ', p_SQL);	
		
	-- RAIDEN 
	ELSEIF (p_MaintenanceType = 'Service Expenses Detail')	
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblexpensestransdetail(ExpensesReferenceNo, ServiceNo, TAIDNo, IRIDNo, ExpensesID, Amount, Remarks, ExpensesDate)
		VALUES ', p_SQL);
	
	ELSEIF (p_MaintenanceType = 'Duplicate Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblduplicatedetail(DupData, DupType, DupDate, DupTime)
		VALUES ', p_SQL);
	
	ELSEIF (p_MaintenanceType = 'Leave Assignment')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblleaveassignment(ParticularID, LeaveTypeID, Code, Remarks, ProcessedBy, ProcessedDateTime, ModifiedBy, ModifiedDateTime, CreditLimit, LeaveCredit)
		VALUES ', p_SQL);
	
	ELSEIF (p_MaintenanceType = 'Leave Movement')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblleavemovement(ParticularID, LeaveTypeID, Code,
						 DateFrom, DateTo, Duration, ProcessedBy, ProcessedDateTime, ModifiedBy, ModifiedDateTime, ReasonID, DateType, 
						 Remarks, isActive)
		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'Privacy Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblprivacydetail(UserID, FullName, PrivacyID, Description,
						 isView, isAdd, isUpdate, isDelete, isPrint)
		VALUES ', p_SQL);	
		
	ELSEIF (p_MaintenanceType = 'Terminal Activity')
	THEN	
		SET @QUERY = CONCAT('INSERT INTO tblterminalactivity(TerminalID, TerminalSN, ParticularID, ParticularName,
						 `Status`, StatusDescription, Operation, OperationDescription, `Date`, `Time`, Remarks, ProcessedBy, ProcessedDateTime, ModifiedBy, ModifiedDateTime, ServiceNo, IRNo)
		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'SIM Activity')
	THEN	
		SET @QUERY = CONCAT('INSERT INTO tblsimactivity(SIMID, SIMSN, ParticularID, ParticularName,
						 `Status`, StatusDescription, Operation, OperationDescription, `Date`, `Time`, Remarks, ProcessedBy, ProcessedDateTime, ModifiedBy, ModifiedDateTime, ServiceNo, IRNo)
		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'Terminal Movement Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblterminalmovementdetail(TransNo, TerminalID, TerminalTypeID, TerminalModelID, SerialNo)
		VALUES ', p_SQL);
					 					 
	ELSEIF (p_MaintenanceType = 'SIM Movement Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblsimmovementdetail(TransNo, SIMID, SerialNo, Carrier)
		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'Invoice Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblpr_invoicesdetail(InvoiceID, InvoiceNo, InvoiceDate, InvoiceTime, IRIDNo, ParticularID, MerchantID, TID, `MID`, Description, RentalFee)
		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'Duplicate Detail2')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblduplicatedetail(DupID, ControlNo, SerialNo, DupData, DupType, DupDate, DupTime)
		VALUES ', p_SQL);	
	ELSEIF (p_MaintenanceType = 'Diagnostic Detail')
	THEN

		#Delete existing

		#SELECT(CONCAT("p_SearchValue=", p_SearchValue));     

		IF (LENGTH(p_SearchValue) > 0)

		THEN

			CALL spDeleteCollectionDetail("Delete", "", p_SearchValue, p_MaintenanceType);

		END IF;
		SET @QUERY = CONCAT('INSERT INTO tbldiagnosticdetail(FSRNo, ServiceNo, TypeID, TypeDescription, SelectionID, Description, SelectedValue)

		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'Manual Diagnostic Detail')
	THEN

		#Delete existing

		#SELECT(CONCAT("p_SearchValue=", p_SearchValue));     

		IF (LENGTH(p_SearchValue) > 0)
		THEN
			CALL spDeleteCollectionDetail("Delete", "", p_SearchValue, p_MaintenanceType);

		END IF;
		SET @QUERY = CONCAT('INSERT INTO tbldiagnosticdetail(FSRNo, ServiceNo, TypeID, TypeDescription, SelectionID, Description, SelectedValue)

		VALUES ', p_SQL);	
	ELSEIF (p_MaintenanceType = 'Service Changes Detail')
	THEN

		#Delete existing

		#SELECT(CONCAT("p_SearchValue=", p_SearchValue));     

		IF (LENGTH(p_SearchValue) > 0)
		THEN
			CALL spDeleteCollectionDetail("Delete", "", p_SearchValue, p_MaintenanceType);

		END IF;
		SET @QUERY = CONCAT('INSERT INTO tblservicechangesdetail(ServiceNo, IRIDNo, MerchantID, MapID, ChangeFrom, ChangeTo)

		VALUES ', p_SQL);	
		
	ELSEIF (p_MaintenanceType = 'Stock Detail')
	THEN        
		SET @QUERY = CONCAT('INSERT INTO tblstockdetail(StockID, ClientID, LocationID, TerminalTypeID, TerminalModelID, TerminalBrandID, SerialNo, StockStatus, DeliveryDate, ReceiveDate, ReleaseDate,
		Allocation, AssetType, PONo, InvNo, PartNo, Remarks)
		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'Stock Movement Detail')
	THEN        
		SET @QUERY = CONCAT('INSERT INTO tblstockmovementdetail(ServiceNo, JobType, IRIDNo, ClientID, ItemID, ReplaceItemID)
		VALUES ', p_SQL);
		
	ELSEIF (p_MaintenanceType = 'MSP Detail')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblmspdetail(MSPNo, ClientID, MerchantID, CreatedID, CreatedAt, SubmitAt, ResultStatus, Remarks)
		VALUES ', p_SQL);	
		
		#SELECT(CONCAT("@QUERY=", @QUERY));
	
	ELSEIF (p_MaintenanceType = 'Helpdesk-Details')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblhddetail
									(AssistNo,
									 RequestID,
									 HelpdeskID,
									 TeamLeadID,
									 CreatedDate,
									 ReasonID, 
									 ContactPerson, 
									 ContactNo, 
									 ContactPosition, 
									 ContactEmail,
									 RequestedBy,
									 Representative,
									 TerminalID,
									 SIMID, 
									 TerminalSN, 
									 SIMSN, 
									 DockerSN,
									 ActualProblem, 
									 ProblemReported, 
									 RemarksHelpDesk, 
									 RemarksService, 
									 SourceID,
									 CategoryID,
									 SubCategoryID,
									 CreatedID, 
									 CreatedAt,
									 CompletedAt,
									 Status, 
									 TimeAssisted, 
									 TimeStart, 
									 TimeEnd,
									 Attempts,
									 RequestDate,
									 AppVersion,
									 AppCrc,
									 ProblemID,
									 DependencyID,
									 StatusReasonID,
									 IssueCategoryID)
			VALUES ', p_SQL);	
		
			#SELECT(CONCAT("@QUERY=", @QUERY));
		
			SET @v_AssistNo = REPLACE(REPLACE(REPLACE(SPLIT_STRING(p_SQL, ',', 1), "'", ''), '(', ''), ')', '');
			SET @v_Status   = REPLACE(REPLACE(REPLACE(SPLIT_STRING(p_SQL, ',', 28), "'", ''), '(', ''), ')', '');
			SET @RequestDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
				#Debug Value
				#Select @v_AssistNo, @v_Status;
				
				-- Update Only if the status is PENDING
				IF @v_Status = 'PENDING' THEN
				
					SET @v_Update = CONCAT(
						 'UPDATE tblhdmaster ',
						 'SET Status = ''PENDING'', ',
						 'RequestDate = ''', @RequestDate, ''' ',
						 'WHERE AssistNo = ', @v_AssistNo, ';'
					);
				ELSE
					-- Otherwise, set status to RESOLVED
					SET @v_Update = CONCAT(
						 'UPDATE tblhdmaster ',
						 'SET Status = ''SUCCESS'', ',
						 'RequestDate = NULL ',
						 'WHERE AssistNo = ', @v_AssistNo,	
						 ';'
					);
			  END IF;
		  		  			
			PREPARE stmt FROM @v_Update;
			EXECUTE stmt;
			DEALLOCATE PREPARE stmt;
		
			#SELECT(CONCAT("@QUERY=", @QUERY));
	
	#Nikko QR DELIVERY
        ELSEIF (p_MaintenanceType = 'QR Delivery Detail')
        THEN
                SET @QUERY = CONCAT('INSERT INTO tblservicingqrdetail(ServiceNo, IRIDNo, MerchantID, QRDate, QRContent, InternalQRContent, ProcessedBy, InventoryStatus, TerminalPrepStatus, DispatcherStatus, QRResult)
         VALUES ', p_SQL);

	ELSEIF (p_MaintenanceType = 'HelpDesk-Master')
	THEN
		SET @QUERY = CONCAT('INSERT INTO tblhdmaster(IRIDNo, ReferenceNo, RequestDate, Requestor, CreatedID, CreatedAt, JobType, Status)
		VALUES ', p_SQL);
		
		#SELECT(CONCAT("@QUERY=", @QUERY));
		
	ELSEIF (p_MaintenanceType = 'Servicing Activity Detail')
	THEN
	    -- Delete any previously abandoned open row for this ServiceNo + ActivityID
	    -- before starting a new one, so no orphaned NULL-EndDateTime rows remain.
	    SET @v_ServiceNo = TRIM(SPLIT_STRING(p_SQL, ',', 2));
	    SET @v_ActivityID = TRIM(SPLIT_STRING(p_SQL, ',', 4));

	    DELETE FROM tblservicingactivitydetail
	    WHERE ServiceNo = @v_ServiceNo
	      AND ActivityID = @v_ActivityID
	      AND EndDateTime IS NULL;

	    SET @QUERY = CONCAT('INSERT INTO tblservicingactivitydetail(IRIDNo, ServiceNo, MerchantID, ActivityID, StartDateTime, EndDateTime, ParticularID, ParticularName)
	    VALUES ', p_SQL);
	    
	    #SELECT(CONCAT("@QUERY=", @QUERY));
	
	 ELSEIF (p_MaintenanceType = 'Service Expenses Detail') 
	 THEN
	    SET @QUERY = CONCAT('INSERT INTO tblexpensestransdetail(ExpensesReferenceNo, ServiceNo, TAIDNo, IRIDNo, ExpensesID, Amount, Remarks, ExpensesDate) 
		VALUES ', p_SQL);
		
		#SELECT (CONCAT('@QUERY=', @QUERY)); 
		
	  ELSEIF (p_MaintenanceType = 'Expenses Trans Detail') 
	 THEN
	    SET @QUERY = CONCAT('INSERT INTO tblexpensestransdetail(ExpensesNo, ExpensesID, ServiceNo, IRIDNo, ExpensesReferenceNo, ExpensesDate, Amount, Remarks, LocationFrom, LocationTo, MerchantName, ReceiptFileName) 
		VALUES ', p_SQL);
		
		#SELECT (CONCAT('@QUERY=', @QUERY)); 
	
	END IF;   
	
	#SELECT(CONCAT("@QUERY=", @QUERY));       

	# Execute Query 
	PREPARE QUERY FROM @QUERY;
	EXECUTE QUERY;

	SET p_outErrorMessage = '';
	
	# Set Last Insert ID
        SELECT LAST_INSERT_ID() INTO v_LastID;
        SET p_outLastInsertID = IFNULL(v_LastID, 0);
        
        #SELECT (CONCAT('p_outLastInsertID=', p_outLastInsertID));

END IF; 

COMMIT;
       
END */$$
DELIMITER ;

/* Procedure structure for procedure `spInsertCollectionMaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `spInsertCollectionMaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spInsertCollectionMaster`(
IN p_StatementType VARCHAR(50),
IN p_MaintenanceType VARCHAR(50),
IN p_SQL longtext,
OUT p_outErrorMessage VARCHAR(200),
OUT p_outLastInsertID INT)
BEGIN  
DECLARE v_LastID INT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION
SET p_outErrorMessage = 'SQLException invoked';
DECLARE EXIT HANDLER FOR 1062
SET p_outErrorMessage = 'MySQL error code 1062 invoked';
DECLARE EXIT HANDLER FOR SQLSTATE '23000'
SET p_outErrorMessage = 'MySQL 23000 invoked';
#SELECT (CONCAT('p_StatementType=', p_StatementType));
#SELECT (CONCAT('p_MaintenanceType=', p_MaintenanceType));
START TRANSACTION;
IF (p_StatementType = 'Insert') 
THEN  
IF (p_MaintenanceType = 'FSR Import Master')
THEN        
		SET @QUERY = CONCAT('INSERT INTO tblfsrmaster(ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy)
			    VALUES ', p_SQL);
	    
 ELSEIF (p_MaintenanceType = 'Terminal Import Master')
 THEN        
		SET @QUERY = CONCAT('INSERT INTO tblterminalmaster(ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy)
			    VALUES ', p_SQL);

 ELSEIF (p_MaintenanceType = 'SIM Import Master')
 THEN        
		SET @QUERY = CONCAT('INSERT INTO tblsimmaster(ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy)
			    VALUES ', p_SQL);
				       
 ELSEIF (p_MaintenanceType = 'IR Import Master')
 THEN        			
		SET @QUERY = CONCAT('INSERT INTO tblinstallationrequestmaster(ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy)
			    VALUES ', p_SQL);      
  
 ELSEIF (p_MaintenanceType = 'Terminal Movement Master')
 THEN        
		SET @QUERY = CONCAT('INSERT INTO tblterminalmovementmaster(TransDate, TransTime, ReleaseDate, FromLocationID, FromLocation, ToLocationID, ToLocation, UserID, RequestNo, ReferenceNo, Remarks, ProcessedBy, ProcessedDateTime, ModifiedBy, ModifiedDateTime)
			    VALUES ', p_SQL);
			    
ELSEIF (p_MaintenanceType = 'SIM Movement Master')
 THEN        
		SET @QUERY = CONCAT('INSERT INTO tblsimmovementmaster(TransDate, TransTime, ReleaseDate, FromLocationID, FromLocation, ToLocationID, ToLocation, UserID, RequestNo, ReferenceNo, Remarks, ProcessedBy, ProcessedDateTime, ModifiedBy, ModifiedDateTime)
			    VALUES ', p_SQL);
			    
ELSEIF (p_MaintenanceType = 'Invoice Master')
 THEN        
		SET @QUERY = CONCAT('INSERT INTO tblpr_invoicesmaster(InvoiceNo, AccountNo, CustomerNo, ParticularID, MerchantID, InvoiceDate, InvoiceTime, ReferenceNo, 
									DateCoveredFrom, DateCoveredTo, 
									DateDue, ProcessedBy, ProcessedDateTime, ModifiedBy, ModifiedDateTime, ModeOfPayment,
									NoteToCustomer, NoteToSelf, TAmtDue, UserID)
			    VALUES ', p_SQL);	
							

ELSEIF (p_MaintenanceType = 'eFSR Registration')
 THEN        			
		SET @QUERY = CONCAT('INSERT INTO tblregistration(IMEID, ProductName, ModelName)
			    VALUES ', p_SQL); 	
			    
ELSEIF (p_MaintenanceType = 'Stock Master')
THEN        
		SET @QUERY = CONCAT('INSERT INTO tblstockmaster(ProcessDate, ProcessTime, UserID, FileName, FullPath, ReferenceNo, Remarks)
		VALUES ', p_SQL);

ELSEIF (p_MaintenanceType = 'MSP Master')
THEN
		SET @QUERY = CONCAT('INSERT INTO tblmspmaster(ReferenceNo, ClientID, MerchantID, CreatedID, CreatedAt, UpdatedID, UpdatedAt, SubmitID, SubmitAt,
								RegisteredName, TradeName, NoBTypeID, BusTypeID, CategoryTypeID, TINNo, AcqTypeID, ReferralTypeID, 
								NoOfPOS, MDRCreditTypeID, MDRDebitTypeID, MDRInstTypeID, SchemeTypeID, NoOfYear, RentalAmt, 
								MSPStatus, ProcessedID, ProcessedDateTime, Remarks)
		VALUES ', p_SQL);
		
		#SELECT (CONCAT('@QUERY=', @QUERY)); 
		
ELSEIF (p_MaintenanceType = 'Report Data Storage Header')
THEN
		SET @QUERY = CONCAT('INSERT INTO tblreportdatastorage(StorageType, Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount)
		VALUES ', p_SQL);
		
		#SELECT (CONCAT('@QUERY=', @QUERY)); 
ELSEIF (p_MaintenanceType = 'Service Expenses Master')
THEN
    SET @ServiceNo = CAST(TRIM(SPLIT_STRING(p_SQL, '|', 1)) AS UNSIGNED INTEGER);
    SET @MasterReferenceNo = TRIM(SPLIT_STRING(p_SQL, '|', 2));

    SET @QUERY = CONCAT('INSERT INTO tblexpensestransmaster(ServiceNo, ServiceDate, FEID, ClientID, Location, ReferenceNo, Remarks, TotalAmount, CreatedBy)
        SELECT d.ServiceNo, MAX(d.ExpensesDate), f.FEID, f.ClientID, f.geoLocality, ',QUOTE(@MasterReferenceNo),', f.JobTypeDescription, SUM(d.Amount), f.ProcessedBy
        FROM tblexpensestransdetail d
        INNER JOIN(SELECT FEID, ClientID, geoLocality, JobTypeDescription, ProcessedBy
        FROM tblfsrdetail WHERE ServiceNo = ', @ServiceNo,' LIMIT 1
        ) f ON 1 = 1
        WHERE d.ServiceNo = ',
        @ServiceNo, '
        GROUP BY
            d.ServiceNo,
            f.FEID,
            f.ClientID,
            f.geoLocality,
            f.JobTypeDescription,
            f.ProcessedBy
        ON DUPLICATE KEY UPDATE
            ServiceDate = VALUES(ServiceDate),
            FEID = VALUES(FEID),
            ClientID = VALUES(ClientID),
            Location = VALUES(Location),
            ReferenceNo = VALUES(ReferenceNo),
            Remarks = VALUES(Remarks),
            TotalAmount = VALUES(TotalAmount),
            UpdatedDate = NOW()'
    );

		#SELECT (CONCAT('@QUERY=', @QUERY)); 
		
ELSEIF (p_MaintenanceType = 'Expenses Trans Master')
THEN
		SET @QUERY = CONCAT('INSERT INTO tblexpensestransmaster(ServiceDate, ExpensesDate, ReferenceNo, ServiceNo, IRIDNo, 
									MerchantID, ClientID, Location, TotalAmount, CreatedBy, 
									CreatedDate, UpdatedBy, UpdatedDate, ServiceNoList, IRIDNoList, MerchantIDList,
									IRNoList, ReceiptList, ReceiptDateList, ReceiptAmountList, FEID, Remarks)
		VALUES ', p_SQL);
		
		#SELECT (CONCAT('@QUERY=', @QUERY)); 		
		
 END IF;     
      
#SELECT (CONCAT('var_sql_statement=', var_sql_statement));   
#SELECT (CONCAT('@QUERY=', @QUERY));         
	
# Execute Query 
PREPARE QUERY FROM @QUERY;
EXECUTE QUERY;
	
SET p_outErrorMessage = '';
# Set Last Insert ID
SELECT LAST_INSERT_ID() INTO v_LastID;
SET p_outLastInsertID = IFNULL(v_LastID, 0);
#SELECT (CONCAT('p_outLastInsertID=', p_outLastInsertID));
END IF; 
COMMIT;
END */$$
DELIMITER ;

