SET p_outErrorMessage = 'MySQL error code 1062 invoked';
DECLARE EXIT HANDLER FOR SQLSTATE '23000'
SET p_outErrorMessage = 'MySQL 23000 invoked';
START TRANSACTION;
IF (p_StatementType = 'Insert') 
THEN  		
IF (p_MaintenanceType = 'FSR Import Detail')
THEN
	SET @QUERY = CONCAT('INSERT INTO tblfsrdetail(FSRID, No, Merchant, MID, TID, TimeArrived, InvoiceNo, TimeStart, BatchNo, FSR, FSRDate, FSRTime, TxnAmt, TimeEnd, TerminalSN, MerchantContactNo, MerchantRepresentative, FEName, Remarks, SerialNo, FSRStatus, FSRStatusDescription, ServiceStatus, ServiceStatusDescription, ReasonID, ClientID, ClientName, ProcessType, TAIDNo, IRNo)
