	ELSEIF (p_MaintenanceType = 'Report Status')

	THEN 

		SET @QUERY = CONCAT('INSERT INTO tblreportstatus(ReportDesc, StatusID, Status, ProcessedAt, ProcessedBy)

		VALUES ', p_SQL);    			

		#SELECT CONCAT('QUERY = ', @QUERY);  
		
	ELSEIF (p_MaintenanceType = 'Zoning')

	THEN 

		SET @QUERY = CONCAT('INSERT INTO tblzoning(`Cluster`, `Region`, `Area`, `CityMunicipal`, `ZoneName`, `SLA`)

		VALUES ', p_SQL);    			

		#SELECT CONCAT('QUERY = ', @QUERY);  
	ELSEIF (p_MaintenanceType = 'Location')

	THEN 

	    SET @QUERY = CONCAT('INSERT INTO tbllocation
		(`Code`, `Description`, `isReleased`, `isTerminalReleased`, `isSIMReleased`, `isDeploy`, `isReturn`)
		VALUES ', p_SQL);	
		
	    #SELECT CONCAT('QUERY = ', @QUERY);
					
	ELSEIF (p_MaintenanceType = 'Zoning Alias')

	THEN

		SET @QUERY = CONCAT(
		    'INSERT INTO tblzoningalias
		    (`AliasName`, `OfficialName`, `Priority`, `IsWholeWord`, `IsActive`)
		    VALUES ', p_SQL);    
		    
		#SELECT CONCAT('QUERY = ', @QUERY);   	      
								    
 END IF;          

 

# Execute Query 

PREPARE QUERY FROM @QUERY;

EXECUTE QUERY;

	

SET p_outErrorMessage = '';



# Set Last Insert ID

SELECT LAST_INSERT_ID() INTO v_LastID; 

SET p_outLastInsertID = IFNULL(v_LastID, 0);



END IF;



 



COMMIT;



END */$$
DELIMITER ;

/* Procedure structure for procedure `spInsertSelectCollectionDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spInsertSelectCollectionDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spInsertSelectCollectionDetail`(

    IN p_StatementType VARCHAR(50),

    IN p_SearchBy VARCHAR(50),

    IN p_SearchValue longtext,

    IN p_MaintenanceType VARCHAR(50)

)
BEGIN  



DECLARE v_ID INTEGER;

DECLARE v_DateTo VARCHAR(45);

DECLARE p_DateTo VARCHAR(45);

DECLARE v_ServiceNo INTEGER;

DECLARE v_TerminalID INTEGER;

DECLARE v_JobTypeDescription VARCHAR(45);

DECLARE v_JobTypeStatusDescription VARCHAR(45);

DECLARE v_TerminalIDList TEXT;



DECLARE p_INSERT longtext;

DECLARE p_WHERE LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_SQL LONGTEXT;



START TRANSACTION;



IF (p_StatementType = 'Insert') 

THEN  		

	IF (p_MaintenanceType = 'Valid FSR')

	THEN

		SET @QUERY =    'INSERT INTO tblfsrdetail(

				FSRID, 

				`No`, 

				Merchant, 

				`MID`, 

				TID, 

				TimeArrived, 

				InvoiceNo, 

				TimeStart, 

				BatchNo, 

				FSRStatus,

				FSRStatusDescription,

				Remarks,

				ServiceStatus,

				ServiceStatusDescription,

				FSR, 

				FSRDate, 

				FSRTime, 

				TxnAmt, 

				TimeEnd, 

				TerminalSN, 

				MerchantContactNo, 

				MerchantRepresentative, 

				FEName, 

				SerialNo, 

				ClientID, 

				ClientName,

				TAIDNo,

				IRNo,

				SIMSN,

				PowerSN,

				DockSN)

				SELECT 

				FSRID, 

				`No`, 

				Merchant, 

				`MID`, 

				TID, 

				TimeArrived, 

				InvoiceNo, 

				TimeStart, 

				BatchNo, 

				FSRStatus,

				FSRStatusDescription,

				Remarks,

				ServiceStatus,

				ServiceStatusDescription,

				FSR, 

				FSRDate, 

				FSRTime, 

				TxnAmt, 

				TimeEnd, 

				TerminalSN, 

				MerchantContactNo, 

				MerchantRepresentative, 

				FEName, 

				SerialNo, 

				ClientID, 

				ClientName,

				TAIDNo,

				IRNo,

				SIMSN,

				PowerSN,

				DockSN

				FROM tblfsrdetailtempdata

				WHERE FSRStatus = 1';

				

	ELSEIF (p_MaintenanceType = 'Invalid FSR')

	THEN

		SET @QUERY =    'INSERT INTO tblfsrdetail(

				FSRID, 

				`No`, 

				Merchant, 

				`MID`, 

				TID, 

				TimeArrived, 

				InvoiceNo, 

				TimeStart, 

				BatchNo, 

				FSRStatus,

				FSRStatusDescription,

				Remarks,

				ServiceStatus,

				ServiceStatusDescription,

				FSR, 

				FSRDate, 

				FSRTime, 

				TxnAmt, 

				TimeEnd, 

				TerminalSN, 

				MerchantContactNo, 

				MerchantRepresentative, 

				FEName, 

				SerialNo, 

				ClientID, 

				ClientName,

				TAIDNo,

				IRNo,

				SIMSN,

				PowerSN,

				DockSN)

				SELECT 

				FSRID, 

				`No`, 

				Merchant, 

				`MID`, 

				TID, 

				TimeArrived, 

				InvoiceNo, 

				TimeStart, 

				BatchNo, 

				FSRStatus,

				FSRStatusDescription,

				Remarks,

				ServiceStatus,

				ServiceStatusDescription,

				FSR, 

				FSRDate, 

				FSRTime, 

				TxnAmt, 

				TimeEnd, 

				TerminalSN, 

				MerchantContactNo, 

				MerchantRepresentative, 

				FEName, 

				SerialNo, 

				ClientID, 

				ClientName,

				TAIDNo,

				IRNo,

				SIMSN,

				PowerSN,

				DockSN

				FROM tblfsrdetailtempdata

				WHERE FSRStatus = 2';

	

	ELSEIF (p_MaintenanceType = 'ERM Dummy Filter Date')

	THEN	

		DELETE FROM tbldummy;

		

		SET @QUERY =    'INSERT INTO tbldummy(

				DateFrom)

				(SELECT FSRDate AS DateFrom FROM tblermdetailtemp ORDER BY FSRNo ASC LIMIT 1)';

		

				

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		# Update DateTo

		SELECT FSRDate INTO v_DateTo

		FROM 

		tblermdetailtemp

		ORDER BY 

		FSRNo DESC 

		LIMIT 1;

		

		SET p_DateTo = v_DateTo;

		

		SET @QUERY = CONCAT('UPDATE tbldummy SET DateTo=', "'", p_DateTo, "'", ' ', 'WHERE IDNo = 1');

		

		#SELECT (CONCAT("QUERY=", @QUERY));

		

	ELSEIF (p_MaintenanceType = 'FSR Dummy Filter Date')

	THEN

		SET @QUERY =    'INSERT INTO tbldummy(

				DateFrom)

				(SELECT `Date` AS DateFrom FROM tblfsrdetailtemp ORDER BY FSRNo ASC LIMIT 1)';

		

				

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		# Update DateTo

		SELECT `Date` INTO v_DateTo

		FROM 

		tblfsrdetailtemp

		ORDER BY 

		FSRNo DESC 

		LIMIT 1;

		

		SET p_DateTo = v_DateTo;

		

		SET @QUERY = CONCAT('UPDATE tbldummy SET DateTo=', "'", p_DateTo, "'", ' ', 'WHERE IDNo = 1');	

		

	ELSEIF (p_MaintenanceType = 'Servicing Detail Temp')

	THEN

		SET v_TerminalIDList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		

		SET p_WHERE = '';		

		IF (LENGTH(v_TerminalIDList) > 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalID IN ');

			SET p_WHERE = CONCAT(p_WHERE, "(", v_TerminalIDList, ")");

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;	

		

		IF (STRCMP(v_JobTypeDescription, "0") != 0 && STRCMP(v_JobTypeDescription, "[NOT SPECIFIED]") != 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'g.ServiceStatus IN ');

			SET p_WHERE = CONCAT(p_WHERE, "(", v_JobTypeDescription, ")");

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;



		IF (STRCMP(v_JobTypeStatusDescription, "0") != 0 && STRCMP(v_JobTypeStatusDescription, "[NOT SPECIFIED]") != 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobTypeStatusDescription IN ');

			SET p_WHERE = CONCAT(p_WHERE, "(", v_JobTypeStatusDescription, ")");

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;	

		

		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

		#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

		#SELECT CONCAT('p_WHERE = ', p_WHERE);

	    

		SET p_SQL = '';	

		SET p_SQL = CONCAT(p_SQL,'SELECT');

		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ServiceNo, 0) AS ServiceNo,	

						IFNULL(a.TAIDNo, 0) AS TAIDNo,

						IFNULL(a.IRIDNo, 0) AS IRIDNo,

						IFNULL(a.IRNo, "-") AS IRNo,

						IFNULL(b.TID, "-") AS TID,

						IFNULL(b.MID, "-") AS MID,

						IFNULL(a.TerminalID, "-") AS TerminalID,

						IFNULL(a.TerminalSN, "-") AS TerminalSN,

						IFNULL(a.TerminalSN, "-") AS TerminalSNTemp,

						IFNULL(c.TerminalStatusDescription, 0) AS TerminalStatusDescription,

						IFNULL(d.Description, "-") AS Type,

						IFNULL(e.Description, "-") AS Model,

						IFNULL(f.Description, "-") AS Brand

						FROM tblservicingdetail AS a

						LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

						LEFT JOIN tblterminaldetail AS c ON a.TerminalID = c.TerminalID

						LEFT JOIN tblterminaltype AS d ON c.TerminalTypeID = d.TerminalTypeID

						LEFT JOIN tblterminalmodel AS e ON c.TerminalModelID = e.TerminalModelID

						LEFT JOIN tblterminalbrand AS f ON c.TerminalBrandID = f.TerminalBrandID

						LEFT JOIN tblservicetype AS g ON a.JobTypeDescription = g.JobTypeDescription');	



		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('Before:p_SQL = ', p_SQL);

    

		IF (LENGTH(p_WHERE) > 0)

		THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

			SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

		END IF;



		SET p_SQL = REPLACE(p_SQL, '"', "'");

		

		#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

		

		# Update tblservicingdetaildummy (installation request details)

		CALL spCreateTemporaryTable('Create', 'Servicing Dummy Detail', '');

		

		SET p_INSERT = '';

		SET p_INSERT = 'INSERT INTO tblservicingdetailtemp (ServiceNo, TAIDNo, IRIDNo, IRNo, TID, `MID`, TerminalID, TerminalSN, TerminalSNTemp, TerminalStatusDescription, `Type`, Model, Brand)';



		SET @QUERY = '';	

		SET @QUERY = CONCAT(p_INSERT, p_SQL);

		

		#SELECT CONCAT('After:Len(@QUERY) = ', LENGTH(@QUERY));

		#SELECT CONCAT('After:@QUERY = ', @QUERY)

		

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		

		# Update tblservicingdetaildummy (installation request details)

		CALL spProcessIRList('Update', '', '');

		

		# Update tblservicingdetaildummy (servicing/fsr details)

		CALL spProcessServiceList('Update', '', '');

		

	ELSEIF (p_MaintenanceType = 'Import Terminal')

	THEN

		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		TRUNCATE TABLE tblterminaldetailrepo; # dummy terminal detail table for repository

		

		# Query in terminaldetail by TIID

		SET p_SQL = '';

		SET p_SQL = CONCAT("SELECT

					a.TIID,

					a.TerminalID,

					a.SerialNo,

					a.TerminalTypeID,

					a.TerminalModelID,

					a.TerminalBrandID,

					(SELECT xTable.Description FROM tblterminaltype xTable WHERE xTable.TerminalTypeID = a.TerminalTypeID) AS pType,

					(SELECT xTable.Description FROM tblterminalmodel xTable WHERE xTable.TerminalModelID = a.TerminalModelID) AS pModel,

					(SELECT xTable.Description FROM tblterminalbrand xTable WHERE xTable.TerminalBrandID = a.TerminalBrandID) AS pBrand,

					'0' AS TerminalStatus,

					'SUCCESS' AS TerminalStatusDescription

					FROM

					tblterminaldetail a

					WHERE a.TIID =", v_ID, ";");

		

		#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

					

		SET p_INSERT = '';

		SET p_INSERT = 'INSERT INTO tblterminaldetailrepo(TIID, TerminalID, SerialNo, TerminalTypeID, TerminalModelID, TerminalBrandID, Type, Model, Brand, TerminalStatus, TerminalStatusDescription)';



		SET @QUERY = '';	

		SET @QUERY = CONCAT(p_INSERT, p_SQL);

		

		#SELECT CONCAT('After:Len(@QUERY) = ', LENGTH(@QUERY));

		#SELECT CONCAT('After:@QUERY = ', @QUERY)

		

		# Execute Query

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;	

		

		# Query in tblduplicatedetail by TIID

		SET p_SQL = '';

		SET p_SQL = CONCAT("SELECT

				a.DupID,

				a.ControlNo,

				b.SerialNo,

				b.TerminalTypeID,

				b.TerminalModelID,

				b.TerminalBrandID,

				(SELECT xTable.Description FROM tblterminaltype xTable WHERE xTable.TerminalTypeID = b.TerminalTypeID) AS pType,

				(SELECT xTable.Description FROM tblterminalmodel xTable WHERE xTable.TerminalModelID = b.TerminalModelID) AS pModel,

				(SELECT xTable.Description FROM tblterminalbrand xTable WHERE xTable.TerminalBrandID = b.TerminalBrandID) AS pBrand,

				'1' AS TerminalStatus,

				'DUPLICATE' AS TerminalStatusDescription

				FROM

				tblduplicatedetail a

				LEFT JOIN tblterminaldetail b ON a.SerialNo = b.SerialNo

				WHERE a.DupID = ", v_ID, ";");

		

		#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

					

		SET p_INSERT = '';

		SET p_INSERT = 'INSERT INTO tblterminaldetailrepo(TIID, TerminalID, SerialNo, TerminalTypeID, TerminalModelID, TerminalBrandID, Type, Model, Brand, TerminalStatus, TerminalStatusDescription)';



		SET @QUERY = '';	

		SET @QUERY = CONCAT(p_INSERT, p_SQL);

		

		#SELECT CONCAT('After:Len(@QUERY) = ', LENGTH(@QUERY));

		#SELECT CONCAT('After:@QUERY = ', @QUERY)

		

	ELSEIF (p_MaintenanceType = 'Import SIM')

	THEN

		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		TRUNCATE TABLE tblsimdetailrepo; # dummy terminal detail table for repository

		

		# Query in simdetail by SIID

		SET p_SQL = '';

		SET p_SQL = CONCAT("SELECT

					a.SerialNo,

					a.Carrier,

					'0' AS SIMStatus,

					'SUCCESS' AS SIMStatusDescription

					FROM

					tblsimdetail a

					WHERE a.SIID = ", v_ID, ";");

		

		#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

					

		SET p_INSERT = '';

		SET p_INSERT = 'INSERT INTO tblsimdetailrepo(SerialNo, Carrier, SIMStatus, SIMStatusDescription)';



		SET @QUERY = '';	

		SET @QUERY = CONCAT(p_INSERT, p_SQL);

		

		#SELECT CONCAT('After:Len(@QUERY) = ', LENGTH(@QUERY));

		#SELECT CONCAT('After:@QUERY = ', @QUERY)

		

		# Execute Query

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;	

		

		# Query in tblduplicatedetail by SIID

		SET p_SQL = '';

		SET p_SQL = CONCAT("SELECT

				b.SerialNo,

				b.Carrier,		

				'1' AS SIMStatus,

				'DUPLICATE' AS SIMStatusDescription

				FROM

				tblduplicatedetail a

				LEFT JOIN tblsimdetail b ON a.SerialNo = b.SerialNo

				WHERE a.DupID = ", v_ID, ";");

		

		#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

					

		SET p_INSERT = '';

		SET p_INSERT = 'INSERT INTO tblsimdetailrepo(SerialNo, Carrier, SIMStatus, SIMStatusDescription)';



		SET @QUERY = '';	

		SET @QUERY = CONCAT(p_INSERT, p_SQL);

		

		#SELECT CONCAT('After:Len(@QUERY) = ', LENGTH(@QUERY));

		#SELECT CONCAT('After:@QUERY = ', @QUERY)	

				

	END IF;          



	# Execute Query

	PREPARE QUERY FROM @QUERY;

	EXECUTE QUERY;	



END IF; 



COMMIT; 

       

END */$$
DELIMITER ;

/* Procedure structure for procedure `spInsertSelectIRDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spInsertSelectIRDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spInsertSelectIRDetail`(

	IN p_StatementType VARCHAR(50),

    IN p_MaintenanceType VARCHAR(50),

    IN p_SearchBy VARCHAR(30) /* = NULL */ ,

    IN p_SearchValue VARCHAR(30))
BEGIN  

	

    DECLARE v_ID INTEGER;

  

START TRANSACTION;

    

IF (p_StatementType = 'Insert-Select')

THEN

	IF (p_MaintenanceType = 'IR Detail')

	THEN

			IF (p_SearchBy = 'IRID')

			THEN

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				

				/* DELETE */

				DELETE FROM tblirdetail WHERE (IRID = v_ID);

				

				INSERT INTO tblirdetail (IRID, IRDate, InstallationDate, IRNo, ParticularID, NAME, MerchantID, MerchantName, TID, MID)            

				SELECT      IRID, 

							DATE_REQUEST, 

			    INSTALLATION_DATE,

			    MCC_INSTALLATION_REQUEST_ID,

							(SELECT ParticularID FROM tblparticular WHERE NAME LIKE MERCHANT_DBA_NAME AND ParticularTypeID = 1),

			    (SELECT NAME FROM tblparticular WHERE NAME LIKE MERCHANT_DBA_NAME AND ParticularTypeID = 1),

			    (SELECT ParticularID FROM tblparticular WHERE NAME LIKE MERCHANT_DBA_NAME AND ParticularTypeID = 1),

			    (SELECT NAME FROM tblparticular WHERE NAME LIKE MERCHANT_DBA_NAME AND ParticularTypeID = 1),

			    PRIME_TID_01,

			    PRIME_MID_01

				FROM        tblinstallationrequestdetail

				WHERE       (IRID = v_ID);				

				

			 END IF;

	END IF;              

END IF;   

   

COMMIT;   

    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spIsCheckEquipment` */

/*!50003 DROP PROCEDURE IF EXISTS  `spIsCheckEquipment` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spIsCheckEquipment`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

    IN p_EquipmentID INTEGER /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */ ,

    OUT p_outCount INTEGER

)
BEGIN

	DECLARE v_Count INT;

    DECLARE v_ID INT;

    

	IF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'RequestID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   						

                        COUNT(*) INTO v_Count

			FROM        tblreqequipmentdetail

			WHERE       (EquipmentID = p_EquipmentID)

            AND         (RequestID = v_ID)

            LIMIT 1;

		 END IF;

         

	END IF;

    

    SET p_outCount = v_Count;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spIsCheckServiceType` */

/*!50003 DROP PROCEDURE IF EXISTS  `spIsCheckServiceType` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spIsCheckServiceType`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

    IN p_ServiceTypeID INTEGER /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */ ,

    OUT p_outCount INTEGER

)
BEGIN

	DECLARE v_Count INT;

    DECLARE v_ID INT;

    

	IF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'RequestID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   						

                        COUNT(*) INTO v_Count

			FROM        tblreqservicetypedetail

			WHERE       (ServiceTypeID = p_ServiceTypeID)

            AND         (RequestID = v_ID)

            LIMIT 1;

		 END IF;

         

	END IF;

    

    SET p_outCount = v_Count;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spKillSleepingConnections` */

/*!50003 DROP PROCEDURE IF EXISTS  `spKillSleepingConnections` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spKillSleepingConnections`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE conn_id INT;
    DECLARE conn_cursor CURSOR FOR
        SELECT ID FROM INFORMATION_SCHEMA.PROCESSLIST WHERE COMMAND = 'Sleep' AND USER != 'system user';
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN conn_cursor;

    read_loop: LOOP
        FETCH conn_cursor INTO conn_id;
        IF done THEN
            LEAVE read_loop;
        END IF;
        SET @kill_command = CONCAT('KILL ', conn_id);
        PREPARE stmt FROM @kill_command;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END LOOP;

    CLOSE conn_cursor;
END */$$
DELIMITER ;

/* Procedure structure for procedure `spMainActivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `spMainActivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spMainActivity`(
IN p_Statement VARCHAR(500),
IN p_SearchBy VARCHAR(500),
IN p_SearchVal VARCHAR(500))
BEGIN


	DECLARE Category VARCHAR(50);

	-- DEBUG
	#Select pStatement, pSearchBy, pSearchVal, pSql;

    CASE -- CATEGORY START BLOCK --

		-- SERVICING GROUP ---
      WHEN p_SearchBy IN (
      
				'SERVICE DETAILS',
				'SERVICE REQUEST',
				'TERMINAL PRICE LIST', 
				'TERMINAL DETAILS',
				'HELP-DESK'

		) THEN SET Category = "SERVICING";

		-- MERCHANT GROUP --
		WHEN p_SearchBy IN (
		
				'MERCHANT DETAILS'
				
		) THEN SET Category = "MERCHANT";

		-- MONITORING GROUP --			
		WHEN p_SearchBy IN (
		
					'SERVICES',
					'SERVICE SUMMARY',
					'SERVICE HISTORY',
					'TOTAL JOBS',
					'JOB INFO',
					'MONTHLY SALES',
					'WEEKLY SALES', 
					'DASHBOARD DAILY', 
					'DASHBOARD MONTHLY',
					'INSTALLATION RECORD',
					'DISPATCH STATUS',
					'TERMINAL STATUS',
					'SIM STATUS',
					'TOTAL INSTALLED',
					'TOTAL REQUEST'
		
		) THEN SET Category = "MONITORING";
					
		-- REPORTS GROUP --	
		WHEN p_SearchBy IN (
		
					'MCC NET MATRIX SUMMARY',
					'MCC NET MATRIX INVOICE'
		
		) THEN SET Category = "REPORTS";
            

    END CASE; -- CATEGORY END BLOCK --


    CASE p_Statement -- STATEMENT START BLOCK -- 

        WHEN "VIEW" THEN
            IF Category IS NOT NULL THEN
                CALL spMainView(Category, p_SearchBy, p_SearchVal);
            END IF;

        WHEN "UPDATE" THEN
            IF Category IS NOT NULL THEN
                CALL spMainUpdate(Category, p_SearchBy, p_SearchVal);
            END IF;

        WHEN "INSERT" THEN
            IF Category IS NOT NULL THEN
                CALL spMainInsert(Category, p_SearchBy, p_SearchVal);
            END IF;

        WHEN "DELETE" THEN
            IF Category IS NOT NULL THEN
                CALL spMainDelete(Category, p_SearchBy, p_SearchVal);
            END IF;

        -- HANDLE OTHER pStatement CASES --

    END CASE; -- STATEMENT END BLOCK -- 

    
	END */$$
DELIMITER ;

/* Procedure structure for procedure `spMainDelete` */

/*!50003 DROP PROCEDURE IF EXISTS  `spMainDelete` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spMainDelete`(

	 IN pStatement VARCHAR(50),

     IN pSearchBy VARCHAR(50),

     IN pSearchVal VARCHAR(50),

     IN pSql TEXT)
BEGIN

    

    CASE pStatement -- STATEMENT START BLOCK -- 

    

        WHEN "SERVICING" THEN -- USERS GROUP --

        

            CASE pSearchBy  -- SEARCHBY START BLOCK --

				

				WHEN 'SERVICING DETAILS' THEN

				

					SELECT HeaderName, `View`, `Add`, `Edit`, `Delete` FROM tbluserpermis WHERE UserID = pSearchVal AND HeaderName = pSql;

					

            END CASE; -- SEARCHBY END BLOCK	

            



        WHEN "GROUP 2" THEN -- GROUP 2 GROUP --

            

            CASE pSearchBy -- SEARCHBY START BLOCK --



                WHEN 'ITEM 1' THEN

                  

					SELECT UserID FROM tbluserprof;

                    

            END CASE; -- SEARCHBY END BLOCK

     

    END CASE; -- STATMENT END BLOCK  

      

	END */$$
DELIMITER ;

/* Procedure structure for procedure `spMainInsert` */

/*!50003 DROP PROCEDURE IF EXISTS  `spMainInsert` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spMainInsert`(

     IN pStatement VARCHAR(50),

     IN pSearchBy VARCHAR(50),

     IN pSearchVal VARCHAR(50),

     IN pSql TEXT )
BEGIN

    

    CASE pStatement -- STATEMENT START BLOCK -- 

    

        WHEN "SERVICING" THEN -- USERS GROUP --

        

            CASE pSearchBy  -- SEARCHBY START BLOCK --

				

				WHEN 'SERVICING DETAILS' THEN

				

					SELECT HeaderName, `View`, `Add`, `Edit`, `Delete` FROM tbluserpermis WHERE UserID = pSearchVal AND HeaderName = pSql;



            END CASE; -- SEARCHBY END BLOCK	

            



        WHEN "GROUP 2" THEN -- GROUP 2 GROUP --

            

            CASE pSearchBy -- SEARCHBY START BLOCK --



                WHEN 'ITEM 1' THEN

                  

					SELECT UserID FROM tbluserprof;

                  

            END CASE; -- SEARCHBY END BLOCK

     

    END CASE; -- STATMENT END BLOCK  

    

	END */$$
DELIMITER ;

/* Procedure structure for procedure `spMainView` */

/*!50003 DROP PROCEDURE IF EXISTS  `spMainView` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spMainView`(
 IN p_Statement VARCHAR(50),
 IN p_SearchBy VARCHAR(50),
 IN p_SearchVal VARCHAR(200))
BEGIN

	DECLARE Category VARCHAR(500);
	DECLARE Search VARCHAR(500);
	DECLARE Others VARCHAR(500);
	DECLARE Flag VARCHAR(500);
	
	#JSON Validation
	IF JSON_VALID(p_SearchVal) THEN
        SET Category = fnJsonExtract(p_SearchVal, '$.Category');
        set Search 	= fnJsonExtract(p_SearchVal, '$.Search');
        set Others 	= fnJsonExtract(p_SearchVal, '$.Others');
   end if;

	#Select Category, Search, Others;

   CASE p_Statement -- STATEMENT START BLOCK -- 

		WHEN "MONITORING" THEN -- SERVICING GROUP --

			CASE p_SearchBy  -- SEARCHBY START BLOCK --

				WHEN 'SERVICES' THEN

					SELECT 
						 Job_ID AS `Job No.`,
						 Request_No as `Req No.`,
						 DATE_FORMAT(Request_Date,  '%b %d, %Y') AS `Req Date`,
						 DATE_FORMAT(Target_Date,  '%b %d, %Y') AS `Target Date`,
						 REPLACE(Request, 'FOR ', '') AS Service,
						 Merchant_Name AS `Merchant`,
						 CASE 
							 WHEN Prov_ID = 5 THEN 'PROVINCE' 
							 WHEN Prov_ID = 4 THEN 'MANILA' 
							 ELSE Province 
						 END AS Region,
						 Terminal_SN AS `Terminal`,
						 Sim_SN AS `Sim`,
						 Days,
						 TAT_Status as `TAT`,
						 Dispatch_By AS `Dispatch By`,
						 IF(STR_TO_DATE(Dispatch_Date_Time, '%Y-%m-%d') IS NOT NULL, DATE_FORMAT(Dispatch_Date_Time, '%h:%i %p, %b %d, %Y'), Dispatch_Date_Time) AS `Dispatch Date`,
						 Service_Status AS `Status`,
						 Service_Result as `Result`,
						 IF(STR_TO_DATE(Service_Date, '%Y-%m-%d') IS NOT NULL, DATE_FORMAT(Service_Date, '%b %d, %Y'), Service_Date) AS `Serviced Date`
					FROM 
						 vw_service_info
					WHERE			 
					
						 (Category = 'All Request' AND -- Multi Search
						 (Type_ID = Search
						 AND
						 (        -- Handle when `Others` is null or empty
						  (Others IS NULL OR Others = '') 
						  OR 
						  -- Filter based on `Others` value
						  (
								Terminal_SN = Others
								OR Sim_SN = Others
								OR TID = Others
								OR Job_ID = Others
								OR Dispatch_By = Others
								OR Service_Result = Others
								or Merchant_Name LIKE CONCAT('%', Others, '%') 
						  ))))
					or
						 (Terminal_SN = p_SearchVal
						 OR Sim_SN = p_SearchVal
						 OR TID = p_SearchVal
						 OR Job_ID = p_SearchVal
						 OR Service_Result = p_SearchVal
						 OR Request_No = p_SearchVal
						 or Merchant_Name LIKE CONCAT('%', p_SearchVal, '%')
						 OR Dispatch_By LIKE CONCAT('%', p_SearchVal, '%')) -- Normal Search

					ORDER BY Processed_Date_Time DESC
					LIMIT 1500;
					
					
				WHEN 'INSTALLATION RECORD' THEN
				
					set Search = TRIM(SPLIT_STRING(p_SearchVal, '|' ,1));
					set Others = TRIM(SPLIT_STRING(p_SearchVal, '|', 2));
					
					#Select Search, Others;
					
					SELECT
						 DATE_FORMAT(Created_Date, '%b %d, %Y') as `Date Created`,
						 Request_No AS `Req No.`,
						 Merchant,
						 TID,
						 MID,
						 Model_Name AS Model,
						 Terminal_SN AS Terminal,
						 Carrier,
						 Sim_SN AS Sim,
						 `Status`,
						 `Client`
					FROM 
						 vw_installation_info
					WHERE 
							 -- CASE 1
						 (   Others = ''
							  AND ( Merchant LIKE CONCAT('%', Search, '%')
										OR `Status` 	= Search
										OR Terminal_SN = Search
										OR Sim_SN 		= Search
										OR TID			= Search
										OR Client_ID 	= Search)
						 )
						 OR -- CASE 2
						 (	  Others != ''
							  AND ( `Status`  		 = Search 
										OR Terminal_Loc = Search 
										OR Client_ID 	 = Search)
							  AND ( Merchant LIKE CONCAT('%', Others, '%')
										or Terminal_SN  = Others
										OR TID 		 	 = Others
										OR Sim_SN 	 	 = Others
										OR `Status` 	 = Others)
						 );

				
				when 'DISPATCH STATUS' THEN
				
					SELECT
						 REPLACE(Request, 'FOR ', '') AS Service,
						 Dispatch_By AS Dispatcher,
						 SUM(CASE WHEN Status_ID = 8 OR Dispatcher_ID = null THEN 1 ELSE 0 END) AS Pending,
						 SUM(CASE WHEN Status_ID = 7 AND Service_Result = 'COMPLETED' THEN 1 ELSE 0 END) AS Completed
					FROM 
						 vw_service_info
					GROUP BY 
						 Dispatcher_ID, Type_ID, Request
					HAVING Pending <> 0 AND Completed <> 0
					ORDER BY Dispatch_By;
					
				WHEN 'TERMINAL STATUS' THEN
																				
					#SET Flag   = TRIM(SPLIT_STRING(p_SearchVal, '|', 1));															
					SET Search = TRIM(SPLIT_STRING(p_SearchVal, '|' ,1));
					SET Others = TRIM(SPLIT_STRING(p_SearchVal, '|', 2));
				
					#Select Flag, Search, Others;
					
					SELECT 
						Terminal_ID AS ID, 
						Model,
						Terminal_SN AS `Serial`,
						App_Version as `App Version`,
						App_Crc as `App Crc`, 
						Location,
						`Status`,
						Client_Name as `Client`
					FROM 
						vw_terminal_info
					Where
						  -- CASE 0
						 (   LENGTH(Others) = 0
							  AND (  -- Values
										(LENGTH(Search)   = 0) OR
										(`Status` 			= Search	
											OR Terminal_SN = Search
											OR Model 		= Search
											OR Location		= Search)
									)
						 )
						 
						 OR -- CASE 1
						 (	  LENGTH(Search) != 0
							  AND ( 	-- Header
											`Status`   		= Search
											OR Location    = Search
											OR Client_ID   = Search
									)	
										
							  AND ( -- Values
									  (LENGTH(Others)  = 0) OR 
									  ( Terminal_SN 	 = Others
											OR Model 	 = Others)
									)
						 );
																
				WHEN 'SIM STATUS' THEN

					SET Search = TRIM(SPLIT_STRING(p_SearchVal, '|' ,1));
					SET Others  = TRIM(SPLIT_STRING(p_SearchVal, '|', 2));
					
					#Select Search, Others;
						
					SELECT 
						Sim_ID AS ID,
						Carrier, 
						Sim_SN AS `Serial`, 
						Location,
						`Status`,
						Client_Name AS `Client`
					FROM 
						vw_sim_info
					WHERE

						 -- CASE 0
						 (   LENGTH(Others) = 0
							  AND (  -- Values
										(LENGTH(Search)   = 0) OR
										(`Status` 			= Search	
											OR Sim_SN = Search
											OR Carrier 		= Search
											OR Location		= Search
											OR Client_ID 	= Search)
									)
						 )
						 OR -- CASE 1
						 (	  LENGTH(Search) != 0
							  AND ( 	-- Header
											`Status`   		= Search
											OR Location    = Search
											OR Client_ID   = Search
									)	
										
							  AND ( -- Values
									  (LENGTH(Others)  = 0) OR 
									  (	Sim_SN 	 	 = Others
											OR Carrier 	 = Others)
									)
						 );
					
				when 'TOTAL JOBS' THEN

					SELECT
						 Coalesce(SUM(IF(Type_ID = 1, 1, 0)), 0) AS Installation,
						 Coalesce(SUM(IF(Type_ID = 3, 1, 0)), 0) AS Reprogramming,
						 Coalesce(SUM(IF(Type_ID = 6, 1, 0)), 0) AS Servicing,
						 Coalesce(SUM(IF(Type_ID = 7, 1, 0)), 0) AS Replacement,
						 Coalesce(SUM(IF(Type_ID = 4, 1, 0)), 0) AS PullOut,
						 COUNT(*) AS Total
					FROM
						 vw_service_info
					where
						 created_Date = CURRENT_DATE();
						 
				when 'TOTAL INSTALLED' THEN
				
					SET Search = TRIM(SPLIT_STRING(p_SearchVal, '|' ,1));
					SET Others  = TRIM(SPLIT_STRING(p_SearchVal, '|', 2));

					#Select Search, Others;
					
					SELECT 	
						 ir.IRNo AS `Request No`,
						 ir.MerchantName AS Merchant,
						 pt.Region as City,
						 ir.TID,
						 ir.MID,
						 td.Model,
						 tm.AppVersion AS `App Version`,
						 tm.AppCrc AS `App Crc`,
						 td.TerminalSN AS `Terminal Serial`,
						 si.Sim_SN AS `Sim Serial`,
						 td.ClientName AS `Client`
					FROM
						 tblterminaldetail td
					LEFT JOIN
						 tblirdetail ir ON ir.TerminalID = td.TerminalID
					LEFT JOIN
						 tblterminalmodel tm ON tm.TerminalModelID = td.TerminalModelID
					LEFT JOIN
						 vw_sim_info si ON si.Sim_ID = ir.SIMID
					LEFT JOIN
						 tblparticular pt ON pt.ParticularID = ir.MerchantID
					WHERE
						 td.TerminalStatus = 7 -- Default
						 AND (
								 ( LENGTH(Others) = 0
									AND ( ir.MerchantName LIKE CONCAT('%', Search, '%')
										OR td.TerminalSN 	 = Search
										OR si.Sim_SN 		 = Search
										OR ir.TID 			 = Search
										OR td.ClientID		 = Search
										or td.ClientName	 = Search )
								 )
								 or 
								 ( LENGTH(Others) != 0
									and td.ClientID = Search
									and ( ir.MerchantName LIKE CONCAT('%', Others, '%')
											OR td.TerminalSN 	 = Others
											OR si.Sim_SN 		 = Others
											OR ir.TID 			 = Others )
								 )
 							  );

				when 'TOTAL REQUEST' THEN
				
					SELECT 
						 Request_No as `Req No.`,
						 Merchant,
						 TID,
						 `Client`
					FROM vw_installation_info
					WHERE		
						Status_ID = 1
						AND (  Merchant LIKE CONCAT('%', p_SearchVal, '%')
								 or Created_Date = p_SearchVal
								 or TID 			  = p_SearchVal
								 or Request_No   = p_SearchVal );
				
				when 'SERVICE SUMMARY' then

					SELECT
						 REPLACE(Request, 'FOR ', '') AS Description,
						 FORMAT(SUM(CASE WHEN Status_ID IN (7, 11) AND Service_Result = 'COMPLETED' THEN 1 ELSE 0 END), 0) AS Completed,
						 FORMAT(SUM(CASE WHEN Status_ID = 8 THEN 1 ELSE 0 END), 0) AS Dispatch,
						 FORMAT(SUM(CASE WHEN Status_ID = 2 THEN 1 ELSE 0 END), 0) AS Pending,
						 FORMAT(SUM(CASE WHEN Status_ID = 9 THEN 1 ELSE 0 END), 0) AS Negative,
						 FORMAT(SUM(CASE WHEN Prov_ID = 4 THEN 1 ELSE 0 END), 0) AS Manila,
						 FORMAT(SUM(CASE WHEN Prov_ID = 5 THEN 1 ELSE 0 END), 0) AS Province,
						 FORMAT(COUNT(*), 0) AS Total
					FROM
						 vw_service_info
					GROUP BY
						 Type_ID;


				WHEN 'SERVICE HISTORY' THEN
						
					SELECT 
						 REPLACE(Request, 'FOR ', '') AS Request,
						 Merchant_Name AS `Merchant Name`,
						 Terminal_SN AS `Terminal Serial`,
						 Sim_SN AS `Sim Serial`,
						 `MID`,
						 TID,
						 IF(STR_TO_DATE(Service_Date, '%Y-%m-%d') IS NOT NULL, DATE_FORMAT(Service_Date, '%M %d, %Y'), Service_Date) AS `Serviced Date`
					FROM
						 vw_service_info
					WHERE
						 Terminal_SN = p_SearchVal
						 OR Sim_SN = p_SearchVal
						 OR Merchant_ID = p_SearchVal;


				WHEN 'JOB INFO' THEN

					select 
						Job_ID,
						Merchant_ID,
						Request,
						Request_Status, 
						Merchant_Name, 
						Terminal_SN, 
						Sim_SN, 
						TID, 
						MID, 
						Model_Name as `Model`, 
						Request_No, 
						Processed_By, 
						DATE_FORMAT(Processed_Date_Time, '%h:%i %p, %M %e, %Y') as Processed_Date_Time,
						Client_Name, 
						FE_Name
					from vw_service_info
					Where Job_ID = p_SearchVal; 

				When 'MONTHLY SALES' then
				
					SELECT 
						 MONTHNAME(Service_Date) AS `Monthly`, 
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID = 1 AND Bill_ID = 1, Charge, 0)), 0)) AS `Installations`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID = 7  AND Bill_ID = 1, Charge, 0)), 0)) AS `Replacements`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (1, 3) AND Bill_ID = 1, Charge, 0)), 0)) AS `Install/Reprog`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4) AND Bill_ID = 1, Charge, 0)), 0)) AS `Maintenance/PullOut`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4, 1, 3, 7) AND Bill_ID = 1, Charge + Price, 0)), 0)) AS `Billable Sales`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4, 1, 3, 7) AND Bill_ID = 0, Charge + Price, 0)), 0)) AS `Non-Billable Sales`
					FROM
						 vw_service_info
					WHERE
						 YEAR(Service_Date) = YEAR(CURRENT_DATE())
						 AND Status_ID IN (7, 11)
						 AND Service_Result = 'SUCCESS'
						 AND Request_Status = 'COMPLETED'

					GROUP BY
						 MONTHNAME(Service_Date)
					ORDER BY
						 MONTH(Service_Date);

				 When 'WEEKLY SALES' then
				 
					SELECT  
						 MONTHNAME(Service_Date) AS `Month`,
						 CONCAT('Week ', WEEK(Service_Date)) AS `Weekly`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID = 1 AND Bill_ID = 1, Charge, 0)), 0)) AS `Installations`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID = 7  AND Bill_ID = 1, Charge, 0)), 0)) AS `Replacements`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (1, 3) AND Bill_ID = 1, Charge, 0)), 0)) AS `Install/Reprog`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4) AND Bill_ID = 1, Charge, 0)), 0)) AS `Maintenance/PullOut`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4, 1, 3, 7) AND Bill_ID = 1, Charge + Price, 0)), 0)) AS `Billable Sales`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4, 1, 3, 7) AND Bill_ID = 0, Charge + Price, 0)), 0)) AS `Non-Billable Sales`
					FROM 
						 vw_service_info
					WHERE 
						 YEAR(Service_Date) = YEAR(CURDATE())
						 AND Status_ID IN (7, 11)
						 AND Service_Result = 'SUCCESS'
						 AND Request_Status = 'COMPLETED'
					GROUP BY 
						 YEAR(Service_Date), WEEK(Service_Date)
					ORDER BY 
						 YEAR(Service_Date), WEEK(Service_Date);
						 
				 WHEN 'DAILY SALES' THEN
				 
					SELECT  
						 MONTHNAME(Service_Date) AS `Month`,
						 CONCAT('Day ', DAY(Service_Date)) AS `Daily`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID = 1 AND Bill_ID = 1, Charge, 0)), 0)) AS `Installations`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID = 7 AND Bill_ID = 1, Charge, 0)), 0)) AS `Replacements`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (1, 3) AND Bill_ID = 1, Charge, 0)), 0)) AS `Install/Reprog`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4) AND Bill_ID = 1, Charge, 0)), 0)) AS `Maintenance/PullOut`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4, 1, 3, 7) AND Bill_ID = 1, Charge + Price, 0)), 0)) AS `Billable Sales`,
						 CONCAT('₱', FORMAT(SUM(IF(Type_ID IN (6, 4, 1, 3, 7) AND Bill_ID = 0, Charge + Price, 0)), 0)) AS `Non-Billable Sales`
					FROM 
						 vw_service_info
					WHERE 
						 YEAR(Service_Date) = YEAR(CURDATE())
						 AND Status_ID IN (7, 11)
						 AND Service_Result = 'SUCCESS'
						 AND Request_Status = 'COMPLETED'
					GROUP BY 
						 Service_Date
					ORDER BY 
						 Service_Date;
    
				 WHEN 'DASHBOARD DAILY' THEN
				 
					SELECT 
						 REPLACE(Request, 'FOR ', '') AS `Request`,
						 SUM(CASE WHEN Prov_ID = 4 THEN 1 ELSE 0 END) AS MM,
						 SUM(CASE WHEN Prov_ID = 5 THEN 1 ELSE 0 END) AS PRO,
						 
						 SUM(CASE WHEN Status_ID IN (7, 11) -- INSTALLED/PULLED-OUT
									 AND Service_Result = 'COMPLETED'
									 THEN 1 ELSE 0 END) AS Completed,
									 
						 SUM(CASE WHEN Status_ID = 2 -- 'ALLOCATED'
									 THEN 1 ELSE 0 END) AS Pending,
									 
						 SUM(CASE WHEN Status_ID = 8 -- 'DISPATCH' 
									 THEN 1 ELSE 0 END) AS Dispatch,
									 
						 SUM(CASE WHEN Status_ID = 9 -- 'NEGATIVE'
									 THEN 1 ELSE 0 END) AS Negative,
									 
						 COUNT(*) AS `Total`
					FROM
						 vw_service_info
					WHERE 
						 Created_Date = CURRENT_DATE()
					GROUP BY
						 Type_ID;
				 
				 WHEN 'DASHBOARD MONTHLY' THEN	
				 
					SELECT 
						 REPLACE(Request, 'FOR ', '') AS `Request`,
						 SUM(CASE WHEN Prov_ID = 4 THEN 1 ELSE 0 END) AS MM,
						 SUM(CASE WHEN Prov_ID = 5 THEN 1 ELSE 0 END) AS PRO,
						 
						 SUM(CASE WHEN Status_ID IN (7, 11) 
									 AND Service_Result = 'COMPLETED'
									 THEN 1 ELSE 0 END) AS Completed,
									 
						 SUM(CASE WHEN Status_ID = 2 -- 'ALLOCATED' 
									 THEN 1 ELSE 0 END) AS Pending,
									 
						 SUM(CASE WHEN Status_ID = 8 -- 'DISPATCH' 
									 THEN 1 ELSE 0 END) AS Dispatch,
									 
						 SUM(CASE WHEN Status_ID = 9 -- 'NEGATIVE' 
									 THEN 1 ELSE 0 END) AS Negative,
									 
						 COUNT(*) AS `Total`
					FROM
						 vw_service_info
					WHERE
						 YEAR(Created_Date) = YEAR(CURRENT_DATE()) 
						 AND MONTH(Created_Date) = MONTH(CURRENT_DATE())
					GROUP BY
						 Type_ID;
					
			END CASE; -- SEARCHBY END BLOCK	

            
		WHEN "SERVICING" THEN -- SERVICING GROUP --

         CASE p_SearchBy  -- SEARCHBY START BLOCK --

				WHEN 'TERMINAL PRICE LIST' THEN

					SELECT
						tp.Price_ID AS `ID`,
						tm.Description AS `Description`,
						COALESCE(tp.Base_Price, 0) AS `Price`,
						COALESCE(tp.Rent_Price, 0) AS `Rental`,
						DATE_FORMAT(tp.Start_Date, '%b %d, %Y') AS `Start Date`,
						DATE_FORMAT(tp.End_Date, '%b %d, %Y') AS `End Date`,
						mi.Merchant_Name AS `Client`
					FROM tblterminalmodel tm
					LEFT JOIN tblterminalpricing tp ON tp.Model_ID = tm.TerminalModelID
					LEFT JOIN vw_merchant_info mi ON mi.Merchant_ID = tp.Client_ID
					ORDER BY ID;

				when 'TERMINAL DETAILS' THEN
				
					Select
					 TerminalModelID as Model_ID,
					 Description
					From tblterminalmodel;
					
			   WHEN 'HELP-DESK' THEN
				
					SELECT * FROM tblhddetail;
				
         END CASE; -- SEARCHBY END BLOCK	

            
		WHEN "REPORTS" THEN -- MERCHANT GROUP --

         CASE p_SearchBy -- SEARCHBY START BLOCK --

                WHEN 'MCC NET MATRIX SUMMARY' THEN
																
					 SELECT
					 TerminalModelID AS Model_ID,
					 Description
					 FROM tblterminalmodel;

         END CASE; -- SEARCHBY END BLOCK


	END CASE; -- STATMENT END BLOCK  

        

	END */$$
DELIMITER ;

/* Procedure structure for procedure `spMainViewX` */

/*!50003 DROP PROCEDURE IF EXISTS  `spMainViewX` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spMainViewX`(

 IN p_Statement VARCHAR(50),

 IN p_SearchBy  VARCHAR(50),

 IN p_SearchValue VARCHAR(300))
BEGIN

	

	DECLARE v_ID INTEGER;

	DECLARE Category VARCHAR(100);

	

	#SET Category = JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Category'));

	

	CASE p_Statement -- STATEMENT START BLOCK -- 



	WHEN "SERVICING" THEN -- SERVICING GROUP --



		CASE p_SearchBy  -- SEARCHBY START BLOCK --



		WHEN 'JOB DETAILS' THEN

			SET @From   	 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @To 	 		 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @Records 	 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SET @Query = CONCAT('SELECT svc.ServiceNo,
				 svc.IRNo AS `Request ID`,
				 td.Brand AS `Vendor`,
				 DATE_FORMAT(ir.IRDate, ''%m-%d-%Y'') AS `Request Date`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Requestor"'')) AS `Requestor`,
				 svc.JobTypeSubDescription AS `Request Type`,
				 ir.REQUEST_FOR AS `Request Prio`,
				 ir.SET_UP AS `POS Setup`,
				 ir.POS_TYPE AS `POS Type`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."POS Connection Type"'')) AS `POS Connection-Type`,
				 DATE_FORMAT(svc.ReqInstallationDate, ''%m-%d-%Y'') AS `Target Installation Date`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Pullout date _(applicable only to exhibit POS _ Request type)"'')) AS `Pullout Date`,
				 svc.RMInstruction AS `RM Instruction/Remarks`,
				 ir.MID AS `Merchant MID`,
				 ir.TID AS `Merchant TID`,
				 svc.MerchantName AS `Merchant`,
				 pt.Address,
				 pt.Region AS `City`,
				 pt.Province AS `Area 1 (MM/PROV)`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Area 2 (Region/Zone/Area code)"'')) AS `Area 2`,
				 svc.CustomerName AS `Contact Person`,
				 svc.CustomerContactNo AS `Contact Number`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Bancnet TID"'')) AS `Bancnet TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Bancnet MID"'')) AS `Bancnet MID`,
				 ir.ALIPAY_TID AS `Alipay TID`,
				 ir.ALIPAY_MID AS `Alipay MID`,
				 ir.WECHAT_TID AS `Wechat TID`,
				 ir.WECHAT_MID AS `Wechat MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-Gcash (TID)"'')) AS `QR-Gcash TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-Gcash (mid)"'')) AS `QR-Gcash MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-Grab (TID)"'')) AS `QR-Grab TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-Grab (MID)"'')) AS `QR-Grab MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-UPI (TID)"'')) AS `QR-UPI TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-UPI (MID)"'')) AS `QR-UPI MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-P2M (TID)"'')) AS `QR-P2M TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."QR-P2M (MID)"'')) AS `QR-P2M MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 1 - Name"'')) AS `Multi Merchant 1 - Name`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 1 - TID"'')) AS `Multi Merchant 1 - TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 1 - MID"'')) AS `Multi Merchant 1 - MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 2 - Name"'')) AS `Multi Merchant 2 - Name`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 2 - TID"'')) AS `Multi Merchant 2 - TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 2 - MID"'')) AS `Multi Merchant 2 - MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 3 - Name"'')) AS `Multi Merchant 3 - Name`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 3 - TID"'')) AS `Multi Merchant 3 - TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 3 - MID"'')) AS `Multi Merchant 3 - MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 4 - Name"'')) AS `Multi Merchant 4 - Name`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 4 - TID"'')) AS `Multi Merchant 4 - TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 4 - MID"'')) AS `Multi Merchant 4 - MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 5 - Name"'')) AS `Multi Merchant 5 - Name`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 5 - TID"'')) AS `Multi Merchant 5 - TID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$.Values."Multi-merchant 5 - MID"'')) AS `Multi Merchant 5 - MID`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."DCC (Yes/No)"'')) AS `Dcc`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."Installment (Yes/No)"'')) AS `Installment`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."Manual Key Entry (MKE) (Yes/No)"'')) AS `Manual Key Entry`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."Preauth (Yes/No)"'')) AS `Preauth`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."Offline Sale (Yes/No)"'')) AS `Offline Sale`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$."Offline Sale Limit (To be specified)"'')) AS `Offline Sale Limit`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."Tip Adjust (Yes/No)"'')) AS `Tip Adjust`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, ''$."Tip Adjust Limit (To be specified)"'')) AS `Tip Adjust Limit`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."Add-on Device  (To be specified)"'')) AS `Add-On Device`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."ECR Integration (Yes/No)"'')) AS `Ecr Integration`,
				 JSON_UNQUOTE(JSON_EXTRACT(ir.profile_info, ''$."ECR Cable Type"'')) AS `ECR Cable`,
				 COALESCE(curr.Terminal_SN, svc.TerminalSN) AS `POS Serial Number`,
				 td.Model AS `POS Model`,
				 ir.POS_TYPE AS `POS Type2`,
				 tmd.AppVersion AS `POS Version`,
				 tmd.AppCRC AS `POS Crc`,
				 sd.Carrier AS `Telco`,
				 COALESCE(curr.Sim_SN, svc.SIMSerialNo) AS `SIM Serial`,
				 ir.PrimaryNum AS `Primary Dialing`,
				 ir.SecondaryNum AS `Secondary Dialing`,
				 DATE_FORMAT(fsr.FSRDate, ''%m-%d-%Y'') AS `Original Install/Reprog Date`,
				 tmd.Price AS `TerminalCost`
			FROM tblservicingdetail AS svc
			LEFT JOIN tblterminaldetail AS td ON svc.TerminalSN = td.TerminalSN
			LEFT JOIN tblirdetail AS ir ON ir.IRIDNo = svc.IRIDNo
			LEFT JOIN (SELECT FSRDate, ServiceNo, ActionMade FROM tblfsrdetail) AS fsr ON fsr.ServiceNo = svc.ServiceNo
			LEFT JOIN (SELECT ParticularID, Address, Region, Province, RegionType FROM tblparticular) AS pt ON pt.ParticularID = svc.MerchantID
			LEFT JOIN tblregion AS rg ON rg.RegionID = pt.RegionType
			LEFT JOIN tblterminalmodel AS tmd ON tmd.TerminalModelID = td.TerminalModelID
			LEFT JOIN tblsimdetail AS sd ON sd.SIMID = svc.SIMID
			LEFT JOIN (
				 SELECT Request_ID, Terminal_SN, Sim_SN FROM vw_monitoring_jobs
				 WHERE Request = "FOR REPLACEMENT"
				 AND Request_Status = "COMPLETED"
				 AND Service_Status = "INSTALLED"
				 AND Service_Result = "SUCCESS"
				 AND Service_Date BETWEEN "', @From, '" AND "', @To, '"
			) AS curr ON curr.Request_ID = svc.IRIDNo
			WHERE svc.JobType = "1"  -- INSTALLATION
			AND svc.ClientID = "21" -- METROBANK
			AND svc.isBillable = "1"  -- BILLABLE
			AND svc.JobTypeStatusDescription = "COMPLETED"
			AND svc.ServiceStatusDescription = "INSTALLED"
			AND fsr.ActionMade = "SUCCESS"
			AND fsr.FSRDate BETWEEN "', @From, '" AND "', @To, '"
			AND NOT EXISTS (
				 -- Check Record of Pull Out in Views
				 SELECT 1
				 FROM vw_monitoring_jobs
				 WHERE Request = "FOR PULL-OUT"
				 AND Request_Status = "COMPLETED"
				 AND Service_Status = "PULLED-OUT"
				 AND Service_Result = "SUCCESS"
				 AND Service_Date BETWEEN "', @From, '" AND "', @To, '"
				 AND MONTH(Service_Date) <> MONTH("', @To, '")
				 AND Request_ID = svc.IRIDNo
			)');

			IF @Records IS NOT NULL AND LENGTH(@Records) > 0 THEN
				 SET @Query = CONCAT(@Query, ' AND svc.ServiceNo NOT IN (', @Records, ')');
			END IF;

			PREPARE stmt FROM @Query;
			EXECUTE stmt;
			DEALLOCATE PREPARE stmt;

		END CASE; -- SEARCHBY END BLOCK --



	END CASE;-- STATMENT END BLOCK  

			  

	END */$$
DELIMITER ;

/* Procedure structure for procedure `spMerchantInsertUpdate` */

/*!50003 DROP PROCEDURE IF EXISTS  `spMerchantInsertUpdate` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spMerchantInsertUpdate`(  

p_MerchantID INTEGER,  

p_Name VARCHAR(100),

p_Address VARCHAR(100),

p_CityID INTEGER,

p_City VARCHAR(100),

p_ProvinceID INTEGER,

p_ProvinceName VARCHAR(100),

p_ContactPerson VARCHAR(100),

p_ContactNo VARCHAR(100),

p_StatementType NVARCHAR(20) /* = NULL */

)
BEGIN  

 

 IF p_StatementType = 'Update'  

	THEN      

		UPDATE tblmerchant SET  

					   MerchantID = p_MerchantID, 

                       NAME = p_Name, 

                       Address = p_Address, 

                       CityID = p_CityID,

                       City = p_City,

                       ProvinceID = p_ProvinceID,

                       ProvinceName = p_ProvinceName,

                       ContactPerson = p_ContactPerson, 

                       ContactNo = p_ContactNo                       

		WHERE MerchantID = p_MerchantID;  

	END IF;  

END */$$
DELIMITER ;

