/* Procedure structure for procedure `spProcessERMDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spProcessERMDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spProcessERMDetail`(

    IN p_StatementType VARCHAR(50),

    IN p_SearchBy VARCHAR(50),

    IN p_SearchValue VARCHAR(50),

    IN p_MaintenanceType VARCHAR(50)

)
BEGIN  

DECLARE v_ID INTEGER;

DECLARE v_ParticularID INTEGER;

DECLARE v_ParticularName VARCHAR(45);

DECLARE p_WHERE LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

    

#SELECT CONCAT('p_StatementType = ', p_StatementType) AS p_StatementType;

#SELECT CONCAT('p_SearchBy = ', p_SearchBy) AS p_SearchBy;

#SELECT CONCAT('p_SearchValue = ', p_SearchValue) AS p_SearchValue;

#SELECT CONCAT('p_MaintenanceType = ', p_MaintenanceType) AS p_MaintenanceType;

        

IF (p_StatementType = 'Process') 

THEN  	

	#SELECT CONCAT("pasok1");

	IF (p_MaintenanceType = 'ERM Temp Detail')

	THEN    	

		#SELECT CONCAT("pasok2");

		CALL spDeleteCollectionDetail('Delete', '', '', 'Dummy Filter Date');

			

		#SELECT CONCAT("pasok3");	

		CALL spInsertSelectCollectionDetail('Insert', '', '', 'ERM Dummy Filter Date');

		

		#SELECT CONCAT("pasok4");

		CALL spDeleteCollectionDetail('Delete', '', '', 'ERM Temp Detail CleanUp');

		

		# Retain record for specific client

		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ParticularName = SPLIT_STRING(p_SearchValue, '|' ,2);

		

		#SELECT CONCAT('v_ParticularID = ', v_ParticularID) AS v_ParticularID;

		#SELECT CONCAT('v_ParticularName = ', v_ParticularName) AS v_ParticularName;

		

		#SELECT CONCAT("pasok5");

		if (STRCMP(v_ParticularName, "WEEPAY") != 0)

		THEN

			CALL spGetQueryString('Search', 'Particular', v_ParticularID, @p_outQueryString);

			#SELECT CONCAT('p_outQueryString = ', @p_outQueryString) AS p_outQueryString;

			

			#SELECT CONCAT("pasok6");		

			CALL spDeleteCollectionDetail('Delete', 'Merchant', @p_outQueryString, 'ERM Temp Detail CleanUp Client'); 

		END IF;

		

		#SELECT CONCAT("pasok5");		

		# Check for count for duplicate is > 0

		CALL spViewCount("Search", "ERM Detail Temp Void", "", @p_outCount);		

		IF (@p_outCount > 0) THEN

		CALL spCheckVoidSalesERM('Search', 'Duplicate', '');

		END IF;

		

		#SELECT CONCAT("pasok6");

		# Check for count for duplicate is > 0

		CALL spViewCount("Search", "ERM Detail Temp Duplicate", "", @p_outCount);		

		IF (@p_outCount > 0) THEN

		CALL spCheckDuplicateERM('Search', 'Duplicate', '');

		END IF;

		

		#SELECT (CONCAT("Process complete"));

					

	END IF;          

	# Execute Query 

	#PREPARE QUERY FROM @QUERY;

	#EXECUTE QUERY;	

END IF; 

       

END */$$
DELIMITER ;

/* Procedure structure for procedure `spProcessIRList` */

/*!50003 DROP PROCEDURE IF EXISTS  `spProcessIRList` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spProcessIRList`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE var_sql_statement LONGTEXT;

	DECLARE v_finished INT DEFAULT 0;

    DECLARE v_ID INT;    

    DECLARE C1 CURSOR FOR

			

			SELECT CONCAT("UPDATE tblservicingdetailtemp SET IRDate=", "'", IFNULL(b.IRDate, "-"), "'", ",", " ", 

						 "InstallationDate=", "'", IFNULL(b.InstallationDate, "-"), "'", ",", " ",

						 "MerchantName=", "'", IFNULL(b.MerchantName, "-"), "'", ",", " ",

						 "Region=", "'", IFNULL(e.Region, "-"), "'", ",", " ",

						 "Province=", "'", IFNULL(d.Province, "-"), "'", ",", " ", 

						 "IRStatusDescription=", "'", IFNULL(b.IRStatusDescription, "-"), "'", " ",

					"WHERE IRIDNo=", a.IRIDNo, ";") AS exec_sql 

			FROM

			tblservicingdetailtemp a

			LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

			LEFT JOIN tblterminalallocation AS c ON b.IRIDNo = c.IRID

			LEFT JOIN tblregiondetail AS d ON c.RegionID = d.RegionID

			LEFT JOIN tblregion AS e ON d.RegionType = e.RegionID

			GROUP BY a.IRIDNo;

            

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

    

    IF (p_StatementType = 'Update')

    THEN

		OPEN C1;

		GET_RECORD: LOOP

			FETCH C1 INTO var_sql_statement;                

		#SELECT (CONCAT('var_sql_statement', var_sql_statement));                

		SET @QUERY = var_sql_statement;					                

			IF (v_finished = 1)

			THEN

				LEAVE GET_RECORD;

			END IF;

			# Execute Query (Delete)

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

		END LOOP GET_RECORD;

		CLOSE C1;   

    END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spProcessReportDataStorage` */

/*!50003 DROP PROCEDURE IF EXISTS  `spProcessReportDataStorage` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spProcessReportDataStorage`(
    IN p_StatementType VARCHAR(50),
    IN p_SearchBy VARCHAR(500),
    IN p_SearchValue LONGTEXT
)
BEGIN
    DECLARE v_Header INT;
    DECLARE v_ClientID INT;
    DECLARE v_JobTypeList VARCHAR(45);
    DECLARE done INT DEFAULT FALSE;
    DECLARE vStorageType INT;
    DECLARE vTitle VARCHAR(255);
    DECLARE vDescription VARCHAR(255);
    DECLARE vTCount INT;
    DECLARE vTTotal INT;
    DECLARE vMonth INT DEFAULT 1; -- Start with January
    DECLARE monthColumn VARCHAR(20);
    DECLARE vYear VARCHAR(45);
    DECLARE vHoldTitle VARCHAR(45);
    
    DECLARE vDateFrom VARCHAR(10);
    DECLARE vDateTo VARCHAR(10);
    
    DECLARE vYearFrom VARCHAR(10);
    DECLARE vMonthFrom VARCHAR(10);
    DECLARE vYearTo VARCHAR(10);
    DECLARE vMonthTo VARCHAR(10);
    
    -- Declare a cursor for fetching results from temp_result
    DECLARE cur CURSOR FOR 
    SELECT Title, DESCRIPTION, TCount, TTotal FROM temp_result;

    -- Declare handler for loop exit condition
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    #SELECT CONCAT("p_StatementType=", p_StatementType);
    #SELECT CONCAT("p_SearchBy=", p_SearchBy);
    #SELECT CONCAT("p_SearchValue=", p_SearchValue);
    
    SET vHoldTitle = '';
    SET v_Header = 0;
    SET vYear = YEAR(NOW());
    SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
    SET v_JobTypeList = ADD_SINGLEQUOTE(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)));

    # cleanup for condtion to meet condition below
    SET v_JobTypeList = REPLACE(v_JobTypeList, '''', ''); -- remove single quotes
    SET v_JobTypeList = REPLACE(v_JobTypeList, ' ', '');  -- remove spaces
    
    # 1,3 = INSTALLATION, REPROGRAMMING (Installation Report)
    # 6,7 = SERVICING, REPLACEMENT	    (Maintenance Report)
    # 4   = PULL-OUT		    (Pull-out Report)
    IF (v_JobTypeList = '1,3') THEN
	SET @JobTypeList = '1';
    ELSEIF (v_JobTypeList = '6,7') THEN
	SET @JobTypeList = '2';
    ELSE
	SET @JobTypeList = '3';
    END IF;

    SET v_JobTypeList = ADD_SINGLEQUOTE(v_JobTypeList);
    
    SET vDateFrom = COALESCE(NULLIF(TRIM(SPLIT_STRING(p_SearchValue, '|', 3)), ''), DATE_FORMAT(CURDATE(), '%Y-01-01'));
    SET vDateTo   = COALESCE(NULLIF(TRIM(SPLIT_STRING(p_SearchValue, '|', 4)), ''), DATE_FORMAT(CURDATE(), '%Y-%m-%d'));

    SET vYearFrom  = COALESCE(YEAR(STR_TO_DATE(vDateFrom, '%Y-%m-%d')), YEAR(CURDATE()));
    SET vMonthFrom = COALESCE(MONTH(STR_TO_DATE(vDateFrom, '%Y-%m-%d')), 1);
    SET vYearTo    = COALESCE(YEAR(STR_TO_DATE(vDateTo, '%Y-%m-%d')), YEAR(CURDATE()));
    SET vMonthTo   = COALESCE(MONTH(STR_TO_DATE(vDateTo, '%Y-%m-%d')), MONTH(CURDATE()));

    IF (vYearFrom <> vYearTo) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Date From and Date To must be within the same year.';
    END IF;

    IF (STR_TO_DATE(vDateFrom, '%Y-%m-%d') > STR_TO_DATE(vDateTo, '%Y-%m-%d')) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Date From cannot be greater than Date To.';
    END IF;

    SET vYear = vYearFrom;
    		
    IF (p_SearchBy = 'Overall Request Per Team Lead') THEN

	    SET @StorageType = 6;
	    SET @Header = 'REQUEST PER TEAM LEAD';

	    SET @Dispatchers =
	    'AL ZEDRICK A LAMATAO|
	     REGGIE D. CALDITO|
	     REYREN DE GUZMAN|
	     APOLINARIO SAMALCA JR.';


	    SET @query = CONCAT('

	    SELECT
		', @StorageType, ' AS StorageType,

		pairs.Dispatcher AS pTitle,

		pairs.RegionType AS pDescription,

		COALESCE(SUM(CASE WHEN s.DaysOverDue <= -7 THEN 1 ELSE 0 END),0) AS Negative7AndBelow,
		COALESCE(SUM(CASE WHEN s.DaysOverDue = -6 THEN 1 ELSE 0 END),0) AS Negative6,
		COALESCE(SUM(CASE WHEN s.DaysOverDue = -5 THEN 1 ELSE 0 END),0) AS Negative5,
		COALESCE(SUM(CASE WHEN s.DaysOverDue = -4 THEN 1 ELSE 0 END),0) AS Negative4,
		COALESCE(SUM(CASE WHEN s.DaysOverDue = -3 THEN 1 ELSE 0 END),0) AS Negative3,
		COALESCE(SUM(CASE WHEN s.DaysOverDue = -2 THEN 1 ELSE 0 END),0) AS Negative2,
		COALESCE(SUM(CASE WHEN s.DaysOverDue = -1 THEN 1 ELSE 0 END),0) AS Negative1,
		COALESCE(SUM(CASE WHEN s.DaysOverDue =  0 THEN 1 ELSE 0 END),0) AS Zero,
		COALESCE(SUM(CASE WHEN s.DaysOverDue =  1 THEN 1 ELSE 0 END),0) AS Positive1,
		COALESCE(SUM(CASE WHEN s.DaysOverDue =  2 THEN 1 ELSE 0 END),0) AS Positive2,
		COALESCE(SUM(CASE WHEN s.DaysOverDue =  3 THEN 1 ELSE 0 END),0) AS Positive3,
		COALESCE(SUM(CASE WHEN s.DaysOverDue >= 4 THEN 1 ELSE 0 END),0) AS Positive4AndAbove,

		COUNT(s.IRNo) AS Total

	    FROM
	    (
		SELECT 
		    d.Dispatcher,
		    r.RegionType

		FROM
		(
		    SELECT "AL ZEDRICK A LAMATAO" AS Dispatcher
		    UNION ALL SELECT "REGGIE D. CALDITO"
		    UNION ALL SELECT "REYREN DE GUZMAN"
		    UNION ALL SELECT "APOLINARIO SAMALCA JR."		    
		) d

		CROSS JOIN
		(
		    SELECT "METRO MANILA" AS RegionType
		    UNION ALL
		    SELECT "PROVINCIAL"
		) r

	    ) pairs


	    LEFT JOIN tmplatestservice s

		ON s.Dispatcher = pairs.Dispatcher

		AND s.RegionType = pairs.RegionType

		AND s.ClientID = ',v_ClientID,'

		AND CAST(s.ServiceDate AS DATE)
		    BETWEEN ',ADD_SINGLEQUOTE(vDateFrom),'
		    AND ',ADD_SINGLEQUOTE(vDateTo),'

		AND (
			    FIND_IN_SET(
				s.JobType,
				', v_JobTypeList, '
			    )
		    )

		AND s.ServiceResult = "PENDING"


	    GROUP BY
		pairs.Dispatcher,
		pairs.RegionType


	    ORDER BY

		FIELD(
		    pairs.Dispatcher,
		    "AL ZEDRICK A LAMATAO",
		    "REGGIE D. CALDITO",
		    "REYREN DE GUZMAN",
		    "APOLINARIO SAMALCA JR."		    
		),

		FIELD(
		    pairs.RegionType,
		    "METRO MANILA",
		    "PROVINCIAL"
		);

	    ');
		#SELECT CONCAT("@query=", @query);
		
		-- Use Insert/Select
		SET @insertSelect = CONCAT(
			    'INSERT INTO tblreportdatastorage (StorageType, Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount) ',
			    @query
			);

	        PREPARE stmtInsertSelect FROM @insertSelect;
	        EXECUTE stmtInsertSelect;
	        DEALLOCATE PREPARE stmtInsertSelect;
	        
	        
	        -- Insert GrandTotal
	        SET @insertTotal = CONCAT(
		    'INSERT INTO tblreportdatastorage (Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, StorageType) ',
		    'SELECT "GRAND TOTAL", "-", ',
		    'COALESCE(SUM(January), 0), COALESCE(SUM(February), 0), COALESCE(SUM(March), 0), COALESCE(SUM(April), 0), ',
		    'COALESCE(SUM(May), 0), COALESCE(SUM(June), 0), COALESCE(SUM(July), 0), COALESCE(SUM(August), 0), ',
		    'COALESCE(SUM(September), 0), COALESCE(SUM(October), 0), COALESCE(SUM(November), 0), COALESCE(SUM(December), 0), ',
		    'COALESCE(SUM(TCount), 0), ',
		    @StorageType, ' ',
		    'FROM tblreportdatastorage ',
		    'WHERE StorageType = ', QUOTE(@StorageType), ' AND Description != "-";'
		);
		
		#SELECT CONCAT("@insertTotal=", @insertTotal);
		    
		PREPARE stmtTotal FROM @insertTotal;
		EXECUTE stmtTotal;
		DEALLOCATE PREPARE stmtTotal;
		
		-- Insert new line
		SET @insertNewLine = CONCAT(
					    "INSERT INTO tblreportdatastorage (Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal, StorageType) ",
					    "VALUES ('-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '0', '0', '", @StorageType, "')"
					);
				    
		PREPARE stmtNewLine FROM @insertNewLine;
		EXECUTE stmtNewLine;
		DEALLOCATE PREPARE stmtNewLine;
		
    ELSE
		-- Loop only through selected months (e.g. Mar-Jul).
		SET vMonth = CAST(vMonthFrom AS UNSIGNED);
		month_loop: WHILE vMonth <= CAST(vMonthTo AS UNSIGNED) DO
	    
		-- Map month number to column name
		SET monthColumn = CASE vMonth
		    WHEN 1 THEN 'January'
		    WHEN 2 THEN 'February'
		    WHEN 3 THEN 'March'
		    WHEN 4 THEN 'April'
		    WHEN 5 THEN 'May'
		    WHEN 6 THEN 'June'
		    WHEN 7 THEN 'July'
		    WHEN 8 THEN 'August'
		    WHEN 9 THEN 'September'
		    WHEN 10 THEN 'October'
		    WHEN 11 THEN 'November'
		    WHEN 12 THEN 'December'
		END;

		-- Empty the temporary table before inserting new data
		DELETE FROM temp_result;

		SET @tempinsertquery = 'INSERT INTO temp_result (Title, Description, TCount, TTotal) ';
				
		-- Dynamic Query Construction
		IF (p_SearchBy = 'Reason Summary') THEN

		    SET @StorageType = 1;
		    SET @Header = 'NEGATIVE/UNSUCCESSFUL ACTIVITY';

		    SET @reasonCondition = '';

		    IF (@JobTypeList = '1') THEN
			    SET @reasonCondition =
				'AND (JobType IN (1,3) OR (JobType = 7 AND ReasonID = 60))';

		    ELSEIF (@JobTypeList = '2') THEN
			    SET @reasonCondition =
				'AND JobType IN (6,7)';

	            ELSE
			    SET @reasonCondition =
				'AND JobType IN (4)';
		    END IF;

		    SET @query = CONCAT('

			SELECT
			    "-" AS pTitle,
			    x.Reason AS pDescription,
			    COUNT(DISTINCT t.IRNo) AS TCount,
			    0 AS TTotal

			FROM
			(
			    SELECT "FOR CONTINUATION" AS Reason
			    UNION ALL SELECT "PARTS REPLACEMENT"
			    UNION ALL SELECT "POS REPLACEMENT"			    
			    UNION ALL SELECT "SIM REPLACEMENT"
			    UNION ALL SELECT "TERMINAL REPLACEMENT"
			    UNION ALL SELECT "CLOSED MERCHANT"
			    UNION ALL SELECT "MERCHANT NOT FOUND"
			    UNION ALL SELECT "MOVED OUT"
			    UNION ALL SELECT "PHONELINE PROBLEM"
			    UNION ALL SELECT "REFUSED BY MERCHANT"
			    UNION ALL SELECT "RESCHEDULED BY MERCHANT"
			    UNION ALL SELECT "SIGNAL PROBLEM BOTH TELCO"
			    UNION ALL SELECT "UNDER CONSTRUCTION"
			    UNION ALL SELECT "OTHERS"
			) x

			LEFT JOIN tmplatestservice t
			    ON t.Reason = x.Reason
			   AND t.ClientID = ', v_ClientID, '
			   AND YEAR(t.ServiceDate) = ', vYear, '
			   AND MONTH(t.ServiceDate) = ', vMonth, '
			   AND t.ServiceResult = ''NEGATIVE''			   
			   ', @reasonCondition, '

			GROUP BY x.Reason

			ORDER BY FIELD
			(
			    x.Reason,
			    "FOR CONTINUATION",
			    "PARTS REPLACEMENT",
			    "POS REPLACEMENT",			    
			    "SIM REPLACEMENT",
			    "TERMINAL REPLACEMENT",
			    "CLOSED MERCHANT",
			    "MERCHANT NOT FOUND",
			    "MOVED OUT",
			    "PHONELINE PROBLEM",
			    "REFUSED BY MERCHANT",
			    "RESCHEDULED BY MERCHANT",
			    "SIGNAL PROBLEM BOTH TELCO",
			    "UNDER CONSTRUCTION",
			    "OTHERS"
			);

		    ');

		    #SELECT CONCAT("@query=", @query);	
			
		ELSEIF (p_SearchBy = 'Overall Request Summary') THEN

		    SET @StorageType = 2;
		    SET @Header = CONCAT('OVERALL REQUESTS ', vYear, '%');

		    SET @query = CONCAT('

			    SELECT
				"-" AS pTitle,
				x.RequestType AS pDescription,
				COUNT(s.IRNo) AS TCount,
				0 AS TTotal

			    FROM
			    (
				SELECT "ADDITIONAL POS" AS RequestType
				UNION ALL SELECT "EXHIBIT POS"
				UNION ALL SELECT "NEW INSTALLATION"
				UNION ALL SELECT "POS SWAPPING"
				UNION ALL SELECT "REPROGRAMMING"
			    ) x

			    LEFT JOIN tmplatestservice s
				ON
				(
				    (
					x.RequestType = s.RequestType
					AND FIND_IN_SET(s.JobType, ', v_JobTypeList, ')
				    )
				    OR
				    (
					x.RequestType = "REPROGRAMMING"
					AND s.ReasonID = 60
				    )
				)
				AND s.ClientID = ', v_ClientID, '
				AND YEAR(s.ServiceDate) = ', vYear, '
				AND MONTH(s.ServiceDate) = ', vMonth, '

			    GROUP BY
				x.RequestType

			    ORDER BY FIELD(
				x.RequestType,
				"ADDITIONAL POS",
				"EXHIBIT POS",
				"NEW INSTALLATION",
				"POS SWAPPING",
				"REPROGRAMMING"
			    );

			');
			
		     #SELECT CONCAT("@query=", @query);	

		ELSEIF (p_SearchBy = 'Overall Status Summary') THEN
		    SET @StorageType = 3;
		    SET @Header = 'OVERALL REQUESTS';	
		    
		    SET @reasonCondition = '';
   		    IF (@JobTypeList = '1') THEN
			SET @reasonCondition = 'OR (f.JobType = 7 AND f.ReasonID IN (60)) ';
		    ELSEIF (@JobTypeList = '2') THEN
			SET @reasonCondition = 'AND f.ReasonID NOT IN (60) ';
		    END IF;
			
			SET v_JobTypeList = TRIM(BOTH "'" FROM v_JobTypeList);
			
			SET @query = CONCAT(
			    'SELECT ',
			    '    r.Region AS pTitle, ',
			    '    s.pDescription, ',
			    '    COUNT(t.ServiceNo) AS TCount, ',
			    '    0 AS TTotal ',
			    'FROM (SELECT DISTINCT Region FROM tblregion WHERE isActive > 0) r ',
			    'CROSS JOIN (',
			    '    SELECT ''CANCELLED'' AS pDescription ',
			    '    UNION ALL SELECT ''HOLD'' ',
			    '    UNION ALL SELECT ''NEGATIVE'' ',
			    '    UNION ALL SELECT ''PENDING'' ',
			    '    UNION ALL SELECT ''RESOLVED'' ',
			    ') s ',
			    'LEFT JOIN tmplatestservice t ',
			    '       ON t.RegionType = r.Region ',
			    '      AND t.ServiceResult = s.pDescription ',
			    '      AND t.ClientID = ', v_ClientID, ' ',
			    '      AND YEAR(t.ServiceDate) = ', vYear, ' ',
			    '      AND MONTH(t.ServiceDate) = ', vMonth, ' ',
			    '      AND (',
			    '           FIND_IN_SET(t.JobType, ', ADD_SINGLEQUOTE(v_JobTypeList), ') ',
			    '           OR (t.JobType = 7 AND t.ReasonID = 60)',
			    '      ) ',
			    'GROUP BY r.Region, s.pDescription ',
			    'ORDER BY r.Region, FIELD(s.pDescription, ',
			    '    ''CANCELLED'', ''HOLD'', ''NEGATIVE'', ''PENDING'', ''RESOLVED'')'
			);
			
			#SELECT CONCAT("@query=", @query);
			
		ELSEIF (p_SearchBy = 'Overall Request Within SLA Summary') THEN

		    SET @StorageType = 4;
		    SET @Header = 'REQUEST WITHIN SLA';

		    SET @query = CONCAT('

			SELECT
			    r.Region AS pTitle,
			    x.ServiceResult AS pDescription,
			    COUNT(DISTINCT s.IRNo) AS TCount,
			    0 AS TTotal

			FROM
			(
			    SELECT "RESOLVED" AS ServiceResult
			    UNION ALL
			    SELECT "NEGATIVE"
			    UNION ALL
			    SELECT "PENDING"
			) x

			CROSS JOIN tblregion r

			LEFT JOIN tmplatestservice s
			    ON s.RegionType = r.Region
			   AND s.ServiceResult = x.ServiceResult
			   AND s.ClientID = ', v_ClientID, '
			   AND YEAR(s.ServiceDate) = ', vYear, '
			   AND MONTH(s.ServiceDate) = ', vMonth, '
			   AND (
				FIND_IN_SET(s.JobType, ', v_JobTypeList, ')
				OR (s.JobType = 7 AND s.ReasonID = 60)
			   )
			   AND s.TATStatus = "WITHIN TAT"

			WHERE
			    r.isActive > 0

			GROUP BY
			    r.Region,
			    x.ServiceResult

			ORDER BY
			    r.Region,
			    FIELD(
				x.ServiceResult,
				"RESOLVED",
				"NEGATIVE",
				"PENDING"
			    );

			');
			
		     #SELECT CONCAT("@query=", @query);
	
		ELSEIF (p_SearchBy = 'Overall Request Beyond SLA Summary') THEN

		    SET @StorageType = 5;
		    SET @Header = 'REQUEST BEYOND SLA';


		    SET @query = CONCAT('

		    SELECT
			base.pTitle,
			base.pDescription,
			COALESCE(actual.TCount,0) AS TCount,
			0 AS TTotal

		    FROM
		    (
			SELECT
			    r.Region AS pTitle,
			    x.ServiceResult AS pDescription

			FROM tblregion r

			CROSS JOIN
			(
			    SELECT "RESOLVED" AS ServiceResult
			    UNION ALL
			    SELECT "NEGATIVE"
			    UNION ALL
			    SELECT "PENDING"

			) x

			WHERE r.isActive > 0

		    ) base


		    LEFT JOIN
		    (
			SELECT
			    s.RegionType AS pTitle,
			    s.ServiceResult AS pDescription,
			    COUNT(DISTINCT s.IRNo) AS TCount

			FROM tmplatestservice s


			WHERE
			    s.ClientID = ', v_ClientID, '
			    AND YEAR(s.ServiceDate) = ', vYear, '
			    AND MONTH(s.ServiceDate) = ', vMonth, '
			    AND FIND_IN_SET(s.JobType,', v_JobTypeList, ')
			    AND s.TATStatus = "BEYOND TAT"


			GROUP BY
			    s.RegionType,
			    s.ServiceResult


		    ) actual


		    ON actual.pTitle = base.pTitle
		    AND actual.pDescription = base.pDescription


		    ORDER BY
			base.pTitle,

			FIELD(
			    base.pDescription,
			    "RESOLVED",
			    "NEGATIVE",
			    "PENDING"
			);

		    ');
			
			#SELECT CONCAT("@query=", @query);
			
		ELSEIF (p_SearchBy = 'Overall Current SLA') THEN
		    SET @StorageType = 7;
		    SET @Header = 'CURRENT SLA %';	
		    
		    SET @JobTypeStatusFilter = "'RESOLVED','NEGATIVE','PENDING'";

		    SET @query = CONCAT('
			SELECT 
			    Region AS pTitle,
			    "-" AS pDescription,
			    #ROUND((FilteredCount / TotalCount) * 100.00, 2) AS TCount,
			    FORMAT((COALESCE(FilteredCount, 0.00) / COALESCE(TotalCount, 0.00)) * 100.00, 2) AS TCount,
			    FilteredCount + TotalCount AS TTotal
			FROM (
			    SELECT 
				Region,
				FORMAT(SUM(IF(IsFiltered = 1, 1, 0)), 2) AS FilteredCount,
				FORMAT(COUNT(*), 2) AS TotalCount
			    FROM (
				SELECT 
				    r.Region,
				    CASE
					WHEN (funcGetDaysOverDue("Search", "Days OverDue", s.ServiceNo) <= 0) THEN 1
					ELSE 0
				    END AS IsFiltered,
				    CASE 
					WHEN s.JobTypeStatusDescription IN ("PENDING", "PROCESSING") THEN "PENDING"
					WHEN s.JobTypeStatusDescription = "COMPLETED" THEN 
					    CASE 
						WHEN f.ActionMade = "SUCCESS" THEN "RESOLVED"
						WHEN f.ActionMade = "NEGATIVE" THEN "NEGATIVE"
						ELSE "INVALID"
					    END
					ELSE "INVALID"
				    END AS FinalStatus
				FROM tblregion r
				LEFT JOIN tblparticular p ON r.RegionID = p.RegionType
				LEFT JOIN tblservicingdetail s ON p.ParticularID = s.MerchantID
				LEFT JOIN tblfsrdetail f ON s.ServiceNo = f.ServiceNo
				WHERE 
				    r.isActive > 0
				    AND (f.ClientID = ', v_ClientID, ' OR f.ClientID IS NULL)
				    AND FIND_IN_SET(s.JobType, ', v_JobTypeList, ')
				    AND s.JobTypeStatusDescription IN ("PENDING", "PROCESSING", "COMPLETED")
				    AND YEAR(s.ServiceDate) = ', vYear, '
				    AND MONTH(s.ServiceDate) = ', vMonth, '
			    ) AS RawData
			    WHERE FinalStatus IN (', @JobTypeStatusFilter, ')
			    GROUP BY Region
			) AS Summary
			ORDER BY pTitle;
			');

		END IF;

		SET @insertquery = CONCAT(@tempinsertquery, @query);
		
		#SELECT CONCAT("@JobTypeList=", @JobTypeList);
		#SELECT CONCAT("@tempinsertquery=", @tempinsertquery);
		#SELECT CONCAT("@query=", @query);
		#SELECT CONCAT("@insertquery=", @insertquery);
		
		-- Execute the dynamic query
		PREPARE stmt FROM @insertquery;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;
		
		-- Open the cursor
		OPEN cur;

		-- Fetch data row-by-row
		read_loop: LOOP
		    FETCH cur INTO vTitle, vDescription, vTCount, vTTotal;

		    -- Exit loop if no more rows
		    IF done THEN
			LEAVE read_loop;
		    END IF;

		    -- Ensure NULL values are treated as 0
		    IF vTCount IS NULL THEN
			SET vTCount = 0;
		    END IF;
		
		    -- Check if the Description already exists
		    IF ((SELECT COUNT(*)
			    FROM tblreportdatastorage
			    WHERE StorageType=@StorageType
			      AND Title=vTitle
			      AND DESCRIPTION=vDescription) > 0) THEN
			      
			-- Update existing row
			/*
			SET @updateQuery = CONCAT('UPDATE tblreportdatastorage SET ', monthColumn, ' = ', vTCount, 
						  ', TCount = TCount + ', vTCount, ',StorageType = ', @StorageType, ',TTotal = ', vTTotal, ' WHERE Title = ', "'", vTitle, "'", ' AND ', 'Description = ', "'", vDescription, "'", ';');
			*/
			SET @updateQuery = CONCAT(
						'UPDATE tblreportdatastorage
						 SET ',
						monthColumn,'=',vTCount,
						', TCount=TCount+',vTCount,
						', StorageType=',@StorageType,
						', TTotal=',vTTotal,
						' WHERE StorageType=',@StorageType,
						' AND Title=',QUOTE(vTitle),
						' AND Description=',QUOTE(vDescription)
						);

			#SELECT CONCAT("@updateQuery=",@updateQuery);
			IF (LENGTH(vDescription)) THEN
				PREPARE stmtUpdate FROM @updateQuery;
				EXECUTE stmtUpdate;
				DEALLOCATE PREPARE stmtUpdate;
			END IF;
			
		    ELSE
			#SELECT CONCAT("vHoldTitle=",vHoldTitle,'|','vTitle=', vTitle);
			IF (vHoldTitle != vTitle) THEN
				SET vHoldTitle = vTitle;
				SET v_Header = 0;
			END IF;
			
			-- Insert total header
			IF (v_Header = 0 AND (@StorageType = 3 OR @StorageType = 4)) THEN
				SET @insertTotalHeader = CONCAT('INSERT INTO tblreportdatastorage (Title, Description, StorageType, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal) ',
								    'VALUES (', 
								    QUOTE(vTitle), ', ',        
								    QUOTE('TOTAL'), ', ',            
								    QUOTE(@StorageType), ', ',    
								    QUOTE('0'), ', ',             
								    QUOTE('0'), ', ',             
								    QUOTE('0'), ', ',            
								    QUOTE('0'), ', ',            
								    QUOTE('0'), ', ',          
								    QUOTE('0'), ', ',           
								    QUOTE('0'), ', ',            
								    QUOTE('0'), ', ',           
								    QUOTE('0'), ', ',            
								    QUOTE('0'), ', ',           
								    QUOTE('0'), ', ',            
								    QUOTE('0'), ', ',           
								    '0, ',                       
								    '0);'                       
								);
					    
				 PREPARE stmtTotalHeader FROM @insertTotalHeader;
				 EXECUTE stmtTotalHeader;
				 DEALLOCATE PREPARE stmtTotalHeader;
				 
				 SET v_Header = 1;
				 
			 END IF;
			 
			-- Insert new row
			SET @insertQuery = CONCAT('INSERT INTO tblreportdatastorage (Title, ', monthColumn, ', TCount, TTotal, StorageType, Description) VALUES ("', 
						  vTitle, '",', vTCount, ',', vTCount, ',', vTTotal, ',', @StorageType, ',', "'", vDescription, "'", ')', ';');
			
			#SELECT CONCAT("@insertQuery=",@insertQuery);
			IF (LENGTH(vDescription)) THEN
				PREPARE stmtInsert FROM @insertQuery;
				EXECUTE stmtInsert;
				DEALLOCATE PREPARE stmtInsert;
			END IF;
			
		    END IF;
		    
		END LOOP;

		-- Close cursor
		CLOSE cur;

		-- Move to the next month
		SET vMonth = vMonth + 1;
		SET done = FALSE; -- Reset done flag for next cursor execution
		
		IF (vMonth > CAST(vMonthTo AS UNSIGNED)) THEN
			SET @insertTotal = CONCAT(
			    'INSERT INTO tblreportdatastorage (Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal, StorageType) ',
			    'SELECT "GRAND TOTAL", "-", ',
			    'COALESCE(SUM(January), 0), COALESCE(SUM(February), 0), COALESCE(SUM(March), 0), COALESCE(SUM(April), 0), ',
			    'COALESCE(SUM(May), 0), COALESCE(SUM(June), 0), COALESCE(SUM(July), 0), COALESCE(SUM(August), 0), ',
			    'COALESCE(SUM(September), 0), COALESCE(SUM(October), 0), COALESCE(SUM(November), 0), COALESCE(SUM(December), 0), ',
			    'COALESCE(SUM(TCount), 0), ',
			    'COALESCE(SUM(TTotal), 0), ',
			    @StorageType, ' ',
			    'FROM tblreportdatastorage ',
			    'WHERE StorageType = ', QUOTE(@StorageType), ' AND Description != "-";'
			);

		    #SELECT CONCAT("@insertTotal=", @insertTotal);
		    
		    PREPARE stmtTotal FROM @insertTotal;
		    EXECUTE stmtTotal;
		    DEALLOCATE PREPARE stmtTotal;
		    
		    -- Insert new line
		    SET @insertNewLine = CONCAT(
					    "INSERT INTO tblreportdatastorage (Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal, StorageType) ",
					    "VALUES ('-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '-', '0', '0', '", @StorageType, "')"
					);
					    
		    PREPARE stmtNewLine FROM @insertNewLine;
		    EXECUTE stmtNewLine;
		    DEALLOCATE PREPARE stmtNewLine;
		
		END IF;
	    END WHILE;
	    
	 # delete extra TOTAL
	 DELETE FROM tblreportdatastorage
	  WHERE ID IN (
	    SELECT max_id FROM (
		SELECT MAX(ID) AS max_id
		FROM tblreportdatastorage
		WHERE StorageType = @StorageType
		  AND DESCRIPTION = 'TOTAL'
		GROUP BY Title, DESCRIPTION
		HAVING COUNT(*) > 1  -- <-- Only if more than 1 record
	    ) AS subquery
	 )
	 AND StorageType = @StorageType
	 AND DESCRIPTION = 'TOTAL';

	-- Build the SELECT query dynamically for SELECT and prepare for INSERT	
	IF (@StorageType = 3) THEN
		SET @CurrentOverallTitle = 'OVERALL REQUESTS';
	ELSE
		SET @CurrentOverallTitle = CONCAT(
		    'OVERALL REQUESTS ',
		    YEAR(CURDATE()),
		    '%'
		);
	END IF;	
	
	#SELECT CONCAT("CurrentOverallTitle=", @CurrentOverallTitle);

	SET @sql_select = '';	
	SET @sql_select = CONCAT(
	    'SELECT StorageType, Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal ',
	    'FROM tblreportdatastorage ',
	    'WHERE StorageType = ', @StorageType, ' ',
	    'ORDER BY ',
	    
	    'CASE ',
		"WHEN Title = '-' AND Description = '-' THEN 5 ",
		"WHEN Title = 'GRAND TOTAL' THEN 4 ",
		"WHEN Title IN (
		    'METRO MANILA',
		    'PROVINCIAL',
		    'CURRENT SLA %',
		    'REQUEST PER TEAM LEAD',
		    '", @CurrentOverallTitle, "',
		    'OVERALL REQUESTS',
		    'REQUEST WITHIN SLA',
		    'NEGATIVE/UNSUCCESSFUL ACTIVITY'
		) THEN 1 ",
		'ELSE 2 ',
	    'END, ',

	    'CASE ',
		"WHEN Title IN (
		    'CURRENT SLA %',
		    'REQUEST PER TEAM LEAD',
		    '", @CurrentOverallTitle, "',
		    'OVERALL REQUESTS',
		    'REQUEST WITHIN SLA',
		    'NEGATIVE/UNSUCCESSFUL ACTIVITY'
		) THEN 1 ",
		"WHEN Title = 'METRO MANILA' THEN 2 ",
		"WHEN Title = 'PROVINCIAL' THEN 3 ",
		'ELSE 4 ',
	    'END, ',

	    'FIELD(
		Description,
		''TOTAL'',
		''CANCELLED'',
		''HOLD'',
		''NEGATIVE'',
		''PENDING'',
		''RESOLVED'',
		''NEGATIVE_'',
		''PENDING_'',
		''RESOLVED_'',
		''NEGATIVE__'',
		''PENDING__'',
		''RESOLVED__'',
		''-''
	    ) '
	);
	-- (Optional) Check the generated SQL
	#SELECT CONCAT("sql_select=", @sql_select);

	CALL spCreateTemporaryTable("Create", "Report Data Storage", "");
	
	SET @sql_insert = '';
	SET @sql_insert = CONCAT(
			    'INSERT INTO tbltempreportdatastorage (StorageType, Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal) ',
			    @sql_select
			);

	#SELECT CONCAT("sql_insert=", @sql_insert);
	
	PREPARE stmt FROM @sql_insert;
	EXECUTE stmt;
	DEALLOCATE PREPARE stmt;
	
	DELETE FROM tblreportdatastorage WHERE StorageType = @StorageType;
	
	SET @sql_select = '';
	SET @sql_select = CONCAT(
	    'SELECT StorageType, Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal FROM tbltempreportdatastorage '
	);
	
	SET @sql_insert = '';
	SET @sql_insert = CONCAT(
			    'INSERT INTO tblreportdatastorage (StorageType, Title, Description, January, February, March, April, May, June, July, August, September, October, November, December, TCount, TTotal) ',
			    @sql_select
			);
			
	PREPARE stmt FROM @sql_insert;
	EXECUTE stmt;
	DEALLOCATE PREPARE stmt;
	
    END IF;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spProcessServiceList` */

/*!50003 DROP PROCEDURE IF EXISTS  `spProcessServiceList` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spProcessServiceList`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

	IN p_SearchBy VARCHAR(50) /* = NULL */ ,

	IN p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE var_sql_statement LONGTEXT;

	DECLARE v_finished INT DEFAULT 0;

    DECLARE v_ID INT;    

    DECLARE C1 CURSOR FOR

			

			SELECT CONCAT("UPDATE tblservicingdetailtemp SET ServiceDateTime=", "'", IFNULL(b.ServiceDateTime, "-"), "'", ",", " ", 

						 "ServiceReqDate=", "'", IFNULL(b.ServiceReqDate, "-"), "'", ",", " ",

						 "ServiceReqTime=", "'", IFNULL(b.ServiceReqTime, "-"), "'", ",", " ",

						 "RequestNo=", "'", IFNULL(b.RequestNo, "-"), "'", ",", " ", 

						 "ReferenceNo=", "'", IFNULL(b.ReferenceNo, "-"), "'", ",", " ", 

						 "CustomerName=", "'", IFNULL(b.CustomerName, "-"), "'", ",", " ", 

						 "CustomerContactNo=", "'", IFNULL(b.CustomerContactNo, "-"), "'", ",", " ", 

						 "ClientName=", "'", IFNULL(b.ClientName, "-"), "'", ",", " ", 

						 "FEName=", "'", IFNULL(b.FEName, "-"), "'", ",", " ", 

						 "SIMSN=", "'", IFNULL(b.SIMSerialNo, "-"), "'", ",", " ", 

						 "SIMCarrier=", "'", IFNULL(g.Carrier, "-"), "'", ",", " ", 

						 "DockSN=", "'", IFNULL(b.DockSN, "-"), "'", ",", " ",

						 "ReplaceTerminalSN=", "'", IFNULL(b.ReplaceTerminalSN, "-"), "'", ",", " ",

						 "ReplaceSIMSN=", "'", IFNULL(b.ReplaceSIMSN, "-"), "'", ",", " ",						 

						 "ReplaceDockSN=", "'", IFNULL(b.ReplaceDockSN, "-"), "'", ",", " ",

						 "JobTypeDescription=", "'", IFNULL(b.JobTypeDescription, "-"), "'", ",", " ", 

						 "JobTypeStatusDescription=", "'", IFNULL(b.JobTypeStatusDescription, "-"), "'", ",", " ", 

						 "ActionMade=", "'", IFNULL(b.ActionMade, "-"), "'", ",", " ", 

						 "FSRDate=", "'", IFNULL(d.FSRDate, "-"), "'", ",", " ", 

						 "FSRTime=", "'", IFNULL(d.FSRTime, "-"), "'", ",", " ", 

						 "TimeArrived=", "'", IFNULL(d.TimeArrived, "-"), "'", ",", " ", 

						 "TimeStart=", "'", IFNULL(d.TimeStart, "-"), "'", ",", " ",

						 "TimeEnd=", "'", IFNULL(d.TimeEnd, "-"), "'", ",", " ",

						 "Remarks=", "'", IFNULL(b.Remarks, "-"), "'", ",", " ",

						 "ProblemReported=", "'", IFNULL(d.ProblemReported, "-"), "'", ",", " ",

						 "ActualProblemReported=", "'", IFNULL(d.ActualProblemReported, "-"), "'", ",", " ",

						 "ActionTaken=", "'", IFNULL(d.ActionTaken, "-"), "'", ",", " ", 

						 "AnyComments=", "'", IFNULL(d.Remarks, "-"), "'", ",", " ",

						 "MerchantRepresentative=", "'", IFNULL(d.MerchantRepresentative, "-"), "'", ",", " ", 

						 "MerchantContactNo=", "'", IFNULL(d.MerchantContactNo, "-"), "'", ",", " ", 

						 "ServiceReqTime=", "'", IFNULL(b.ServiceReqTime, "-"), "'", " ",  						 						 						 						 

			"WHERE ServiceNo=", a.ServiceNo, ";") AS exec_sql

			FROM

			tblservicingdetailtemp a

			LEFT JOIN tblservicingdetail AS b ON a.ServiceNo = b.ServiceNo

			LEFT JOIN tblirdetail AS c ON b.IRIDNo = c.IRIDNo

			LEFT JOIN tblfsrdetail AS d ON b.ServiceNo = d.ServiceNo

			LEFT JOIN tblparticular AS e ON b.ClientID = e.ParticularID

			LEFT JOIN tblparticular AS f ON b.FEID = f.ParticularID

			LEFT JOIN tblsimdetail AS g ON b.SIMID = g.SIMID

			GROUP BY a.IRIDNo, a.TAIDNo, a.ServiceNo;

            

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;      

    

    IF (p_StatementType = 'Update')

    THEN

		OPEN C1;

		GET_RECORD: LOOP

			FETCH C1 INTO var_sql_statement;                

		#SELECT (CONCAT('var_sql_statement', var_sql_statement));                

		SET @QUERY = var_sql_statement;					                

			IF (v_finished = 1)

			THEN

				LEAVE GET_RECORD;

			END IF;

			# Execute Query (Delete)

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

		END LOOP GET_RECORD;

		CLOSE C1;   

    END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spProcessTimeSheet` */

/*!50003 DROP PROCEDURE IF EXISTS  `spProcessTimeSheet` */;

DELIMITER $$

