/* Procedure structure for procedure `spReplaceDevice` */

/*!50003 DROP PROCEDURE IF EXISTS  `spReplaceDevice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spReplaceDevice`(
    IN in_id INT,
    IN in_NewTerminalSn VARCHAR(50),
    IN in_NewSimSn VARCHAR(50)
)
proc_block: BEGIN
    -- Current device
    DECLARE c_IrIdNo INT;
    DECLARE c_TID VARCHAR(60);
    DECLARE c_TerminalID INT;
    DECLARE c_TerminalSN VARCHAR(50);
    DECLARE c_SimID INT;
    DECLARE c_SimSN VARCHAR(50);

    -- New device
    DECLARE n_TerminalID INT DEFAULT NULL;
    DECLARE n_TerminalSN VARCHAR(50);
    DECLARE n_TerminalStatusID INT DEFAULT NULL;
    DECLARE n_SimID INT DEFAULT NULL;
    DECLARE n_SimSN VARCHAR(50);
    DECLARE n_SimStatusID INT DEFAULT NULL;

    DECLARE msg VARCHAR(255);
    DECLARE result TINYINT DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET msg = 'Unexpected database error occurred.';
        SELECT result AS Result, msg AS Message;
    END;

    START TRANSACTION;

    -- Get current IR device
    SELECT IRIDNo, TID, TerminalID, TerminalSN, SIMID, SIMSN
      INTO c_IrIdNo, c_TID, c_TerminalID, c_TerminalSN, c_SimID, c_SimSN
      FROM tblirdetail
     WHERE IRIDNo = in_id
       AND IRActive = 1
       AND TerminalID IS NOT NULL
       AND TerminalID <> 0
     LIMIT 1;

	-- Validate IRIDNo
    IF c_IrIdNo IS NULL THEN
        SET msg = 'I.R not found or inactive.';
        ROLLBACK;
        SELECT result AS Result, msg AS Message;
        LEAVE proc_block;
    END IF;
    
	-- Validate TID
    IF c_TID IS NULL THEN
        SET msg = 'TID not found or inactive.';
        ROLLBACK;
        SELECT result AS Result, msg AS Message;
        LEAVE proc_block;
    END IF;
    
	-- Check Installation service record
	IF NOT EXISTS (
		SELECT 1
		FROM tblservicingdetail
		WHERE JobType = 1
		  AND IRIDNo = c_IrIdNo
	) THEN
		SET msg = 'Installation Service not found.';
		ROLLBACK;
		SELECT result AS Result, msg AS Message;
		LEAVE proc_block;
	END IF;

    -- Get new terminal
    IF in_NewTerminalSn IS NOT NULL AND in_NewTerminalSn <> '' THEN
        SELECT TerminalID, TerminalSN, TerminalStatus
          INTO n_TerminalID, n_TerminalSN, n_TerminalStatusID
          FROM tblterminaldetail
         WHERE TerminalSN = in_NewTerminalSn
         LIMIT 1;
    END IF;

    -- Get new SIM
    IF in_NewSimSn IS NOT NULL AND in_NewSimSn <> '' THEN
        SELECT SIMID, SIMSN, SIMStatus
          INTO n_SimID, n_SimSN, n_SimStatusID
          FROM tblsimdetail
         WHERE SIMSN = in_NewSimSn
         LIMIT 1;
    END IF;

    -- Validate duplicates
    IF n_TerminalSN = c_TerminalSN THEN
        SET msg = 'This terminal is already installed on this TID.';
        ROLLBACK;
        SELECT result AS Result, msg AS Message;
        LEAVE proc_block;
    END IF;

    IF n_SimSN = c_SimSN THEN
        SET msg = 'This SIM is already installed on this TID.';
        ROLLBACK;
        SELECT result AS Result, msg AS Message;
        LEAVE proc_block;
    END IF;

    -- Validate: new terminal already installed
    IF n_TerminalID IS NOT NULL AND n_TerminalStatusID <> 1 THEN
        SET msg = 'Selected terminal is already installed or in an ongoing process.';
        ROLLBACK;
        SELECT result AS Result, msg AS Message;
        LEAVE proc_block;
    END IF;

    -- Validate: new SIM already installed
    IF n_SimID IS NOT NULL AND n_SimStatusID <> 1 THEN
        SET msg = 'Selected sim is already installed or in an ongoing process.';
        ROLLBACK;
        SELECT result AS Result, msg AS Message;
        LEAVE proc_block;
    END IF;

    -- Update IR detail
    UPDATE tblirdetail
       SET TerminalID = COALESCE(n_TerminalID, TerminalID),
           TerminalSN = COALESCE(n_TerminalSN, TerminalSN),
           SIMID	  = COALESCE(n_SimID, SIMID),
           SIMSN      = COALESCE(n_SimSN, SIMSN)
     WHERE IRIDNo = c_IrIdNo
       AND IRActive = 1;

    -- Update terminal statuses
    IF n_TerminalID IS NOT NULL THEN
        UPDATE tblterminaldetail
           SET TerminalStatus = 7,
               TerminalStatusDescription = 'INSTALLED',
               LocationID = 18,
               Location = 'PRODUCTION',
               ClientID = 21,
               ClientName = 'METROBANK'
         WHERE TerminalID = n_TerminalID;

        UPDATE tblterminaldetail
           SET TerminalStatus = 1,
               TerminalStatusDescription = 'AVAILABLE',
               LocationID = 1,
               Location = 'STOCK ROOM',
               ClientID = 0,
               ClientName = NULL
         WHERE TerminalID = c_TerminalID;
    END IF;

    -- Update SIM statuses
    IF n_SimID IS NOT NULL THEN
        UPDATE tblsimdetail
           SET SIMStatus = 7,
               SIMStatusDescription = 'INSTALLED',
               LocationID = 18,
               Location = 'PRODUCTION',
               ClientID = 21,
               ClientName = 'METROBANK'
         WHERE SIMID = n_SimID;

        UPDATE tblsimdetail
           SET SIMStatus = 1,
               SIMStatusDescription = 'AVAILABLE',
               LocationID = 1,
               Location = 'STOCK ROOM',
               ClientID = 0,
               ClientName = NULL
         WHERE SIMID = c_SimID;
    END IF;

    COMMIT;
    SET result = 1;
    SET msg = 'Device successfully replaced.';
    SELECT 1 AS Result, msg AS Message;

END proc_block */$$
DELIMITER ;

