/* Procedure structure for procedure `spServicingReversal` */

/*!50003 DROP PROCEDURE IF EXISTS  `spServicingReversal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spServicingReversal`(
    IN p_ServiceNo INT,
    IN p_Json JSON
)
BEGIN
	
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
    END;
    
    START TRANSACTION;
   
    -- LIST OF DEVICE STATUS -----------------------------------------------------
    #1: Available
    #2: Allocated
    #3: For Repair
    #4: Defective
    #5: Lost
    #6: Loan/Borrow
    #7: Installed
    #8: Dispatch
    #9: Negative
    #10: Reprogrammed
    #11: Pulled-Out
    #12: Diagnostic
    #13: Reprogrammed
    #14: Pulled Out
    #15: Leasing
   
    -- LIST OF JOB STATUS --------------------------------------------------------
    #1: Installation
    #2: Negative
    #3: Reprogramming
    #4: Pull-Out
    #5: Diagnostic
    #6: Servicing
    #7: Replacement
    #8: Dispatch
    #9: Hold Service
    #10: Cancel Service
   
    -- EXTRACT JSON DATA
    SET @d_JobType 		 = p_Json->>'$.JobType';
    SET @d_RepTerminalID = p_Json->>'$.RepTerminalID';
    SET @d_RepSIMID 	 = p_Json->>'$.RepSimID';
    
    -- GET CURRENT SERVICE RECORD
    SELECT s.IRIDNo, s.JobType, s.TerminalID, s.TerminalSN, s.SIMID, s.SIMSerialNo, s.ClientID, s.ClientName, f.ActionMade
    INTO @svc_IRIDNo, @svc_JobType, @svc_TerminalID, @svc_TerminalSN, @svc_SIMID, @svc_SIMSN, @svc_ClientID, @svc_ClientName, @fsr_ActionMade
    FROM tblservicingdetail s
    LEFT JOIN tblfsrdetail f ON f.ServiceNo = s.ServiceNo
    WHERE s.ServiceNo = p_ServiceNo
    LIMIT 1;
   
    -- GET NEW JOB TYPE
    SELECT JobType, JobTypeDescription, Description
    INTO @n_JobType, @n_JobTypeDesc, @n_JobDesc
    FROM tblservicetype
    WHERE JobType = @d_JobType
    LIMIT 1;
    
    IF @n_JobType IS NULL THEN
        ROLLBACK;
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Job type not found';
    END IF;
   
   -- TEMPORARY REMOVE IR CHECKING
   /*
    -- GET IR RECORD
    SELECT IRIDNo, TerminalID, SIMID
    INTO @ir_IRIDNo, @ir_TerminalID, @ir_SIMID
    FROM tblirdetail
    WHERE IRIDNo = @svc_IRIDNo
    LIMIT 1;
    IF @ir_IRIDNo IS NULL THEN
        ROLLBACK;
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'IR record not found';
    END IF;
    */
    
	-- ADD CONDITIONS HERE FOR SERVICE TYPES ------------------------------
	IF @n_JobType IN (3, 7) THEN -- REPROGRAMMING / REPLACEMENT START BLOCK

		-- VALIDATE DEVICE
		SELECT TerminalStatus, TerminalID, TerminalSN
		INTO @chkTerminalStatus, @rep_TerminalID, @rep_TerminalSN
		FROM tblterminaldetail
		WHERE TerminalID = @d_RepTerminalID;

		SELECT SIMStatus, SIMID, SIMSN
		INTO @chkSIMStatus, @rep_SIMID, @rep_SIMSN
		FROM tblsimdetail
		WHERE SIMID = @d_RepSIMID;

		IF @chkTerminalStatus <> 1 THEN
			ROLLBACK;
			SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Terminal is Not Available';
		END IF;

		IF @chkSIMStatus <> 1 THEN
			ROLLBACK;
			SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'SIM is Not Available';
		END IF;

		-- REPLACE SERVICE REQUEST DEVICE
		UPDATE tblservicingdetail s
		LEFT JOIN tblfsrdetail f ON f.ServiceNo = s.ServiceNo
		SET
			s.JobType = COALESCE(NULLIF(@n_JobType, ''), s.JobType),
			s.JobTypeDescription = COALESCE(NULLIF(@n_JobTypeDesc, ''), s.JobTypeDescription),
			s.JobTypeSubDescription = COALESCE(NULLIF(@n_JobDesc, ''), s.JobTypeSubDescription),
			f.JobType = COALESCE(NULLIF(@n_JobType, ''), f.JobType),
			f.JobTypeDescription = COALESCE(NULLIF(@n_JobTypeDesc, ''), f.JobTypeDescription),
			s.ReplaceTerminalID = COALESCE(NULLIF(@rep_TerminalID, ''), s.ReplaceTerminalID),
			s.ReplaceTerminalSN = COALESCE(NULLIF(@rep_TerminalSN, ''), s.ReplaceTerminalSN),
			s.ReplaceSIMID = COALESCE(NULLIF(@rep_SIMID, ''), s.ReplaceSIMID),
			s.ReplaceSIMSN = COALESCE(NULLIF(@rep_SIMSN, ''), s.ReplaceSIMSN),
			f.TerminalID = COALESCE(NULLIF(@rep_TerminalID, ''), f.TerminalID),
			f.TerminalSN = COALESCE(NULLIF(@rep_TerminalSN, ''), f.TerminalSN),
			f.SIMID = COALESCE(NULLIF(@rep_SIMID, ''), f.SIMID),
			f.SIMSN = COALESCE(NULLIF(@rep_SIMSN, ''), f.SIMSN)
		WHERE s.ServiceNo = p_ServiceNo;

	ELSEIF @n_JobType = 4 THEN
	
		-- PULLOUT
		UPDATE tblservicingdetail s
		LEFT JOIN tblfsrdetail f ON f.ServiceNo = s.ServiceNo
		SET
			s.JobType = COALESCE(NULLIF(@n_JobType, ''), s.JobType),
			s.JobTypeDescription = COALESCE(NULLIF(@n_JobTypeDesc, ''), s.JobTypeDescription),
			s.JobTypeSubDescription = COALESCE(NULLIF(@n_JobDesc, ''), s.JobTypeSubDescription),
			f.JobType = COALESCE(NULLIF(@n_JobType, ''), f.JobType),
			f.JobTypeDescription = COALESCE(NULLIF(@n_JobTypeDesc, ''), f.JobTypeDescription),
			s.ReplaceTerminalID = 0,
			s.ReplaceTerminalSN = 0,
			s.ReplaceSIMID = 0,
			s.ReplaceSIMSN = 0
		WHERE s.ServiceNo = p_ServiceNo;

	ELSEIF @n_JobType = 6 THEN
	
		-- SERVICING
		UPDATE tblservicingdetail s
		LEFT JOIN tblfsrdetail f ON f.ServiceNo = s.ServiceNo
		SET
			s.JobType = COALESCE(NULLIF(@n_JobType, ''), s.JobType),
			s.JobTypeDescription = COALESCE(NULLIF(@n_JobTypeDesc, ''), s.JobTypeDescription),
			s.JobTypeSubDescription = COALESCE(NULLIF(@n_JobDesc, ''), s.JobTypeSubDescription),
			f.JobType = COALESCE(NULLIF(@n_JobType, ''), f.JobType),
			f.JobTypeDescription = COALESCE(NULLIF(@n_JobTypeDesc, ''), f.JobTypeDescription),
			s.ReplaceTerminalID = 0,
			s.ReplaceTerminalSN = 0,
			s.ReplaceSIMID = 0,
			s.ReplaceSIMSN = 0
		WHERE s.ServiceNo = p_ServiceNo;

	END IF;
	
    COMMIT;
END */$$
DELIMITER ;

