/* Procedure structure for procedure `spTestView` */

/*!50003 DROP PROCEDURE IF EXISTS  `spTestView` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spTestView`(

 IN p_Statement VARCHAR(50),

 IN p_SearchBy  VARCHAR(50),

 IN p_SearchValue JSON)
BEGIN

	

	DECLARE v_ID INTEGER;

	DECLARE Category VARCHAR(100);

	

	SET Category = JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Category'));

	

	CASE p_Statement -- STATEMENT START BLOCK -- 



	WHEN "SERVICING" THEN -- SERVICING GROUP --



		CASE p_SearchBy  -- SEARCHBY START BLOCK --



		WHEN 'JOB DETAILS' THEN

			

		 SELECT 

			 Target_Date AS `Target Date`,

			 Job_ID AS `Job Number`,

			 Request,

			 Merchant_Name AS `Merchant Name`,

			 Terminal_SN AS `Terminal Serial`,

			 Sim_SN AS `Sim Serial`,

			 `Status`,

			 Days,

			 CASE WHEN Dispatch_By IN ('',"-", NULL) THEN 'WAITING' ELSE Dispatch_By END AS `Dispatcher`,

			 CASE WHEN Dispatch_Date_Time IN ('',"-", NULL) THEN 'WAITING' ELSE Dispatch_Date_Time END AS `Dispatch Date`,

			 CASE WHEN `Status` = "PENDING" THEN 'WAITING' ELSE Service_Date END AS `Serviced Date`

		 FROM 

			 vw_monitoring_jobs

		 WHERE 

			 CASE 

				  WHEN Category = 'Request' THEN

						Request 		 = JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1'))

						AND `Status` = JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value2'))

				  ELSE

						Merchant_Name 		LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Job_ID 			LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Request_ID 		LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Terminal_SN 	LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR TID 				LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR `Status` 		LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Service_Status LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Request_No 		LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Sim_SN 			LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Request 			LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Model 			LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR `Type` 			LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Location 		LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

						OR Processed_By 	LIKE CONCAT('%', JSON_UNQUOTE(JSON_EXTRACT(p_SearchValue, '$.Value1')), '%')

			 END; -- CATEGORY END BLOCK --

					

		END CASE; -- SEARCHBY END BLOCK --



	END CASE;-- STATMENT END BLOCK  

			  

	END */$$
DELIMITER ;

