/* Procedure structure for procedure `spUpdateBulkCollectionDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spUpdateBulkCollectionDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spUpdateBulkCollectionDetail`(
    IN p_StatementType VARCHAR(100),
    IN p_SearchBy VARCHAR(100),
    IN p_SearchValue LONGTEXT
)
BEGIN  
DECLARE v_ID INTEGER;
DECLARE v_ClientID INTEGER;
DECLARE v_ServiceNo INTEGER;
DECLARE v_LocationID INTEGER;
DECLARE v_TerminalID INTEGER;
DECLARE v_SIMID INTEGER;
DECLARE v_SerialNo VARCHAR(45);
DECLARE v_Location VARCHAR(45);
DECLARE v_ReleaseDate DATE;
