			SET v_UpdateAt = TRIM(SPLIT_STRING(p_Parse, '~' ,7)); 
			SET v_Remarks = TRIM(SPLIT_STRING(p_Parse, '~' ,8));
			SET @ReleaseDate = TRIM(SPLIT_STRING(p_Parse, '~' ,9));			
			SET @TransNo = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,10)) AS UNSIGNED INTEGER);
			SET @MovementType = TRIM(SPLIT_STRING(p_Parse, '~' ,11));
			
			# Update
			IF (v_TerminalID > 0) THEN
				UPDATE tblterminaldetail
				SET
				TerminalStatus = v_StatusID,
				TerminalStatusDescription = v_Status,
				LocationID = v_LocationID,
				Location = v_Location,
				UpdatedID = v_UpdateID,
				UpdatedAt = v_UpdateAt,
				Remarks = v_Remarks,
				ReleaseDate = @ReleaseDate,
				PONo = @PONo,
				PartNo = @PartNo,
				TIID = @TransNo,
				MovementType = @MovementType
				WHERE TerminalID = v_TerminalID;
			END IF;
			
		END IF;
		
		END LOOP GET_RECORD;
		
	ELSEIF (p_SearchBy = 'Multiple SIM Detail')
	THEN				
		SET v_TLoop = CAST(TRIM(SPLIT_STRING(p_SearchValue, '^' ,1)) AS UNSIGNED INTEGER); # Total Count Iteration
		#SELECT (CONCAT("v_TLoop=", v_TLoop));
		SET p_String = TRIM(SPLIT_STRING(p_SearchValue, '^' ,2));
		#SELECT (CONCAT("p_String=", p_String));
		
		GET_RECORD: LOOP
		
		SET v_Counter = v_Counter + 1;
		IF v_Counter > v_TLoop 
		THEN		 
			LEAVE GET_RECORD;			
		ELSE

			# Parse		
			SET p_Parse = TRIM(SPLIT_STRING(p_String, '|' ,v_Counter));
			#SELECT (CONCAT("p_Parse=", p_Parse));
			
			SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,1)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,2)) AS UNSIGNED INTEGER);
			SET v_Status = funcGetDesc("Search", "SIM Status", v_StatusID);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,4)) AS UNSIGNED INTEGER);
			SET v_Location = funcGetDesc("Search", "Location", v_LocationID); 
			SET v_UpdateID = TRIM(SPLIT_STRING(p_Parse, '~' ,6)); 
			SET v_UpdateAt = TRIM(SPLIT_STRING(p_Parse, '~' ,7)); 
			SET v_Remarks = TRIM(SPLIT_STRING(p_Parse, '~' ,8));	
			SET @ReleaseDate = TRIM(SPLIT_STRING(p_Parse, '~' ,9));		
			SET @TransNo = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,10)) AS UNSIGNED INTEGER);
			SET @MovementType = TRIM(SPLIT_STRING(p_Parse, '~' ,11));
			
			# Update
			IF (v_SIMID > 0) THEN
				UPDATE tblsimdetail
				SET
				SIMStatus = v_StatusID,
				SIMStatusDescription = v_Status,
				LocationID = v_LocationID,
				Location = v_Location,
				UpdatedID = v_UpdateID,
				UpdatedAt = v_UpdateAt,
				Remarks = v_Remarks,
				ReleaseDate = @ReleaseDate,
				SIID = @TransNo,
				MovementType = @MovementType
				WHERE SIMID = v_SIMID;
			END IF;
			
		END IF;
		
		END LOOP GET_RECORD;
	
	ELSEIF (p_SearchBy = 'Multiple Terminal SN Detail')
	THEN				
		SET v_TLoop = CAST(TRIM(SPLIT_STRING(p_SearchValue, '^' ,1)) AS UNSIGNED INTEGER); # Total Count Iteration
		#SELECT (CONCAT("v_TLoop=", v_TLoop));
		SET p_String = TRIM(SPLIT_STRING(p_SearchValue, '^' ,2));
		#SELECT (CONCAT("p_String=", p_String));
		
		GET_RECORD: LOOP
		
		SET v_Counter = v_Counter + 1;
		IF v_Counter > v_TLoop 
		THEN		 
			LEAVE GET_RECORD;			
		ELSE

			# Parse		
			SET p_Parse = TRIM(SPLIT_STRING(p_String, '|' ,v_Counter));
			#SELECT (CONCAT("p_Parse=", p_Parse));
			
			SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,1)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,2)) AS UNSIGNED INTEGER);
			SET v_Status = funcGetDesc("Search", "Terminal Status", v_StatusID);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,4)) AS UNSIGNED INTEGER);
			SET v_Location = funcGetDesc("Search", "Location", v_LocationID); 
			SET v_UpdateID = TRIM(SPLIT_STRING(p_Parse, '~' ,6)); 
			SET v_UpdateAt = TRIM(SPLIT_STRING(p_Parse, '~' ,7)); 
			SET v_Remarks = TRIM(SPLIT_STRING(p_Parse, '~' ,8)); 
			
			
			# Update
			SET p_SQL = CONCAT(v_TerminalID, "|", v_StatusID, "|", v_Status, "|", v_LocationID, "|", v_Location, "|", v_UpdateID, "|", v_UpdateAt, "|", v_Remarks);
