			CALL spUpdateCollectionDetail(p_StatementType, p_SearchBy, p_SQL); # Stored Procedure Call
		END IF;
		
		END LOOP GET_RECORD;	
		
	ELSEIF (p_SearchBy = 'Multiple SIM SN Detail')
	THEN				
		SET v_TLoop = CAST(TRIM(SPLIT_STRING(p_SearchValue, '^' ,1)) AS UNSIGNED INTEGER); # Total Count Iteration
		#SELECT (CONCAT("v_TLoop=", v_TLoop));
		SET p_String = TRIM(SPLIT_STRING(p_SearchValue, '^' ,2));
		#SELECT (CONCAT("p_String=", p_String));
		
		GET_RECORD: LOOP
		
		SET v_Counter = v_Counter + 1;
		IF v_Counter > v_TLoop 
		THEN		 
			LEAVE GET_RECORD;			
		ELSE

			# Parse		
			SET p_Parse = TRIM(SPLIT_STRING(p_String, '|' ,v_Counter));
