			SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,1)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,2)) AS UNSIGNED INTEGER);
			SET v_Status = funcGetDesc("Search", "SIM Status", v_StatusID);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,4)) AS UNSIGNED INTEGER);
