			SET v_Remarks = TRIM(SPLIT_STRING(p_Parse, '~' ,8)); 
			
			
			# Update
			SET p_SQL = CONCAT(v_SIMID, "|", v_StatusID, "|", v_Status, "|", v_LocationID, "|", v_Location, "|", v_UpdateID, "|", v_UpdateAt, "|", v_Remarks);
			#SELECT (CONCAT("p_SQL=", p_SQL));
			
			CALL spUpdateCollectionDetail(p_StatementType, p_SearchBy, p_SQL); # Stored Procedure Call
		END IF;
		
