	ELSEIF (p_SearchBy = 'Service Changes Detail')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		SET @p_outCount = 0;
		CALL spCheckRecordExist("Search","Dynamic Search", CONCAT("tblservicechangesdetail|ServiceNo|",v_ServiceNo),@p_outCount);
		
		if (@p_outCount > 0) THEN
			WHILE EXISTS(SELECT a.ID FROM tblservicechangesdetail a WHERE a.isPosted = 0 AND a.ServiceNo = v_ServiceNo)

			DO

				SELECT
					a.ID,
					CASE
						WHEN b.TableName = 'tblirdetail' THEN 
						    CASE 
							WHEN b.FieldName = 'rawdata_info' AND b.FieldNestedObj = 'Values' THEN
							    CONCAT(
								'UPDATE ', b.TableName, 
								' SET `', b.FieldName, '` = JSON_SET(`', b.FieldName, '`, ''$."', b.FieldNestedObj, '"."', b.FieldKeyValue, '"'', ''', a.ChangeTo, ''')',                                       
								' WHERE ', b.FieldSearchKey, ' = ', a.IRIDNo, ';'
							    )
							WHEN b.FieldName = 'profile_info' AND b.FieldNestedObj = '' THEN
							    CONCAT(
								'UPDATE ', b.TableName, 
								' SET `', b.FieldName, '` = JSON_SET(`', b.FieldName, '`, ''$."', b.FieldKeyValue, '"'', ''', a.ChangeTo, ''')',                                       
								' WHERE ', b.FieldSearchKey, ' = ', a.IRIDNo, ';'
							    )
							ELSE 
							    CONCAT(
								'UPDATE ', b.TableName, 
								' SET `', b.FieldName, '` = ''', a.ChangeTo, '''',                                              
								' WHERE ', b.FieldSearchKey, ' = ', a.IRIDNo, ';'
							    )
						    END
						WHEN b.TableName = 'tblparticular' THEN
						    CASE 
							WHEN b.FieldName = 'profile_config_info' AND b.FieldNestedObj = 'Values' THEN
							    CONCAT(
								'UPDATE ', b.TableName, 
								' SET `', b.FieldName, '` = JSON_SET(`', b.FieldName, '`, ''$."', b.FieldNestedObj, '"."', b.FieldKeyValue, '"'', ''', a.ChangeTo, ''')',                                  
								' WHERE ', b.FieldSearchKey, ' = ', a.MerchantID, ';'
							    )
							ELSE 
							    CONCAT(
								'UPDATE ', b.TableName, 
								' SET `', b.FieldName, '` = ''', a.ChangeTo, '''',                                             
								' WHERE ', b.FieldSearchKey, ' = ', a.MerchantID, ';'
							    )
						    END
					    END INTO v_ID, var_sql_statement
				FROM 
				tblservicechangesdetail a
				LEFT JOIN tblmapping AS b ON a.MapID = b.MapID
				WHERE
				a.isPosted = 0 AND a.ServiceNo = v_ServiceNo
				LIMIT 1;
				
				IF (v_ID IS NOT NULL && LENGTH(var_sql_statement) > 0) then
				
					SET @QUERY = var_sql_statement;
					
					# Execute Query
					PREPARE QUERY FROM @QUERY;
					EXECUTE QUERY;
					UPDATE tblservicechangesdetail SET isPosted = 1 WHERE ID = v_ID AND ServiceNo = v_ServiceNo;
					#SELECT CONCAT("v_ID=", v_ID, "|", "var_sql_statement=", var_sql_statement);
				end if;
				
			END WHILE;
		END IF;

		
		
	ELSEIF (p_SearchBy = 'Multiple Stock Movement Detail')
	THEN				
		SET v_TLoop = CAST(TRIM(SPLIT_STRING(p_SearchValue, '^' ,1)) AS UNSIGNED INTEGER); # Total Count Iteration
		#SELECT (CONCAT("v_TLoop=", v_TLoop));
		SET p_String = TRIM(SPLIT_STRING(p_SearchValue, '^' ,2));
		#SELECT (CONCAT("p_String=", p_String));
		
		GET_RECORD: LOOP
		
		SET v_Counter = v_Counter + 1;
		IF v_Counter > v_TLoop 
		THEN		 
			LEAVE GET_RECORD;			
		ELSE

			# Parse		
			SET p_Parse = TRIM(SPLIT_STRING(p_String, '|' ,v_Counter));
			#SELECT (CONCAT("p_Parse=", p_Parse));
			
			SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,1)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,2)) AS UNSIGNED INTEGER);
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,3)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_Parse, '~' ,4)) AS UNSIGNED INTEGER);
			SET v_UpdateID = TRIM(SPLIT_STRING(p_Parse, '~' ,5)); 
			SET v_UpdateAt = TRIM(SPLIT_STRING(p_Parse, '~' ,6)); 
			SET v_Remarks = TRIM(SPLIT_STRING(p_Parse, '~' ,7)); 
			
			
			# Update
			SET p_SQL = CONCAT(v_TerminalID, "|", v_StatusID, "|", v_ClientID, "|", v_LocationID, "|", v_UpdateID, "|", v_UpdateAt, "|", v_Remarks);
			#SELECT (CONCAT("p_SQL=", p_SQL));
			
			CALL spUpdateCollectionDetail(p_StatementType, p_SearchBy, p_SQL); # Stored Procedure Call
		END IF;
		
		END LOOP GET_RECORD;
						
	END IF;				
	
END IF; 

COMMIT; 
       
END */$$
DELIMITER ;

