DECLARE v_FSRTime VARCHAR(255);
DECLARE v_TimeEnd VARCHAR(255);
DECLARE v_Attempt INTEGER;

DECLARE v_Serviced INTEGER;

#Rocky - Location Hold
DECLARE v_TerminalLocation VARCHAR(255);
DECLARE v_SimLocation VARCHAR(255);
DECLARE v_RepTerminalLocation VARCHAR(255);
DECLARE v_RepSimLocation VARCHAR(255);
DECLARE v_ServiceTypeStatus INTEGER;
DECLARE v_ServiceTypeStatusDescription VARCHAR(255);
DECLARE v_ID INTEGER;
DECLARE v_TableName VARCHAR(255);

DECLARE v_TimeSheetID INTEGER;
DECLARE v_MobileTerminalID VARCHAR(255);
DECLARE v_ComputerName VARCHAR(255);
DECLARE v_Device VARCHAR(255);

#User
DECLARE v_FullName VARCHAR(255);
DECLARE v_UserName VARCHAR(255);
DECLARE v_Password VARCHAR(255);
DECLARE v_UserType VARCHAR(255);
DECLARE v_MD5Password VARCHAR(255);
DECLARE v_LocationID INTEGER;
DECLARE v_Value VARCHAR(255);
DECLARE v_Info LONGTEXT;

DECLARE v_DispatchID INTEGER;
DECLARE v_Dispatcher VARCHAR(255);

DECLARE v_DataInfo LONGTEXT;

DECLARE v_Date VARCHAR(45);

#Helpdesk
DECLARE v_AssistNo INTEGER;
DECLARE v_ProblemNo INTEGER;

DECLARE v_ModeType VARCHAR(255);

DECLARE v_ServiceNos JSON;

DECLARE p_WHERE LONGTEXT;
DECLARE p_ORDERBY LONGTEXT;
DECLARE p_SQL LONGTEXT;

START TRANSACTION;

IF (p_StatementType = 'Update') 
THEN  		

	IF (p_SearchBy = 'SIM Detail') 
	THEN
		# Split SearchValue
		#SELECT (CONCAT('p_SearchValue=', p_SearchValue));
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_BatchNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET v_SIMSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET v_Carrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
		SET v_AssignedTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		SET v_Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
		SET v_DeliveryDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));
		SET v_ReceiveDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
		SET v_SIMStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);
		SET v_SIMStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11));

		IF (LENGTH(v_SIMID) > 0)
		THEN
			UPDATE tblsimdetail
			SET
			FEID = v_FEID,
			BatchNo = v_BatchNo,
			SerialNo = v_SIMSerialNo,
			Carrier = v_Carrier,
			AssignedTo = v_AssignedTo,
			Remarks = v_Remarks,
			DeliveryDate = v_DeliveryDate,
			ReceiveDate = v_ReceiveDate,
			SIMStatus = v_SIMStatus,
			SIMStatusDescription = v_SIMStatusDescription,
			Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)),
			Allocation = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)),
			ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)) AS UNSIGNED INTEGER),
			LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)) AS UNSIGNED INTEGER),
			isActive = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)) AS UNSIGNED INTEGER),
			CarrierID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER),
			ReleaseDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)),
			ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19)),
			ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,20)) AS UNSIGNED INTEGER),
			UpdatedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,21)) AS UNSIGNED INTEGER),
			UpdatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,22))
			WHERE (SIMID = v_SIMID);

			IF (v_SIMStatus = 1) # AVAILABLE
			THEN
				UPDATE tblsimdetail
				SET
				LastServiceNo = 0,
				LastIRIDNo = 0
				WHERE (SIMID = v_SIMID);
			END IF;					
		END IF;

	ELSEIF (p_SearchBy = 'Released SIM Detail')
	THEN			
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		IF (LENGTH(v_SIMID) > 0)
		THEN
			UPDATE tblsimdetail
			SET			
			Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)),
			ReleaseDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),
			ReleasedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),
			ReleasedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
			Remarks =  TRIM(SPLIT_STRING(p_SearchValue, '|' ,6))
			WHERE (SIMID = v_SIMID);
		END IF;		

	ELSEIF (p_SearchBy = 'Terminal Detail')
	THEN			
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_TIID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));		
		SET v_Type = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET v_Model = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
		SET v_Brand = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		SET v_DeliveryDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
		SET v_ReceiveDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));
		SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)) AS UNSIGNED INTEGER);
		SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);
		SET v_TerminalBrandID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)) AS UNSIGNED INTEGER);
		SET v_PartNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));
		SET v_PONo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13));
		SET v_InvNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));
		SET v_Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15));
		SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16));
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER);		
		SET v_TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)) AS UNSIGNED INTEGER);
		SET v_TerminalStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19));

		IF (LENGTH(v_TerminalID) > 0)

		THEN
			UPDATE tblterminaldetail
			SET
			TIID = v_TIID, 
			SerialNo = v_TerminalSN, 
			`Type` = v_Type, 
			Model = v_Model, 
			Brand = v_Brand, 
			DeliveryDate = v_DeliveryDate, 
			ReceiveDate = v_ReceiveDate, 
			TerminalTypeID = v_TerminalTypeID, 
			TerminalModelID = v_TerminalModelID, 
			TerminalBrandID = v_TerminalBrandID, 
			PartNo = v_PartNo, 
			PONo = v_PONo, 
			InvNo = v_InvNo, 
			Remarks = v_Remarks, 
			ClientName = v_ClientName, 
			ClientID = v_ClientID, 
			TerminalStatusDescription = v_TerminalStatusDescription, 
			TerminalStatus = v_TerminalStatus,
			Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20)),
			Allocation = TRIM(SPLIT_STRING(p_SearchValue, '|' ,21)),
			AssetType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,22)),
			ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,23)) AS UNSIGNED INTEGER),
			LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,24)) AS UNSIGNED INTEGER),
			isActive = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,25)) AS UNSIGNED INTEGER),
			ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,26)) AS UNSIGNED INTEGER),
			ReleaseDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,27)),
			UpdatedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,28)) AS UNSIGNED INTEGER),
			UpdatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,29))
			WHERE (TerminalID = v_TerminalID);
			
			IF (v_TerminalStatus = 1) # AVAILABLE
			THEN
				UPDATE tblterminaldetail
				SET
				LastServiceNo = 0,
				LastIRIDNo = 0
				WHERE (TerminalID = v_TerminalID);
			END IF;
		END IF;	

	ELSEIF (p_SearchBy = 'Released Terminal Detail')
	THEN			
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		IF (LENGTH(v_TerminalID) > 0)
		THEN
			UPDATE tblterminaldetail
			SET			
			LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER),
			Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),
			ReleaseDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),
			ReleasedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
			ReleasedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)),
			Remarks =  TRIM(SPLIT_STRING(p_SearchValue, '|' ,7))
			WHERE (TerminalID = v_TerminalID);
		END IF;	

	ELSEIF (p_SearchBy = 'Released SIM Detail')
	THEN			
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		IF (LENGTH(v_SIMID) > 0)
		THEN
			UPDATE tblsimdetail
			SET			
			LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER),
			Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),
			ReleaseDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),
			ReleasedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
			ReleasedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)),
			Remarks =  TRIM(SPLIT_STRING(p_SearchValue, '|' ,7))
			WHERE (SIMID = v_SIMID);
		END IF;		

	ELSEIF (p_SearchBy = 'TA Detail')
	THEN
		# Split SearchValue
		#SELECT (CONCAT('p_SearchValue=', p_SearchValue));
		SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_ServiceProviderID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
		SET v_IRID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
		SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
		SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);
		SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)) AS UNSIGNED INTEGER);
		SET v_TerminalBrandID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)) AS UNSIGNED INTEGER);
		SET v_ServiceTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)) AS UNSIGNED INTEGER);
		SET v_OtherServiceTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)) AS UNSIGNED INTEGER);
		SET v_TADateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15));
		SET v_ProcessedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16));
		SET v_ModifiedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,17));
		SET v_ProcessedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18));
		SET v_ModifiedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19));
		SET v_Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20));
		SET v_Comments = TRIM(SPLIT_STRING(p_SearchValue, '|' ,21));
		SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,22));
		SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,23));
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,24)) AS UNSIGNED INTEGER);
		SET v_SIMSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,25));
		SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,26)) AS UNSIGNED INTEGER);
		SET v_Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,27));
		SET v_DockID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,28)) AS UNSIGNED INTEGER);
		SET v_DockSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,29));

		IF (LENGTH(v_TAIDNo) > 0)
		THEN
			UPDATE tblterminalallocation
			SET
			ClientID = v_ClientID,
			ServiceProviderID = v_ServiceProviderID,
			FEID = v_FEID,
			IRID = v_IRID,
			IRNo = v_IRNo,
			MerchantID = v_MerchantID,
			TerminalID = v_TerminalID,
			TerminalSN = v_TerminalSN,
			TerminalTypeID = v_TerminalTypeID,
			TerminalModelID = v_TerminalModelID,
			TerminalBrandID = v_TerminalBrandID,
			ServiceTypeID = v_ServiceTypeID,
			OtherServiceTypeID = v_OtherServiceTypeID,
			TADateTime = v_TADateTime,
			ProcessedBy = v_ProcessedBy,
			ModifiedBy = v_ModifiedBy,
			ProcessedDateTime = v_ProcessedDateTime,
			ModifiedDateTime = v_ModifiedDateTime,
			Remarks = v_Remarks,
			Comments = v_Comments,
			TID = v_TID,
			`MID` = v_MID,
			SIMID = v_SIMID,
			SIMSerialNo = v_SIMSerialNo,
			RegionID = v_RegionID,
			Region = v_Region,
			DockID = v_DockID,
			DockSN = v_DockSN
			WHERE (TAIDNo = v_TAIDNo);
		END IF;	
	
	ELSEIF (p_SearchBy = 'Reason')
	THEN
		SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ReasonCode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_ReasonDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET v_ReasonType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

		IF (LENGTH(v_ReasonID) > 0)
		THEN
			UPDATE tblreason
			SET `Code` = v_ReasonCode,
			Description = v_ReasonDescription,
			`Type` = v_ReasonType
			WHERE (ReasonID = v_ReasonID);
		END IF;
	
	ELSEIF (p_SearchBy = 'Region Detail')
	THEN
		SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);		
		SET v_Province = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		IF (LENGTH(v_RegionID) > 0)
		THEN
			UPDATE tblregiondetail
			SET RegionType = v_RegionType,
		            Province = v_Province
			WHERE (RegionID = v_RegionID);
		END IF;	

	ELSEIF (p_SearchBy = 'Region')
	THEN
		SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));		

		IF (LENGTH(v_RegionID) > 0)
		THEN
			UPDATE tblregion
			SET Region = v_Region			
			WHERE (RegionID = v_RegionID);
		END IF;	

	ELSEIF (p_SearchBy = 'Particular')
	THEN
		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));		
		SET v_Address = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));		
		SET v_Address2 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));		
		SET v_Address3 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));		
		SET v_Address4 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));		
		SET v_ProvinceID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_CityID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
		SET v_ParticularTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)) AS UNSIGNED INTEGER);
		SET v_ParticularDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,10));		
		SET v_ContactPerson = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11));		
		SET v_TelNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));		
		SET v_Mobile = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13));		
		SET v_Fax = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));		
		SET v_Email = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15));		
		SET v_ContractTerms = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16));		
		SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER); 
		SET v_Province = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18));		
		SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,19)) AS UNSIGNED INTEGER); 
		SET v_Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20));
		SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,21)) AS UNSIGNED INTEGER); 
		SET v_PositionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,22)) AS UNSIGNED INTEGER); 
		SET v_EmploymentStatus = TRIM(SPLIT_STRING(p_SearchValue, '|' ,23));
		SET v_Code = TRIM(SPLIT_STRING(p_SearchValue, '|' ,24));

		SET v_ComputerName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,25));	
		SET v_isActive = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,26)) AS UNSIGNED INTEGER);
		SET v_isWorkArrangement = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,27)) AS UNSIGNED INTEGER);
		SET v_isTimeSheet = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,28)) AS UNSIGNED INTEGER);
		SET v_isAppVersion = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,29)) AS UNSIGNED INTEGER);
		SET v_isAppVersion = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,29)) AS UNSIGNED INTEGER);

		SET v_RentalType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,30)) AS UNSIGNED INTEGER);
		SET v_RentalTerms = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,31)) AS UNSIGNED INTEGER);
		SET v_AccountNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,32));
		SET v_CustomerNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,33));

		#SELECT CONCAT('v_ParticularID = ', v_ParticularID);
		#SELECT CONCAT('v_Name = ', v_Name);
		#SELECT CONCAT('v_DepartmentID = ', v_DepartmentID);
		#SELECT CONCAT('v_PositionID = ', v_PositionID);
		#SELECT CONCAT('v_EmploymentStatus = ', v_EmploymentStatus);

		IF (LENGTH(v_ParticularID) > 0)
		THEN
			UPDATE tblparticular			
			SET 
			`Name` = v_Name, 
			Address = v_Address, 
			Address2 = v_Address2, 
			Address3 = v_Address3, 
			Address4 = v_Address4,
			ProvinceID = v_ProvinceID,
			CityID = v_CityID,
			ParticularTypeID = v_ParticularTypeID, 
			ParticularDescription = v_ParticularDescription, 
			ContactPerson = v_ContactPerson, 
			TelNo = v_TelNo, 
			Mobile = v_Mobile, 
			Fax = v_Fax, 
			Email = v_Email, 
			ContractTerms = v_ContractTerms, 
			RegionID = v_RegionID, 
			Province = v_Province, 
			RegionType = v_RegionType, 
			Region = v_Region,
			DepartmentID = v_DepartmentID,
			PositionID = v_PositionID,
			EmploymentStatus = v_EmploymentStatus,
			`Code` = v_Code,
			ComputerName = v_ComputerName,
			isActive = v_isActive,
			isWorkArrangement = v_isWorkArrangement,
			isTimeSheet = v_isTimeSheet,
			isAppVersion = v_isAppVersion,
			CountryID = v_CountryID,
			Country = v_Country,
			RentalType = v_RentalType,
			RentalTerms = v_RentalTerms,
			AccountNo = v_AccountNo,
			CustomerNo = v_CustomerNo,

			#Rocky - Additional Particular Info
			JobDescription 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,34)),
			OnBoardDate 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,35)),
			TINNo 			= TRIM(SPLIT_STRING(p_SearchValue, '|' ,36)),
			PhilhealthNo 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,37)),
			SSSNo 			= TRIM(SPLIT_STRING(p_SearchValue, '|' ,38)),
			HDMFNo 			= TRIM(SPLIT_STRING(p_SearchValue, '|' ,39)),
			EducLevel 		= TRIM(SPLIT_STRING(p_SearchValue, '|' ,40)),
			PresentID 		= TRIM(SPLIT_STRING(p_SearchValue, '|' ,41)),
			Gender 			= TRIM(SPLIT_STRING(p_SearchValue, '|' ,42)),
			ResignDate 		= TRIM(SPLIT_STRING(p_SearchValue, '|' ,43)),
			PresentIDNo 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,44)),
			AccountInfo 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,45)),
			BirthDate 		= TRIM(SPLIT_STRING(p_SearchValue, '|' ,46)),

			#Rocky - Employee Requirements
			NbiReq 		= TRIM(SPLIT_STRING(p_SearchValue, '|' ,47)),
			SchoolReq 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,48)),
			AppFormReq 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,49)),
			WaiverReq 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,50)),
			
			#Zoning
			ZoneID 	= TRIM(SPLIT_STRING(p_SearchValue, '|' ,51))

		
			WHERE (ParticularID = v_ParticularID);
		END IF;
	
