		SET v_StatusRepSIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,21)) AS UNSIGNED INTEGER);
		SET v_ServiceCode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,22));				
		SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,23));	
		SET v_AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|' ,24));
		SET v_AppCRC = TRIM(SPLIT_STRING(p_SearchValue, '|' ,25));
		SET v_isBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,26));
		SET v_CustomerName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,27));
		SET v_CustomerPosition = TRIM(SPLIT_STRING(p_SearchValue, '|' ,28));
		SET v_CustomerContactNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,29));
		SET v_Address = TRIM(SPLIT_STRING(p_SearchValue, '|' ,30));
		SET v_Attempt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,31));
		#Rocky - Replacement Success - but no service Happen - Issue Fix 

		SET v_Serviced = TRIM(SPLIT_STRING(p_SearchValue, '|' ,32));
		#Rocky - Location Update Enhancement
		SET v_TerminalLocation = TRIM(SPLIT_STRING(p_SearchValue, '|' ,33));
		SET v_SimLocation  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,34));

		SET v_RepTerminalLocation = TRIM(SPLIT_STRING(p_SearchValue, '|' ,35));
		SET v_RepSimLocation  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,36));

		SET v_CustomerEmail  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,37));
		
		#SELECT (CONCAT("v_JobTypeDescription=",v_JobTypeDescription));
		#SELECT (CONCAT("v_TerminalID=",v_TerminalID));
		#SELECT (CONCAT("v_StatusTerminalID=",v_StatusTerminalID));
		#SELECT (CONCAT("v_SIMID=",v_SIMID));
		#SELECT (CONCAT("v_StatusSIMID=",v_StatusSIMID));		
		#SELECT (CONCAT("v_RepTerminalID=",v_RepTerminalID));
		#SELECT (CONCAT("v_StatusRepTerminalID=",v_StatusRepTerminalID));
		#SELECT (CONCAT("v_RepSIMID=",v_RepSIMID));
		#SELECT (CONCAT("v_StatusRepSIMID=",v_StatusRepSIMID));
		#SELECT (CONCAT("v_Serviced=",v_Serviced));
		#SELECT (CONCAT("v_TerminalLocation=",v_TerminalLocation));
		#SELECT (CONCAT("v_SimLocation=",v_SimLocation));
		#SELECT (CONCAT("v_RepTerminalLocation=",v_RepTerminalLocation));
		#SELECT (CONCAT("v_RepSimLocation=",v_RepSimLocation));
		#SELECT (CONCAT("v_CustomerEmail=",v_CustomerEmail));
		#SELECT (CONCAT("v_FSRNo=",v_FSRNo));
		#SELECT (CONCAT("v_ServiceNo=",v_ServiceNo));
		#SELECT (CONCAT("v_IRIDNo=",v_IRIDNo));
		# Hold

		SET v_HoldTerminalID = v_TerminalID;
		SET v_HoldSIMID = v_SIMID;
		
		# tblservicingdetail always set to COMPLETED
		IF (v_ServiceNo > 0)

		then

			# tblservicingdetail to COMPLETE

			UPDATE tblservicingdetail

			SET

			JobTypeStatusDescription = "COMPLETED"			

			WHERE ServiceNo = v_ServiceNo;

			

			# tblfsrdetail (attempt)

			UPDATE tblfsrdetail

			SET

			Attempt = v_Attempt

			WHERE ServiceNo = v_ServiceNo;

		END IF;
		# tblfsrdetail		

		UPDATE tblfsrdetail

		SET 

		FEID = v_FEID,

		FEName = v_FEName,

		isBillable = v_isBillable 		

		WHERE ServiceNo = v_ServiceNo;
		# tblservicingdetail		

		UPDATE tblservicingdetail

		SET 	

		FEID = v_FEID,

		FEName = v_FEName,

		CustomerName = v_CustomerName,

		CustomerPosition = v_CustomerPosition,

		CustomerContactNo = v_CustomerContactNo,

		CustomerEmail = v_CustomerEmail,

		isBillable = v_isBillable 		

		WHERE ServiceNo = v_ServiceNo;
		# tblfsrdetail

		UPDATE tblfsrdetail

		SET

		MerchantRepresentative = v_CustomerName,

		MerchantRepresentativePosition = v_CustomerPosition,

		MerchantContactNo = v_CustomerContactNo,

		MerchantRepresentativeEmail = v_CustomerEmail

		WHERE ServiceNo = v_ServiceNo;

		

		# tblparticular
		/*
		UPDATE tblparticular

		SET

		ContactPerson = v_CustomerName,

		ContactPosition = v_CustomerPosition,

		ContactNumber = v_CustomerContactNo,

		TelNo = v_CustomerContactNo,

		Mobile = v_CustomerContactNo,

		Email = v_CustomerEmail

		WHERE

		ParticularID = v_MerchantID;
		*/
		

		IF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0 || 

			STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0 || 

			STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0)

		THEN

			UPDATE tblservicingdetail

			SET

			AppVersion = v_AppVersion,

			AppCRC = v_AppCRC

			WHERE 

			IRIDNo = v_IRIDNo;

		END IF;

		

		# ------------------------------------------------------------------------------

		# (IF) UPDATE STATUS  WITH CHECKING (ServiceNo and IRINo)

		# ------------------------------------------------------------------------------

		IF (v_ServiceNo > 0 && v_IRIDNo > 0)

		THEN

			# ==============================================================================

			# success

			# ==============================================================================

			IF (STRCMP(v_ActionMade, "SUCCESS") = 0)

			THEN				

				UPDATE tblservicingdetail

				SET

				ServiceStatus = 7,

				ServiceStatusDescription = 'INSTALLED'

				WHERE (ServiceNo = v_ServiceNo);
				UPDATE tblirdetail

				SET

				IRStatus = 7,

				IRStatusDescription = 'INSTALLED'

				WHERE (IRIDNo = v_IRIDNo);

		

				# Update tblirdetail AppVersion/AppCRC

				UPDATE tblirdetail

				SET

				AppVersion = v_AppVersion,

				AppCRC = v_AppCRC

				WHERE 

				IRIDNo = v_IRIDNo;
				IF (STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0)

				THEN

					UPDATE tblirdetail

					SET

					IRActive = 0,
					
					IRStatus = 11,

					IRStatusDescription = 'PULLED-OUT',

					TerminalID = 0,

					TerminalSN = '-',

					SIMID = 0,

					SIMSN = '-'

					WHERE (IRIDNo = v_IRIDNo);				
					UPDATE tblfsrdetail

					SET

					ServiceStatus = 11,

					ServiceStatusDescription = 'PULLED-OUT'

					WHERE (FSRNo = v_FSRNo);					
					UPDATE tblservicingdetail

					SET

					ServiceStatus = 11,

					ServiceStatusDescription = 'PULLED-OUT'

					WHERE (ServiceNo = v_ServiceNo);

					

					# ----------------------------------------------------

					# update client

					# ----------------------------------------------------

					UPDATE tblterminaldetail
					SET
					#ClientID = 0,
					#ClientName = '-',
					LastIRIDNo = 0
					WHERE
					TerminalID = v_TerminalID;

					

					UPDATE tblsimdetail
					SET
					#ClientID = 0,
					#ClientName = '-',
					LastIRIDNo = 0
					WHERE
					SIMID = v_SIMID;

					# ----------------------------------------------------

					# update client

					# ----------------------------------------------------

					

					# ------------------------------------------------------------------------------

					# Update current tblirdetail current SN

					# ------------------------------------------------------------------------------

					UPDATE tblirdetail

					SET

					TerminalID = 0,

					TerminalSN = '-'

					WHERE (IRIDNo = v_IRIDNo);

					

					UPDATE tblirdetail

					SET

					SIMID = 0,

					SIMSN = '-'

					WHERE (IRIDNo = v_IRIDNo);

					# ------------------------------------------------------------------------------

					# Update current tblirdetail current SN

					# ------------------------------------------------------------------------------

					

				ELSEIF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0)

				THEN

					# tblirdetail, Terminal

					CALL spGetInfoDetail("Search", "Terminal SN Info", v_TerminalID, @p_outResult);

					SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));

					UPDATE tblirdetail

					SET

					TerminalID = v_TerminalID,

					TerminalSN = v_TerminalSN

					WHERE 

					IRIDNo = v_IRIDNo;

					

					# tblirdetail, SIM

					CALL spGetInfoDetail("Search", "SIM SN Info", v_SIMID, @p_outResult);

					SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));			

					UPDATE tblirdetail

					SET

					SIMID = v_SIMID,

					SIMSN = v_SIMSN

					WHERE

					IRIDNo = v_IRIDNo;

				

					# tblterminaldetail
					UPDATE tblterminaldetail
					SET
					LocationID = funcGetID("Search", "Location", v_TerminalLocation),
					Location = v_TerminalLocation,
					TerminalStatus = v_StatusTerminalID,
					TerminalStatusDescription = funcGetDesc("Search", "Terminal Status", v_StatusTerminalID)
					#ClientID = v_ClientID,
					#ClientName = v_ClientName
					WHERE
					TerminalID = v_TerminalID;
					
					# tblsimdetail
					UPDATE tblsimdetail
					SET
					LocationID = funcGetID("Search", "Location", v_SimLocation),
					Location = v_SimLocation,
					SIMStatus = v_StatusSIMID,
					SIMStatusDescription = funcGetDesc("Search", "SIM Status", v_StatusSIMID)
					#ClientID = v_ClientID,
					#ClientName = v_ClientName
					WHERE
					SIMID = v_SIMID;

					# ----------------------------------------------------
					# update client
					# ----------------------------------------------------
					/*
					UPDATE tblterminaldetail
					SET
					ClientID = v_ClientID,
					ClientName = v_ClientName
					WHERE
					TerminalID = v_TerminalID;
					*/
					
					/*
					UPDATE tblsimdetail
					SET
					ClientID = v_ClientID,
					ClientName = v_ClientName
					WHERE
					SIMID = v_SIMID;
					*/

					# ----------------------------------------------------
					# update client
					# ----------------------------------------------------
					
					# ------------------------------------------------------------------------------

					# Update current tblirdetail current SN

					# ------------------------------------------------------------------------------

					IF (v_TerminalID > 0)

					THEN

						CALL spGetInfoDetail("Search", "Terminal SN Info", v_TerminalID, @p_outResult);

						SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));					
						UPDATE tblirdetail

						SET

						TerminalID = v_TerminalID,

						TerminalSN = v_TerminalSN

						WHERE (IRIDNo = v_IRIDNo);

					END IF;

					

					# tblirdetail, update SIMSN

					IF (v_SIMID > 0)

					THEN

						CALL spGetInfoDetail("Search", "SIM SN Info", v_SIMID, @p_outResult);

						SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));

			

						UPDATE tblirdetail

						SET

						SIMID = v_SIMID,

						SIMSN = v_SIMSN

						WHERE (IRIDNo = v_IRIDNo);

					END IF;

					# ------------------------------------------------------------------------------

					# Update current tblirdetail current SN

					# ------------------------------------------------------------------------------

					

				ELSEIF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)

				THEN

					# ----------------------------------------------------
					# update client
					# ----------------------------------------------------
					# current
					/*
					IF (v_TerminalID > 0)
					THEN
						UPDATE tblterminaldetail
						SET
						ClientID = v_ClientID,
						ClientName = v_ClientName
						WHERE
						TerminalID = v_TerminalID;
					END IF;					
					*/
					
					/*
					IF (v_SIMID > 0)
					then
						UPDATE tblsimdetail
						SET
						ClientID = v_ClientID,
						ClientName = v_ClientName
						WHERE
						SIMID = v_SIMID;
					END IF;
					*/
					
					# new
					/*
					if (v_RepTerminalID > 0)
					THEN
						UPDATE tblterminaldetail
						SET
						ClientID = v_ClientID,
						ClientName = v_ClientName
						WHERE
						TerminalID = v_RepTerminalID;
					END IF;
					*/
					
					/*
					IF (v_RepSIMID > 0)
					THEN
						UPDATE tblsimdetail
						SET
						ClientID = v_ClientID,
						ClientName = v_ClientName
						WHERE
						SIMID = v_RepSIMID;
					END IF;
					*/
					
					# ----------------------------------------------------
					# update client
					# ----------------------------------------------------

					
					# ------------------------------------------------------------------------------
					# Update current tblirdetail current SN
					# ------------------------------------------------------------------------------

					IF (v_TerminalID > 0)
					THEN
						CALL spGetInfoDetail("Search", "Terminal SN Info", v_TerminalID, @p_outResult);

						SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));	
										
						UPDATE tblirdetail
						SET
						TerminalID = v_TerminalID,
						TerminalSN = v_TerminalSN
						WHERE (IRIDNo = v_IRIDNo);

					END IF;
					
					# tblirdetail, update SIMSN
					IF (v_SIMID > 0)
					THEN
						CALL spGetInfoDetail("Search", "SIM SN Info", v_SIMID, @p_outResult);
						SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));

						UPDATE tblirdetail
						SET
						SIMID = v_SIMID,
						SIMSN = v_SIMSN
						WHERE (IRIDNo = v_IRIDNo);
					END IF;

					# ------------------------------------------------------------------------------
					# Update current tblirdetail current SN
					# ------------------------------------------------------------------------------

					# ------------------------------------------------------------------------------
					# Update current tblirdetail replace SN
					# ------------------------------------------------------------------------------
					IF (v_RepTerminalID > 0)
					THEN
						CALL spGetInfoDetail("Search", "Terminal SN Info", v_RepTerminalID, @p_outResult);
						SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));
											
						UPDATE tblirdetail
						SET
						TerminalID = v_RepTerminalID,
						TerminalSN = v_TerminalSN
						WHERE (IRIDNo = v_IRIDNo);
					END IF;

					

					# tblirdetail, update SIMSN
					IF (v_RepSIMID > 0)
					THEN
						CALL spGetInfoDetail("Search", "SIM SN Info", v_RepSIMID, @p_outResult);
						SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));

						UPDATE tblirdetail
						SET
						SIMID = v_RepSIMID,
						SIMSN = v_SIMSN
						WHERE (IRIDNo = v_IRIDNo);
					END IF;

					# ------------------------------------------------------------------------------
					# Update current tblirdetail replace SN
					# ------------------------------------------------------------------------------

				END IF;

			# ==============================================================================	

			# NEGATIVE	

			# ==============================================================================

			ELSEIF (STRCMP(v_ActionMade, "NEGATIVE") = 0)
			THEN

				IF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0)
				THEN
					# tblirdetail
					UPDATE tblirdetail
					SET
					IRStatus = 1,
					IRStatusDescription = 'AVAILABLE'
					WHERE (IRIDNo = v_IRIDNo);

					# tblservicingdetail
					UPDATE tblservicingdetail
					SET
					ServiceStatus = 1,
					ServiceStatusDescription = 'AVAILABLE'
					WHERE (ServiceNo = v_ServiceNo);

					# ------------------------------------------------------------------------------
					# Update current tblirdetail current SN
					# ------------------------------------------------------------------------------
					UPDATE tblirdetail
					SET
					TerminalID = 0,
					TerminalSN = '-'
					WHERE (IRIDNo = v_IRIDNo);
				
					UPDATE tblirdetail
					SET
					SIMID = 0,
					SIMSN = '-'
					WHERE (IRIDNo = v_IRIDNo);
				
				/*
				ELSEIF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)
				THEN

					# tblirdetail
					UPDATE tblirdetail
					SET
					IRStatus = 7,
					IRStatusDescription = 'INSTALLED'
					WHERE (IRIDNo = v_IRIDNo);
					
					# tblservicingdetail
					UPDATE tblservicingdetail
					SET
					ServiceStatus = 7,
					ServiceStatusDescription = 'INSTALLED'
					WHERE (ServiceNo = v_ServiceNo);

				ELSEIF (STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0)
				THEN
					
					# tblirdetail
					UPDATE tblirdetail
					SET
					IRStatus = 7,
					IRStatusDescription = 'INSTALLED'
					WHERE (IRIDNo = v_IRIDNo);
					
					# tblservicingdetail
					UPDATE tblservicingdetail
					SET
					ServiceStatus = 7,
					ServiceStatusDescription = 'INSTALLED'
					WHERE (ServiceNo = v_ServiceNo);
				*/
				ELSE
					#tblirdetail
					UPDATE tblirdetail
					SET
					IRStatus = 7,
					IRStatusDescription = 'INSTALLED'
					WHERE (IRIDNo = v_IRIDNo);
					
					# tblservicingdetail
					UPDATE tblservicingdetail
					SET
					ServiceStatus = 7,
					ServiceStatusDescription = 'INSTALLED'
					WHERE (ServiceNo = v_ServiceNo);										

				END IF;
		
				/*
				UPDATE tblservicingdetail
				SET
				ServiceStatus = 9,
				ServiceStatusDescription = 'NEGATIVE'
				WHERE (ServiceNo = v_ServiceNo);
				*/
					
			END IF;

		END IF;

		# ------------------------------------------------------------------------------

		# (END IF) UPDATE STATUS  WITH CHECKING (ServiceNo and IRINo)

		# ------------------------------------------------------------------------------

		

		#SELECT (CONCAT("v_JobTypeDescription=",v_JobTypeDescription));

		#SELECT (CONCAT("v_ServiceNo=",v_ServiceNo,",v_IRIDNo=", v_IRIDNo));

		#SELECT (CONCAT("v_TerminalLocation=",v_TerminalLocation,",v_SimLocation=", v_SimLocation));

		#SELECT (CONCAT("v_TerminalID=",v_TerminalID,",v_SIMID=", v_SIMID));

		#SELECT (CONCAT("v_RepTerminalLocation=",v_RepTerminalLocation,",v_RepSimLocation=", v_RepSimLocation));

		#SELECT (CONCAT("v_RepTerminalID=",v_RepTerminalID,",v_RepSIMID=", v_RepSIMID));

		

		# ------------------------------------------------------------------------------
		# (IF) UPDATE LOCATION
		# ------------------------------------------------------------------------------
		IF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0 ||
		    STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)
		THEN
			if (v_ServiceNo > 0 && v_IRIDNo > 0)
			THEN
				# Update tblterminal location, current
				IF (v_TerminalID > 0 && LENGTH(v_TerminalLocation) > 0 && (STRCMP(v_TerminalLocation, "[NOT SPECIFIED]") != 0) && (STRCMP(v_TerminalLocation, "-") != 0))
				THEN

					# Set location
					SET v_ID = funcGetID("Search", "Location", v_TerminalLocation);
					UPDATE tblterminaldetail 
					SET  						
					LocationID = v_ID,
					Location = v_TerminalLocation
					WHERE TerminalID = v_TerminalID;
				END IF;

				
				# Update tblsimdetail location, current
				IF (v_SIMID > 0 && LENGTH(v_SimLocation) > 0 && (STRCMP(v_SimLocation, "[NOT SPECIFIED]") != 0) && (STRCMP(v_SimLocation, "-") != 0))
				THEN
					# Set location
					SET v_ID = funcGetID("Search", "Location", v_SimLocation);
					UPDATE tblsimdetail 
					SET  						
					LocationID = v_ID,
					Location = v_SimLocation
					WHERE SIMID = v_SIMID;		
				END IF;

				

				# Update tblterminal location, replace
				IF (v_RepTerminalID > 0 && LENGTH(v_RepTerminalLocation) > 0 && (STRCMP(v_RepTerminalLocation, "[NOT SPECIFIED]") != 0) && (STRCMP(v_RepTerminalLocation, "-") != 0))
				THEN
					# Set location
					SET v_ID = funcGetID("Search", "Location", v_RepTerminalLocation);
					UPDATE tblterminaldetail 
					SET  						
					LocationID = v_ID,
					Location = v_RepTerminalLocation
					WHERE TerminalID = v_RepTerminalID;
				END IF;

				# Update tblsimdetail location, replace
				IF (v_RepSIMID > 0 && LENGTH(v_RepSimLocation) > 0 && (STRCMP(v_RepSimLocation, "[NOT SPECIFIED]") != 0) && (STRCMP(v_RepSimLocation, "-") != 0))
				THEN
					# Set location
					SET v_ID = funcGetID("Search", "Location", v_RepSimLocation);
					UPDATE tblsimdetail 
					SET  						
					LocationID = v_ID,
					Location = v_RepSimLocation
					WHERE SIMID = v_RepSIMID;
				END IF;
			END IF;

		END IF;	

		# ------------------------------------------------------------------------------

		# (END IF) UPDATE LOCATION

		# ------------------------------------------------------------------------------

		
		# ------------------------------------------------------------------------------

		# (IF) UPDATE LOCATION

		# ------------------------------------------------------------------------------					

		IF ((STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0) ||
		    (STRCMP(v_JobTypeDescription, "SVC REQ SERVICING") = 0) ||
		    (STRCMP(v_JobTypeDescription, "SVC REQ REPROGRAMMING")) = 0)
		THEN	

			# tblterminaldetail, current	
			IF (v_TerminalID > 0)	

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusTerminalID, @p_outResult);
				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));												
				UPDATE tblterminaldetail 
				SET  						
				TerminalStatus = v_Status,
				TerminalStatusDescription = v_Description
				WHERE TerminalID = v_TerminalID;				
				# tblfsrdetail

				UPDATE tblfsrdetail
				SET  							
				ServiceStatus = v_Status,
				ServiceStatusDescription = v_Description
				WHERE   FSRNo = v_FSRNo;
				
				# ------------------------------------------------------------------------------
				# Update for switch terminal SN
				# ------------------------------------------------------------------------------
				IF (v_PrevTerminalID > 0)
				THEN
					CALL spGetInfoDetail("Search", "Terminal SN Info", v_TerminalID, @p_outResult);

					SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));					
					CALL spGetInfoDetail("Search", "Terminal SN Info", v_PrevTerminalID, @p_outResult);

					SET v_RepTerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));					
					UPDATE tblterminaldetail 

					SET  						
					TerminalStatus = 1,
					TerminalStatusDescription = 'AVAILABLE'
					WHERE TerminalID = v_PrevTerminalID;										
					UPDATE tblservicingdetail 

					SET  						
					TerminalID = v_TerminalID,
					TerminalSN = v_TerminalSN,
					ReplaceTerminalID = v_PrevTerminalID,
					ReplaceTerminalSN = v_RepTerminalSN
					WHERE ServiceNo = v_ServiceNo;					

					UPDATE tblfsrdetail
					SET
					TerminalID = v_TerminalID,
					TerminalSN = v_TerminalSN
					WHERE ServiceNo = v_ServiceNo;														
				END IF;	

				# ------------------------------------------------------------------------------
				# Update for switch terminal SN
				# ------------------------------------------------------------------------------						
			END IF;		
				
			# tblsimdetail, current
			IF (v_SIMID > 0)
			THEN
				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusSIMID, @p_outResult);
				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));
				UPDATE tblsimdetail 
				SET  						
				SIMStatus = v_Status,
				SIMStatusDescription = v_Description
				WHERE SIMID = v_SIMID;
				
				# ------------------------------------------------------------------------------
				# Update for switch SIM SN
				# ------------------------------------------------------------------------------
				IF (v_PrevSIMID > 0)
				THEN
					CALL spGetInfoDetail("Search", "SIM SN Info", v_SIMID, @p_outResult);
					SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));
					
					CALL spGetInfoDetail("Search", "SIM SN Info", v_PrevSIMID, @p_outResult);
					SET v_RepSIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));	
									
					UPDATE tblsimdetail 
					SET  						
					SIMStatus = 1,
					SIMStatusDescription = 'AVAILABLE'
					WHERE SIMID = v_PrevSIMID;	
														
					UPDATE tblservicingdetail 
					SET  						
					SIMID = v_SIMID,
					SIMSerialNo = v_SIMSN,
					ReplaceSIMID = v_PrevSIMID,
					ReplaceSIMSN = v_RepSIMSN
					WHERE ServiceNo = v_ServiceNo;	
										
					UPDATE tblfsrdetail
					SET
					SIMID = v_SIMID,
					SIMSN = v_SIMSN
					WHERE ServiceNo = v_ServiceNo;										

				END IF;

				# ------------------------------------------------------------------------------

				# Update for switch SIM SN

				# ------------------------------------------------------------------------------

			ELSE
				CALL spGetInfoDetail("Search", "SIM SN Info", v_PrevSIMID, @p_outResult);

				SET v_RepSIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));				
				UPDATE tblsimdetail 

				SET  						

				SIMStatus = 1,

				SIMStatusDescription = 'AVAILABLE'

				WHERE SIMID = v_PrevSIMID;				
				UPDATE tblservicingdetail 

				SET  

				SIMID = 0,

				SIMSerialNo = "",						

				ReplaceSIMID = v_PrevSIMID,

				ReplaceSIMSN = v_RepSIMSN

				WHERE ServiceNo = v_ServiceNo;			
				UPDATE tblfsrdetail

				SET

				SIMID = 0,

				SIMSN = ""

				WHERE ServiceNo = v_ServiceNo;

			END IF;

		END IF;

		# ------------------------------------------------------------------------------

		# (END IF) UPDATE LOCATION

		# ------------------------------------------------------------------------------

		

		# ----------------------------------------------------------------------------------------

		# (IF) SVC REQ REPLACEMENT

		# ----------------------------------------------------------------------------------------

		IF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)

		THEN		

			SET v_TerminalID = v_HoldTerminalID;	

			SET v_SIMID = v_HoldSIMID;

				

			# tblterminaldetail, current

			IF (v_TerminalID > 0)	

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusTerminalID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));				
				UPDATE tblterminaldetail 

				SET  						

				TerminalStatus = v_Status,

				TerminalStatusDescription = v_Description

				#ClientID = 0,

				#ClientName = "-"

				WHERE TerminalID = v_TerminalID;

			END IF;
		

			# tblsimdetail, current

			IF (v_SIMID > 0)

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusSIMID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));
				UPDATE tblsimdetail 

				SET  						

				SIMStatus = v_Status,

				SIMStatusDescription = v_Description

				#ClientID = 0,

				#ClientName = "-"

				WHERE SIMID = v_SIMID;				

			END IF;

	

			# tblterminaldetail, replace	

			IF (v_RepTerminalID > 0)	

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusRepTerminalID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));
				UPDATE tblterminaldetail 

				SET  						

				TerminalStatus = v_Status,

				TerminalStatusDescription = v_Description

				WHERE TerminalID = v_RepTerminalID;

			

				# tblfsrdetail

				UPDATE tblfsrdetail

				SET  							

				ServiceStatus = v_Status,

				ServiceStatusDescription = v_Description		

				WHERE   FSRNo = v_FSRNo;
		

				# Update tblterminaldetail for switch SN

				IF (v_PrevTerminalID > 0)

				THEN

					CALL spGetInfoDetail("Search", "Terminal SN Info", v_TerminalID, @p_outResult);

					SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));
					CALL spGetInfoDetail("Search", "Terminal SN Info", v_RepTerminalID, @p_outResult);

					SET v_RepTerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));
					UPDATE tblterminaldetail 

					SET  						

					TerminalStatus = 1,

					TerminalStatusDescription = 'AVAILABLE'

					WHERE TerminalID = v_PrevTerminalID;										
					UPDATE tblservicingdetail 

					SET  						

					TerminalID = v_TerminalID,

					TerminalSN = v_TerminalSN,

					ReplaceTerminalID = v_RepTerminalID,

					ReplaceTerminalSN = v_RepTerminalSN

					WHERE ServiceNo = v_ServiceNo;	

					

					UPDATE tblfsrdetail

					SET

					TerminalID = v_RepTerminalID,

					TerminalSN = v_RepTerminalSN

					WHERE ServiceNo = v_ServiceNo;						
				END IF;
			END IF;

			

			# tblsimdetail, replace

			IF (v_RepSIMID > 0)

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusRepSIMID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));

				

				UPDATE tblsimdetail 

				SET  						

				SIMStatus = v_Status,

				SIMStatusDescription = v_Description

				WHERE SIMID = v_RepSIMID;

			

				# Update tblsimdetail for switch SN

				IF (v_PrevSIMID > 0)

				THEN

					CALL spGetInfoDetail("Search", "SIM SN Info", v_SIMID, @p_outResult);

					SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));
					CALL spGetInfoDetail("Search", "SIM SN Info", v_RepSIMID, @p_outResult);

					SET v_RepSIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));
					UPDATE tblsimdetail 

					SET  						

					SIMStatus = 1,

					SIMStatusDescription = 'AVAILABLE'

					WHERE SIMID = v_PrevSIMID;					
					UPDATE tblservicingdetail 

					SET  						

					SIMID = v_SIMID,

					SIMSerialNo = v_SIMSN,

					ReplaceSIMID = v_RepSIMID,

					ReplaceSIMSN = v_RepSIMSN

					WHERE ServiceNo = v_ServiceNo;	

					

					UPDATE tblfsrdetail

					SET

					SIMID = v_RepSIMID,

					SIMSN = v_RepSIMSN

					WHERE ServiceNo = v_ServiceNo;						

															

				END IF;

			END IF;

		END IF;

		# ----------------------------------------------------------------------------------------

		# (IF) SVC REQ PULL-OUT

		# ----------------------------------------------------------------------------------------

		

		# ----------------------------------------------------------------------------------------

		# (IF) SVC REQ PULL-OUT

		# ----------------------------------------------------------------------------------------

		IF (STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0)

		THEN						

			# tblterminaldetail, currrent	

			IF (v_TerminalID > 0)	

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusTerminalID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));
				UPDATE tblterminaldetail 

				SET  						

				TerminalStatus = v_Status,

				TerminalStatusDescription = v_Description

				WHERE TerminalID = v_TerminalID;

				

				# Set location

				SET v_ID = funcGetID("Search", "Location", v_TerminalLocation);

				UPDATE tblterminaldetail 

				SET  						

				LocationID = v_ID,

				Location = v_TerminalLocation

				WHERE TerminalID = v_TerminalID;
			END IF;		
			# tblsimdetail, current

			IF (v_SIMID > 0)

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusSIMID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));				
				UPDATE tblsimdetail 

				SET  						

				SIMStatus = v_Status,

				SIMStatusDescription = v_Description

				WHERE SIMID = v_SIMID;

				

				# Set location

				SET v_ID = funcGetID("Search", "Location", v_SimLocation);

				UPDATE tblsimdetail 

				SET  						

				LocationID = v_ID,

				Location = v_SimLocation

				WHERE SIMID = v_SIMID;

				

			END IF;

			

			# tblfsrdetail

			IF (v_FSRNo > 0)

			then

				UPDATE tblfsrdetail

				SET  							

				ServiceStatus = v_Status,

				ServiceStatusDescription = v_Description		

				WHERE   FSRNo = v_FSRNo;

			END IF;

		END IF;

		# ----------------------------------------------------------------------------------------

		# (END IF) SVC REQ PULL-OUT

		# ----------------------------------------------------------------------------------------

		

		# ------------------------------------------------------------------------------

		# (IF) UPDATE LAST CONTROL NO

		# ------------------------------------------------------------------------------		

		IF (STRCMP(v_ActionMade, "SUCCESS") = 0)

		THEN

			IF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0 ||

			    STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0)

			THEN

				# current terminal

				IF (v_TerminalID > 0 && v_StatusTerminalID != 7) #7 = INSTALLED

				THEN

					UPDATE tblterminaldetail

					SET

					LastServiceNo = 0,

					LastIRIDNo = 0

					#ClientID = 0,

					#ClientName = 0

					WHERE

					TerminalID = v_TerminalID;

				END IF;

				

				# current sim

				IF (v_SIMID > 0 && v_StatusSIMID != 7) #7 = INSTALLED

				THEN

					UPDATE tblsimdetail

					SET

					LastServiceNo = 0,

					LastIRIDNo = 0

					#ClientID = 0,

					#ClientName = 0

					WHERE

					SIMID = v_SIMID;

				END IF;

			END IF;

			

			IF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)

			THEN

				IF (v_RepTerminalID > 0)

				THEN

					UPDATE tblterminaldetail

					SET

					LastServiceNo = v_ServiceNo,

					LastIRIDNo = v_IRIDNo

					WHERE

					TerminalID = v_RepTerminalID;

				END IF;

				

				IF (v_RepSIMID > 0)

				THEN

					UPDATE tblsimdetail

					SET

					LastServiceNo = v_ServiceNo,

					LastIRIDNo = v_IRIDNo

					WHERE

					SIMID = v_RepSIMID;

				END IF;

			END IF;

			

			IF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0)

			THEN

				IF (v_TerminalID > 0)

				THEN

					UPDATE tblterminaldetail

					SET

					LastServiceNo = v_ServiceNo,

					LastIRIDNo = v_IRIDNo

					WHERE

					TerminalID = v_TerminalID;

				END IF;

				

				IF (v_SIMID > 0)

				THEN

					UPDATE tblsimdetail

					SET

					LastServiceNo = v_ServiceNo,

					LastIRIDNo = v_IRIDNo

					WHERE

					SIMID = v_SIMID;

				END IF;

			END IF;

			

			

		END IF;
		# ------------------------------------------------------------------------------

		# (END IF) UPDATE LAST CONTROL NO

		# ------------------------------------------------------------------------------
		
		# ------------------------------------------------------------------------------
		# Update ClientID
		# ------------------------------------------------------------------------------
		IF (STRCMP(v_ActionMade, "SUCCESS") = 0)
		THEN
			IF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0)
			THEN
				IF (v_TerminalID > 0)
				THEN
					UPDATE
					tblterminaldetail
					SET
					ClientID = v_ClientID,
					ClientName = v_ClientName
					WHERE
					TerminalID = v_TerminalID;
				END IF;
				
				IF (v_SIMID > 0)
				THEN
					UPDATE
					tblsimdetail
					SET
					ClientID = v_ClientID,
					ClientName = v_ClientName
					WHERE
					SIMID = v_SIMID;
				END IF;
				
			END IF;
			
			IF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)
			THEN
				IF (v_TerminalID > 0 && v_RepTerminalID > 0)
				then
					UPDATE
					tblterminaldetail
					SET
					ClientID = 0,
					ClientName = '-'
					WHERE
					TerminalID = v_TerminalID;
					
					UPDATE
					tblterminaldetail
					SET
					ClientID = v_ClientID,
					ClientName = v_ClientName
					WHERE
					TerminalID = v_RepTerminalID;
				end if;
				
				IF (v_SIMID > 0 && v_RepSIMID > 0)
				THEN
					UPDATE
					tblsimdetail
					SET
					ClientID = 0,
					ClientName = '-'
					WHERE
					SIMID = v_SIMID;
					
					UPDATE
					tblsimdetail
					SET
					ClientID = v_ClientID,
					ClientName = v_ClientName
					WHERE
					SIMID = v_RepSIMID;
				END IF;

			END IF;
			
			IF (STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0)
			THEN
				IF (v_TerminalID > 0)
				THEN
					UPDATE
					tblterminaldetail
					SET
					ClientID = 0,
					ClientName = '-'
					WHERE
					TerminalID = v_TerminalID;
				END IF;
				
				IF (v_SIMID > 0)
				THEN
					UPDATE
					tblsimdetail
					SET
					ClientID = 0,
					ClientName = '-'
					WHERE
					SIMID = v_SIMID;
				END IF;
				
			END IF;
		END IF;
		
		# fix to sync tblservicingdetail/tblfsrdetail, IRNo are sync -- sidumili
		IF (v_ServiceNo > 0 && v_IRIDNo > 0) THEN
		
			SELECT 
			a.IRNo INTO @IRNo 
			FROM 
			tblservicingdetail a 
			WHERE a.ServiceNo = v_ServiceNo 
			AND a.IRIDNo = v_IRIDNo;
			
			UPDATE
			tblfsrdetail
			SET
			IRNo = @IRNo
			WHERE
			ServiceNo = v_ServiceNo
			AND IRIDNo = v_IRIDNo;			
		END IF;
		
		# fix for NEGATIVE service result
		IF (v_ServiceNo > 0 && v_IRIDNo > 0) THEN
			IF (STRCMP(v_ActionMade, "NEGATIVE") = 0) THEN
				IF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0) THEN
					
					IF (v_TerminalID > 0) THEN						
						UPDATE tblterminaldetail
						SET
						LocationID = funcGetID("Search", "Location", v_TerminalLocation),
						Location = v_TerminalLocation,
						TerminalStatus = v_StatusTerminalID,
						TerminalStatusDescription = funcGetDesc("Search", "Terminal Status", v_StatusTerminalID),
						ClientID = 0,
						ClientName = 0
						WHERE
						TerminalID = v_TerminalID;
					END IF;
					
					IF (v_SIMID > 0) THEN						
						UPDATE tblsimdetail
						SET
						LocationID = funcGetID("Search", "Location", v_SimLocation),
						Location = v_SimLocation,
						SIMStatus = v_StatusSIMID,
						SIMStatusDescription = funcGetDesc("Search", "SIM Status", v_StatusSIMID),
						ClientID = 0,
						ClientName = 0
						WHERE
						SIMID = v_SIMID;
					END IF;
						
				END IF;
				
			END IF;
		END IF;
		
		# -------------------------------------------
		# update problem reported
		# -------------------------------------------
		IF (v_ServiceNo > 0 && v_IRIDNo > 0) THEN
			
			SELECT a.ProblemReported INTO @ProblemReported 
			FROM 
			tblservicingdetail a 
			WHERE 
			a.ServiceNo = v_ServiceNo
			AND a.IRIDNo = v_IRIDNo;
			
			UPDATE tblfsrdetail
			SET
			ProblemReported = @ProblemReported
			WHERE
			ServiceNo = v_ServiceNo
			AND IRIDNo = v_IRIDNo;
		end if; 
		
	ELSEIF (p_SearchBy = 'Cancel Service')	
	THEN
		SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));		
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);		
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);						
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);							

		# current, terminal		
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);				
		# current, sim

		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);

		IF (v_ServiceNo > 0 AND v_IRIDNo > 0)
		THEN
			# tblservicingdetail
			DELETE
			FROM
			tblservicingdetail
			WHERE (ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo);

			# tblfsrdetail
			DELETE
			FROM
			tblfsrdetail
			WHERE (ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo);
			
			IF ((STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0) ||
			    (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0))
			THEN
				IF ((STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0) ||
				    (STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0))
				THEN
					# tblirdetail
					UPDATE
					tblirdetail
					SET
					TerminalID = 0,
					TerminalSN = 0,
					SIMID = 0,
					SIMSN = 0,
					IRStatus = 1,
					IRStatusDescription = 'AVAILABLE'
					WHERE
					IRIDNo = v_IRIDNo;
				END IF;

				#tblterminaldetail
				IF (v_TerminalID > 0)
				THEN
					UPDATE
					tblterminaldetail
					SET
					TerminalStatus = 1,
					TerminalStatusDescription = 'AVAILABLE',
					LocationID = 1,
					Location = 'STOCK ROOM',
					ClientID = 0,
					ClientName = 0
					WHERE
					TerminalID = v_TerminalID;
				END IF;

				#tblsimdetail
				IF (v_SIMID > 0)
				THEN
					UPDATE
					tblsimdetail
					SET
					SIMStatus = 1,
					SIMStatusDescription = 'AVAILABLE',
					LocationID = 1,
					Location = 'STOCK ROOM',
					ClientID = 0,
					ClientName = 0
					WHERE
					SIMID = v_SIMID;
				END IF;
			END IF;
			
		END IF;	

	ELSEIF (p_SearchBy = 'Multiple Update Service')	
	THEN
		SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);	

		IF (v_ServiceNo > 0)
		THEN

			UPDATE tblservicingdetail

			SET

			ServiceDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),

			ServiceTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),

			FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER),

			FEName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)),

			ReferenceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)),

			CustomerName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)),

			CustomerContactNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)),

			CustomerPosition = TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)),

			Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)),

			AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)),

			AppCRC = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)),

			ModifiedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)),

			ModifiedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)),

			JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)),

			ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER),

			ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)),

			# eFSR

			ProblemReported = TRIM(SPLIT_STRING(p_SearchValue, '|' ,26)),

			ReqInstallationDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,27)),

			RMInstruction = TRIM(SPLIT_STRING(p_SearchValue, '|' ,28)),

			CustomerEmail = TRIM(SPLIT_STRING(p_SearchValue, '|' ,29)),
			
			IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,30)),
			
			ServiceReqDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,31)),
			
			ServiceReqTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,32)),
			
			SourceID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,33)) AS UNSIGNED INTEGER),
			CategoryID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,34)) AS UNSIGNED INTEGER),
			SubCategoryID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,35)) AS UNSIGNED INTEGER),
			
			DispatchID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,36)) AS UNSIGNED INTEGER),
			DispatchBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,37)),
			
			Vendor = TRIM(SPLIT_STRING(p_SearchValue, '|' ,38)),
			Requestor = TRIM(SPLIT_STRING(p_SearchValue, '|' ,39)),
			
			BillingTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,40)) AS UNSIGNED INTEGER)

			WHERE (ServiceNo = v_ServiceNo);
		END IF;

		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,19)) AS UNSIGNED INTEGER); # new
		SET v_PrevTerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,20)) AS UNSIGNED INTEGER); #old
		SET v_StatusTerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,21)) AS UNSIGNED INTEGER); # new
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,22)) AS UNSIGNED INTEGER); # new
		SET v_PrevSIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,23)) AS UNSIGNED INTEGER);	 # old
		SET v_StatusSIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,24)) AS UNSIGNED INTEGER); # new
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,25)) AS UNSIGNED INTEGER);

		

		IF (v_IRIDNo > 0)

		THEN

			IF ((STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0) ||

			    (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0))

			THEN

				UPDATE tblirdetail

				SET

				IRStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER),

				IRStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18))

				WHERE (IRIDNo = v_IRIDNo);

			END IF;
		END IF;

		IF (STRCMP(v_JobTypeDescription, "SVC REQ INSTALLATION") = 0)

		THEN

			# update terminal

			IF (v_TerminalID > 0)

			THEN
				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusTerminalID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));

				

				# check current and previous

				IF (v_TerminalID != v_PrevTerminalID)

				THEN

					# current

					UPDATE tblterminaldetail 

					SET  						

					TerminalStatus = v_Status,

					TerminalStatusDescription = v_Description

					WHERE TerminalID = v_TerminalID;

					

					# previous

					IF (v_PrevTerminalID > 0)

					THEN					
						UPDATE tblterminaldetail 
						SET  						
						TerminalStatus = 1,
						TerminalStatusDescription = 'AVAILABLE'
						WHERE TerminalID = v_PrevTerminalID
						AND TerminalStatus IN (2, 8);
					END IF;

				ELSE
					# current

					UPDATE tblterminaldetail 

					SET  						

					TerminalStatus = v_Status,

					TerminalStatusDescription = v_Description

					WHERE TerminalID = v_TerminalID;
				END IF;

				CALL spGetInfoDetail("Search", "Terminal SN Info", v_TerminalID, @p_outResult);

				SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));

				# tblservicingdetail, SN
				UPDATE tblservicingdetail 

				SET  						

				TerminalID = v_TerminalID,

				TerminalSN = v_TerminalSN

				WHERE ServiceNo = v_ServiceNo;

			ELSE

				# previous, terminal

				UPDATE tblterminaldetail 

				SET  						

				TerminalStatus = 1,

				TerminalStatusDescription = 'AVAILABLE'

				WHERE TerminalID = v_PrevTerminalID;

				

				# tblservicingdetail, SN

				UPDATE tblservicingdetail 

				SET  						

				TerminalID = 0,

				TerminalSN = "-"
				WHERE ServiceNo = v_ServiceNo;

			END IF;

			

			# update sim

			IF (v_SIMID > 0)

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusSIMID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));

				

				# check current and previous

				IF (v_SIMID != v_PrevSIMID)

				THEN

					# current

					UPDATE tblsimdetail 

					SET  						

					SIMStatus = v_Status,

					SIMStatusDescription = v_Description

					WHERE SIMID = v_SIMID;

					

					# previous

					IF (v_PrevSIMID > 0)

					THEN

						UPDATE tblsimdetail 

						SET  						

						SIMStatus = 1,

						SIMStatusDescription = 'AVAILABLE'

						WHERE SIMID = v_PrevSIMID;

					END IF;
				ELSE

					# current

					UPDATE tblsimdetail 

					SET  						

					SIMStatus = v_Status,

					SIMStatusDescription = v_Description

					WHERE SIMID = v_SIMID;
				END IF;

				CALL spGetInfoDetail("Search", "SIM SN Info", v_SIMID, @p_outResult);

				SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));

				

				# tblservicingdetail, SN

				UPDATE tblservicingdetail 

				SET  						

				SIMID = v_SIMID,

				SIMSerialNo = v_SIMSN

				WHERE ServiceNo = v_ServiceNo;	

			ELSE

				# previous, sim

				UPDATE tblsimdetail 

				SET  						

				SIMStatus = 1,

				SIMStatusDescription = 'AVAILABLE'

				WHERE SIMID = v_PrevSIMID;

				

				# tblservicingdetail, SN

				UPDATE tblservicingdetail 

				SET  						

				SIMID = 0,

				SIMSerialNo = "-"

				WHERE ServiceNo = v_ServiceNo;	

			END IF;						

		END IF;

		

		IF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)

		THEN

			# update terminal

			IF (v_TerminalID > 0)

			THEN

				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusTerminalID, @p_outResult);

				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));

				

				# check current and previous

				IF (v_TerminalID != v_PrevTerminalID)

				THEN

					# current

					UPDATE tblterminaldetail 

					SET  						

					TerminalStatus = v_Status,

					TerminalStatusDescription = v_Description

					WHERE TerminalID = v_TerminalID;

					

					# previous

					IF (v_PrevTerminalID > 0)

					THEN

						UPDATE tblterminaldetail 

						SET  						

						TerminalStatus = 1,

						TerminalStatusDescription = 'AVAILABLE'

						WHERE TerminalID = v_PrevTerminalID;

					END IF;

				ELSE

					# current

					UPDATE tblterminaldetail 

					SET  						

					TerminalStatus = v_Status,

					TerminalStatusDescription = v_Description

					WHERE TerminalID = v_TerminalID;

				END IF;

				

				CALL spGetInfoDetail("Search", "Terminal SN Info", v_TerminalID, @p_outResult);

				SET v_TerminalSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,7));

				

				# tblservicingdetail, SN
				UPDATE tblservicingdetail 
				SET  						
				ReplaceTerminalID = v_TerminalID,
				ReplaceTerminalSN = v_TerminalSN
				WHERE ServiceNo = v_ServiceNo;

				

			ELSE
				# previous, terminal
				UPDATE tblterminaldetail 
				SET  						
				TerminalStatus = 1,
				TerminalStatusDescription = 'AVAILABLE'
				WHERE TerminalID = v_PrevTerminalID
				AND TerminalStatus IN (2, 8);

				# tblservicingdetail, SN
				UPDATE tblservicingdetail 
				SET  						
				ReplaceTerminalID = 0,
				ReplaceTerminalSN = "-"
				WHERE ServiceNo = v_ServiceNo;
							
			END IF;						

			# update sim
			IF (v_SIMID > 0)
			THEN
				CALL spGetInfoDetail("Search", "SN Status Info By ID", v_StatusSIMID, @p_outResult);
				SET v_Status = CAST(TRIM(SPLIT_STRING(@p_outResult, '|' ,2)) AS UNSIGNED INTEGER);
				SET v_Description = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));

				# check current and previous
				IF (v_SIMID != v_PrevSIMID)
				THEN
					# current
					UPDATE tblsimdetail 
					SET  						
					SIMStatus = v_Status,
					SIMStatusDescription = v_Description
					WHERE SIMID = v_SIMID;

					# previous
					IF (v_PrevSIMID > 0)
					THEN
						UPDATE tblsimdetail 
						SET  						
						SIMStatus = 1,
						SIMStatusDescription = 'AVAILABLE'
						WHERE SIMID = v_PrevSIMID;
					END IF;				
				ELSE
					# tblsimdetail, status
					UPDATE tblsimdetail 
					SET  						
					SIMStatus = v_Status,
					SIMStatusDescription = v_Description
					WHERE SIMID = v_SIMID;
				END IF;				

				CALL spGetInfoDetail("Search", "SIM SN Info", v_SIMID, @p_outResult);
				SET v_SIMSN = TRIM(SPLIT_STRING(@p_outResult, '|' ,4));

				# tblservicingdetail, SN
				UPDATE tblservicingdetail 
				SET  						
				ReplaceSIMID = v_SIMID,
				ReplaceSIMSN = v_SIMSN
				WHERE ServiceNo = v_ServiceNo;	

			ELSE
				# previous, sim
				UPDATE tblsimdetail 
				SET  						
				SIMStatus = 1,
				SIMStatusDescription = 'AVAILABLE'
				WHERE SIMID = v_PrevSIMID
				AND SIMStatus IN (2, 8);

				# tblservicingdetail, SN
				UPDATE tblservicingdetail 
				SET  						
				ReplaceSIMID = 0,
				ReplaceSIMSN = "-"
				WHERE ServiceNo = v_ServiceNo;	

			END IF;
												
		END IF;
		

	ELSEIF (p_SearchBy = 'Multiple Update FSR')	
	THEN
		SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);		
		
		IF (v_FSRNo > 0)	
		THEN
			UPDATE tblfsrdetail
			SET
			FSRDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
			FSRTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)),
			TimeArrived = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)),
			TimeStart = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)),
			TimeEnd = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)),
			FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER),
			FEName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)),
			MerchantRepresentative = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)),
			MerchantRepresentativePosition = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)),
			MerchantContactNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)),
			PowerSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)),
			DockSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)),
			ProblemReported = TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)),
			ActionTaken = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)),
			Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19)),
			ActualProblemReported = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20)),
			AnyComments = TRIM(SPLIT_STRING(p_SearchValue, '|' ,21)),	
			ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,22)) AS UNSIGNED INTEGER),	
			Reason = TRIM(SPLIT_STRING(p_SearchValue, '|' ,23)),
			isBillable = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,24)) AS UNSIGNED INTEGER)
			WHERE (FSRNo = v_FSRNo);
		END IF;	
			
		IF (v_ServiceNo > 0)
		THEN
			UPDATE tblservicingdetail
			SET
			isBillable = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,24)) AS UNSIGNED INTEGER),
			AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|' ,25)),
			AppCRC = TRIM(SPLIT_STRING(p_SearchValue, '|' ,26))			
			WHERE (ServiceNo = v_ServiceNo);
		END IF;

		IF (v_IRIDNo > 0)
		THEN
			UPDATE tblirdetail
			SET
			AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|' ,25)),
			AppCRC = TRIM(SPLIT_STRING(p_SearchValue, '|' ,26))
			WHERE (IRIDNo = v_IRIDNo);
		END IF;

		IF (v_FSRNo > 0)
		THEN
			UPDATE tblfsrdetail
			SET
			ModifiedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,27)),
			ModifiedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,28))
			WHERE (FSRNo = v_FSRNo);
		END IF;
	
		IF (STRCMP(v_JobTypeDescription, "SVC REQ REPLACEMENT") = 0)
		THEN
		    SELECT TerminalID, SIMID, ReplaceTerminalID, ReplaceSIMID
		    INTO @curTerminalID, @curSIMID, @repTerminalID, @repSIMID
		    FROM tblservicingdetail
		    WHERE ServiceNo = v_ServiceNo
		    LIMIT 1;
            
		    -- RAIDEN
		    IF (@curTerminalID > 0 AND @repTerminalID > 0 AND @repTerminalID <> @curTerminalID) 
		    THEN
			SET @isActiveInstalled = 0;

			CALL spCheckRecordExist('Search', 'TerminalID Active Installed', CAST(@curTerminalID AS CHAR),
			    @isActiveInstalled
			    );

			IF (@isActiveInstalled = 0) THEN
			    UPDATE tblterminaldetail
			    SET TerminalStatus = 1,
				TerminalStatusDescription = 'AVAILABLE',
				LocationID = 1,
				Location = 'STOCK ROOM'
			    WHERE TerminalID = @curTerminalID
			      AND TerminalStatus IN (1, 7);
			END IF;
		    END IF;

		    -- RAIDEN
		    IF (@curSIMID > 0 AND @repSIMID > 0 AND @repSIMID <> @curSIMID)
		    THEN
			SET @isSIMActiveInstalled = 0;

			CALL spCheckRecordExist('Search', 'SIMID Active Installed', CAST(@curSIMID AS CHAR),
			    @isSIMActiveInstalled
			);

			IF (@isSIMActiveInstalled = 0) THEN
			    UPDATE tblsimdetail
			    SET SIMStatus = 1,
				SIMStatusDescription = 'AVAILABLE',
				LocationID = 1,
				Location = 'STOCK ROOM'
			    WHERE SIMID = @curSIMID
			      AND SIMStatus IN (1, 7);
			END IF;
		    END IF;

		    IF (@repTerminalID > 0) THEN
			UPDATE tblterminaldetail
			SET TerminalStatus = 7, TerminalStatusDescription = 'INSTALLED',
			    LocationID = 18, Location = 'PRODUCTION'
			WHERE TerminalID = @repTerminalID;
		    END IF;

		    IF (@repSIMID > 0) THEN
			UPDATE tblsimdetail
			SET SIMStatus = 7, SIMStatusDescription = 'INSTALLED',
			    LocationID = 18, Location = 'PRODUCTION'
			WHERE SIMID = @repSIMID;
		    END IF;
		END IF;
		
		#Rocky -- Update Location
		SET v_TerminalLocation = TRIM(SPLIT_STRING(p_SearchValue, '|' ,29));

		SET v_SimLocation =	TRIM(SPLIT_STRING(p_SearchValue, '|' ,30));

		SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,31));

		SET v_SIMSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,32));	
		
		IF (v_ServiceNo > 0)
		THEN
			UPDATE tblservicingdetail
			SET
			Vendor = TRIM(SPLIT_STRING(p_SearchValue, '|' ,33)),
			Requestor = TRIM(SPLIT_STRING(p_SearchValue, '|' ,34))			
			WHERE (ServiceNo = v_ServiceNo);
		END IF;	
		
		# -------------------------------------------
		# update problem reported
		# -------------------------------------------
		IF (v_ServiceNo > 0 && v_IRIDNo > 0) THEN

			SELECT a.ProblemReported INTO @ProblemReported 
			FROM 
			tblservicingdetail a 
			WHERE 
			a.ServiceNo = v_ServiceNo
			AND a.IRIDNo = v_IRIDNo;

			UPDATE tblfsrdetail
			SET
			ProblemReported = @ProblemReported
			WHERE
			ServiceNo = v_ServiceNo
			AND IRIDNo = v_IRIDNo;
		END IF; 
		

	ELSEIF (p_SearchBy = 'Update IR Info')	
	THEN
		SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

		UPDATE tblirdetail
		SET
		IRDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),
		InstallationDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),
		TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
		`MID` = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)),
		ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER),
		ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)),
		PrimaryNum = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)),
		SecondaryNum = TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)),
		AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)),
		AppCRC = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)),
		SET_UP = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)),
		REQUEST_FOR = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)),
		OTHER_SPECIAL_INSTRUCTION = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)),
		AnyComments = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)),
		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)),
		ModifiedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)),
		ModifiedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19)),
		POS_TYPE = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20))
		WHERE (MerchantID = v_MerchantID AND IRIDNo = v_IRIDNo);

		

	ELSEIF (p_SearchBy = 'Update RequestID')

	THEN

		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		

		IF (v_IRIDNo > 0)

		THEN

			UPDATE tblirdetail

			SET

			IRNo = v_IRNo

			WHERE (IRIDNo = v_IRIDNo);

			

			UPDATE tblservicingdetail

			SET

			IRNo = v_IRNo

			WHERE (IRIDNo = v_IRIDNo);

			

			UPDATE tblfsrdetail

			SET

			IRNo = v_IRNo

			WHERE (IRIDNo = v_IRIDNo);

		END IF;
	ELSEIF (p_SearchBy = 'Update Particular Image')

	THEN

		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_Image = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		

		UPDATE tblparticular

		SET Image = v_Image

		WHERE ParticularID = v_ParticularID;

		

	ELSEIF (p_SearchBy = 'Update Holiday')

	THEN

		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		UPDATE tblholiday

		SET 

		HolidayDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)),

		Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3))

		WHERE HolidayID = v_ID;

		

	ELSEIF (p_SearchBy = 'Multiple Terminal Detail')

	THEN
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		UPDATE tblterminaldetail

		SET

		TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER),

		TerminalStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),

		LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER),

		Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),

		UpdatedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER),

		UpdatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)),

		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8))

		WHERE TerminalID = v_TerminalID;

		

	ELSEIF (p_SearchBy = 'Multiple Terminal SN Detail')

	THEN

		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		UPDATE tblterminaldetail

		SET

		TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER),

		TerminalStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),

		LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER),

		Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),

		UpdatedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER),

		UpdatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)),

		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8))

		WHERE TerminalID = v_TerminalID;

		

	ELSEIF (p_SearchBy = 'Multiple SIM SN Detail')

	THEN

		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		UPDATE tblsimdetail

		SET

		SIMStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER),

		SIMStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),

		LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER),

		Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),

		UpdatedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER),

		UpdatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)),

		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8))

		WHERE SIMID = v_SIMID;

		

	ELSEIF (p_SearchBy = 'Update Job Order')

	THEN

		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

		

		/*

		# tblservicingdetail always set to COMPLETED

		UPDATE tblservicingdetail

		SET

		JobTypeStatusDescription = "COMPLETED"			

		WHERE ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;

		*/
	ELSEIF (p_SearchBy = 'Update isPDF')
	THEN
		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_Value = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
	
		UPDATE tblfsrdetail
		SET
		isPDF = v_Value
		WHERE FSRNo = v_FSRNo;
	
	ELSEIF (p_SearchBy = 'Update isDiagnostic')
	THEN
		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_Value = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
	
		UPDATE tblfsrdetail
		SET
		isDiagnostic = v_Value
		WHERE FSRNo = v_FSRNo;

	ELSEIF (p_SearchBy = 'Reset eFSR Generator')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_Value = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
	
		UPDATE tblfsrdetail
		SET
		isPDF = v_Value,
		isDiagnostic = v_Value
		WHERE FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo;

	ELSEIF (p_SearchBy = 'Update Signature')

	THEN

		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

		

		UPDATE tblfsrdetail

		SET

		Signature1 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),

		Signature2 = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4))

		WHERE FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo;

		

	ELSEIF (p_SearchBy = 'Update GeoLocation')

	THEN

		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

		

		UPDATE tblfsrdetail

		SET

		geoLatitude = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),

		geoLongitude = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),

		geoCountry = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),

		geoLocality = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)),

		geoAddress = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7))

		WHERE ServiceNo = v_ServiceNo;

		

	ELSEIF (p_SearchBy = 'Update Diagnostic')

	THEN

		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

		SET v_Info = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		

		UPDATE tblfsrdetail

		SET

		diagnostic_info = JSON_OBJECT('diagnostic_info', v_Info)

		WHERE FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo;	


	ELSEIF (p_SearchBy = 'Update Profile Info')

	THEN

		SET v_IRIDNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

		

		UPDATE tblirdetail

		SET

		profile_info =  TRIM(SPLIT_STRING(p_SearchValue, '|' ,2))

		WHERE IRIDNo = v_IRIDNo;	

		

	ELSEIF (p_SearchBy = 'Update Raw Data')
	THEN
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_DataInfo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		
		UPDATE tblirdetail
		SET
		rawdata_info =  v_DataInfo
		WHERE IRIDNo = v_IRIDNo;
		
	ELSEIF (p_SearchBy = 'Update Raw Data 2')
	THEN
		SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_DataInfo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		
		UPDATE tblirdetail
		SET
		rawdata_info =  v_DataInfo
		WHERE TID = v_TID AND `MID` = v_MID;	
		
	ELSEIF (p_SearchBy = 'Update Profile')
	THEN
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_DataInfo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		
		UPDATE tblirdetail
		SET
		profile_info =  v_DataInfo
		WHERE IRIDNo = v_IRIDNo;
	
	ELSEIF (p_SearchBy = 'Update Profile 2')
	THEN
		SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_DataInfo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		
		UPDATE tblirdetail
		SET
		profile_info =  v_DataInfo
		WHERE TID = v_TID AND `MID` = v_MID;
		
	ELSEIF (p_SearchBy = 'Update FSRRefNo')

	THEN

		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

		

		UPDATE tblfsrdetail

		SET

		FSRRefNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3))

		WHERE FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo;

	ELSEIF (p_SearchBy = 'Update Profile Config Info')
	THEN
		SET v_MerchantID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_DataInfo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		
		UPDATE tblparticular
		SET
		profile_config_info =  v_DataInfo
		WHERE ParticularID = v_MerchantID;	

	ELSEIF (p_SearchBy = 'Reset Merchant Service')

	THEN

		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		

		UPDATE tblirdetail

		SET

		IRStatus = 1,

		IRStatusDescription = 'AVAILABLE',

		TerminalID = 0,

		TerminalSN = '0',

		SIMID = 0,

		SIMSN = '0'

		WHERE IRIDNo = v_IRIDNo;

		

	ELSEIF (p_SearchBy = 'Update Mobile Version')

	THEN

		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_Value = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		

		UPDATE tblfsrdetail

		SET

		MobileVersion = v_Value

		WHERE ServiceNo = v_ServiceNo;	

		

	ELSEIF (p_SearchBy = 'Update Application Info')

	THEN

		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		SET v_AppCRC = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		

		UPDATE tblterminalmodel

		SET

		AppVersion = v_AppVersion,

		AppCRC = v_AppCRC

		WHERE

		TerminalModelID = v_ID;
		
	ELSEIF (p_SearchBy = 'Manual Diagnostic Detail')
	THEN
		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		
		UPDATE tblfsrdetail
		SET
		diagnostic_info = JSON_OBJECT('diagnostic_info', "Manual Diagnostic")
		WHERE FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo;
		
	ELSEIF (p_SearchBy = 'Ticket Status')
	THEN
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_Status = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS SIGNED INTEGER);
		
		UPDATE tblservicingdetail
		SET
		TicketStatus = v_Status,
		TicketID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER),
		TicketDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
		isBillable = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER)
		WHERE IRIDNo = v_IRIDNo AND ServiceNo = v_ServiceNo;
		
		UPDATE tblfsrdetail
		SET
		isBillable = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER)
		WHERE IRIDNo = v_IRIDNo AND ServiceNo = v_ServiceNo;
		
	ELSEIF (p_SearchBy = 'DispatchID')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		
		UPDATE tblservicingdetail
		SET
		DispatchID = v_ID,
		DispatchBy = v_Name
		WHERE ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
		
	ELSEIF (p_SearchBy = 'Service Status')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)); # SVC_...
		SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
		SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)); # INSTALLED
		SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)); # COMPLETED
		SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)); # SUCCESS/NEGATIVE
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)) AS UNSIGNED INTEGER);
		SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,10));
		
		-- GUARD: refuse reset if this ServiceNo already has a SUCCESS FSR
		SELECT COUNT(1) INTO @hasSuccessFSR
		FROM tblfsrdetail
		WHERE ServiceNo = v_ServiceNo AND ActionMade = 'SUCCESS';

		IF @hasSuccessFSR > 0 THEN
			SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot reset: this service already has a completed (SUCCESS) FSR.';
		END IF;
		
		IF (v_JobType = 1) #INSTALLATION
		THEN
		   SET @Status = 8;
		   SET @StatusDescription = 'DISPATCH';
		   
		   SET @LocationID = 2;
		   SET @Location = 'CITAS F.E';
		ELSE
		   SET @Status = 7;
		   SET @StatusDescription = 'INSTALLED';
		   
		   SET @LocationID = 18;
		   SET @Location = 'PRODUCTION';
		END IF;
		
		UPDATE tblservicingdetail
		SET
		JobTypeStatusDescription = 'PROCESSING',
		ServiceStatus = 8,
		ServiceStatusDescription = 'DISPATCH'
		WHERE ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
		
		#-------------------------------
		# get SN from tblservicingdetail
		#-------------------------------
		SELECT
		a.TerminalID, a.TerminalSN,
		a.SIMID, a.SIMSerialNo,
		a.ReplaceTerminalID, a.ReplaceTerminalSN,
		a.ReplaceSIMID, a.ReplaceSIMSN,
		a.ClientID, a.ClientName
		INTO @TerminalID, @TerminalSN, @SIMID, @SIMSN, @ReplaceTerminalID, @ReplaceTerminalSN, @ReplaceSIMID, @ReplaceSIMSN, @ClientID, @ClientName
		FROM
		tblservicingdetail a
		WHERE
		a.ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
		
		UPDATE tblirdetail
		SET
		IRStatus = @Status,
		IRStatusDescription = @StatusDescription,
		ClientID = @ClientID,
		ClientName = @ClientName
		WHERE
		IRIDNo = v_IRIDNo;
		
		IF (v_JobType = 1) #INSTALLATION
		THEN
			   if (@TerminalID > 0)
			   THEN
				   UPDATE tblirdetail
				   SET
				   TerminalID = @TerminalID,
				   TerminalSN = @TerminalSN
				   WHERE
				   IRIDNo = v_IRIDNo;
				   
				   UPDATE tblterminaldetail
				   SET
				   TerminalStatus = @Status,
				   TerminalStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   TerminalID = @TerminalID;
			   END IF;
			   
			   IF (@SIMID > 0)
			   THEN
				   UPDATE tblirdetail
				   SET
				   SIMID = @SIMID,
				   SIMSN = @SIMSN
				   WHERE
				   IRIDNo = v_IRIDNo;
				   
				   UPDATE tblsimdetail
				   SET
				   SIMStatus = @Status,
				   SIMStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   SIMID = @SIMID;
			   END if;
		   
		ELSEIF (v_JobType = 7) #REPLACEMENT
		THEN
			    # current		    
			    IF (@TerminalID > 0)
			    THEN
				   UPDATE tblirdetail
				   SET
				   TerminalID = @TerminalID,
				   TerminalSN = @TerminalSN
				   WHERE
				   IRIDNo = v_IRIDNo;
				   
				   UPDATE tblterminaldetail
				   SET
				   TerminalStatus = @Status,
				   TerminalStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   TerminalID = @TerminalID;
			   END IF;
			   
			   IF (@SIMID > 0)
			   THEN
				   UPDATE tblirdetail
				   SET
				   SIMID = @SIMID,
				   SIMSN = @SIMSN
				   WHERE
				   IRIDNo = v_IRIDNo;
				   
				   UPDATE tblsimdetail
				   SET
				   SIMStatus = @Status,
				   SIMStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   SIMID = @SIMID;
			   END IF;
			   
			   # replace 
			   SET @Status = 8;
			   SET @StatusDescription = 'DISPATCH';
			   SET @LocationID = 2;
			   SET @Location = 'CITAS F.E';
			   
			   IF (@ReplaceTerminalID > 0)
			    THEN
				   UPDATE tblterminaldetail
				   SET
				   TerminalStatus = @Status,
				   TerminalStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   TerminalID = @ReplaceTerminalID;
			   END IF;
			   
			   IF (@ReplaceSIMID > 0)
			   THEN
				   UPDATE tblsimdetail
				   SET
				   SIMStatus = @Status,
				   SIMStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   SIMID = @ReplaceSIMID;
			   END IF;
		   
		  elseIF (v_JobType = 4) #PULL-OUT
		  THEN
			   SET @Status = 7;
			   SET @StatusDescription = 'INSTALLED';
			   SET @LocationID = 18;
			   SET @Location = 'PRODUCTION';
		   
			   IF (@TerminalID > 0)
			   THEN
				   UPDATE tblirdetail
				   SET
				   TerminalID = @TerminalID,
				   TerminalSN = @TerminalSN
				   WHERE
				   IRIDNo = v_IRIDNo;
				   
				   UPDATE tblterminaldetail
				   SET
				   TerminalStatus = @Status,
				   TerminalStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   TerminalID = @TerminalID;
			   END IF;
			   
			   IF (@SIMID > 0)
			   THEN
				   UPDATE tblirdetail
				   SET
				   SIMID = @SIMID,
				   SIMSN = @SIMSN
				   WHERE
				   IRIDNo = v_IRIDNo;
				   
				   UPDATE tblsimdetail
				   SET
				   SIMStatus = @Status,
				   SIMStatusDescription = @StatusDescription,
				   LocationID = @LocationID,
				   Location = @Location,
				   ClientID = @ClientID,
				   ClientName = @ClientName
				   WHERE
				   SIMID = @SIMID;
			   END IF;
		    
		END IF;
		
	ELSEIF (p_SearchBy = 'Merchant Representative Info')
	THEN	
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_CustomerName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET v_CustomerPosition = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET v_CustomerContactNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
		SET v_CustomerEmail  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		
		UPDATE tblservicingdetail
		SET 	
		CustomerName = v_CustomerName,
		CustomerPosition = v_CustomerPosition,
		CustomerContactNo = v_CustomerContactNo,
		CustomerEmail = v_CustomerEmail	
		WHERE ServiceNo = v_ServiceNo;
		
		UPDATE tblfsrdetail
		SET
		MerchantRepresentative = v_CustomerName,
		MerchantRepresentativePosition = v_CustomerPosition,
		MerchantContactNo = v_CustomerContactNo,
		MerchantRepresentativeEmail = v_CustomerEmail
		WHERE ServiceNo = v_ServiceNo;
		
		UPDATE tblparticular
		SET
		ContactPerson = v_CustomerName,
		ContactPosition = v_CustomerPosition,
		ContactNumber = v_CustomerContactNo,
		Email = v_CustomerEmail
		WHERE ParticularID = v_MerchantID;
		
	ELSEIF (p_SearchBy = 'Stock Detail')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		UPDATE
		tblstockdetail
		SET
		ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER), 
		LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER), 
		TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER), 
		TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER), 
		TerminalBrandID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER), 
		SerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)), 
		StockStatus = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)), 
		DeliveryDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)), 
		ReceiveDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)), 
		ReleaseDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)),
		Allocation = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)), 
		AssetType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)), 
		PONo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)), 
		InvNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)), 
		PartNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)),
		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,17))
		WHERE
		ItemID = v_ID;
		
	ELSEIF (p_SearchBy = 'Multiple Stock Movement Detail')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		UPDATE tblstockdetail
		SET
		StockStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER),
		ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER),
		LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER),
		UpdatedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER),
		UpdatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)),
		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7))
		WHERE ItemID = v_ID;
		
	ELSEIF (p_SearchBy = 'Update Service Info JSON')
	THEN
		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_Info = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		UPDATE tblfsrdetail
		SET
		service_info = JSON_OBJECT('service_info', v_Info)
		WHERE ServiceNo = v_ServiceNo;
		
	ELSEIF (p_SearchBy = 'Type Info')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		UPDATE tbltype
		SET
		Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)),
		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),
		SequenceDisplay = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),
		RentFee = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
		Price = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6))
		WHERE TypeID = v_ID;
		
	ELSEIF (p_SearchBy = 'MSP Master')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		UPDATE tblmspmaster
		SET
		ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER),
		MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER),
		UpdatedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER),
		UpdatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
		SubmitID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER),
		SubmitAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)),
		RegisteredName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)),
		TradeName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)),
		NoBTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER),
		BusTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)) AS UNSIGNED INTEGER),
		CategoryTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)) AS UNSIGNED INTEGER),
		TINNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)), 
		AcqTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)) AS UNSIGNED INTEGER),
		ReferralTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)) AS UNSIGNED INTEGER),
		NoOfPOS = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)),
		MDRCreditTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER),
		MDRDebitTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)) AS UNSIGNED INTEGER),
		MDRInstTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,19)) AS UNSIGNED INTEGER), 
		SchemeTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,20)) AS UNSIGNED INTEGER),
		NoOfYear = TRIM(SPLIT_STRING(p_SearchValue, '|' ,21)),
		RentalAmt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,22)),
		MSPStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,23)) AS UNSIGNED INTEGER),
		Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,24))
		WHERE
		MSPNo = v_ID;
		
	ELSEIF (p_SearchBy = 'Particular-MSP')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		UPDATE tblparticular
		SET
		`Name` = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)), 
		Address = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),  
		ContactPerson = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)), 
		ContactPosition = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)), 
		ContactNumber = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)), 
		Email = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)), 
		TelNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)), 
		Mobile = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)), 
		RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER),
		Province = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)), 
		RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,12)) AS UNSIGNED INTEGER),
		Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13))
		WHERE
		ParticularID = v_ID;
		
	ELSEIF (p_SearchBy = 'MSP Master-Bank')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		UPDATE tblmspmaster
		SET
		BankAcntName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)),
		BankAcntNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)),
		BankSettlement = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)),
		BankReferring = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)),
		CheckedID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER),
		CheckedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7))
		WHERE
		MSPNo = v_ID;
		
	ELSEIF (p_SearchBy = 'MSP Master-Status')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		UPDATE tblmspmaster
		SET
		MSPStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER)
		WHERE
		MSPNo = v_ID;
		
	ELSEIF (p_SearchBy = 'Dependency')
	THEN
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		
		UPDATE tblfsrdetail
		SET		
		DependencyID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER),
		StatusReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER),
		IssueCategoryID = COALESCE(CAST(NULLIF(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)), '') AS UNSIGNED INTEGER), IssueCategoryID)
		WHERE IRIDNo = v_IRIDNo AND ServiceNo = v_ServiceNo;
		
	ELSEIF (p_SearchBy = 'Helpdesk-Details')
	THEN
		SET v_ID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		
		UPDATE tblhddetail AS d
		JOIN tblhdmaster AS m ON m.AssistNo = d.AssistNo
		SET
			 d.HelpdeskID = CASE WHEN d.HelpdeskID = TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) THEN d.HelpdeskID
								 ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) END,
			 d.TeamLeadID = CASE WHEN d.TeamLeadID = TRIM(SPLIT_STRING(p_SearchValue, '|', 3)) THEN d.TeamLeadID
								 ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 3)) END,
			 d.ReasonID   = CASE WHEN d.ReasonID = TRIM(SPLIT_STRING(p_SearchValue, '|', 4)) THEN d.ReasonID
								 ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 4)) END,
			 d.ContactPerson 	 = CASE WHEN d.ContactPerson = TRIM(SPLIT_STRING(p_SearchValue, '|', 5)) THEN d.ContactPerson
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 5)) END,
			 d.ContactNo 	  	 = CASE WHEN d.ContactNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 6)) THEN d.ContactNo
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 6)) END,
			 d.ContactPosition = CASE WHEN d.ContactPosition = TRIM(SPLIT_STRING(p_SearchValue, '|', 7)) THEN d.ContactPosition
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 7)) END,
			 d.ContactEmail 	 = CASE WHEN d.ContactEmail = TRIM(SPLIT_STRING(p_SearchValue, '|', 8)) THEN d.ContactEmail
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 8)) END,
			 d.TerminalSN 		 = CASE WHEN d.TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|', 9)) THEN d.TerminalSN
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 9)) END,
			 d.SIMSN 		 	 = CASE WHEN d.SIMSN = TRIM(SPLIT_STRING(p_SearchValue, '|', 10)) THEN d.SIMSN
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 10)) END,
			 d.DockerSN 		 = CASE WHEN d.DockerSN = TRIM(SPLIT_STRING(p_SearchValue, '|', 11)) THEN d.DockerSN
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 11)) END,
			 d.ProblemReported = CASE WHEN d.ProblemReported = TRIM(SPLIT_STRING(p_SearchValue, '|', 12)) THEN d.ProblemReported
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 12)) END,
			 d.RemarksHelpdesk = CASE WHEN d.RemarksHelpdesk = TRIM(SPLIT_STRING(p_SearchValue, '|', 13)) THEN d.RemarksHelpdesk
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 13)) END,
			 d.RemarksService  = CASE WHEN d.RemarksService = TRIM(SPLIT_STRING(p_SearchValue, '|', 14)) THEN d.RemarksService
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 14)) END,
			 d.Status 			 = CASE WHEN d.Status = TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) THEN d.Status
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) END,
			 d.CreatedAt 		 = CASE WHEN d.CreatedAt = TRIM(SPLIT_STRING(p_SearchValue, '|', 16)) THEN d.CreatedAt
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 16)) END,
			 d.SourceID 		 = CASE WHEN d.SourceID = TRIM(SPLIT_STRING(p_SearchValue, '|', 17)) THEN d.SourceID
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 17)) END,
			 d.CategoryID		 = CASE WHEN d.CategoryID = TRIM(SPLIT_STRING(p_SearchValue, '|', 18)) THEN d.CategoryID
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 18)) END,
			 d.SubCategoryID 	 = CASE WHEN d.SubCategoryID = TRIM(SPLIT_STRING(p_SearchValue, '|', 19)) THEN d.SubCategoryID
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 19)) END,
			 d.TimeAssisted    = CASE WHEN d.TimeAssisted = TRIM(SPLIT_STRING(p_SearchValue, '|', 20)) THEN d.TimeAssisted
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 20)) END,
			 d.RequestID 		 = CASE WHEN d.RequestID = TRIM(SPLIT_STRING(p_SearchValue, '|', 21)) THEN d.RequestID
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 21)) END,
			 d.RequestedBy 	 = CASE WHEN d.RequestedBy = TRIM(SPLIT_STRING(p_SearchValue, '|', 22)) THEN d.RequestedBy
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 22)) END,
			 d.Representative  = CASE WHEN d.Representative = TRIM(SPLIT_STRING(p_SearchValue, '|', 23)) THEN d.Representative
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 23)) END,
			 d.ActualProblem 	 = CASE WHEN d.ActualProblem = TRIM(SPLIT_STRING(p_SearchValue, '|', 24)) THEN d.ActualProblem
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 24)) END,
			 d.RequestDate 	 = CASE WHEN d.RequestDate = TRIM(SPLIT_STRING(p_SearchValue, '|', 25)) THEN d.RequestDate
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 25)) END,
										
			 d.CompletedAt 	 = CASE WHEN TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) IN ('SUCCESS', 'NEGATIVE') AND
										d.CompletedAt != TRIM(SPLIT_STRING(p_SearchValue, '|', 26)) THEN TRIM(SPLIT_STRING(p_SearchValue, '|', 26))
										WHEN TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) NOT IN ('SUCCESS', 'NEGATIVE') THEN d.CompletedAt
										ELSE d.CompletedAt END,
										
			 d.AppVersion 		 = CASE WHEN d.AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|', 27)) THEN d.AppVersion
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 27)) END,
			 d.AppCrc 			 = CASE WHEN d.AppCrc = TRIM(SPLIT_STRING(p_SearchValue, '|', 28)) THEN d.AppCrc
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 28)) END,
										
			d.ProblemID 		 = CASE WHEN d.RequestID = TRIM(SPLIT_STRING(p_SearchValue, '|', 29)) THEN d.RequestID
							ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 29)) END,
							
			d.IssueCategoryID       = CASE WHEN d.RequestID = TRIM(SPLIT_STRING(p_SearchValue, '|', 30)) THEN d.RequestID
							ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 30)) END,

			 m.RequestDate = CASE WHEN TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) IN ('SUCCESS', 'NEGATIVE') THEN NULL
										WHEN m.Status IN ('SUCCESS', 'NEGATIVE') THEN m.RequestDate
										WHEN m.RequestDate = TRIM(SPLIT_STRING(p_SearchValue, '|', 25)) THEN m.RequestDate
										ELSE TRIM(SPLIT_STRING(p_SearchValue, '|', 25)) END,
										
			 m.Status = CASE WHEN TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) IN ('SUCCESS', 'NEGATIVE') AND m.Status not in ('SUCCESS', 'NEGATIVE') THEN 'SUCCESS'
								  WHEN TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) NOT IN ('SUCCESS', 'NEGATIVE') AND m.Status != TRIM(SPLIT_STRING(p_SearchValue, '|', 15)) THEN TRIM(SPLIT_STRING(p_SearchValue, '|', 15))
								  ELSE m.Status END
			WHERE
				 d.ProblemNo = v_ID;
			 
	ELSEIF (p_SearchBy = 'Update Service RequestID')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
	
		IF (v_ServiceNo > 0)
		THEN
			UPDATE tblservicingdetail
			SET
			IRNo = v_IRNo
			WHERE (ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo);		

			UPDATE tblfsrdetail
			SET
			IRNo = v_IRNo
			WHERE (ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo);

		END IF;
		
	ELSEIF (p_SearchBy = 'Service Type Status Category')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		
		IF (v_ServiceNo > 0)
		THEN
			UPDATE tblservicingdetail
			SET
			ServiceStatus = v_ServiceStatus,
			ServiceStatusDescription = v_ServiceStatusDescription
			WHERE (ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo);		

		END IF;
		
	ELSEIF (p_SearchBy = 'Update IR Detail Terminal/SIM')
	THEN	
	        SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER); 
		SET v_IRIDNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
		SET v_SIMSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		SET @ServiceNos = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
		SET @Deployed = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));

		# update terminal
		IF (v_TerminalID > 0) THEN
			UPDATE tblirdetail 
			SET  						
			TerminalID = v_TerminalID,
			TerminalSN = v_TerminalSN
			WHERE IRIDNo = v_IRIDNo;
			
			IF (@Deployed = 1) THEN
				UPDATE tblterminaldetail
				SET
				TerminalStatus = 7,
				TerminalStatusDescription = 'INSTALLED',
				LocationID = 18,
				Location = 'PRODUCTION'
				WHERE
				TerminalID = v_TerminalID;			
			END IF;
		END IF;	
		
		# update sim
		if (v_SIMID > 0) THEN
			UPDATE tblirdetail 
			SET  									
			SIMID = v_SIMID,
			SIMSN = v_SIMSN
			WHERE IRIDNo = v_IRIDNo;
			
			IF (@Deployed = 1) THEN
				UPDATE tblsimdetail
				SET
				SIMStatus = 7,
				SIMStatusDescription = 'INSTALLED',
				LocationID = 18,
				Location = 'PRODUCTION'
				WHERE
				SIMID = v_SIMID;			
			END IF;
			
		END IF;	
		
		IF (@ServiceNos IS NOT NULL 
		    AND TRIM(@ServiceNos) <> '' 
		    AND JSON_VALID(@ServiceNos) 
		    AND JSON_TYPE(@ServiceNos) = 'ARRAY' 
		    AND JSON_LENGTH(@ServiceNos) > 0 
		) THEN 

		    # -------------------------------------------------------------
		    # tblservicingdetail - TERMINAL + SIM
		    # -------------------------------------------------------------
		    UPDATE tblservicingdetail a 
		    INNER JOIN JSON_TABLE(
			@ServiceNos, 
			'$[*]' COLUMNS (
			    ServiceNo VARCHAR(50) PATH '$'
			)
		    ) jt 
			ON jt.ServiceNo = a.ServiceNo 
		    SET 

			# TERMINAL
			a.TerminalID = CASE 
			    WHEN a.JobType = 7 THEN a.TerminalID 
			    ELSE v_TerminalID 
			END, 

			a.TerminalSN = CASE 
			    WHEN a.JobType = 7 THEN a.TerminalSN 
			    ELSE v_TerminalSN 
			END, 

			a.ReplaceTerminalID = CASE 
			    WHEN a.JobType = 7 THEN v_TerminalID 
			    ELSE a.ReplaceTerminalID 
			END, 

			a.ReplaceTerminalSN = CASE 
			    WHEN a.JobType = 7 THEN v_TerminalSN 
			    ELSE a.ReplaceTerminalSN 
			END,

			# SIM
			a.SIMID = CASE 
			    WHEN a.JobType = 7 THEN a.SIMID 
			    ELSE v_SIMID 
			END,

			a.SIMSerialNo = CASE 
			    WHEN a.JobType = 7 THEN a.SIMSerialNo 
			    ELSE v_SIMSN 
			END,

			a.ReplaceSIMID = CASE 
			    WHEN a.JobType = 7 THEN v_SIMID 
			    ELSE a.ReplaceSIMID 
			END,

			a.ReplaceSIMSN = CASE 
			    WHEN a.JobType = 7 THEN v_SIMSN 
			    ELSE a.ReplaceSIMSN 
			END

		    WHERE a.IRIDNo = v_IRIDNo;


		    # -------------------------------------------------------------
		    # tblfsrdetail - TERMINAL + SIM
		    # -------------------------------------------------------------
		    UPDATE tblfsrdetail a 
		    INNER JOIN JSON_TABLE(
			@ServiceNos, 
			'$[*]' COLUMNS (
			    ServiceNo VARCHAR(50) PATH '$'
			)
		    ) jt 
			ON jt.ServiceNo = a.ServiceNo 
		    SET 

			a.TerminalID = CASE 
			    WHEN a.JobType = 7 THEN a.TerminalID 
			    ELSE v_TerminalID 
			END, 

			a.TerminalSN = CASE 
			    WHEN a.JobType = 7 THEN a.TerminalSN 
			    ELSE v_TerminalSN 
			END,

			a.SIMID = v_SIMID,

			a.SIMSN = v_SIMSN

		    WHERE a.IRIDNo = v_IRIDNo; 

		END IF;
		
	ELSEIF (p_SearchBy = 'Reported Date')
	THEN	
		SET v_JobType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_ServiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_IRIDNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET v_Date = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

		UPDATE tblservicingdetail 
		SET  						
		ReportedDate = v_Date
		WHERE 
		JobType = v_JobType
		AND IRIDNo = v_IRIDNo
		AND IRNo = v_IRNo;
		
	ELSEIF (p_SearchBy = 'Beyond Reason')
	THEN
		SET v_JobType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_FSRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_ServiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET v_IRIDNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET v_Info = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
		
		UPDATE tblfsrdetail
		SET
		BeyondReason = v_Info
		WHERE
		JobType = v_JobType
		AND FSRNo = v_FSRNo
		AND ServiceNo = v_ServiceNo
		AND IRIDNo = v_IRIDNo;
		
	ELSEIF (p_SearchBy = 'Report Data Storage')
	THEN
		# OVERALL REQUESTS / REQUEST WITHIN SLA
		UPDATE tblreportdatastorage t
		JOIN (
		  SELECT 
		    StorageType,
		    Title,
			FLOOR(ROUND(COALESCE(SUM(January), 0), 2))    AS January,
			FLOOR(ROUND(COALESCE(SUM(February), 0), 2))   AS February,
			FLOOR(ROUND(COALESCE(SUM(March), 0), 2))      AS March,
			FLOOR(ROUND(COALESCE(SUM(April), 0), 2))      AS April,
			FLOOR(ROUND(COALESCE(SUM(May), 0), 2))        AS May,
			FLOOR(ROUND(COALESCE(SUM(June), 0), 2))       AS June,
			FLOOR(ROUND(COALESCE(SUM(July), 0), 2))       AS July,
			FLOOR(ROUND(COALESCE(SUM(August), 0), 2))     AS August,
			FLOOR(ROUND(COALESCE(SUM(September), 0), 2))  AS September,
			FLOOR(ROUND(COALESCE(SUM(October), 0), 2))    AS October,
			FLOOR(ROUND(COALESCE(SUM(November), 0), 2))   AS November,
			FLOOR(ROUND(COALESCE(SUM(December), 0), 2))   AS December
		  FROM tblreportdatastorage
		  WHERE isActive = 1
		    AND (
		      Description IN ('NEGATIVE', 'PENDING', 'RESOLVED') 
		      OR Description IN ('NEGATIVE_', 'PENDING_', 'RESOLVED_')
		    )
		  GROUP BY StorageType, Title
		) X ON t.Title = x.Title AND t.StorageType = x.StorageType
		SET 
		  t.January = x.January,
		  t.February = x.February,
		  t.March = x.March,
		  t.April = x.April,
		  t.May = x.May,
		  t.June = x.June,
		  t.July = x.July,
		  t.August = x.August,
		  t.September = x.September,
		  t.October = x.October,
		  t.November = x.November,
		  t.December = x.December
		WHERE t.Description = 'TOTAL'
		  AND t.isActive = 1;
		  
		#CURRENT SLA %
		UPDATE tblreportdatastorage t7
		JOIN tblreportdatastorage t4 ON t4.StorageType = 4 AND t4.Title = 'GRAND TOTAL' AND t4.Description = '-' AND t4.isActive = 1
		JOIN tblreportdatastorage t3 ON t3.StorageType = 3 AND t3.Title = 'GRAND TOTAL' AND t3.Description = '-' AND t3.isActive = 1
		SET 
			t7.January    = COALESCE(FLOOR(ROUND((t4.January    / NULLIF(t3.January, 0)) * 100, 2)), 0),
			t7.February   = COALESCE(FLOOR(ROUND((t4.February   / NULLIF(t3.February, 0)) * 100, 2)), 0),
			t7.March      = COALESCE(FLOOR(ROUND((t4.March      / NULLIF(t3.March, 0)) * 100, 2)), 0),
			t7.April      = COALESCE(FLOOR(ROUND((t4.April      / NULLIF(t3.April, 0)) * 100, 2)), 0),
			t7.May        = COALESCE(FLOOR(ROUND((t4.May        / NULLIF(t3.May, 0)) * 100, 2)), 0),
			t7.June       = COALESCE(FLOOR(ROUND((t4.June       / NULLIF(t3.June, 0)) * 100, 2)), 0),
			t7.July       = COALESCE(FLOOR(ROUND((t4.July       / NULLIF(t3.July, 0)) * 100, 2)), 0),
			t7.August     = COALESCE(FLOOR(ROUND((t4.August     / NULLIF(t3.August, 0)) * 100, 2)), 0),
			t7.September  = COALESCE(FLOOR(ROUND((t4.September  / NULLIF(t3.September, 0)) * 100, 2)), 0),
			t7.October    = COALESCE(FLOOR(ROUND((t4.October    / NULLIF(t3.October, 0)) * 100, 2)), 0),
			t7.November   = COALESCE(FLOOR(ROUND((t4.November   / NULLIF(t3.November, 0)) * 100, 2)), 0),
			t7.December   = COALESCE(FLOOR(ROUND((t4.December   / NULLIF(t3.December, 0)) * 100, 2)), 0)
		WHERE 
			t7.StorageType = 7 AND t7.Title = 'GRAND TOTAL' AND t7.Description = '-' AND t7.isActive = 1;
			
		# update TCount
		UPDATE tblreportdatastorage
		SET TCount = 
		    COALESCE(January, 0) +
		    COALESCE(February, 0) +
		    COALESCE(March, 0) +
		    COALESCE(April, 0) +
		    COALESCE(May, 0) +
		    COALESCE(June, 0) +
		    COALESCE(July, 0) +
		    COALESCE(August, 0) +
		    COALESCE(September, 0) +
		    COALESCE(October, 0) +
		    COALESCE(November, 0) +
		    COALESCE(December, 0)
		WHERE StorageType = 7 AND isActive = 1;
		
	ELSEIF (p_SearchBy = 'Service Helpdesk')
	THEN
		SET v_ServiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_AssistNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_ProblemNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		
		UPDATE tblservicingdetail
		SET
		AssistNo = v_AssistNo,
		ProblemNo = v_ProblemNo
		WHERE
		ServiceNo = v_ServiceNo;
		
	ELSEIF (p_SearchBy = 'Report Status')
	THEN
		SET @ReportDesc = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		
		SET @StatusID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET @Status = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET @ProcessedAt = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET @ProcessedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
		
		UPDATE tblreportstatus
		SET
		StatusID = @StatusID,
		`Status`= @Status,
		ProcessedAt = @ProcessedAt,
		ProcessedBy = @ProcessedBy
		WHERE
		ReportDesc = @ReportDesc;
		
	ELSEIF (p_SearchBy = 'Request-Schedule Date')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET @UpdatedDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET @UpdatedTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET @ReqInstallationDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));		
		SET @ServiceReqDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		
		SET @ProblemReported = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
		SET @RMInstruction = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));
		SET @Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
		
		UPDATE tblservicingdetail
		SET
		ReqInstallationDate = @ReqInstallationDate,
		ServiceReqDate = @ServiceReqDate,
		ProblemReported = @ProblemReported,
		RMInstruction = @RMInstruction,
		Remarks = @Remarks 		
		WHERE
		ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
		
		UPDATE tblfsrdetail
		SET
		ProblemReported = @ProblemReported
		WHERE
		ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
		
	ELSEIF (p_SearchBy = 'Serviced Date-Time')
	THEN
		SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET @UpdatedDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET @UpdatedTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
		SET @FSRDate = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));		
		SET @TimeArrived = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
		SET @ReceiptTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));
		SET @TimeStart = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
		SET @TimeEnd = TRIM(SPLIT_STRING(p_SearchValue, '|' ,10));
		
		SET @ProblemReported = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11));
		SET @ActualProblemReported = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));
		SET @ActionTaken = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13));
		SET @AnyComments = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));
		SET @Remarks = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15));
		
		SET @isReport = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)) AS UNSIGNED INTEGER);
		SET @isBillable = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER);
		
		SET @ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18));
		
		SET @isCloseTicket = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,19)) AS UNSIGNED INTEGER);
		SET @TicketID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,20)) AS UNSIGNED INTEGER);
		SET @TicketDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,21));
		
		SET @ModifiedBy = TRIM(SPLIT_STRING(p_SearchValue, '|' ,22));
		SET @ModifiedDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,23));
		
		UPDATE tblfsrdetail
		SET
		FSRDate = @FSRDate,
		FSRTime = @ReceiptTime,
		TimeArrived = @TimeArrived,
		TimeStart = @TimeStart,
		TimeEnd = @TimeEnd,
		InvoiceNo = @TimeStart,
		BatchNo = @TimeEnd,
		ProblemReported = @ProblemReported,
		ActualProblemReported = @ActualProblemReported,
		ActionTaken = @ActionTaken,
		AnyComments = @AnyComments,
		Remarks = @Remarks,
		isReport = @isReport,
		isBillable = @isBillable,
		ActionMade = @ActionMade,
		ModifiedBy = @ModifiedBy,
		ModifiedDateTime = @ModifiedDateTime
		WHERE
		FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
		
		UPDATE tblservicingdetail
		SET
		isBillable = @isBillable,
		isReport = @isReport,
		TicketStatus = @isCloseTicket,
		TicketID = @TicketID,
		TicketDateTime = @TicketDateTime
		WHERE
		ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
		
	ELSEIF (p_SearchBy = 'Merchant SN-Mode Type')
	THEN
		SET v_ModeType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
		SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
		SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
		SET v_Status = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)) AS UNSIGNED INTEGER);

		SET @Name = '-';
		SET @TerminalSN = '-';
		SET @SIMSN = '-';
		SET @Location = '-';
		SET @Status = '-';
		
		if (v_ClientID > 0) THEN
			SELECT a.Name INTO @Name FROM tblparticular a WHERE a.ParticularID = v_ClientID;
		END IF;
		
		IF (v_TerminalID > 0) THEN
			SELECT a.TerminalSN INTO @TerminalSN FROM tblterminaldetail a WHERE a.TerminalID = v_TerminalID;
		END IF;
		
		IF (v_SIMID > 0) THEN
			SELECT a.SIMSN INTO @SIMSN FROM tblsimdetail a WHERE a.SIMID = v_SIMID;
		END IF;
		
		IF (v_LocationID > 0) THEN
			SELECT a.Description INTO @Location FROM tbllocation a WHERE a.LocationID = v_LocationID;
		END IF;
		
		IF (v_Status > 0) THEN
			SELECT a.Description INTO @Status FROM tblterminalstatus a WHERE a.TerminalStatusID = v_Status;
		END IF;
		
		#tblirdetail
		if (v_IRIDNo > 0) THEN
			IF (v_ModeType = 'Return') THEN
				SET @TerminalID = 0;
				SET @TerminalSN = 0;
				SET @SIMID = 0;
				SET @SIMSN = 0;
			ELSE
				SET @TerminalID = v_TerminalID;
				SET @TerminalSN = @TerminalSN;	
				SET @SIMID = v_SIMID;
				SET @SIMSN = @SIMSN;			
			END IF;
			
			UPDATE tblirdetail
			SET
			IRStatus = v_Status,
			IRStatusDescription = @Status,
			TerminalID = @TerminalID,
			TerminalSN = @TerminalSN,
			SIMID = @SIMID,
			SIMSN = @SIMSN
			WHERE
			IRIDNo = v_IRIDNo AND MerchantID = v_MerchantID;
		END IF;
		
		#tblterminaldetail
		IF (v_TerminalID > 0) THEN
			IF (v_ModeType = 'Return') THEN
				SET @ClientID = 0;
				SET @ClientName = 0;
			ELSE
				SET @ClientID = v_ClientID;
				SET @ClientName = @Name;				
			END IF;
			
			UPDATE tblterminaldetail
			SET
			ClientID = @ClientID,
			ClientName = @ClientName,
			TerminalStatus = v_Status,
			TerminalStatusDescription = @Status,
			LocationID = v_LocationID,
			Location = @Location
			WHERE
			TerminalID = v_TerminalID;
		END IF;
		
		#tblsimdetail
		IF (v_SIMID > 0) then
			IF (v_ModeType = 'Return') THEN
				SET @ClientID = 0;
				SET @ClientName = 0;
			ELSE
				SET @ClientID = v_ClientID;
				SET @ClientName = @Name;				
			END IF;
			
			UPDATE tblsimdetail
			SET
			ClientID = @ClientID,
			ClientName = @ClientName,
			SIMStatus = v_Status,
			SIMStatusDescription = @Status,
			LocationID = v_LocationID,
			Location = @Location
			WHERE
			SIMID = v_SIMID;
		end if;
		
		IF (v_ModeType = 'Deploy') THEN
			#tblservicingdetail
			IF (v_ServiceNo > 0) THEN
				UPDATE tblservicingdetail
				SET
				TerminalID = v_TerminalID,
				TerminalSN = @TerminalSN,
				SIMID = v_SIMID,
				SIMSerialNo = @SIMSN
				WHERE
				ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
			end if;
			
			#tblfsrdetail
			IF (v_ServiceNo > 0) THEN
				UPDATE tblfsrdetail
				SET
				TerminalID = v_TerminalID,
				TerminalSN = @TerminalSN,
				SIMID = v_SIMID,
				SIMSN = @SIMSN
				WHERE
				ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo;
			END IF;
		END IF;
		
	ELSEIF (p_SearchBy = 'Complete Helpdesk Service-FSR')
	THEN
		SET @ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET @ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET @ServiceStatusDesc = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET @ServiceStatusCode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		
		UPDATE tblservicingdetail
		SET
		ServiceStatus = @ServiceStatus,
		ServiceStatusDescription = @ServiceStatusDesc,
		ServiceCode = @ServiceStatusCode,
		isBillable = 0
		WHERE
		ServiceNo = @ServiceNo;
		
		UPDATE tblfsrdetail
		SET
		ServiceStatus = @ServiceStatus,
		ServiceStatusDescription = @ServiceStatusDesc,
		ServiceCode = @ServiceStatusCode,
		isBillable = 0
		WHERE
		ServiceNo = @ServiceNo;
		
	ELSEIF (p_SearchBy = 'Servicing-FSR Job Type')
	THEN	
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		
		IF (v_ServiceNo > 0 && v_JobType > 0) THEN
		
			SELECT a.ServiceTypeID, a.JobType, a.Description, a.Code, a.JobTypeDescription, a.ServiceJobTypeDescription 
			INTO @ServiceTypeID, @JobType, @Description, @Code, @JobTypeDescription, @ServiceJobTypeDescription 
			FROM tblservicetype a 
			WHERE a.JobType = v_JobType;
			
			# tblservicingdetail
			UPDATE tblservicingdetail 
			SET  							
				JobType = @JobType,			
				JobTypeDescription = @JobTypeDescription,
				ServiceCode = @Code,
				JobTypeSubDescription = @Description
			WHERE   ServiceNo = v_ServiceNo 
				AND IRNo = v_IRNo;
				
			# tblfsrdetail
			UPDATE tblfsrdetail 
			SET  							
				JobType = @JobType,			
				JobTypeDescription = @JobTypeDescription,
				ServiceCode = @Code
			WHERE   ServiceNo = v_ServiceNo 
				AND IRNo = v_IRNo;
						
		END IF;
		
	ELSEIF (p_SearchBy = 'Remove Merchant SN Assigned')
	THEN
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
		SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
		
		#tblirdetail
		IF (v_IRIDNo > 0) THEN
			IF (v_TerminalID > 0) THEN
				UPDATE tblirdetail
				SET			
				TerminalID = 0,
				TerminalSN = 0
				WHERE
				IRIDNo = v_IRIDNo AND MerchantID = v_MerchantID;
			END IF;
			
			IF (v_SIMID > 0) THEN
				UPDATE tblirdetail
				SET					
				SIMID = 0,
				SIMSN = 0
				WHERE
				IRIDNo = v_IRIDNo AND MerchantID = v_MerchantID;
			END IF;
			
			
		END IF;
		
	ELSEIF (p_SearchBy = 'Servicing-FSR Include In Report')
	THEN
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET @value = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
		
		UPDATE tblservicingdetail s
		JOIN tblfsrdetail f 
		  ON f.ClientID = s.ClientID
		 AND f.ServiceNo = s.ServiceNo
		 AND f.IRIDNo   = s.IRIDNo
		SET 
		    s.isReport = @value,
		    f.isReport = @value
		WHERE 
		    s.ClientID  = v_ClientID
		AND s.ServiceNo = v_ServiceNo
		AND s.IRIDNo    = v_IRIDNo;
		
	ELSEIF (p_SearchBy = 'Job-Order-Overide')
	THEN	
		SET @ServiceNo 	= CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET @Json 		= CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS JSON);
		
		#SELECT @ServiceNo, @Json;
		CALL `spServicingReversal`(@ServiceNo, @Json);
		
	#andy
	ELSEIF (p_SearchBy = 'Service-Result-Overide')
	THEN	
		SET @ServiceNo 	= CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET @Json 		= CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS JSON);
		SET @NewResult 	= JSON_UNQUOTE(JSON_EXTRACT(@Json, '$.NewResult'));

		IF @NewResult NOT IN ('SUCCESS', 'NEGATIVE') THEN
			SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid Service Result value';
		END IF;

		-- CONFIRM RECORD EXISTS, GET IRIDNo FOR SAFE UPDATES
		SELECT COUNT(1), MAX(IRIDNo) INTO @recExists, @v_IRIDNo
		FROM tblfsrdetail
		WHERE ServiceNo = @ServiceNo;

		IF @recExists = 0 THEN
			SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'FSR record not found for this ServiceNo';
		END IF;

		-- GET JOB TYPE / DEVICE INFO FOR THIS SERVICE
		SELECT JobType, TerminalID, SIMID, ReplaceTerminalID, ReplaceSIMID
		INTO @svc_JobType, @svc_TerminalID, @svc_SIMID, @svc_RepTerminalID, @svc_RepSIMID
		FROM tblservicingdetail
		WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo
		LIMIT 1;

		UPDATE tblfsrdetail
		SET ActionMade = @NewResult
		WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo;

		-- KEEP ServiceStatus/JobTypeStatusDescription IN SYNC WITH THE NEW RESULT
		IF @NewResult = 'SUCCESS' THEN

			UPDATE tblservicingdetail
			SET ServiceStatus = 7,
				ServiceStatusDescription = 'INSTALLED',
				JobTypeStatusDescription = 'COMPLETED'
			WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo;

			UPDATE tblfsrdetail
			SET ServiceStatus = 7,
				ServiceStatusDescription = 'INSTALLED'
			WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo;

			UPDATE tblirdetail
			SET IRStatus = 7,
				IRStatusDescription = 'INSTALLED'
			WHERE IRIDNo = @v_IRIDNo;

		ELSE -- NEGATIVE

			IF @svc_JobType = 1 THEN
				-- INSTALLATION: Success -> Negative (CONFIRMED SPEC)

				UPDATE tblservicingdetail
				SET JobTypeStatusDescription = 'COMPLETED',
					ServiceStatus = 1,
					ServiceStatusDescription = 'AVAILABLE'
				WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo;

				UPDATE tblterminaldetail
				SET TerminalStatus = 1,
					TerminalStatusDescription = 'AVAILABLE',
					Location = 'STOCKROOM'
				WHERE TerminalID = @svc_TerminalID;

				UPDATE tblsimdetail
				SET SIMStatus = 1,
					SIMStatusDescription = 'AVAILABLE',
					Location = 'STOCKROOM'
				WHERE SIMID = @svc_SIMID;

				UPDATE tblirdetail
				SET IRStatus = 1,
					IRStatusDescription = 'AVAILABLE'
				WHERE IRIDNo = @v_IRIDNo;

			ELSEIF @svc_JobType = 4 THEN
				-- PULLOUT: Success -> Negative
				-- Pull-out did not actually happen; device remains installed at merchant.
				UPDATE tblirdetail
				SET IRActive = 1,
					IRStatus = 7,
					IRStatusDescription = 'INSTALLED',
					TerminalID = @svc_TerminalID,
					SIMID = @svc_SIMID
				WHERE IRIDNo = @v_IRIDNo;

				UPDATE tblfsrdetail
				SET ServiceStatus = 7,
					ServiceStatusDescription = 'INSTALLED'
				WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo;

				UPDATE tblservicingdetail
				SET JobTypeStatusDescription = 'COMPLETED',
					ServiceStatus = 7,
					ServiceStatusDescription = 'INSTALLED'
				WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo;

				UPDATE tblterminaldetail
				SET LastIRIDNo = @v_IRIDNo
				WHERE TerminalID = @svc_TerminalID;

				UPDATE tblsimdetail
				SET LastIRIDNo = @v_IRIDNo
				WHERE SIMID = @svc_SIMID;

			ELSEIF @svc_JobType = 7 THEN
				-- REPLACEMENT: Success -> Negative
				-- Swap did not take; merchant stays on the ORIGINAL device, replacement device goes back to stock.
				UPDATE tblirdetail
				SET TerminalID = @svc_TerminalID,
					SIMID = @svc_SIMID,
					IRStatus = 7,
					IRStatusDescription = 'INSTALLED'
				WHERE IRIDNo = @v_IRIDNo;

				UPDATE tblservicingdetail
				SET JobTypeStatusDescription = 'COMPLETED',
					ServiceStatus = 7,
					ServiceStatusDescription = 'INSTALLED'
				WHERE ServiceNo = @ServiceNo AND IRIDNo = @v_IRIDNo;

				IF @svc_RepTerminalID > 0 THEN
					UPDATE tblterminaldetail
					SET TerminalStatus = 1,
						TerminalStatusDescription = 'AVAILABLE',
						Location = 'STOCKROOM'
					WHERE TerminalID = @svc_RepTerminalID;
				END IF;

				IF @svc_RepSIMID > 0 THEN
					UPDATE tblsimdetail
					SET SIMStatus = 1,
						SIMStatusDescription = 'AVAILABLE',
						Location = 'STOCKROOM'
					WHERE SIMID = @svc_RepSIMID;
				END IF;
			END IF;
		END IF;
		
	ELSEIF (p_SearchBy = 'ERM Settlement Report')
	THEN
		# cleanup
		DELETE FROM tbltempsettlement
		WHERE 
		    UPPER(TRIM(Field0)) IN (
			'SETTLEMENT REPORT',
			'MERCHANT :',
			'MERCHANT ID :',
			'TERMINAL ID :',
			'SETTLEMENT DATE :',
			'BATCH NO :',
			'REFERENCE NO :',
			'TERMINAL SERIAL NUMBER :',
			'RECEIPT SOURCE :',
			'NO'
		    )
		    OR UPPER(TRIM(Field1)) = 'MERCHANT'
		    OR TRIM(Field0) = '' 
		    OR TRIM(Field1) = ''
		    OR TRIM(Field0) = '-' 
		    OR TRIM(Field1) = '-';
		    
		# update TransTypeID and TransType
		UPDATE tbltempsettlement AS t
		JOIN tbltranstype AS a 
		  ON t.Field2 LIKE CONCAT('%', a.Prefix, '%')
		  AND a.isActive = 1
		SET 
		    t.TransType = a.Description,
		    t.TransTypeID = a.TransTypeID
		WHERE (t.TransType IS NULL OR t.TransType = '')
		   OR (t.TransTypeID IS NULL OR t.TransTypeID = 0);
		
		# update trans date
		UPDATE tbltempsettlement
		SET TransDate = STR_TO_DATE(TRIM(Field5), '%d-%b-%Y')
		WHERE 
		    Field5 REGEXP '^[0-9]{2}-[A-Za-z]{3}-[0-9]{4}$'
		    AND STR_TO_DATE(TRIM(Field5), '%d-%b-%Y') IS NOT NULL
		    AND (TransDate IS NULL OR TransDate = '0000-00-00');
    
		# update trans amount   
		UPDATE tbltempsettlement
		SET 
		    Field10 = CASE
			WHEN Field10 REGEXP '^[0-9]+(\\.[0-9]+)?$' THEN Field10
			ELSE '0'
		    END,
		    
		    Amount = CASE
			WHEN Field10 REGEXP '^[0-9]+(\\.[0-9]+)?$' THEN CAST(Field10 AS DECIMAL(15,2))
			ELSE 0
		    END
		WHERE 
		    Field10 IS NULL 
		    OR Field10 = '' 
		    OR Field10 NOT REGEXP '^[0-9]+(\\.[0-9]+)?$'
		    OR Amount IS NULL 
		    OR Amount = 0
		    OR Amount = 0.00;
		
		# update MerchantName and TID
		UPDATE tbltempsettlement
		SET 
		MerchantName = funcGetDesc('Search', 'CleanUp MerchantName', Field1),
		TID = TRIM(Field3)
		WHERE
		(MerchantName IS NULL OR MerchantName = '' OR MerchantName = '0')
		OR (TID IS NULL OR TID = '' OR TID = '0');
		
		# delete testing
		DELETE FROM tbltempsettlement
		WHERE UPPER(TRIM(MerchantName)) LIKE '%TEST%';
		
		# delete test TID
		#DELETE FROM tbltempsettlement
		#WHERE UPPER(TRIM(Field1)) IN ('30285051', '30285052', '30285019', '30285012', '30285006', '30046224', '30285013', '30285018', '50285024', '30285018', '30285020');
		 
		# delete below 10.00
		#DELETE FROM tbltempsettlement
		#WHERE 
		#    Field10 REGEXP '^[0-9]+(\\.[0-9]+)?$'
		#    AND CAST(UPPER(TRIM(Field10)) AS DECIMAL(15,2)) <= 10;
		    
	ELSEIF (p_SearchBy = 'Service Apps Info')
	THEN	
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
		SET v_AppVersion = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		SET v_AppCRC = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));		

		UPDATE tblservicingdetail
		SET 		
		AppVersion = v_AppVersion,
		AppCRC = v_AppCRC	
		WHERE (ServiceNo = v_ServiceNo AND IRIDNo = v_IRIDNo);
		
	ELSEIF (p_SearchBy = 'Zoning')
	THEN	
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		SET @Cluster = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));		
		SET @Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));		
		SET @Area = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));		
		SET @CityMunicipal = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));		
		SET @ZoneName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		SET @SLA = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));		
		
		UPDATE tblzoning
		SET		
		Cluster = @Cluster, 
		Region = @Region, 
		`Area` = @Area, 
		CityMunicipal = @CityMunicipal, 
		ZoneName = @ZoneName,
		SLA = @SLA
		WHERE (ZoneID = v_ID);
		
	ELSEIF (p_SearchBy = 'Zoning Alias')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
		SET @AliasName = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
		SET @OfficialName = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
		SET @Priority = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 4)) AS UNSIGNED INTEGER);
		SET @IsWholeWord = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 5)) AS UNSIGNED INTEGER);
		SET @IsActive = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 6)) AS UNSIGNED INTEGER);

		UPDATE tblzoningalias
		SET
		    AliasName = @AliasName,
		    OfficialName = @OfficialName,
		    Priority = @Priority,
		    IsWholeWord = @IsWholeWord,
		    IsActive = @IsActive
		WHERE (AliasID = v_ID);
		
		ELSEIF (p_SearchBy = 'Location')
		THEN
		    SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
		    SET @Code = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
		    SET @Description = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
		    SET @isReleased = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 4)) AS UNSIGNED INTEGER);
		    SET @isTerminalReleased = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 5)) AS UNSIGNED INTEGER);
		    SET @isSIMReleased = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 6)) AS UNSIGNED INTEGER);
		    SET @isDeploy = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 7)) AS UNSIGNED INTEGER);
		    SET @isReturn = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 8)) AS UNSIGNED INTEGER);

		    UPDATE tbllocation
		    SET
			CODE = @Code,
			DESCRIPTION = @Description,
			isReleased = @isReleased,
			isTerminalReleased = @isTerminalReleased,
			isSIMReleased = @isSIMReleased,
			isDeploy = @isDeploy,
			isReturn = @isReturn
		    WHERE LocationID = v_ID;
	    
	ELSEIF (p_SearchBy = 'Merchant-ZoneID')
	THEN
	   SET @IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
	   SET @MerchantName = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
	   SET @TID = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
	   SET @MID = TRIM(SPLIT_STRING(p_SearchValue, '|', 4));
	   SET @Address = TRIM(SPLIT_STRING(p_SearchValue, '|', 5));
	   SET @Area = TRIM(SPLIT_STRING(p_SearchValue, '|', 6));
	   SET @City  = TRIM(SPLIT_STRING(p_SearchValue, '|', 7));

	   SET @MerchantID = 0;
	   SET @ZoneID = 0;
	   
	   # get MerchantID
	   SELECT IFNULL(a.MerchantID, 0)
	   INTO @MerchantID
	   FROM tblirdetail a
	   WHERE a.IRNo = @IRNo
	   AND a.MerchantName = @MerchantName
	   AND a.TID = @TID
	   AND a.MID = @MID
	   LIMIT 1;
	   
	   SET @search = CONCAT(@Address, ',', @City);				
	   SET @ZoneID = COALESCE(funcGetZoneID(@search),0);
	   
	   IF (@MerchantID > 0 AND @ZoneID > 0)
	   THEN
		   UPDATE tblparticular
		   SET
		   ZoneID = @ZoneID
		   WHERE
		   ParticularID = @MerchantID;
	   
	   END IF;
	   
	ELSEIF (p_SearchBy = 'Servicing Activity Detail')
	THEN
	    SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	    SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
	    SET @EndDateTime = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
	    SET @ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
	    SET @ParticularName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

	    SET @PrevEndDateTime = NULL;
	    IF v_ID = 4 THEN  -- TermPrep only
		SELECT EndDateTime INTO @PrevEndDateTime
		FROM tblservicingactivitydetail
		WHERE ServiceNo = v_ServiceNo
		  AND ActivityID = v_ID
		ORDER BY ID DESC
		LIMIT 1;
	    END IF;

	    UPDATE tblservicingactivitydetail
	    SET EndDateTime = @EndDateTime,
		ParticularID = @ParticularID,
		ParticularName = @ParticularName,
		StartDateTime = IF(@PrevEndDateTime IS NOT NULL, @PrevEndDateTime, StartDateTime)
	    WHERE ServiceNo = v_ServiceNo
	      AND ActivityID = v_ID
	    ORDER BY ID DESC
	    LIMIT 1;
		    
	ELSEIF (p_SearchBy = 'Close Rescheduled Ticket')
	    THEN
	    SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
	    SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);

	    UPDATE tblservicingdetail
	    SET TicketStatus = 1
	    WHERE IRIDNo = v_IRIDNo AND ServiceNo = v_ServiceNo;  
	    
	ELSEIF (p_SearchBy = 'Particular-ZoneID')
	THEN
		SET @ParticularID = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
		SET @ZoneID = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
		
		UPDATE tblparticular
		   SET
		   ZoneID = @ZoneID
		   WHERE
		   ParticularID = @ParticularID;
		  
	ELSEIF (p_SearchBy = 'Service Override')
	THEN
		SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);
		SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 3)) AS UNSIGNED INTEGER);
		SET @BillingTypeID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
		SET @SourceID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
		SET @CategoryID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
		SET @SubCategoryID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
		
		UPDATE tblservicingdetail
		SET
		BillingTypeID  = COALESCE(@BillingTypeID, 0),
		SourceID = COALESCE(@SourceID, 0),
		CategoryID = COALESCE(@CategoryID, 0),
		SubCategoryID = COALESCE(@SubCategoryID, 0)
		WHERE
		ServiceNo = v_ServiceNo
		AND IRIDNo = v_IRIDNo;
		 
     -- RAIDEN
     ELSEIF (p_SearchBy = 'Update Service Expenses Detail')
        THEN
            SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
            SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);
            SET v_ExpensesID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 3)) AS UNSIGNED INTEGER);
            SET v_TExpenses = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 4)) AS DECIMAL(12,2));
            SET @ExpensesDate = TRIM(SPLIT_STRING(p_SearchValue, '|', 5));

            UPDATE tblexpensestransdetail
            SET
                Amount = v_TExpenses,
                ExpensesDate = @ExpensesDate
            WHERE ServiceNo = v_ServiceNo
              AND TAIDNo = 0
              AND IRIDNo = v_IRIDNo
              AND ExpensesID = v_ExpensesID;

            UPDATE tblexpensestransmaster
            SET
                TotalAmount =
                (
                    SELECT COALESCE(SUM(Amount), 0)
                    FROM tblexpensestransdetail
                    WHERE ServiceNo = v_ServiceNo
                ),
                UpdatedDate = NOW()
            WHERE ServiceNo = v_ServiceNo;
		 
			END IF;				
			
		END IF; 
		
		#Andy
		IF (p_SearchBy = 'Multiple Save FSR' AND STRCMP(v_JobTypeDescription, "SVC REQ PULL-OUT") = 0)
		THEN
			IF (STRCMP(v_ActionMade, "SUCCESS") = 0)
			THEN
				-- derive TID/MID from the IRIDNo already provided, so no new
				-- parameters/parsing are needed from the caller
				SELECT TID, MID
				INTO v_TID, v_MID
				FROM tblirdetail
				WHERE IRIDNo = v_IRIDNo
				LIMIT 1;

				-- status/description stays scoped to the specific IRIDNo being processed
				UPDATE tblirdetail
				SET
				IRStatus = 11,
				IRStatusDescription = 'PULLED-OUT'
				WHERE IRIDNo = v_IRIDNo;

				-- reset SN/ID/IRActive scoped to TID+MID (physically gone -> clear all
				-- rows for this terminal/merchant, self-healing stale IRActive=1 leftovers)
				IF (v_TID IS NOT NULL AND v_MID IS NOT NULL) THEN
					UPDATE tblirdetail
					SET
					IRActive = 0,
					TerminalID = 0,
					TerminalSN = '-',
					SIMID = 0,
					SIMSN = '-'
					WHERE TID = v_TID
					AND MID = v_MID;
				END IF;

				-- Leak 1 fix: FSR/servicing status stays PULLED-OUT instead of being
				-- overwritten by the terminal's stock-status lookup
				IF (v_ServiceNo > 0 AND v_FSRNo > 0)
				THEN
					UPDATE tblfsrdetail
					SET
					ServiceStatus = 11,
					ServiceStatusDescription = 'PULLED-OUT'
					WHERE FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo;
				END IF;

				UPDATE tblservicingdetail
				SET
				ServiceStatus = 11,
				ServiceStatusDescription = 'PULLED-OUT'
				WHERE (ServiceNo = v_ServiceNo);

				-- ----------------------------------------------------
				-- update client
				-- ----------------------------------------------------
				UPDATE tblterminaldetail
				SET
				LastIRIDNo = 0
				WHERE
				TerminalID = v_TerminalID;

				UPDATE tblsimdetail
				SET
				LastIRIDNo = 0
				WHERE
				SIMID = v_SIMID;
				-- ----------------------------------------------------
				-- update client
				-- ----------------------------------------------------

			ELSEIF (STRCMP(v_ActionMade, "NEGATIVE") = 0)
			THEN
				-- Leak 2: on a FAILED pull-out, terminal/SIM still get pushed
				-- to whatever stock status/location the client sent, even
				-- though the device never actually left the merchant.
				IF (v_TerminalID > 0)
				THEN
					UPDATE tblterminaldetail
					SET
					TerminalStatus = 7,
					TerminalStatusDescription = 'INSTALLED',
					LocationID = 18,
					Location = 'PRODUCTION'
					WHERE TerminalID = v_TerminalID;
				END IF;

				IF (v_SIMID > 0)
				THEN
					UPDATE tblsimdetail
					SET
					SIMStatus = 7,
					SIMStatusDescription = 'INSTALLED',
					LocationID = 18,
					Location = 'PRODUCTION'
					WHERE SIMID = v_SIMID;
				END IF;

				IF (v_ServiceNo > 0 AND v_FSRNo > 0)
				THEN
					UPDATE tblfsrdetail
					SET
					ServiceStatus = 7,
					ServiceStatusDescription = 'INSTALLED'
					WHERE FSRNo = v_FSRNo AND ServiceNo = v_ServiceNo;
				END IF;
			END IF;
			
	ELSEIF (p_SearchBy = 'SyncID')
        THEN
		SET @SyncEntity = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
		SET @FieldKey = TRIM(SPLIT_STRING(p_SearchValue, '|', 2)); 
		SET @FieldValue = TRIM(SPLIT_STRING(p_SearchValue, '|', 3)); 
		
		SET @SyncIDRaw = COALESCE(@FieldValue, '');
		SET @SyncID = MD5(@SyncIDRaw);
		
		IF (@SyncEntity = 'Expenses Trans Master')
		THEn
			UPDATE tblexpensestransmaster
			SET
			SyncIDRaw = @SyncIDRaw,
			SyncID = @SyncID
			WHERE
			ExpensesNo = @FieldKey;
			
		elseIF (@SyncEntity = 'Expenses Trans Detail')
		THEN
			UPDATE tblexpensestransdetail
			SET
			SyncIDRaw = @SyncIDRaw,
			SyncID = @SyncID
			WHERE
			DetailID = @FieldKey;
		END IF;
		
        ELSEIF (p_SearchBy = 'Update Expenses Status')
        THEN
            SET @ExpensesNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
            SET @ExpensesStatus = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));

            UPDATE tblexpensestransmaster
            SET
                ExpensesStatus = @ExpensesStatus,
                UpdatedDate = NOW()
            WHERE ExpensesNo = @ExpensesNo
              AND isActive = 1;
		
	END IF;

COMMIT;
       
END */$$
DELIMITER ;

/* Procedure structure for procedure `spUpdateSIMDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spUpdateSIMDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spUpdateSIMDetail`(  

	p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(30) /* = NULL */ ,

	p_SearchValue VARCHAR(255) /* = NULL */

)
BEGIN  

 

DECLARE v_SIMID INTEGER;

DECLARE v_FEID INTEGER;

DECLARE v_BatchNo VARCHAR(45);

DECLARE v_SerialNo VARCHAR(45);

DECLARE v_Carrier VARCHAR(45);

DECLARE v_AssignedTo VARCHAR(45);

DECLARE v_Remarks VARCHAR(45);

DECLARE v_DeliveryDate VARCHAR(45);

DECLARE v_ReceiveDate VARCHAR(45);

DECLARE v_SIMStatus INTEGER;

DECLARE v_SIMStatusDescription VARCHAR(45);

START TRANSACTION;

IF p_StatementType = 'Update'  

THEN      

	# Split SearchValue

	#SELECT (CONCAT('p_SearchValue=', p_SearchValue));

	SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

	SET v_FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

	SET v_BatchNo = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,3));

	SET v_SerialNo = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,4));

	SET v_Carrier = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,5));

	SET v_AssignedTo = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,6));

	SET v_Remarks = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,7));

	SET v_DeliveryDate = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,8));

	SET v_ReceiveDate = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,9));

	SET v_SIMStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);

	SET v_SIMStatusDescription = ADD_DOUBLEQUOTE(SPLIT_STRING(p_SearchValue, '|' ,11));

			

	IF (p_SearchBy = 'SIM')

	THEN

		IF (LENGTH(v_SIMID) > 0)

		THEN

			UPDATE tblsimdetail

			SET

			FEID = v_FEID,

			BatchNo = v_BatchNo,

			SerialNo = v_SerialNo,

			Carrier = v_Carrier,

			AssignedTo = v_AssignedTo,

			Remarks = v_Remarks,

			DeliveryDate = v_DeliveryDate,

			ReceiveDate = v_ReceiveDate,

			SIMStatus = v_SIMStatus,

			SIMStatusDescription = v_SIMStatusDescription

			WHERE (SIMID = v_SIMID);

		END IF;

		

	END IF;			

			

END IF;  

COMMIT;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spUpdateStatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `spUpdateStatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spUpdateStatus`(  

IN p_StatementType VARCHAR(30) /* = NULL */ ,

IN p_MaintenanceType VARCHAR(50) /* = NULL */ ,

IN p_SearchBy VARCHAR(50) /* = NULL */ ,

IN p_SearchValue VARCHAR(50) /* = NULL */ ,

IN p_StatusID INTEGER /* = NULL */ ,

IN p_StatusDescription VARCHAR(50) /* = NULL */

)
BEGIN  

 DECLARE v_ID INTEGER;

 

	IF p_StatementType = 'Update'  

	THEN		

		IF (p_MaintenanceType = 'Master File')

		THEN

			IF (p_SearchBy = 'ProductID')

			THEN

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				UPDATE tblmasterfile SET  						

				StatusID = p_StatusID,

				StatusDescription = ADD_DOUBLEQUOTE(p_StatusDescription)

				WHERE ProductID = v_ID;  

			END IF;

            

		ELSEIF (p_MaintenanceType = 'Request Form')

		THEN

			IF (p_SearchBy = 'RequestID')

			THEN

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				UPDATE tblrequestformmaster SET  						

				ReqStatus = p_StatusID,

				ReqStatusDesc = ADD_DOUBLEQUOTE(p_StatusDescription)

				WHERE RequestID = v_ID;  

			END IF;

        

		ELSEIF (p_MaintenanceType = 'Receive Form')

		THEN

			IF (p_SearchBy = 'ReceiveID')

			THEN

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				UPDATE tblreceiveformmaster SET  						

				ReceiveStatus = p_StatusID,

				ReceiveStatusDesc = ADD_DOUBLEQUOTE(p_StatusDescription)

				WHERE ReceiveID = v_ID;  

			END IF;

		ELSEIF (p_MaintenanceType = 'IR Detail')

		THEN

			IF (p_SearchBy = 'IRNo')

			THEN				

				UPDATE tblirdetail SET  						

				IRStatus = p_StatusID,

				IRStatusDescription = ADD_DOUBLEQUOTE(p_StatusDescription)

				WHERE IRNo = p_SearchValue;

							

			ELSEIF (p_SearchBy = 'IRIDNo')

			THEN				

				UPDATE tblirdetail SET  						

				IRStatus = p_StatusID,

				IRStatusDescription = ADD_DOUBLEQUOTE(p_StatusDescription)

				WHERE IRIDNo = p_SearchValue;		  

			END IF;

            

		ELSEIF (p_MaintenanceType = 'Terminal Detail')

		THEN

			IF (p_SearchBy = 'TerminalID')

			THEN			

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				UPDATE tblterminaldetail SET  						

				TerminalStatus = p_StatusID,

				TerminalStatusDescription = ADD_DOUBLEQUOTE(p_StatusDescription)

				WHERE TerminalID = v_ID;  

			END IF;  

            

		ELSEIF (p_MaintenanceType = 'SIM Detail')

		THEN

			IF (p_SearchBy = 'SIMID')

			THEN			

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				UPDATE tblsimdetail SET  						

				SIMStatus = p_StatusID,

				SIMStatusDescription = ADD_DOUBLEQUOTE(p_StatusDescription)

				WHERE SIMID = v_ID;  

			END IF; 

           

		ELSEIF (p_MaintenanceType = 'User Log')

		THEN

			IF (p_SearchBy = 'UserID')

			THEN			

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				UPDATE tbluser SET  						

				LogStatus = p_StatusID,

				LogStatusDesc = p_StatusDescription

				WHERE UserID = v_ID;  

			END IF;  

					

		ELSEIF (p_MaintenanceType = 'TA Detail')

		THEN

			IF (p_SearchBy = 'TAIDNo')

			THEN			

				SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

				UPDATE tblterminalallocation SET  						

				ServiceTypeStatus = p_StatusID,

				ServiceTypeStatusDescription = ADD_DOUBLEQUOTE(p_StatusDescription)

			WHERE TAIDNo = v_ID;

			END IF;

	END IF; 

END IF;  

END */$$
DELIMITER ;

/* Procedure structure for procedure `spUpdateZoneID` */

/*!50003 DROP PROCEDURE IF EXISTS  `spUpdateZoneID` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spUpdateZoneID`()
BEGIN

    DECLARE vDone INT DEFAULT 0;
    DECLARE vParticularID INT;
    DECLARE vAddress TEXT;
    DECLARE vProvince TEXT;
    DECLARE vZoneID INT;
    DECLARE vCounter INT DEFAULT 0;
    DECLARE vTotal INT DEFAULT 0;
    
    DECLARE vClientID INT DEFAULT 21;
    DECLARE vIsActive INT DEFAULT 1;
    DECLARE vLocationID INT DEFAULT 18;
    DECLARE vStatus INT DEFAULT 7;

    DECLARE cur CURSOR FOR
        
        /*
        SELECT ParticularID, Address
        FROM tblparticular
        WHERE ParticularTypeID = 1
          AND IsActive = 1
        ORDER BY ParticularID;   
        */
        SELECT
	c.ParticularID,
	c.Address,
	d.Province
	FROM
	tblterminaldetail a
	LEFT JOIN tblirdetail b ON a.TerminalID = b.TerminalID
	LEFT JOIN tblparticular c ON b.MerchantID = c.ParticularID
	LEFT JOIN tblregiondetail d ON c.RegionID = d.RegionID
	WHERE
	a.isActive = vIsActive
	AND a.LocationID = vLocationID
	AND a.TerminalStatus = vStatus
	AND a.ClientID = vClientID
	AND b.MerchantID IS NOT NULL; 

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET vDone = 1;

    /*	
    SELECT COUNT(*)
    INTO vTotal
    FROM tblparticular
    WHERE ParticularTypeID = 1
      AND IsActive = 1;
    */  
    
	SELECT
	COUNT(*) INTO vTotal
	FROM
	tblterminaldetail a
	LEFT JOIN tblirdetail b ON a.TerminalID = b.TerminalID
	LEFT JOIN tblparticular c ON b.MerchantID = c.ParticularID
	LEFT JOIN tblregiondetail d ON c.RegionID = d.RegionID
	WHERE
	a.isActive = vIsActive
	AND a.LocationID = vLocationID
	AND a.TerminalStatus = vStatus
	AND a.ClientID = vClientID
	AND b.MerchantID IS NOT NULL; 

    DROP TABLE IF EXISTS tmpProgress;

    CREATE TABLE tmpProgress
    (
        CounterNo INT,
        ParticularID INT,
        Address TEXT,
        Province TEXT,
        FullSearch TEXT,
        ZoneID INT,
        Progress VARCHAR(100)
    );

    OPEN cur;

    read_loop: LOOP

        FETCH cur INTO vParticularID, vAddress, vProvince;

        IF vDone = 1 THEN
            LEAVE read_loop;
        END IF;

        SET vCounter = vCounter + 1;

	SET @search = CONCAT(vAddress,",", vProvince);
        SET vZoneID = COALESCE(funcGetZoneID(@search),0);

        UPDATE tblparticular
        SET ZoneID = vZoneID
        WHERE ParticularID = vParticularID;

        INSERT INTO tmpProgress
            (
                CounterNo,
                ParticularID,
                Address,
                Province,
                FullSearch,
                ZoneID,
                Progress
            )
            VALUES
            (
                vCounter,
                vParticularID,
                vAddress,
                vProvince,
                @search,
                vZoneID,
                CONCAT(
                    'Processing ',
                    vCounter,
                    ' of ',
                    vTotal,
                    ' (',
                    ROUND(vCounter * 100 / vTotal,2),
                    '%)'
                )
            );

    END LOOP;

    CLOSE cur;

    /* Debug Output */
    SELECT *
    FROM tmpProgress
    ORDER BY CounterNo;

    /* Summary */
    SELECT
        vCounter AS TotalProcessed,
        vTotal AS TotalRecords,
        ROUND(vCounter * 100 / vTotal,2) AS PercentCompleted,
        NOW() AS FinishedDate;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spUserInsertUpdate` */

/*!50003 DROP PROCEDURE IF EXISTS  `spUserInsertUpdate` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spUserInsertUpdate`(  

p_UserID INTEGER,  

p_UserName VARCHAR(50),

p_Password VARCHAR(50),

p_FullName VARCHAR(50),

p_UserType VARCHAR(20),

p_StatementType NVARCHAR(20) /* = NULL */

)
BEGIN  

IF p_StatementType = 'Insert'  

	THEN  

		INSERT INTO tbluser(UserID, UserName, PASSWORD, FullName, UserType) 

			  VALUES(p_UserID, p_UserName, p_Password, p_FullName, p_UserType);  

	END IF;  

IF p_StatementType = 'Update'  

	THEN  

		UPDATE tbluser SET  

					   UserName = p_UserName,

					   PASSWORD = p_Password,

					   FullName = p_FullName,

					   UserType = p_UserType					   	

		WHERE UserID = p_UserID;  

	END IF;  

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewAdvanceDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewAdvanceDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewAdvanceDetail`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(255) /* = NULL */ ,

	p_SearchValue LONGTEXT /* = NULL */

)
BEGIN
	DECLARE v_ID INTEGER;

	DECLARE v_Type INTEGER;

	DECLARE v_ClientID INT;

	DECLARE v_ParticularID INTEGER;

	DECLARE v_MerchantID INTEGER;
	
	DECLARE v_DispatcherID INT;

	DECLARE v_InvoiceID INTEGER;

	DECLARE v_FromInvoiceID INTEGER;

	DECLARE v_ToInvoiceID INTEGER;

	DECLARE v_FSRNo INTEGER;

	DECLARE v_ServiceNo INTEGER;

	DECLARE v_IRIDNo INTEGER;

	

	DECLARE v_TempQuery VARCHAR(200);

	DECLARE v_SearchQuery VARCHAR(200);

	DECLARE v_SearchString VARCHAR(200);

	DECLARE v_Description VARCHAR(45);

	DECLARE v_DateFrom VARCHAR(45);

	DECLARE v_DateTo VARCHAR(45);

	DECLARE v_CurrentDate VARCHAR(45);

	
	DECLARE v_JobType INTEGER;
	
	DECLARE v_JobTypeStatusDescription VARCHAR(100); # eg. PENDING/PROCESSING/COMPLETED

	DECLARE v_ServiceJobTypeDescription VARCHAR(100); # eg. INSTALLATION/SERVICING.... 
	
	DECLARE v_ServiceResult VARCHAR(100); # eg. SUCCESS/NEGATIVE
   
	DECLARE v_DateFilter VARCHAR(100); # eg. TODAY/RANGE

	DECLARE v_IncludeBillable VARCHAR(45);
	
	DECLARE v_FSRMode VARCHAR(45);
   
	DECLARE v_FEID INTEGER;
	
	DECLARE v_DispatchID INTEGER;
	
	DECLARE v_RegionType INTEGER;
	
	DECLARE v_RegionID INTEGER;
	
	DECLARE v_Region VARCHAR(45);
	
	DECLARE v_LocationID INT;
	
	DECLARE v_StatusID INT;
	
	DECLARE v_Year VARCHAR(45);
	
	DECLARE v_MonthName VARCHAR(45);
	
	DECLARE v_CurrentMonth INT;
	
	DECLARE v_ActionMade VARCHAR(45);
	
	DECLARE v_Temp VARCHAR(100);
	
	DECLARE v_isActive INT;
	DECLARE v_OffSetFrom INTEGER;
	DECLARE v_OffSetTo INTEGER;
	DECLARE v_OffSet INTEGER;
	
	DECLARE v_MobileID INTEGER;
	DECLARE v_isFSR INTEGER;
	
	DECLARE v_TID VARCHAR(45);
	DECLARE v_MID VARCHAR(45);
	DECLARE v_MerchantName VARCHAR(45);
	
	DECLARE v_MSPNo INTEGER;
	
	DECLARE v_TATStatus VARCHAR(45);
	
	DECLARE v_TerminalTypeID INTEGER;
	DECLARE v_TerminalModelID INTEGER;
	
	DECLARE v_RequestType VARCHAR(100);
	
	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

	DECLARE p_TempQuery LONGTEXT;

	DECLARE p_INSERT LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN
                IF (p_SearchBy = 'TimeSheet Terminal')

		THEN

			SELECT

				TID AS ID,

				TerminalID,

				TerminalName

			FROM

				tblterminal

			WHERE (ACTIVE > 0)

			ORDER BY OrderDisplay;
		ELSEIF (p_SearchBy = 'Country')	

		THEN	

			SELECT 

				CountryID AS ID,

				Country

			FROM

			tblcountry

			WHERE (isActive > 0)

			ORDER BY Country;
			
		ELSEIF (p_SearchBy = 'Location')
		
		THEN
		    SELECT
			LocationID AS ID,
			DESCRIPTION AS `Description`
		    FROM tbllocation
		    WHERE (isActive > 0);
			
