				SET p_WHERE = CONCAT(p_WHERE, "'", v_JobTypeStatusDescription, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'b.ServiceNo,\n'

							"JSON_OBJECT(

							'JobType', IFNULL_STRING_ONLY(a.JobType),

							'ServiceJobTypeDescription', IFNULL_STRING_ONLY(a.ServiceJobTypeDescription),

							'ProcessedBy', IFNULL_STRING_ONLY(b.ProcessedBy),

							'TInstallation', IFNULL_STRING_ONLY(SUM(CASE WHEN b.JobType = 1 THEN 1 ELSE 0 END)),

							'TReprogramming', IFNULL_STRING_ONLY(SUM(CASE WHEN b.JobType = 3 THEN 1 ELSE 0 END)),

							'TPullout', IFNULL_STRING_ONLY(SUM(CASE WHEN b.JobType = 4 THEN 1 ELSE 0 END)),

							'TServicing', IFNULL_STRING_ONLY(SUM(CASE WHEN b.JobType = 6 THEN 1 ELSE 0 END)),

							'TReplacement', IFNULL_STRING_ONLY(SUM(CASE WHEN b.JobType = 7 THEN 1 ELSE 0 END))

							) AS detail_info\n"

							"FROM 

							tblservicetype a

							LEFT JOIN tblservicingdetail AS b ON a.JobType = b.JobType");	
				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
				IF (LENGTH(p_WHERE) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

				END IF;
				SET p_SQL = REPLACE(p_SQL, '"', "'");

				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('After:p_SQL = ', p_SQL);	
				SET p_GROUPBY = 'b.ProcessedBy';
				IF (LENGTH(p_GROUPBY) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

					SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

				END IF;
				SET p_ORDERBY = '';
				IF (LENGTH(p_ORDERBY) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

					SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

				END IF;
				#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT(':p_SQL = ', p_SQL);
				SET @QUERY = p_SQL;
				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;
		ELSEIF (p_SearchBy = 'eFSR Diagnostic')

		THEN

			# Split SearchValue

			#SELECT (CONCAT('p_SearchValue=', p_SearchValue));            			

			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);			

						

			#SELECT (CONCAT('v_IRNo=', v_IRNo));
			SET p_WHERE = '';            
			IF (v_ServiceNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'm.ServiceNo = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ServiceNo);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (v_FSRNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'm.FSRNo = ');

				SET p_WHERE = CONCAT(p_WHERE, v_FSRNo);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	
			IF (v_ServiceNo > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL,'SELECT');

				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_STRING_ONLY(a.IRNo) AS IRNo,

							IFNULL_STRING_ONLY(b1.`Name`) AS MerchantName,

							IFNULL_NUMERIC(i.IRIDNo) AS IRIDNo,

							IFNULL_STRING_ONLY(i.TID) AS TID,

							IFNULL_STRING_ONLY(i.MID) AS MID,

							IFNULL_STRING_ONLY(b2.`Name`) AS ClientName,							

							IFNULL_STRING_ONLY(b3.`Name`) AS FEName,

							IFNULL_STRING_ONLY(j.FSRDate) AS FSRDate,

							IFNULL_STRING_ONLY(j.FSRRefNo) AS FSRRefNo,

							IFNULL_NUMERIC(j.FSRNo) AS FSRNo,

							IFNULL_STRING_ONLY(b1.ContactPerson) AS ContactPerson,

							IFNULL_STRING_ONLY(b1.Address) AS Address,														

							IFNULL_NUMERIC(a.ServiceNo) AS ServiceNo,							

							IFNULL_STRING_ONLY(a.RequestNo) AS RequestNo,

							IFNULL_STRING_ONLY(a.JobTypeSubDescription) AS JobTypeSubDescription,

							IFNULL(j.Signature1, "-") AS Signature1,

							IFNULL(j.Signature2, "-") AS Signature2,

							IFNULL_NUMERIC(m.TypeID) AS TypeID,

							IFNULL_STRING_ONLY(m.TypeDescription) AS SelectionDescription,

							IFNULL_NUMERIC(m.SelectionID) AS SelectionID,

							IFNULL_STRING_ONLY(m.Description) AS Description,

							IFNULL_STRING_ONLY(m.SelectedValue) AS SelectedValue,

							IFNULL_STRING_ONLY(g1.ServiceJobTypeDescription) AS ServiceJobTypeDescription,

							IFNULL_STRING_ONLY(a.ReqInstallationDate) AS ReqInstallationDate,

							IFNULL_STRING_ONLY(a.ServiceDate) AS ServiceDate,

							IFNULL_STRING_ONLY(a.ServiceReqDate) AS ServiceReqDate,
							
							IFNULL_STRING_ONLY(a.CustomerName) AS ServiceCustomerName

							FROM

							tblservicingdetail AS a

							LEFT JOIN tblparticular AS b1 ON a.MerchantID = b1.ParticularID AND b1.ParticularTypeID = 1

							LEFT JOIN tblparticular AS b2 ON a.ClientID = b2.ParticularID AND b2.ParticularTypeID = 2

							LEFT JOIN tblparticular AS b3 ON a.FEID = b3.ParticularID AND b3.ParticularTypeID = 3							

							LEFT JOIN tblservicetype AS g1 ON a.JobType = g1.JobType						

							LEFT JOIN tblirdetail AS i ON a.IRIDNo = i.IRIDNo

							LEFT JOIN tblfsrdetail AS j ON a.IRIDNo = j.IRIDNo AND a.ServiceNo = j.ServiceNo

							LEFT JOIN tbldiagnosticdetail AS m ON j.FSRNo = m.FSRNo AND j.ServiceNo = m.ServiceNo');
			END IF;
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;
			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET p_GROUPBY = '';		

			IF (LENGTH(p_GROUPBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

			END IF;
			SET p_ORDERBY = '';
			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;
			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;
		ELSEIF (p_SearchBy = 'Profile Mapping')	

