				'MapTo', a.MapTo,

				'ColumnIndex', a.ColumnIndex

				) AS detail_info

			FROM

			tblmapping a

			WHERE (a.Type = 'IR' AND a.isAddToJSON AND a.isActive > 0);
		ELSEIF (p_SearchBy = 'Incoming Job Order Count Per HelpDesk/Merchant List')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET p_WHERE = '';
			IF (v_ID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.FEID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	
			#ServiceTypeActive

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceTypeActive > 0 ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			# filter for job type status

			SET v_JobTypeStatusDescription = "PENDING";

			IF (STRCMP(v_JobTypeStatusDescription, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.JobTypeStatusDescription = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_JobTypeStatusDescription, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			# get current data

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.ServiceReqDate', ' ', '<', ' ');

			SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'b.FEID,\n'

							"JSON_OBJECT(

							'JobType', IFNULL_STRING_ONLY(a.JobType),

							'ServiceJobTypeDescription', IFNULL_STRING_ONLY(a.ServiceJobTypeDescription),

							'FEName', IFNULL_STRING_ONLY(d.Name),

							'MerhantName', IFNULL_STRING_ONLY(c.Name),

							'ProcessedAt', IFNULL_FORMAT_DATETIME_AMPM(b.ProcessedDateTime),

							'ProcessedBy', IFNULL_STRING_ONLY(b.ProcessedBy),

							'IRNo', IFNULL_STRING_ONLY(b.IRNo),

							'TID', IFNULL_STRING_ONLY(f.TID),

							'MID', IFNULL_STRING_ONLY(f.MID),

							'Address', IFNULL_STRING_ONLY(c.Address),

							'ContactPerson', IFNULL_STRING_ONLY(c.ContactPerson),

							'ContactNumber', IFNULL_STRING_ONLY(c.ContactNumber),

							'Region', IFNULL_STRING_ONLY(e.Region),

							'Email', IFNULL_STRING_ONLY(c.Email),

							'ReqInstallationDate', IFNULL_STRING_ONLY(b.ReqInstallationDate),

							'ServiceReqDate', IFNULL_STRING_ONLY(b.ServiceReqDate),

							'TDateDiff', IFNULL_STRING_ONLY(DATEDIFF(",ADD_SINGLEQUOTE(v_DateFrom),", b.ServiceReqDate))

							) AS detail_info\n"

							"FROM 

							tblservicetype a

							LEFT JOIN tblservicingdetail AS b ON a.JobType = b.JobType 

							LEFT JOIN tblparticular AS c ON b.MerchantID = c.ParticularID AND c.ParticularTypeID = 1

							LEFT JOIN tblparticular AS d ON b.FEID = d.ParticularID AND d.ParticularTypeID = 3

							LEFT JOIN tblregion AS e ON c.RegionType = e.RegionID

							LEFT JOIN tblirdetail AS f ON b.IRIDNo = f.IRIDNo");	
				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
				IF (LENGTH(p_WHERE) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

				END IF;
				SET p_SQL = REPLACE(p_SQL, '"', "'");

				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('After:p_SQL = ', p_SQL);	
				SET p_GROUPBY = 'f.IRIDNo';
				IF (LENGTH(p_GROUPBY) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

					SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

				END IF;
				SET p_ORDERBY = 'b.FEID, b.ServiceReqDate';
				IF (LENGTH(p_ORDERBY) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

					SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

				END IF;
				#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT(':p_SQL = ', p_SQL);
				SET @QUERY = p_SQL;
				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;
		ELSEIF (p_SearchBy = 'Mobile List')	

		THEN	

			SELECT 

			a.TID AS MobileID,

			IFNULL_STRING_ONLY(a.TerminalID) AS MobileTerminalID,

			JSON_OBJECT('MobileID', IFNULL_STRING_ONLY(a.TID),

			'MobileTerminalID', IFNULL_STRING_ONLY(a.TerminalID),

			'MobileTerminalName', IFNULL_STRING_ONLY(a.TerminalName),

			'UserID', IFNULL_STRING_ONLY(b.UserID),

			'ParticularID', IFNULL_STRING_ONLY(c.ParticularID),

			'FullName', IFNULL_STRING_ONLY(c.Name)

			) AS detail_info

			FROM tblterminal a

			LEFT JOIN tbluser AS b ON a.TID = b.MobileID

			LEFT JOIN tblparticular AS c ON b.ParticularID = c.ParticularID 

			WHERE

			a.Active > 0 AND b.UserID > 0

			ORDER BY c.Name;
		ELSEIF (p_SearchBy = 'Completed Diagnostic List')	

		THEN	

			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SELECT 

			a.DiagnosticID AS DiagnosticID,

			a.SelectionID AS SelectionID,

			JSON_OBJECT('DiagnosticID', IFNULL_STRING_ONLY(a.DiagnosticID),

			'SelectionID', IFNULL_STRING_ONLY(a.SelectionID),

			'Description', IFNULL_STRING_ONLY(a.Description),

			'SelectedValue', IFNULL_STRING_ONLY(a.SelectedValue)) AS detail_info

			FROM tbldiagnosticdetail a 

			LEFT JOIN tblselection AS b ON a.SelectionID = b.SelectionID

			WHERE a.FSRNo = v_FSRNo AND a.ServiceNo = v_ServiceNo;
		ELSEIF (p_SearchBy = 'Service TerminalSN History List')	

		THEN	

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT

			a.ServiceNo,
			JSON_OBJECT(
			"ServiceNo", IFNULL_NUMERIC(a.ServiceNo),		
			"FSRNo", IFNULL_NUMERIC(c.FSRNo),
			"ReqInstallationDate", IFNULL_FORMAT_DATE(a.ReqInstallationDate),
			"ServiceReqDate", IFNULL_FORMAT_DATE(a.ServiceReqDate),
			"TID", IFNULL_STRING_ONLY(b.TID),
			"MID", IFNULL_STRING_ONLY(b.MID),
			"IRNo", IFNULL_STRING_ONLY(a.IRNo),
			"MerchantName", funcGetDesc("Search", "Particular", a.MerchantID),
			"FSRDate", IFNULL_FORMAT_DATE(c.FSRDate),
			"FSRTime", IFNULL_FORMAT_TIME(c.FSRTime),
			"ActionMade", IFNULL_STRING_ONLY(c.ActionMade),
			"ServiceJobTypeDescription", IFNULL_STRING_ONLY(d.ServiceJobTypeDescription),		
			"TerminalSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.TerminalID)),			
			"SIMSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.SIMID)),			
			"ReplaceTerminalSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.ReplaceTerminalID)),			
			"ReplaceSIMSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.ReplaceSIMID)),			
			"JobTypeStatusDescription", IFNULL_STRING_ONLY(a.JobTypeStatusDescription)

			) AS detail_info

			FROM

			tblservicingdetail a

			LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

			LEFT JOIN tblfsrdetail AS c ON a.ServiceNo = c.ServiceNo

			LEFT JOIN tblservicetype AS d ON a.JobType = d.JobType

			WHERE

			a.TerminalID = v_ID
			OR a.ReplaceTerminalID = v_ID

			ORDER BY a.ServiceNo;
		ELSEIF (p_SearchBy = 'Service SIMSN History List')	

		THEN	

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SELECT

			a.ServiceNo,

			JSON_OBJECT(

			"ServiceNo", a.ServiceNo,
			
			"FSRNo", c.FSRNo,

			"ReqInstallationDate", a.ReqInstallationDate,

			"ServiceReqDate", a.ServiceReqDate,

			"TID", b.TID,

			"MID", b.MID,

			"IRNo", a.IRNo,

			"MerchantName", funcGetDesc("Search", "Particular", a.MerchantID),

			"FSRDate", c.FSRDate,

			"FSRTime", c.FSRTime,

			"ActionMade", IFNULL_STRING_ONLY(c.ActionMade),

			"ServiceJobTypeDescription", IFNULL_STRING_ONLY(d.ServiceJobTypeDescription),
			
			"TerminalSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.TerminalID)),
			
			"SIMSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.SIMID)),
			
			"ReplaceTerminalSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.ReplaceTerminalID)),
			
			"ReplaceSIMSN", IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.ReplaceSIMID)),
			
			"JobTypeStatusDescription", IFNULL_STRING_ONLY(a.JobTypeStatusDescription)

			) AS detail_info

			FROM

			tblservicingdetail a

			LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

			LEFT JOIN tblfsrdetail AS c ON a.ServiceNo = c.ServiceNo

			LEFT JOIN tblservicetype AS d ON a.JobType = d.JobType

			WHERE

			a.SIMID = v_ID
			OR a.ReplaceSIMID = v_ID

			ORDER BY a.ServiceNo;
		ELSEIF (p_SearchBy = 'eFSR Changes Mapping')	

		THEN	

			SELECT 

				a.MapID AS MapID,

				JSON_OBJECT(

				'MapID', a.MapID,

				'Description', a.Description,

				'MapFrom', a.MapFrom,

				'MapTo', a.MapTo,

				'TableName', a.TableName,

				'FieldName', a.FieldName,

				'FieldSearchKey', a.FieldSearchKey,
				
				'FieldType', a.FieldType,

				'MaxLimit', a.MaxLimit,
				
				'FieldNestedObj', a.FieldNestedObj,
				
				'FieldKeyValue', a.FieldKeyValue

				) AS detail_info

			FROM

			tblmapping a

			WHERE (a.Type = 'eFSR' AND a.isActive > 0);
		ELSEIF (p_SearchBy = 'eFSR Changes Service')	

		THEN	

			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			IF (v_ServiceNo > 0 && v_IRIDNo > 0)

			THEN

				SELECT 

				b.MapID AS MapID,

				JSON_OBJECT(

				'ID', b.ID,

				'MapID', b.MapID,

				'ServiceNo', b.ServiceNo,

				'IRIDNo', b.IRIDNo,

				'MerchantID', b.MerchantID,

				'Description', a.Description,

				'ChangeFrom', b.ChangeFrom,

				'ChangeTo', b.ChangeTo,

				'TableName', a.TableName,

				'FieldName', a.FieldName,

				'FieldSearchKey', a.FieldSearchKey,

				'MaxLimit', a.MaxLimit,
				
				'FieldType', a.FieldType

				) AS detail_info

				FROM

				tblmapping a

				LEFT JOIN tblservicechangesdetail AS b ON a.MapID = b.MapID

				WHERE (b.ServiceNo = v_ServiceNo AND b.IRIDNo = v_IRIDNo AND a.Type = 'eFSR' AND a.isActive > 0);

			
			ELSE

				SELECT 

				b.MapID AS MapID,

				JSON_OBJECT(

				'ID', b.ID,

				'MapID', b.MapID,

				'ServiceNo', b.ServiceNo,

				'IRIDNo', b.IRIDNo,

				'MerchantID', b.MerchantID,

				'Description', a.Description,

				'ChangeFrom', b.ChangeFrom,

				'ChangeTo', b.ChangeTo,

				'TableName', a.TableName,

				'FieldName', a.FieldName,

				'FieldSearchKey', a.FieldSearchKey,

				'MaxLimit', a.MaxLimit

				) AS detail_info

				FROM

				tblmapping a

				LEFT JOIN tblservicechangesdetail AS b ON a.MapID = b.MapID

				WHERE (b.isPosted = 0 AND a.Type = 'eFSR' AND a.isActive > 0);
			END IF;
