			IF (v_Description = 'Deploy')

			THEN

				SELECT 

				LocationID AS ID,

				DESCRIPTION AS `Description`

				FROM

				tbllocation

				WHERE (isDeploy > 0 AND isActive > 0);
			ELSEIF (v_Description = 'Return')

			THEN

				SELECT 

				LocationID AS ID,

				DESCRIPTION AS `Description`

				FROM

				tbllocation

				WHERE (isReturn > 0 AND isActive > 0);

			END IF;
		ELSEIF (p_SearchBy = 'Application Info List')	

		THEN

			SELECT

