			JSON_OBJECT(

			'TerminalTypeID', b.TerminalTypeID,

			'TerminalModelID', a.TerminalModelID,

			'TerminalType', b.Description,

			'TerminalModel', a.Description,

			'AppVersion', a.AppVersion,

			'AppCRC', a.AppCRC

			) AS detail_info

			FROM 

			tblterminalmodel a 

			LEFT JOIN tblterminaltype AS b ON a.TerminalTypeID = b.TerminalTypeID

			WHERE 
			a.isActive > 0
			AND (b.Type NOT IN (2, 3, 4)) #exclude terminal type dont need apps version/crc

			ORDER BY

			b.Description;
			
		ELSEIF (p_SearchBy = 'Diagnostic Master List')	
		THEN
			SELECT
			IFNULL_NUMERIC(a.DiagnosticID) AS ID,
			JSON_OBJECT(
			'DiagnosticID', IFNULL_NUMERIC(a.DiagnosticID),
			'Description', IFNULL_STRING_ONLY(a.Description),
			'TypeID', IFNULL_NUMERIC(a.TypeID),
			'FormatType', IFNULL_NUMERIC(a.FormatType)
			) AS detail_info
			FROM 
			tbldiagnosticmaster a 
			WHERE 
