			ORDER BY
			a.Description;
			
		ELSEIF (p_SearchBy = 'Diagnostic Detail List')	
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			IFNULL_NUMERIC(a.SelectionID) AS ID,
			JSON_OBJECT(
			'SelectionID', IFNULL_NUMERIC(a.SelectionID),
			'TypeID', IFNULL_NUMERIC(a.TypeID),
			'Description', IFNULL_STRING_ONLY(a.Description)
			) AS detail_info
			FROM 
			tblselection a 
			WHERE 
			a.TypeID = v_ID 
			AND a.isActive > 0;
			
		ELSEIF (p_SearchBy = 'Merchant Service Status List')	
		THEN
			SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_DispatchID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SET p_WHERE = '';			
			SET p_SQL = '';
			
			SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
				    'IFNULL_NUMERIC(a.ServiceNo) AS ID, ',
				    'JSON_OBJECT(',
					"'ServiceNo', IFNULL_NUMERIC(a.ServiceNo), ",
					"'FSRNo', IFNULL_NUMERIC(b.FSRNo), ",
					"'IRIDNo', IFNULL_NUMERIC(a.IRIDNo), ",
					"'MerchantID', IFNULL_NUMERIC(a.MerchantID), ",
					"'IRNo', IFNULL_STRING_ONLY(a.IRNo) ",
					') AS detail_info ',
					'FROM ',
					'tblservicingdetail a ',
					'LEFT JOIN tblfsrdetail AS b ON a.ServiceNo = b.ServiceNo '
					);
			
			# Filter
			SET p_SQL = CONCAT(
					p_SQL, ' ',
					'WHERE a.TicketStatus = 0', ' '
					);
					
			SET p_SQL = CONCAT(
					p_SQL, ' ',
					'AND a.isActive > 0', ' '
					);
					
			SET p_SQL = CONCAT(
					p_SQL, ' ',
					"AND a.JobTypeStatusDescription = 'COMPLETED'", ' '
					);
							
			IF (v_MerchantID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND a.MerchantID = ', v_MerchantID, ' '
					);
			END IF;
			
			IF (v_FEID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND a.FEID = ', v_FEID, ' '
					);
			END IF;
			
			IF (v_DispatchID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND a.DispatchID = ', v_DispatchID, ' '
					);
			END IF;
			
			SET p_SQL = CONCAT(
			    p_SQL,
			    'ORDER BY b.FSRNo ASC',
			    ';'
			);
			
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
			
		ELSEIF (p_SearchBy = 'Particular By Position Type List')	
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
	
			SELECT
			IFNULL_NUMERIC(a.ParticularID) AS ID,
			JSON_OBJECT(
			'ParticularID', IFNULL_NUMERIC(a.ParticularID),
			'FullName', IFNULL_STRING_ONLY(a.Name),
			'Position', IFNULL_STRING_ONLY(b.Description)
			) AS detail_info
			FROM tblparticular a 
			LEFT JOIN tblposition b ON a.PositionID = b.PositionID
			WHERE 
			b.PositionType = v_ID
			AND a.isActive > 0
			ORDER BY a.Name;
			
		ELSEIF (p_SearchBy = 'Service Summary')	
		THEN
			SET v_DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
	
			SELECT
			IFNULL_NUMERIC(st.JobType) AS ID,
			JSON_OBJECT(
			'JobType', IFNULL_NUMERIC(st.JobType),
			'ServiceJobTypeDescription', IFNULL_STRING_ONLY(st.ServiceJobTypeDescription),
			'Import', IFNULL_NUMERIC(xTable.Import),
			'Completed', IFNULL_NUMERIC(xTable.Completed),
			'Pending', IFNULL_NUMERIC(xTable.Pending),
			'Dispatch', IFNULL_NUMERIC(xTable.Dispatch),
			'Negative', IFNULL_NUMERIC(xTable.Negative)
			) AS detail_info
			FROM
			tblservicetype st
			LEFT JOIN 
			(SELECT 
				vw.JobType AS JobType,
				(SELECT	COUNT(*) FROM tblirdetail ir WHERE ir.IRStatus = 1 AND vw.JobType = 1 AND (ir.IRDate BETWEEN v_DateFrom AND v_DateTo)) AS `Import`,
				SUM(IF(vw.Request_Status = 'COMPLETED' AND vw.Service_Status IN ('INSTALLED', 'PULLED-OUT') AND vw.Service_Result = 'SUCCESS' AND vw.Service_Date BETWEEN v_DateFrom AND v_DateTo, 1, 0)) AS Completed, 
				SUM(IF(vw.Service_Status = 'ALLOCATED' AND vw.Service_Result = 'WAITING' AND Request_Date BETWEEN v_DateFrom AND v_DateTo, 1, 0)) AS Pending,
				SUM(IF(vw.Service_Status = 'DISPATCH'  AND vw.Service_Result = 'PENDING FSR' AND Request_Date BETWEEN v_DateFrom AND v_DateTo, 1, 0)) AS Dispatch,
				SUM(
					IF(
					    vw.Service_Result = 'NEGATIVE'
					    AND vw.Service_Date BETWEEN v_DateFrom AND v_DateTo
					    AND vw.Request_No NOT IN (
						SELECT DISTINCT Request_No
						FROM vw_service_info2
						WHERE Service_Result = 'SUCCESS'
					    ),
					    1,
					    0
					)
				    ) AS Negative
			FROM vw_service_info2 vw
			#WHERE 
			#vw.Service_Date BETWEEN v_DateFrom AND v_DateTo
			GROUP BY vw.JobType) AS xTable ON st.JobType = xTable.JobType
			WHERE
			st.isActive > 0
			ORDER BY
			st.SequenceDisplay;
				
		ELSEIF (p_SearchBy = 'Region Service Summary')	
		THEN
			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)); # eg. (PENDING, PROCESSING, COMPLETED...)
			SET v_DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			IF (v_JobTypeStatusDescription = 'PENDING' || v_JobTypeStatusDescription = 'PROCESSING')
			THEN
				SELECT
				IFNULL_NUMERIC(st.JobType) AS ID,
				JSON_OBJECT(
				'JobType', IFNULL_NUMERIC(st.JobType),
				'ServiceJobTypeDescription', IFNULL_STRING_ONLY(st.ServiceJobTypeDescription),
				'RegionType', IFNULL_STRING_ONLY(xTable.Prov_ID),
				'Region', IFNULL_STRING_ONLY(xTable.Province),
				'TInstallation', IFNULL_NUMERIC(xTable.TInstallation),
				'TReprogramming', IFNULL_NUMERIC(xTable.TReprogramming),
				'TPullOut', IFNULL_NUMERIC(xTable.TPullOut),
				'TServicing', IFNULL_NUMERIC(xTable.TServicing),
				'TReplacement', IFNULL_NUMERIC(xTable.TReplacement)
				) AS detail_info
				FROM
				tblservicetype st
				LEFT JOIN 
				(SELECT 
					vw.JobType AS JobType,
					vw.Prov_ID,
					vw.Province,
					vw.TID,
					SUM(IF(vw.Request_Status IN ('PENDING', 'PROCESSING') AND vw.Service_Result IN ('WAITING', 'PENDING FSR') AND vw.JobType = 1, 1, 0)) AS TInstallation,
					SUM(IF(vw.Request_Status IN ('PENDING', 'PROCESSING') AND vw.Service_Result IN ('WAITING', 'PENDING FSR') AND vw.JobType = 3, 1, 0)) AS TReprogramming,
					SUM(IF(vw.Request_Status IN ('PENDING', 'PROCESSING') AND vw.Service_Result IN ('WAITING', 'PENDING FSR') AND vw.JobType = 4, 1, 0)) AS TPullOut,
					SUM(IF(vw.Request_Status IN ('PENDING', 'PROCESSING') AND vw.Service_Result IN ('WAITING', 'PENDING FSR') AND vw.JobType = 6, 1, 0)) AS TServicing,
					SUM(IF(vw.Request_Status IN ('PENDING', 'PROCESSING') AND vw.Service_Result IN ('WAITING', 'PENDING FSR') AND vw.JobType = 7, 1, 0)) AS TReplacement
				FROM vw_service_info2 vw
				GROUP BY vw.Prov_ID) AS xTable ON st.JobType = xTable.JobType
				WHERE
				st.isActive > 0
				AND xTable.Prov_ID > 0
				AND xTable.TID != "-"
				GROUP BY
				xTable.Prov_ID
				ORDER BY
				st.SequenceDisplay;
			ELSE
				SELECT
				IFNULL_NUMERIC(st.JobType) AS ID,
				JSON_OBJECT(
				'JobType', IFNULL_NUMERIC(st.JobType),
				'ServiceJobTypeDescription', IFNULL_STRING_ONLY(st.ServiceJobTypeDescription),
				'RegionType', IFNULL_STRING_ONLY(xTable.Prov_ID),
				'Region', IFNULL_STRING_ONLY(xTable.Province),
				'TInstallation', IFNULL_NUMERIC(xTable.TInstallation),
				'TReprogramming', IFNULL_NUMERIC(xTable.TReprogramming),
				'TPullOut', IFNULL_NUMERIC(xTable.TPullOut),
				'TServicing', IFNULL_NUMERIC(xTable.TServicing),
				'TReplacement', IFNULL_NUMERIC(xTable.TReplacement)
				) AS detail_info
				FROM
				tblservicetype st
				LEFT JOIN 
				(SELECT 
					vw.JobType AS JobType,
					vw.Prov_ID,
					vw.Province,
					SUM(IF(vw.Request_Status IN ('COMPLETED') AND vw.Service_Result IN ('SUCCESS', 'NEGATIVE') AND vw.JobType = 1, 1, 0)) AS TInstallation,
					SUM(IF(vw.Request_Status IN ('COMPLETED') AND vw.Service_Result IN ('SUCCESS', 'NEGATIVE') AND vw.JobType = 3, 1, 0)) AS TReprogramming,
					SUM(IF(vw.Request_Status IN ('COMPLETED') AND vw.Service_Result IN ('SUCCESS', 'NEGATIVE') AND vw.JobType = 4, 1, 0)) AS TPullOut,
					SUM(IF(vw.Request_Status IN ('COMPLETED') AND vw.Service_Result IN ('SUCCESS', 'NEGATIVE') AND vw.JobType = 6, 1, 0)) AS TServicing,
					SUM(IF(vw.Request_Status IN ('COMPLETED') AND vw.Service_Result IN ('SUCCESS', 'NEGATIVE') AND vw.JobType = 7, 1, 0)) AS TReplacement
				FROM vw_service_info2 vw
				WHERE 
				vw.Service_Date BETWEEN v_DateFrom AND v_DateTo
				GROUP BY vw.Prov_ID) AS xTable ON st.JobType = xTable.JobType
				WHERE
				st.isActive > 0
				AND xTable.Prov_ID > 0
				GROUP BY
				xTable.Prov_ID
				ORDER BY
				st.SequenceDisplay;
			END IF;
			
		ELSEIF (p_SearchBy = 'General Service Summary')	
		THEN	
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			    r.RegionID AS ID,
			    JSON_OBJECT
			    (
				'RegionID', r.RegionID,
				'Region', r.Code,
				'TInstallation', FORMAT(COALESCE(SUM(
				CASE WHEN a.JobType = 1 
				     AND a.JobTypeStatusDescription = 'COMPLETED' 
				     AND b.ActionMade IN ('SUCCESS', 'NEGATIVE') 
				     THEN 1 ELSE 0 END), 0), 0),
				'TReprogramming', FORMAT(COALESCE(SUM(
				CASE WHEN a.JobType = 3 
				     AND a.JobTypeStatusDescription = 'COMPLETED' 
				     AND b.ActionMade IN ('SUCCESS', 'NEGATIVE') 
				     THEN 1 ELSE 0 END), 0), 0),
				'TServicing', FORMAT(COALESCE(SUM(
				CASE WHEN a.JobType = 6 
				     AND a.JobTypeStatusDescription = 'COMPLETED' 
				     AND b.ActionMade IN ('SUCCESS', 'NEGATIVE') 
				     THEN 1 ELSE 0 END), 0), 0),
				'TReplacement', FORMAT(COALESCE(SUM(
				CASE WHEN a.JobType = 7 
				     AND a.JobTypeStatusDescription = 'COMPLETED' 
				     AND b.ActionMade IN ('SUCCESS', 'NEGATIVE') 
				     THEN 1 ELSE 0 END), 0), 0),
				 'TPullOut', FORMAT(COALESCE(SUM(
				CASE WHEN a.JobType = 4 
				     AND a.JobTypeStatusDescription = 'COMPLETED' 
				     AND b.ActionMade IN ('SUCCESS', 'NEGATIVE') 
				     THEN 1 ELSE 0 END), 0), 0)
			    ) AS detail_info   
			FROM tblregion r
			LEFT JOIN tblparticular p ON p.RegionType = r.RegionID
			LEFT JOIN tblservicingdetail a ON a.MerchantID = p.ParticularID AND a.isActive > 0
			LEFT JOIN tblfsrdetail b ON b.ServiceNo = a.ServiceNo
			WHERE 
			r.isActive > 0
			AND a.ClientID = v_ClientID
			GROUP BY r.Region;
			
		ELSEIF (p_SearchBy = 'Service Detail List')	
		THEN
			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)); # eg. (PENDING, PROCESSING, COMPLETED...)
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER); # eg. (1=INSTALLATION, ....)
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_ServiceJobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)); # eg. (INSTALLATION, SERVICING, ...)
			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)); # eg. (SUCCESS, NEGATIVE)		
			SET v_DateFilter = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)); # eg (TODAY, RANGE)
			
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)) AS UNSIGNED INTEGER);
			SET v_FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);
			SET v_DispatcherID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)) AS UNSIGNED INTEGER);
			
			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));
			SET v_FSRMode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13));
			
			SET v_RegionType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));
			SET v_Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15));
			
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16));
			
			#SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER);
			#SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)) AS UNSIGNED INTEGER);

			SET p_WHERE = '';	
										
			SET p_SQL = '';	
					
			IF (v_JobTypeStatusDescription = 'PENDING AND PROCESSING' || v_JobTypeStatusDescription = 'OVERALL PENDING')
			THEN			
			SET p_SQL = CONCAT(
				p_SQL,
				'SELECT ',
				"IFNULL_NUMERIC(st.JobType) AS ID,
				JSON_OBJECT(
				'JobType', IFNULL_NUMERIC(xTable.JobType),
				'ServiceJobTypeDescription', IFNULL_STRING_ONLY2(xTable.ServiceJobTypeDescription),
				'RegionType', IFNULL_NUMERIC(xTable.RegionType),
				'RegionID', IFNULL_NUMERIC(xTable.RegionID),
				'Job_ID', IFNULL_STRING_ONLY2(xTable.Job_ID),
				'Request_ID', IFNULL_STRING_ONLY2(xTable.Request_ID),
				'Schedule_Date', IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Schedule_Date)),
				'Request_Date', IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Request_Date)),
				'Installation_Date', IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Installation_Date)),
				'Created_Date', IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Created_Date)),
				'Target_Date', IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Target_Date)),
				'FSRDate', IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.FSRDate)),				
				'Region', IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Service_Date)),
				
				'Service_Date', IFNULL_STRING_ONLY2(xTable.Region),
				'Service_Result', IFNULL_STRING_ONLY2(xTable.Service_Result),
				'Request_Status', IFNULL_STRING_ONLY2(xTable.Request_Status),
				'Service_Status', IFNULL_STRING_ONLY2(xTable.Service_Status),
				
				'Request_No', IFNULL_STRING_ONLY2(xTable.Request_No),
				'Reference_No', IFNULL_STRING_ONLY2(xTable.Reference_No),
				'Merchant_ID', IFNULL_STRING_ONLY2(xTable.Merchant_ID),
				'Merchant_Name', IFNULL_STRING_ONLY2(xTable.Merchant_Name),
				'TID', IFNULL_STRING_ONLY2(xTable.TID),
				'MID', IFNULL_STRING_ONLY2(xTable.MID),
				'Old_TSID', IFNULL_STRING_ONLY2(xTable.Old_TSID),
				'Old_TSN', IFNULL_STRING_ONLY2(xTable.Old_TSN),
				'New_TSN', IFNULL_STRING_ONLY2(xTable.New_TSN),
				'Old_SSID', IFNULL_STRING_ONLY2(xTable.Old_SSID),
				'Old_SSN', IFNULL_STRING_ONLY2(xTable.Old_SSN),
				'New_SSN', IFNULL_STRING_ONLY2(xTable.New_SSN),
				'Terminal_ID', IFNULL_STRING_ONLY2(xTable.Terminal_ID),
				'Terminal_SN', IFNULL_STRING_ONLY2(xTable.Terminal_SN),
				'SIM_ID', IFNULL_STRING_ONLY2(xTable.Sim_ID),
				'SIM_SN', IFNULL_STRING_ONLY2(xTable.Sim_SN),
				'AppVersion', IFNULL_STRING_ONLY2(xTable.AppVersion),
				'AppCRC', IFNULL_STRING_ONLY2(xTable.AppCRC),
				'MerchantRepresentative', IFNULL_STRING_ONLY2(xTable.MerchantRepresentative),	
				
				'RMInstruction', IFNULL_STRING_ONLY2(xTable.RMInstruction),			
				'ProblemReported', IFNULL_STRING_ONLY2(xTable.ProblemReported),
				'ActualProblemReported', IFNULL_STRING_ONLY2(xTable.ActualProblemReported),
				'ActionTaken', IFNULL_STRING_ONLY2(xTable.ActionTaken),
				'AnyComments', IFNULL_STRING_ONLY2(xTable.AnyComments),
				'fsrRemarks', IFNULL_STRING_ONLY2(xTable.fsrRemarks),
				'fsrReason', IFNULL_STRING_ONLY2(xTable.fsrReason),
				'Address', IFNULL_STRING_ONLY2(xTable.Address),
				'Province', IFNULL_STRING_ONLY2(xTable.Province),
				'MobileID', IFNULL_STRING_ONLY2(xTable.MobileID),
				'FEID', IFNULL_STRING_ONLY2(xTable.FEID),
				'FEName', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Particular', IFNULL_NUMERIC(xTable.FEID))),				
				'DispatchID', IFNULL_STRING_ONLY2(xTable.DispatchID),
				'Dispatcher', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Particular', IFNULL_NUMERIC(xTable.DispatchID))),
				'ClientID', IFNULL_STRING_ONLY2(xTable.ClientID),
				'ClientName', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Particular', IFNULL_NUMERIC(xTable.ClientID))),
				'MerchantID', IFNULL_STRING_ONLY2(xTable.MerchantID),
				'IRIDNo', IFNULL_STRING_ONLY2(xTable.IRIDNo),
				'isBillable', funcGetDesc('Search', 'Yes/No', xTable.isBillable),
				
				'SLA', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Get SLA', xTable.Merchant_ID)),
				'NetworkDays', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Get NetworkDays', xTable.Job_ID)),
				'DaysOverDue', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Get DaysOverDue', CONCAT(xTable.Merchant_ID,'|',xTable.Job_ID))),
				'TATStatus', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Get TAT Status', IFNULL_NUMERIC(funcGetDesc('Search', 'Get DaysOverDue', CONCAT(xTable.Merchant_ID,'|',xTable.Job_ID))))),
				
				'DCC_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"DCC (Yes/No)\"')),
				'Installment_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"Installment (Yes/No)\"')),
				'MKE_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"Manual Key Entry (MKE) (Yes/No)\"')),
				'Preauth_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"Preauth (Yes/No)\"')),
				'Offline_Sale_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"Offline Sale (Yes/No)\"')),
				'Offline_Sale_Limit_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"Offline Sale Limit (To be specified)\"')),
				'Tip_Adjust_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"Tip Adjust (Yes/No)\"')),
				'Tip_Adjust_Limit_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"Tip Adjust Limit (To be specified)\"')),
				'ECR_Integration_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"ECR Integration (Yes/No)\"')),
				'ECR_Cable_Type_', IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,'$.\"ECR Cable Type\"')),
				
				'TerminalType', funcGetDesc('Search', 'TerminalID Type', IFNULL_NUMERIC(xTable.Old_TSID)),
				'TerminalModel', funcGetDesc('Search', 'TerminalID Model', IFNULL_NUMERIC(xTable.Old_TSID)),
				'RepTerminalType', funcGetDesc('Search', 'TerminalID Type', IFNULL_NUMERIC(xTable.New_TSID)),
				'RepTerminalModel', funcGetDesc('Search', 'TerminalID Model', IFNULL_NUMERIC(xTable.New_TSID)),
				'SIMSNCarrier', funcGetDesc('Search', 'SIMID Carrier', IFNULL_NUMERIC(xTable.Old_SSID)),
				'RepSIMSNCarrier', funcGetDesc('Search', 'SIMID Carrier', IFNULL_NUMERIC(xTable.New_SSID)),
				
				'Vendor', IFNULL_STRING_ONLY2(xTable.Vendor),
				'Requestor', IFNULL_STRING_ONLY2(xTable.Requestor),
				'Request_For', IFNULL_STRING_ONLY2(xTable.Request_For),
				'POS_Type', IFNULL_STRING_ONLY2(xTable.POS_Type),
				
				'isClosedTicket', funcGetDesc('Search', 'Yes/No', xTable.TicketStatus),
				
				'InstalledDate', funcGetDesc('Search', 'Merchant Operational Period', CONCAT(xTable.ClientID, '|', '1', '|', xTable.IRIDNo)),
				'PulloutDate', funcGetDesc('Search', 'Merchant Operational Period', CONCAT(xTable.ClientID, '|', '4', '|', xTable.IRIDNo)),
				'OperationalPeriod', funcGetDesc('Search', 'Date Diff YMD', CONCAT(funcGetDesc('Search', 'Merchant Operational Period', CONCAT(xTable.ClientID, '|', '1', '|', xTable.IRIDNo)), '|', funcGetDesc('Search', 'Merchant Operational Period', CONCAT(xTable.ClientID, '|', '4', '|', xTable.IRIDNo))))
				
				) AS detail_info", ' ',

				'FROM tblservicetype st ',
				'LEFT JOIN (SELECT ',
				'vw.JobType AS JobType, ',
				'vw.Prov_ID AS Prov_ID, ',
				'vw.RegionType AS RegionType, ',
				'vw.RegionID AS RegionID, ',
				'vw.Region AS Region, ',

				'vw.Job_ID AS Job_ID, ',
				'vw.ServiceJobTypeDescription AS ServiceJobTypeDescription, ',
				'vw.Request_ID AS Request_ID, ',
				'vw.Schedule_Date AS Schedule_Date, ',
				'vw.Request_Date AS Request_Date, ',
				'vw.Installation_Date AS Installation_Date, ',
				'vw.Created_Date AS Created_Date, ',
				'vw.Target_Date AS Target_Date, ',
				'vw.Service_Date AS Service_Date, ',
				'vw.Service_Result AS Service_Result, ',
				'vw.Request_Status AS Request_Status, ',
				'vw.Service_Status AS Service_Status, ',
				
				'vw.FSRDate AS FSRDate, ',

				'vw.Request_No AS Request_No, ',
				'vw.Reference_No AS Reference_No, ',
				'vw.Merchant_ID AS Merchant_ID, ',
				'vw.Merchant_Name AS Merchant_Name, ',
				'vw.TID AS TID, ',
				'vw.MID AS MID, ',
				'vw.profile_info AS profile_info, ',				
				'vw.Old_TSID AS Old_TSID, ',
				'vw.Old_TSN AS Old_TSN, ',
