			IF ((LENGTH(v_SearchString > 0)) && (STRCMP(v_SearchString, "0") != 0)) THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'AND');
				SET p_SQL = CONCAT(p_SQL, ' ', '(');
				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.Request_No LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.Merchant_Name LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.TID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.MID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				# Old/New TerminalSN
				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.Old_TSN LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.New_TSN LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				# Old/New SIMSN
				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.Old_SSN LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.New_TSN LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'vw.Job_ID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', ')');
			END IF;
			
			IF v_ServiceJobTypeDescription != '[NOT SPECIFIED]' THEN
			    SET p_SQL = CONCAT(
				p_SQL,
				'AND vw.ServiceJobTypeDescription = ', ADD_SINGLEQUOTE(v_ServiceJobTypeDescription), ' '
			    );
			END IF;
			
			IF v_JobTypeStatusDescription != '[NOT SPECIFIED]' THEN
			
			    IF v_JobTypeStatusDescription = 'PENDING' || 
			    v_JobTypeStatusDescription = 'PROCESSING' ||  
			    v_JobTypeStatusDescription = 'PENDING AND PROCESSING' || 
			    v_JobTypeStatusDescription = 'OVERALL PENDING' THEN
				    SET p_SQL = CONCAT(p_SQL,'');
			ELSEIF v_JobTypeStatusDescription = 'UNCLOSED TICKET' THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Request_Status = ', ADD_SINGLEQUOTE('COMPLETED'), ' '
					);
			    ELSE	
				    SET p_SQL = CONCAT(
						p_SQL,
						'AND vw.Request_Status = ', ADD_SINGLEQUOTE(v_JobTypeStatusDescription), ' '
					    ); 
			    END IF;
			END IF;
			
			IF v_ServiceResult != '[NOT SPECIFIED]' THEN
			      
			        IF v_JobTypeStatusDescription = 'PENDING' || 
			        v_JobTypeStatusDescription = 'PROCESSING' || 
			        v_JobTypeStatusDescription = 'PENDING AND PROCESSING' || 
			        v_JobTypeStatusDescription = 'OVERALL PENDING' THEN
			                SET p_SQL = CONCAT(p_SQL,'');
			ELSEIF v_JobTypeStatusDescription = 'UNCLOSED TICKET' THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Request_Status = ', ADD_SINGLEQUOTE('COMPLETED'), ' '
					);
			        ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					#'AND vw.Service_Result = ', ADD_SINGLEQUOTE(v_ServiceResult), ' '
					'AND FIND_IN_SET(vw.Service_Result,', ADD_SINGLEQUOTE(v_ServiceResult), ')', ' '
					
					
				    );
			        END IF;			
			END IF;
			
			IF (v_ClientID > 0) THEN
			    SET p_SQL = CONCAT(
