			IF (v_RegionType > 0) THEN
			    SET p_SQL = CONCAT(
				p_SQL,
				'AND vw.Prov_ID = ', v_RegionType, ' '
			    );
			END IF;
			
			IF (LENGTH(v_Region) > 0 && v_Region != '[NOT SPECIFIED]')
			THEN
				SET p_SQL = CONCAT(
