				'AND vw.Region = ', ADD_SINGLEQUOTE(v_Region), ' '
			    );
			END IF;
			
			IF (v_IRIDNo > 0) THEN
			    SET p_SQL = CONCAT(
				p_SQL,
				'AND vw.IRIDNo = ', v_IRIDNo, ' '
			    );
			END IF;
			
			IF (v_FEID > 0) THEN
			    SET p_SQL = CONCAT(
