				'AND vw.FEID = ', v_FEID, ' '
			    );
			END IF;
			
			IF (v_DispatcherID > 0) THEN
			    SET p_SQL = CONCAT(
				p_SQL,
				'AND vw.DispatchID = ', v_DispatcherID, ' '
			    );
			END IF;
			
			IF (LENGTH(v_IncludeBillable) > 0 && v_IncludeBillable != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_IncludeBillable, "BILLABLE") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.isBillable = 1', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.isBillable = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (LENGTH(v_FSRMode) > 0 && v_FSRMode != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_FSRMode, "DIGITAL FSR") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.MobileID > 0', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.MobileID = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (v_JobType > 0)
			THEN
				SET p_SQL = CONCAT(
				    p_SQL,
				    ') AS xTable ',
				    'ON xTable.JobType = st.JobType ',
				    'WHERE st.isActive > 0',' ',
				    'AND st.JobType = ', v_JobType,' ',
				    'AND xTable.TID != "-"'
				);
			ELSE
				SET p_SQL = CONCAT(
