			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))
			THEN	
				SET v_OffSet = 0;

				IF (v_OffSetFrom = 1)
				THEN
					SET v_OffSet = 0;
				ELSE
					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;
				END IF;
				
			
				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');
				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);
				
			END IF;
			*/
			
			SET p_SQL = CONCAT(p_SQL, ';');	
							
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Installation Detail List')
		THEN
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);
			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
			
			SET p_WHERE = '';			
			SET p_SQL = '';
			
			SET p_SQL = CONCAT(
				p_SQL,
				'SELECT ',
				"IFNULL_NUMERIC(a.IRIDNo) AS ID,
				JSON_OBJECT(
				'IRIDNo', IFNULL_NUMERIC(a.IRIDNo),
				'MerchantID', IFNULL_NUMERIC(a.MerchantID),
				'RegionType', IFNULL_NUMERIC(b.RegionType),
				'RegionID', IFNULL_NUMERIC(b.RegionID),
				'Request_No', IFNULL_STRING_ONLY2(a.IRNo),
				'Merchant_Name', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Particular', a.MerchantID)),
				'Address', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Address', a.MerchantID)),
				'Region', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Region', b.RegionType)),
				'Province', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Region Detail', b.RegionID)),
				'Request_Date', IFNULL_STRING_ONLY2(a.IRDate),
				'Installation_Date', IFNULL_STRING_ONLY2(a.InstallationDate),
				'TID', IFNULL_STRING_ONLY2(a.TID),
				'MID', IFNULL_STRING_ONLY2(a.MID),
