				'REQUEST_FOR', IFNULL_STRING_ONLY2(a.REQUEST_FOR),
				'OTHER_SPECIAL_INSTRUCTION', IFNULL_STRING_ONLY2(a.OTHER_SPECIAL_INSTRUCTION),
				'POS_TYPE', IFNULL_STRING_ONLY2(a.POS_TYPE),
				'ProcessType', IFNULL_STRING_ONLY2(a.ProcessType),
				'rawdata_info', IFNULL_STRING_ONLY2(a.rawdata_info),
				'profile_info', IFNULL_STRING_ONLY2(a.profile_info),
				
				'DCC_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"DCC (Yes/No)\"')),
				'Installment_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"Installment (Yes/No)\"')),
				'MKE_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"Manual Key Entry (MKE) (Yes/No)\"')),
				'Preauth_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"Preauth (Yes/No)\"')),
				'Offline_Sale_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"Offline Sale (Yes/No)\"')),
				'Offline_Sale_Limit_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"Offline Sale Limit (To be specified)\"')),
				'Tip_Adjust_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"Tip Adjust (Yes/No)\"')),
				'Tip_Adjust_Limit_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"Tip Adjust Limit (To be specified)\"')),
				'ECR_Integration_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"ECR Integration (Yes/No)\"')),
				'ECR_Cable_Type_', IFNULL_STRING_ONLY2(fnJsonExtract(a.profile_info,'$.\"ECR Cable Type\"')),
				
				'Requestor', IFNULL(JSON_UNQUOTE(JSON_EXTRACT(a.rawdata_info, '$.Values.\"Requestor\"')), ''),
			        'ContactPerson', IFNULL(JSON_UNQUOTE(JSON_EXTRACT(a.rawdata_info, '$.Values.\"Contact Person\"')), ''),
			        'ContactNumber', IFNULL(JSON_UNQUOTE(JSON_EXTRACT(a.rawdata_info, '$.Values.\"Contact Number\"')), ''),
			        'Status', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Service Status', a.IRStatus)),
			        'rawdata_info_status', IF(funcIsNullOrNotEmpty(a.rawdata_info) > 0, 'HAS DATA', 'NO DATA'),
			        'profile_info_status', IF(funcIsNullOrNotEmpty(a.profile_info) > 0, 'HAS DATA', 'NO DATA'),
			        
			        'ActionMade', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'FSR ActionMade', CONCAT('1','|','0','|',a.IRIDNo,'|',a.IRNo))),
			        'FSRDate', IFNULL_STRING_ONLY2(funcGetDesc('Search', 'FSR ServiceDate', CONCAT('1','|','0','|',a.IRIDNo,'|',a.IRNo)))
				
				) AS detail_info", ' ',
					
				'FROM ',
				'tblirdetail a ',
				'LEFT JOIN tblparticular b ON a.MerchantID = b.ParticularID '
				#'WHERE NOT EXISTS (SELECT xTable.IRIDNo FROM tblservicingdetail xTable WHERE a.IRIDNo = xTable.IRIDNo AND xTable.JobType = 1 AND xTable.JobTypeStatusDescription = "COMPLETED")'
				);
			
			# Filter IRStatus as AVAILABLE
			SET p_SQL = CONCAT(
					p_SQL, ' ',
					'WHERE a.IRStatus = 1', ' '
					);
			
			IF ((LENGTH(v_SearchString > 0)) && (STRCMP(v_SearchString, "0") != 0)) THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'AND');
				SET p_SQL = CONCAT(p_SQL, ' ', '(');
				SET p_SQL = CONCAT(p_SQL, ' ', 'a.IRNo LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'b.Name LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'a.TID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'a.MID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', ')');
			END IF;
							
			IF (v_RegionType > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND b.RegionType = ', v_RegionType, ' '
					);
			END IF;
			
			IF (v_RegionID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND b.RegionID = ', v_RegionID, ' '
					);
			END IF;
			
			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND a.IRDate BETWEEN ', 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)', ' '
					);
			END IF;
			
			#Order By
			SET p_ORDERBY = '';
			SET p_ORDERBY = 'a.IRDate DESC';				
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
			END IF;
			
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))
			THEN	
				SET v_OffSet = 0;

				IF (v_OffSetFrom = 1)
				THEN
					SET v_OffSet = 0;
				ELSE
					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;
				END IF;


				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');
				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;

			SET p_SQL = CONCAT(
				    p_SQL,
				    ';'
				);
			
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Active Terminal')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SELECT 
			IFNULL_NUMERIC(vw.Model_ID) AS ID,
			JSON_OBJECT
			(
			'TerminalTypeID', IFNULL_NUMERIC(vw.Model_ID),
			'TerminalModelID', IFNULL_NUMERIC(vw.Type_ID),
			'TerminalType', IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Type", vw.Type_ID)),
			'TerminalModel', IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Model", vw.Model_ID)),
			'TCount', IFNULL_NUMERIC(COUNT(*))
			) AS detail_info
			FROM   
			vw_terminal_info vw
			WHERE  
			vw.Client_ID = v_ClientID
			AND vw.Loc_ID = v_LocationID
			AND vw.Status_ID = v_StatusID
			AND vw.isActive > 0
			GROUP BY 
			vw.Model_ID
			ORDER BY
			vw.Type_ID;
			
		ELSEIF (p_SearchBy = 'Whos Online')
		THEN
			SELECT 
			    a.LogID AS ID,
			    JSON_OBJECT(
				'LogID', a.LogID,
				'UserID', a.UserID,
				'UserName', a.UserName,
				'FullName', a.FullName,
				'ComputerName', a.ComputerName,
				'PublishVersion', a.PublishVersion,
				'LogDate', IFNULL_GET_DATE(a.LogDate),
				'LogTime', IFNULL_GET_TIME(a.LogDate)
			    ) AS detail_info
			FROM tbluserlog a
			INNER JOIN (
			    SELECT 
				UserID,
				MAX(LogID) AS MaxLogID
			    FROM tbluserlog
			    WHERE 
				CAST(LogDate AS DATE) = CURRENT_DATE()
				AND ComputerName != 'Web Access'
			    GROUP BY UserID
			) b ON b.UserID = a.UserID
			   AND b.MaxLogID = a.LogID
			ORDER BY a.FullName ASC;
			
		ELSEIF (p_SearchBy = 'Whos eFSR Online')
		THEN
			SELECT 
			a.FSRNo AS ID,
			JSON_OBJECT
			(
			   'FSRNo', a.FSRNo,
			   'FEID', a.FEID,
			   'FullName', funcGetDesc("Search", "Particular", a.FEID),
			   'MobileID', a.MobileID,
			   'MobileTerminalID', funcGetDesc("Search", "Moblie Terminal ID", a.MobileID),
			   'MobileTerminalName', funcGetDesc("Search", "Mobile Terminal Name", a.MobileID),
			   'MobileVersion', a.MobileVersion,
			   'FSRTime', a.FSRTime
			) AS detail_info
			FROM tblfsrdetail a 
			WHERE 
			CAST(a.FSRDate AS DATE) = CURRENT_DATE()
			AND ProcessType = 'AUTO'
			GROUP BY a.FEID
			ORDER BY a.FSRNo DESC;
			
		ELSEIF (p_SearchBy = 'User List')
		THEN
			SET v_isFSR = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT 
			    a.UserID AS ID,
			    JSON_OBJECT
			    (
				'UserID', a.UserID,
				'UserName', a.UserName,
				'Name', funcGetDesc("Search", "Particular", a.ParticularID)
			    ) AS detail_info
			FROM tbluser a
			LEFT JOIN tblparticular b ON a.ParticularID = b.ParticularID
			WHERE 
			(v_isFSR = 0 OR a.MobileID > 0)
			AND a.isActive > 0
			ORDER BY b.Name ASC;
			
		ELSEIF (p_SearchBy = 'Duplicate SN Merchant List')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			IF (v_Description = 'Terminal')
			THEN
				SELECT
				a.MerchantID AS ID,
				JSON_OBJECT
				(
				'MerchantID', a.MerchantID,
				'MerchantName', IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.MerchantID)),
				'TID', IFNULL_STRING_ONLY(a.TID),
				'MID', IFNULL_STRING_ONLY(a.MID)
				) AS detail_info
				FROM
				tblirdetail a
				LEFT JOIN (SELECT xTable.TerminalID FROM tblirdetail xTable WHERE xTable.IRActive > 0 AND xTable.TerminalID > 0 GROUP BY xTable.TerminalID HAVING COUNT(*) > 0) b ON a.TerminalID = b.TerminalID
				WHERE
				a.IRActive > 0 
				AND a.TerminalID = b.TerminalID AND a.TerminalID = v_ID AND a.IRIDNo != v_IRIDNo
				ORDER BY
				a.MerchantName;
				
			ELSEIF (v_Description = 'SIM')
			THEN
				SELECT
				a.MerchantID AS ID,
				JSON_OBJECT
				(
				'MerchantID', a.MerchantID,
				'MerchantName', IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.MerchantID)),
				'TID', IFNULL_STRING_ONLY(a.TID),
				'MID', IFNULL_STRING_ONLY(a.MID)
				) AS detail_info
				FROM
				tblirdetail a
				LEFT JOIN (SELECT xTable.SIMID FROM tblirdetail xTable WHERE xTable.IRActive > 0 AND xTable.SIMID > 0 GROUP BY xTable.SIMID HAVING COUNT(*) > 0) b ON a.SIMID = b.SIMID
				WHERE
				a.IRActive > 0 
				AND a.SIMID = b.SIMID AND a.SIMID = v_ID AND a.IRIDNo != v_IRIDNo
				ORDER BY
				a.MerchantName;
			END IF;
			
		ELSEIF (p_SearchBy = 'Monthly Service Count List')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)); # (SUCCESS, NEGATIVE)
			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_FSRMode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SET v_CurrentMonth = 1;
			SET v_Year = YEAR(CURRENT_DATE());
			
			-- Create a temporary table to store the results
			CREATE TEMPORARY TABLE IF NOT EXISTS monthly_service_results (
			month_name VARCHAR(20),
			month_index INT,
			installation_count INT,
			reprogramming_count INT,
			servicing_count INT,
			replacement_count INT,
			pullout_count INT,
			tcount INT
			);

			WHILE v_CurrentMonth <= 12 DO
			
			SET v_MonthName = MONTHNAME(STR_TO_DATE(CONCAT(v_Year, '-', v_CurrentMonth, '-01'), '%Y-%m-%d'));
			SET v_Temp = CONCAT("|", v_ClientID, "|", v_ServiceResult, "|", v_IncludeBillable, "|", v_FSRMode, "|", v_Year, "|", v_CurrentMonth);
			
			#SELECT (CONCAT("v_Temp=", v_Temp));
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(1, v_Temp), @p_outID);
			SET @installation_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(3, v_Temp), @p_outID);
			SET @reprogramming_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(6, v_Temp), @p_outID);
			SET @servicing_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(7, v_Temp), @p_outID);
			SET @replacement_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(4, v_Temp), @p_outID);
			SET @pullout_count = @p_outID;
			
			SET @tcount = 0;
			SET @tcount = @installation_count + @reprogramming_count + @servicing_count + @replacement_count + @pullout_count;
			
			# Insert to temporary table
			INSERT INTO monthly_service_results (month_index, month_name, installation_count, reprogramming_count, servicing_count, replacement_count, pullout_count, tcount)
			VALUES (v_CurrentMonth, v_MonthName,
			@installation_count,
			@reprogramming_count,
			@servicing_count,
			@replacement_count,
			@pullout_count,
			@tcount
			);

			SET v_CurrentMonth = v_CurrentMonth + 1;
			END WHILE;
			
			#total
			SET v_CurrentMonth = 0;
			SET v_MonthName = "TOTAL";
			SET @installation_count = (SELECT SUM(installation_count) FROM monthly_service_results);
			SET @reprogramming_count = (SELECT SUM(reprogramming_count) FROM monthly_service_results);
			SET @servicing_count = (SELECT SUM(servicing_count) FROM monthly_service_results);
			SET @replacement_count = (SELECT SUM(replacement_count) FROM monthly_service_results);
			SET @pullout_count = (SELECT SUM(pullout_count) FROM monthly_service_results);
			SET @tcount = (SELECT SUM(tcount) FROM monthly_service_results);
			
			INSERT INTO monthly_service_results (month_index, month_name, installation_count, reprogramming_count, servicing_count, replacement_count, pullout_count, tcount)
			VALUES (v_CurrentMonth, v_MonthName,
			@installation_count,
			@reprogramming_count,
			@servicing_count,
			@replacement_count,
			@pullout_count,
			@tcount
			);
						
			# Select service count
			SELECT
			a.month_index AS ID,
			JSON_OBJECT(
			'month_index', a.month_index,
			'month_name', a.month_name,
			'TInstallation', a.installation_count,
			'TReprogramming', a.reprogramming_count,
			'TServicing', a.servicing_count,
			'TReplacement', a.replacement_count,
			'TPullout', a.pullout_count,
			'TCount', a.tcount
			) AS detail_info
			FROM monthly_service_results a;

			# Drop temporary table	
			DROP TEMPORARY TABLE monthly_service_results;
			
		ELSEIF (p_SearchBy = 'Stock Movement Detail List')
		THEN
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			IF (v_IRIDNo > 0)
			THEN
				SELECT
				a.TransNo AS ID,
				JSON_OBJECT
				(
				'TransNo', a.TransNo,
				'JobType', a.JobType,
				'ServiceNo', a.ServiceNo,
				'IRIDNo', a.IRIDNo,
				'ItemID', a.ItemID,
				'ReplaceItemID', a.ReplaceItemID,
				'TerminalTypeID', c.TerminalTypeID,
				'TerminalModelID', d.TerminalModelID,
				'TerminalBrandID', e.TerminalBrandID,
				'LocationID', f.LocationID,
				'SerialNo', IFNULL_STRING_ONLY(b.SerialNo),
				'TerminalType', IFNULL_STRING_ONLY(c.Description),
				'TerminalModel', IFNULL_STRING_ONLY(d.Description),
				'TerminalBrand', IFNULL_STRING_ONLY(e.Description),
				'TerminalStatus', IFNULL_STRING_ONLY(g.Description),
				'Location', IFNULL_STRING_ONLY(f.Description),
				'ItemInfo', funcGetJSON('Search', 'Stock Detail Info', a.ItemID),
				'ReplaceItemInfo', funcGetJSON('Search', 'Stock Detail Info', a.ReplaceItemID)
				) AS detail_info
				FROM
				tblstockmovementdetail a
				LEFT JOIN tblstockdetail b ON a.ItemID = b.ItemID
				LEFT JOIN tblterminaltype c ON b.TerminalTypeID = c.TerminalTypeID
				LEFT JOIN tblterminalmodel d ON b.TerminalModelID = d.TerminalModelID
				LEFT JOIN tblterminalbrand e ON b.TerminalBrandID = e.TerminalBrandID
				LEFT JOIN tbllocation f ON b.LocationID = f.LocationID
				LEFT JOIN tblterminalstatus g ON b.StockStatus = g.TerminalStatusID
				WHERE
				a.IRIDNo = v_IRIDNo
				GROUP BY
				a.ItemID;
			ELSE
				SELECT
				a.TransNo AS ID,
				JSON_OBJECT
				(
				'TransNo', a.TransNo,
				'JobType', a.JobType,
				'ServiceNo', a.ServiceNo,
				'IRIDNo', a.IRIDNo,
				'ItemID', a.ItemID,
				'ReplaceItemID', a.ReplaceItemID,
				'TerminalTypeID', c.TerminalTypeID,
				'TerminalModelID', d.TerminalModelID,
				'TerminalBrandID', e.TerminalBrandID,
				'LocationID', f.LocationID,
				'SerialNo', IFNULL_STRING_ONLY(b.SerialNo),
				'TerminalType', IFNULL_STRING_ONLY(c.Description),
				'TerminalModel', IFNULL_STRING_ONLY(d.Description),
				'TerminalBrand', IFNULL_STRING_ONLY(e.Description),
				'TerminalStatus', IFNULL_STRING_ONLY(g.Description),
				'Location', IFNULL_STRING_ONLY(f.Description),
				'Item_Info', funcGetJSON('Search', 'Stock Detail Info', a.ItemID),
				'Replace_Item_Info', funcGetJSON('Search', 'Stock Detail Info', a.ReplaceItemID)
				) AS detail_info
				FROM
				tblstockmovementdetail a
				LEFT JOIN tblstockdetail b ON a.ItemID = b.ItemID
				LEFT JOIN tblterminaltype c ON b.TerminalTypeID = c.TerminalTypeID
				LEFT JOIN tblterminalmodel d ON b.TerminalModelID = d.TerminalModelID
				LEFT JOIN tblterminalbrand e ON b.TerminalBrandID = e.TerminalBrandID
				LEFT JOIN tbllocation f ON b.LocationID = f.LocationID
				LEFT JOIN tblterminalstatus g ON b.StockStatus = g.TerminalStatusID;
			END IF;	
			
		ELSEIF (p_SearchBy = 'Incoming Job Order List 2')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_Type = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SET p_WHERE = '';
			# filter for job type status

			SET v_JobTypeStatusDescription = "PROCESSING";

			IF (STRCMP(v_JobTypeStatusDescription, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobTypeStatusDescription = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_JobTypeStatusDescription, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (v_ID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FEID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;	
			IF (v_Type > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobType = ');

				SET p_WHERE = CONCAT(p_WHERE, v_Type);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;	
			
			IF (LENGTH(v_SearchString) > 0 && (STRCMP(v_SearchString, "0") != 0))

			THEN

				# MechantName			
				SET p_WHERE = CONCAT(p_WHERE, ' ', '(', 'c3.Name LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# TID			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.TID LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# MID			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.MID LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# ServiceNo			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceNo LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# IRNo			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.`IRNo` LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'", ')');	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				
			END IF;
			
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'a.ServiceNo,\n'

							"JSON_OBJECT(

							'ServiceNo', IFNULL_STRING_ONLY(a.ServiceNo),

							'ReferenceNo', IFNULL_STRING_ONLY(a.ReferenceNo),

							'IRIDNo', IFNULL_STRING_ONLY(a.IRIDNo),

							'IRNo', IFNULL_STRING_ONLY(a.IRNo),

							'ReqInstallationDate', IFNULL_STRING_ONLY(a.ServiceReqDate),

							'ServiceDate', IFNULL_STRING_ONLY(a.ServiceDate),

							'ServiceReqDate', IFNULL_STRING_ONLY(a.ServiceDate),

							'ServiceStatus', IFNULL_STRING_ONLY(a.ServiceStatus),

							'ServiceStatusDescription', IFNULL_STRING_ONLY(a.ServiceStatusDescription),

							'ServiceCode', IFNULL_STRING_ONLY(a.ServiceCode),

							'FEID', IFNULL_STRING_ONLY(c1.ParticularID),

							'FEName', funcGetDesc('Search', 'Particular', IFNULL_NUMERIC(c1.ParticularID)),

							'FEEmail', c1.Email,

							'ClientID', IFNULL_STRING_ONLY(a.ClientID),

							'ClientName', funcGetDesc('Search', 'Particular', IFNULL_NUMERIC(a.ClientID)),

							'MerchantID', IFNULL_STRING_ONLY(a.MerchantID),

							'MerchantName', funcGetDesc('Search', 'Particular', IFNULL_NUMERIC(a.MerchantID)),

							'Address', IFNULL_STRING_ONLY(c3.Address),

							'Region', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Region', c3.RegionType)),

