			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|', 16));
			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER);
			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,18)) AS UNSIGNED INTEGER);
			SET v_TATStatus = TRIM(SPLIT_STRING(p_SearchValue, '|', 19));
			
			# debug
			#SELECT funcDebugSplitString(p_SearchValue, '|') AS DebugResult;

			# get regionId
			SET @RegionType = funcGetID("Search", "Region", v_Region);
			SET v_RegionType = @RegionType;

			-- Start SQL Query
			SET p_SQL = 'SELECT 
			    IFNULL_NUMERIC(xTable.JobType) AS ID,
			    JSON_OBJECT(
				"JobType", IFNULL_NUMERIC(xTable.JobType),
				"ServiceJobTypeDescription", IFNULL_STRING_ONLY(xTable.ServiceJobTypeDescription),
				"RegionType", IFNULL_NUMERIC(xTable.RegionType),
				"RegionID", IFNULL_NUMERIC(xTable.RegionID),
				"Job_ID", IFNULL_STRING_ONLY(xTable.Job_ID),
				"Request_ID", IFNULL_STRING_ONLY2(xTable.Request_ID),
				"Schedule_Date", IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Schedule_Date)),
				"Request_Date", IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Request_Date)),
				"Installation_Date", IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Installation_Date)),
				"Created_Date", IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Created_Date)),
				"Target_Date", IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.Target_Date)),
				"FSRDate", IFNULL_STRING_ONLY2(IFNULL_FORMAT_DATE2(xTable.FSRDate)),
				"Region", IFNULL_STRING_ONLY2(xTable.Service_Date),
				"Service_Date", IFNULL_STRING_ONLY2(xTable.Region),
				"Service_Result", IFNULL_STRING_ONLY2(xTable.Service_Result),
				"Request_Status", IFNULL_STRING_ONLY2(xTable.Request_Status),
				"Service_Status", IFNULL_STRING_ONLY2(xTable.Service_Status),
				"Request_No", IFNULL_STRING_ONLY2(xTable.Request_No),
				"Reference_No", IFNULL_STRING_ONLY2(xTable.Reference_No),
				"Merchant_ID", IFNULL_STRING_ONLY2(xTable.Merchant_ID),
				"Merchant_Name", IFNULL_STRING_ONLY2(xTable.Merchant_Name),
				"TID", IFNULL_STRING_ONLY2(xTable.TID),
				"MID", IFNULL_STRING_ONLY2(xTable.MID),
				"Old_TSID", IFNULL_STRING_ONLY2(xTable.Old_TSID),
				"Old_TSN", IFNULL_STRING_ONLY2(xTable.Old_TSN),
				"New_TSN", IFNULL_STRING_ONLY2(xTable.New_TSN),
				"Old_SSID", IFNULL_STRING_ONLY2(xTable.Old_SSID),
				"Old_SSN", IFNULL_STRING_ONLY2(xTable.Old_SSN),
				"New_SSN", IFNULL_STRING_ONLY2(xTable.New_SSN),
				"Terminal_ID", IFNULL_STRING_ONLY2(xTable.Terminal_ID),
				"Terminal_SN", IFNULL_STRING_ONLY2(xTable.Terminal_SN),
				"SIM_ID", IFNULL_STRING_ONLY2(xTable.Sim_ID),
				"SIM_SN", IFNULL_STRING_ONLY2(xTable.Sim_SN),
				"AppVersion", IFNULL_STRING_ONLY2(xTable.AppVersion),
				"AppCRC", IFNULL_STRING_ONLY2(xTable.AppCRC),
				"MerchantRepresentative", IFNULL_STRING_ONLY2(xTable.MerchantRepresentative),					
				"RMInstruction", IFNULL_STRING_ONLY2(xTable.RMInstruction),	
				"ProblemReported", IFNULL_STRING_ONLY2(xTable.ProblemReported),
				"ActualProblemReported", IFNULL_STRING_ONLY2(xTable.ActualProblemReported),
				"ActionTaken", IFNULL_STRING_ONLY2(xTable.ActionTaken),
				"AnyComments", IFNULL_STRING_ONLY2(xTable.AnyComments),				
				"fsrRemarks", IFNULL_STRING_ONLY2(xTable.fsrRemarks),
				"fsrReason", IFNULL_STRING_ONLY2(xTable.fsrReason),
				"Address", IFNULL_STRING_ONLY2(xTable.Address),
				"Province", IFNULL_STRING_ONLY2(xTable.Province),
				"MobileID", IFNULL_STRING_ONLY2(xTable.MobileID),
				"FEID", IFNULL_STRING_ONLY2(xTable.FEID),
				"FEName", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", IFNULL_NUMERIC(xTable.FEID))),				
				"DispatchID", IFNULL_STRING_ONLY2(xTable.DispatchID),
				"Dispatcher", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", IFNULL_NUMERIC(xTable.DispatchID))),
				"ClientID", IFNULL_STRING_ONLY2(xTable.ClientID),
				"ClientName", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", IFNULL_NUMERIC(xTable.ClientID))),
				"MerchantID", IFNULL_STRING_ONLY2(xTable.MerchantID),
				"IRIDNo", IFNULL_STRING_ONLY2(xTable.IRIDNo),
				"isBillable", funcGetDesc("Search", "Yes/No", xTable.isBillable),
				"SLA", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Get SLA", xTable.Merchant_ID)),
				"NetworkDays", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Get NetworkDays", xTable.Job_ID)),
				"DaysOverDue", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Get DaysOverDue", CONCAT(xTable.Merchant_ID,"|",xTable.Job_ID))),
				"TATStatus", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Get TAT Status", IFNULL_NUMERIC(funcGetDesc("Search", "Get DaysOverDue", CONCAT(xTable.Merchant_ID,"|",xTable.Job_ID))))),
				"DCC_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."DCC (Yes/No)"'')),
				"Installment_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."Installment (Yes/No)"'')),
				"MKE_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."Manual Key Entry (MKE) (Yes/No)"'')),
				"Preauth_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."Preauth (Yes/No)"'')),
				"Offline_Sale_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."Offline Sale (Yes/No)"'')),
				"Offline_Sale_Limit_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."Offline Sale Limit (To be specified)"'')),
				"Tip_Adjust_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."Tip Adjust (Yes/No)"'')),
				"Tip_Adjust_Limit_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."Tip Adjust Limit (To be specified)"'')),
				"ECR_Integration_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."ECR Integration (Yes/No)"'')),
				"ECR_Cable_Type_", IFNULL_STRING_ONLY2(fnJsonExtract(xTable.profile_info,''$."ECR Cable Type"'')),
				"TerminalType", funcGetDesc("Search", "TerminalID Type", IFNULL_NUMERIC(xTable.Old_TSID)),
				"TerminalModel", funcGetDesc("Search", "TerminalID Model", IFNULL_NUMERIC(xTable.Old_TSID)),
				"RepTerminalType", funcGetDesc("Search", "TerminalID Type", IFNULL_NUMERIC(xTable.New_TSID)),
				"RepTerminalModel", funcGetDesc("Search", "TerminalID Model", IFNULL_NUMERIC(xTable.New_TSID)),
				"SIMSNCarrier", funcGetDesc("Search", "SIMID Carrier", IFNULL_NUMERIC(xTable.Old_SSID)),
				"RepSIMSNCarrier", funcGetDesc("Search", "SIMID Carrier", IFNULL_NUMERIC(xTable.New_SSID)),
				"Vendor", IFNULL_STRING_ONLY2(xTable.Vendor),
				"Requestor", IFNULL_STRING_ONLY2(xTable.Requestor),
				"Request_For", IFNULL_STRING_ONLY2(xTable.Request_For),
				"POS_Type", IFNULL_STRING_ONLY2(xTable.POS_Type),
				"isClosedTicket", funcGetDesc("Search", "Yes/No", xTable.TicketStatus),
				"InstalledDate", funcGetDesc("Search", "Merchant Operational Period", CONCAT(xTable.ClientID, "|", "1", "|", xTable.IRIDNo)),
				"PulloutDate", funcGetDesc("Search", "Merchant Operational Period", CONCAT(xTable.ClientID, "|", "4", "|", xTable.IRIDNo)),
				"OperationalPeriod", funcGetDesc("Search", "Date Diff YMD", CONCAT(funcGetDesc("Search", "Merchant Operational Period", CONCAT(xTable.ClientID, "|", "1", "|", xTable.IRIDNo)), "|", funcGetDesc("Search", "Merchant Operational Period", CONCAT(xTable.ClientID, "|", "4", "|", xTable.IRIDNo))))

			    ) AS detail_info
			FROM (
			    SELECT vw.JobType AS JobType,
				vw.Prov_ID AS Prov_ID,
				vw.RegionType AS RegionType,
				vw.RegionID AS RegionID,
				vw.Region AS Region,
				vw.Job_ID AS Job_ID,
				vw.ServiceJobTypeDescription AS ServiceJobTypeDescription,
				vw.Request_ID AS Request_ID,
				vw.Schedule_Date AS Schedule_Date,
				vw.Request_Date AS Request_Date,
				vw.Installation_Date AS Installation_Date,
				vw.Created_Date AS Created_Date,
				vw.Target_Date AS Target_Date,
				vw.Service_Date AS Service_Date,
				vw.Service_Result AS Service_Result,
				vw.Request_Status AS Request_Status,
				vw.Service_Status AS Service_Status,
				vw.FSRDate AS FSRDate,
				vw.Request_No AS Request_No,
				vw.Reference_No AS Reference_No,
				vw.Merchant_ID AS Merchant_ID,
				vw.Merchant_Name AS Merchant_Name,
				vw.TID AS TID,
				vw.MID AS MID,
				vw.profile_info AS profile_info,				
				vw.Old_TSID AS Old_TSID,
				vw.Old_TSN AS Old_TSN,
				vw.New_TSID AS New_TSID,
				vw.New_TSN AS New_TSN,
				vw.Old_SSID AS Old_SSID,
				vw.Old_SSN AS Old_SSN,
				vw.New_SSID AS New_SSID,
				vw.New_SSN AS New_SSN,			    
				vw.Terminal_ID AS Terminal_ID,
				vw.Terminal_SN AS Terminal_SN,
				vw.Sim_ID AS Sim_ID,
				vw.Sim_SN AS Sim_SN,		  
				vw.AppVersion AS AppVersion,
				vw.AppCRC AS AppCRC,
				vw.MerchantRepresentative AS MerchantRepresentative,
				vw.VendorRepresentative AS VendorRepresentative,
				vw.RMInstruction AS RMInstruction,
				vw.ProblemReported AS ProblemReported,
				vw.ActualProblemReported AS ActualProblemReported,
				vw.ActionTaken AS ActionTaken,
				vw.AnyComments AS AnyComments,
				vw.fsrRemarks AS fsrRemarks,
				vw.fsrReason AS fsrReason,
				vw.Address AS Address,
				vw.Province AS Province,
				vw.MobileID AS MobileID,
				vw.FEID AS FEID,
				vw.DispatchID AS DispatchID,
				vw.ClientID AS ClientID,
				vw.MerchantID AS MerchantID,
				vw.IRIDNo AS IRIDNo,
				vw.isBillable AS isBillable,
				vw.TicketStatus AS TicketStatus,
				vw.rawdata_info AS rawdata_info,
				vw.Vendor AS Vendor,
				vw.Requestor AS Requestor,
				vw.Request_For AS Request_For,
				vw.POS_Type AS POS_Type
			    FROM vw_monitoring_jobs vw
			    WHERE 1 = 1 '; -- Base condition

			-- Condition for Search
			IF (LENGTH(v_SearchString) > 0 AND STRCMP(v_SearchString, "0") != 0) THEN
			    SET p_SQL = CONCAT(
				p_SQL, ' AND (',
				'vw.Request_No LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',
				'vw.Merchant_Name LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',
				'vw.TID LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',
				'vw.MID LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',
				'vw.Old_TSN LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',
				'vw.New_TSN LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',
				'vw.Old_SSN LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',
				'vw.New_SSN LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' OR ',  -- Fixed duplicate
				'vw.Job_ID LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)),
				')'
			    );
			END IF;

			-- Condition for Job Type Status
			IF v_JobTypeStatusDescription IN ('PENDING', 'PROCESSING', 'PENDING AND PROCESSING', 'OVERALL PENDING') THEN
			    IF (v_JobTypeStatusDescription = 'PENDING AND PROCESSING' || v_JobTypeStatusDescription = 'OVERALL PENDING') THEN
				SET p_SQL = CONCAT(p_SQL, " AND vw.Request_Status IN ('PENDING', 'PROCESSING') ");			    
			    ELSE
			        SET p_SQL = CONCAT(p_SQL, " AND vw.Request_Status IN (", "'", v_JobTypeStatusDescription, "'", ")");
			    END IF;
			ELSEIF v_JobTypeStatusDescription = 'UNCLOSED TICKET' THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.TicketStatus = 0 ");
			ELSEIF v_JobTypeStatusDescription != '[NOT SPECIFIED]' AND v_JobTypeStatusDescription != '0' THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.Request_Status = ", ADD_SINGLEQUOTE(v_JobTypeStatusDescription));
			END IF;

			-- Date filtering
			IF v_DateFrom IS NOT NULL AND v_DateTo IS NOT NULL THEN
				IF (v_DateFrom <> '0000-00-00' AND v_DateTo <> '0000-00-00') THEN
					SET p_SQL = CONCAT(p_SQL, " AND vw.Service_Date BETWEEN ", ADD_SINGLEQUOTE(v_DateFrom), " AND ", ADD_SINGLEQUOTE(v_DateTo));
				END IF;
			END IF;

			-- Condition for Service Job Type Description
			#IF v_ServiceJobTypeDescription != '[NOT SPECIFIED]' THEN
			#    SET p_SQL = CONCAT(p_SQL, " AND vw.ServiceJobTypeDescription = ", ADD_SINGLEQUOTE(v_ServiceJobTypeDescription));
			#END IF;

			-- Condition for Service Result
			IF v_ServiceResult != '[NOT SPECIFIED]' AND v_ServiceResult != '0' THEN
			    #SET p_SQL = CONCAT(p_SQL, " AND vw.Service_Result = ", ADD_SINGLEQUOTE(v_ServiceResult));
			    SET p_SQL = CONCAT(p_SQL, " AND FIND_IN_SET(vw.Service_Result,", ADD_SINGLEQUOTE(v_ServiceResult), ')');			    
			END IF;

			-- Condition for Client ID
			IF v_ClientID > 0 THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.ClientID = ", v_ClientID);
			END IF;

			-- Condition for Region and Region Type
			IF v_RegionType > 0 THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.Prov_ID = ", v_RegionType);
			END IF;

			/*
			IF LENGTH(v_Region) > 0 AND v_Region != '[NOT SPECIFIED]' THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.Region = ", ADD_SINGLEQUOTE(v_Region));
			END IF;
			*/
			
			-- Condition for IRID, FEID, DispatcherID
			IF v_IRIDNo > 0 THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.IRIDNo = ", v_IRIDNo);
			END IF;

			IF v_FEID > 0 THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.FEID = ", v_FEID);
			END IF;

			IF v_DispatcherID > 0 THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.DispatchID = ", v_DispatcherID);
			END IF;

			-- Condition for Billable
			IF LENGTH(v_IncludeBillable) > 0 AND v_IncludeBillable != '[NOT SPECIFIED]' THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.isBillable = ", IF(v_IncludeBillable = 'BILLABLE', 1, 0));
			END IF;

			-- Condition for FSR Mode
			IF LENGTH(v_FSRMode) > 0 AND v_FSRMode != '[NOT SPECIFIED]' THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.MobileID ", IF(v_FSRMode = 'DIGITAL FSR', "> 0", "= 0"));
			END IF;

			-- Condition for Job Type
			IF v_JobType > 0 THEN
			    SET p_SQL = CONCAT(p_SQL, " AND vw.JobType = ", v_JobType);
			END IF;
			
			IF (v_TATStatus > 0) THEN				
				IF (v_TATStatus = 1) THEN -- WITHIN TAT
				  SET p_SQL = CONCAT(p_SQL, " HAVING ", 'funcGetDesc("Search", "Get DaysOverDue", CONCAT(vw.Merchant_ID,"|",vw.Job_ID))', ' <= 0');				
				ELSEIF (v_TATStatus = 2) THEN -- BEYOND TAT
				  SET p_SQL = CONCAT(p_SQL, " HAVING ", 'funcGetDesc("Search", "Get DaysOverDue", CONCAT(vw.Merchant_ID,"|",vw.Job_ID))', ' > 0');
				END IF;
			END IF;

			-- Final Closing Query
			SET p_SQL = CONCAT(p_SQL, ') AS xTable WHERE xTable.JobType IS NOT NULL');

			-- Always order by vw.Service_Date
			#SET p_SQL = CONCAT(p_SQL, ' ORDER BY xTable.Request_Date');

			-- For LIMIT
			IF (v_OffSetFrom > 0 AND v_OffSetTo > 0) THEN
			    SET v_OffSet = IF(v_OffSetFrom = 1, 0, (v_OffSetFrom * v_OffSetTo) - v_OffSetTo);

			    SET p_SQL = CONCAT(p_SQL, ' LIMIT ', v_OffSet, ',', v_OffSetTo);
			END IF;

			SET p_SQL = CONCAT(p_SQL, ';');	
							
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
		
		ELSEIF (p_SearchBy = 'TAT Summary List')	
		THEN
			SELECT
			    stt.JobType AS ID,
			    JSON_OBJECT
			    (
			      'JobType', stt.JobType,
			      'JobTypeDescription', stt.ServiceJobTypeDescription,
			      'TCount', COALESCE(xTable.TCount, 0),
			      'MetroManila', COALESCE(xTable.ManilaRegionCount, 0),
			      'Provincial', COALESCE(xTable.ProvincialRegionCount, 0),
			      'TBeyondTAT', COALESCE(xTable.BeyondTAT, 0),
			      'TWithinTAT', COALESCE(xTable.WithinTAT, 0)
			    ) AS detail_info
			    
			FROM
			    tblservicetype stt
			LEFT JOIN 
			(
			    SELECT
				svc.JobType,
				COUNT(*) AS TCount,
				SUM(CASE WHEN rg.RegionID = '4' THEN 1 ELSE 0 END) AS ManilaRegionCount,
				SUM(CASE WHEN rg.RegionID = '5' THEN 1 ELSE 0 END) AS ProvincialRegionCount,
				SUM(CASE WHEN 
				    (funcGetDesc("Search", "Get DaysOverDue", CONCAT(pr.ParticularID,"|",svc.ServiceNo)) > 0)
				THEN 1 ELSE 0 END) AS BeyondTAT,
				SUM(CASE WHEN 
				    (funcGetDesc("Search", "Get DaysOverDue", CONCAT(pr.ParticularID,"|",svc.ServiceNo)) <= 0)
				THEN 1 ELSE 0 END) AS WithinTAT
			    FROM
				tblservicingdetail svc
			    LEFT JOIN tblparticular AS pr ON svc.MerchantID = pr.ParticularID 
			    LEFT JOIN tblregion AS rg ON pr.RegionType = rg.RegionID
			    WHERE
				svc.isActive > 0
				AND FIND_IN_SET(svc.JobTypeStatusDescription, 'PENDING,PROCESSING')
				-- AND svc.ReqInstallationDate BETWEEN '2025-02-01' AND '2025-02-28'
			    GROUP BY svc.JobType
			) AS xTable
			ON xTable.JobType = stt.JobType
			WHERE
			    stt.isActive > 0
			ORDER BY stt.SequenceDisplay;
			
		ELSEIF (p_SearchBy = 'Helpdesk-Master')
		THEN
		
			SET @Value = '';
		SET @Value = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SELECT hdm.AssistNo AS ID,
				 JSON_OBJECT(
					  'IRIDNo', hdm.IRIDNo,
					  'AssistNo', hdm.AssistNo,
					  'MerchantID', ir.MerchantID,
					  'ClientID', ir.ClientID,
					  'MerchantName', ir.MerchantName,
					  'TID', ir.TID,
					  'MID', ir.MID,					  
					  'ReferenceNo', hdm.ReferenceNo,					  
					  'RequestDate', IF(hdm.RequestDate = '0000-00-00' OR hdm.RequestDate IS NULL, '-', DATE_FORMAT(hdm.RequestDate, '%b %e, %Y')),					  
					  'Requestor', hdm.Requestor,
					  -- 'SOURCE ID', hdm.SourceID,
					  -- 'CATEGORY ID', hdm.CategoryID,
					  -- 'SUB CATEGORY ID', hdm.SubCategoryID,
					  'CreatedID', hdm.CreatedID,
					  'CreatedAt', DATE_FORMAT(hdm.CreatedAt,'%b %e, %Y'),
					  'Status', CASE 
								  WHEN hdm.Status = 'SUCCESS' THEN 'RESOLVED'
								  ELSE hdm.Status
						END,
					  'ProblemNo', hdd.ProblemNo,
					  'CreatedDate', IF(hdm.RequestDate = '0000-00-00' OR hdd.CreatedDate IS NULL, '-', DATE_FORMAT(hdd.CreatedDate, '%b %e, %Y')),	
					  'RequestID', hdd.RequestID,
					  'TicketStatus', hdd.Status,	
					  'HelpdeskName', funcGetDesc('Search', 'Particular', hdd.HelpdeskID),
					  'TeamLeadName', funcGetDesc('Search', 'Particular', hdd.TeamLeadID),
					  'ServiceJobTypeDescription', st.ServiceJobTypeDescription

				 )
		   AS detail_info
			FROM tblhdmaster hdm
			JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
			JOIN tblhddetail hdd ON hdm.AssistNo = hdd.AssistNo
			LEFT JOIN tblservicetype st ON hdm.JobType = st.JobType
			WHERE 
				 (
				   hdm.AssistNo 		 = @Value 
				   OR hdm.ReferenceNo = @Value 
				   -- OR hdm.RequestID   = @Value 
				   OR ir.MerchantID   = @Value
				   OR ir.MerchantName LIKE CONCAT('%', @Value, '%')
				   OR ir.TID 			 = @Value
				   OR ir.MID		    = @Value
				   OR hdd.RequestID 	    = @Value
				 ) 
			-- Display All Data if There is no Search Value
			OR @Value = "" OR @Value IS NULL OR @Value = ''
			GROUP BY hdm.AssistNo
			ORDER BY hdm.AssistNo DESC
			LIMIT 50;
			 				 
		ELSEIF (p_SearchBy = 'Helpdesk-Details')
		THEN	
		
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SELECT 
				 a.ProblemNo AS ID,
				 JSON_OBJECT(
					  'ID', IFNULL(a.ProblemNo, 0),					  
					  'AssistNo', IFNULL(a.AssistNo, 0),
					  'RequestID', IFNULL(a.RequestID, 0),        
					  'HelpdeskID', IFNULL(a.HelpdeskID, 0),        
					  'TeamLeadID', IFNULL(a.TeamLeadID, 0),
					  'CreatedDate', DATE_FORMAT(IFNULL(a.CreatedDate, ''), '%b %e, %Y'),
					  'ReasonID', IFNULL(a.ReasonID, 0),
					  'ContactPerson', IFNULL(a.ContactPerson, ''),
					  'ContactNo', IFNULL(a.ContactNo, ''),
					  'ContactPosition', IFNULL(a.ContactPosition, ''),
					  'ContactEmail', IFNULL(a.ContactEmail, ''),
					  'RequestedBy', IFNULL(a.RequestedBy, ''),
					  'Representative', IFNULL(a.Representative, ''),
					  'TerminalSN', IFNULL(a.TerminalSN, ''),            
					  'SIMSN', IFNULL(a.SIMSN, ''),    
					  'DockerSN', IFNULL(a.DockerSN, ''),
					  'ActualProblem', IFNULL(a.ActualProblem, ''),
					  'ProblemReported', IFNULL(a.ProblemReported, ''),
					  'RemarksService', IFNULL(a.RemarksService, ''),
					  'SourceID', IFNULL(a.SourceID, ''),
					  'CategoryID', IFNULL(a.CategoryID, ''),
					  'SubCategoryID', IFNULL(a.SubCategoryID, ''),
					  'CreatedID', IFNULL(a.CreatedID, 0),    
					  'RequestDate', DATE_FORMAT(IFNULL(a.RequestDate, ''), '%b %e, %Y'), 
					  'CreatedAt', DATE_FORMAT(IFNULL(a.CreatedAt, ''), '%b %e, %Y'),  
					  'CompletedAt', DATE_FORMAT(IFNULL(a.CompletedAt, ''), '%b %e, %Y'),  
					  'Status',
		    CASE 
		      WHEN a.Status = 'SUCCESS' THEN 'RESOLVED'
		      ELSE IFNULL(a.Status, '')
		    END,  
					  'TimeAssisted', IFNULL(a.TimeAssisted, ''),
					  'TimeAssistAt', IFNULL(DATE_FORMAT(a.TimeAssisted, '%r'), ''),
					  'TimeStart', IFNULL(a.TimeStart, ''),
					  'TimeEnd', IFNULL(a.TimeEnd, ''),
					  'Attempts', IFNULL(a.Attempts, ''),
					  'isActive', IFNULL(a.isActive, 0),
					  'CreatedByName', IFNULL(pt.Name, ''),
					  'ProblemID', IFNULL(a.ProblemID, 0),
					  'ProblemNo', IFNULL_NUMERIC(a.ProblemNo),
					  'ServiceNo', IFNULL_NUMERIC(svc.ServiceNo),
					  'FSRNo', IFNULL_NUMERIC(fsr.FSRNo),
					  'ScheduleDate', IFNULL_FORMAT_DATE(svc.ServiceReqDate),
					  'FSRDate', IFNULL_FORMAT_DATE(fsr.FSRDate),
					  'ActionMade', IFNULL(fsr.ActionMade, '-'),
					  'ServiceJobTypeDescription', funcGetDesc('Search', 'Service JobType Description', b.JobType)
					      
			) AS detail_info
			FROM tblhddetail a
			LEFT JOIN tblhdmaster b ON b.AssistNo = a.AssistNo
			LEFT JOIN tblparticular pt ON pt.ParticularID = a.CreatedID
			LEFT JOIN tblservicingdetail svc ON a.AssistNo = svc.AssistNo AND a.ProblemNo = svc.ProblemNo
			LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo
			WHERE a.AssistNo = v_ID
			ORDER BY a.TimeStart DESC
			LIMIT 15;
			
		ELSEIF (p_SearchBy = 'Helpdesk-JobType')
		THEN
			SET @Value = '';
			SET @Value = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		
			SELECT 
			 a.JobType AS ID,
			 JSON_OBJECT(
				  'ID', IFNULL(a.JobType, 0),
				  'Description', IFNULL(a.ServiceJobTypeDescription, '')		  
			 ) AS detail_info
			FROM tblservicetype a
			WHERE 
				 a.JobType IN (3, 6) -- Only include specific JobType IDs
				 AND (
					  @Value IS NULL
					  OR @Value = ''
					  OR a.ServiceJobTypeDescription = @Value
					  OR a.JobType = CAST(@Value AS UNSIGNED INTEGER)
				 )
			ORDER BY a.SequenceDisplay;
				 
		ELSEIF (p_SearchBy = 'Service Reversal-JobType')
		THEN
			SET @Value = '';
			SET @Value = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		
			SELECT 
			 a.JobType AS ID,
			 JSON_OBJECT(
				  'ID', IFNULL(a.JobType, 0),
				  'Description', IFNULL(a.ServiceJobTypeDescription, '')		  
			 ) AS detail_info
			FROM tblservicetype a
			WHERE 
				 a.JobType IN (3, 4, 6, 7) -- Only include specific JobType IDs
				 AND (
					  @Value IS NULL
					  OR @Value = ''
					  OR a.ServiceJobTypeDescription = @Value
					  OR a.JobType = CAST(@Value AS UNSIGNED INTEGER)
				 )
			ORDER BY a.SequenceDisplay;
			 
		ELSEIF (p_SearchBy = 'Mobile Terminal List')
		THEN
			# show tblterminal record which is active and do not have entry in tbluser
			SELECT
			a.TID AS ID,
			JSON_OBJECT
			(
			'MobileID', a.TID,
			'MobileTerminalID', a.TerminalID,
			'MobileTerminalName', a.TerminalName,
			'Password', a.Password
			) AS detail_info
			FROM tblterminal a
			LEFT JOIN tbluser b ON a.TID = b.MobileID
			WHERE
			a.Active > 0
			AND b.MobileID IS NULL;
			
		ELSEIF (p_SearchBy = 'Whos Dashboard Online')
		THEN
			SELECT 
			a.LogID AS ID,
			JSON_OBJECT
			(
			   'LogID', a.LogID,
			   'UserID', a.UserID,
			   'UserName', a.UserName,
			   'FullName', a.FullName,
			   'ComputerName', a.ComputerName,
			   'PublishVersion', a.PublishVersion,
			   'LogDate', IFNULL_GET_DATE(a.LogDate),
			   'LogTime', IFNULL_GET_TIME(a.LogDate)
			) AS detail_info
			FROM tbluserlog a 
			WHERE 
			CAST(a.LogDate AS DATE) = CURRENT_DATE()
			AND a.SessionStatus = 0
			AND a.ComputerName = 'Web Access'
			GROUP BY a.UserID
			ORDER BY a.LogID DESC;
			
		ELSEIF (p_SearchBy = 'FSR-Field Engineer List')
		THEN
			SELECT
			    a.FSRNo AS ID,
			    JSON_OBJECT(
				'ServiceNo', a.ServiceNo,
				'FEID', a.FEID,
				'DispatchID', b.DispatchID,
				'FEName', fePart.Name,
				'Dispatcher', dispPart.Name,
				'Region', reg.Region,                -- e.g. METRO MANILA
				'Province', prov.Province,           -- e.g. CALOOCAN
				'Area', IFNULL(dispPart.AreaCode, '-'),
				'TCount', IFNULL(x.count_today, 0),
				'TRemaining', IFNULL(rem.RemainingCount, 0)
			    ) AS detail_info
			FROM tblfsrdetail a 
			LEFT JOIN tblservicingdetail b 
			       ON a.ServiceNo = b.ServiceNo

			-- Field Engineer info
			LEFT JOIN tblparticular fePart 
			       ON fePart.ParticularID = a.FEID

			-- Dispatcher info (also holds AreaCode)
			LEFT JOIN tblparticular dispPart 
			       ON dispPart.ParticularID = b.DispatchID

			-- Merchant info (Region + Province)
			LEFT JOIN tblparticular merch 
			       ON merch.ParticularID = a.MerchantID
			LEFT JOIN tblregion reg 
			       ON merch.RegionType = reg.RegionID
			LEFT JOIN tblregiondetail prov 
			       ON merch.RegionID = prov.RegionID

			-- User account for FE (active only)
			INNER JOIN tbluser e 
			       ON a.FEID = e.ParticularID 
			      AND e.isActive > 0

			-- Count of today's services
			LEFT JOIN (
			    SELECT FEID, COUNT(*) AS count_today
			    FROM tblfsrdetail
			    WHERE FSRDate = CURRENT_DATE()
			    GROUP BY FEID
			) X 
			       ON x.FEID = a.FEID

			-- Remaining services (not completed)
			LEFT JOIN (
			    SELECT FEID, COUNT(*) AS RemainingCount
			    FROM tblservicingdetail
			    WHERE JobTypeStatusDescription != 'COMPLETED'
			    GROUP BY FEID
			) rem 
			       ON rem.FEID = a.FEID

			WHERE 
			    a.MobileID > 0
			    AND a.FEID > 0
			    AND YEAR(a.FSRDate) = YEAR(NOW())

			GROUP BY
			    a.FEID

			ORDER BY
			    IFNULL(x.count_today, 0) DESC,
			    fePart.Name ASC;
		
		ELSEIF (p_SearchBy = 'FSR-Field Engineer Activity List')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			a.FSRNo AS ID,
			JSON_OBJECT
			(
				'ServiceNo', a.ServiceNo,
				'RequestDate', IFNULL_FORMAT_DATE2(b.ReqInstallationDate),
				'TargetDate', IFNULL_FORMAT_DATE2(IF(b.JobType = 1, c.InstallationDate, b.ServiceReqDate)),
				'ScheduleDate', IFNULL_FORMAT_DATE2(b.ServiceReqDate),
				'ServicedDate', CONCAT(IFNULL_FORMAT_DATE2(a.FSRDate),' ',a.FSRTime),
				'Region', funcGetDesc("Search", "Region", d.RegionType),
				'Province', funcGetDesc("Search", "Region Detail", d.RegionID),
				'SLA', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get SLA", a.MerchantID)),
				'DaysOverDue', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get DaysOverDue", CONCAT(a.MerchantID,"|",a.ServiceNo))),
				'NetworkDays', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get NetworkDays", a.ServiceNo)),
				'TATStatus', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get TAT Status", IFNULL_NUMERIC(funcGetDesc("Search", "Get DaysOverDue", CONCAT(a.MerchantID,"|",a.ServiceNo))))),
				'FEName', funcGetDesc("Search", "Particular", a.FEID),
				'Dispatcher', funcGetDesc("Search", "Particular", b.DispatchID),
				'MerchantName', funcGetDesc("Search", "Particular", a.MerchantID),
				'TID', c.TID,
				'MID', c.MID,
				'JobTypeDescription', funcGetDesc("Search", "Service JobType Description", a.JobType),
				'ActionMade', a.ActionMade,
				'geoLatitude', geoLatitude,
				'geoLongitude', geoLongitude,
				'geoCountry', geoCountry,
				'geoLocality', geoLocality,
				'geoAddress', geoAddress,
				'Reason', funcGetDesc("Search", "Reason", a.ReasonID),
				'IRNo', a.IRNo
				
			)AS detail_info
			FROM tblfsrdetail a 
			LEFT JOIN tblservicingdetail b ON a.ServiceNo = b.ServiceNo
			LEFT JOIN tblirdetail c ON b.IRIDNo = c.IRIDNo
			LEFT JOIN tblparticular d ON a.MerchantID = d.ParticularID
			WHERE 
			a.MobileID > 0
			AND a.FEID > 0 
			AND a.FEID = v_ID
			ORDER BY a.FSRNo DESC
			LIMIT 10;
			
		ELSEIF (p_SearchBy = 'FSR-Field Engineer Activity List-Remaining')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			    b.ServiceNo AS ID,
			    JSON_OBJECT
			    (
				'ServiceNo', b.ServiceNo,
				'RequestDate', IFNULL_FORMAT_DATE2(b.ReqInstallationDate),
				'TargetDate', IFNULL_FORMAT_DATE2(IF(b.JobType = 1, c.InstallationDate, b.ServiceReqDate)),
				'ScheduleDate', IFNULL_FORMAT_DATE2(b.ServiceReqDate),
				'ServicedDate', '-',
				'Region', funcGetDesc('Search', 'Region', d.RegionType),
				'Province', funcGetDesc('Search', 'Region Detail', d.RegionID),
				'SLA', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Get SLA', b.MerchantID)),
				'DaysOverDue', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Get DaysOverDue', CONCAT(b.MerchantID,'|',b.ServiceNo))),
				'NetworkDays', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Get NetworkDays', b.ServiceNo)),
				'TATStatus', IFNULL_STRING_ONLY(funcGetDesc('Search', 'Get TAT Status', IFNULL_NUMERIC(funcGetDesc('Search', 'Get DaysOverDue', CONCAT(b.MerchantID,'|',b.ServiceNo))))),
				'FEName', funcGetDesc('Search', 'Particular', b.FEID),
				'Dispatcher', funcGetDesc('Search', 'Particular', b.DispatchID),
				'MerchantName', funcGetDesc('Search', 'Particular', b.MerchantID),
				'TID', c.TID,
				'MID', c.MID,
				'JobTypeDescription', funcGetDesc('Search', 'Service JobType Description', b.JobType),
				'ActionMade', '-', 
				'geoLatitude', '-',
				'geoLongitude', '-',
				'geoCountry', '-',
				'geoLocality', '-',
				'geoAddress', '-',
				'Reason', '-', 
				'IRNo', c.IRNo
			    ) AS detail_info
			FROM tblservicingdetail b
			LEFT JOIN tblfsrdetail a ON a.ServiceNo = b.ServiceNo 
			LEFT JOIN tblirdetail c ON b.IRIDNo = c.IRIDNo
			LEFT JOIN tblparticular d ON b.MerchantID = d.ParticularID
			WHERE 
			    b.FEID = v_ID
			    AND a.ServiceNo IS NULL
			    AND b.JobTypeStatusDescription != 'COMPLETED'
			ORDER BY b.ServiceNo DESC;
			
		ELSEIF (p_SearchBy = 'FSR-Field Engineer Current Location')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			a.FSRNo AS ID,
			JSON_OBJECT
			(
				'ServicedDate', IFNULL_FORMAT_DATE2(a.FSRDate),
				'ServicedTime', (a.FSRTime),
				'geoLatitude', geoLatitude,
				'geoLongitude', geoLongitude,
				'geoCountry', geoCountry,
				'geoLocality', geoLocality,
				'geoAddress', geoAddress
				
			)AS detail_info
			FROM tblfsrdetail a 
			LEFT JOIN tblservicingdetail b ON a.ServiceNo = b.ServiceNo
			LEFT JOIN tblirdetail c ON b.IRIDNo = c.IRIDNo
			LEFT JOIN tblparticular d ON a.MerchantID = d.ParticularID
			WHERE 
			a.MobileID > 0
			AND a.FEID > 0 
			AND a.FEID = v_ID			
			ORDER BY a.FSRNo DESC
			LIMIT 1;
		
		ELSEIF (p_SearchBy = 'FSR-Field Engineer Previous Location')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT
			a.FSRNo AS ID,
			JSON_OBJECT
			(
				'ServicedDate', IFNULL_FORMAT_DATE2(a.FSRDate),	
				'ServicedTime', (a.FSRTime),			
				'geoLatitude', geoLatitude,
				'geoLongitude', geoLongitude,
				'geoCountry', geoCountry,
				'geoLocality', geoLocality,
				'geoAddress', geoAddress
				
			)AS detail_info
			FROM tblfsrdetail a 
			LEFT JOIN tblservicingdetail b ON a.ServiceNo = b.ServiceNo
			LEFT JOIN tblirdetail c ON b.IRIDNo = c.IRIDNo
			LEFT JOIN tblparticular d ON a.MerchantID = d.ParticularID
			WHERE 
			a.MobileID > 0
			AND a.FEID > 0 
			AND a.FEID = v_ID			
			ORDER BY a.FSRNo DESC
			LIMIT 1;
			
		ELSEIF (p_SearchBy = 'Active Detail Terminal')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|', 8));
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)) AS UNSIGNED INTEGER);
			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);
			
			/*
			SELECT CONCAT('v_ClientID = ', v_ClientID);
			SELECT CONCAT('v_LocationID = ', v_LocationID);
			SELECT CONCAT('v_StatusID = ', v_StatusID);
			SELECT CONCAT('v_TerminalTypeID = ', v_TerminalTypeID);
			SELECT CONCAT('v_TerminalModelID = ', v_TerminalModelID);
			SELECT CONCAT('v_DateFrom = ', v_DateFrom);
			SELECT CONCAT('v_DateTo = ', v_DateTo);
			SELECT CONCAT('v_SearchString = ', v_SearchString);
			SELECT CONCAT('v_RegionType = ', v_RegionType);
			SELECT CONCAT('v_RegionID = ', v_RegionID);
			*/
			
			SET p_WHERE = '';
			SET p_SQL = '';
			
			SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
				        'DISTINCT(vw.Terminal_ID) AS ID,'
				        'JSON_OBJECT(
						"TerminalSN", vw.Terminal_SN,
						"TerminalType", vw.Type,
						"TerminalModel", vw.Model,
						"TerminalStatus", vw.Status,
						"TerminalLocation", vw.Location,
						"TerminalDeliveryDate", IFNULL_FORMAT_DATE2(vw.Delivery_Date),
						"TerminalReceiveDate", IFNULL_FORMAT_DATE2(vw.Receive_Date),
						"TerminalReleasedDate", IFNULL_FORMAT_DATE2(vw.Released_Date),
						"PONo", (vw.PO_No),
						"InvNo", (vw.Inv_No),
						"PartNo", (vw.Part_No),
						"Asset", (vw.Asset),
						"Allocation", (vw.Allocation),
						#"JobType", IFNULL_NUMERIC(svc.JobType),
						#"ServiceNo", IFNULL_NUMERIC(svc.ServiceNo),
						#"ClientID", IFNULL_NUMERIC(svc.ClientID),
						#"IRIDNo", IFNULL_NUMERIC(svc.IRIDNo),
						#"MerchantID", IFNULL_NUMERIC(svc.MerchantID),
						#"TerminalTypeID", IFNULL_NUMERIC(vw.Type_ID),
						#"TerminalModelID", IFNULL_NUMERIC(vw.Model_ID),
						#"TerminalID", IFNULL_NUMERIC(vw.Terminal_ID),												
						"isTerminalSNMatch", IFNULL_STRING_ONLY2(IF(vw.Terminal_ID = ir.TerminalID, "MATCH", "NOT MATCH")),
						"TerminalUsedCount", IFNULL_STRING_ONLY2(funcGetCount("Search", "Terminal Used Count", vw.Terminal_ID)),
						"TerminalFirstInstalledDate", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Terminal 1st Installation", CONCAT(ir.ClientID, "|", vw.Terminal_ID))),
						"SIMSN", IFNULL_STRING_ONLY2(vws.Sim_SN),
						"SIMCarrier", IFNULL_STRING_ONLY2(vws.Carrier),
						"IRNo", IFNULL_STRING_ONLY2(ir.IRNo),
						"RequestDate", IFNULL_FORMAT_DATE2(ir.IRDate),
						"TargetInstallationDate", IFNULL_FORMAT_DATE2(ir.InstallationDate),
						"ServicedDate", IFNULL_FORMAT_DATE2(funcGetDesc("Search", "Merchant 1st Installation Date", CONCAT(vw.Client_ID, "|", "1", "|", ir.IRIDNo))),
						"InstalledDate", IFNULL_FORMAT_DATE2(funcGetDesc("Search", "Merchant Operational Period", CONCAT(ir.ClientID, "|", "1", "|", ir.IRIDNo))),
						"PulloutDate", IFNULL_FORMAT_DATE2(funcGetDesc("Search", "Merchant Operational Period", CONCAT(ir.ClientID, "|", "4", "|", ir.IRIDNo))),
						"OperationalPeriod", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Date Diff YMD", CONCAT(funcGetDesc("Search", "Merchant Operational Period", CONCAT(ir.ClientID, "|", "1", "|", ir.IRIDNo)), "|", funcGetDesc("Search", "Merchant Operational Period", CONCAT(ir.ClientID, "|", "4", "|", ir.IRIDNo))))),
						"OperationalStatus", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Terminal Operational Status", CONCAT(ir.ClientID, "|", "1", "|", ir.IRIDNo))),
						"OperationalAging", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Operational Aging", funcGetDesc("Search", "Merchant Operational Period", CONCAT(ir.ClientID, "|", "1", "|", ir.IRIDNo)))),
						"InventoryAging", IFNULL_STRING_ONLY2(funcGetDesc("Search", "Inventory Aging", vw.Receive_Date)),
						
						"StorageDurationAging", IFNULL_STRING_ONLY2(
										    funcGetDesc(
											"Search", 
											"Terminal Storage Duration", 
											CONCAT(
											    IFNULL_STRING_ONLY2(funcGetDesc("Search", "Terminal 1st Installation", CONCAT(ir.ClientID, "|", vw.Terminal_ID))),
											    "|",
											    IFNULL_STRING_ONLY2(vw.Delivery_Date)
											)
										    )
										),
										
						"MerchantName", IFNULL_STRING_ONLY2(pr.Name),
						"TID", IFNULL_STRING_ONLY2(ir.TID),
						"MID", IFNULL_STRING_ONLY2(ir.MID),
						#"RegionType", IFNULL_NUMERIC(pr.RegionType),
						"Region", IFNULL_STRING_ONLY2(vwp.Province),
						#"RegionID", IFNULL_NUMERIC(pr.RegionID),
						"Province", IFNULL_STRING_ONLY2(vwp.Region),
						"Address", IFNULL_STRING_ONLY2(pr.Address),
						"ContactPerson", IFNULL_STRING_ONLY2(pr.ContactPerson),
						"ContactPosition", IFNULL_STRING_ONLY2(pr.ContactPosition),
						"ContactNumber", IFNULL_STRING_ONLY2(pr.ContactNumber),									
						"AppVersion_", IFNULL_STRING_ONLY2(ir.AppVersion),
						"AppCRC", IFNULL_STRING_ONLY2(ir.AppCRC)							         
				        ) AS detail_info '				
					'FROM ',
					'vw_terminal_info vw ',					
					'LEFT JOIN tblirdetail ir ON vw.Terminal_ID = ir.TerminalID', ' ',
					'LEFT JOIN vw_sim_info vws ON vws.Sim_ID = ir.SIMID', ' ',
					'LEFT JOIN tblparticular pr ON ir.MerchantID = pr.ParticularID', ' '
					'LEFT JOIN vw_particular_info vwp ON vwp.ParticularID = ir.MerchantID', ' '					
					);
			
			# Set WHERE
			SET p_SQL = CONCAT(
				p_SQL,
				'WHERE', ' '
			    );
			
			# Filter Active
			SET p_SQL = CONCAT(
					p_SQL, ' ',
					'vw.isActive = 1', ' '
					);
			
			# With TerminalID
			/*
			SET p_SQL = CONCAT(
					p_SQL,
					'AND ir.TerminalID IS NOT NULL', ' '
					);
			*/
								
			IF (v_ClientID > 0 && v_StatusID = 7) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					 'AND', '(', ' ',' vw.Client_ID = ', v_ClientID, ')'
					);
			END IF;
			
			
			IF (v_LocationID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Loc_ID = ', v_LocationID, ' '
					);
			END IF;
			
			IF (v_StatusID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Status_ID = ', v_StatusID, ' '
					);
			END IF;
			
			IF (v_TerminalTypeID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Type_ID = ', v_TerminalTypeID, ' '
					);
			END IF;
			
			IF (v_TerminalModelID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Model_ID = ', v_TerminalModelID, ' '
					);
			END IF;
			
			IF (LENGTH(v_SearchString) > 0 AND v_SearchString != '0' AND v_SearchString != '[NOT SPECIFIED]') THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Terminal_SN LIKE ', ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)), ' '
					);
			END IF;
			
			SET p_GROUPBY = '';
			#SET p_GROUPBY = 'vw.Terminal_ID';
			IF (LENGTH(p_GROUPBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);
			END IF;
			
			SET p_ORDERBY = '';
			#SET p_ORDERBY = 'vw.Receive_Date ASC';
			#SET p_ORDERBY = 'funcGetCount("Search", "Terminal Used Count", vw.Terminal_ID) DESC';			
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
			END IF;
				
			# LIMIT
			#SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT 20');
			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));	
			
			SET p_SQL = CONCAT(p_SQL, ';');
			
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Process Type Breakdown')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_Year   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_Region   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT
			    IF(ProcessType = 'AUTO', '1', '2') AS ID,
			    JSON_OBJECT
			    (
				'ProcessType', ProcessType,
				'January', January,
				'February', February,
				'March', March,
				'April', April,
				'May', May,
				'June', June,
				'July', July,
				'August', August,
				'September', September,
				'October', October,
				'November', November,
				'December', December,
				'Total', Total
			    )AS detail_info
			FROM (
			    SELECT
				a.ProcessType,
				SUM(CASE WHEN MONTH(a.FSRDate) = 1 THEN 1 ELSE 0 END) AS January,
				SUM(CASE WHEN MONTH(a.FSRDate) = 2 THEN 1 ELSE 0 END) AS February,
				SUM(CASE WHEN MONTH(a.FSRDate) = 3 THEN 1 ELSE 0 END) AS March,
				SUM(CASE WHEN MONTH(a.FSRDate) = 4 THEN 1 ELSE 0 END) AS April,
				SUM(CASE WHEN MONTH(a.FSRDate) = 5 THEN 1 ELSE 0 END) AS May,
				SUM(CASE WHEN MONTH(a.FSRDate) = 6 THEN 1 ELSE 0 END) AS June,
				SUM(CASE WHEN MONTH(a.FSRDate) = 7 THEN 1 ELSE 0 END) AS July,
				SUM(CASE WHEN MONTH(a.FSRDate) = 8 THEN 1 ELSE 0 END) AS August,
				SUM(CASE WHEN MONTH(a.FSRDate) = 9 THEN 1 ELSE 0 END) AS September,
				SUM(CASE WHEN MONTH(a.FSRDate) = 10 THEN 1 ELSE 0 END) AS October,
				SUM(CASE WHEN MONTH(a.FSRDate) = 11 THEN 1 ELSE 0 END) AS November,
				SUM(CASE WHEN MONTH(a.FSRDate) = 12 THEN 1 ELSE 0 END) AS December,
				SUM(
				    CASE WHEN MONTH(a.FSRDate) BETWEEN 1 AND 12 THEN 1 ELSE 0 END
				) AS Total
			    FROM tblfsrdetail a
			    LEFT JOIN tblservicingdetail b ON b.ServiceNo = a.ServiceNo
			    LEFT JOIN tblparticular c ON b.MerchantID = c.ParticularID
			    LEFT JOIN tblregion d ON c.RegionType = d.RegionID
			    WHERE
				b.ClientID = v_ClientID
				AND YEAR(a.FSRDate) = v_Year
				AND a.ProcessType IN ('AUTO', 'MANUAL')
				AND (
					v_Region = '[NOT SPECIFIED]' OR v_Region = '0' OR d.Region = v_Region
				    )
			    GROUP BY a.ProcessType
			) AS summary
			ORDER BY ProcessType;
			
		ELSEIF (p_SearchBy = 'Service Result Breakdown')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_Year   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_Region   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_Temp   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SET @JobType = funcGetID("Search", "Service Job Type Description", v_Temp);
			
			SELECT
			    IF(ActionMade = 'SUCCESS', '1', '2') AS ID,
			    JSON_OBJECT
			    (
				'ActionMade', ActionMade,
				'January', January,
				'February', February,
				'March', March,
				'April', April,
				'May', May,
				'June', June,
				'July', July,
				'August', August,
				'September', September,
				'October', October,
				'November', November,
				'December', December,
				'Total', Total
			    ) AS detail_info
			FROM (
			    SELECT
				a.ActionMade,
				SUM(CASE WHEN MONTH(a.FSRDate) = 1 THEN 1 ELSE 0 END) AS January,
				SUM(CASE WHEN MONTH(a.FSRDate) = 2 THEN 1 ELSE 0 END) AS February,
				SUM(CASE WHEN MONTH(a.FSRDate) = 3 THEN 1 ELSE 0 END) AS March,
				SUM(CASE WHEN MONTH(a.FSRDate) = 4 THEN 1 ELSE 0 END) AS April,
				SUM(CASE WHEN MONTH(a.FSRDate) = 5 THEN 1 ELSE 0 END) AS May,
				SUM(CASE WHEN MONTH(a.FSRDate) = 6 THEN 1 ELSE 0 END) AS June,
				SUM(CASE WHEN MONTH(a.FSRDate) = 7 THEN 1 ELSE 0 END) AS July,
				SUM(CASE WHEN MONTH(a.FSRDate) = 8 THEN 1 ELSE 0 END) AS August,
				SUM(CASE WHEN MONTH(a.FSRDate) = 9 THEN 1 ELSE 0 END) AS September,
				SUM(CASE WHEN MONTH(a.FSRDate) = 10 THEN 1 ELSE 0 END) AS October,
				SUM(CASE WHEN MONTH(a.FSRDate) = 11 THEN 1 ELSE 0 END) AS November,
				SUM(CASE WHEN MONTH(a.FSRDate) = 12 THEN 1 ELSE 0 END) AS December,
				SUM(
				    CASE WHEN MONTH(a.FSRDate) BETWEEN 1 AND 12 THEN 1 ELSE 0 END
				) AS Total
			    FROM tblfsrdetail a
			    LEFT JOIN tblservicingdetail b ON b.ServiceNo = a.ServiceNo
			    LEFT JOIN tblparticular c ON b.MerchantID = c.ParticularID
			    LEFT JOIN tblregion d ON c.RegionType = d.RegionID
			    WHERE
				b.ClientID = v_ClientID
				AND YEAR(a.FSRDate) = v_Year
				AND b.JobType = @JobType
				AND a.ActionMade IN ('SUCCESS', 'NEGATIVE')
				AND (
				    v_Region = '[NOT SPECIFIED]' OR v_Region = '0' OR d.Region = v_Region
				)
			    GROUP BY a.ActionMade
			) AS summary
			ORDER BY FIELD(ActionMade, 'SUCCESS', 'NEGATIVE');
			
		ELSEIF (p_SearchBy = 'Request Type Breakdown')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_Year   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_Region   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_RequestType   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SET @RegionType = funcGetID("Search", "Region", v_Region);
			
			SELECT
			    xTable.TypeID AS ID,			  
			    JSON_OBJECT(
			      'TypeID', CASE 
				WHEN xTable.TypeID = 4 THEN 0
				WHEN xTable.TypeID = 5 THEN 1
				WHEN xTable.TypeID = 6 THEN 2
				WHEN xTable.TypeID = 8 THEN 3
				WHEN xTable.TypeID = 9 THEN 4
			      END,
			      'RequestType', xTable.Description,
			      'January', xTable.January,
			      'February', xTable.February,
			      'March', xTable.March,
			      'April', xTable.April,
			      'May', xTable.May,
			      'June', xTable.June,
			      'July', xTable.July,
			      'August', xTable.August,
			      'September', xTable.September,
			      'October', xTable.October,
			      'November', xTable.November,
			      'December', xTable.December,
			      'Total', (
					  IFNULL(xTable.January, 0) +
					  IFNULL(xTable.February, 0) +
					  IFNULL(xTable.March, 0) +
					  IFNULL(xTable.April, 0) +
					  IFNULL(xTable.May, 0) +
					  IFNULL(xTable.June, 0) +
					  IFNULL(xTable.July, 0) +
					  IFNULL(xTable.August, 0) +
					  IFNULL(xTable.September, 0) +
					  IFNULL(xTable.October, 0) +
					  IFNULL(xTable.November, 0) +
					  IFNULL(xTable.December, 0)
				)
			    ) AS detail_info
			  FROM (
			    SELECT
			       c.TypeID,
			       c.Description,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 1, "|", v_Region)) AS January,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 2, "|", v_Region)) AS February,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 3, "|", v_Region)) AS March,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 4, "|", v_Region)) AS April,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 5, "|", v_Region)) AS May,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 6, "|", v_Region)) AS June,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 7, "|", v_Region)) AS July,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 8, "|", v_Region)) AS August,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 9, "|", v_Region)) AS September,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 10, "|", v_Region)) AS October,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 11, "|", v_Region)) AS November,
				funcGetCount("Search", "Request Type Count", CONCAT(v_ClientID, "|", c.TypeID, "|", v_Year, "|", 12, "|", v_Region)) AS December,
				0 AS Total
			    FROM tblservicingdetail a 
			    LEFT JOIN tblirdetail b ON a.IRIDNo = b.IRIDNo 
			    LEFT JOIN tbltype c ON b.RequestTypeID = c.TypeID AND c.Type = 2
			    LEFT JOIN tblparticular d ON a.MerchantID = d.ParticularID			    
			    LEFT JOIN tblfsrdetail f ON a.ServiceNo = f.ServiceNo
			    WHERE
			      a.ClientID = v_ClientID
			      AND YEAR(a.ReqInstallationDate) = v_Year
			      AND c.TypeID IN (4,5,6,8,9)
			      AND (
				v_Region = '[NOT SPECIFIED]' OR v_Region = '0' OR d.RegionType = @RegionType
			      )
			      AND (
				v_RequestType = '[NOT SPECIFIED]' OR v_RequestType = '0' OR c.Description = v_RequestType
			      )	
			      AND (
				    funcGetDesc("Search", "Daily Service Status", CONCAT(a.ServiceStatus, "|", IFNULL(f.ActionMade, "")))
				    IN ('CANCELLED', 'HOLD', 'PENDING', 'NEGATIVE', 'RESOLVED')
				)		      
			      AND a.isActive > 0
			    GROUP BY c.TypeID
			  ) AS xTable
			  ORDER BY FIELD(xTable.Description, 'ADDITIONAL POS', 'EXHIBIT POS', 'NEW INSTALLATION', 'POS SWAPPING', 'REPROGRAMMING');
			  
		ELSEIF (p_SearchBy = 'Dashboard-Summary')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);

			SELECT 
			    r.RegionID AS ID,
			    JSON_OBJECT
			    (
				'RegionID', r.RegionID,
				'Region', r.Code,
				'TInstalled', funcFormatNumber(i.TInstalled, 0),
				'THoldService', funcFormatNumber(h.THoldService, 0),
				'TCancelService', funcFormatNumber(c.TCancelService, 0),
				'TPendingFSR', funcFormatNumber(d.TPendingFSR, 0)
			    ) AS detail_info
			FROM tblregion r

			# TInstalled
			LEFT JOIN (
				SELECT
				  uniq.RegionID,
				  COUNT(*) AS TInstalled
				FROM (
				    SELECT
				      td.TerminalID,
				      MIN(r.RegionID) AS RegionID
				    FROM tblregion r
				    LEFT JOIN tblparticular p
				      ON p.RegionType = r.RegionID
				    LEFT JOIN tblirdetail ir
				      ON ir.MerchantID = p.ParticularID
				    LEFT JOIN tblterminaldetail td
				      ON td.TerminalID = ir.TerminalID
				    WHERE
				      r.isActive > 0
				      AND td.isActive > 0
				      AND td.LocationID = 18
				      AND td.TerminalStatus = 7
				      AND td.ClientID = v_ClientID
				    GROUP BY
				      td.TerminalID
				) AS uniq
				GROUP BY
				  uniq.RegionID
				ORDER BY
				  uniq.RegionID
			) i ON i.RegionID = r.RegionID

			# THoldService
			LEFT JOIN (
			    SELECT 
				r.RegionID,
				COUNT(
				    CASE 
					WHEN sd.isActive > 0 
					  AND sd.ClientID = v_ClientID
					  AND sd.ServiceStatus = 9 # Hold Service
					  #AND YEAR(sd.ReqInstallationDate) = YEAR(CURDATE())
					THEN 1 
					ELSE NULL 
				    END
				) AS THoldService
			    FROM tblregion r
			    LEFT JOIN tblparticular p ON p.RegionType = r.RegionID
			    LEFT JOIN tblservicingdetail sd ON sd.MerchantID = p.ParticularID
			    WHERE 
				r.isActive > 0
				AND sd.ClientID = v_ClientID
			    GROUP BY r.RegionID
			) h ON h.RegionID = r.RegionID

			# TCancelService
			LEFT JOIN (
			    SELECT 
				r.RegionID,
				COUNT(
				    CASE 
					WHEN sd.isActive > 0 
					  AND sd.ClientID = v_ClientID
					  AND sd.ServiceStatus = 10 # Cancelled Service
					THEN 1 
					ELSE NULL 
				    END
				) AS TCancelService
			    FROM tblregion r
			    LEFT JOIN tblparticular p ON p.RegionType = r.RegionID
			    LEFT JOIN tblservicingdetail sd ON sd.MerchantID = p.ParticularID
			    WHERE 
				r.isActive > 0
				AND sd.ClientID = v_ClientID
			    GROUP BY r.RegionID
			) c ON c.RegionID = r.RegionID
			
			# TPendingFSR
			LEFT JOIN (
			    SELECT 
				r.RegionID,
				COUNT(
				    CASE 
					WHEN sd.isActive > 0 
					  AND sd.ClientID = v_ClientID
					  AND fd.isPDF != 1
					  AND fd.isDiagnostic != 1					  
					  AND fd.MobileID > 0
					  AND fd.ProcessType = 'AUTO'				
					THEN 1 
					ELSE NULL 
				    END
				) AS TPendingFSR
			    FROM tblregion r
			    LEFT JOIN tblparticular p ON p.RegionType = r.RegionID
			    LEFT JOIN tblservicingdetail sd ON sd.MerchantID = p.ParticularID
			    LEFT JOIN tblfsrdetail fd ON sd.ServiceNo = fd.ServiceNo
			    WHERE 
				r.isActive > 0
				AND sd.ClientID = v_ClientID
				#AND YEAR(sd.ReqInstallationDate) = YEAR(CURDATE())
				AND fd.isPDF != 1
				AND fd.isDiagnostic != 1	
				AND fd.MobileID > 0
				AND fd.ProcessType = 'AUTO'
			    GROUP BY r.RegionID
			) d ON d.RegionID = r.RegionID

			WHERE r.isActive > 0
			GROUP BY r.RegionID
			ORDER BY r.Region;
			
		ELSEIF (p_SearchBy = 'Dashboard-User Access Log')
		THEN
			SET @CurrentDate = CURRENT_DATE();
			#SET @CurrentDate = '2025-06-02';
			
			-- eMIS
			SELECT 
			  JSON_ARRAYAGG(
			    JSON_OBJECT(
			      'ID', b.ParticularID,
			      'FullName', funcGetDesc('Search', 'Particular', b.ParticularID),
			      'DateTime', a.LogDate,
			      'PublishVersion', a.PublishVersion
			    )
			  ) INTO @eMISData
			FROM tbluserlog a
			LEFT JOIN tbluser b ON a.UserID = b.UserID
			WHERE 
			  CAST(a.LogDate AS DATE) = @CurrentDate
			  AND a.ComputerName != 'Web Access'
			  AND a.LogDate = (
			    SELECT MIN(a2.LogDate)
			    FROM tbluserlog a2
			    WHERE a2.UserID = a.UserID
			      AND CAST(a2.LogDate AS DATE) = @CurrentDate
			      AND a2.ComputerName != 'Web Access'
			  );

			-- eFSR
			SELECT 
			  JSON_ARRAYAGG(
			    JSON_OBJECT(
			      'ID', a.FEID,
			      'FullName', funcGetDesc('Search', 'Particular', a.FEID),
			      'DateTime', CONCAT(a.FSRDate, ' ', a.FSRTime),
			      'PublishVersion', a.MobileVersion
			    )
			  ) INTO @eFSRData
			FROM tblfsrdetail a
			WHERE CAST(a.FSRDate AS DATE) = @CurrentDate
			  AND a.ProcessType = 'AUTO'
			  AND CONCAT(a.FSRDate, ' ', a.FSRTime) = (
			    SELECT MIN(CONCAT(b.FSRDate, ' ', b.FSRTime))
			    FROM tblfsrdetail b
			    WHERE b.FEID = a.FEID
			      AND CAST(b.FSRDate AS DATE) = @CurrentDate
			      AND b.ProcessType = 'AUTO'
			  );

			-- eDashboard			
			  SELECT 
			  JSON_ARRAYAGG(
			    JSON_OBJECT(
			      'ID', u.ParticularID,
			      'FullName', funcGetDesc('Search', 'Particular', u.ParticularID),
			      'DateTime', x.LogDate,
			      'PublishVersion', x.PublishVersion
			    )
			  ) INTO @eDashboardData
			FROM (
			  SELECT a.*
			  FROM tbluserlog a
			  WHERE CAST(a.LogDate AS DATE) = @CurrentDate
			    AND a.SessionStatus = 0
			    AND a.ComputerName = 'Web Access'
			    AND NOT EXISTS (
			      SELECT 1
			      FROM tbluserlog b
			      WHERE b.UserID = a.UserID
				AND CAST(b.LogDate AS DATE) = @CurrentDate
				AND b.SessionStatus = 0
				AND b.ComputerName = 'Web Access'
				AND b.LogDate < a.LogDate
			    )
			  GROUP BY a.UserID
			) AS X
			JOIN tbluser u ON x.UserID = u.UserID;

			-- Final Combined JSON
			SELECT
			  1 AS ID,
			  JSON_OBJECT
			  (
			    'eMIS', IFNULL(@eMISData, JSON_ARRAY()),
			    'eFSR', IFNULL(@eFSRData, JSON_ARRAY()),
			    'eDashboard', IFNULL(@eDashboardData, JSON_ARRAY())
			  ) AS detail_info;

		ELSEIF (p_SearchBy = 'Helpdesk Problem List')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));	
			
			SET p_WHERE = '';			
			SET p_SQL = '';
			
			SET p_SQL = CONCAT(
				p_SQL,
				"SELECT
					IFNULL_NUMERIC(a.AssistNo) AS ID,
					JSON_OBJECT(
					'AssistNo', a.AssistNo,
					'ProblemNo', b.ProblemNo,
					'JobType', a.JobType,
					'ReferenceNo', a.ReferenceNo,				
					'ClientID', c.ClientID,
					'IRIDNo', a.IRIDNo,
					'MerchantID', c.MerchantID,
					'ReasonID', b.ReasonID,
					'ProblemID', b.ProblemID,
					'RequestID', b.RequestID,
					'CreatedDate', IFNULL_FORMAT_DATE(b.CreatedDate),
					'RequestDate', IFNULL_FORMAT_DATE(b.RequestDate),
					'MerchantName', d.Name,
					'TID', c.TID,
					'MID', c.MID,
					'ProblemReported', funcGetDesc('Search', 'Reason', b.ProblemID),
					'Reason', funcGetDesc('Search', 'Reason', b.ReasonID),
					'CreatedBy', funcGetDesc('Search', 'Particular', a.CreatedID),
					'HelpdeskName', funcGetDesc('Search', 'Particular', b.HelpdeskID),
					'TeamLeadName', funcGetDesc('Search', 'Particular', b.TeamLeadID),
					'RemarksHelpDesk', b.RemarksService,
					'ServiceJobTypeDescription', e.ServiceJobTypeDescription			
					) AS detail_info				
				FROM
				tblhdmaster a
				LEFT JOIN tblhddetail b ON a.AssistNo = b.AssistNo
				LEFT JOIN tblirdetail c ON a.IRIDNo = c.IRIDNo
				LEFT JOIN tblparticular d ON c.MerchantID = d.ParticularID
				LEFT JOIN tblservicetype e ON a.JobType = e.JobType"			
				);
			
			# isActive (tblhdmaster)
			SET p_SQL = CONCAT(p_SQL,' ','WHERE a.isActive = 1', ' ');
				
			IF ((LENGTH(v_SearchString > 0)) && (STRCMP(v_SearchString, "0") != 0)) THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'AND');
				SET p_SQL = CONCAT(p_SQL, ' ', '(');
				SET p_SQL = CONCAT(p_SQL, ' ', 'a.ReferenceNo LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'd.Name LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'c.TID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				SET p_SQL = CONCAT(p_SQL, ' ', 'c.MID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				SET p_SQL = CONCAT(p_SQL, ' ', 'b.RequestID LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				SET p_SQL = CONCAT(p_SQL, ' ', 'funcGetDesc("Search", "Particular", b.HelpdeskID) LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');
				
				SET p_SQL = CONCAT(p_SQL, ' ', 'funcGetDesc("Search", "Particular", b.TeamLeadID) LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', 'OR');

				SET p_SQL = CONCAT(p_SQL, ' ', 'funcGetDesc("Search", "Reason", b.ProblemID) LIKE ');
				SET p_SQL = CONCAT(p_SQL, ADD_SINGLEQUOTE(ADD_PERCENT_CHAR(v_SearchString)));	
				SET p_SQL = CONCAT(p_SQL, ' ', ')');
			END IF;
							
			IF (v_ClientID > 0) THEN
				SET p_SQL = CONCAT(p_SQL,'AND c.ClientID = ', v_ClientID, ' ');
			END IF;
			
			# IRActive (tblirdetail)
			SET p_SQL = CONCAT(p_SQL,'AND c.IRActive = 1', ' ');
			
			# IRStatus (tblirdetail, INSTALLED)
			SET p_SQL = CONCAT(p_SQL,'AND c.IRStatus = 7', ' ');
			
			# Status = NEGATIVE
			SET p_SQL = CONCAT(p_SQL,'AND b.Status = ',ADD_SINGLEQUOTE('NEGATIVE'), ' ');
				
			#Order By
			SET p_ORDERBY = '';
			SET p_ORDERBY = '';				
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
			END IF;
			
			SET p_SQL = CONCAT(p_SQL,';');
			
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;

			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Dashboard Terminal Summary Inventory')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
			
			SELECT
			    d.TerminalStatusID AS ID,
			    JSON_OBJECT(
				'StatusID', d.TerminalStatusID,	
				'TerminalTypeID', b.TerminalTypeID,
				'TerminalType', b.Description,
				'TerminalModelID', c.TerminalModelID,
				'TerminalModel', c.Description,
				'Status', TRIM(d.Description),
				'Statuses',
				    (
					SELECT JSON_ARRAYAGG(JSON_OBJECT(
						    'StatusID', ts.TerminalStatusID,
						    'Status', TRIM(ts.Description)
						))
					FROM tblterminalstatus ts
					WHERE ts.TerminalStatusID IN (
					    SELECT DISTINCT a2.TerminalStatus
					    FROM tblterminaldetail a2
					    WHERE a2.TerminalTypeID = a.TerminalTypeID
					      AND a2.TerminalModelID = a.TerminalModelID
					      AND a2.isActive > 0
					)
				    ),
				'TInstalled', SUM(CASE WHEN d.TerminalStatusID = 7 AND a.LocationID = 18 THEN 1 ELSE 0 END),
				'TAvailable', SUM(CASE WHEN d.TerminalStatusID = 1 THEN 1 ELSE 0 END),
				'TDefective', SUM(CASE WHEN d.TerminalStatusID = 4 THEN 1 ELSE 0 END),
				'TAllocated', SUM(CASE WHEN d.TerminalStatusID = 2 THEN 1 ELSE 0 END),
				'TDispatch', SUM(CASE WHEN d.TerminalStatusID = 8 THEN 1 ELSE 0 END),
				'TBorrowed', SUM(CASE WHEN d.TerminalStatusID = 6 THEN 1 ELSE 0 END),
				'TLost', SUM(CASE WHEN d.TerminalStatusID = 5 THEN 1 ELSE 0 END),
				
				'Total',
					    SUM(CASE WHEN d.TerminalStatusID = 7 AND a.LocationID = 18 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN d.TerminalStatusID = 1 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN d.TerminalStatusID = 4 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN d.TerminalStatusID = 2 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN d.TerminalStatusID = 8 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN d.TerminalStatusID = 6 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN d.TerminalStatusID = 5 THEN 1 ELSE 0 END)
			    ) AS detail_info
			FROM tblterminaldetail a
			LEFT JOIN tblterminaltype b ON a.TerminalTypeID = b.TerminalTypeID
			LEFT JOIN tblterminalmodel c ON a.TerminalModelID = c.TerminalModelID
			LEFT JOIN tblterminalstatus d ON a.TerminalStatus = d.TerminalStatusID
			WHERE a.isActive > 0
			GROUP BY
			    b.TerminalTypeID,
			    c.TerminalModelID
			ORDER BY
			    b.Description,
			    c.Description;
			  
		ELSEIF (p_SearchBy = 'Dashboard SIM Summary Inventory')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
			
			SELECT
			    a.CarrierID AS ID,
			    JSON_OBJECT(
				'StatusID', b.TerminalStatusID,
				'Status', TRIM(b.Description),
				'Statuses',
				    (
					SELECT JSON_ARRAYAGG(JSON_OBJECT(
						    'StatusID', ts.TerminalStatusID,
						    'Status', TRIM(ts.Description)
						))
					FROM tblterminalstatus ts
					WHERE ts.TerminalStatusID IN (
					    SELECT DISTINCT a2.SIMStatus
					    FROM tblsimdetail a2
					    WHERE a2.CarrierID = a.CarrierID
					      AND a2.isActive > 0
					)
				    ),
				'CarrierID', a.CarrierID,
				'Carrier', c.Description,
				'TInstalled', SUM(CASE WHEN b.TerminalStatusID = 7 AND a.LocationID = 18 THEN 1 ELSE 0 END),
				'TAvailable', SUM(CASE WHEN b.TerminalStatusID = 1 THEN 1 ELSE 0 END),
				'TDefective', SUM(CASE WHEN b.TerminalStatusID = 4 THEN 1 ELSE 0 END),
				'TAllocated', SUM(CASE WHEN b.TerminalStatusID = 2 THEN 1 ELSE 0 END),
				'TDispatch', SUM(CASE WHEN b.TerminalStatusID = 8 THEN 1 ELSE 0 END),
				'TBorrowed', SUM(CASE WHEN b.TerminalStatusID = 6 THEN 1 ELSE 0 END),
				'TLost', SUM(CASE WHEN b.TerminalStatusID = 5 THEN 1 ELSE 0 END),
				
				'Total',
					    SUM(CASE WHEN b.TerminalStatusID = 7 AND a.LocationID = 18 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN b.TerminalStatusID = 1 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN b.TerminalStatusID = 4 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN b.TerminalStatusID = 2 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN b.TerminalStatusID = 8 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN b.TerminalStatusID = 6 THEN 1 ELSE 0 END)
					  + SUM(CASE WHEN b.TerminalStatusID = 5 THEN 1 ELSE 0 END)
			    ) AS detail_info
			FROM tblsimdetail a
			LEFT JOIN tblterminalstatus b ON a.SIMStatus = b.TerminalStatusID
			LEFT JOIN tbltype c ON a.CarrierID = c.TypeID
			WHERE a.isActive > 0
			GROUP BY a.CarrierID
			ORDER BY c.Description;
			
		ELSEIF (p_SearchBy = 'Dashboard-HelpDesk-Summary')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);

			SELECT 
			    r.RegionID AS ID,
			    JSON_OBJECT
			    (
				'RegionID', r.RegionID,
				'Region', r.Code,				
				'TForCreation', funcFormatNumber(f.TForCreation, 0),
				'TPendingHD', funcFormatNumber(phd.TPendingHD, 0),
				'TResolvedHD', funcFormatNumber(rhd.TResolvedHD, 0),
				'TGPendingHD', funcFormatNumber(gphd.TGPendingHD, 0),
				'TGResolvedHD', funcFormatNumber(grhd.TGResolvedHD, 0)
			    ) AS detail_info
			FROM tblregion r

			# TForCreation 
			LEFT JOIN (
			    SELECT 
				    r.RegionID AS RegionID,
				    COUNT(svc_unique.ServiceNo) AS TForCreation
				FROM tblregion r
				LEFT JOIN tblparticular p 
				    ON p.RegionType = r.RegionID
				INNER JOIN (
				    SELECT 
					svc.ServiceNo,
					svc.IRNo,
					svc.MerchantID
				    FROM tblservicingdetail svc
				    INNER JOIN tblhddetail a 
					ON a.RequestID = svc.IRNo
				    LEFT JOIN tblfsrdetail fsr 
					ON svc.ServiceNo = fsr.ServiceNo
				    WHERE 
					a.isActive > 0
					AND a.Status = 'NEGATIVE'
					AND fsr.ServiceNo IS NULL
					AND svc.ClientID = v_ClientID
				    GROUP BY
					svc.IRNo
				) AS svc_unique
				    ON svc_unique.MerchantID = p.ParticularID
				WHERE 
				    r.isActive > 0
				GROUP BY 
				    r.RegionID, r.Region
				ORDER BY 
				    r.RegionID
			) f ON f.RegionID = r.RegionID
			
			# TPendingHD 
			LEFT JOIN (
			    SELECT 
				e.RegionID,
				COUNT(
				    CASE 
					WHEN c.IRStatus > 0 AND a.Status = 'PENDING'
					THEN 1 
					ELSE NULL 
				    END
				) AS TPendingHD
			    FROM tblregion e
			    LEFT JOIN tblparticular d ON d.RegionType = e.RegionID
			    LEFT JOIN tblirdetail c ON c.MerchantID = d.ParticularID
			    LEFT JOIN tblhdmaster b ON b.IRIDNo = c.IRIDNo
			    LEFT JOIN tblhddetail a ON a.AssistNo = b.AssistNo				    			    	    
			    WHERE 
				e.isActive > 0
				AND c.ClientID = v_ClientID
				AND CAST(a.CreatedAt AS DATE) = CURRENT_DATE()
			    GROUP BY e.RegionID
			) phd ON phd.RegionID = r.RegionID
			
			# TResolvedHD 
			LEFT JOIN (
			    SELECT 
				e.RegionID,
				COUNT(
				    CASE 
					WHEN c.IRStatus > 0 AND a.Status = 'SUCCESS'
					THEN 1 
					ELSE NULL 
				    END
				) AS TResolvedHD
			    FROM tblregion e
			    LEFT JOIN tblparticular d ON d.RegionType = e.RegionID
			    LEFT JOIN tblirdetail c ON c.MerchantID = d.ParticularID
			    LEFT JOIN tblhdmaster b ON b.IRIDNo = c.IRIDNo
			    LEFT JOIN tblhddetail a ON a.AssistNo = b.AssistNo	
			    LEFT JOIN tblservicingdetail svc ON a.RequestID = svc.IRNo AND b.IRIDNo = svc.IRIDNo			    	    
			    WHERE 
				e.isActive > 0
				AND c.ClientID = v_ClientID
				AND CAST(a.CreatedAt AS DATE) = CURRENT_DATE()
			    GROUP BY e.RegionID
			) rhd ON rhd.RegionID = r.RegionID
			
			# TGPendingHD 
			LEFT JOIN (
			    SELECT 
				e.RegionID,
				COUNT(
				    CASE 
					WHEN c.IRStatus > 0 AND a.Status IN ('PENDING', 'NEGATIVE', 'SUCCESS')
					THEN 1 
					ELSE NULL 
				    END
				) AS TGPendingHD
			    FROM tblregion e
			    LEFT JOIN tblparticular d ON d.RegionType = e.RegionID
			    LEFT JOIN tblirdetail c ON c.MerchantID = d.ParticularID
			    LEFT JOIN tblhdmaster b ON b.IRIDNo = c.IRIDNo
			    LEFT JOIN tblhddetail a ON a.AssistNo = b.AssistNo	
			    LEFT JOIN tblservicingdetail svc ON a.RequestID = svc.IRNo AND b.IRIDNo = svc.IRIDNo
			    LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo		    
			    WHERE 
				e.isActive > 0
				AND c.ClientID = v_ClientID				
			    GROUP BY e.RegionID
			) gphd ON gphd.RegionID = r.RegionID
			
			# TGResolvedHD 
			LEFT JOIN (
			    SELECT 
				e.RegionID,
				COUNT(
				    CASE 
					WHEN c.IRStatus > 0 AND a.Status = 'SUCCESS'
					THEN 1 
					ELSE NULL 
				    END
				) AS TGResolvedHD
			    FROM tblregion e
			    LEFT JOIN tblparticular d ON d.RegionType = e.RegionID
			    LEFT JOIN tblirdetail c ON c.MerchantID = d.ParticularID
			    LEFT JOIN tblhdmaster b ON b.IRIDNo = c.IRIDNo
			    LEFT JOIN tblhddetail a ON a.AssistNo = b.AssistNo	
			    LEFT JOIN tblservicingdetail svc ON a.RequestID = svc.IRNo AND b.IRIDNo = svc.IRIDNo
			    LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo		    
			    WHERE 
				e.isActive > 0
				AND c.ClientID = v_ClientID				
			    GROUP BY e.RegionID
			) grhd ON grhd.RegionID = r.RegionID

			WHERE r.isActive > 0
			GROUP BY r.RegionID
			ORDER BY r.Region;
		
		ELSEIF (p_SearchBy = 'Report Group')
		THEN
			SET @ReportGroup = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT 
			a.ReportID AS ID,
			JSON_OBJECT
			(
			   'ReportID', a.ReportID,
			   'ReportDesc', a.ReportDesc
			) AS detail_info
			FROM tblreport a 
			WHERE 
			a.isActive > 0
			AND a.ReportGroup = @ReportGroup;
			
		ELSEIF (p_SearchBy = 'ERM Settlement Report-Per Month')
		THEN
			SET v_DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT 
    
			    TID AS ID,
			    JSON_OBJECT(
				'TID', TID,
				'MerchantName', MerchantName,
				'January',   FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 1  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'February',  FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 2  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'March',     FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 3  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'April',     FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 4  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'May',       FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 5  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'June',      FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 6  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'July',      FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 7  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'August',    FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 8  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'September', FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 9  THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'October',   FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 10 THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'November',  FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 11 THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'December',  FORMAT(SUM(CASE WHEN MONTH(STR_TO_DATE(Field5, '%d-%b-%Y')) = 12 THEN CAST(Field10 AS DECIMAL(15,2)) ELSE 0 END), 2),
				'Total',     FORMAT(SUM(CAST(Field10 AS DECIMAL(15,2))), 2)
				
			    ) AS detail_info
			  
			FROM tbltempsettlement
			WHERE 
			    isActive > 0
			    AND (
				   (v_DateFrom = '0000-00-00' OR v_DateTo = '0000-00-00')
				   OR (TransDate BETWEEN v_DateFrom AND v_DateTo)
				)
			    AND (
				    v_SearchString = ''
				    OR MerchantName LIKE CONCAT('%', v_SearchString, '%')
				    OR TID LIKE CONCAT('%', v_SearchString, '%')
				)
			    
			GROUP BY 
			    TID,
			    MerchantName

			ORDER BY MerchantName, TID;
			
		ELSEIF (p_SearchBy = 'ERM Settlement Report-Per Trans Type')
		THEN
			SET v_DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));	
			
			SELECT
			    TID AS ID,
			    
			    JSON_OBJECT
			    (
			      'TID', TID,
			      'MerchantName', MerchantName,
			      'Credit', FORMAT(SUM(CASE 
				WHEN TRIM(Field2) LIKE '%0000400%' THEN CAST(Field10 AS DECIMAL(15,2))
				ELSE 0 END), 2),
			      'Debit', FORMAT(SUM(CASE 
				WHEN TRIM(Field2) LIKE '%8699082%' THEN CAST(Field10 AS DECIMAL(15,2))
				ELSE 0 END), 2),
			       'QRPay', FORMAT(SUM(CASE 
				WHEN TRIM(Field2) LIKE '%0001505%' THEN CAST(Field10 AS DECIMAL(15,2))
				ELSE 0 END), 2),
			       'QRPh', FORMAT(SUM(CASE 
				WHEN TRIM(Field2) LIKE '%8000000%' THEN CAST(Field10 AS DECIMAL(15,2))
				ELSE 0 END), 2),
				'Total', FORMAT(SUM(
				CASE 
				    WHEN TRIM(Field2) LIKE '%0000400%' THEN CAST(Field10 AS DECIMAL(15,2))
				    WHEN TRIM(Field2) LIKE '%8699082%' THEN CAST(Field10 AS DECIMAL(15,2))
				    WHEN TRIM(Field2) LIKE '%0001505%' THEN CAST(Field10 AS DECIMAL(15,2))
				    WHEN TRIM(Field2) LIKE '%8000000%' THEN CAST(Field10 AS DECIMAL(15,2))
				    ELSE 0 END
			    ), 2)    
			      
			    ) AS detail_info
			    
			FROM tbltempsettlement
			WHERE 
			    isActive > 0
			    AND (
				  (v_DateFrom = '0000-00-00' OR v_DateTo = '0000-00-00')
			          OR (TransDate BETWEEN v_DateFrom AND v_DateTo)
				)
			    AND (
				    v_SearchString = ''
				    OR MerchantName LIKE CONCAT('%', v_SearchString, '%')
				    OR TID LIKE CONCAT('%', v_SearchString, '%')
				)

			GROUP BY 
			    TID,
			    MerchantName

			ORDER BY MerchantName, TID;
			
		ELSEIF (p_SearchBy = 'ERM Settlement Report-Per Top Sales')
		THEN
			SET v_DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT 
			    t.TID AS ID,
			    JSON_OBJECT
			    (
			      'TID', t.TID,
			      'MerchantName', t.MerchantName,
			      'Total', FORMAT(t.Total, 2)
			    ) AS detail_info
			    
			FROM (
			    SELECT
				TID,
				MerchantName,
				SUM(
				    CASE 
					WHEN TRIM(Field2) LIKE '%0000400%' THEN CAST(Field10 AS DECIMAL(15,2))
					WHEN TRIM(Field2) LIKE '%8699082%' THEN CAST(Field10 AS DECIMAL(15,2))
					WHEN TRIM(Field2) LIKE '%0001505%' THEN CAST(Field10 AS DECIMAL(15,2))
					WHEN TRIM(Field2) LIKE '%8000000%' THEN CAST(Field10 AS DECIMAL(15,2))
					ELSE 0 END
				) AS Total
			    FROM tbltempsettlement
			    WHERE 
				    isActive > 0
				    AND (
					   (v_DateFrom = '0000-00-00' OR v_DateTo = '0000-00-00')
					   OR (TransDate BETWEEN v_DateFrom AND v_DateTo)
					)
				    AND (
					    v_SearchString = ''
					    OR MerchantName LIKE CONCAT('%', v_SearchString, '%')
					    OR TID LIKE CONCAT('%', v_SearchString, '%')
					)
			    
			    GROUP BY 
				TID,
				MerchantName
			) AS t
			ORDER BY t.Total DESC
			LIMIT 15;
			
		ELSEIF (p_SearchBy = 'ERM Settlement Report-Per Qtr')
		THEN
			SET v_DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT 
			     1 AS ID,
			     JSON_OBJECT
			     (
				'Quarter', CASE 
						WHEN QUARTER(STR_TO_DATE(Field5, '%d-%b-%Y')) = 1 THEN 'Q1'
						WHEN QUARTER(STR_TO_DATE(Field5, '%d-%b-%Y')) = 2 THEN 'Q2'
						WHEN QUARTER(STR_TO_DATE(Field5, '%d-%b-%Y')) = 3 THEN 'Q3'
						WHEN QUARTER(STR_TO_DATE(Field5, '%d-%b-%Y')) = 4 THEN 'Q4'
					    END,
				'Total', FORMAT(SUM(CAST(Field10 AS DECIMAL(15,2))), 2)
			    
			     ) AS detail_info
			FROM tbltempsettlement
			WHERE 
				    isActive > 0
				    AND (
					  (v_DateFrom = '0000-00-00' OR v_DateTo = '0000-00-00')
					  OR (TransDate BETWEEN v_DateFrom AND v_DateTo)
					)
				    AND (
					    v_SearchString = ''
					    OR MerchantName LIKE CONCAT('%', v_SearchString, '%')
					    OR TID LIKE CONCAT('%', v_SearchString, '%')
					)
				    AND STR_TO_DATE(Field5, '%d-%b-%Y') IS NOT NULL
				    
			GROUP BY 
			    QUARTER(STR_TO_DATE(Field5, '%d-%b-%Y'))
			ORDER BY 
			    QUARTER(STR_TO_DATE(Field5, '%d-%b-%Y'));
			    
		ELSEIF (p_SearchBy = 'ERM Settlement Report-Summary')
		THEN
			SELECT 
			    tt.TransTypeID,
			    tt.Description,
			    COALESCE(MIN(ts.TransDate), '-') AS Start_Time,
			    COALESCE(MAX(ts.TransDate), '-') AS End_Time,
			    COALESCE(COUNT(ts.TID), '0') AS `Count`,
			    COALESCE(FORMAT(SUM(CAST(ts.Field10 AS DECIMAL(15,2))), 2), '0.00') AS Amount
			FROM 
			    tbltranstype tt
			LEFT JOIN 
			    tbltempsettlement ts 
				ON tt.TransTypeID = ts.TransTypeID
				AND ts.isActive > 0
			WHERE 
			    tt.isActive > 0
			GROUP BY 
			    tt.TransTypeID,
			    tt.Description
			ORDER BY 
			    tt.TransTypeID;
			    
		ELSEIF (p_SearchBy = 'Helpdesk-Callout For Dispatch')
		THEN
			SET @JobType   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @TicketStatus   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @ServiceStatus   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @HelpdeskID   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET @TeamLeadID   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET @SearchString   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			
			SELECT 
			    svc.ServiceNo AS ID,
			    JSON_OBJECT(
				'ServiceNo', svc.ServiceNo,
				'IRNo', a.RequestID,
				'ServiceJobTypeDescription', st.ServiceJobTypeDescription,
				'MerchantName', pt.Name,
				'TID', ir.TID,
				'MID', ir.MID,
				'HelpDesk', funcGetDesc("Search", "Particular", a.HelpdeskID),
				'TeamLead', funcGetDesc("Search", "Particular", a.TeamLeadID),
				'FEName', funcGetDesc("Search", "Particular", svc.FEID),
				'Dispatcher', funcGetDesc("Search", "Particular", svc.DispatchID),
				'ProblemReported', IFNULL_STRING_ONLY2(a.ProblemReported),
				'ActualProblem', IFNULL_STRING_ONLY2(a.ActualProblem),
				'Reason', IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", a.ReasonID)),
				'ReqInstallationDate', IFNULL_FORMAT_DATE(svc.ReqInstallationDate),
				'ServiceReqDate', IFNULL_FORMAT_DATE(svc.ServiceReqDate),
				'ServiceDate', IFNULL_FORMAT_DATE(svc.ServiceDate),
				'TicketDate', IFNULL_FORMAT_DATETIME_AMPM(a.CreatedDate),
				'ActionMade', IFNULL_STRING_ONLY2(fsr.ActionMade),
				'TerminalSN', IFNULL_STRING_ONLY2(funcGetDesc("Search", "Terminal Detail", ir.TerminalID)),
				'SIMSN', IFNULL_STRING_ONLY2(funcGetDesc("Search", "SIM Detail", ir.SIMID)),
				'ContactPerson', IFNULL_STRING_ONLY2(a.ContactPerson),
				'ContactNo', IFNULL_STRING_ONLY2(a.ContactNo),
				'ContactPosition', IFNULL_STRING_ONLY2(a.ContactPosition),
				'RequestedBy', IFNULL_STRING_ONLY2(a.RequestedBy),
				'Representative', IFNULL_STRING_ONLY2(a.Representative),
				'AssistNo', a.AssistNo,
				'ProblemNo', a.ProblemNo,
				'TicketStatus', funcGetDesc("Search", "Return Ticket Status", a.Status),
				'ServiceStatus', funcGetDesc("Search", "Return Service Status", svc.JobTypeStatusDescription),
				'ActionMade', fsr.ActionMade,
				'TimeAssistAt', IFNULL_FORMAT_DATETIME_AMPM(a.TimeAssisted)
			    ) AS detail_info
			FROM tblhddetail a
			LEFT JOIN tblhdmaster b ON a.AssistNo = b.AssistNo
			LEFT JOIN tblservicingdetail svc ON a.AssistNo = svc.AssistNo AND a.ProblemNo = svc.ProblemNo
			LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo
			LEFT JOIN tblirdetail ir ON b.IRIDNo = ir.IRIDNo
			LEFT JOIN tblparticular pt ON ir.MerchantID = pt.ParticularID
			LEFT JOIN tblparticular ptd ON a.HelpdeskID = ptd.ParticularID AND ptd.ParticularTypeID = 3
			LEFT JOIN tblparticular ptm ON a.TeamLeadID = ptm.ParticularID AND ptm.ParticularTypeID = 3
			LEFT JOIN tblservicetype st ON b.JobType = st.JobType
			WHERE a.isActive > 0
			  AND (@JobType = '0' OR @JobType = '' OR b.JobType = @JobType)
			  AND (@TicketStatus = '0' OR @TicketStatus = '' OR a.Status = @TicketStatus)
			  AND (@ServiceStatus = '0' OR @ServiceStatus = '' OR svc.JobTypeStatusDescription = @ServiceStatus)
			  AND (@HelpdeskID = '0' OR @HelpdeskID = '' OR a.HelpdeskID = @HelpdeskID)
			  AND (@TeamLeadID = '0' OR @TeamLeadID = '' OR a.TeamLeadID = @TeamLeadID)
			  AND (@SearchString = '' OR (
				a.RequestedBy LIKE CONCAT('%', @SearchString, '%')
				OR a.ProblemReported LIKE CONCAT('%', @SearchString, '%')
				OR a.ActualProblem LIKE CONCAT('%', @SearchString, '%')
				OR a.RequestID LIKE CONCAT('%', @SearchString, '%')
				OR ir.TID LIKE CONCAT('%', @SearchString, '%')
				OR ir.MID LIKE CONCAT('%', @SearchString, '%')
				OR pt.Name LIKE CONCAT('%', @SearchString, '%')
				OR ptd.Name LIKE CONCAT('%', @SearchString, '%')
				OR ptm.Name LIKE CONCAT('%', @SearchString, '%')
				OR svc.IRNo LIKE CONCAT('%', @SearchString, '%')
			  ))
			GROUP BY a.RequestID
			ORDER BY a.CreatedDate DESC;
			
		ELSEIF (p_SearchBy = 'Inventory Bulk Cross-Check List')
		THEN
		
			    SET @Mode = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));	
			    SET @InventoryType = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
			    SET @SNList = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));

			    -- Convert CSV to rows using JSON trick
			    SET @json = CONCAT('["', REPLACE(@SNList, ',', '","'), '"]');

			    IF @InventoryType = 'SIM' THEN

				WITH input_sim AS
				(
				    SELECT DISTINCT TRIM(j.sn) AS sn
				    FROM JSON_TABLE(
					@json,
					'$[*]' COLUMNS (
					    sn VARCHAR(50) PATH '$'
					)
				    ) j
				    WHERE TRIM(j.sn) <> ''
				)
				SELECT
				    a.SIMID AS ID,
				    JSON_OBJECT(
					'ID', a.SIMID,
					'SerialNo', t.sn,
					'Result',
					    CASE
						WHEN EXISTS (
						    SELECT 1
						    FROM tblservicingdetail b
						    WHERE b.SIMID = a.SIMID
						       OR b.ReplaceSIMID = a.SIMID
						)
						THEN 'RESTRICTED'
						ELSE 'DUPLICATE'
					    END
				    ) AS detail_info
				FROM input_sim t
				INNER JOIN tblsimdetail a
				    ON a.SIMSN = t.sn;

			    END IF;      
		  
			 IF @InventoryType = 'Terminal' THEN

			    WITH input_terminal AS
			    (
				SELECT DISTINCT TRIM(j.sn) AS sn
				FROM JSON_TABLE(
				    @json,
				    '$[*]' COLUMNS (
					sn VARCHAR(50) PATH '$'
				    )
				) j
				WHERE TRIM(j.sn) <> ''
			    )
			    SELECT
				a.TerminalID AS ID,
				JSON_OBJECT(
				    'ID', a.TerminalID,
				    'SerialNo', t.sn,
				    'Result',
					CASE
					    WHEN EXISTS (
						SELECT 1
						FROM tblservicingdetail b
						WHERE b.TerminalID = a.TerminalID
						   OR b.ReplaceTerminalID = a.TerminalID
					    )
					    THEN 'RESTRICTED'
					    ELSE 'DUPLICATE'
					END
				) AS detail_info
			    FROM input_terminal t
			    INNER JOIN tblterminaldetail a
				ON a.TerminalSN = t.sn;

			END IF;
			
		ELSEIF  (p_SearchBy = 'Billing-Type')
		THEN
			-- SET @Id = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
			
			SELECT 
					type_id AS ID,
					JSON_OBJECT(
							'ID', type_id,
							'Description', `description`
					) AS detail_info
			FROM tblbilling_type
			WHERE is_active = 1;
						
		ELSEIF (p_SearchBy = 'FSR Service Detail')
		    THEN        
			SET @JobType    = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @ServiceNo  = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));            
			SET @DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @DateTo     = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET @Search     = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET @FSRMode    = TRIM(SPLIT_STRING(p_SearchValue, '|', 6));
			SET @ParticularID = TRIM(SPLIT_STRING(p_SearchValue, '|', 7));
						
			SELECT
			    a.FSRNo AS ID,
			    JSON_OBJECT
			    (
				'JobType', a.JobType,
				'JobTypeDescription', funcGetDesc('Search', 'Service JobType Description', a.JobType),
				'FSRNo', a.FSRNo,
				'ServiceNo', a.ServiceNo,
				'IRIDNo', a.IRIDNo,
				'IRNo', a.IRNo,
				'FSRDate', a.FSRDate,
				'FSRTime', a.FSRTime,
				'RequestDate', b.ReqInstallationDate,
				'ScheduleDate', b.ServiceReqDate,
				'TID', c.TID,
				'MID', c.MID,
				'MerchantName', d.Name,
				'ActionMade', a.ActionMade,
				'MobileID', a.MobileID,
				'ProcessType', a.ProcessType,
				'ServiceResult', IFNULL_STRING_ONLY(a.ActionMade),
				'DaysOverDue',   IFNULL_STRING_ONLY(funcGetDaysOverDue("Search", "Days OverDue", a.ServiceNo)),
				'TATStatus',     IFNULL_STRING_ONLY(funcGetTATStatus("Search", "TAT Status", a.ServiceNo)),
				'FEName', funcGetDesc('Search', 'Particular', b.FEID)
			    ) AS detail_info
			FROM
			    tblfsrdetail a
			    LEFT JOIN tblservicingdetail b ON a.ServiceNo = b.ServiceNo
			    LEFT JOIN tblirdetail c ON a.IRIDNo = c.IRIDNo
			    LEFT JOIN tblparticular d ON a.MerchantID = d.ParticularID
			    LEFT JOIN tblparticular fe ON a.FEName = fe.Name
			WHERE
			    (
				@JobType = '0'
				OR a.JobType = @JobType
			    )
			AND DATE(a.FSRDate) BETWEEN DATE(@DateFrom) AND DATE(@DateTo)
			AND (
			    @Search = ''
			    OR a.ServiceNo     LIKE CONCAT('%', @Search, '%')
			    OR a.IRNo          LIKE CONCAT('%', @Search, '%')
			    OR c.TID           LIKE CONCAT('%', @Search, '%')
			    OR d.Name          LIKE CONCAT('%', @Search, '%')
			)
			AND (
			    @FSRMode = '' OR @FSRMode = '[NOT SPECIFIED]'  -- SHOW ALL
			    OR (@FSRMode = 'DIGITAL FSR' AND a.MobileID >= 1)
			    OR (@FSRMode = 'MANUAL FSR'  AND a.MobileID = 0)
			)
			AND (
			    @ParticularID = '0'
			    OR fe.ParticularID = @ParticularID
			)
			ORDER BY a.FSRDate;
			
		ELSEIF (p_SearchBy = 'Particular List By Type')
		THEN
			SET @Type = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
			
			IF (@Type = 1) # Field Engineer
			THEN
				SELECT
				IFNULL_NUMERIC(a.ParticularID) AS ID,
				JSON_OBJECT(
				'ParticularID', IFNULL_NUMERIC(a.ParticularID),
				'Name', IFNULL_STRING_ONLY(a.Name),
				'Address', IFNULL_STRING_ONLY(a.Address),
				'Position', IFNULL_STRING_ONLY(b.Description),
				'Department', IFNULL_STRING_ONLY(c.Description)
				) AS detail_info
				FROM tblparticular a 
				LEFT JOIN tblposition b ON a.PositionID = b.PositionID
				LEFT JOIN tbldepartment c ON a.DepartmentID = c.DepartmentID
				WHERE 
				b.PositionType = 1
				AND c.DepartmentID = 5
				AND a.isActive > 0
				ORDER BY a.Name;

			ELSEIF (@Type = 2) # Admin
			THEN
				SELECT
				IFNULL_NUMERIC(a.ParticularID) AS ID,
				JSON_OBJECT(
				'ParticularID', IFNULL_NUMERIC(a.ParticularID),
				'Name', IFNULL_STRING_ONLY(a.Name),
				'Address', IFNULL_STRING_ONLY(a.Address),
				'Position', IFNULL_STRING_ONLY(b.Description),
				'Department', IFNULL_STRING_ONLY(c.Description)
				) AS detail_info
				FROM tblparticular a 
				LEFT JOIN tblposition b ON a.PositionID = b.PositionID
				LEFT JOIN tbldepartment c ON a.DepartmentID = c.DepartmentID
				WHERE 				
				c.DepartmentID IN (3, 4)
				AND a.isActive > 0
				ORDER BY a.Name;
				
			ELSEIF (@Type = 3) # Finance
			THEN
				SELECT
				IFNULL_NUMERIC(a.ParticularID) AS ID,
				JSON_OBJECT(
				'ParticularID', IFNULL_NUMERIC(a.ParticularID),
				'Name', IFNULL_STRING_ONLY(a.Name),
				'Address', IFNULL_STRING_ONLY(a.Address),
				'Position', IFNULL_STRING_ONLY(b.Description),
				'Department', IFNULL_STRING_ONLY(c.Description)
				) AS detail_info
				FROM tblparticular a 
				LEFT JOIN tblposition b ON a.PositionID = b.PositionID
				LEFT JOIN tbldepartment c ON a.DepartmentID = c.DepartmentID
				WHERE 				
				c.DepartmentID = 8
				AND a.isActive > 0
				ORDER BY a.Name;
			END IF;
			
		ELSEIF (p_SearchBy = 'Zoning Lookup')
		THEN
			SET @Type = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
			
			IF (@Type = 'Cluster')
			    THEN

				SELECT
				    ZoneID AS ID,
				    JSON_OBJECT(
					'Description', IFNULL_STRING_NORMAL(Cluster)
				    ) AS detail_info
				FROM tblzoning
				GROUP BY Cluster
				ORDER BY Cluster;

			    ELSEIF (@Type = 'Region')
			    THEN

				SELECT
				    ZoneID AS ID,
				    JSON_OBJECT(
					'Description', IFNULL_STRING_NORMAL(Region)
				    ) AS detail_info
				FROM tblzoning
				GROUP BY Region
				ORDER BY Region;

			    ELSEIF (@Type = 'Area')
			    THEN

				SELECT
				    ZoneID AS ID,
				    JSON_OBJECT(
					'Description', AREA
				    ) AS detail_info
				FROM tblzoning
				GROUP BY AREA
				ORDER BY AREA;

			    ELSEIF (@Type = 'City')
			    THEN

				SELECT
				    ZoneID AS ID,
				    JSON_OBJECT(
					'Description', IFNULL_STRING_NORMAL(CityMunicipal)
				    ) AS detail_info
				FROM tblzoning
				GROUP BY CityMunicipal
				ORDER BY CityMunicipal;

			    ELSEIF (@Type = 'Zone')
			    THEN

				SELECT
				    ZoneID AS ID,
				    JSON_OBJECT(
					'Description', IFNULL_STRING_NORMAL(ZoneName)
				    ) AS detail_info
				FROM tblzoning
				GROUP BY ZoneName
				ORDER BY ZoneName;

			    END IF;
			    
		ELSEIF (p_SearchBy = 'Zoning List')
		THEN
			SET @Search = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
			
			SELECT
			ZoneID AS ID,
			JSON_OBJECT
			(
				'ZoneID', a.ZoneID,
				'Cluster', IFNULL_STRING_NORMAL(a.Cluster),
				'Zone', IFNULL_STRING_NORMAL(a.ZoneName),				
				'Region', IFNULL_STRING_NORMAL(a.Region),
				'Area', IFNULL_STRING_NORMAL(a.Area),
				'CityMunicipal', IFNULL_STRING_NORMAL(a.CityMunicipal),
				'SLA', IFNULL_STRING_NORMAL(a.SLA)
			) AS detail_info

			FROM
			
			tblzoning a
			
			WHERE
				(
				    IFNULL(@Search,'') = ''
				    OR IFNULL(@Search,'0') = '0'

				    OR UPPER(a.Cluster) LIKE CONCAT('%',UPPER(@Search),'%')
				    OR UPPER(a.ZoneName) LIKE CONCAT('%',UPPER(@Search),'%')
				    OR UPPER(a.Region) LIKE CONCAT('%',UPPER(@Search),'%')
				    OR UPPER(a.Area) LIKE CONCAT('%',UPPER(@Search),'%')
				    OR UPPER(a.CityMunicipal) LIKE CONCAT('%', UPPER(@Search), '%')
				    
				    -- First word of search 
				    OR (LENGTH(SUBSTRING_INDEX(@Search,' ',1)) >= 4 AND UPPER(a.CityMunicipal) LIKE CONCAT('%', UPPER(SUBSTRING_INDEX(@Search,' ',1)), '%'))

				    -- Reverse matching 
				    OR UPPER(@Search) LIKE CONCAT('%', UPPER(SUBSTRING_INDEX(a.CityMunicipal,'/',1)), '%')
				)
				
			ORDER BY
			
			a.CityMunicipal;
			
		ELSEIF (p_SearchBy = 'Incentives Service Detail')
		THEN		
			SET @FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET @DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT
			a.FSRNo AS ID,
			JSON_OBJECT
			(
				'ServiceNo', a.ServiceNo,
				'RequestDate', IFNULL_FORMAT_DATE2(b.ReqInstallationDate),
				'TargetDate', IFNULL_FORMAT_DATE2(IF(b.JobType = 1, c.InstallationDate, b.ServiceReqDate)),
				'ScheduleDate', IFNULL_FORMAT_DATE2(b.ServiceReqDate),
				'ServicedDate', CONCAT(IFNULL_FORMAT_DATE2(a.FSRDate),' ',a.FSRTime),
				'Region', funcGetDesc("Search", "Region", d.RegionType),
				'Province', funcGetDesc("Search", "Region Detail", d.RegionID),
				'SLA', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get SLA", a.MerchantID)),
				'DaysOverDue', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get DaysOverDue", CONCAT(a.MerchantID,"|",a.ServiceNo))),
				'NetworkDays', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get NetworkDays", a.ServiceNo)),
				'TATStatus', IFNULL_STRING_ONLY(funcGetDesc("Search", "Get TAT Status", IFNULL_NUMERIC(funcGetDesc("Search", "Get DaysOverDue", CONCAT(a.MerchantID,"|",a.ServiceNo))))),
				'FEID', a.FEID,
				'FEName', funcGetDesc("Search", "Particular", a.FEID),
				'Dispatcher', funcGetDesc("Search", "Particular", b.DispatchID),
				'MerchantID', a.MerchantID,
				'MerchantName', funcGetDesc("Search", "Particular", a.MerchantID),
				'TID', c.TID,
				'MID', c.MID,
				'JobTypeDescription', funcGetDesc("Search", "Service JobType Description", a.JobType),
				'ActionMade', a.ActionMade,
				'geoLatitude', geoLatitude,
				'geoLongitude', geoLongitude,
				'geoCountry', geoCountry,
				'geoLocality', geoLocality,
				'geoAddress', geoAddress,
				'Reason', funcGetDesc("Search", "Reason", a.ReasonID),
				'IRNo', a.IRNo,
				'FSRDate', IFNULL_FORMAT_DATE2(a.FSRDate),
				'FSRTime', a.FSRTime,
				'TimeArrived', a.TimeArrived,
				'TimeStart', a.TimeStart,
				'TimeEnd', a.TimeEnd,
				'ZoneName', funcGetDesc("Search", "ZoneName", d.ZoneID)
				
			)AS detail_info
			FROM tblfsrdetail a 
			LEFT JOIN tblservicingdetail b ON a.ServiceNo = b.ServiceNo
			LEFT JOIN tblirdetail c ON b.IRIDNo = c.IRIDNo
			LEFT JOIN tblparticular d ON a.MerchantID = d.ParticularID
			
			WHERE 1=1 			
			
			AND (
			    NULLIF(@FEID,0) IS NULL
			    OR a.FEID = @FEID
			)

			AND (
			    NULLIF(@DateFrom,'0000-00-00') IS NULL 
			    OR DATE(a.FSRDate) >= @DateFrom
			)

			AND (
			    NULLIF(@DateTo,'0000-00-00') IS NULL 
			    OR DATE(a.FSRDate) <= @DateTo
			)
			
			ORDER BY a.FSRNo DESC;
			
		ELSEIF (p_SearchBy = 'Zoning Alias List')
		THEN 
		   SET @Search = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
		   SELECT
			AliasID AS ID,
			JSON_OBJECT
			(
				'AliasID', a.AliasID,
				'AliasName', IFNULL_STRING_NORMAL(a.AliasName),
				'OfficialName', IFNULL_STRING_NORMAL(a.OfficialName),				
				'Priority', IFNULL_STRING_ONLY(a.Priority),
				'IsWholeWord', IFNULL_STRING_ONLY(a.IsWholeWord),
				'IsActive', IFNULL_STRING_ONLY(a.IsActive)
			) AS detail_info

			FROM tblzoningalias a
			WHERE
				(
				    IFNULL(@Search,'') = ''
				    OR IFNULL(@Search,'0') = '0'

				    OR UPPER(a.AliasName) LIKE CONCAT('%',UPPER(@Search),'%')
				    OR UPPER(a.OfficialName) LIKE CONCAT('%',UPPER(@Search),'%')
				    OR UPPER(a.Priority) LIKE CONCAT('%',UPPER(@Search),'%')
				    
				    -- First word of search 
				    OR (LENGTH(SUBSTRING_INDEX(@Search,' ',1)) >= 4 AND UPPER(a.AliasName) LIKE CONCAT('%', UPPER(SUBSTRING_INDEX(@Search,' ',1)), '%'))

				    -- Reverse matching 
				    OR UPPER(@Search) LIKE CONCAT('%', UPPER(SUBSTRING_INDEX(a.AliasName,'/',1)), '%')
				)
				
			ORDER BY
			
			a.AliasName;
		
		-- FOUND: RAIDEN sp still using old serviceno remove dependency
        ELSEIF (p_SearchBy = 'Expenses Service Detail')
		THEN
			SET @FEID   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @DateFrom   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SELECT 
			    m.ExpensesNo AS ID,

			    JSON_OBJECT(
                'expenses_master', JSON_OBJECT(
                    'ServiceDate', m.ServiceDate,
                    'ReferenceNo', m.ReferenceNo,
                    'FEID', m.FEID,
				    'FEName', funcGetDesc('Search', 'Particular', m.FEID),
				    'Location', m.Location,
				    'Remarks', m.Remarks,
				    'TotalAmount', m.TotalAmount,
				    'ServiceNoList', m.ServiceNoList,
                    'IRNoList', m.IRNoList,
                    'ReceiptList', m.ReceiptList,
                    'ExpensesStatus', m.ExpensesStatus,
                    'CreatedBy', m.CreatedBy
				),
				
				'services', IFNULL((
                SELECT JSON_ARRAYAGG(
                    JSON_OBJECT(
                        'ServiceNo', svc.ServiceNo,
                        'RequestID', fsr.IRNo,
                        'MerchantName', pt.Name,
                        'TID', fsr.TID,
                        'JobType', funcGetDesc('Search', 'JobType Description', svc.JobType),
                        'Region', funcGetDesc('Search', 'Region', pt.RegionType),
                        'Province', funcGetDesc('Search', 'Region Detail', pt.RegionID),
                        'geoLatitude', fsr.geoLatitude,
                        'geoLongitude', fsr.geoLongitude,
                        'geoCountry', fsr.geoCountry,
                        'geoLocality', fsr.geoLocality,
                        'geoAddress', fsr.geoAddress
                    )
                    )
                    FROM tblservicingdetail svc
                    LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo
                    LEFT JOIN tblparticular pt ON svc.MerchantID = pt.ParticularID
                    WHERE FIND_IN_SET(svc.ServiceNo, m.ServiceNoList) > 0
                ), JSON_ARRAY()),

				'expenses_detail', IFNULL((
				    SELECT JSON_ARRAYAGG(
					JSON_OBJECT(
					    'DetailID', d.DetailID,
					    'ExpensesID', d.ExpensesID,
					    'Description', e.Description,
					    'Amount', d.Amount,
					    'Remarks', d.Remarks,
					    'LocationFrom', d.LocationFrom,
					    'LocationTo', d.LocationTo,
					    'ExpensesDate', d.ExpensesDate
				    ))
				    FROM tblexpensestransdetail d
				    LEFT JOIN tblexpenses e 
					ON e.ExpensesID = d.ExpensesID
				    WHERE d.ExpensesNo = m.ExpensesNo
				), JSON_ARRAY())

			    ) AS detail_info

            FROM tblexpensestransmaster m
            WHERE 1=1
            AND (NULLIF(@FEID,0) IS NULL OR m.FEID = @FEID)
            AND (NULLIF(@DateFrom,'0000-00-00') IS NULL OR DATE(m.ServiceDate) >= @DateFrom)
            AND (NULLIF(@DateTo,'0000-00-00') IS NULL OR DATE(m.ServiceDate) <= @DateTo);
			
        ELSEIF (p_SearchBy = 'Expense List')
		THEN

		    SELECT
			ExpensesID AS ID,

			JSON_OBJECT(
			    'ExpensesID', a.ExpensesID,
			    'Description', a.Description,
			    'SequenceDisplay', COALESCE(a.SequenceDisplay, 0)
			) AS detail_info

		    FROM tblexpenses a
		    
		    WHERE a.isActive = 1

		    ORDER BY
			COALESCE(a.SequenceDisplay, 0),
			a.Description;		
		
        ELSEIF (p_SearchBy = 'Expenses Transaction Detail')
        THEN
            SET @ExpensesNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
            
            SELECT d.DetailID AS ID,
                JSON_OBJECT(
                    'DetailID', d.DetailID,
                    'ServiceNo', d.ServiceNo,
                    'TAIDNo', d.TAIDNo,
                    'IRIDNo', d.IRIDNo,
                    'ExpensesID', d.ExpensesID,
                    'ExpensesReferenceNo', d.ExpensesReferenceNo,
                    'ExpenseType', IFNULL_STRING_ONLY(e.Description),
                    'ExpensesAmount', d.Amount,
                    'ExpensesDescription', d.Remarks,
                    'ExpensesDate', DATE_FORMAT(d.ExpensesDate, '%Y-%m-%d'),
                    'LocationFrom', d.LocationFrom,
                    'LocationTo', d.LocationTo,
                    'MerchantName', d.MerchantName,
                    'ReceiptFileName', d.ReceiptFileName
                ) AS detail_info

                FROM tblexpensestransdetail d

                LEFT JOIN tblexpenses e ON e.ExpensesID = d.ExpensesID
                WHERE d.ExpensesNo = @ExpensesNo
                ORDER BY d.DetailID;
                
        ELSEIF (p_SearchBy = 'Merchant Service Summary')	
	THEN
		SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);
		
		SELECT
		    a.JobType AS ID, 
		    JSON_OBJECT(
			'JobType', a.JobType,
			'MerchantID', a.MerchantID,
			'Name', c.Name,
			'TID', b.TID,
			'MID', b.MID,
			'JobType', a.JobType,
			'JobTypeDescription', d.JobTypeDescription,
			'ServiceJobTypeDescription', d.ServiceJobTypeDescription,

			'JobTypeCount', COUNT(*),

			'CompletedCount',
			SUM(
			    CASE
				WHEN a.JobTypeStatusDescription = 'COMPLETED'
				THEN 1 ELSE 0
			    END
			),

			'ProcessingCount',
			SUM(
			    CASE
				WHEN a.JobTypeStatusDescription = 'PROCESSING'
				THEN 1 ELSE 0
			    END
			),

			'PendingCount',
			SUM(
			    CASE
				WHEN a.JobTypeStatusDescription = 'PENDING'
				THEN 1 ELSE 0
			    END
			),

			'SuccessCount',
			SUM(
			    CASE
				WHEN f.ActionMade = 'SUCCESS'
				THEN 1 ELSE 0
			    END
			),

			'NegativeCount',
			SUM(
			    CASE
				WHEN f.ActionMade = 'NEGATIVE'
				THEN 1 ELSE 0
			    END
			)
		    ) AS detail_info

		FROM tblservicingdetail a

		LEFT JOIN tblirdetail b
		    ON a.IRIDNo = b.IRIDNo

		LEFT JOIN tblparticular c
		    ON b.MerchantID = c.ParticularID

		LEFT JOIN tblservicetype d
		    ON a.JobType = d.JobType

		LEFT JOIN tblfsrdetail f
		    ON a.ServiceNo = f.ServiceNo

		WHERE
		    b.IRActive = 1
		    AND a.isActive = 1
		    AND b.IRIDNo = v_IRIDNo

		GROUP BY
		    a.MerchantID,
		    c.Name,
		    b.TID,
		    b.MID,
		    a.JobType,
		    d.JobTypeDescription,
		    d.ServiceJobTypeDescription

		ORDER BY
		    c.Name,
		    a.JobType;
	
	ELSEIF (p_SearchBy = 'Service Diagnostic Summary')
	THEN

	    SET @status = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
	    
	    SELECT
	        COUNT(*) AS ID,
		JSON_OBJECT(
		    'TotalJobs',
			COUNT(*),

		    'BeyondTAT',
			SUM(
			    CASE
				WHEN funcGetTATStatus(
				    'Search',
				    'TAT Status',
				    a.ServiceNo
				) = 'BEYOND TAT'
				THEN 1
				ELSE 0
			    END
			),

		    'WithinTAT',
			SUM(
			    CASE
				WHEN funcGetTATStatus(
				    'Search',
				    'TAT Status',
				    a.ServiceNo
				) = 'WITHIN TAT'
				THEN 1
				ELSE 0
			    END
			),

		    'Over5Days',
			SUM(
			    CASE
				WHEN DATEDIFF(
				    CURDATE(),
				    a.ServiceReqDate
				) > 5
				THEN 1
				ELSE 0
			    END
			),
			 	
		    'Over10Days',
			SUM(
			    CASE
				WHEN DATEDIFF(
				    CURDATE(),
				    a.ServiceReqDate
				) > 10
				THEN 1
				ELSE 0
			    END
			),
		     	 	
		    'Over30Days',
			SUM(
			    CASE
				WHEN DATEDIFF(
				    CURDATE(),
				    a.ServiceReqDate
				) > 30
				THEN 1
				ELSE 0
			    END
			),

		    'Over90Days',
			SUM(
			    CASE
				WHEN DATEDIFF(
				    CURDATE(),
				    a.ServiceReqDate
				) > 90
				THEN 1
				ELSE 0
			    END
			),

		    'Over180Days',
			SUM(
			    CASE
				WHEN DATEDIFF(
				    CURDATE(),
				    a.ServiceReqDate
				) > 180
				THEN 1
				ELSE 0
			    END
			)
		) AS detail_info

	    FROM tblservicingdetail a

	    LEFT JOIN tblirdetail b
		ON a.IRIDNo = b.IRIDNo

	    WHERE
		b.IRActive = 1
		AND a.isActive = 1

		AND (
		    (
			@status = '[NOT SPECIFIED]'
			AND a.JobTypeStatusDescription IN (
			    'PROCESSING',
			    'PENDING'
			)
		    )
		    OR
		    (
			@status <> '[NOT SPECIFIED]'
			AND a.JobTypeStatusDescription = @status
		    )
		);
        	    
	ELSEIF (p_SearchBy = 'Service Diagnostic Detail')	
	THEN
		SET @status = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
		
		SELECT
		    x.ServiceNo AS ID,
		    JSON_OBJECT(
			'JobType', x.JobType,
			'ServiceNo', x.ServiceNo,
			'MerchantID', x.MerchantID,
			'MerchantName', x.Name,
			'Region', x.Region,
			'Zone', x.Zone,
			'TID', x.TID,
			'MID', x.MID,
			'ServiceJobTypeDescription', x.ServiceJobTypeDescription,
			'ServiceStatusDescription', x.ServiceStatus,
			'DaysOverDue', x.DaysOverDue,
			'TATStatus', x.TATStatus,
			'TCount', x.TCount,
			'RequestDate', x.RequestDate,
			'ScheduleDate', x.ScheduleDate,
			'FEName', x.FEName,
			'Dispatcher', x.Dispatcher,
			'HelpDesk', x.HelpDesk
		    ) AS detail_info

		FROM
		(
		    SELECT
		        a.JobType,
		        a.ServiceNo,
			a.MerchantID,
			c.Name,
			
			funcGetDesc('Search', 'Region', c.RegionType) AS Region,
			
			funcGetDesc('Search', 'ZoneName', c.ZoneID) AS Zone,
			
			b.TID,
			b.MID,
			
			funcGetDesc('Search', 'Service JobType Description', a.JobType) as ServiceJobTypeDescription,
			
			funcGetDesc('Search', 'Service Status', a.ServiceStatus) AS ServiceStatus,

			funcGetDaysOverDue('Search', 'Days OverDue', a.ServiceNo) AS DaysOverDue,

			funcGetTATStatus('Search', 'TAT Status', a.ServiceNo) AS TATStatus,

			COUNT(*) AS TCount,
						
			IFNULL_FORMAT_DATE(a.ServiceDate) as RequestDate,
			
			IFNULL_FORMAT_DATE(a.ServiceReqDate) AS ScheduleDate,
			
			funcGetDesc('Search', 'Service Owner', CONCAT('Field Engineer', '|', a.ServiceNo, '|', a.FEID)) AS FEName,
			
			funcGetDesc('Search', 'Service Owner', CONCAT('Dispatcher', '|', a.ServiceNo, '|', a.DispatchID)) AS Dispatcher,
			
			funcGetDesc('Search', 'Service Owner', CONCAT('Job Orders', '|', a.ServiceNo, '|', 0)) AS HelpDesk

		    FROM tblservicingdetail a

		    LEFT JOIN tblirdetail b
			ON a.IRIDNo = b.IRIDNo

		    LEFT JOIN tblparticular c
			ON b.MerchantID = c.ParticularID

		    WHERE
			b.IRActive = 1
			AND a.isActive = 1
			AND (
			    (
				@status = '[NOT SPECIFIED]'
				AND a.JobTypeStatusDescription IN (
				    'PROCESSING',
				    'PENDING'
				)
			    )
			    OR
			    (
				@status <> '[NOT SPECIFIED]'
				AND a.JobTypeStatusDescription = @status
			    )
			)

		    GROUP BY
			a.MerchantID,
			c.Name,
			b.TID,
			b.MID
		) x

		ORDER BY
		    CASE
			WHEN x.TATStatus = 'BEYOND TAT' THEN 0
			ELSE 1
		    END,
		    x.DaysOverDue DESC,
		    x.Name;
	
	ELSEIF (p_SearchBy = 'Terminal Inventory Diagnostic Summary')
	THEN

	    SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);	
	    	
	    SET @RepairRoomLocationID = (
		SELECT LocationID
		FROM tbllocation
		WHERE Description = 'REPAIR ROOM'
		LIMIT 1
	    );

	   	
	    SELECT 
		"1" AS ID,
		JSON_OBJECT(

		'TotalInventory',
		(
		    SELECT COUNT(*)
		    FROM tblterminaldetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		),

		'StatusMismatch',
		(
		    SELECT COUNT(*)
		    FROM tblterminaldetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		      AND
		      (
			    (a.TerminalStatus = 1
			     AND a.LocationID NOT IN (1, 2))

			    OR

			    (a.TerminalStatus = 7
			     AND a.LocationID <> 18)
		      )
		),

		'LocationMismatch',
		(
		    SELECT COUNT(*)
		    FROM tblterminaldetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		      AND
		      (
			    (a.TerminalStatus = 3
			     AND (
				 a.LocationID IS NULL
				 OR a.LocationID <> @RepairRoomLocationID
			     ))

			    OR

			    (a.TerminalStatus = 4
			     AND (
				 a.LocationID IS NULL
				 OR a.LocationID <> @RepairRoomLocationID
			     ))
		      )
		),

		'StatusLocationMismatch',
		(
		    SELECT COUNT(*)
		    FROM tblterminaldetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		      AND
		      (
			    (a.TerminalStatus = 1
			     AND a.LocationID NOT IN (1, 2))

			    OR

			    (a.TerminalStatus = 7
			     AND a.LocationID <> 18)

			    OR

			    (a.TerminalStatus = 3
			     AND (
				 a.LocationID IS NULL
				 OR a.LocationID <> @RepairRoomLocationID
			     ))

			    OR

			    (a.TerminalStatus = 4
			     AND (
				 a.LocationID IS NULL
				 OR a.LocationID <> @RepairRoomLocationID
			     ))
		      )
		)

	    ) AS detail_info;
    	    
	ELSEIF (p_SearchBy = 'Terminal Inventory Diagnostic Detail')
	THEN

	    SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);	
	    SET @IssueCategory = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));

	    /*
		==========================================================
		TERMINAL INVENTORY DIAGNOSTIC RULES
		==========================================================

		STATUS MISMATCH
		----------------
		AVAILABLE
		    Valid Location:
			1 = STOCK ROOM
			2 = CITAS F.E.

		INSTALLED
		    Valid Location:
			18 = PRODUCTION


		LOCATION MISMATCH
		------------------
		FOR REPAIR
		    Valid Location:
			REPAIR ROOM

		DEFECTIVE
		    Valid Location:
			REPAIR ROOM


		STATUS AND LOCATION MISMATCH
		----------------------------
		Combined result of all STATUS MISMATCH
		and LOCATION MISMATCH records.
	    */


	    SET @RepairRoomLocationID = (
		SELECT LocationID
		FROM tbllocation
		WHERE Description = 'REPAIR ROOM'
		LIMIT 1
	    );
	    
	    IF (@IssueCategory = '[NOT SPECIFIED]') THEN
		SET @IssueCategory = 'ALL';
	    END IF;


	    SELECT 
	            a.TerminalID AS ID,
		    JSON_OBJECT(
		    'TerminalID', a.TerminalID,		    
		    'TerminalSN', a.TerminalSN,
		    'SerialNo', a.SerialNo,

		    'TerminalTypeID', a.TerminalTypeID,
		    'TerminalType', funcGetDesc("Search", "Terminal Type", a.TerminalTypeID),
		    'TerminalModelID', a.TerminalModelID,
		    'TerminalModel', funcGetDesc("Search", "Terminal Type", a.TerminalTypeID),
		    'TerminalBrandID', a.TerminalBrandID,
		    'TerminalBrand', funcGetDesc("Search", "Terminal Brand", a.TerminalTypeID),

		    'TerminalStatus', a.TerminalStatus,		    
		    'TerminalStatus', funcGetDesc("Search", "Terminal Status", a.TerminalStatus),

		    'LocationID', a.LocationID,
		    'Location', funcGetDesc("Search", "Location", a.LocationID),

		    'ClientID', a.ClientID,
		    'ClientName', funcGetDesc("Search", "Particular", a.ClientID),

		    'DeliveryDate', IFNULL_FORMAT_DATE2(a.DeliveryDate),
		    'ReceiveDate', IFNULL_FORMAT_DATE2(a.ReceiveDate),
		    'ReleaseDate', IFNULL_FORMAT_DATE2(a.ReleaseDate),

		    'IssueCategory',
			CASE
			    WHEN a.TerminalStatus = 1
				 AND a.LocationID NOT IN (1, 2)
			    THEN 'STATUS MISMATCH'

			    WHEN a.TerminalStatus = 7
				 AND a.LocationID <> 18
			    THEN 'STATUS MISMATCH'

			    WHEN a.TerminalStatus = 3
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'LOCATION MISMATCH'

			    WHEN a.TerminalStatus = 4
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'LOCATION MISMATCH'

			    ELSE NULL
			END,

		    'IssueDescription',
			CASE
			    WHEN a.TerminalStatus = 1
				 AND a.LocationID NOT IN (1, 2)
			    THEN 'AVAILABLE terminal is not located in STOCK ROOM or CITAS F.E.'

			    WHEN a.TerminalStatus = 7
				 AND a.LocationID <> 18
			    THEN 'INSTALLED terminal is not located in PRODUCTION.'

			    WHEN a.TerminalStatus = 3
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'FOR REPAIR terminal is not located in REPAIR ROOM.'

			    WHEN a.TerminalStatus = 4
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'DEFECTIVE terminal is not located in REPAIR ROOM.'

			    ELSE NULL
			END,

		    'RecommendedAction',
			CASE
			    WHEN a.TerminalStatus = 1
				 AND a.LocationID NOT IN (1, 2)
			    THEN 'Review terminal status. If already deployed, update status to INSTALLED.'

			    WHEN a.TerminalStatus = 7
				 AND a.LocationID <> 18
			    THEN 'Review terminal status and location. INSTALLED terminal should be in PRODUCTION.'

			    WHEN a.TerminalStatus = 3
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'Move terminal to REPAIR ROOM.'

			    WHEN a.TerminalStatus = 4
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'Move terminal to REPAIR ROOM.'

			    ELSE NULL
			END

		) AS detail_info


	    FROM tblterminaldetail a

	    LEFT JOIN tbllocation r
		ON r.LocationID = @RepairRoomLocationID


	    WHERE a.isActive = 1
	      AND a.ClientID = v_ClientID


	      /*
		  ========================================================
		  ONLY DIAGNOSTIC RECORDS
		  ========================================================
	      */

	      AND
	      (
		    /*
			STATUS MISMATCH
			AVAILABLE
		    */
		    (
			a.TerminalStatus = 1
			AND a.LocationID NOT IN (1, 2)
		    )

		    OR

		    /*
			STATUS MISMATCH
			INSTALLED
		    */
		    (
			a.TerminalStatus = 7
			AND a.LocationID <> 18
		    )

		    OR

		    /*
			LOCATION MISMATCH
			FOR REPAIR
		    */
		    (
			a.TerminalStatus = 3
			AND (
			    a.LocationID IS NULL
			    OR a.LocationID <> @RepairRoomLocationID
			)
		    )

		    OR

		    /*
			LOCATION MISMATCH
			DEFECTIVE
		    */
		    (
			a.TerminalStatus = 4
			AND (
			    a.LocationID IS NULL
			    OR a.LocationID <> @RepairRoomLocationID
			)
		    )
	      )


	      /*
		  ========================================================
		  ISSUE CATEGORY FILTER
		  ========================================================
	      */

	      AND
	      (
		    @IssueCategory IS NULL
		    OR @IssueCategory = ''
		    OR @IssueCategory = 'ALL'


		    /*
			STATUS MISMATCH
		    */
		    OR
		    (
			@IssueCategory = 'STATUS MISMATCH'
			AND
			(
			    (
				a.TerminalStatus = 1
				AND a.LocationID NOT IN (1, 2)
			    )

			    OR

			    (
				a.TerminalStatus = 7
				AND a.LocationID <> 18
			    )
			)
		    )


		    /*
			LOCATION MISMATCH
		    */
		    OR
		    (
			@IssueCategory = 'LOCATION MISMATCH'
			AND
			(
			    (
				a.TerminalStatus = 3
				AND (
				    a.LocationID IS NULL
				    OR a.LocationID <> @RepairRoomLocationID
				)
			    )

			    OR

			    (
				a.TerminalStatus = 4
				AND (
				    a.LocationID IS NULL
				    OR a.LocationID <> @RepairRoomLocationID
				)
			    )
			)
		    )


		    /*
			STATUS AND LOCATION MISMATCH
			= COMBINED RESULT
		    */
		    OR
		    (
			@IssueCategory = 'STATUS AND LOCATION MISMATCH'
			AND
			(
			    (
				a.TerminalStatus = 1
				AND a.LocationID NOT IN (1, 2)
			    )

			    OR

			    (
				a.TerminalStatus = 7
				AND a.LocationID <> 18
			    )

			    OR

			    (
				a.TerminalStatus = 3
				AND (
				    a.LocationID IS NULL
				    OR a.LocationID <> @RepairRoomLocationID
				)
			    )

			    OR

			    (
				a.TerminalStatus = 4
				AND (
				    a.LocationID IS NULL
				    OR a.LocationID <> @RepairRoomLocationID
				)
			    )
			)
		    )
	      )


	    ORDER BY
		a.TerminalStatus,
		a.Location;

	ELSEIF (p_SearchBy = 'SIM Inventory Diagnostic Summary')
	THEN

	    SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED);	

	    SET @RepairRoomLocationID = (
