		    FROM tblsimdetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		),

		'StatusMismatch',
		(
		    SELECT COUNT(*)
		    FROM tblsimdetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		      AND
		      (
			    (a.SIMStatus = 1
			     AND a.LocationID NOT IN (1, 2))

			    OR

			    (a.SIMStatus = 7
			     AND a.LocationID <> 18)
		      )
		),

		'LocationMismatch',
		(
		    SELECT COUNT(*)
		    FROM tblsimdetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		      AND
		      (
			    (a.SIMStatus = 3
			     AND (
				 a.LocationID IS NULL
				 OR a.LocationID <> @RepairRoomLocationID
			     ))

			    OR

			    (a.SIMStatus = 4
			     AND (
				 a.LocationID IS NULL
				 OR a.LocationID <> @RepairRoomLocationID
			     ))
		      )
		),

		'StatusLocationMismatch',
		(
		    SELECT COUNT(*)
		    FROM tblsimdetail a
		    WHERE a.isActive = 1
		      AND a.ClientID = v_ClientID
		      AND
		      (
			    (a.SIMStatus = 1
			     AND a.LocationID NOT IN (1, 2))

			    OR

			    (a.SIMStatus = 7
			     AND a.LocationID <> 18)

			    OR

			    (a.SIMStatus = 3
			     AND (
				 a.LocationID IS NULL
				 OR a.LocationID <> @RepairRoomLocationID
			     ))

			    OR

			    (a.SIMStatus = 4
			     AND (
