		FROM tbllocation
		WHERE DESCRIPTION = 'REPAIR ROOM'
		LIMIT 1
	    );

	    IF (@IssueCategory = '[NOT SPECIFIED]') THEN
		SET @IssueCategory = 'ALL';
	    END IF;


	    SELECT 
		    a.SIMID AS ID,
		    JSON_OBJECT(
		    'SIMID', a.SIMID,		    
		    'SIMSN', a.SIMSN,
		    'SerialNo', a.SerialNo,

		    'CarrierID', a.CarrierID,
		    'SIMCarrier', funcGetDesc("Search", "SIM Carrier", a.CarrierID),
		    
		    'SIMStatus', a.SIMStatus,		    
		    'SIMStatus', funcGetDesc("Search", "SIM Status", a.SIMStatus),

		    'LocationID', a.LocationID,
