		    'ClientID', a.ClientID,
		    'ClientName', funcGetDesc("Search", "Particular", a.ClientID),

		    'DeliveryDate', IFNULL_FORMAT_DATE2(a.DeliveryDate),
		    'ReceiveDate', IFNULL_FORMAT_DATE2(a.ReceiveDate),
		    'ReleaseDate', IFNULL_FORMAT_DATE2(a.ReleaseDate),

