			    THEN 'LOCATION MISMATCH'

			    WHEN a.SIMStatus = 4
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'LOCATION MISMATCH'

			    ELSE NULL
			END,

		    'IssueDescription',
			CASE
			    WHEN a.SIMStatus = 1
				 AND a.LocationID NOT IN (1, 2)
			    THEN 'AVAILABLE SIM is not located in STOCK ROOM or CITAS F.E.'

			    WHEN a.SIMStatus = 7
				 AND a.LocationID <> 18
			    THEN 'INSTALLED SIM is not located in PRODUCTION.'

			    WHEN a.SIMStatus = 3
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'FOR REPAIR SIM is not located in REPAIR ROOM.'

			    WHEN a.SIMStatus = 4
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'DEFECTIVE SIM is not located in REPAIR ROOM.'

			    ELSE NULL
			END,

		    'RecommendedAction',
			CASE
			    WHEN a.SIMStatus = 1
				 AND a.LocationID NOT IN (1, 2)
			    THEN 'Review SIM status. If already deployed, update status to INSTALLED.'

			    WHEN a.SIMStatus = 7
				 AND a.LocationID <> 18
			    THEN 'Review SIM status and location. INSTALLED SIM should be in PRODUCTION.'

			    WHEN a.SIMStatus = 3
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'Move SIM to REPAIR ROOM.'

			    WHEN a.SIMStatus = 4
				 AND (
				     a.LocationID IS NULL
				     OR a.LocationID <> @RepairRoomLocationID
				 )
			    THEN 'Move SIM to REPAIR ROOM.'

			    ELSE NULL
			END

		) AS detail_info


	    FROM tblsimdetail a

	    LEFT JOIN tbllocation r
		ON r.LocationID = @RepairRoomLocationID


	    WHERE a.isActive = 1
	      AND a.ClientID = v_ClientID


	      /*
		  ========================================================
		  ONLY DIAGNOSTIC RECORDS
		  ========================================================
	      */

	      AND
	      (
		    /*
			STATUS MISMATCH
			AVAILABLE
		    */
		    (
