				AND a.LocationID NOT IN (1, 2)
			    )

			    OR

			    (
				a.SIMStatus = 7
				AND a.LocationID <> 18
			    )
			)
		    )


		    /*
			LOCATION MISMATCH
		    */
		    OR
		    (
			@IssueCategory = 'LOCATION MISMATCH'
			AND
			(
			    (
				a.SIMStatus = 3
				AND (
				    a.LocationID IS NULL
				    OR a.LocationID <> @RepairRoomLocationID
				)
			    )

			    OR

			    (
				a.SIMStatus = 4
				AND (
