					'ExpensesAmount', IFNULL(d.Amount, 0),
					'ExpensesDescription', IFNULL_STRING_NORMAL(d.Remarks),
					'ExpensesDate', IFNULL_FORMAT_DATE2(d.ExpensesDate)
				) AS detail_info

			FROM tblexpensestransdetail d

			LEFT JOIN tblservicingdetail svc
				ON svc.ServiceNo = d.ServiceNo

			LEFT JOIN tblfsrdetail f
				ON f.ServiceNo = d.ServiceNo

			LEFT JOIN tblirdetail ir
				ON ir.IRIDNo = svc.IRIDNo

			LEFT JOIN tblparticular pt
				ON pt.ParticularID = ir.MerchantID

			LEFT JOIN tblexpenses e
				ON e.ExpensesID = d.ExpensesID

			WHERE
				(
					IFNULL(@Search, '') = ''
					OR IFNULL(@Search, '0') = '0'

					OR UPPER(d.ExpensesReferenceNo) LIKE CONCAT('%', UPPER(@Search), '%')
					OR CAST(d.ServiceNo AS CHAR) LIKE CONCAT('%', @Search, '%')
					OR UPPER(pt.Name) LIKE CONCAT('%', UPPER(@Search), '%')
					OR UPPER(ir.TID) LIKE CONCAT('%', UPPER(@Search), '%')
					OR UPPER(ir.MID) LIKE CONCAT('%', UPPER(@Search), '%')
				)

			ORDER BY
				d.ExpensesDate DESC,
				d.DetailID DESC;
				
      #Nikko QR DELIVERY HISTORY
      ELSEIF (p_SearchBy = 'QR Delivery History')
       THEN

         SELECT
          q.QRID AS ID,

            JSON_OBJECT(
              'QRID', q.QRID,
              'ServiceNo', q.ServiceNo,
              'IRIDNo', q.IRIDNo,
              'MerchantID', q.MerchantID,
              'MerchantName', IFNULL_STRING_NORMAL(mer.Name),
              'MerchantAddress', IFNULL_STRING_NORMAL(mer.Address),
              'TID', IFNULL_STRING_NORMAL(ir.TID),
              'MID', IFNULL_STRING_NORMAL(ir.MID),

              'TerminalSN', IFNULL_STRING_NORMAL(
                  CASE
                      WHEN svc.JobType = 7
                         THEN svc.ReplaceTerminalSN
                      ELSE svc.TerminalSN
                  END
              ),

              'SIMSN', IFNULL_STRING_NORMAL(
                  CASE
                      WHEN svc.JobType = 7
                         THEN svc.ReplaceSIMSN
                      ELSE svc.SIMSerialNo
                  END
              ),

              'QRContent', IFNULL_STRING_NORMAL(q.QRContent),
              'InventoryStatus', IFNULL_STRING_NORMAL(q.InventoryStatus),
              'TerminalPrepStatus', IFNULL_STRING_NORMAL(q.TerminalPrepStatus),
              'DispatcherStatus', IFNULL_STRING_NORMAL(q.DispatcherStatus),
              'QRResult', IFNULL_STRING_NORMAL(q.QRResult),
              'QRDate', IFNULL_FORMAT_DATE(q.QRDate),
              'ProcessedBy', IFNULL_STRING_NORMAL(q.ProcessedBy),
              'DateTimeStamp', q.DateTimeStamp
           ) AS detail_info

     FROM tblservicingqrdetail q
     LEFT JOIN tblirdetail ir
         ON q.IRIDNo = ir.IRIDNo
     LEFT JOIN tblparticular mer
         ON q.MerchantID = mer.ParticularID
     LEFT JOIN tblservicingdetail svc
         ON q.ServiceNo = svc.ServiceNo

     WHERE CAST(p_SearchValue AS UNSIGNED) = 0
         OR q.ServiceNo = CAST(p_SearchValue AS UNSIGNED)
 
     ORDER BY q.DateTimeStamp DESC, q.QRID DESC
     LIMIT 50;

       ELSEIF (p_SearchBy = 'QR Delivery By ID')
       
       THEN
       
	      SELECT
	      
		       QRID,

		       ServiceNo,

		       IRIDNo,

		       MerchantID,

		       QRDate,

		       QRContent,

		       ProcessedBy,

		       InventoryStatus,
		  
		       TerminalPrepStatus,
		  
		       DispatcherStatus,

		       DateTimeStamp

	      FROM 

	      tblservicingqrdetail
	      
	      WHERE QRID = CAST(p_SearchValue AS UNSIGNED)
	      
	      LIMIT 1;
	      
	      
	ELSEIF (p_SearchBy = 'QR Delivery Dashboard')

	THEN

	SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
	SET v_DateTo   = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

	SELECT

		qs.QRID AS ID,

		JSON_OBJECT(
			'QRCodeID', qs.QRID,
			'ServiceNo', qs.ServiceNo,
			'RequestDate', IFNULL_FORMAT_DATE2(b.ServiceDate),
			'ProcessedDate', IFNULL_FORMAT_DATETIME_AMPM(qs.DateTimeStamp),
			'ProcessedBy', IFNULL_STRING_NORMAL(qs.ProcessedBy),
			'Name', IFNULL_STRING_NORMAL(ir.MerchantName),
			'TID', IFNULL_STRING_NORMAL(ir.TID),
			'MID', IFNULL_STRING_NORMAL(ir.MID),
			'Address', IFNULL_STRING_NORMAL(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, '$.Values.Address'))),
			'POSConnectionType', IFNULL_STRING_NORMAL(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, '$.Values."POS Connection Type"'))),
			'TerminalSN', IFNULL_STRING_NORMAL(funcGetDesc("Search", "Terminal Detail", b.TerminalID)),
			'TerminalType', IFNULL_STRING_NORMAL(funcGetDesc("Search", "TerminalID Type", b.TerminalID)),
			'TerminalModel', IFNULL_STRING_NORMAL(funcGetDesc("Search", "TerminalID Model", b.TerminalID)),
			'SIMSN', IFNULL_STRING_NORMAL(funcGetDesc("Search", "SIM Detail", b.SIMID)),
			'SIMCarrier', IFNULL_STRING_NORMAL(funcGetDesc("Search", "SIMID Carrier", b.SIMID)),
			'InventoryStatus', IFNULL_STRING_NORMAL(qs.InventoryStatus),
			'TermPrepStatus', IFNULL_STRING_NORMAL(qs.TerminalPrepStatus),
			'QRResult', IFNULL_STRING_NORMAL(qs.QRResult),
			'DispatcherStatus', IFNULL_STRING_NORMAL(qs.DispatcherStatus)
			
		) AS detail_info

	FROM (
		SELECT
			t.*,
			ROW_NUMBER() OVER (PARTITION BY t.ServiceNo ORDER BY t.DateTimeStamp DESC) AS rn
		FROM tblservicingqrdetail t
		WHERE t.QRDate BETWEEN v_DateFrom AND v_DateTo
	) qs
	LEFT JOIN tblirdetail ir ON qs.IRIDNo = ir.IRIDNo
	LEFT JOIN tblservicingdetail b ON qs.ServiceNo = b.ServiceNo
	WHERE qs.rn = 1
	AND ir.TID IS NOT NULL AND ir.TID <> ''
	ORDER BY qs.DateTimeStamp DESC;
		
	ELSEIF (p_SearchBy = 'QR Delivery Received')
	THEN
	 
	SELECT
	 
		qs.QRID AS ID,
	 
		JSON_OBJECT(
			'QRCodeID', qs.ServiceNo,
			'ServiceNo', qs.ServiceNo,
			'RequestDate', IFNULL_FORMAT_DATE2(b.ServiceDate),
			'ProcessedDate', IFNULL_FORMAT_DATETIME_AMPM(qs.DateTimeStamp),
			'ProcessedBy', IFNULL_STRING_NORMAL(COALESCE(pu.FullName, qs.ProcessedBy)),
			'Name', IFNULL_STRING_NORMAL(ir.MerchantName),
			'TID', IFNULL_STRING_NORMAL(ir.TID),
			'MID', IFNULL_STRING_NORMAL(ir.MID),
			'Address', IFNULL_STRING_NORMAL(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, '$.Values.Address'))),
			'POSConnectionType', IFNULL_STRING_NORMAL(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info, '$.Values."POS Connection Type"'))),
			'TerminalSN', IFNULL_STRING_NORMAL(funcGetDesc("Search", "Terminal Detail", b.TerminalID)),
			'TerminalType', IFNULL_STRING_NORMAL(funcGetDesc("Search", "TerminalID Type", b.TerminalID)),
			'TerminalModel', IFNULL_STRING_NORMAL(funcGetDesc("Search", "TerminalID Model", b.TerminalID)),
			'SIMSN', IFNULL_STRING_NORMAL(funcGetDesc("Search", "SIM Detail", b.SIMID)),
			'SIMCarrier', IFNULL_STRING_NORMAL(funcGetDesc("Search", "SIMID Carrier", b.SIMID)),
			'InventoryStatus', IFNULL_STRING_NORMAL(qs.InventoryStatus),
			'TermPrepStatus', IFNULL_STRING_NORMAL(qs.TerminalPrepStatus),
			'QRResult', IFNULL_STRING_NORMAL(qs.QRResult),
			'DispatcherStatus', IFNULL_STRING_NORMAL(qs.DispatcherStatus),
			'Remarks', IFNULL_STRING_NORMAL(qs.Remarks),
			'ReceivedStatus', CASE WHEN qs.isReceived = 1 THEN 'RECEIVED' ELSE 'NOT RECEIVED' END,
			'ReceivedDate', IFNULL_FORMAT_DATETIME_AMPM(qs.ReceivedDate)
		) AS detail_info
	 
	FROM (
		SELECT
			t.*,
			ROW_NUMBER() OVER (PARTITION BY t.ServiceNo ORDER BY t.DateTimeStamp DESC) AS rn
		FROM tblservicingqrdetail t
		WHERE t.QRResult = 'READY TO DISPATCH'
		  AND t.isReceived = 1
	) qs
	LEFT JOIN tblirdetail ir ON qs.IRIDNo = ir.IRIDNo
	LEFT JOIN tblservicingdetail b ON qs.ServiceNo = b.ServiceNo
	LEFT JOIN tbluser pu ON UPPER(pu.UserName) = UPPER(qs.ProcessedBy)
	WHERE qs.rn = 1
	ORDER BY qs.DateTimeStamp DESC;
	
	-- RAIDEN WAYBILL INFO      
	ELSEIF (p_SearchBy = 'Waybill Information')
		THEN
		   SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
		   
		   SET @url = "https://sit-uat.citas.com.ph/miscastlestech/waybill/index.html";

              SELECT
                 pt.Name AS MerchantName,
                 td.SerialNo AS POSSN,
                 sd.SerialNo AS SIMSN,
                 pt.Address AS MerchantAddress,
                 qr.QRID AS QRID,
                 qr.ServiceNo AS ServiceNo,
                 qr.IRIDNo AS IRIDNo,
                 qr.MerchantID AS MerchantID,
                 qr.QRDate AS QRDate,
                   JSON_SET(
                   IFNULL(NULLIF(qr.InternalQRContent, ''), '{}'),
                  '$.QRID',
                  CAST(qr.QRID AS CHAR)
                  ) AS InternalQRContent,
                  
                  # QRUrl
                    CONCAT(
			@url,
			'?QRID=',
			qr.ServiceNo,
			'&bank=MCC',
			'&InternalQRContent=',
			TO_BASE64(
			    JSON_OBJECT(
				'TerminalSN', td.SerialNo,
				'SIMSN', sd.SerialNo,
				'MerchantName', pt.Name,
				'MerchantAddress', pt.Address
			    )
			)
		    ) AS QRUrl
		    
             FROM tblservicingdetail svc

             LEFT JOIN tblparticular pt
              ON pt.ParticularID = svc.MerchantID

             LEFT JOIN tblterminaldetail td
              ON td.TerminalID = svc.TerminalID

             LEFT JOIN tblsimdetail sd
              ON sd.SIMID = svc.SIMID

             LEFT JOIN tblservicingqrdetail qr
              ON qr.QRID = (
                 SELECT latestQR.QRID
                 FROM tblservicingqrdetail latestQR
                 WHERE latestQR.ServiceNo = svc.ServiceNo
                 ORDER BY latestQR.DateTimeStamp DESC, latestQR.QRID DESC
                 LIMIT 1
        )

    WHERE svc.ServiceNo = v_ServiceNo

    LIMIT 1;
		    
	ELSEIF (p_SearchBy = 'Expenses Transaction Master')
        THEN
		SET @Search = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		
		SELECT 
		     a.ExpensesNo AS ID,
		    JSON_OBJECT(
		    'ExpensesNo', a.ExpensesNo,
		    'ExpensesDate', IFNULL_FORMAT_DATE(a.ExpensesDate),
		    'ServiceDate', IFNULL_FORMAT_DATE(a.ServiceDate),
		    'FEID', a.FEID,
		    'FEName', funcGetDesc("Search", "Particular", a.FEID),
		    'IRIDNo', a.IRIDNo,
		    'MerchantID', a.MerchantID,
		    'ReferenceNo', a.ReferenceNo,
		    'Remarks', a.Remarks,
		    'TotalAmount', a.TotalAmount,
		    'ServiceNoList', a.ServiceNoList,
		    'IRIDNoList', a.IRIDNoList,
		    'IRNoList', a.IRNoList,
		    'ReceiptList', a.ReceiptList,
		    'ReceiptDateList', a.ReceiptDateList,
		    'ReceiptAmountList', a.ReceiptAmountList,
		    'CreatedBy', a.CreatedBy,
		    'CreatedDate', a.CreatedDate,
		    'UpdatedBy', a.UpdatedBy,
		    'UpdatedDate', a.UpdatedDate,
		    'DateTimeStamp', a.DateTimeStamp
		) AS detail_info
		FROM 
		tblexpensestransmaster a
		WHERE 
			@Search = ''
			OR a.ExpensesNo = @Search
			OR a.ReferenceNo = @Search
		ORDER BY 
		a.ExpensesNo DESC;

	END IF;
END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewAdvanceFSR` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewAdvanceFSR` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewAdvanceFSR`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

    p_SearchBy VARCHAR(30) /* = NULL */ ,

    p_SearchValue VARCHAR(255) /* = NULL */    

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_ServiceTypeID INT;

	DECLARE v_ParticularID INT;

	DECLARE v_TerminalTypeID INT;

	DECLARE v_TerminalModelID INT;

	DECLARE v_TerminalBrandID INT;

	DECLARE v_TerminalSerialNo VARCHAR(45);

	DECLARE v_IRNo VARCHAR(45);

	DECLARE v_TID VARCHAR(45);

	DECLARE v_MID VARCHAR(45);

	DECLARE v_InvoiceNo VARCHAR(45);

	DECLARE v_BatchNo VARCHAR(45);

	DECLARE v_ClientID INT;

	DECLARE v_SPID INT;

	DECLARE v_FEID INT;

	DECLARE v_TerminalStatus INT;

	DECLARE v_FSRStatus INT;

	DECLARE v_ServiceStatus INT;

	DECLARE v_isClose INT;

	DECLARE v_FSRDateFrom VARCHAR(45);

	DECLARE v_FSRDateTo VARCHAR(45);

	DECLARE v_ActionMade VARCHAR(45);

	DECLARE v_JobType INT;	

	DECLARE v_JobTypeDescription VARCHAR(45);	

	DECLARE v_OffSetFrom INTEGER;

	DECLARE v_OffSetTo INTEGER;

	DECLARE v_OffSet INTEGER;

	

	DECLARE v_DummyID INT;

	DECLARE v_RegionType INT;

	DECLARE v_RegionID INT;

	DECLARE v_LocationID INT;	

	DECLARE v_MerchantID INT;

	DECLARE v_IRIDNo INT;

	DECLARE v_DateFrom VARCHAR(45);

	DECLARE v_DateTo VARCHAR(45);

	DECLARE v_isCancelled INT;

	DECLARE v_isActive INT;

	DECLARE v_isPullOut INT;

	DECLARE v_IncludeBillable VARCHAR(45);

	DECLARE v_isBillable INT;

	

	DECLARE v_Status INT;

	DECLARE v_StatusDescription VARCHAR(45);

	DECLARE v_TerminalID INT;

	DECLARE v_TerminalSN VARCHAR(45);

	DECLARE v_SIMID INT;

	DECLARE v_SIMSN VARCHAR(45);

	

	DECLARE v_isMobile INT;

	DECLARE v_MobileID INT;

	DECLARE v_MobileTerminalID VARCHAR(45);

	

	DECLARE v_JobTypeStatusDescription VARCHAR(100); # eg. PENDING/PROCESSING/COMPLETED

	DECLARE v_ServiceJobTypeDescription VARCHAR(100); # eg. INSTALLATION/SERVICING.... 

	DECLARE v_ServiceResultDescription VARCHAR(100); # eg. SUCCESS/NEGATIVE 

	DECLARE v_Temp VARCHAR(100);

	DECLARE v_DateFilter VARCHAR(100);

	

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

	

	DECLARE p_SQL_Select LONGTEXT;

	DECLARE p_SQL_Insert LONGTEXT;	

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Advance FSR')

		THEN

			# Split SearchValue

			#SELECT (CONCAT('p_SearchValue=', p_SearchValue));            

			SET v_ServiceTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);

			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

			SET v_TerminalBrandID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);

			SET v_TerminalSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));

			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));

			SET v_ClientID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));

			SET v_SPID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));

			SET v_FEID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,10));

			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11));

			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));

			SET v_InvoiceNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13));

			SET v_BatchNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));

			SET v_TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)) AS UNSIGNED INTEGER);

			SET v_FSRStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,16)) AS UNSIGNED INTEGER);

			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER);

			SET v_isClose = 0;

			SET v_FSRDateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18));

			SET v_FSRDateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19));

			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20));

			SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,21));

			

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,22)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,23)) AS UNSIGNED INTEGER);

			

			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,24)) AS UNSIGNED INTEGER);

			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,25)) AS UNSIGNED INTEGER);

			

			#SELECT (CONCAT('v_ServiceTypeID=', v_ServiceTypeID));

			#SELECT (CONCAT('v_ParticularID=', v_ParticularID));

			#SELECT (CONCAT('v_TerminalTypeID=', v_TerminalTypeID));

			#SELECT (CONCAT('v_TerminalModelID=', v_TerminalModelID));

			#SELECT (CONCAT('v_TerminalBrandID=', v_TerminalBrandID));

			#SELECT (CONCAT('v_TerminalSerialNo=', v_TerminalSerialNo));

			#SELECT (CONCAT('v_IRNo=', v_IRNo));

			#SELECT (CONCAT('v_ClientID=', v_ClientID));

			#SELECT (CONCAT('v_SPID=', v_SPID));

			#SELECT (CONCAT('v_FEID=', v_FEID));

			#SELECT (CONCAT('v_TID=', v_TID));

			#SELECT (CONCAT('v_MID=', v_MID));

			#SELECT (CONCAT('v_InvoiceNo=', v_InvoiceNo));

			#SELECT (CONCAT('v_BatchNo=', v_BatchNo));

			#SELECT (CONCAT('v_TerminalStatus=', v_TerminalStatus));

			#SELECT (CONCAT('v_FSRStatus=', v_FSRStatus));

			#SELECT (CONCAT('v_OffSetFrom=', v_OffSetFrom));

			#SELECT (CONCAT('v_OffSetTo=', v_OffSetTo));

						

			SET p_WHERE = '';

			/*

			IF (v_ServiceTypeID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'h.ServiceTypeID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ServiceTypeID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			*/

						

			IF (v_TerminalTypeID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.TerminalTypeID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalTypeID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_TerminalModelID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.TerminalModelID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalModelID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_TerminalBrandID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.TerminalBrandID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalBrandID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_ParticularID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.MerchantID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_TerminalSerialNo, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.SerialNo = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_TerminalSerialNo));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_ClientID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.ClientID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ClientID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_SPID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.ServiceProviderID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SPID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_FEID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.FEID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_FEID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_TID, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TID = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_TID));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_MID, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.MID = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_MID));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_TerminalStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.TerminalStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_FSRStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FSRStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_FSRStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_ServiceStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'j.IRStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ServiceStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_isClose > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'j.isClose = ');

				SET p_WHERE = CONCAT(p_WHERE, v_isClose);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_FSRDateFrom, "0000-00-00") != 0 && STRCMP(v_FSRDateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FSRDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_FSRDateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_FSRDateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_ActionMade, "0") != 0 && STRCMP(v_ActionMade, "[NOT SPECIFIED]") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ActionMade = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_ActionMade));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_JobTypeDescription, "0") != 0 && STRCMP(v_JobTypeDescription, "[NOT SPECIFIED]") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobTypeDescription = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_JobTypeDescription));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_RegionID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'n.RegionType = ');

				SET p_WHERE = CONCAT(p_WHERE, v_RegionID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_LocationID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'n.RegionID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_LocationID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE			

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

					

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', '

							IFNULL(a.FSRNo, 0) AS FSRNo,	

							IFNULL(a.FSRID, 0) AS FSRID,

							IFNULL(a.No, "-") AS `No`,

							IFNULL(b1.`Name`, "-") AS Merchant,

							IFNULL(o.Region, "-") AS Region,

							IFNULL(n.Province, "-") AS Province,

							IFNULL(b1.Address, "-") AS Address,

							IFNULL(j.PrimaryNum, "-") AS PrimaryNum,

							IFNULL(j.SecondaryNum, "-") AS SecondaryNum,

							IFNULL(a.MID, "-") AS MID,

							IFNULL(a.TID, "-") AS TID,

							IFNULL(a.InvoiceNo, "-") AS InvoiceNo,

							IFNULL(a.BatchNo, "-") AS BatchNo,

							IFNULL(a.TimeArrived, "-") AS TimeArrived,

							IFNULL(a.TimeStart, "-") AS TimeStart,

							IFNULL(h.Description, "-") AS FSR,

							IFNULL(l.JobTypeSubDescription, "-") AS ServiceTypeDescription,

							IFNULL(l.ServiceStatusDescription, "-") AS ServiceStatusDescription,							

							IFNULL(DATE_FORMAT(a.FSRDate, "%m-%d-%Y"), "-") AS FSRDate,

							IFNULL(a.FSRTime, "-") AS FSRTime,

							IFNULL(a.TxnAmt, "-") AS TxnAmt,

							IFNULL(a.TimeEnd, "-") AS TimeEnd,

							IFNULL(c.SerialNo, "-") AS TerminalSN,

							IFNULL(a.MerchantContactNo, "-") AS MerchantContactNo,

							IFNULL(a.MerchantRepresentative, "-") AS MerchantRepresentative,

							IFNULL(a.MerchantRepresentativePosition, "-") AS MerchantRepresentativePosition,

							IFNULL(a.FEName, "-") AS FEName,

							IFNULL(a.SerialNo, "-") AS SerialNo,

							IFNULL(e.Description, "-") AS TypeDescription,

							IFNULL(f.Description, "-") AS ModelDescription,

							IFNULL(g.Description, "-") AS BrandDescription,

							IFNULL(a.FSRStatusDescription, "-") AS FSRStatusDescription,

							IFNULL(a.ProcessType, "-") AS ProcessType,

							IFNULL(a.IRNo, "-") AS IRNo,

							IFNULL(b2.`Name`, "-") AS ClientName,							

							IFNULL((SELECT t2.SerialNo FROM tblservicingdetail t1 LEFT JOIN tblsimdetail AS t2 ON t1.SIMID = t2.SIMID WHERE (a.ServiceNo = t1.ServiceNo)), "-") AS SIMSN,

							IFNULL((SELECT t2.Carrier FROM tblservicingdetail t1 LEFT JOIN tblsimdetail AS t2 ON t1.SIMID = t2.SIMID WHERE (a.ServiceNo = t1.ServiceNo)), "-") AS Carrier,														

							IFNULL(a.PowerSN, "-") AS PowerSN,

							IFNULL(a.DockSN, "-") AS DockSN,

							IFNULL(l.ServiceNo, 0) AS ServiceNo,

							IFNULL(l.RequestNo, "-") AS RequestNo,

							IFNULL(a.ActionTaken, "-") AS ActionTaken,							

							IFNULL((SELECT t2.Description FROM tblfsrdetail t1 LEFT JOIN tblreason AS t2 ON t1.ReasonID = t2.ReasonID WHERE (a.ServiceNo = t1.ServiceNo)), "-") AS Reason,												

							IFNULL_NUMERIC(l.TerminalID) AS TerminalID,

							IFNULL_NUMERIC(l.SIMID) AS SIMID,

							IFNULL_NUMERIC(l.DockID) AS DockID,

							IFNULL_NUMERIC(l.ReplaceTerminalID) AS ReplaceTerminalID,

							IFNULL_NUMERIC(l.ReplaceSIMID) AS ReplaceSIMID,

							IFNULL_NUMERIC(l.ReplaceDockID) AS ReplaceDockID,							

							IFNULL_STRING(l.ReplaceTerminalSN) AS ReplaceTerminalSN,

							IFNULL_STRING(l.ReplaceSIMSN) AS ReplaceSIMSN,

							IFNULL_STRING(l.ReplaceDockSN) AS ReplaceDockSN,

							IFNULL((SELECT t2.Description FROM tblterminaldetail t1 LEFT JOIN tblterminaltype AS t2 ON t1.TerminalTypeID = t2.TerminalTypeID WHERE (t1.TerminalID = l.ReplaceTerminalID)), "-") AS RepTerminalType,

							IFNULL((SELECT t2.Description FROM tblterminaldetail t1 LEFT JOIN tblterminalmodel AS t2 ON t1.TerminalModelID = t2.TerminalModelID WHERE (t1.TerminalID = l.ReplaceTerminalID)), "-") AS RepTerminalModel,

							IFNULL((SELECT t2.Description FROM tblterminaldetail t1 LEFT JOIN tblterminalbrand AS t2 ON t1.TerminalBrandID = t2.TerminalBrandID WHERE (t1.TerminalID = l.ReplaceTerminalID)), "-") AS RepTerminalBrand,

							IFNULL((SELECT Carrier FROM tblsimdetail WHERE (SIMID = l.ReplaceSIMID)), "-") AS RepSIMCarrier,

							IFNULL(a.JobTypeDescription, "-") AS JobTypeDescription,

							IFNULL(i.ServiceJobTypeDescription, "-") AS ServiceJobTypeDescription,

							IFNULL(a.ActionMade, "-") AS ActionMade,

							IFNULL(l.CurTerminalSNStatusDescription, "-") AS CurTerminalSNStatusDescription,

							IFNULL(l.CurSIMSNStatusDescription, "-") AS CurSIMSNStatusDescription,

							IFNULL(l.CurDockSNStatusDescription, "-") AS CurDockSNStatusDescription,

							IFNULL(l.RepTerminalSNStatusDescription, "-") AS RepTerminalSNStatusDescription,

							IFNULL(l.RepSIMSNStatusDescription, "-") AS RepSIMSNStatusDescription,

							IFNULL(l.RepDockSNStatusDescription, "-") AS RepDockSNStatusDescription,

							IFNULL(l.AppVersion, "-") AS AppVersion,

							IFNULL(l.AppCRC, "-") AS AppCRC,

							IFNULL(j.SET_UP, "-") AS SET_UP,

							IFNULL(j.REQUEST_FOR, "-") AS REQUEST_FOR,

							IFNULL(j.ALIPAY_TID, "-") AS ALIPAY_TID,

							IFNULL(j.ALIPAY_MID, "-") AS ALIPAY_MID,

							IFNULL(j.WECHAT_TID, "-") AS WECHAT_TID,

							IFNULL(j.WECHAT_MID, "-") AS WECHAT_MID,

							IFNULL(j.DCC_MERCHANT, "-") AS DCC_MERCHANT,

							IFNULL(j.IRDate, "-") AS IRDate,

							IFNULL(j.InstallationDate, "-") AS InstallationDate,

							IFNULL(j.OTHER_SPECIAL_INSTRUCTION, "-") AS OTHER_SPECIAL_INSTRUCTION

							FROM

							tblfsrdetail AS a

							LEFT JOIN tblterminalallocation AS b ON a.MID = b.MID AND a.TID = b.TID

							LEFT JOIN tblparticular AS b1 ON b.MerchantID = b1.ParticularID AND b1.ParticularTypeID = 1

							LEFT JOIN tblparticular AS b2 ON b.ClientID = b2.ParticularID AND b2.ParticularTypeID = 2

							LEFT JOIN tblterminaldetail AS c ON a.TerminalSN = c.SerialNo

							LEFT JOIN tblparticular AS d ON b.MerchantID = d.ParticularID

							LEFT JOIN tblterminaltype AS e ON c.TerminalTypeID = e.TerminalTypeID

							LEFT JOIN tblterminalmodel AS f ON c.TerminalModelID = f.TerminalModelID

							LEFT JOIN tblterminalbrand AS g ON c.TerminalBrandID = g.TerminalBrandID

							LEFT JOIN tblservicetype AS h ON a.FSR = h.Code

							LEFT JOIN tblservicetype AS i ON a.JobTypeDescription = i.JobTypeDescription

							LEFT JOIN tblirdetail AS j ON b.IRID = j.IRIDNo

							LEFT JOIN tblsimdetail AS k ON b.SIMID = k.SIMID

							LEFT JOIN tblservicingdetail AS l ON a.ServiceNo = l.ServiceNo

							LEFT JOIN tblreason AS m ON a.ReasonID = m.ReasonID

							LEFT JOIN tblregiondetail AS n ON b.RegionID = n.RegionID

							LEFT JOIN tblregion AS o ON b.RegionType = o.RegionID');

			

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

							

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.FSRDate';

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;	

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			IF (v_OffSetTo > 0)

			THEN	

				SET v_OffSet = 0;

				

				IF (v_OffSetFrom <= 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;

				

				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			SET @QUERY = p_SQL;

			

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'FSR For Client')	

		THEN

			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);

			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER); # MetroManila/Provincial

			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER); # Pasig

			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);

			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));

			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));

			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));

			SET v_Status = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);

			SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11));

			SET v_SIMSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));

			SET v_isPullOut = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)) AS UNSIGNED INTEGER);

			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));

										

			SET p_WHERE = '';

			IF (v_ClientID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ClientID = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ClientID, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_MerchantID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.MerchantID = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_MerchantID, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_JobType > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobType = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_JobType, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_RegionType > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.RegionType = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_RegionType, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_RegionID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.RegionID = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_RegionID, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_IRIDNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRIDNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_IRIDNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_ActionMade, "0") != 0 && STRCMP(v_ActionMade, "[NOT SPECIFIED]") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.ActionMade = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_ActionMade));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.FSRDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_TerminalSN, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalSN = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_TerminalSN));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_SIMSN, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMSN = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_SIMSN));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_Status > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_Status, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			# include service already done FSR

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.FSRNo > 0 ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			

			# pullout ir

			IF (v_isPullOut > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.IRStatus != 11'); # pullout ir

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (LENGTH(v_IncludeBillable))

			THEN

				IF (STRCMP(v_IncludeBillable, "BILLABLE") = 0)

				THEN

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isBillable = 1'); # pullout ir

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				ELSEIF (STRCMP(v_IncludeBillable, "NON-BILLABLE") = 0)

				THEN

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isBillable = 0'); # pullout ir

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				END IF;

			END IF;

								

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			

			# ORDER BY			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.ServiceNo';

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(xTable.FSRNo) AS FSRNo,

							IFNULL_NUMERIC(xTable.IRIDNo) AS IRIDNo,						

							IFNULL_NUMERIC(xTable.RegionID) AS RegionID,

							IFNULL_NUMERIC(xTable.RegionType) AS RegionType,

							IFNULL_NUMERIC(xTable.ServiceNo) AS ServiceNo,

							IFNULL_STRING(xTable.RequestNo) AS RequestNo,

							IFNULL_STRING(xTable.ReferenceNo) AS ReferenceNo,							

							IFNULL_STRING(xTable.ServiceDate) AS ServiceDate,

							IFNULL_STRING(xTable.ServiceTime) AS ServiceTime,

							IFNULL_STRING(xTable.ServiceReqDate) AS ServiceReqDate,

							IFNULL_STRING(xTable.ServiceReqTime) AS ServiceReqTime,

							xTable.JobType AS JobType,

							xTable.JobTypeDescription AS JobTypeDescription,

							xTable.JobTypeSubDescription AS JobTypeSubDescription,

							xTable.JobTypeStatusDescription AS JobTypeStatusDescription,

							IFNULL_NUMERIC(xTable.ServiceStatus) AS ServiceStatus,

							xTable.ServiceStatusDescription AS ServiceStatusDescription,

							IFNULL_STRING(xTable.AppVersion) AS AppVersion,

							IFNULL_STRING(xTable.AppCRC) AS AppCRC,							

							IFNULL_STRING(xTable.ReplaceTerminalSN) AS ReplaceTerminalSN,

							IFNULL_STRING(xTable.ReplaceSIMSN) AS ReplaceSIMSN,

							IFNULL_STRING(xTable.ReplaceDockSN) AS ReplaceDockSN,							

							IFNULL_STRING(xTable.IRNo) AS IRNo,

							IFNULL_STRING(xTable.IRDate) AS IRDate,							

							IFNULL_STRING(xTable.TID) AS TID,

							IFNULL_STRING(xTable.`MID`) AS `MID`,

							IFNULL_STRING(xTable.SET_UP) AS SET_UP,

							IFNULL_STRING(xTable.OTHER_SPECIAL_INSTRUCTION) AS OTHER_SPECIAL_INSTRUCTION,	

							IFNULL_STRING(xTable.Remarks) AS Remarks,								

							IFNULL_STRING(xTable.PrimaryNum) AS PrimaryNum,

							IFNULL_STRING(xTable.SecondaryNum) AS SecondaryNum,

							IFNULL_NUMERIC(xTable.IRStatus) AS IRStatus,																					

							IFNULL_STRING(xTable.FSRDate) AS FSRDate,

							IFNULL_STRING(xTable.TimeStart) AS TimeStart,

							IFNULL_STRING(xTable.TimeEnd) AS TimeEnd,

							IFNULL_STRING(xTable.ActionMade) AS ActionMade,

							IFNULL_STRING(xTable.MerchantRepresentative) AS MerchantRepresentative,

							IFNULL_STRING(xTable.MerchantRepresentativePosition) AS MerchantRepresentativePosition,

							IFNULL_STRING(xTable.MerchantContactNo) AS MerchantContactNo,							

							IFNULL_STRING(xTable.ProblemReported) AS ProblemReported,

							IFNULL_STRING(xTable.ActualProblemReported) AS ActualProblemReported,

							IFNULL_STRING(xTable.ActionTaken) AS ActionTaken,

							IFNULL_STRING(xTable.AnyComments) AS AnyComments,

							IFNULL_STRING(xTable.FSRMerchant) AS FSRMerchant,	

							IFNULL_NUMERIC(xTable.Attempt) AS Attempt,						

							IFNULL_STRING(xTable.Reason) AS Reason,

							IFNULL_STRING(xTable.MerchantID) AS MerchantID,

							xTable.Merchant AS Merchant,

							IFNULL_STRING(xTable.ClientID) AS ClientID,

							IFNULL_STRING(xTable.Client) AS `Client`,

							IFNULL_STRING(xTable.FEID) AS FEID,

							IFNULL_STRING(xTable.FEName) AS FEName,

							IFNULL_STRING(xTable.TerminalSN) AS TerminalSN,

							IFNULL_STRING(xTable.SIMSN) AS SIMSN,

							IFNULL_STRING(xTable.Carrier) AS Carrier,

							(SELECT

							b.Region

							FROM

							tblregiondetail a

							LEFT JOIN tblregion AS b ON a.RegionType = b.RegionID

							WHERE (a.RegionID = xTable.RegionID)) AS Region,

							(SELECT

							a.Province

							FROM

							tblregiondetail a

							WHERE (a.RegionID = xTable.RegionID)) AS Province,

							IFNULL_NUMERIC(xTable.isCancelled) AS isCancelled,

							IFNULL_NUMERIC(xTable.isActive) AS isActive,

							IFNULL_STRING(xTable.CreatedBy) AS CreatedBy,

							IFNULL_FORMAT_DATETIME_AMPM(xTable.CreatedDateTime) AS CreatedDateTime,

							IFNULL_STRING(xTable.DispatchBy) AS DispatchBy,

							IFNULL_FORMAT_DATETIME_AMPM(xTable.DispatchDateTime) AS DispatchDateTime,

							IFNULL_STRING(xTable.ProcessedBy) AS ProcessedBy,

							IFNULL_FORMAT_DATETIME_AMPM(xTable.ProcessedDateTime) AS ProcessedDateTime,

							IFNULL_STRING(xTable.isBillable) AS isBillable

							FROM

							(

							SELECT	

							d.FSRNo,												

							a.IRIDNo,						

							f1.RegionID,

							f1.RegionType,

							a.ServiceNo,

							a.RequestNo,

							a.ReferenceNo,							

							IFNULL_FORMAT_DATE(a.ServiceDate) AS ServiceDate,

							a.ServiceTime,							

							IFNULL_FORMAT_DATE(a.ServiceReqDate) AS ServiceReqDate,

							a.ServiceReqTime,

							a.JobType,

							a.JobTypeDescription,

							a.JobTypeSubDescription,

							a.JobTypeStatusDescription,

							a.ServiceStatus,

							a.ServiceStatusDescription,

							a.AppVersion,

							a.AppCRC,

							a.ReplaceTerminalSN AS ReplaceTerminalSN,

							a.ReplaceSIMSN AS ReplaceSIMSN,

							a.ReplaceDockSN AS ReplaceDockSN,

							b.IRNo,						

							IFNULL_FORMAT_DATE(b.IRDate) AS IRDate,

							b.TID,

							b.`MID`,

							b.SET_UP,

							b.OTHER_SPECIAL_INSTRUCTION,

							(CONCAT(IFNULL_STRING(b.IRNo), "^", 

							IFNULL_STRING(a.RequestNo), "^",

							IFNULL_STRING(a.ReferenceNo), "^", 

							IFNULL_STRING(a.JobTypeDescription), "^", 

							IFNULL_STRING(a.JobTypeStatusDescription), "^", 

							IFNULL_STRING(b.MerchantName), "^", 

							IFNULL_STRING(b.TID), "^", 

							IFNULL_STRING(b.MID), "^", 

							IFNULL_STRING(a.TerminalSN), "^", 

							IFNULL_STRING(a.SIMSerialNo))) AS sFields,

							d.Remarks,							

							b.PrimaryNum,

							b.SecondaryNum,

							b.IRStatus,							

							IFNULL_FORMAT_DATE(d.`FSRDate`) AS FSRDate,

							d.TimeStart,

							d.TimeEnd,

							d.ActionMade,

							d.MerchantRepresentative,

							d.MerchantRepresentativePosition,

							d.MerchantContactNo,

							d.ProblemReported,

							d.ActualProblemReported,

							d.ActionTaken,

							d.AnyComments,

							d.Merchant AS FSRMerchant,

							d.Attempt,

							e.Description AS Reason,

							f1.ParticularID AS MerchantID,

							f1.`Name` AS Merchant,

							f2.ParticularID AS ClientID,

							f2.`Name` AS `Client`,

							d.FEID AS FEID,

							d.FEName AS FEName,

							g.SerialNo AS TerminalSN,

							h.SerialNo AS SIMSN,

							h.Carrier AS Carrier,

							a.isCancelled,

							a.isActive,

							a.ProcessedBy AS CreatedBy,

							a.ProcessedDateTime AS CreatedDateTime,

							a.DispatchBy AS DispatchBy,

							a.DispatchDateTime AS DispatchDateTime,

							d.ProcessedBy AS ProcessedBy,

							d.ProcessedDateTime AS ProcessedDateTime,

							(IF(a.JobTypeStatusDescription != "COMPLETED", 99, d.isBillable)) AS isBillable	

							FROM

							tblservicingdetail a						

							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

							LEFT JOIN tblfsrdetail AS d ON a.IRIDNo = a.IRIDNo AND a.ServiceNo = d.ServiceNo

							LEFT JOIN tblreason AS e ON d.ReasonID = e.ReasonID

							INNER JOIN tblparticular AS f1 ON a.MerchantID = f1.ParticularID AND f1.ParticularTypeID = 1

							INNER JOIN tblparticular AS f2 ON a.ClientID = f2.ParticularID AND f2.ParticularTypeID = 2

							INNER JOIN tblparticular AS f3 ON a.FEID = f3.ParticularID AND f3.ParticularTypeID = 3

							LEFT JOIN tblterminaldetail AS g ON a.TerminalID = g.TerminalID

							LEFT JOIN tblsimdetail AS h ON a.SIMID = h.SIMID

							',

							' ', (IF(LENGTH(p_WHERE)>0, (CONCAT('WHERE',' ',p_WHERE)), '')), ' ',

							(IF(LENGTH(p_ORDERBY)>0, CONCAT('ORDER BY',' ', p_ORDERBY),'')),' ',

							'

							) AS xTable');

							

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			

			SET p_SQL_Select = '';	

			SET p_SQL_Select = CONCAT(p_SQL_Select,'SELECT');

			SET p_SQL_Select = CONCAT(p_SQL_Select, ' ', 

							'IFNULL_NUMERIC(xTable.FSRNo) AS FSRNo,

							IFNULL_NUMERIC(xTable.IRIDNo) AS IRIDNo,

							IFNULL_STRING(xTable.ClientID) AS ClientID,

							IFNULL_STRING(xTable.MerchantID) AS MerchantID,

							IFNULL_NUMERIC(xTable.ServiceNo) AS ServiceNo,

							xTable.JobType AS JobType,

							xTable.JobTypeDescription AS JobTypeDescription,							

							IFNULL_NUMERIC(xTable.ServiceStatus) AS ServiceStatus,

							xTable.ServiceStatusDescription AS ServiceStatusDescription,							

							IFNULL_STRING(xTable.ActionMade) AS ActionMade,

							IFNULL_STRING(xTable.FSRDate) AS FSRDate,

							IFNULL_STRING(xTable.TerminalSN) AS TerminalSN,

							IFNULL_STRING(xTable.SIMSN) AS SIMSN,

							IFNULL_NUMERIC(xTable.IRStatus) AS IRStatus,

							IFNULL_NUMERIC(xTable.RegionType) AS RegionType,

							IFNULL_NUMERIC(xTable.RegionID) AS RegionID,

							IFNULL_STRING(xTable.isBillable) AS isBillable

							FROM

							(

							SELECT	

							d.FSRNo,

							a.IRIDNo,

							f2.ParticularID AS ClientID,	

							f1.ParticularID AS MerchantID,																		

							a.ServiceNo,							

							a.JobType,

							a.JobTypeDescription,							

							a.ServiceStatus,

							a.ServiceStatusDescription,

							(CONCAT(IFNULL_STRING(b.IRNo), "^", 

							IFNULL_STRING(a.RequestNo), "^",

							IFNULL_STRING(a.ReferenceNo), "^", 

							IFNULL_STRING(a.JobTypeDescription), "^", 

							IFNULL_STRING(a.JobTypeStatusDescription), "^", 

							IFNULL_STRING(b.MerchantName), "^", 

							IFNULL_STRING(b.TID), "^", 

							IFNULL_STRING(b.MID), "^", 

							IFNULL_STRING(a.TerminalSN), "^", 

							IFNULL_STRING(a.SIMSerialNo))) AS sFields,							

							d.ActionMade,

							d.`FSRDate` AS FSRDate,

							g.SerialNo AS TerminalSN,

							h.SerialNo AS SIMSN,

							b.IRStatus,

							f1.RegionType,

							f1.RegionID,

							(IF(a.JobTypeStatusDescription != "COMPLETED", 99, d.isBillable)) AS isBillable				

							FROM

							tblservicingdetail a							

							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

							LEFT JOIN tblfsrdetail AS d ON a.IRIDNo = a.IRIDNo AND a.ServiceNo = d.ServiceNo

							LEFT JOIN tblreason AS e ON d.ReasonID = e.ReasonID

							INNER JOIN tblparticular AS f1 ON a.MerchantID = f1.ParticularID AND f1.ParticularTypeID = 1

							INNER JOIN tblparticular AS f2 ON a.ClientID = f2.ParticularID AND f2.ParticularTypeID = 2

							INNER JOIN tblparticular AS f3 ON a.FEID = f3.ParticularID AND f3.ParticularTypeID = 3

							LEFT JOIN tblterminaldetail AS g ON a.TerminalID = g.TerminalID

							LEFT JOIN tblsimdetail AS h ON a.SIMID = h.SIMID

							) AS xTable');

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

				

			SET @QUERY = p_SQL;

						

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

												

			IF (LENGTH(p_SQL_Select) > 0)

			THEN

				CALL spCreateTempTable("Create", "FSR Client Temp");

				

				SET p_SQL_Insert = '';

				SET p_SQL_Insert = 'INSERT INTO tblfsrclient (FSRNo, IRIDNo, ClientID, MerchantID, ServiceNo, JobType, JobTypeDescription, ServiceStatus, ServiceStatusDescription, ActionMade, FSRDate, TerminalSN, SIMSN, IRStatus, RegionType, RegionID, IncludeBillable)';

				SET @QUERY = '';	

				SET @QUERY = CONCAT(p_SQL_Insert, p_SQL_Select);

				

				#SELECT CONCAT('After:QUERY = ', @QUERY);

				

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

			END IF;					

			

		ELSEIF (p_SearchBy = 'FSR For Operation')	

		THEN

			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);

			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER); # LuzViMin

			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER); # Pasig

			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);

			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));

			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));

			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));

			SET v_Status = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);

			SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,11));

			SET v_SIMSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));

			SET v_isPullOut = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,13)) AS UNSIGNED INTEGER);

			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));

			

			# Mobile

			SET v_MobileID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)) AS UNSIGNED INTEGER);

			SET v_MobileTerminalID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16));

			SET v_isMobile = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,17)) AS UNSIGNED INTEGER);

			

			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18));

			SET v_ServiceJobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19));

			SET v_ServiceResultDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20));

