			SET p_WHERE = '';

			IF (v_ClientID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ClientID = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ClientID, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_MerchantID > 0)

