				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_IRIDNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRIDNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_IRIDNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_ActionMade, "0") != 0 && STRCMP(v_ActionMade, "[NOT SPECIFIED]") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.ActionMade = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_ActionMade));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET v_Temp = '';

			IF (STRCMP(v_JobTypeStatusDescription, "OVERALL") = 0)

			THEN

				SET v_DateFrom = '0000-00-00';

				SET v_DateTo = '0000-00-00';

				SET v_Temp = CONCAT('(',ADD_SINGLEQUOTE("PENDING"), ",", ADD_SINGLEQUOTE("PROCESSING"), ')');

			ELSE

				SET v_Temp = CONCAT('(',ADD_SINGLEQUOTE(v_JobTypeStatusDescription), ')');

			END IF;

			

			

			IF (LENGTH(v_Temp) > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobTypeStatusDescription IN ', v_Temp); # pullout ir

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_TerminalSN, "0") != 0)

