							IFNULL_STRING(xTable.AppCRC) AS AppCRC,							

							IFNULL_STRING(xTable.ReplaceTerminalSN) AS ReplaceTerminalSN,

							IFNULL_STRING(xTable.ReplaceSIMSN) AS ReplaceSIMSN,

							IFNULL_STRING(xTable.ReplaceDockSN) AS ReplaceDockSN,	

							IFNULL_STRING(xTable.IRID) AS IRID,						

							IFNULL_STRING(xTable.IRNo) AS IRNo,

