							IFNULL_STRING(xTable.PrimaryNum) AS PrimaryNum,

							IFNULL_STRING(xTable.SecondaryNum) AS SecondaryNum,

							IFNULL_NUMERIC(xTable.IRStatus) AS IRStatus,

							IFNULL_STRING(xTable.FSRDate) AS FSRDate,

							IFNULL_STRING(xTable.TimeStart) AS TimeStart,

							IFNULL_STRING(xTable.TimeEnd) AS TimeEnd,

							IFNULL_STRING(xTable.ActionMade) AS ActionMade,

							IFNULL_STRING(xTable.MerchantRepresentative) AS MerchantRepresentative,

							IFNULL_STRING(xTable.MerchantRepresentativePosition) AS MerchantRepresentativePosition,

							IFNULL_STRING(xTable.MerchantContactNo) AS MerchantContactNo,							

							IFNULL_STRING(xTable.ProblemReported) AS ProblemReported,

							IFNULL_STRING(xTable.ActualProblemReported) AS ActualProblemReported,

							IFNULL_STRING(xTable.ActionTaken) AS ActionTaken,

							IFNULL_STRING(xTable.AnyComments) AS AnyComments,

							IFNULL_STRING(xTable.FSRMerchant) AS FSRMerchant,

							IFNULL_NUMERIC(xTable.Attempt) AS Attempt,

							IFNULL_NUMERIC(xTable.RegionType) AS RegionType,							

							IFNULL_STRING(xTable.Reason) AS Reason,

							IFNULL_STRING(xTable.MerchantID) AS MerchantID,

							xTable.Merchant AS Merchant,

