							a.ReplaceTerminalSN AS ReplaceTerminalSN,

							a.ReplaceSIMSN AS ReplaceSIMSN,

							a.ReplaceDockSN AS ReplaceDockSN,

							b.IRID,

							b.IRNo,						

							IFNULL_FORMAT_DATE(b.IRDate) AS IRDate,

							IFNULL_FORMAT_DATE(b.InstallationDate) AS InstallationDate,

							IFNULL_FORMAT_DATE((SELECT MAX(xTemp.ImportDateTime) FROM tblinstallationrequestmaster xTemp WHERE xTemp.IRID = b.IRID)) AS ImportDateTime,						

							b.TID,

							b.`MID`,

							b.SET_UP,

							b.OTHER_SPECIAL_INSTRUCTION,

							(CONCAT(IFNULL_STRING(b.IRNo), "^", 

