							d.Attempt,

							e.Description AS Reason,							

							f1.RegionID AS RegionID,

							f1.RegionType AS RegionType,

							(SELECT xTable.ParticularID FROM tblparticular xTable WHERE xTable.ParticularID = a.MerchantID) AS MerchantID,

							(SELECT xTable.`Name` FROM tblparticular xTable WHERE xTable.ParticularID = a.MerchantID) AS Merchant,

							(SELECT xTable.ParticularID FROM tblparticular xTable WHERE xTable.ParticularID = a.ClientID) AS ClientID,

							(SELECT xTable.`Name` FROM tblparticular xTable WHERE xTable.ParticularID = a.ClientID) AS Client,

							(SELECT xTable.ParticularID FROM tblparticular xTable WHERE xTable.ParticularID = a.FEID) AS FEID,

							(SELECT xTable.`Name` FROM tblparticular xTable WHERE xTable.ParticularID = a.FEID) AS FEName,							

							g.SerialNo AS TerminalSN,

							h.SerialNo AS SIMSN,

							h.Carrier AS Carrier,

							a.isCancelled,

							a.isActive,

							a.ProcessedBy AS CreatedBy,

							a.ProcessedDateTime AS CreatedDateTime,

							a.DispatchBy AS DispatchBy,

							a.DispatchDateTime AS DispatchDateTime,

							d.ProcessedBy AS ProcessedBy,

							d.ProcessedDateTime AS ProcessedDateTime,							

							(IF(a.JobTypeStatusDescription != "COMPLETED", 99, d.isBillable)) AS isBillable,

							d.MobileID AS MobileID,

							d.MobileTerminalID AS MobileTerminalID

							FROM

							tblservicingdetail a						

							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

							LEFT JOIN tblfsrdetail AS d ON a.IRIDNo = a.IRIDNo AND a.ServiceNo = d.ServiceNo

							LEFT JOIN tblreason AS e ON d.ReasonID = e.ReasonID							

							LEFT JOIN tblterminaldetail AS g ON a.TerminalID = g.TerminalID

							LEFT JOIN tblsimdetail AS h ON a.SIMID = h.SIMID

							INNER JOIN tblparticular AS f1 ON a.MerchantID = f1.ParticularID AND f1.ParticularTypeID = 1

							',

							' ', (IF(LENGTH(p_WHERE)>0, (CONCAT('WHERE',' ',p_WHERE)), '')), ' ',

							(IF(LENGTH(p_ORDERBY)>0, CONCAT('ORDER BY',' ', p_ORDERBY),'')),' ',

							') AS xTable');

							

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			

			SET p_SQL_Select = '';	

