							xTable.ServiceStatusDescription AS ServiceStatusDescription,							

							IFNULL_STRING(xTable.ActionMade) AS ActionMade,

							IFNULL_STRING(xTable.FSRDate) AS FSRDate,

							IFNULL_STRING(xTable.TerminalSN) AS TerminalSN,

							IFNULL_STRING(xTable.SIMSN) AS SIMSN,

							IFNULL_NUMERIC(xTable.IRStatus) AS IRStatus,

							IFNULL_NUMERIC(xTable.RegionType) AS RegionType,

							IFNULL_NUMERIC(xTable.RegionID) AS RegionID,

							IFNULL_STRING(xTable.isBillable) AS isBillable,

							IFNULL_NUMERIC(xTable.MobileID) AS MobileID,

							IFNULL_STRING(xTable.isBillable) AS MobileTerminalID

							FROM

							(

							SELECT	

							a.IRIDNo,							

							(SELECT xTable.ParticularID FROM tblparticular xTable WHERE xTable.ParticularID = a.ClientID) AS ClientID,

							(SELECT xTable.ParticularID FROM tblparticular xTable WHERE xTable.ParticularID = a.MerchantID) AS MerchantID,																									

							a.ServiceNo,							

							a.JobType,

							a.JobTypeDescription,							

							a.ServiceStatus,

							a.ServiceStatusDescription,

							(CONCAT(IFNULL_STRING(b.IRNo), "^", 

							IFNULL_STRING(a.RequestNo), "^",

							IFNULL_STRING(a.ReferenceNo), "^", 

							IFNULL_STRING(a.JobTypeDescription), "^", 

							IFNULL_STRING(a.JobTypeStatusDescription), "^", 

							IFNULL_STRING(b.MerchantName), "^", 

							IFNULL_STRING(b.TID), "^", 

							IFNULL_STRING(b.MID), "^", 

							IFNULL_STRING(a.TerminalSN), "^", 

							IFNULL_STRING(a.SIMSerialNo))) AS sFields,							

							d.ActionMade,

							d.`FSRDate` AS FSRDate,

							g.SerialNo AS TerminalSN,

							h.SerialNo AS SIMSN,

							b.IRStatus,

							f1.RegionType,

							f1.RegionID,

							(IF(a.JobTypeStatusDescription != "COMPLETED", 99, d.isBillable)) AS isBillable,

							d.MobileID,

							d.MobileTerminalID		

							FROM

							tblservicingdetail a							

							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

							LEFT JOIN tblfsrdetail AS d ON a.IRIDNo = a.IRIDNo AND a.ServiceNo = d.ServiceNo

							LEFT JOIN tblreason AS e ON d.ReasonID = e.ReasonID							

							LEFT JOIN tblterminaldetail AS g ON a.TerminalID = g.TerminalID

							LEFT JOIN tblsimdetail AS h ON a.SIMID = h.SIMID

							INNER JOIN tblparticular AS f1 ON a.MerchantID = f1.ParticularID AND f1.ParticularTypeID = 1

							) AS xTable');

					

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

				

			SET @QUERY = p_SQL;

						

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

						

			IF (LENGTH(p_SQL_Select) > 0)

			THEN

				CALL spCreateTempTable("Create", "FSR Client Temp");

				

				SET p_SQL_Insert = '';

				SET p_SQL_Insert = 'INSERT INTO tblfsrclient (IRIDNo, ClientID, MerchantID, ServiceNo, JobType, JobTypeDescription, ServiceStatus, ServiceStatusDescription, ActionMade, FSRDate, TerminalSN, SIMSN, IRStatus, RegionType, RegionID, IncludeBillable, MobileID, MobileTerminalID)';

				SET @QUERY = '';	

				SET @QUERY = CONCAT(p_SQL_Insert, p_SQL_Select);

				

				#SELECT CONCAT('After:QUERY = ', @QUERY);

				

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

			END IF;

			

				

		ELSE

			SELECT FSRID, NO, Merchant, MID, TID, TimeArrived, TimeStart, FSR, FSRDate, FSRTime, TxnAmt, TimeEnd, TerminalSN, MerchantContactNo, MerchantRepresentative, FEName, SerialNo

			FROM   tblfsrdetail

			ORDER BY FSRDate;

		END IF;	

            

	END IF;    

END */$$
DELIMITER ;

