			SET v_TerminalSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_IRStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));
