			SET v_TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)) AS UNSIGNED INTEGER);
			SET v_ReqDateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));
