			SET v_InstDateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,14));
			SET v_InstDateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,15));
			SET v_TADateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,16));
			SET v_TADateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,17));
			SET v_FSRDateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,18));
			SET v_FSRDateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,19));
			SET v_IRImportDateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,20));
			SET v_IRImportDateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,21));
			SET v_SIMSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,22));
			
			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,23));			
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,24)) AS UNSIGNED INTEGER);
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,25));
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,26)) AS UNSIGNED INTEGER);
			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,27));
			SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,28));
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,29));
			SET v_NoOfDayPending = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,30)) AS UNSIGNED INTEGER);
			SET v_isOverDue = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,31)) AS UNSIGNED INTEGER);
			SET v_isClose = TRIM(SPLIT_STRING(p_SearchValue, '|' ,32));
			SET v_DummyID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,33)) AS UNSIGNED INTEGER);
			SET v_DummyID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,34)) AS UNSIGNED INTEGER);			
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,35)) AS UNSIGNED INTEGER);
			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,36)) AS UNSIGNED INTEGER);
			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,37)) AS UNSIGNED INTEGER);			
			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,38)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,39)) AS UNSIGNED INTEGER);			
			SET v_isPrimary = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,40)) AS UNSIGNED INTEGER);				
			
			#SELECT (CONCAT('v_ServiceTypeID=', v_ServiceTypeID));
			#SELECT (CONCAT('v_ParticularID=', v_ParticularID));
			#SELECT (CONCAT('v_TerminalTypeID=', v_TerminalTypeID));
			#SELECT (CONCAT('v_TerminalModelID=', v_TerminalModelID));
			#SELECT (CONCAT('v_TerminalBrandID=', v_TerminalBrandID));
			#SELECT (CONCAT('v_TerminalSerialNo=', v_TerminalSerialNo));
			#SELECT (CONCAT('v_IRStatus=', v_IRStatus));
			#SELECT (CONCAT('v_IRNo=', v_IRNo));
			#SELECT (CONCAT('v_TID=', v_TID));
