			#SELECT (CONCAT('v_TerminalStatus=', v_TerminalStatus));
			#SELECT (CONCAT('v_ReqDateFrom=', v_ReqDateFrom, "|", 'v_ReqDateTo=', v_ReqDateTo));
			#SELECT (CONCAT('v_InstDateFrom=', v_InstDateFrom, "|", 'v_InstDateTo=', v_InstDateTo));
			#SELECT (CONCAT('v_TADateFrom=', v_TADateFrom, "|", 'v_TADateTo=', v_TADateTo));
			#SELECT (CONCAT('v_FSRDateFrom=', v_FSRDateFrom, "|", 'v_FSRDateTo=', v_FSRDateTo));
			#SELECT (CONCAT('v_IRImportDateFrom=', v_IRImportDateFrom, "|", 'v_IRImportDateTo=', v_IRImportDateTo));			
			#SELECT (CONCAT('v_SIMSerialNo=', v_SIMSerialNo));
			#SELECT (CONCAT('v_ServiceStatus=', v_ServiceStatus));
			#SELECT (CONCAT('v_ServiceStatusDescription=', v_ServiceStatusDescription));			
			#SELECT (CONCAT('v_JobType=', v_JobType));
			#SELECT (CONCAT('v_JobTypeStatusDescription=', v_JobTypeStatusDescription));
			#SELECT (CONCAT('v_JobTypeDescription=', v_JobTypeDescription));
			#SELECT (CONCAT('v_ActionMade=', v_ActionMade));
			#SELECT (CONCAT('v_NoOfDayPending=', v_NoOfDayPending));
			#SELECT (CONCAT('v_isOverDue=', v_isOverDue));
			#SELECT (CONCAT('v_isClose=', v_isClose));
			#SELECT (CONCAT('v_OffSetFrom=', v_OffSetFrom));
			#SELECT (CONCAT('v_OffSetTo=', v_OffSetTo));
		    
			SET p_WHERE = '';
			IF (STRCMP(v_IRNo, "0") != 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRNo = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_IRNo, "'");
