				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_InstDateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_InstDateTo, "'", ' AS DATE)');
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;

			IF (STRCMP(v_IRImportDateFrom, "0000-00-00") != 0 && STRCMP(v_IRImportDateTo, "0000-00-00") != 0)
			THEN			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'CAST(g.ImportDateTime AS DATE)', ' ', 'BETWEEN', ' ');
				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_IRImportDateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_IRImportDateTo, "'", ' AS DATE)');
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			IF (STRCMP(v_SIMSerialNo, "0") != 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'i.SerialNo = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMSerialNo, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			IF ((LENGTH(v_SearchString > 0)) && (STRCMP(v_SearchString, "0") != 0))
			THEN	
				# MechantName			
				SET p_WHERE = CONCAT(p_WHERE, ' ', '(', 'a.MerchantName LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# TerminalSN			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'e.TerminalSN LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Dock			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'e.DockSN LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# SIMSerialNo			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'e.SIMSerialNo LIKE ');
