				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# TID			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TID LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# MID			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.MID LIKE ');
