				# IRNo
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRNo LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# ClientName			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'j.`Name` LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'", ')');	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			
			END IF;
			
			IF (v_ServiceStatus > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.ServiceStatus = ');
				SET p_WHERE = CONCAT(p_WHERE, v_ServiceStatus);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;	

			IF (STRCMP(v_ServiceStatusDescription, "0") != 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.ServiceStatusDescription = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceStatusDescription, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			IF (v_JobType > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.JobType = ');
				SET p_WHERE = CONCAT(p_WHERE, v_JobType);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;	

			IF (STRCMP(v_JobTypeStatusDescription, "0") != 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.JobTypeStatusDescription = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_JobTypeStatusDescription, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			IF (STRCMP(v_JobTypeDescription, "0") != 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.JobTypeDescription = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_JobTypeDescription, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			IF (STRCMP(v_ActionMade, "0") != 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.ActionMade = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_ActionMade, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			IF (v_isOverDue > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.InstallationDate < ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_SystemDate, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
						
			IF (v_ClientID > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ClientID = ');
				SET p_WHERE = CONCAT(p_WHERE, v_ClientID);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;			
			
			/*
			IF (STRCMP(v_isClose, "99") != 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.isClose = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_isClose, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			*/
			
			IF (v_RegionID > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'q.RegionType = ');
				SET p_WHERE = CONCAT(p_WHERE, v_RegionID);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			
			IF (v_LocationID > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'q.RegionID = ');
				SET p_WHERE = CONCAT(p_WHERE, v_LocationID);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			
			IF (v_isPrimary > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'l.isPrimary = ');
				SET p_WHERE = CONCAT(p_WHERE, v_isPrimary);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
				
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
			#SELECT CONCAT('p_WHERE = ', p_WHERE);
		    
			SET p_SQL = '';	
			SET p_SQL = CONCAT(p_SQL,'SELECT');
			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(e.TAIDNo, 0) AS TAIDNo,
							IFNULL(a.IRIDNo, 0) AS IRIDNo,
							IFNULL(a.IRID, 0) AS IRID,											
							IFNULL(a.IRNo, "-") AS IRNo,
							IFNULL(DATE_FORMAT(a.IRDate, "%m-%d-%Y"), "-") AS IRDate,
							IFNULL(DATE_FORMAT(a.InstallationDate, "%m-%d-%Y"), "-") AS InstallationDate,
							IFNULL(a.MerchantID, 0) AS MerchantID,
							IFNULL(b.`Name`, "-") AS ParticularName,
							IFNULL(r.Region, "-") AS Region,
							IFNULL(q.Province, "-") AS Province,
							IFNULL(b.Address, "-") AS Address,
							IFNULL(b.Address2, "-")AS Address2,
							IFNULL(b.Address3, "-") AS Address3,
							IFNULL(b.Address4, "-") AS Address4,
							IFNULL(a.PrimaryNum, "-") AS PrimaryNum,
							IFNULL(a.SecondaryNum, "-") AS SecondaryNum,
							IFNULL(b.ContactPerson, "-") AS ContactPerson,
							IFNULL(b.TelNo, "-") AS TelNo,
							IFNULL(b.Mobile, "-") AS Mobile,
							IFNULL(b.Email, "-") AS Email,
							IFNULL(h.Province, "-") AS City,
							IFNULL(k.Region, "-") AS Province,
							IFNULL(a.TID, "-") AS TID,
							IFNULL(a.MID, "-") AS MID,
							IFNULL(a.IRStatus, 0) AS IRStatus,
							IFNULL(a.IRStatusDescription, "-") AS IRStatusDescription,
							IFNULL(f.Description, "-") AS ServiceTypeDescription,														
							IFNULL(DATE_FORMAT(g.ImportDateTime, "%m-%d-%Y %h:%i:%s %p"), "-") AS ImportDateTime,
							IFNULL(h.RegionID, 0) AS RegionID,
							IFNULL(e.TerminalID, 0) AS TerminalID,
							IFNULL(e.TerminalSN, "-") AS TerminalSN,							
							IFNULL(o.Description, "-") AS TerminalType,
							IFNULL(p.Description, "-") AS TerminalModel,							
							IFNULL(e.SIMID, 0) AS SIMID,
							IFNULL(e.SIMSerialNo, "-") AS SIMSerialNo,
							IFNULL(i.Carrier, "-") AS Carrier,
							IFNULL(e.DockID, 0) AS DockID,
							IFNULL(e.DockSN, "-") AS DockSN,
							IFNULL(j.ParticularID, 0) AS ClientID,
							IFNULL(j.`Name`, "-") AS ClientName,						
							IFNULL(b1.ParticularID, 0) AS ServiceProviderID,
							IFNULL(b1.`Name`, "-") AS ServiceProviderName,
							IFNULL(b2.ParticularID, 0) AS FEID,
							IFNULL(b2.`Name`, "-") AS FEName,																					
							IFNULL(DATE_FORMAT(a.ProcessedDateTime, "%m-%d-%Y %h:%i:%s %p"), "-") AS ProcessedDateTime,
							IFNULL(a.ProcessedBy, "-") AS ProcessedBy,
							IFNULL(a.ProcessType, "-") AS ProcessType,
							IFNULL(l.ServiceStatus, 0) AS ServiceStatus,
							IFNULL(l.ServiceStatusDescription, "-") AS ServiceStatusDescription,
							IFNULL(l.ServiceNo, 0) AS ServiceNo,
