				# FSRRefNo
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'f.FSRRefNo LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# MechantName										
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'g.Name LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Field Engineer										
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'g1.Name LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# TerminalSN									
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalSN LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# SIMSN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMSerialNo LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# ReplaceTerminalSN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ReplaceTerminalSN LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# ReplaceSIMSN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ReplaceSIMSN LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# MID			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.MID LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# TID			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.TID LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');

				# JobTypeStatusDescription (COMPLETED, PROCESSING, PENDING, ...)			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobTypeStatusDescription LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');

				# ActionMade (SUCCESS, NEGATIVE)			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'f.ActionMade LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');

				# ProcessType (AUTO, MANUAL)			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'f.ProcessType LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
						
			END IF;
				
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
			#SELECT CONCAT('p_WHERE = ', p_WHERE);
		    
			SET p_SQL = '';	
			SET p_SQL = CONCAT(p_SQL,'SELECT');
			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(a.ServiceNo) AS ServiceNo,
							IFNULL_STRING_ONLY(a.RequestNo) AS RequestNo,
							IFNULL_STRING_ONLY(a.ReferenceNo) AS ReferenceNo,
							IFNULL_NUMERIC(a.IRIDNo) AS IRIDNo,
							IFNULL_STRING_ONLY(a.IRNo) AS IRNo,
							IFNULL_FORMAT_DATE_ONLY(a.ServiceDate) AS ServiceDate,
							IFNULL_FORMAT_DATE_ONLY(a.ServiceReqDate) AS ServiceReqDate,
							IFNULL_FORMAT_DATE_ONLY(b.IRDate) AS IRDate,
							IFNULL_FORMAT_DATE_ONLY(b.InstallationDate) AS InstallationDate,
							IFNULL_FORMAT_DATE_ONLY(f.FSRDate) AS FSRDate,							
							IFNULL_NUMERIC(a.ServiceStatus) AS ServiceStatus,							
							IFNULL_STRING_ONLY(a.ServiceStatusDescription) AS ServiceStatusDescription,
							IFNULL_STRING_ONLY(a.JobTypeStatusDescription) AS JobTypeStatusDescription,
							IFNULL_NUMERIC(a.FEID) AS FEID,
							funcGetDesc("Search", "Particular", a.FEID) AS FEName,
							IFNULL_NUMERIC(a.ClientID) AS ClientID,
							funcGetDesc("Search", "Particular", a.ClientID) AS ClientName,
							IFNULL_NUMERIC(a.MerchantID) AS MerchantID,
							funcGetDesc("Search", "Particular", a.MerchantID) AS MerchantName,						
							IFNULL_STRING_ONLY(b.TID) AS TID,
							IFNULL_STRING_ONLY(b.MID) AS MID,							
							IFNULL_NUMERIC(a.JobType) AS JobType,
							funcGetDesc("Search", "JobType Description", a.JobType) AS JobTypeDescription,
							funcGetDesc("Search", "Service JobType Description", a.JobType) AS ServiceJobTypeDescription,
							IFNULL_STRING_ONLY(f.ActionMade) AS ActionMade,
							IFNULL_NUMERIC(f.FSRNo) AS FSRNo,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.TerminalID)) AS TerminalSN,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.SIMID)) AS SIMSerialNo,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.ReplaceTerminalID)) AS ReplaceTerminalSN,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.ReplaceSIMID)) AS ReplaceSIMSN
							FROM 
							tblservicingdetail AS a
							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo
							LEFT JOIN tblfsrdetail AS f ON a.ServiceNo = f.ServiceNo
							LEFT JOIN tblparticular AS g ON a.MerchantID = g.ParticularID AND g.ParticularTypeID = 1
							LEFT JOIN tblparticular AS g1 ON a.FEID = g1.ParticularID AND g1.ParticularTypeID = 3');	

				# ParticularTypeID = 1 (Merchant)
				# ParticularTypeID = 3 (Field Engineer)
				
				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
		    
				IF (LENGTH(p_WHERE) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");
				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('After:p_SQL = ', p_SQL);	
				
				SET p_GROUPBY = '';
				#SET p_GROUPBY = 'l.IRNo, l.ActionMade';
				
				IF (LENGTH(p_GROUPBY) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');
					SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);
				END IF;
			
				SET p_ORDERBY = '';
				#SET p_ORDERBY = 'c3.Name ASC';

				#SET p_ORDERBY = 'b.TID, a.ServiceNo ASC';

				SET p_ORDERBY = 'a.ServiceNo, a.JobType DESC';
				
				IF (LENGTH(p_ORDERBY) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
					SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
				END IF;
				
				#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT(':p_SQL = ', p_SQL);
				
				#IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))
				
				IF (v_OffSetTo > 0)
				THEN	
					#SET v_OffSetTo = 3;
					/*
					SET v_OffSet = 0;
					
					IF (v_OffSetFrom = 1)
					THEN
						SET v_OffSet = 0;
					ELSE
						SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;
					END IF;
					*/
					
					SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');
					SET p_SQL = CONCAT(p_SQL, ' ', v_OffSetFrom, ",", v_OffSetTo);
				END IF;
				
				SET p_SQL = CONCAT(p_SQL, ';');
				
				#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT(':p_SQL = ', p_SQL);
				
				SET @QUERY = p_SQL;
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;	
				
		ELSEIF (p_SearchBy = 'Installation Request')
		THEN
				SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);				
				SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
				SET v_Status = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
				SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
				SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
				SET v_TypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);
				SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
				SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
				
				#SELECT (CONCAT("v_DateFrom=", v_DateFrom));
				#SELECT (CONCAT("v_DateTo=", v_DateTo));
				
				SET p_WHERE = '';
				IF (v_ClientID > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'f2.ParticularID = ');
					SET p_WHERE = CONCAT(p_WHERE, v_ClientID);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (v_IRIDNo > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRIDNo = ');
					SET p_WHERE = CONCAT(p_WHERE, v_IRIDNo);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (v_Status > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRStatus = ');
					SET p_WHERE = CONCAT(p_WHERE, v_Status);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)
				THEN					
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRDate', ' ', 'BETWEEN', ' ');
					SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
												
				if (v_TypeID > 0)
				THEN
					CALL spGetInfoDetail("Search", "Setup QueryString Info", v_TypeID, @p_outResult);
					SET v_QueryString = TRIM(SPLIT_STRING(@p_outResult, '|' ,3));
														
					IF (LENGTH(v_QueryString) > 0)
					then
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SET_UP LIKE ');
						SET p_WHERE = CONCAT(p_WHERE, "'%", v_QueryString, "%'");
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
					
					end if;
				END IF;
				
				IF (v_RegionType > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'f1.RegionType = ');
					SET p_WHERE = CONCAT(p_WHERE, v_RegionType);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (v_RegionID > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'f1.RegionID = ');
					SET p_WHERE = CONCAT(p_WHERE, v_RegionID);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
				
				SET p_SQL = '';	
				SET p_SQL = CONCAT(p_SQL,'SELECT');
				SET p_SQL = CONCAT(p_SQL, ' ', 'a.IRID,
								a.IRIDNo,
								a.IRNo,
								a.IRStatus,
								a.IRStatusDescription,
								f1.Name AS MerchantName,
								f1.Address,
								f1.Address2,
								f1.Address3,
								f1.Address4,
								f1.ContactPerson,
								f1.TelNo,
								f1.Mobile,
								f1.Email,								
								IFNULL_FORMAT_DATE(a.IRDate) AS IRDate,
								IFNULL_FORMAT_DATE(a.InstallationDate) AS InstallationDate,								
								IFNULL_FORMAT_DATE((SELECT MAX(xTable.ImportDateTime) FROM tblinstallationrequestmaster xTable WHERE xTable.IRID = a.IRID)) AS ImportDateTime,								
								IFNULL_FORMAT_DATE((SELECT MAX(xTable.ServiceDate) FROM tblservicingdetail xTable WHERE xTable.IRIDNo = a.IRIDNo)) AS ServiceDate,
								IFNULL_FORMAT_DATE((SELECT MAX(xTable.ServiceReqDate) FROM tblservicingdetail xTable WHERE xTable.IRIDNo = a.IRIDNo)) AS ServiceReqDate,								
								IFNULL_FORMAT_DATE((SELECT MAX(xTable.FSRDate) FROM tblfsrdetail xTable WHERE xTable.IRIDNo = a.IRIDNo AND xTable.ServiceNo > 0 AND xTable.FSRNo > 0)) AS FSRDate,
								IFNULL_FORMAT_DATE((SELECT MAX(xTable.ProcessedDateTime) FROM tblfsrdetail xTable WHERE xTable.IRIDNo = a.IRIDNo AND xTable.ServiceNo > 0 AND xTable.FSRNo > 0)) AS FSRCreatedDate,																																				
								a.TID,
								a.MID,
								f2.Name AS ClientName,
								a.SET_UP,
								a.OTHER_SPECIAL_INSTRUCTION,
								(SELECT
								b.Region
								FROM
								tblregiondetail a
								LEFT JOIN tblregion AS b ON a.RegionType = b.RegionID
								WHERE (a.RegionID = f1.RegionID)) AS Region,
								(SELECT
								a.Province
								FROM
								tblregiondetail a
								LEFT JOIN tblregion AS b ON a.RegionType = b.RegionID
								WHERE (a.RegionID = f1.RegionID)) AS Province,
								f1.RegionType,
								f1.RegionID
								FROM
								tblirdetail a
								INNER JOIN tblparticular AS f1 ON a.MerchantID = f1.ParticularID AND f1.ParticularTypeID = 1
								INNER JOIN tblparticular AS f2 ON a.ClientID = f2.ParticularID AND f2.ParticularTypeID = 2');	

					#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
					#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			    
					IF (LENGTH(p_WHERE) > 0)
					THEN
						SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
						SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
					END IF;

					SET p_SQL = REPLACE(p_SQL, '"', "'");
					#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
					#SELECT CONCAT('After:p_SQL = ', p_SQL);	
					
					SET p_GROUPBY = '';					
					
					IF (LENGTH(p_GROUPBY) > 0)
					THEN
						SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');
						SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);
					END IF;
				
					SET p_ORDERBY = '';
					SET p_ORDERBY = 'a.IRDate';
					
					IF (LENGTH(p_ORDERBY) > 0)
					THEN
						SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
						SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
					END IF;
					
					#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
					#SELECT CONCAT('After:p_SQL = ', p_SQL);
				
					SET p_SQL = REPLACE(p_SQL, '"', "'");
					
					#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
					#SELECT CONCAT('After:p_SQL = ', p_SQL);	
						
					SET @QUERY = p_SQL;
					# Execute Query 
					PREPARE QUERY FROM @QUERY;
					EXECUTE QUERY;
					
		ELSEIF (p_SearchBy = 'Multi-Merchant Info')
		THEN	
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT			
			a.MerchantID,
			a.IRIDNo,
			a.IRNo,
			a.TID,
			a.MID,
			a.IRStatus,
			funcGetDesc("Search", "Service Status", a.IRStatus) AS IRStatusDescription
			FROM
			tblirdetail a
			WHERE 
			(a.MerchantID = v_ID
			AND a.IRStatus != 11
			AND a.IRActive > 0) # Not PULLED-OUT
			ORDER BY IRIDNo;
			
		ELSEIF (p_SearchBy = 'Installation Request Summary')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);					
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);	
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
				
			SET p_WHERE = '';
					
			IF (v_RegionID > 0)
			THEN			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.RegionType = ');
				SET p_WHERE = CONCAT(p_WHERE, v_RegionID);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
			END IF;
			
			IF (v_JobType > 0)
			THEN			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobType = ');
				SET p_WHERE = CONCAT(p_WHERE, v_JobType);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
			END IF;
			
			IF (v_TerminalTypeID > 0)
			THEN			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalTypeID = ');
				SET p_WHERE = CONCAT(p_WHERE, v_TerminalTypeID);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
			END IF;
			
			IF (v_TerminalModelID > 0)
			THEN			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalModelID = ');
				SET p_WHERE = CONCAT(p_WHERE, v_TerminalModelID);
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
			END IF;
			
			# active region
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.isActive > 0 ');
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			
			# has total
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TTotal > 0 ');
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
											   
			SET p_SQL = '';	
			SET p_SQL = CONCAT(p_SQL,'SELECT');
			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.RegionType, 0) AS RegionType,							
							IFNULL(a.Region, "-") AS Region,
							IFNULL(a.RegionID, 0) AS RegionID,
							IFNULL(a.TerminalTypeID, "-") AS TerminalTypeID,
							IFNULL(a.TerminalType, "-") AS TerminalType,
							IFNULL(a.TerminalModelID, "-") AS TerminalModelID,
							IFNULL(a.TerminalModel, "-") AS TerminalModel,							
							IFNULL(a.JobType, "-") AS JobType,
							IFNULL(a.JobTypeDescription, "-") AS JobTypeDescription,							
							IFNULL(a.TSuccess, 0) AS TSuccess,
							IFNULL(a.TNegative, 0) AS TNegative,
							IFNULL(a.TTotal, 0) AS TTotal						
							FROM tblinstallationsummary a
							LEFT JOIN tblregion b ON a.RegionType = b.RegionID');
			
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
						
			IF (LENGTH(p_WHERE) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('After:p_SQL = ', p_SQL);
			
			SET p_GROUPBY = '';
			#SET p_GROUPBY = 'a.LocationID';

			IF (LENGTH(p_GROUPBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);
			END IF;
				
			SET p_ORDERBY = '';
			
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
			END IF;
			
			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final p_SQL = ', p_SQL);	

			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;	
			
		ELSEIF (p_SearchBy = 'POS Rental IR List')
		THEN	
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT	
			IFNULL_NUMERIC(a.IRIDNo) AS IRIDNo,
			IFNULL_STRING_ONLY(a.IRNo) AS IRNo,		
			IFNULL_NUMERIC(a.MerchantID) AS MerchantID,
			IFNULL_NUMERIC(a.ParticularID) AS ParticularID,
			IFNULL_STRING_ONLY(a.TID) AS TID,
			IFNULL_STRING_ONLY(a.MID) AS `MID`,
			IFNULL_STRING_ONLY((SELECT xTable.Description FROM tblpr_rentalfee xTable WHERE xTable.QueryString = a.POS_TYPE LIMIT 1)) as Description,
			IFNULL_DECIMAL((SELECT xTable.RentalFee FROM tblpr_rentalfee xTable WHERE xTable.QueryString = a.POS_TYPE LIMIT 1)) AS RentalFee
			FROM
			tblirdetail a
			WHERE (a.MerchantID = v_ID)
			ORDER BY IRIDNo;
				
		END IF;
	        
END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewAdvanceParticular` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewAdvanceParticular` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewAdvanceParticular`(  
    p_StatementType VARCHAR(30) /* = NULL */ ,
    p_SearchBy VARCHAR(50) /* = NULL */ ,
    p_SearchValue VARCHAR(255) /* = NULL */
    
)
BEGIN
DECLARE v_Count INTEGER;
DECLARE v_ID INTEGER;	
DECLARE v_ParticularID INT;
DECLARE v_ProvinceID INT;
DECLARE v_CityID INT;
DECLARE v_ParticularTypeID INT;
DECLARE v_isDashboard INT;
DECLARE v_ParticularDescription VARCHAR(45);
DECLARE v_ParticularName VARCHAR(45);
DECLARE v_isActive INT;
DECLARE v_isTimeSheet INT;
DECLARE v_DepartmentID INT;
DECLARE v_isUserOrHead INT;
DECLARE v_SearchString VARCHAR(45);

DECLARE v_OffSetFrom INTEGER;
DECLARE v_OffSetTo INTEGER;
DECLARE v_OffSet INTEGER;
	
DECLARE p_WHERE LONGTEXT;
DECLARE p_SQL LONGTEXT;
DECLARE p_ORDERBY LONGTEXT;
DECLARE p_GROUPBY LONGTEXT;
    
    IF (p_StatementType = 'View')
    THEN	
		IF (p_SearchBy = 'Advance Particular')
		THEN			
			# Split SearchValue
			#SELECT (CONCAT('p_SearchValue=', p_SearchValue));            
			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
