			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(xTable.IRIDNo) AS IRIDNo,

							IFNULL_NUMERIC(xTable.TAIDNo) AS TAIDNo,

							IFNULL_NUMERIC(xTable.ClientID) AS ClientID,

							IFNULL_NUMERIC(xTable.FEID) AS FEID,

							IFNULL_NUMERIC(xTable.ServiceProviderID) AS ServiceProviderID,

							IFNULL_NUMERIC(xTable.MerchantID) AS MerchantID,

							IFNULL_NUMERIC(xTable.RegionID) AS RegionID,

							IFNULL_NUMERIC(xTable.RegionType) AS RegionType,

							IFNULL_NUMERIC(xTable.ServiceNo) AS ServiceNo,

							IFNULL_STRING(xTable.RequestNo) AS RequestNo,

							IFNULL_STRING(xTable.ReferenceNo) AS ReferenceNo,							

							IFNULL_STRING(xTable.ServiceDateTime) AS ServiceDateTime,

							IFNULL_STRING(xTable.ServiceDate) AS ServiceDate,

							IFNULL_STRING(xTable.ServiceTime) AS ServiceTime,

							IFNULL_STRING(xTable.ServiceReqDate) AS ServiceReqDate,

							IFNULL_STRING(xTable.ServiceReqTime) AS ServiceReqTime,

							IFNULL_STRING(xTable.JobTypeDescription) AS JobTypeDescription,

							IFNULL_STRING(xTable.JobTypeStatusDescription) AS JobTypeStatusDescription,

							IFNULL_NUMERIC(xTable.ServiceStatus) AS ServiceStatus,

							IFNULL_STRING(xTable.ServiceStatusDescription) AS ServiceStatusDescription,

							IFNULL_STRING(xTable.IRNo) AS IRNo,

							IFNULL_STRING(xTable.MerchantName) AS MerchantName,

							IFNULL_STRING(xTable.TID) AS TID,

							IFNULL_STRING(xTable.`MID`) AS `MID`,

							IFNULL_NUMERIC(xTable.TerminalID) AS TerminalID,

							IFNULL_STRING(xTable.TerminalSN) AS TerminalSN,

							IFNULL_NUMERIC(xTable.SIMID) AS SIMID,

							IFNULL_STRING(xTable.SIMSN) AS SIMSerialNo,	

							IFNULL_NUMERIC(xTable.DockID) AS DockID,

							IFNULL_STRING(xTable.DockSN) AS DockSN,													

							IFNULL_STRING(xTable.PrimaryNum) AS PrimaryNum,

							IFNULL_STRING(xTable.SecondaryNum) AS SecondaryNum

							FROM

							(

							SELECT													

							a.IRIDNo,

							a.TAIDNo,

							a.ClientID,

							a.FEID,

							a.ServiceProviderID,

							a.MerchantID,

							a.RegionID,

							a.RegionType,

							c.ServiceNo,

							c.RequestNo,

							c.ReferenceNo,

							c.ServiceDateTime,

							c.ServiceDate,

							c.ServiceTime,

							c.ServiceReqDate,

							c.ServiceReqTime,

							c.JobTypeDescription,

							c.JobTypeStatusDescription,

							c.ServiceStatus,

							c.ServiceStatusDescription,

							b.IRNo,

							b.MerchantName,

							b.TID,

							b.`MID`,

							a.TerminalID,

							a.TerminalSN,

							a.SIMID AS SIMID,

							a.SIMSerialNo AS SIMSN,

							a.DockID AS DockID,

							a.DockSN AS DockSN,							

							(CONCAT(IFNULL_STRING(b.IRNo), "^", 

							IFNULL_STRING(c.RequestNo), "^",

							IFNULL_STRING(c.ReferenceNo), "^", 

							IFNULL_STRING(c.JobTypeDescription), "^", 

							IFNULL_STRING(c.JobTypeStatusDescription), "^", 

							IFNULL_STRING(b.MerchantName), "^", 

							IFNULL_STRING(b.TID), "^", 

							IFNULL_STRING(b.MID), "^", 

							IFNULL_STRING(a.TerminalSN), "^", 

							IFNULL_STRING(a.SIMSerialNo))) AS sFields,

							c.isPrimary,							

							b.PrimaryNum,

							b.SecondaryNum

							FROM

							tblterminalallocation a							

							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo

							LEFT JOIN tblservicingdetail AS c ON a.IRIDNo = c.IRIDNo AND a.TAIDNo = c.TAIDNo

							) AS xTable');

							

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

				

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;



			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			IF (v_OffSetTo > 0)

			THEN	

				SET v_OffSet = 0;

				

				IF (v_OffSetFrom <= 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;

				

				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;



			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

				

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;		



	END IF;    

  END IF;    	



END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewAdvanceTerminal` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewAdvanceTerminal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewAdvanceTerminal`(  

	p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(1000) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_TerminalID INT;

	DECLARE v_TerminalTypeID INT;

	DECLARE v_TerminalModelID INT;

	DECLARE v_TerminalBrandID INT;

	DECLARE v_TerminalSerialNo VARCHAR(45);	

	DECLARE v_TerminalType VARCHAR(1000);	

	DECLARE v_TerminalStatus INT;

	

	DECLARE v_SIMID INT;

	DECLARE v_SIMSerialNo VARCHAR(45);

	DECLARE v_SIMCarrier VARCHAR(45);	

	DECLARE v_SIMStatus INT;

	DECLARE v_Province VARCHAR(45);

	DECLARE v_Region VARCHAR(45);

	

	DECLARE v_LocationID INT;

	DECLARE v_Location VARCHAR(45);

	

	DECLARE v_OffSetFrom INTEGER;

	DECLARE v_OffSetTo INTEGER;

	DECLARE v_OffSet INTEGER;	

	DECLARE v_StockID INT;
	DECLARE v_ItemID INT;
	DECLARE v_StockStatus INT;
	DECLARE v_SerialNo VARCHAR(45);

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Advance Terminal')

		THEN

			# Split SearchValue

			#SELECT (CONCAT('p_SearchValue=', p_SearchValue));

			SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			

			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);

			SET v_TerminalBrandID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

			SET v_TerminalSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

			SET v_TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);

			#SELECT (CONCAT('v_TerminalID=', v_TerminalID));	

			#SELECT (CONCAT('v_TerminalTypeID=', v_TerminalTypeID));

			#SELECT (CONCAT('v_TerminalModelID=', v_TerminalModelID));

			#SELECT (CONCAT('v_TerminalBrandID=', v_TerminalBrandID));

			#SELECT (CONCAT('v_TerminalSerialNo=', v_TerminalSerialNo));

			#SELECT (CONCAT('v_TerminalStatus=', v_TerminalStatus));
			SET p_WHERE = '';            

			IF (v_TerminalID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

						

			IF (v_TerminalTypeID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalTypeID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalTypeID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (v_TerminalModelID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalModelID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalModelID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (v_TerminalBrandID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalBrandID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalBrandID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (STRCMP(v_TerminalSerialNo, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_TerminalSerialNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (v_TerminalStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TIID, 0) AS TIID,

							IFNULL(a.TerminalID, 0) AS TerminalID,

							IFNULL(a.TerminalTypeID, 0) AS TerminalTypeID,

							IFNULL(a.TerminalModelID, 0) AS TerminalModelID,

							IFNULL(a.TerminalBrandID, 0) AS TerminalBrandID,											

							IFNULL(a.`No`, "-") AS No,

							IFNULL(a.SerialNo, "-") AS SerialNo,

							IFNULL(a.`Type`, "-") AS Type,

							IFNULL(a.Model, "-") AS Model,

							IFNULL(a.Brand, "-") AS Brand,

							IFNULL(a.DeliveryDate, "-") AS DeliveryDate,

							IFNULL(a.ReceiveDate, "-") AS ReceiveDate,

							IFNULL(a.TerminalStatus, 0) AS TerminalStatus,	

							IFNULL(a.TerminalStatusDescription, "-") AS TerminalStatusDescription,

							IFNULL(a.PartNo, "-") AS PartNo,

							IFNULL(a.PONo, "-") AS PONo,

							IFNULL(a.InvNo, "-") AS InvNo,

							IFNULL(a.Remarks, "-") AS Remarks

							FROM tblterminaldetail AS a

							LEFT JOIN tblterminaltype AS b ON a.TerminalTypeID = b.TerminalTypeID

							LEFT JOIN tblterminalmodel AS c ON a.TerminalModelID = c.TerminalModelID

							LEFT JOIN tblterminalbrand AS d ON a.TerminalBrandID = d.TerminalBrandID');
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;
		ELSEIF (p_SearchBy = 'Advance SIM')

		THEN

			# Split SearchValue

			#SELECT (CONCAT('p_SearchValue=', p_SearchValue));

			SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);						

			SET v_SIMSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_SIMStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

			#SELECT (CONCAT('v_SIMID=', v_SIMID));				

			#SELECT (CONCAT('v_SIMSerialNo=', v_SIMSerialNo));

			#SELECT (CONCAT('v_SIMCarrier=', v_SIMCarrier));

			#SELECT (CONCAT('v_SIMStatus=', v_SIMStatus));	
			SET p_WHERE = '';            

			IF (v_SIMID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SIMID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	
			IF (STRCMP(v_SIMSerialNo, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMSerialNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (STRCMP(v_SIMCarrier, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Carrier = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMCarrier, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	
			IF (v_SIMStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SIMStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);	
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.SIMID, 0) AS SIMID,							

							IFNULL(a.SerialNo, "-") AS SerialNo,							

							IFNULL(a.Carrier, "-") AS Carrier,							

							IFNULL(a.SIMStatus, 0) AS SIMStatus

							FROM tblsimdetail AS a');
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;
		ELSEIF (p_SearchBy = 'TerminalSN List')

		THEN

			SET v_TerminalSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_TerminalType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);

			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
			#SELECT (CONCAT('v_TerminalSerialNo=', v_TerminalSerialNo));

			#SELECT (CONCAT('v_TerminalStatus=', v_TerminalStatus));

			#SELECT (CONCAT('v_TerminalType=', v_TerminalType));

			#SELECT (CONCAT('v_Location=', v_Location));	
			
			# debug
			#SELECT funcDebugSplitString(p_SearchValue, '|') AS DebugResult;
			
			SET p_WHERE = '';

			IF (LENGTH(v_TerminalSerialNo > 0) AND (STRCMP(v_TerminalSerialNo, "0") != 0))

			THEN								

				# TerminaID			

				SET p_WHERE = CONCAT(p_WHERE, ' ', '(', 'a.TerminalID = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_TerminalSerialNo, "'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# SN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# SN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalSN LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Type			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.Description LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# Model			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.Description LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# Brand			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.Description LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# Location			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Location LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# Status			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'g.Description LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# AssetType			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.AssetType LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalSerialNo, "%'", ')');	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
			END IF;
			IF (v_TerminalStatus > 0)

			THEN

				IF v_TerminalStatus = 99 THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalStatus != 7'); #Rocky -- Fix Do not Display Installed Status
				ELSE
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalStatus = ', v_TerminalStatus);
				END IF;

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (STRCMP(v_Location, "0") != 0 && STRCMP(v_Location, "[NOT SPECIFIED]") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Location = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_Location));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (LENGTH(v_TerminalType) > 0)

			THEN				

				IF (v_TerminalType = 'View Terminal')

				THEN

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.Description IN');

					SET p_WHERE = CONCAT(p_WHERE, ' ', "(", "'V3 TOUCH','V5S','MP200','ANDROID SE','V3 NT','V3000','ANDROID','V5000'",")");	

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				ELSEIF (v_TerminalType = 'View Dock')

				THEN

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.Description IN ');

					SET p_WHERE = CONCAT(p_WHERE, ' ', "(", "'V3 DOCK','V3 MOBILE BASE KIT','V5 BASE'",  ")");	

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;			

			END IF;				

			#SET p_WHERE = CONCAT(p_WHERE, ' ', 'NOT (h.TerminalID IS NOT NULL AND IFNULL_NUMERIC(a.TerminalStatus) = 1) AND');

			# check active

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

						

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(a.TerminalID) AS TerminalID,							

							IFNULL_STRING_ONLY(a.SerialNo) AS SerialNo,

							IFNULL_STRING_ONLY(a.`Type`) AS Type,

							IFNULL_STRING_ONLY(a.Model) AS Model,

							IFNULL_STRING_ONLY(a.Brand) AS Brand,

							CASE WHEN h.TerminalID IS NOT NULL AND IFNULL_NUMERIC(a.TerminalStatus) = 1 THEN 7 ELSE IFNULL_NUMERIC(a.TerminalStatus) END AS TerminalStatus,

							CASE WHEN h.TerminalID IS NOT NULL AND IFNULL_NUMERIC(a.TerminalStatus) = 1 THEN "INSTALLED" ELSE IFNULL_STRING_ONLY(a.TerminalStatusDescription) END AS TerminalStatusDescription,

							IFNULL_STRING_ONLY(f.`Name`) AS MerchantName,

							IFNULL_STRING_ONLY(e.TID) AS TID,

							IFNULL_STRING_ONLY(e.`MID`) AS `MID`,

							IFNULL_STRING_ONLY(e.IRNo) AS IRNo,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.ClientID)) AS ClientName,

							IFNULL_STRING_ONLY(a.Location) AS Location,

							IFNULL_STRING_ONLY(a.Allocation) AS Allocation,

							IFNULL_STRING_ONLY(a.AssetType) AS AssetType,

							IFNULL_STRING_ONLY(a.DeliveryDate) AS DeliveryDate,

							IFNULL_STRING_ONLY(a.ReceiveDate) AS ReceiveDate,

							IFNULL_STRING_ONLY(a.ReleaseDate) AS ReleaseDate

							FROM tblterminaldetail AS a

							LEFT JOIN tblterminaltype AS b ON a.TerminalTypeID = b.TerminalTypeID

							LEFT JOIN tblterminalmodel AS c ON a.TerminalModelID = c.TerminalModelID

							LEFT JOIN tblterminalbrand AS d ON a.TerminalBrandID = d.TerminalBrandID

							LEFT JOIN tblirdetail AS e ON a.LastIRIDNo = e.IRIDNo

							LEFT JOIN tblparticular AS f ON e.MerchantID = f.ParticularID AND f.ParticularTypeID = 1

							LEFT JOIN tblparticular AS f1 ON e.ClientID = f1.ParticularID AND f1.ParticularTypeID = 2

							LEFT JOIN tblterminalstatus AS g ON a.TerminalStatus = g.TerminalStatusType

							LEFT JOIN (SELECT DISTINCT TerminalID FROM tblirdetail WHERE IRActive > 0 AND TerminalID > 0) AS h ON a.TerminalID = h.TerminalID');
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.TerminalID ASC';
			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;
			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);
			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

			THEN	

				SET v_OffSet = 0;
				IF (v_OffSetFrom = 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;
				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;	
			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;
		ELSEIF (p_SearchBy = 'SIMSN List')

		THEN

			SET v_SIMSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_SIMStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);

			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			#SELECT (CONCAT('v_SIMSerialNo=', v_SIMSerialNo));	
			SET p_WHERE = '';

			IF (LENGTH(v_SIMSerialNo > 0) AND (STRCMP(v_SIMSerialNo, "0") != 0))

			THEN				
				# SIMID			
				SET p_WHERE = CONCAT(p_WHERE, ' ', '(', 'a.SIMID = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMSerialNo, "'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# SN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SIMSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# Carrier			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Carrier LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SIMSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# Status			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.Description LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SIMSerialNo, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				# Location			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Location LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SIMSerialNo, "%'", ')');	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;
			IF (v_SIMStatus > 0)

			THEN

				IF v_SIMStatus = 99 THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMStatus != 7'); #Rocky -- Fix Do not Display Installed Status
				ELSE
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMStatus = ', v_SIMStatus);
				END IF;

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			IF (STRCMP(v_Location, "0") != 0 && STRCMP(v_Location, "[NOT SPECIFIED]") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Location = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_Location));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			# SET p_WHERE = CONCAT(p_WHERE, ' ', 'NOT (h.SIMID IS NOT NULL AND IFNULL_NUMERIC(a.SIMStatus) = 1) AND');

			# check is active

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(a.SIMID) AS SIMID,							

							IFNULL_STRING_ONLY(a.SerialNo) AS SerialNo,

							IFNULL_STRING_ONLY(a.Carrier) AS Carrier,

							CASE WHEN h.SIMID IS NOT NULL AND IFNULL_NUMERIC(a.SIMStatus) = 1 THEN 7 ELSE IFNULL_NUMERIC(a.SIMStatus) END AS SIMStatus,

							CASE WHEN h.SIMID IS NOT NULL AND IFNULL_NUMERIC(a.SIMStatus) = 1 THEN "INSTALLED" ELSE IFNULL_STRING_ONLY(a.SIMStatusDescription) END AS SIMStatusDescription,

							IFNULL_STRING_ONLY(c.`Name`) AS MerchantName,

							IFNULL_STRING_ONLY(b.TID) AS TID,

							IFNULL_STRING_ONLY(b.`MID`) AS `MID`,

							IFNULL_STRING_ONLY(b.IRNo) AS IRNo,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.ClientID)) AS ClientName,

							IFNULL_STRING_ONLY(a.Location) AS Location,

							IFNULL_STRING_ONLY(a.Allocation) AS Allocation,

							IFNULL_STRING_ONLY(a.DeliveryDate) AS DeliveryDate,

							IFNULL_STRING_ONLY(a.ReceiveDate) AS ReceiveDate,

							IFNULL_STRING_ONLY(a.ReleaseDate) AS ReleaseDate

							FROM tblsimdetail AS a

							LEFT JOIN tblirdetail AS b ON a.LastIRIDNo = b.IRIDNo

							LEFT JOIN tblparticular AS c ON b.MerchantID = c.ParticularID AND c.ParticularTypeID = 1

							LEFT JOIN tblparticular AS c1 ON b.ClientID = c1.ParticularID AND c1.ParticularTypeID = 2

							LEFT JOIN tblterminalstatus AS d ON a.SIMStatus = d.TerminalStatusType

							LEFT JOIN (SELECT DISTINCT SIMID FROM tblirdetail WHERE IRActive > 0 AND SIMID > 0) AS h ON a.SIMID = h.SIMID');
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.SIMID ASC';
			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);
			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

			THEN	

				SET v_OffSet = 0;
				IF (v_OffSetFrom = 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;
				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;	
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;
		ELSEIF (p_SearchBy = 'Terminal Status Description')

		THEN

			SET v_TerminalSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));			
			SET p_WHERE = '';            

			IF (LENGTH(v_TerminalSerialNo) > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_TerminalSerialNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);	
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TerminalID, 0) AS TerminalID,

							IFNULL(a.TerminalStatusDescription, "-") AS TerminalStatusDescription

							FROM tblterminaldetail AS a');
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;
			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

	

		ELSEIF (p_SearchBy = 'SIM Status Description')

		THEN

			SET v_SIMSerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET p_WHERE = '';            

			IF (LENGTH(v_SIMSerialNo) > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMSerialNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);	
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.SIMID, 0) AS SIMID,

							IFNULL(a.SIMStatusDescription, "-") AS SIMStatusDescription

							FROM tblsimdetail AS a');
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;
			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Stock Detail List')
		THEN
			SET v_SerialNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_StockStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_TerminalType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);
			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));

			SET p_WHERE = '';

			IF (LENGTH(v_SerialNo > 0) AND (STRCMP(v_SerialNo, "0") != 0))

			THEN								

				# SN			
				SET p_WHERE = CONCAT(p_WHERE, ' ', '(', 'a.SerialNo LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SerialNo, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Type			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.Description LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SerialNo, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Model			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.Description LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SerialNo, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Brand			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.Description LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SerialNo, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Location			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'e.Description LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SerialNo, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# Status			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'g.Description LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SerialNo, "%'");	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');
				
				# AssetType			
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.AssetType LIKE ');
				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SerialNo, "%'", ')');	
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
				
			END IF;
			
			IF (v_StockStatus > 0)

			THEN

				IF v_StockStatus = 99 THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.StockStatus != 7'); #Rocky -- Fix Do not Display Installed Status
				ELSE
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.StockStatus = ', v_StockStatus);
				END IF;

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
			
			IF (v_LocationID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.LocationID = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_LocationID));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;
					
			# check active
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 ');
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(a.ItemID) AS TerminalID,							

							IFNULL_STRING_ONLY(a.SerialNo) AS SerialNo,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Type", a.TerminalTypeID)) AS Type,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Model", a.TerminalModelID)) AS Model,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Brand", a.TerminalBrandID)) AS Brand,

							IFNULL_NUMERIC(a.StockStatus) AS TerminalStatus,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Status", a.StockStatus)) AS TerminalStatusDescription,

							"-" AS MerchantName,

							"-" AS TID,

							"-" AS `MID`,

							"-" AS IRNo,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.ClientID)) AS ClientName,

							IFNULL_STRING_ONLY(funcGetDesc("Search", "Location", a.LocationID)) AS Location,

							IFNULL_STRING_ONLY(a.Allocation) AS Allocation,

							IFNULL_STRING_ONLY(a.AssetType) AS AssetType,

							IFNULL_STRING_ONLY(a.DeliveryDate) AS DeliveryDate,

							IFNULL_STRING_ONLY(a.ReceiveDate) AS ReceiveDate,

							IFNULL_STRING_ONLY(a.ReleaseDate) AS ReleaseDate

							FROM tblstockdetail AS a

							LEFT JOIN tblterminaltype AS b ON a.TerminalTypeID = b.TerminalTypeID

							LEFT JOIN tblterminalmodel AS c ON a.TerminalModelID = c.TerminalModelID

							LEFT JOIN tblterminalbrand AS d ON a.TerminalBrandID = d.TerminalBrandID
							
							LEFT JOIN tbllocation AS e ON a.LocationID = e.LocationID

							LEFT JOIN tblterminalstatus AS g ON a.StockStatus = g.TerminalStatusType');
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);	
			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.ItemID ASC';
			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;
			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);
			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

			THEN	

				SET v_OffSet = 0;
				IF (v_OffSetFrom = 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;
				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;	
			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);
			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

							

		ELSE

			SELECT TIID, TerminalID, TerminalTypeID, TerminalModelID, TerminalBrandID, NO, SerialNo, TYPE, Model, Brand, DeliveryDate, ReceiveDate, TerminalStatus, TerminalStatusDescription

			FROM   tblterminaldetail

			ORDER BY TerminalID;

		END IF;

         

     END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewCity` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewCity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewCity`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT CityID, City

		FROM   tblcity

		ORDER BY City;

    ELSEIF (p_StatementType = 'Search')

    THEN				

		IF (p_SearchBy = 'City')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						CityID,

						City

			FROM        tblcity

			WHERE       (City LIKE p_SearchValue);

            

		ELSEIF (p_SearchBy = 'CityID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						CityID,

						City

			FROM        tblcity

			WHERE       (CityID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewClient` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewClient` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewClient`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'ForDashboard')

		THEN

			SELECT 

			IFNULL(a.ParticularID, 0) AS ParticularID, 

			IFNULL(a.`Name`, "-") AS `Name`, 

			IFNULL(a.TAvailable, 0) AS TAvailable,

			IFNULL(a.TAllocated, 0) AS TAllocated,

			IFNULL(a.TDispatch, 0) AS TDispatch,

			IFNULL(a.TInstalled, 0) AS TInstalled,

			IFNULL(a.TNegative, 0) AS TNegative,

			IFNULL(a.TLastMonthInstalled, 0) AS TInstalledLastMonth,

			IFNULL(a.TThisMonthInstalled, 0) AS TInstalledThisMonth

			FROM

			tbldashboardclient a						

			ORDER BY a.`Name`;

			

		ELSE

			SELECT ClientID, NAME, Address, CityID, City,  ContactPerson, ContactNo

			FROM   tblclient

			ORDER BY NAME;

		END IF;	

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Name')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						ClientID,

						NAME, 

                        Address, 

                        CityID,

                        City,  

                        ContactPerson, 

                        ContactNo

			FROM        tblclient

			WHERE       (NAME LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'ClientID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						ClientID,

						NAME, 

                        Address, 

                        CityID,

                        City,  

                        ContactPerson, 

                        ContactNo

			FROM        tblclient

			WHERE       (ClientID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewCount` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewCount` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewCount`(  
    IN p_StatementType VARCHAR(30) /* = NULL */ ,
    IN p_SearchBy VARCHAR(255) /* = NULL */ ,
    IN p_SearchValue VARCHAR(255) /* = NULL */ ,
    OUT p_outCount INTEGER
)
BEGIN

DECLARE v_Count INT;
DECLARE v_SubCount INT;
DECLARE v_TCount INT;
DECLARE v_ID INT;
DECLARE v_TerminalTypeID INT;
DECLARE v_TerminalModelID INT;
DECLARE v_TerminalBrandID INT;
DECLARE v_TerminalStatus INT;
DECLARE v_TerminalStatusDescription VARCHAR(45);
DECLARE v_ModelDescription VARCHAR(45);
DECLARE v_ClientID INT;
DECLARE v_ClientName VARCHAR(45);
DECLARE v_ClientIDList VARCHAR(45);
DECLARE v_ServiceStatus INT;
DECLARE v_ServiceStatusDescription VARCHAR(45);
DECLARE v_TID VARCHAR(45);
DECLARE v_MID VARCHAR(45);
DECLARE v_TerminalSN VARCHAR(45);
DECLARE v_RegionID INT;
DECLARE v_RegionType INT;
DECLARE v_ServiceTypeStatus INT;
DECLARE v_Region VARCHAR(45);
DECLARE v_ServiceTypeStatusDescription VARCHAR(45);
DECLARE v_TAIDNo INT;
DECLARE v_JobType INTEGER;
DECLARE v_JobTypeDescription VARCHAR(500);
DECLARE v_JobTypeStatusDescription VARCHAR(500);
DECLARE v_isClose INT;
DECLARE v_isOverDue INT;
DECLARE v_ActionMade VARCHAR(45);
DECLARE v_DateFrom VARCHAR(45);
DECLARE v_DateTo VARCHAR(45);
DECLARE v_MerchantID INTEGER;
DECLARE v_IRIDNo INTEGER;
DECLARE v_TerminalID INTEGER;
DECLARE v_SIMID INTEGER;
DECLARE v_FEID INTEGER;
DECLARE v_TerminalSerialNo VARCHAR(45);
DECLARE v_SIMSerialNo VARCHAR(45);
DECLARE v_SIMStatus INT;
DECLARE v_TerminalType VARCHAR(1000);	
DECLARE v_ParticularTypeID INT;
DECLARE v_isDashboard INT;
DECLARE v_ParticularName VARCHAR(45);
DECLARE v_Province VARCHAR(45);
DECLARE v_ServiceTypeID INT;
DECLARE v_ParticularID INT;
DECLARE v_IRStatus INT;
DECLARE v_IRNo VARCHAR(45);
DECLARE v_ReqDateFrom VARCHAR(45);
DECLARE v_ReqDateTo VARCHAR(45);
DECLARE v_InstDateFrom VARCHAR(45);
DECLARE v_InstDateTo VARCHAR(45);
DECLARE v_TADateFrom VARCHAR(45);
DECLARE v_TADateTo VARCHAR(45);
DECLARE v_FSRDateFrom VARCHAR(45);
DECLARE v_FSRDateTo VARCHAR(45);
DECLARE v_IRImportDateFrom VARCHAR(45);
DECLARE v_IRImportDateTo VARCHAR(45);
DECLARE v_MerchantName VARCHAR(45);
DECLARE v_SearchString VARCHAR(45);
DECLARE v_SIMCarrier VARCHAR(45);
DECLARE v_UserID INTEGER;
DECLARE v_UserType VARCHAR(45);
DECLARE v_LogDateFrom VARCHAR(45);
DECLARE v_LogDateTo VARCHAR(45);
DECLARE v_SessionStatus INTEGER;
DECLARE v_NoOfDayPending INT;
DECLARE v_SystemDate VARCHAR(45);
DECLARE v_SearchQuery VARCHAR(200);
DECLARE v_LeaveTypeID INT;
DECLARE v_isPrimary INT;
DECLARE v_Location VARCHAR(45);
DECLARE v_Status INT;
DECLARE v_Attempt INT;

DECLARE p_WHERE LONGTEXT;
DECLARE p_ORDERBY LONGTEXT;
DECLARE p_GROUPBY LONGTEXT;
DECLARE p_SQL LONGTEXT;
DECLARE p_TempQuery LONGTEXT;
DECLARE p_INSERT LONGTEXT;
    
SET v_Count = 0;
SET v_SystemDate = CURDATE();

IF (p_StatementType = 'Search')
THEN
	IF (p_SearchBy = 'Total')
	THEN
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_TerminalStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
						
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblterminaldetail a
			LEFT JOIN tblterminalmodel AS b ON a.TerminalModelID = b.TerminalModelID
			WHERE a.TerminalTypeID = v_TerminalTypeID AND a.TerminalModelID = v_TerminalModelID AND a.TerminalStatus = v_TerminalStatus			
			GROUP BY a.TerminalModelID
			ORDER BY b.Description;
										
	ELSEIF (p_SearchBy = 'Grand Total')
	THEN
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);						
						
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblterminaldetail a
			LEFT JOIN tblterminalmodel AS b ON a.TerminalModelID = b.TerminalModelID
			WHERE a.TerminalTypeID = v_TerminalTypeID AND a.TerminalModelID = v_TerminalModelID
			GROUP BY a.TerminalModelID;
			
	ELSEIF (p_SearchBy = 'IR Total')
	THEN
	
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_TCount
			FROM tblirdetail
			WHERE ClientName = v_ClientName;					
			
			#SELECT IFNULL(COUNT(*), 0) INTO v_SubCount
			#FROM tblirdetail
			#WHERE IRStatus = 2 AND IRStatusDescription = 'ALLOCATED' AND ClientName = v_ClientName;
			
			#SET v_Count = v_TCount - v_SubCount;
			SET v_Count = v_TCount;
			
			#SELECT CONCAT("v_TCount=",v_TCount);
			#SELECT CONCAT("v_SubCount=",v_SubCount);
			#SELECT CONCAT("v_Count=",v_Count);
			
	ELSEIF (p_SearchBy = 'IR Remaining')
	THEN	
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_TCount
			FROM tblirdetail
			WHERE ClientName = v_ClientName;					
			
			SELECT IFNULL(COUNT(*), 0) INTO v_SubCount
			FROM tblirdetail
			WHERE (IRStatus = 2 AND IRStatusDescription = 'ALLOCATED' OR 
			       IRStatus = 8 AND IRStatusDescription = 'DISPATCH' OR
			       IRStatus = 1 AND IRStatusDescription = 'INSTALLED') 
			       AND 
			       ClientName = v_ClientName;
			
			SET v_Count = v_TCount - v_SubCount;			
			
			#SELECT CONCAT("v_TCount=",v_TCount);
			#SELECT CONCAT("v_SubCount=",v_SubCount);
			#SELECT CONCAT("v_Count=",v_Count);
					
	ELSEIF (p_SearchBy = 'TA Region Total')
	THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_SubCount
			FROM tblirdetail
			WHERE IRStatus = 1 AND ClientName = v_ClientName;					
			
			SELECT IFNULL(COUNT(*), 0) INTO v_TCount
			FROM tblirdetail
			WHERE ClientName = v_ClientName;
			
			SET v_Count = v_TCount - v_SubCount;
												
		
	ELSEIF (p_SearchBy = 'FSR Attempt Count Negative')
	THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER); #NEGATIVE
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)); #NEGATIVE
			
			SELECT IFNULL(COUNT(*), 0) INTO v_TCount
			FROM tblfsrdetail			
			WHERE ClientName = v_ClientName AND ServiceStatusDescription = 'NEGATIVE';
			
			SET v_Count = v_TCount;
	
	ELSEIF (p_SearchBy = 'FSR Service Count')
	THEN			
			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_TCount
			FROM tblfsrdetail
			WHERE TID = v_TID AND
			      `MID` = v_MID AND
			      TerminalSN = v_TerminalSN;			
			
			SET v_Count = v_TCount;
			
	ELSEIF (p_SearchBy = 'Service Call Count')
	THEN			
			SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT IFNULL(COUNT(*), 0) INTO v_TCount
			FROM tblservicecalldetail
			WHERE TAIDNo = v_TAIDNo;			
			
			IF (v_TCount > 0)
			THEN
				SET v_Count = v_TCount + 1;
			ELSE
				SET v_Count = 1;
			END IF;
			
	ELSEIF (p_SearchBy = 'Servicing Detail Count')
	THEN			
			SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT IFNULL(COUNT(*), 0) INTO v_TCount
			FROM tblservicingdetail
			WHERE TAIDNo = v_TAIDNo;			
			
			IF (v_TCount > 0)
			THEN
				SET v_Count = v_TCount + 1;
			ELSE
				SET v_Count = 1;
			END IF;			
			
	ELSEIF (p_SearchBy = 'Region Status Count')
	THEN			
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ServiceTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			#SELECT (CONCAT("Region:v_RegionType=", v_RegionType, ":v_ServiceTypeStatusDescription=", v_ServiceTypeStatusDescription, ":v_ClientName=", v_ClientName)) as sDump;
			
			IF (v_ServiceTypeStatusDescription = 'INSTALLED')
			THEN
				# Get ClientID
				CALL spGetID('Search', 'ClientID', v_ClientName, @p_outID);
				SELECT @p_outID INTO v_ClientID;
				
				#SELECT CONCAT("Final::v_Count=", v_Count);
								
				SELECT SUM(src_table2.total_count) INTO v_Count
				FROM 
				(SELECT SUM(x1+x2+x3) AS total_count
				FROM
					(SELECT IRIDNo, TAIDNo, ServiceNo, MerchantName, TerminalSN, JobTypeDescription, 
										    IF(JobTypeDescription='SVC REQ INSTALLATION' AND ActionMade = 'SUCCESS',1,0) AS x1, 
										    IF(JobTypeDescription='SVC REQ PULL-OUT' AND ActionMade = 'SUCCESS',0,0) AS x2,
										    IF(JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(ReplaceTerminalSN, '-')) > 2 AND 
										    (TerminalSN = ReplaceTerminalSN) 
										    AND ActionMade = 'SUCCESS',0, 0)  AS x3
					FROM 
					tblservicingdetail
					WHERE RegionType = v_RegionType AND ClientID IN (v_ClientID)
				) 
				AS src_table1
				GROUP BY TerminalSN) AS src_table2;
				
				#SELECT CONCAT("Final::v_Count=", v_Count);
			ELSE
						
				SET p_WHERE = '';
				IF (v_RegionType > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.RegionID = ');
					SET p_WHERE = CONCAT(p_WHERE, v_RegionType);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;

				IF (STRCMP(v_ServiceTypeStatusDescription, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRStatusDescription = ');
					SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceTypeStatusDescription, "'");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (STRCMP(v_ClientName, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ClientName IN ');
					SET p_WHERE = CONCAT(p_WHERE, "(", v_ClientName, ")");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;	

				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
				#SELECT CONCAT('p_WHERE = ', p_WHERE);
				
				SET p_SQL = '';	
				SET p_SQL = CONCAT(p_SQL,'SELECT');
				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(COUNT(*), 0) AS v_Count
								FROM tblirdetail a				
								LEFT JOIN tblparticular AS b ON a.MerchantID = b.ParticularID					
								LEFT JOIN tblregion AS c ON b.Region = c.Region');	

				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
		    
				IF (LENGTH(p_WHERE) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");
				
				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('After:p_SQL = ', p_SQL);
				
				DROP TEMPORARY TABLE IF EXISTS tbltempcountregion;
				
				SET p_TempQuery = '';
				SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltempcountregion (xCount VARCHAR(45) NOT NULL)');
				SET @QUERY = p_TempQuery;
				
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;
				
				SET p_INSERT = '';
				SET p_INSERT = 'INSERT INTO tbltempcountregion (xCount)';
				SET @QUERY = '';	
				SET @QUERY = CONCAT(p_INSERT, p_SQL);
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;

				SELECT xCount INTO v_Count 
				FROM tbltempcountregion;
				
				#SELECT CONCAT("Final::v_Count=", v_Count);
			END IF;	
			
	ELSEIF (p_SearchBy = 'Region Last Month Count')	
	THEN
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			
			SET v_ServiceTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			IF (v_ServiceTypeStatusDescription = 'INSTALLED')
			THEN
				# Get ClientID
				CALL spGetID('Search', 'ClientID', v_ClientName, @p_outID);
				SELECT @p_outID INTO v_ClientID;

				SELECT IFNULL(SUM(src_table2.total_count), 0) INTO v_Count
				FROM 
				(SELECT SUM(x1+x2+x3) AS total_count
				FROM
					(SELECT a.IRIDNo, a.TAIDNo, a.ServiceNo, a.MerchantName, a.TerminalSN, a.JobTypeDescription, 
										    IF(a.JobTypeDescription='SVC REQ INSTALLATION' AND a.ActionMade = 'SUCCESS',1,0) AS x1, 
										    IF(a.JobTypeDescription='SVC REQ PULL-OUT' AND a.ActionMade = 'SUCCESS',0,0) AS x2,
										    IF(a.JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(a.ReplaceTerminalSN, '-')) > 2 AND 
										    (a.TerminalSN = a.ReplaceTerminalSN) 
										    AND a.ActionMade = 'SUCCESS',0, 0)  AS x3
					FROM 
					tblservicingdetail a
					LEFT JOIN tblfsrdetail AS b ON a.ServiceNo = b.ServiceNo
					WHERE (a.ClientID = v_ClientID) AND (a.RegionType = v_RegionType) AND (LEFT(b.FSRDate, 7) = LEFT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), 7))
				) 
				AS src_table1
				GROUP BY TerminalSN) AS src_table2;
			ELSE			
				SET p_WHERE = '';
				IF (v_RegionType > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.RegionID = ');
					SET p_WHERE = CONCAT(p_WHERE, v_RegionType);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;

				IF (STRCMP(v_ServiceTypeStatusDescription, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatusDescription = ');
					SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceTypeStatusDescription, "'");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (STRCMP(v_ClientName, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.ClientName IN ');
					SET p_WHERE = CONCAT(p_WHERE, "(", v_ClientName, ")");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				# Date
				SET p_WHERE = CONCAT(p_WHERE, ' ', '(LEFT(a.FSRDate, 7) = LEFT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), 7)) ');
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
				#SELECT CONCAT('p_WHERE = ', p_WHERE);
				
				SET p_SQL = '';	
				SET p_SQL = CONCAT(p_SQL,'SELECT');
				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(COUNT(*), 0) AS v_Count
								FROM tblfsrdetail a
								LEFT JOIN tblterminalallocation AS b ON a.TAIDNo = b.TAIDNo
								LEFT JOIN tblregion AS c ON b.Region = c.Region
								LEFT JOIN tblirdetail AS d ON b.IRID = d.IRIDNo');	

				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
		    
				IF (LENGTH(p_WHERE) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");
				
				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('After:p_SQL = ', p_SQL);
				
				DROP TEMPORARY TABLE IF EXISTS tbltempcountregion;
				
				SET p_TempQuery = '';
				SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltempcountregion (xCount VARCHAR(45) NOT NULL)');
				SET @QUERY = p_TempQuery;
				
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;
				
				SET p_INSERT = '';
				SET p_INSERT = 'INSERT INTO tbltempcountregion (xCount)';
				SET @QUERY = '';	
				SET @QUERY = CONCAT(p_INSERT, p_SQL);
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;

				SELECT xCount INTO v_Count 
				FROM tbltempcountregion;
			END IF;	
			
	ELSEIF (p_SearchBy = 'Region This Month Count')	
	THEN	
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			
			SET v_ServiceTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			IF (v_ServiceTypeStatusDescription = 'INSTALLED')
			THEN
				# Get ClientID
				CALL spGetID('Search', 'ClientID', v_ClientName, @p_outID);
				SELECT @p_outID INTO v_ClientID;

				SELECT IFNULL(SUM(src_table2.total_count), 0) INTO v_Count
				FROM 
				(SELECT SUM(x1+x2+x3) AS total_count
				FROM
					(SELECT a.IRIDNo, a.TAIDNo, a.ServiceNo, a.MerchantName, a.TerminalSN, a.JobTypeDescription, 
										    IF(a.JobTypeDescription='SVC REQ INSTALLATION' AND a.ActionMade = 'SUCCESS',1,0) AS x1, 
										    IF(a.JobTypeDescription='SVC REQ PULL-OUT' AND a.ActionMade = 'SUCCESS',0,0) AS x2,
										    IF(a.JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(a.ReplaceTerminalSN, '-')) > 2 AND 
										    (a.TerminalSN = a.ReplaceTerminalSN) 
										    AND a.ActionMade = 'SUCCESS',0, 0)  AS x3
					FROM 
					tblservicingdetail a
					LEFT JOIN tblfsrdetail AS b ON a.ServiceNo = b.ServiceNo
					WHERE (a.ClientID = v_ClientID) AND (a.RegionType = v_RegionType) AND (LEFT(b.FSRDate, 7) = LEFT(CURDATE(), 7))
				) 
				AS src_table1
				GROUP BY TerminalSN) AS src_table2;
			ELSE						
				SET p_WHERE = '';
				IF (v_RegionType > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.RegionID = ');
					SET p_WHERE = CONCAT(p_WHERE, v_RegionType);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;

				IF (STRCMP(v_ServiceTypeStatusDescription, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatusDescription = ');
					SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceTypeStatusDescription, "'");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (STRCMP(v_ClientName, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'd.ClientName IN ');
					SET p_WHERE = CONCAT(p_WHERE, "(", v_ClientName, ")");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				# Date
				SET p_WHERE = CONCAT(p_WHERE, ' ', '(LEFT(a.FSRDate, 7) = LEFT(CURDATE(), 7)) ');
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
				#SELECT CONCAT('p_WHERE = ', p_WHERE);
				
				SET p_SQL = '';	
				SET p_SQL = CONCAT(p_SQL,'SELECT');
				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(COUNT(*), 0) AS v_Count
								FROM tblfsrdetail a
								LEFT JOIN tblterminalallocation AS b ON a.TAIDNo = b.TAIDNo
								LEFT JOIN tblregion AS c ON b.Region = c.Region
								LEFT JOIN tblirdetail AS d ON b.IRID = d.IRIDNo');	

				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
		    
				IF (LENGTH(p_WHERE) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");
				
				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('After:p_SQL = ', p_SQL);
				
				DROP TEMPORARY TABLE IF EXISTS tbltempcountregion;
				
				SET p_TempQuery = '';
				SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltempcountregion (xCount VARCHAR(45) NOT NULL)');
				SET @QUERY = p_TempQuery;
				
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;
				
				SET p_INSERT = '';
				SET p_INSERT = 'INSERT INTO tbltempcountregion (xCount)';
				SET @QUERY = '';	
				SET @QUERY = CONCAT(p_INSERT, p_SQL);
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;

				SELECT xCount INTO v_Count 
				FROM tbltempcountregion;
			END IF;	
			
	ELSEIF (p_SearchBy = 'TypeAndModel Original Stock Count')
	THEN
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ModelDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
						
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblterminaldetail a
			LEFT JOIN tblterminalmodel AS b ON a.TerminalModelID = b.TerminalModelID
			WHERE a.TerminalTypeID = v_TerminalTypeID AND b.Description = v_ModelDescription
			GROUP BY a.TerminalModelID;	
			
	ELSEIF (p_SearchBy = 'TypeAndModel Status Count')
	THEN
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ModelDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_TerminalStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			#SELECT CONCAT("ClientName=", v_ClientName);
			
			IF (v_TerminalStatusDescription = 'INSTALLED')
			THEN
				# Get TerminalModelID
				CALL spGetID('Search', 'TerminalModelID', CONCAT("'", v_ModelDescription, "'"), @p_outID);
				SELECT @p_outID INTO v_TerminalModelID;
				
				# Get ClientID
				CALL spGetID('Search', 'ClientID', v_ClientName, @p_outID);
				SELECT @p_outID INTO v_ClientID;
				
				#SELECT CONCAT("Final::v_Count=", v_Count);
								
				SELECT SUM(src_table2.total_count) INTO v_Count
				FROM 
				(SELECT SUM(x1+x2+x3) AS total_count
				FROM
					(SELECT a.IRIDNo, a.TAIDNo, a.ServiceNo, a.MerchantName, a.TerminalSN, a.JobTypeDescription, 
										    IF(a.JobTypeDescription='SVC REQ INSTALLATION' AND a.ActionMade = 'SUCCESS',1,0) AS x1, 
										    IF(a.JobTypeDescription='SVC REQ PULL-OUT' AND a.ActionMade = 'SUCCESS',0,0) AS x2,
										    IF(a.JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(a.ReplaceTerminalSN, '-')) > 2 AND 
										    (a.TerminalSN = a.ReplaceTerminalSN) 
										    AND a.ActionMade = 'SUCCESS',0, 0)  AS x3
					FROM 
					tblservicingdetail a
					LEFT JOIN tblterminaldetail AS b ON a.TerminalID = b.TerminalID
					WHERE b.TerminalTypeID = v_TerminalTypeID AND b.TerminalModelID = v_TerminalModelID AND a.ClientID = v_ClientID
				) 
				AS src_table1
				GROUP BY TerminalSN) AS src_table2;
				
				#SELECT CONCAT("Final::v_Count=", v_Count);
			ELSE			
			
				SET p_WHERE = '';
				IF (v_TerminalTypeID > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.TerminalTypeID = ');
					SET p_WHERE = CONCAT(p_WHERE, v_TerminalTypeID);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;

				IF (STRCMP(v_ModelDescription, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.Description = ');
					SET p_WHERE = CONCAT(p_WHERE, "'", v_ModelDescription, "'");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (STRCMP(v_TerminalStatusDescription, "0") != 0)
				THEN
					
					IF (v_TerminalStatusDescription = 'INSTALLED')
					THEN
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatusDescription = ');
						SET p_WHERE = CONCAT(p_WHERE, "'", v_TerminalStatusDescription, "'");
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
						
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ActionMade = ');
						SET p_WHERE = CONCAT(p_WHERE, "'", 'SUCCESS', "'");
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
					ELSE
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatusDescription = ');
						SET p_WHERE = CONCAT(p_WHERE, "'", v_TerminalStatusDescription, "'");
						SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');								
					END IF;	
					
				END IF;
				
				IF (STRCMP(v_ClientName, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ClientName IN ');
					SET p_WHERE = CONCAT(p_WHERE, "(", v_ClientName, ")");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
				#SELECT CONCAT('p_WHERE = ', p_WHERE);
								
				SET p_SQL = CONCAT('SELECT COUNT(src_table.v_TempCount) AS v_Count');
				SET p_SQL = CONCAT(p_SQL, ' ', 'FROM');
				SET p_SQL = CONCAT(p_SQL, ' ', '(SELECT IFNULL(a.ServiceNo, 0) AS v_TempCount');
				SET p_SQL = CONCAT(p_SQL, ' ', 'FROM tblservicingdetail a');
				SET p_SQL = CONCAT(p_SQL, ' ', 'LEFT JOIN tblterminaldetail AS b ON a.TerminalID = b.TerminalID');
				SET p_SQL = CONCAT(p_SQL, ' ', 'LEFT JOIN tblterminalmodel AS c ON b.TerminalModelID = c.TerminalModelID');			
				
				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
		    
				IF (LENGTH(p_WHERE) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");
				
				SET p_GROUPBY = '';
				SET p_GROUPBY = 'a.TerminalID, a.ServiceNo';

				IF (LENGTH(p_GROUPBY) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');
					SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);
				END IF;
				
				SET p_SQL = CONCAT(p_SQL, ')', 'AS src_table');
				SET p_SQL = CONCAT(p_SQL, ';');
					
				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('After:p_SQL = ', p_SQL);
				
				DROP TEMPORARY TABLE IF EXISTS tbltempcountterminal;
				
				SET p_TempQuery = '';
				SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltempcountterminal (xCount VARCHAR(45) NOT NULL)');
				SET @QUERY = p_TempQuery;
				
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;
				
				SET p_INSERT = '';
				SET p_INSERT = 'INSERT INTO tbltempcountterminal (xCount)';
				SET @QUERY = '';	
				SET @QUERY = CONCAT(p_INSERT, p_SQL);
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;

				SELECT xCount INTO v_Count 
				FROM tbltempcountterminal;
				
				#SELECT (CONCAT("v_Count=", v_Count));
			END IF;		
																				
	ELSEIF (p_SearchBy = 'TypeAndModel Last Month Count' || p_SearchBy = 'TypeAndModel This Month Count')
	THEN	
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ModelDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_ClientName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			IF (v_ServiceStatusDescription = 'INSTALLED')
			THEN
				# Get TerminalModelID
				CALL spGetID('Search', 'TerminalModelID', CONCAT("'", v_ModelDescription, "'"), @p_outID);
				SELECT @p_outID INTO v_TerminalModelID;

				# Get ClientID
				CALL spGetID('Search', 'ClientID', v_ClientName, @p_outID);
				SELECT @p_outID INTO v_ClientID;
					
				IF (p_SearchBy = 'TypeAndModel Last Month Count')
				THEN																					
					SELECT SUM(src_table2.total_count) INTO v_Count
					FROM 
					(SELECT SUM(x1+x2+x3) AS total_count
					FROM
						(SELECT a.IRIDNo, a.TAIDNo, a.ServiceNo, a.MerchantName, a.TerminalSN, a.JobTypeDescription, 
											    IF(a.JobTypeDescription='SVC REQ INSTALLATION' AND a.ActionMade = 'SUCCESS',1,0) AS x1, 
											    IF(a.JobTypeDescription='SVC REQ PULL-OUT' AND a.ActionMade = 'SUCCESS',0,0) AS x2,
											    IF(a.JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(a.ReplaceTerminalSN, '-')) > 2 AND 
											    (a.TerminalSN = a.ReplaceTerminalSN) 
											    AND a.ActionMade = 'SUCCESS',0, 0)  AS x3
						FROM 
						tblservicingdetail a
						LEFT JOIN tblterminaldetail AS b ON a.TerminalID = b.TerminalID
						LEFT JOIN tblfsrdetail AS c ON a.ServiceNo = c.ServiceNo
						WHERE b.TerminalTypeID = v_TerminalTypeID AND 
							b.TerminalModelID = v_TerminalModelID AND 
							a.ClientID = v_ClientID AND (LEFT(c.FSRDate, 7) = LEFT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), 7))
					) 
					AS src_table1
					GROUP BY TerminalSN) AS src_table2;
				END IF;
				
				IF (p_SearchBy = 'TypeAndModel This Month Count')
				THEN
					SELECT SUM(src_table2.total_count) INTO v_Count
					FROM 
					(SELECT SUM(x1+x2+x3) AS total_count
					FROM
						(SELECT a.IRIDNo, a.TAIDNo, a.ServiceNo, a.MerchantName, a.TerminalSN, a.JobTypeDescription, 
											    IF(a.JobTypeDescription='SVC REQ INSTALLATION' AND a.ActionMade = 'SUCCESS',1,0) AS x1, 
											    IF(a.JobTypeDescription='SVC REQ PULL-OUT' AND a.ActionMade = 'SUCCESS',0,0) AS x2,
											    IF(a.JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(a.ReplaceTerminalSN, '-')) > 2 AND 
											    (a.TerminalSN = a.ReplaceTerminalSN) 
											    AND a.ActionMade = 'SUCCESS',0, 0)  AS x3
						FROM 
						tblservicingdetail a
						LEFT JOIN tblterminaldetail AS b ON a.TerminalID = b.TerminalID
						LEFT JOIN tblfsrdetail AS c ON a.ServiceNo = c.ServiceNo
						WHERE b.TerminalTypeID = v_TerminalTypeID AND 
							b.TerminalModelID = v_TerminalModelID AND 
							a.ClientID = v_ClientID AND (LEFT(c.FSRDate, 7) = LEFT(CURDATE(), 7))
					) 
					AS src_table1
					GROUP BY TerminalSN) AS src_table2;
				END IF;
			ELSE						
				SET p_WHERE = '';
				IF (v_TerminalTypeID > 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.TerminalTypeID = ');
					SET p_WHERE = CONCAT(p_WHERE, v_TerminalTypeID);
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;

				IF (STRCMP(v_ModelDescription, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.Description = ');
					SET p_WHERE = CONCAT(p_WHERE, "'", v_ModelDescription, "'");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (STRCMP(v_TerminalStatusDescription, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatusDescription = ');
					SET p_WHERE = CONCAT(p_WHERE, "'", v_TerminalStatusDescription, "'");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				IF (STRCMP(v_ClientName, "0") != 0)
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ClientName IN ');
					SET p_WHERE = CONCAT(p_WHERE, "(", v_ClientName, ")");
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				# Date
				IF (p_SearchBy = 'TypeAndModel Last Month Count')
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', '(LEFT(a.FSRDate, 7) = LEFT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), 7)) ');
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				# Date
				IF (p_SearchBy = 'TypeAndModel This Month Count')
				THEN
					SET p_WHERE = CONCAT(p_WHERE, ' ', '(LEFT(a.FSRDate, 7) = LEFT(CURDATE(), 7)) ');
					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
				END IF;
				
				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
				#SELECT CONCAT('p_WHERE = ', p_WHERE);
				
				SET p_SQL = '';	
				SET p_SQL = CONCAT(p_SQL,'SELECT');
				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(COUNT(*), 0) AS v_Count
								FROM tblfsrdetail a
								LEFT JOIN tblterminaldetail AS b ON a.TerminalSN = b.SerialNo
								LEFT JOIN tblterminalmodel AS c ON b.TerminalModelID = c.TerminalModelID');	

				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('Before:p_SQL = ', p_SQL);
		    
				IF (LENGTH(p_WHERE) > 0)
				THEN
					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");
				
				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
				#SELECT CONCAT('After:p_SQL = ', p_SQL);
				
				DROP TEMPORARY TABLE IF EXISTS tbltempcountterminal;
				
				SET p_TempQuery = '';
				SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltempcountterminal (xCount VARCHAR(45) NOT NULL)');
				SET @QUERY = p_TempQuery;
				
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;
				
				SET p_INSERT = '';
				SET p_INSERT = 'INSERT INTO tbltempcountterminal (xCount)';
				SET @QUERY = '';	
				SET @QUERY = CONCAT(p_INSERT, p_SQL);
				# Execute Query 
				PREPARE QUERY FROM @QUERY;
				EXECUTE QUERY;

				SELECT xCount INTO v_Count 
				FROM tbltempcountterminal;
			END IF;	
	
	ELSEIF (p_SearchBy = 'Client Status Count')
	THEN			
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			
			SET v_ServiceTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			
				
			IF (v_ServiceTypeStatusDescription = 'AVAILABLE')
			THEN
				SELECT IFNULL(COUNT(*), 0) INTO v_Count
				FROM tblirdetail a				
				LEFT JOIN tblparticular AS b ON a.ClientID = b.ParticularID									
				WHERE a.ClientID = v_ClientID AND a.IRStatusDescription = v_ServiceTypeStatusDescription;
				
			ELSEIF (v_ServiceTypeStatusDescription = 'ALLOCATED')
			THEN	
				SELECT IFNULL(COUNT(*), 0) INTO v_Count
				FROM tblterminalallocation a
				LEFT JOIN tblterminaldetail AS b ON a.TerminalID = b.TerminalID				
				LEFT JOIN tblservicingdetail AS d ON a.IRID = d.IRIDNo					
				WHERE a.ClientID = v_ClientID AND d.ServiceStatusDescription = v_ServiceTypeStatusDescription AND
				      d.JobTypeStatusDescription = 'PENDING';

			ELSEIF (v_ServiceTypeStatusDescription = 'DISPATCH')
			THEN	
				SELECT IFNULL(COUNT(*), 0) INTO v_Count
				FROM tblterminalallocation a
				LEFT JOIN tblterminaldetail AS b ON a.TerminalID = b.TerminalID				
				LEFT JOIN tblservicingdetail AS d ON a.IRID = d.IRIDNo					
				WHERE d.ClientID = v_ClientID AND d.ServiceStatusDescription = v_ServiceTypeStatusDescription AND
				      d.JobTypeStatusDescription = 'PROCESSING';
				      
			ELSEIF (v_ServiceTypeStatusDescription = 'INSTALLED')
			THEN					     
				SELECT SUM(src_table2.total_count) INTO v_Count
				FROM 
				(SELECT SUM(x1+x2+x3) AS total_count
				FROM
					(SELECT IRIDNo, TAIDNo, ServiceNo, MerchantName, TerminalSN, JobTypeDescription, 
										    IF(JobTypeDescription='SVC REQ INSTALLATION' AND ActionMade = 'SUCCESS',1,0) AS x1, 
										    IF(JobTypeDescription='SVC REQ PULL-OUT' AND ActionMade = 'SUCCESS',0,0) AS x2,
										    IF(JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(ReplaceTerminalSN, '-')) > 2 AND 
										    (TerminalSN = ReplaceTerminalSN) 
										    AND ActionMade = 'SUCCESS',0, 0)  AS x3
					FROM 
					tblservicingdetail
					WHERE ClientID = v_ClientID
				) 
				AS src_table1
				GROUP BY TerminalSN) AS src_table2;      
				      		
			ELSE
				SELECT IFNULL(COUNT(*), 0) INTO v_Count
				FROM tblterminalallocation a
				LEFT JOIN tblterminaldetail AS b ON a.TerminalID = b.TerminalID
				LEFT JOIN tblterminalmodel AS c ON b.TerminalModelID = c.TerminalModelID
				LEFT JOIN tblirdetail AS d ON a.IRID = d.IRIDNo
				WHERE d.ClientID = v_ClientID AND 
					a.ServiceTypeStatusDescription = v_ServiceTypeStatusDescription;	
			END IF;
			
			
	ELSEIF (p_SearchBy = 'Client Last Month Count')	
	THEN			
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			
			SET v_ServiceTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(SUM(src_table2.total_count), 0) INTO v_Count
			FROM 
			(SELECT SUM(x1+x2+x3) AS total_count
			FROM
				(SELECT a.IRIDNo, a.TAIDNo, a.ServiceNo, a.MerchantName, a.TerminalSN, a.JobTypeDescription, 
									    IF(a.JobTypeDescription='SVC REQ INSTALLATION' AND a.ActionMade = 'SUCCESS',1,0) AS x1, 
									    IF(a.JobTypeDescription='SVC REQ PULL-OUT' AND a.ActionMade = 'SUCCESS',0,0) AS x2,
									    IF(a.JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(a.ReplaceTerminalSN, '-')) > 2 AND 
									    (a.TerminalSN = a.ReplaceTerminalSN) 
									    AND a.ActionMade = 'SUCCESS',0, 0)  AS x3
				FROM 
				tblservicingdetail a
				LEFT JOIN tblfsrdetail AS b ON a.ServiceNo = b.ServiceNo
				WHERE (a.ClientID = v_ClientID) AND (LEFT(b.FSRDate, 7) = LEFT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), 7))
			) 
			AS src_table1
			GROUP BY TerminalSN) AS src_table2;
	
	ELSEIF (p_SearchBy = 'Client This Month Count')	
	THEN				
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			
			SET v_ServiceTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(SUM(src_table2.total_count), 0) INTO v_Count
			FROM 
			(SELECT SUM(x1+x2+x3) AS total_count
			FROM
				(SELECT a.IRIDNo, a.TAIDNo, a.ServiceNo, a.MerchantName, a.TerminalSN, a.JobTypeDescription, 
									    IF(a.JobTypeDescription='SVC REQ INSTALLATION' AND a.ActionMade = 'SUCCESS',1,0) AS x1, 
									    IF(a.JobTypeDescription='SVC REQ PULL-OUT' AND a.ActionMade = 'SUCCESS',0,0) AS x2,
									    IF(a.JobTypeDescription='SVC REQ REPLACEMENT' AND LENGTH(IFNULL(a.ReplaceTerminalSN, '-')) > 2 AND 
									    (a.TerminalSN = a.ReplaceTerminalSN) 
									    AND a.ActionMade = 'SUCCESS',0, 0)  AS x3
				FROM 
				tblservicingdetail a
				LEFT JOIN tblfsrdetail AS b ON a.ServiceNo = b.ServiceNo
				WHERE (a.ClientID = v_ClientID) AND (LEFT(b.FSRDate, 7) = LEFT(CURDATE(), 7))
			) 
			AS src_table1
			GROUP BY TerminalSN) AS src_table2;
			
	ELSEIF (p_SearchBy = 'IR Status Count')
	THEN	
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblirdetail a			
			WHERE (a.IRStatus = v_ServiceStatus) AND (a.IRStatusDescription = v_ServiceStatusDescription) AND (a.IRActive > 0);
			
	ELSEIF (p_SearchBy = 'IR Days Pending Count')
	THEN	
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_NoOfDayPending = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM
			(
				SELECT InstallationDate, IRNo, DATE_SUB(InstallationDate, INTERVAL v_NoOfDayPending DAY) AS iDateSub
				FROM
				tblirdetail
				WHERE ((v_SystemDate <= InstallationDate) AND (isClose = 0))
				ORDER BY InstallationDate
			) AS src_table
			WHERE (src_table.InstallationDate BETWEEN iDateSub AND (DATE_ADD(v_SystemDate, INTERVAL v_NoOfDayPending DAY)));

			
	ELSEIF (p_SearchBy = 'IR OverDue Count')
	THEN	
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblirdetail a			
			WHERE (a.IRStatus = v_ServiceStatus) AND (a.IRStatusDescription = v_ServiceStatusDescription) AND (a.IRActive > 0) AND (InstallationDate < v_SystemDate);				
			
	ELSEIF (p_SearchBy = 'Servicing Status Count')
	THEN	
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblservicingdetail a			
			WHERE (a.ServiceStatus = v_ServiceStatus) AND (a.ServiceStatusDescription = v_ServiceStatusDescription) AND 
			      (a.JobTypeStatusDescription = v_JobTypeStatusDescription);
				
	ELSEIF (p_SearchBy = 'Negative Servicing Status Count')
	THEN	
			#SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			#SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			#SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			#SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			#SET v_isClose = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			
			SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_isClose = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SELECT IFNULL(COUNT(DISTINCT a.TerminalSN), 0) INTO v_Count
			FROM tblservicingdetail a
			WHERE (a.JobTypeDescription = v_JobTypeDescription AND a.ActionMade = v_ActionMade AND a.isClose = v_isClose AND a.JobTypeStatusDescription = v_JobTypeStatusDescription)			
			ORDER BY a.ServiceNo DESC;
			      
	ELSEIF (p_SearchBy = 'Success Servicing Status Count')
	THEN	
			#SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			#SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			#SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			#SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			#SET v_isClose = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			
			SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_isClose = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SELECT DISTINCT IFNULL(COUNT(DISTINCT a.TerminalSN), 0) INTO v_Count
			FROM tblservicingdetail a
			WHERE (a.JobTypeDescription = v_JobTypeDescription AND a.ActionMade = v_ActionMade AND a.isClose = v_isClose)			
			ORDER BY a.ServiceNo DESC;
			      			     
	ELSEIF (p_SearchBy = 'IR Active Count')
	THEN	
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblirdetail a			
			WHERE (a.IRStatus = v_ServiceStatus) AND (a.IRStatusDescription = v_ServiceStatusDescription) AND (a.IRActive = 0);
			
	ELSEIF (p_SearchBy = 'ERM Temp Detail')	
	THEN
			
			SELECT IFNULL(COUNT(*), 0) INTO v_Count
			FROM tblermdetailtemp;
			
	ELSEIF (p_SearchBy = 'Service TerminalSN List')
	THEN
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));			
			SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
			SET v_FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
