			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_Status = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			
			IF (v_ClientID > 0)
			THEN
				SELECT 
				IFNULL_NUMERIC(COUNT(*)) INTO v_TCount
				FROM 
				tblterminaldetail 
				WHERE
				Location = v_Location AND
				TerminalTypeID = v_TerminalTypeID AND
				TerminalModelID = v_TerminalModelID AND
				TerminalStatus = v_Status AND
				ClientID = v_ClientID AND
				isActive > 0;	
			ELSE
				SELECT 
				IFNULL_NUMERIC(COUNT(*)) INTO v_TCount
				FROM 
				tblterminaldetail 
				WHERE
				Location = v_Location AND
				TerminalTypeID = v_TerminalTypeID AND
				TerminalModelID = v_TerminalModelID AND
				TerminalStatus = v_Status AND
				isActive > 0;	
			END IF;
			

			SET v_Count = v_TCount;	
			
	ELSEIF (p_SearchBy = 'SIM Count By Status')
	THEN		
	
			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_Status = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			
			SELECT 
			IFNULL_NUMERIC(COUNT(*)) INTO v_TCount
			FROM 
			tblsimdetail 
			WHERE
			Location = v_Location AND
			Carrier = v_SIMCarrier AND
			SIMStatus = v_Status AND
			isActive > 0;	

			SET v_Count = v_TCount;	
			
	ELSEIF (p_SearchBy = 'Terminal Count By Service JobType')
	THEN		
			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			
			SELECT 
			IFNULL_NUMERIC(COUNT(*)) INTO v_TCount
			FROM 
			tblterminaldetail a
			LEFT JOIN tblfsrdetail b ON a.TerminalID = b.TerminalID 
			WHERE
			a.Location = v_Location AND
			a.TerminalTypeID = v_TerminalTypeID AND
			a.TerminalModelID = v_TerminalModelID AND
			b.JobType = v_JobType AND
			a.isActive > 0 AND
			b.ActionMade = v_ActionMade;	

			SET v_Count = v_TCount;	
			
	ELSEIF (p_SearchBy = 'SIM Count By Service JobType')
	THEN			
			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SELECT 
			IFNULL_NUMERIC(COUNT(*)) INTO v_TCount
			FROM 
			tblsimdetail a
			LEFT JOIN tblfsrdetail b ON a.SIMID = b.SIMID  
			WHERE
			a.Location = v_Location AND
			a.Carrier = v_SIMCarrier AND
			b.JobType = v_JobType AND
			a.isActive > 0 AND
			b.ActionMade = v_ActionMade;

			SET v_Count = v_TCount;	
			
	ELSEIF (p_SearchBy = 'Installation Count By Service JobType')
	THEN		
			SET v_RegionType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			
			SELECT
			IFNULL_NUMERIC(COUNT(*)) INTO v_TCount
			FROM
			tblfsrdetail a
			LEFT JOIN tblparticular b ON a.MerchantID = b.ParticularID
			LEFT JOIN tblterminaldetail c ON a.TerminalID = c.TerminalID
			WHERE 
			b.RegionType = v_RegionType AND 
			c.TerminalTypeID = v_TerminalTypeID AND 
			c.TerminalModelID = v_TerminalModelID AND 
			a.JobType = v_JobType AND
			a.ActionMade = v_ActionMade;
			
			SET v_Count = v_TCount;	
			
	ELSEIF (p_SearchBy = 'Attempt Counter')	
	THEN
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			
			SELECT 
			ActionMade, Attempt INTO v_ActionMade, v_Attempt 
			FROM tblfsrdetail 
			WHERE (IRIDNo = v_IRIDNo AND JobType = v_JobType)
			ORDER BY FSRNo DESC
			LIMIT 1;
			
			IF (STRCMP(v_ActionMade, "SUCCESS") = 0)
			THEN
				SET v_Count = 1;
			ELSE
				set v_Count = v_Attempt + 1;
			END IF;
			
			IF (v_Count <= 0 || ISNULL(v_Count))
			THEN
			   SET v_Count = 1;
			end IF;
			
	ELSEIF (p_SearchBy = 'Action Made Counter')	
	THEN
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_ActionMade = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
						
			SELECT 
			COUNT(*) INTO v_Count
			FROM tblfsrdetail 
			WHERE (IRIDNo = v_IRIDNo AND ActionMade = v_ActionMade);
			#WHERE (IRIDNo = v_IRIDNo AND JobType = v_JobType AND ActionMade = v_ActionMade);
			
			IF (v_Count <= 0 || ISNULL(v_Count))
			THEN
			   SET v_Count = 0;
			END IF;
			
	ELSEIF (p_SearchBy = 'Generate FSR Count')	
	THEN
			SELECT funcGetCount("Search", p_SearchBy, "") INTO v_Count;
			
	ELSEIF (p_SearchBy = 'Failed Service Count')	
	THEN
			SELECT funcGetCount("Search", p_SearchBy, "") INTO v_Count;
										
	END IF;
	
	#SELECT CONCAT("Out::v_Count=", v_Count);
	
	IF (v_Count > 0)
	THEN
		SET p_outCount = v_Count;
	ELSE
		SET p_outCount = 0;
	END IF;
		
END IF;
        
END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewDepartment` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewDepartment` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewDepartment`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_Active INTEGER;

	DECLARE v_Description VARCHAR(45);

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Department')

		THEN			

			SELECT 

			DepartmentID,			

			Description,

			isActive

			FROM

			tbldepartment

			WHERE 

			(isActive > 0)

			ORDER BY Description;

			

		ELSEIF (p_SearchBy = 'Department List')

		THEN

			SELECT

			DepartmentID,			

			Description,

			isActive

			FROM

			tbldepartment

			WHERE 

			(isActive > 0)

			ORDER BY Description;

		END IF;	

		

	ELSEIF (p_StatementType = 'Search')

	THEN

	

		IF (p_SearchBy = 'Department')

		THEN

			SET p_SearchValue = ADD_PERCENT_CHAR(p_SearchValue);

			SELECT         

			DepartmentID,

			Description,

			isActive

			FROM        

			tbldepartment

			WHERE       

			(Description LIKE p_SearchValue);

		ELSEIF (p_SearchBy = 'DepartmentID')

		THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT         

			DepartmentID,

			Description,

			isActive

			FROM        

			tbldepartment

			WHERE       

			(DepartmentID = v_ID);				

		 END IF;		  

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewEquipment` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewEquipment` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewEquipment`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT EquipmentID, Description

		FROM   tblequipment

		ORDER BY Description;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						EquipmentID,

						Description

			FROM        tblequipment

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'EquipmentID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						EquipmentID,

						Description

			FROM        tblequipment

			WHERE       (EquipmentID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewERM` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewERM` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewERM`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(300) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_DateFrom VARCHAR(45);

	DECLARE v_DateTo VARCHAR(45);

	DECLARE v_OffSetFrom INTEGER;

	DECLARE v_OffSetTo INTEGER;

	DECLARE v_Billable INTEGER;

	DECLARE v_SearchQuery VARCHAR(200);

	

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_LIMIT LONGTEXT;

	DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN		

		IF (p_SearchBy = 'ERM Temp Detail')

		THEN		

				SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

				SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

				

				#SELECT (CONCAT("v_OffSetFrom=",v_OffSetFrom));

				#SELECT (CONCAT("v_OffSetTo=",v_OffSetTo));

				

				SET p_WHERE = '';

				IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

				THEN					

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FSRNo', ' ', 'BETWEEN', ' ');

					SET p_WHERE = CONCAT(p_WHERE, v_OffSetFrom, ' ', 'AND', ' ', v_OffSetTo);

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				END IF;

				

				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

				#SELECT CONCAT('p_WHERE = ', p_WHERE);

				

				SET p_SQL = '';	

				SET p_SQL = CONCAT(p_SQL,'SELECT');                

                SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

								IFNULL(a.`No`, "-") AS `No`,

								IFNULL(a.Merchant, "-") AS Merchant,

								IFNULL(a.`MID`, "-") AS `MID`,

								IFNULL(a.TID, "-") AS TID,

								IFNULL(a.InvoiceNo, "-") AS InvoiceNo,

								IFNULL(a.BatchNo, "-") AS BatchNo,

								IFNULL(a.PAN, "-") AS FSR,

								IFNULL(a.FSRDate, "-") AS FSRDate,

								IFNULL(a.FSRTime, "-") AS FSRTime,

                                IFNULL(a.TxnType, "-") AS TxnType,

								IFNULL_DECIMAL(a.TxnAmt) AS TxnAmt,                                

								IFNULL(IF(LENGTH(TRIM(a.AuthCode)) > 0, a.AuthCode, "-"), "0") AS AuthCode,				

								IFNULL(IF(LENGTH(TRIM(a.RefNo)) > 0, a.RefNo, "-"), "0") AS RefNo,			

								IFNULL(IF(LENGTH(TRIM(a.PhoneNo)) > 0, a.PhoneNo, "-"), "0") AS MerchantContactNo,

								IFNULL(IF(LENGTH(TRIM(a.Email)) > 0, a.Email, "-"), "0") AS MerchantRepresentative,

								IFNULL(IF(LENGTH(TRIM(a.NRIC)) > 0, a.NRIC, "-"), "0") AS NRIC,

								IFNULL(IF(LENGTH(TRIM(a.AddInfo)) > 0, a.AddInfo, "-"), "0") AS AddInfo

								FROM

								tblermdetailtemp a');

					#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

					#SELECT CONCAT('After:p_SQL = ', p_SQL);

					IF (LENGTH(p_WHERE) > 0)

					THEN

						SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

						SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

					END IF;

					SET p_SQL = REPLACE(p_SQL, '"', "'");

					#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

					#SELECT CONCAT('After:p_SQL = ', p_SQL);

								

					

					SET p_ORDERBY = '';

					SET p_ORDERBY = 'a.FSRNo';

					

					IF (LENGTH(p_ORDERBY) > 0)

					THEN

						SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

						SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

					END IF;

					

					#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

					#SELECT CONCAT(':p_SQL = ', p_SQL);

					

					SET @QUERY = p_SQL;

					# Execute Query 

					PREPARE QUERY FROM @QUERY;

					EXECUTE QUERY;

                    

        ELSEIF (p_SearchBy = 'ERM Temp Detail Report')

		THEN 

				SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

				SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

				SET v_Billable = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);

                

				#SELECT (CONCAT("v_OffSetFrom=",v_OffSetFrom));

				#SELECT (CONCAT("v_OffSetTo=",v_OffSetTo));

				

				SET p_WHERE = '';

				IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

				THEN					

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FSRNo', ' ', 'BETWEEN', ' ');

					SET p_WHERE = CONCAT(p_WHERE, v_OffSetFrom, ' ', 'AND', ' ', v_OffSetTo);

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				END IF;

				

				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

				#SELECT CONCAT('p_WHERE = ', p_WHERE);

				

				SET p_SQL = '';	

				SET p_SQL = CONCAT(p_SQL,'SELECT'); 

                

				IF (v_Billable > 0)

				THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

										IFNULL(a.`No`, "-") AS `No`,

										IFNULL(a.Merchant, "-") AS Merchant,

										IFNULL(a.`MID`, "-") AS `MID`,

										IFNULL(a.TID, "-") AS TID,

										IFNULL(a.InvoiceNo, "-") AS InvoiceNo,

										IFNULL(a.BatchNo, "-") AS BatchNo,

										IFNULL(a.PAN, "-") AS FSR,

										IFNULL(a.FSRDate, "-") AS FSRDate,

										IFNULL(a.FSRTime, "-") AS FSRTime,

						IFNULL(a.TxnType, "-") AS TxnType,

										IFNULL_DECIMAL(a.TxnAmt) AS TxnAmt,				

										IFNULL(IF(LENGTH(TRIM(a.AuthCode)) > 0, a.AuthCode, "-"), "0") AS AuthCode,				

										IFNULL(IF(LENGTH(TRIM(a.RefNo)) > 0, a.RefNo, "-"), "0") AS RefNo,			

										IFNULL(IF(LENGTH(TRIM(a.PhoneNo)) > 0, a.PhoneNo, "-"), "0") AS MerchantContactNo,

										IFNULL(IF(LENGTH(TRIM(a.Email)) > 0, a.Email, "-"), "0") AS MerchantRepresentative,

										IFNULL(IF(LENGTH(TRIM(a.NRIC)) > 0, a.NRIC, "-"), "0") AS NRIC,

										IFNULL(IF(LENGTH(TRIM(a.AddInfo)) > 0, a.AddInfo, "-"), "0") AS AddInfo

										FROM

										tblermdetailtemp a');

				ELSE

				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

										IFNULL(a.`No`, "-") AS `No`,

										IFNULL(a.Merchant, "-") AS Merchant,

										IFNULL(a.`MID`, "-") AS `MID`,

										IFNULL(a.TID, "-") AS TID,

										IFNULL(a.InvoiceNo, "-") AS InvoiceNo,

										IFNULL(a.BatchNo, "-") AS BatchNo,

										IFNULL(a.PAN, "-") AS FSR,

										IFNULL(a.FSRDate, "-") AS FSRDate,

										IFNULL(a.FSRTime, "-") AS FSRTime,

						IFNULL(a.TxnType, "-") AS TxnType,

										IFNULL_DECIMAL(a.TxnAmt) AS TxnAmt,				

										IFNULL(IF(LENGTH(TRIM(a.AuthCode)) > 0, a.AuthCode, "-"), "0") AS AuthCode,				

										IFNULL(IF(LENGTH(TRIM(a.RefNo)) > 0, a.RefNo, "-"), "0") AS RefNo,			

										IFNULL(IF(LENGTH(TRIM(a.PhoneNo)) > 0, a.PhoneNo, "-"), "0") AS MerchantContactNo,

										IFNULL(IF(LENGTH(TRIM(a.Email)) > 0, a.Email, "-"), "0") AS MerchantRepresentative,

										IFNULL(IF(LENGTH(TRIM(a.NRIC)) > 0, a.NRIC, "-"), "0") AS NRIC,

										IFNULL(IF(LENGTH(TRIM(a.AddInfo)) > 0, a.AddInfo, "-"), "0") AS AddInfo

										FROM

										tblermdetailrepo a

						WHERE `No` NOT IN (SELECT `No` FROM tblermdetailtemp)');

				END IF;

			       

				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('After:p_SQL = ', p_SQL);

				IF (LENGTH(p_WHERE) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");

				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('After:p_SQL = ', p_SQL);

							

				

				SET p_ORDERBY = '';

				SET p_ORDERBY = 'a.FSRNo';

				

				IF (LENGTH(p_ORDERBY) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

					SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

				END IF;

				

				#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT(':p_SQL = ', p_SQL);

				

				SET @QUERY = p_SQL;

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

				

		ELSEIF (p_SearchBy = 'ERM Temp Detail Date Filter')

		THEN

			SELECT DateFrom, DateTo

			FROM

			tbldummy;

			

		ELSEIF (p_SearchBy = 'ERM Temp Detail By Type')

		THEN

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_Billable = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);	

			SET v_SearchQuery = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

			

			#SELECT (CONCAT("v_OffSetFrom=",v_OffSetFrom));

			#SELECT (CONCAT("v_OffSetTo=",v_OffSetTo));

			#SELECT (CONCAT("v_Billable=",v_Billable));

			#SELECT (CONCAT("v_SearchQuery=",v_SearchQuery));

			

			SET p_WHERE = '';

			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

			THEN					

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FSRNo', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, v_OffSetFrom, ' ', 'AND', ' ', v_OffSetTo);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_SearchQuery, "0") != 0 AND LENGTH(v_SearchQuery) > 0)

			THEN					

				-- Remove the trailing ^ if any (optional based on your actual input format)
				SET v_SearchQuery = LEFT(v_SearchQuery, LENGTH(v_SearchQuery) - 1);

				-- Replace ^ with | (for regex OR condition)
				SET v_SearchQuery = REPLACE(v_SearchQuery, "^", "|");

				-- Escape literal parentheses: replace ( with \\( and ) with \\)
				SET v_SearchQuery = REPLACE(v_SearchQuery, "(", "\\\\(");
				SET v_SearchQuery = REPLACE(v_SearchQuery, ")", "\\\\)");

				-- Now build the REGEXP clause
				SET p_WHERE = CONCAT(p_WHERE, ' a.Merchant REGEXP ', "'", v_SearchQuery, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' AND ');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT'); 

	

			IF (v_Billable > 0)

			THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

									IFNULL(a.`No`, "-") AS `No`,

									IFNULL(a.Merchant, "-") AS Merchant,

									IFNULL(a.`MID`, "-") AS `MID`,

									IFNULL(a.TID, "-") AS TID,

									IFNULL(a.InvoiceNo, "-") AS InvoiceNo,

									IFNULL(a.BatchNo, "-") AS BatchNo,

									IFNULL(a.PAN, "-") AS FSR,

									IFNULL(a.FSRDate, "-") AS FSRDate,

									IFNULL(a.FSRTime, "-") AS FSRTime,

									IFNULL(a.TxnType, "-") AS TxnType,

									IFNULL_DECIMAL(a.TxnAmt) AS TxnAmt,				

									IFNULL(IF(LENGTH(TRIM(a.AuthCode)) > 0, a.AuthCode, "-"), "0") AS AuthCode,				

									IFNULL(IF(LENGTH(TRIM(a.RefNo)) > 0, a.RefNo, "-"), "0") AS RefNo,			

									IFNULL(IF(LENGTH(TRIM(a.PhoneNo)) > 0, a.PhoneNo, "-"), "0") AS MerchantContactNo,

									IFNULL(IF(LENGTH(TRIM(a.Email)) > 0, a.Email, "-"), "0") AS MerchantRepresentative,

									IFNULL(IF(LENGTH(TRIM(a.NRIC)) > 0, a.NRIC, "-"), "0") AS NRIC,

									IFNULL(IF(LENGTH(TRIM(a.AddInfo)) > 0, a.AddInfo, "-"), "0") AS AddInfo

									FROM

									tblermdetailtemp a');

			ELSE

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

									IFNULL(a.`No`, "-") AS `No`,

									IFNULL(a.Merchant, "-") AS Merchant,

									IFNULL(a.`MID`, "-") AS `MID`,

									IFNULL(a.TID, "-") AS TID,

									IFNULL(a.InvoiceNo, "-") AS InvoiceNo,

									IFNULL(a.BatchNo, "-") AS BatchNo,

									IFNULL(a.PAN, "-") AS FSR,

									IFNULL(a.FSRDate, "-") AS FSRDate,

									IFNULL(a.FSRTime, "-") AS FSRTime,

									IFNULL(a.TxnType, "-") AS TxnType,

									IFNULL_DECIMAL(a.TxnAmt) AS TxnAmt,				

									IFNULL(IF(LENGTH(TRIM(a.AuthCode)) > 0, a.AuthCode, "-"), "0") AS AuthCode,				

									IFNULL(IF(LENGTH(TRIM(a.RefNo)) > 0, a.RefNo, "-"), "0") AS RefNo,			

									IFNULL(IF(LENGTH(TRIM(a.PhoneNo)) > 0, a.PhoneNo, "-"), "0") AS MerchantContactNo,

									IFNULL(IF(LENGTH(TRIM(a.Email)) > 0, a.Email, "-"), "0") AS MerchantRepresentative,

									IFNULL(IF(LENGTH(TRIM(a.NRIC)) > 0, a.NRIC, "-"), "0") AS NRIC,

									IFNULL(IF(LENGTH(TRIM(a.AddInfo)) > 0, a.AddInfo, "-"), "0") AS AddInfo

									FROM

									tblermdetailrepo a

					WHERE `No` NOT IN (SELECT `No` FROM tblermdetailtemp)');

			END IF;

		       

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);
			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.FSRNo';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			
			# Insert result to tblermdetailtype

			SET @QUERY = '';

			SET @QUERY = CONCAT("INSERT INTO tblermdetailtype (FSRNo,`No`,Merchant,`MID`,TID,InvoiceNo,BatchNo,PAN,FSRDate,FSRTime,TxnType,TxnAmt,AuthCode,RefNo,PhoneNo,Email,NRIC,AddInfo)", p_SQL);

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

						

		END IF;		         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewExpenses` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewExpenses` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewExpenses`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_ExpensesID INTEGER;

	DECLARE v_TAIDNo INTEGER;

	DECLARE v_ServiceNo INTEGER;

	DECLARE v_Description VARCHAR(45);

	   

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

	

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Service Expenses')

		THEN

			SET v_ExpensesID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);

			

			

			SET p_WHERE = '';

			IF (v_ExpensesID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.UserID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_UserID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_TAIDNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.UserID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_UserID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_ServiceNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.UserID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_UserID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;					

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

		    

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(b.ExpensesID, 0) AS ExpensesID,

							IFNULL(b.Description, "-") AS Description,

							IFNULL(a.TAIDNo, 0) AS TAIDNo,

							IFNULL(a.ServiceNo, 0) AS ServiceNo,							

							IFNULL(a.RequestNo, "-") AS RequestNo,

							IFNULL(a.FEID, 0) AS FEID,

							IFNULL(a.FEName, "-") AS FEName,

							IFNULL(a.ClientID, 0) AS ClientID,

							IFNULL(a.ClientName, "-") AS ClientName,

							IFNULL(a.MerchantID, 0) AS MerchantID,

							IFNULL(a.MerchantName, "-") AS MerchantName,

							IFNULL(DATE_FORMAT(a.ServiceDate, "%m-%d-%Y"), "-") AS ServiceDate,

							IFNULL(DATE_FORMAT(a.ServiceTime, "%h:%i %p"), "-") AS ServiceTime,

							IFNULL(a.TExpenses, 0) AS TExpenses

							FROM tblservicingdetail AS a

							LEFT JOIN tblexpenses AS b ON a.ExpensesID = b.ExpensesID');	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'b.SequenceDisplay';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSE

			SELECT 

			ExpensesID, 

			Description

			FROM   

			tblexpenses

			ORDER BY 

			SequenceDisplay;

		END IF;

		

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			

			SELECT      

			ExpensesID, 

			Description

			FROM        

			tblexpenses

			WHERE       

			(Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'ExpensesID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT

			ExpensesID, 

			Description

			FROM        

			tblexpenses

			WHERE       

			(ExpensesID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewFE` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewFE` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewFE`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT DISTINCT

		FEID,

		NAME,

		Address,

		ContactNo

		FROM   tblfe

		ORDER BY NAME;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Name')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

			FEID,

			NAME,

			Address,

			ContactNo

			FROM        tblfe

			WHERE       (NAME LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'FEID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			FEID,

			NAME,

			Address,

			ContactNo

			FROM        tblfe

			WHERE       (FEID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewFSR` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewFSR` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewFSR`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(300) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_FSRNo INTEGER;

	DECLARE v_ServiceNo INTEGER;

	DECLARE v_DateFrom VARCHAR(45);

	DECLARE v_DateTo VARCHAR(45);

	DECLARE v_ReasonID INTEGER;

	DECLARE v_ReasonDescription VARCHAR(45);

	DECLARE v_ServiceCode VARCHAR(45);

	DECLARE v_Merchant VARCHAR(45);

	DECLARE v_TerminaSN VARCHAR(45);

	DECLARE v_SIMSN VARCHAR(45);

	DECLARE v_IRNo VARCHAR(45);

	DECLARE v_TerminalSN VARCHAR(45);

	DECLARE v_OffSetFrom INTEGER;

	DECLARE v_OffSetTo INTEGER;

	DECLARE v_OffSet INTEGER;

    

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

	DECLARE p_SearchQuery VARCHAR(100);

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Download Completed FSR')

		THEN

			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			

			SET p_WHERE = '';

			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FSRDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

		    

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

							IFNULL(a.Merchant, "-") AS Merchant,

							IFNULL(a.TID, "-") AS TID,

							IFNULL(a.MID, "-") AS `MID`,

							IFNULL(a.TimeArrived, "-") AS TimeArrived,

							IFNULL(a.TimeStart, "-") AS TimeStart,

							IFNULL(a.FSR, "-") AS FSR,

							IFNULL(a.FSRDate, "-") AS FSRDate,

							IFNULL(a.FSRTime, "-") AS FSRTime,

							IFNULL(a.TimeEnd, "-") AS TimeEnd,

							IFNULL(a.MerchantContactNo, "-") AS MerchantContactNo,

							IFNULL(a.MerchantRepresentative, "-") AS MerchantRepresentative

							FROM tblfsrdetail AS a');	

				#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('Before:p_SQL = ', p_SQL);

		    

				IF (LENGTH(p_WHERE) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");

				#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('After:p_SQL = ', p_SQL);	

				

				SET p_ORDERBY = '';

				SET p_ORDERBY = 'a.FSRDate';

				

				IF (LENGTH(p_ORDERBY) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

					SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

				END IF;

				

				#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT(':p_SQL = ', p_SQL);

				

				SET @QUERY = p_SQL;

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;

				

		ELSEIF (p_SearchBy = 'FSR Temp Detail')

		THEN		

				SELECT

				a.FSRNo,

				a.`No`,

				a.Merchant,

				a.`MID`,

				a.TID,				

				IFNULL(DATE_FORMAT(CAST(a.InvoiceNo AS TIME), "%H:%i:%s"), "-") AS InvoiceNo,							

				IFNULL(DATE_FORMAT(CAST(a.BatchNo AS TIME), "%H:%i:%s"), "-") AS BatchNo,						

				a.PAN AS FSR,

				a.`Date` AS FSRDate,

				a.`Time` AS FSRTime,

				a.Txn_Amt,				

				IFNULL(DATE_FORMAT(CAST(a.Auth_Code AS TIME), "%H:%i:%s"), "-") AS TimeEnd,

				a.Ref_No AS TerminalSN,

				a.Phone_No AS MerchantContactNo,

				a.Email AS MerchantRepresentative,

				a.NRIC AS FEName,

				a.Additional_Information AS SerialNo,

				b.Description AS Description

				FROM

				tblfsrdetailtemp a

				LEFT JOIN tblservicetype AS b ON a.PAN = b.Code

				ORDER BY 

				b.Code;

		

		ELSEIF (p_SearchBy = 'FSR Ready For Import' || p_SearchBy = 'FSR Already Processed' || p_SearchBy = 'FSR Import Service Not Found')

		THEN

			SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			

			SET v_ReasonDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_ServiceCode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			

			SET p_WHERE = '';

			IF (v_ReasonID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ReasonID = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ReasonID, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_ServiceCode, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.PAN = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceCode, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

							IFNULL(a.`No`, "-") AS No,

							IFNULL(a.Merchant, "-") AS Merchant,

							IFNULL(a.`MID`, "-") AS MID,

							IFNULL(a.TID, "-") AS TID,							

							IFNULL(DATE_FORMAT(CAST(a.InvoiceNo AS TIME), "%H:%i:%s"), "-") AS InvoiceNo,

							IFNULL(DATE_FORMAT(CAST(a.BatchNo AS TIME), "%H:%i:%s"), "-") AS BatchNo,

							IFNULL(a.PAN, "-") AS FSR,

							IFNULL(a.`Date`, "-") AS FSRDate,

							IFNULL(a.`Time`, "-") AS FSRTime,

							IFNULL(a.Txn_Amt, "-") AS Txn_Amt,							

							IFNULL(DATE_FORMAT(CAST(a.Auth_Code AS TIME), "%H:%i:%s"), "-") AS TimeEnd,

							IFNULL(a.Ref_No, "-") AS TerminalSN,

							IFNULL(a.Phone_No, "-") AS MerchantContactNo,

							IFNULL(a.Email, "-") AS MerchantRepresentative,

							IFNULL(a.NRIC, "-") AS FEName,

							IFNULL(a.Additional_Information, "-") AS SerialNo

							FROM

							tblfsrdetailtemp a');	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

				

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.FSRNo';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'FSR Temp Detail Date Filter')

		THEN

			SELECT DateFrom, DateTo

			FROM

			tbldummy;

			

		ELSEIF (p_SearchBy = 'FSR FillUp')

		THEN

			SET v_FSRNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';

			IF (v_FSRNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.FSRNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_FSRNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

						

			IF (v_ServiceNo > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceNo, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

						

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,

							IFNULL(a.ServiceNo, 0) AS ServiceNo,

							IFNULL(a.ProblemReported, "-") AS ProblemReported,

							IFNULL(a.`ActualProblemReported`, "-") AS ActualProblemReported,

							IFNULL(a.ActionTaken, "-") AS ActionTaken,

							IFNULL(a.Remarks, "-") AS AnyComments,

							IFNULL(a.ReasonID, 0) AS ReasonID,

							IFNULL(b.Code, "-") AS ReasonCode,

							IFNULL(b.Description, "-") AS ReasonDescription,

							IFNULL(a.MerchantRepresentative, "-") AS MerchantRepresentative,

							IFNULL(a.MerchantContactNo, "-") AS MerchantContactNo

							FROM

							tblfsrdetail a

							LEFT JOIN tblreason AS b ON a.ReasonID = b.ReasonID');	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

				

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

		

		ELSEIF (p_SearchBy = 'FSR')

		THEN			

			SET p_SearchQuery = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);	

			

			SET p_WHERE = '';

			IF (LENGTH(p_SearchQuery) > 0 && STRCMP(p_SearchQuery, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'xTable.sFields LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", p_SearchQuery, "%'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(xTable.FSRNo) AS FSRNo,

							IFNULL_NUMERIC(xTable.ServiceNo) AS ServiceNo,

							IFNULL_NUMERIC(xTable.IRIDNo) AS IRIDNo,

							IFNULL_NUMERIC(xTable.TAIDNo) AS TAIDNo,

							IFNULL_NUMERIC(xTable.ClientID) AS ClientID,

							IFNULL_STRING(xTable.FSRDate) AS FSRDate,

							IFNULL_STRING(xTable.IRNo) AS IRNo,

							IFNULL_STRING(xTable.Merchant) AS Merchant,

							IFNULL_STRING(xTable.TID) AS TID,

							IFNULL_STRING(xTable.`MID`) AS `MID`,

							IFNULL_STRING(xTable.TerminalSN) AS TerminalSN,

							IFNULL_STRING(xTable.SIMSN) AS SIMSN,

							IFNULL_STRING(xTable.PrimaryNum) AS PrimaryNum,

							IFNULL_STRING(xTable.SecondaryNum) AS SecondaryNum,

							IFNULL_STRING(xTable.AppVersion) AS AppVersion,

							IFNULL_STRING(xTable.AppCRC) AS AppCRC,

							IFNULL_STRING(xTable.RequestNo) AS RequestNo,

							IFNULL_STRING(xTable.JobTypeDescription) AS JobTypeDescription,

							IFNULL_STRING(xTable.FEName) AS FEName,

							IFNULL_STRING(xTable.ServiceDateTime) AS ServiceDateTime,

							IFNULL_STRING(xTable.ServiceDate) AS ServiceDate,

							IFNULL_STRING(xTable.ServiceTime) AS ServiceTime,

							IFNULL_STRING(xTable.ServiceReqDate) AS ServiceReqDate,

							IFNULL_STRING(xTable.ServiceReqTime) AS ServiceReqTime

							FROM

							(

							SELECT

							a.FSRNo,

							a.ServiceNo,							

							a.IRIDNo,

							a.TAIDNo,

							a.ClientID,

							a.FSRDate,

							a.IRNo,

							g.`Name` AS Merchant,

							a.TID,

							a.`MID`,

							c.SerialNo AS TerminalSN,

							d.SerialNo AS SIMSN,

							(CONCAT(IFNULL_STRING(a.IRNo), "^", IFNULL_STRING(g.`Name`), "^", IFNULL_STRING(a.TID), "^", IFNULL_STRING(a.MID), "^", IFNULL_STRING(c.SerialNo), "^", IFNULL_STRING(d.SerialNo))) AS sFields,

							e.PrimaryNum AS PrimaryNum,

							e.SecondaryNum AS SecondaryNum,

							e.AppVersion AS AppVersion,

							e.AppCRC AS AppCRC,

							b.RequestNo,

							b.JobTypeDescription,

							f.`Name` AS FEName,

							b.ServiceDateTime,

							b.ServiceDate,

							b.ServiceTime,

							b.ServiceReqDate,

							b.ServiceReqTime

							FROM

							tblfsrdetail a

							LEFT JOIN tblservicingdetail AS b ON a.ServiceNo = b.ServiceNo

							LEFT JOIN tblterminaldetail AS c ON b.TerminalID = c.TerminalID

							LEFT JOIN tblsimdetail AS d ON b.SIMID = d.SIMID

							LEFT JOIN tblirdetail AS e ON a.IRIDNo = e.IRIDNo

							LEFT JOIN tblparticular AS f ON b.FEID = f.ParticularID

							LEFT JOIN tblparticular AS g ON a.MerchantID = g.ParticularID

							) AS xTable');

							

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

				

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			IF (v_OffSetTo > 0)

			THEN	

				SET v_OffSet = 0;

				

				IF (v_OffSetFrom <= 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;

				

				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

				

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;				

					

		ELSE		

			SELECT 

			FSRID, 

			`No`, 

			Merchant, 

			`MID`, 

			TID, 

			TimeArrived,

			TimeStart, 

			FSR, 

			FSRDate, 

			FSRTime, 

			TimeEnd, 

			TerminalSN, 

			MerchantContactNo, 

			MerchantRepresentative, 

			FEName, 

			SerialNo

			FROM   

			tblfsrdetail

			ORDER BY 

			FSRID;

		END IF;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'FSR')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			

			SELECT      DISTINCT FSRID, `No`, Merchant, `MID`, TID, TimeArrived, TimeStart, FSR, FSRDate, FSRTime, TimeEnd, TerminalSN, MerchantContactNo, MerchantRepresentative, FEName, SerialNo  						

			FROM        tblfsrdetail

			WHERE       (FSR LIKE p_SearchValue);

            

        ELSEIF (p_SearchBy = 'TerminalSN')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			

			SELECT      DISTINCT FSRID, `No`, Merchant, `MID`, TID, TimeArrived, TimeStart, FSR, FSRDate, FSRTime, TimeEnd, TerminalSN, MerchantContactNo, MerchantRepresentative, FEName, SerialNo  						

			FROM        tblfsrdetail

			WHERE       (TerminalSN LIKE p_SearchValue);    

		

	ELSEIF (p_SearchBy = 'FSRID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			

			SELECT      DISTINCT FSRID, `No`, Merchant, `MID`, TID, TimeArrived, TimeStart, FSR, FSRDate, FSRTime, TimeEnd, TerminalSN, MerchantContactNo, MerchantRepresentative, FEName, SerialNo   						

			FROM        tblfsrdetail

			WHERE       (FSRID = v_ID);

			

	ELSEIF (p_SearchBy = 'FSRNo')

        THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			

			

			SELECT      

			FSRNo, 

			FSRID,

			ServiceNo,

			IRIDNo,

			TAIDNo,

			IRNo, 			

			Merchant, 

			TID, 

			`MID`, 	

			IFNULL(TerminalSN, "-") AS TerminalSN,

			IFNULL(SIMSN, "-") AS SIMSN,

			IFNULL(PowerSN, "-") AS PowerSN,

			IFNULL(DockSN, "-") AS DockSN, 				

			TimeArrived, 

			TimeStart, 

			FSR, 

			FSRDate, 

			FSRTime, 

			TimeEnd, 			

			MerchantContactNo, 

			MerchantRepresentative, 

			FEName, 

			SerialNo,			

			IFNULL(ActionMade, "-") AS ActionMade,			

			IFNULL(ProblemReported, "-") AS ProblemReported,

			IFNULL(ActualProblemReported, "-") AS ActualProblemReported,

			IFNULL(ActionTaken, "-") AS ActionTaken,

			ServiceStatus,

			ServiceStatusDescription			

			FROM        tblfsrdetail

			WHERE       (FSRNo = v_ID);						

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewFSRAttempt` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewFSRAttempt` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewFSRAttempt`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

DECLARE v_ID INTEGER;

DECLARE v_TAIDNo INT;

DECLARE v_ClientID INT;

DECLARE v_TID VARCHAR(45);

DECLARE v_MID VARCHAR(45);

DECLARE v_IRNo VARCHAR(45);

DECLARE p_WHERE LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN

		SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

		SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

		SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

		

		SET p_WHERE = '';			

		IF (v_TAIDNo > 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TAIDNo = ');

			SET p_WHERE = CONCAT(p_WHERE, v_TAIDNo);

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;

		

		IF (v_ClientID > 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ClientID = ');

			SET p_WHERE = CONCAT(p_WHERE, v_ClientID);

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;

		

		IF (STRCMP(v_TID, "0") != 0)

		THEN				

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TID = ');

			SET p_WHERE = CONCAT(p_WHERE, "'", v_TID, "'");	

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

		END IF;

		

		IF (STRCMP(v_MID, "0") != 0)

		THEN				

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.MID = ');

			SET p_WHERE = CONCAT(p_WHERE, "'", v_MID, "'");	

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

		END IF;

		

		IF (STRCMP(v_IRNo, "0") != 0)

		THEN				

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.IRNo = ');

			SET p_WHERE = CONCAT(p_WHERE, "'", v_IRNo, "'");	

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

		END IF;

		

		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

		

		SET p_SQL = '';	

		SET p_SQL = CONCAT(p_SQL,'SELECT');

		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.FSRNo, 0) AS FSRNo,							

						IFNULL(a.FSRDate, "-") AS FSRDate,

						IFNULL(a.FSRTime, "-") AS FSRTime,

						IFNULL(a.ServiceStatus, 0) AS ServiceStatus,

						IFNULL(a.ServiceStatusDescription, "-") AS ServiceStatusDescription,

						IFNULL(a.Remarks, "-") AS Remarks															

						FROM tblfsrdetail AS a');

		

		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('Before:p_SQL = ', p_SQL);

					

		IF (LENGTH(p_WHERE) > 0)

		THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

			SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

		END IF;

		SET p_SQL = REPLACE(p_SQL, '"', "'");			

		

		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

		

		SET p_ORDERBY = '';

		SET p_ORDERBY = 'a.FSRNo ASC';

		IF (LENGTH(p_ORDERBY) > 0)

		THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

		END IF;

			

		SET @QUERY = p_SQL;

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

							

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						ReasonID,

						`Code`,

						Description

			FROM        tblreason

			WHERE       (Description LIKE p_SearchValue)

			ORDER BY Description;

		

		ELSEIF (p_SearchBy = 'ReasonID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						ReasonID,

						`Code`,

						Description

			FROM        tblreason

			WHERE       (ReasonID = v_ID)

			ORDER BY Description;				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewHeader` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewHeader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewHeader`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT 

        IFNULL_NUMERIC(HeaderID) AS HeaderID, 

        IFNULL_STRING(`Name`) as `Name`,

        IFNULL_STRING(Header1) as Header1,

        IFNULL_STRING(Header2) AS Header2,

        IFNULL_STRING(Header3) AS Header3,

        IFNULL_STRING(Header4) AS Header4,

        IFNULL_STRING(Header5) AS Header5

		FROM   tblheader

		ORDER BY HeaderID;

	END IF;

      

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewHoliday` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewHoliday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewHoliday`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_Active INTEGER;

	DECLARE v_Description VARCHAR(45);

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Holiday')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT 

			HolidayID,

			HolidayDate,

			Description,

			isActive

			FROM

			tblholiday

			WHERE 

			(HolidayID = v_ID AND isActive > 0)

			ORDER BY Description;

			

		ELSEIF (p_SearchBy = 'Holiday List')

		THEN

			SET v_Active = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT 

			HolidayID, 

			HolidayDate,		

			Description,

			isActive

			FROM

			tblholiday

			WHERE isActive > 0

			ORDER BY HolidayDate;

		END IF;

		

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

		THEN

			SET v_Description = ADD_PERCENT_CHAR(SPLIT_STRING(p_SearchValue, '|' ,1));

			

			SELECT 

			HolidayID, 

			HolidayDate,		

			Description,

			isActive

			FROM   

			tblholiday

			WHERE

			(Description LIKE v_Description);

		ELSEIF (p_SearchBy = 'HolidayID')

		THEN			

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT 

			HolidayID, 

			HolidayDate,		

			Description,

			isActive

			FROM   

			tblholiday

			WHERE 

			(HolidayID = v_ID);			

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewInfo` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewInfo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewInfo`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

    IN p_SearchBy VARCHAR(255) /* = NULL */ ,

    IN p_SearchValue VARCHAR(255) /* = NULL */ ,

    OUT p_outInfo TEXT

)
BEGIN

DECLARE v_Info TEXT;

DECLARE v_outInfo TEXT;

DECLARE v_Count TEXT;

DECLARE v_SearchQuery VARCHAR(200);

DECLARE p_WHERE LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

DECLARE p_TempQuery LONGTEXT;

DECLARE p_INSERT LONGTEXT;

    

IF (p_StatementType = 'Search')

THEN

	IF (p_SearchBy = 'Get Terminal Model Code')

	THEN		

		SET p_SearchValue = CONCAT("'", p_SearchValue, "'");

		

		#SELECT CONCAT("Out::p_SearchValue=", p_SearchValue);

		

		SET p_WHERE = '';						

		SET p_SQL = '';	

		SET p_SQL = CONCAT(p_SQL,'SELECT');

		SET p_SQL = CONCAT(p_SQL, ' ', 'Code AS v_Count

					FROM   tblterminalmodel AS a

					WHERE Description = ', p_SearchValue);

							

		#SELECT CONCAT("p_SQL=", p_SQL);

		

		DROP TEMPORARY TABLE IF EXISTS tbltemp;

		SET p_TempQuery = '';

		SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltemp (xCount VARCHAR(45) NOT NULL)');

		SET @QUERY = p_TempQuery;

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		SET p_INSERT = '';

		SET p_INSERT = 'INSERT INTO tbltemp (xCount)';

		SET @QUERY = '';	

		SET @QUERY = CONCAT(p_INSERT, p_SQL);

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

		SELECT xCount INTO v_Count 

		FROM tbltemp;

							

	END IF;

		

	#SELECT CONCAT("v_outInfo=", v_outInfo);

	

	IF (LENGTH(v_Count) > 0)

	THEN

		SET p_outInfo = v_Count;

	ELSE

		SET p_outInfo = "-";

	END IF;

	

	

		

END IF;

        

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewIRMaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewIRMaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewIRMaster`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(100) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT IRID, ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy

		FROM   tblinstallationrequestmaster

		ORDER BY FSRID;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'FileName')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT IRID, ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy  						

			FROM        tblinstallationrequestmaster

			WHERE       (FileName LIKE p_SearchValue);

            

        ELSEIF (p_SearchBy = 'ProcessedBy')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT IRID, ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy

			FROM        tblinstallationrequestmaster

			WHERE       (ProcessedBy LIKE p_SearchValue);    

		

		ELSEIF (p_SearchBy = 'IRID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT IRID, ImportDateTime, FilePath, FileName, Remarks, DateTimeModified, ProcessedBy, ModifiedBy

			FROM        tblinstallationrequestmaster

			WHERE       (IRID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewItem` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewItem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewItem`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

    DECLARE v_ID INTEGER;

    DECLARE v_Active INTEGER;

    

    DECLARE p_WHERE LONGTEXT;

    DECLARE p_GROUPBY LONGTEXT;

    DECLARE p_ORDERBY LONGTEXT;

    DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Item')		

			THEN

				SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

				SET v_Active = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

				

				SET p_WHERE = ''; 			

				IF (v_ID > 0)

				THEN

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.STTid = ');

					SET p_WHERE = CONCAT(p_WHERE, v_ID);

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				END IF;

				

				IF (v_Active > 0)

				THEN

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive = ');

					SET p_WHERE = CONCAT(p_WHERE, v_Active);

					SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				END IF;

				

				SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

				#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

				#SELECT CONCAT('p_WHERE = ', p_WHERE);

				

				SET p_SQL = '';	

				SET p_SQL = CONCAT(p_SQL,'SELECT');				

				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.isActive, 0) AS isActive,

								IFNULL(a.prtid, 0) AS PRTid,

								IFNULL(a.catid, 0) AS CATid,

								IFNULL(a.sztid, 0) AS SZTid,

								IFNULL(a.szCode, "-") AS szCode,

								IFNULL(a.szDescription, "-") AS szDescription,

								IFNULL(a.szImage, "-") AS szImage,

								IFNULL(a.dblPrice, 0) AS dblPrice,

								IFNULL(a.dblCost, 0) AS dblCost,

								IFNULL(a.dblPercentDisc, 0) AS dblPercentDisc

								FROM otblprt AS a				

								LEFT JOIN otblspt AS b ON a.PRTid = b.PRTid');

								

				#SELECT CONCAT('Before Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('Before p_SQL = ', p_SQL);				

								

				IF (LENGTH(p_WHERE) > 0)

				THEN

					SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

					SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

				END IF;

				SET p_SQL = REPLACE(p_SQL, '"', "'");	

				#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

				#SELECT CONCAT('p_SQL = ', p_SQL);	

			

				SET @QUERY = p_SQL;

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;						

							

		ELSEIF (p_SearchBy = 'Size')

			THEN

				SELECT 

				otblszt.isActive AS isActive,

				otblszt.sztid AS SZTid,	

				otblszt.szCode AS szCode,

				otblszt.szDescription AS szDescription

				FROM otblszt;	

		ELSEIF (p_SearchBy = 'Category')

			THEN

				SELECT 

				otblcat.isActive AS isActive,

				otblcat.catid AS CATid,	

				otblcat.szCode AS szCode,

				otblcat.szDescription AS szDescription

				FROM otblcat;			

		ELSE			

				SELECT 

				otblprt.isActive AS isActive,

				otblprt.prtid AS PRTid,	

				otblprt.szCode AS szCode,

				otblprt.szDescription AS szPRTDescription

				FROM otblprt

				LEFT JOIN otblspt ON otblprt.prtid = otblspt.sptid

				LEFT JOIN otblszt ON otblspt.sztid = otblszt.sztid  

				WHERE otblprt.isActive = 1 AND otblspt.isActive = 1;		

		END IF;

       

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewLeaveDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewLeaveDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewLeaveDetail`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_ParticularID INTEGER;	

	DECLARE v_ParticularTypeID INTEGER;

	DECLARE v_ParticularName VARCHAR(45);	

	DECLARE v_LeaveTypeID INTEGER;

	DECLARE v_DepartmentID INTEGER;	

	DECLARE v_DateFrom DATE;

	DECLARE v_DateTo DATE;

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

		

    IF (p_StatementType = 'View')

