/* Procedure structure for procedure `spViewLeaveType` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewLeaveType` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewLeaveType`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_Active INTEGER;

	DECLARE v_Description VARCHAR(45);

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'LeaveType')

		THEN

			SELECT 

			LeaveTypeID,

			`Code`,

			Description,

			CreditLimit,

			isActive

			FROM

			tblleavetype

			WHERE 

			(isActive > 0)

			ORDER BY Description;

			

		ELSEIF (p_SearchBy = 'LeaveType List')

		THEN

			SET v_Active = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT 

			LeaveTypeID,

			`Code`,

			Description,

			CreditLimit,

			isActive

			FROM

			tblleavetype

			WHERE

			(isActive > 0)

			ORDER BY Description;

		END IF;

		

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

		THEN

			SET v_Description = ADD_PERCENT_CHAR(SPLIT_STRING(p_SearchValue, '|' ,1));

			

			SELECT 

			LeaveTypeID,

			`Code`,

			Description,

			CreditLimit,

			isActive

			FROM

			tblleavetype

			WHERE 

			(Description LIKE v_Description);

		ELSEIF (p_SearchBy = 'LeaveTypeID')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT 

			LeaveTypeID,

			`Code`,

			Description,

			CreditLimit,

			isActive

			FROM

			tblleavetype

			WHERE 

			(LeaveTypeID = v_ID);		

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewMapping` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewMapping` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewMapping`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Type')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						MapID, 

                        MapFrom, 

                        MapTo, 

                        Delimeter,

                        ColumnIndex,

                        isMust,

                        IFNULL_STRING_ONLY(`Format`) as `Format`

			FROM        tblmapping

			WHERE       (`TYPE` LIKE p_SearchValue AND isActive > 0)

			ORDER BY ColumnIndex;

        ELSE

        

			SELECT MapID, 

			MapFrom, 

			MapTo, 

			Delimeter, 

			ColumnIndex,

			isMust,

                        IFNULL_STRING_ONLY(`Format`) AS `Format`

			FROM   tblmapping

			ORDER BY ColumnIndex;

		END IF;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'MapFrom')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						MapID, 

                        MapFrom, 

                        MapTo, 

                        Delimeter,

                        ColumnIndex,

                        isMust,

                        IFNULL_STRING_ONLY(`Format`) AS `Format`

			FROM        tblmapping

			WHERE       (MapFrom LIKE p_SearchValue);

            

        ELSEIF (p_SearchBy = 'MapTo')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						MapID, 

                        MapFrom, 

                        MapTo, 

                        Delimeter,

                        ColumnIndex,

                        isMust,

                        IFNULL_STRING_ONLY(`Format`) AS `Format`

			FROM        tblmapping

			WHERE       (MapTo LIKE p_SearchValue);    		

		ELSEIF (p_SearchBy = 'ID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						MapID, 

                        MapFrom, 

                        MapTo, 

                        Delimeter,

                        ColumnIndex,

                        isMust,

                        IFNULL_STRING_ONLY(`Format`) AS `Format`

			FROM        tblmapping

			WHERE       (MapID = v_ID);				            

		 END IF;         

	END IF; 

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewMasterFile` */

