			TypeID,

			TypeDescription,

			ModelID,

			ModelDescription,

			Description,

			UoMID,

			UoMDescription,

			SerialNo,

			Barcode,

			OnHand,

			StatusID,

			StatusDescription,

            DateTimeProcessed, 

            DateTimeModified, 

            ProcessedBy, 

            ModifiedBy

			FROM tblmasterfile

			WHERE       (Description LIKE p_SearchValue)

            LIMIT 1;

		

        ELSEIF (p_SearchBy = 'SerialNo')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

			ProductID,

			TypeID,

			TypeDescription,

			ModelID,

			ModelDescription,

			Description,

			UoMID,

			UoMDescription,

			SerialNo,

			Barcode,

			OnHand,

			StatusID,

			StatusDescription,

            DateTimeProcessed, 

            DateTimeModified, 

            ProcessedBy, 

            ModifiedBy

			FROM tblmasterfile

			WHERE       (SerialNo LIKE p_SearchValue)

            LIMIT 1;

            

		ELSEIF (p_SearchBy = 'ProductID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			ProductID,

			TypeID,

			TypeDescription,

			ModelID,

			ModelDescription,

			Description,

			UoMID,

			UoMDescription,

			SerialNo,

			Barcode,

			OnHand,

			StatusID,

			StatusDescription,

            DateTimeProcessed, 

            DateTimeModified, 

            ProcessedBy, 

            ModifiedBy

			FROM tblmasterfile

			WHERE       (ProductID = v_ID)

            LIMIT 1;

                    

        ELSEIF (p_SearchBy = 'TypeID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			ProductID,

			TypeID,

			TypeDescription,

			ModelID,

			ModelDescription,

			Description,

			UoMID,

			UoMDescription,

			SerialNo,

			Barcode,

			OnHand,

			StatusID,

			StatusDescription,

            DateTimeProcessed, 

            DateTimeModified, 

            ProcessedBy, 

            ModifiedBy

			FROM tblmasterfile

			WHERE       (TypeID = v_ID)

            LIMIT 1;

          

	    ELSEIF (p_SearchBy = 'ModelID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			ProductID,

			TypeID,

			TypeDescription,

			ModelID,

			ModelDescription,

			Description,

			UoMID,

			UoMDescription,

			SerialNo,

			Barcode,

			OnHand,

			StatusID,

			StatusDescription,

            DateTimeProcessed, 

            DateTimeModified, 

            ProcessedBy, 

            ModifiedBy

			FROM tblmasterfile

			WHERE       (ModelID = v_ID)

            LIMIT 1;

         

		ELSEIF (p_SearchBy = 'StatusID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			ProductID,

			TypeID,

			TypeDescription,

			ModelID,

			ModelDescription,

			Description,

			UoMID,

			UoMDescription,

			SerialNo,

			Barcode,

			OnHand,

			StatusID,

			StatusDescription,

            DateTimeProcessed, 

            DateTimeModified, 

            ProcessedBy, 

            ModifiedBy

			FROM tblmasterfile

			WHERE       (StatusID = v_ID)

            LIMIT 1;

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewMerchant` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewMerchant` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewMerchant`(  



    p_StatementType VARCHAR(30) /* = NULL */ ,



	p_SearchBy VARCHAR(50) /* = NULL */ ,



	p_SearchValue VARCHAR(50) /* = NULL */



)
BEGIN



	DECLARE v_ID INTEGER;



    



    IF (p_StatementType = 'View')



	THEN



		SELECT  DISTINCT



				MerchantID,



				NAME AS MerchantName, 



				Address, 



				CityID,



				City,



				ProvinceID,



				ProvinceName,



				ContactPerson, 



				ContactNo



		FROM   tblmerchant



		ORDER BY NAME;



    ELSEIF (p_StatementType = 'Search')



    THEN



		IF (p_SearchBy = 'Name')



        THEN



			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');



			SELECT      DISTINCT   



						MerchantID,



						NAME AS MerchantName, 



                        Address, 



                        CityID,



                        City,



                        ProvinceID,



                        ProvinceName,



                        ContactPerson, 



                        ContactNo



			FROM        tblmerchant



			WHERE       (NAME LIKE p_SearchValue);



		



		ELSEIF (p_SearchBy = 'MerchantID')



        THEN



			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);



			SELECT      DISTINCT   



						MerchantID,



						NAME AS MerchantName, 



                        Address, 



                        CityID,



                        City,



                        ProvinceID,



                        ProvinceName,



                        ContactPerson, 



                        ContactNo



			FROM        tblmerchant



			WHERE       (MerchantID = v_ID);				



            



		 END IF;



         



	END IF;    



END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewNotification` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewNotification` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewNotification`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_UserID INTEGER;

	DECLARE v_UserType VARCHAR(45);

	DECLARE v_LogDateFrom VARCHAR(45);

	DECLARE v_LogDateTo VARCHAR(45);

	DECLARE v_UserAction VARCHAR(45);

	DECLARE v_SessionStatus INTEGER;

   

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;	

	

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Email Notif')

		THEN			

			SET p_WHERE = '';

					    

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.NotifID, 0) AS NotifID,

							IFNULL(DATE_FORMAT(a.NotifDateTime, "%m-%d-%Y %h:%i %p"), "-") AS NotifDateTime,

							IFNULL(a.UserID, 0) AS UserID,

							IFNULL(a.ServiceNo, 0) AS ServiceNo,

							IFNULL(a.TAIDNo, 0) AS TAIDNo,

							IFNULL(a.IRIDNo, 0) AS IRIDNo,

							IFNULL(a.ClientID, 0) AS ClientID,

							IFNULL(a.MerchantID, 0) AS MerchantID,

							IFNULL(a.FEID, 0) AS FEID,					

							IFNULL(b.FullName, "-") AS FullName,

							IFNULL(c.`Name`, "-") AS ClientName,

							IFNULL(d.`Name`, "-") AS MerchantName,

							IFNULL(e.`Name`, "-") AS FEName,

							IFNULL(g.TID, "-") AS TID,

							IFNULL(g.MID, "-") AS MID,

							IFNULL(f.IRNo, "-") AS IRNo,

							IFNULL(f.RequestNo, "-") AS RequestNo,

							IFNULL(f.TerminalSN, "-") AS TerminalSN,

							IFNULL(f.SIMSerialNo, "-") AS SIMSN,

							IFNULL(f.DockSN, "-") AS DockSN,

							IFNULL(e.Email, "-") AS Email,

							IFNULL(e.Mobile, "-") AS Mobile,																						

							IFNULL(a.JobTypeDescription, "-") AS JobTypeDescription,							

							IFNULL(a.ReportType, 0) AS ReportType,

							IFNULL(a.ReportTypeDescription, "-") AS ReportTypeDescription,

							IFNULL(a.NotifType, 0) AS NotifType,

							IFNULL(a.NotifDescription, "-") AS NotifDescription

							FROM tblnotifyemail AS a

							LEFT JOIN tbluser AS b ON a.UserID = b.UserID

							LEFT JOIN tblparticular AS c ON a.ClientID = c.ParticularID AND c.ParticularTypeID = 2

							LEFT JOIN tblparticular AS d ON a.MerchantID = d.ParticularID AND d.ParticularTypeID = 1

							LEFT JOIN tblparticular AS e ON a.FEID = e.ParticularID AND e.ParticularTypeID = 3

							LEFT JOIN tblservicingdetail AS f ON a.ServiceNo = f.ServiceNo

							LEFT JOIN tblterminalallocation AS g ON a.TAIDNo = g.TAIDNo');	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.NotifID';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

		ELSEIF (p_SearchBy = 'SMS Notif')

		THEN			

			SET p_WHERE = '';

					    

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.NotifID, 0) AS NotifID,

							IFNULL(DATE_FORMAT(a.NotifDateTime, "%m-%d-%Y %h:%i %p"), "-") AS NotifDateTime,

							IFNULL(a.UserID, 0) AS UserID,

							IFNULL(a.ServiceNo, 0) AS ServiceNo,

							IFNULL(a.TAIDNo, 0) AS TAIDNo,

							IFNULL(a.IRIDNo, 0) AS IRIDNo,

							IFNULL(a.ClientID, 0) AS ClientID,

							IFNULL(a.MerchantID, 0) AS MerchantID,

							IFNULL(a.FEID, 0) AS FEID,					

							IFNULL(b.FullName, "-") AS FullName,

							IFNULL(c.`Name`, "-") AS ClientName,

							IFNULL(d.`Name`, "-") AS MerchantName,

							IFNULL(e.`Name`, "-") AS FEName,

							IFNULL(g.TID, "-") AS TID,

							IFNULL(g.MID, "-") AS MID,

							IFNULL(f.IRNo, "-") AS IRNo,

							IFNULL(f.RequestNo, "-") AS RequestNo,

							IFNULL(f.TerminalSN, "-") AS TerminalSN,

							IFNULL(f.SIMSerialNo, "-") AS SIMSN,

							IFNULL(f.DockSN, "-") AS DockSN,

							IFNULL(e.Email, "-") AS Email,

							IFNULL(e.Mobile, "-") AS Mobile,																						

							IFNULL(a.JobTypeDescription, "-") AS JobTypeDescription,							

							IFNULL(a.ReportType, 0) AS ReportType,

							IFNULL(a.ReportTypeDescription, "-") AS ReportTypeDescription,

							IFNULL(a.NotifType, 0) AS NotifType,

							IFNULL(a.NotifDescription, "-") AS NotifDescription

							FROM tblnotifysms AS a

							LEFT JOIN tbluser AS b ON a.UserID = b.UserID

							LEFT JOIN tblparticular AS c ON a.ClientID = c.ParticularID AND c.ParticularTypeID = 2

							LEFT JOIN tblparticular AS d ON a.MerchantID = d.ParticularID AND d.ParticularTypeID = 1

							LEFT JOIN tblparticular AS e ON a.FEID = e.ParticularID AND e.ParticularTypeID = 3

							LEFT JOIN tblservicingdetail AS f ON a.ServiceNo = f.ServiceNo

							LEFT JOIN tblterminalallocation AS g ON a.TAIDNo = g.TAIDNo');	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.NotifID';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;		

		END IF;				        

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewOtherServiceType` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewOtherServiceType` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewOtherServiceType`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT OtherServiceTypeID, Description

		FROM   tblotherservicetype

		ORDER BY Description;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						OtherServiceTypeID,

						Description

			FROM        tblotherservicetype

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'OtherServiceTypeID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						OtherServiceTypeID,

						Description

			FROM        tblotherservicetype

			WHERE       (OtherServiceTypeID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewParticularDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewParticularDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewParticularDetail`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_ParticularID INTEGER;	

	DECLARE v_ParticularTypeID INTEGER;

	DECLARE v_ParticularName VARCHAR(45);	

	DECLARE v_LeaveTypeID INTEGER;

	DECLARE v_DepartmentID INTEGER;	

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Particular Detail')

		THEN

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);		

			SET v_ParticularName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET p_WHERE = '';

			

			# ParticularID		

			IF (v_ParticularID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;	

			# Particular Name		

			IF (STRCMP(v_ParticularName, "0") != 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Name = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ParticularName, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;	

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ParticularID, 0) AS ParticularID, 														

							IFNULL(a.ParticularTypeID, 0) AS ParticularTypeID,

							IFNULL(a.ParticularDescription, "-") AS ParticularDescription,

							IFNULL(a.`Name`, "-") AS `Name`,

							IFNULL(a.`Code`, "-") AS `Code`,

							IFNULL(a.Address, "-") AS Address,

							IFNULL(a.Address2, "-") AS Address2,

							IFNULL(a.Address3, "-") AS Address3,

							IFNULL(a.Address4, "-") AS Address4,

							IFNULL(a.ContactPerson, "-") AS ContactPerson,

							IFNULL(a.TelNo, "-") AS TelNo,

							IFNULL(a.Mobile, "-") AS Mobile,

							IFNULL(a.Fax, "-") AS Fax,

							IFNULL(a.Email, "-") AS Email,

							IFNULL(a.ContractTerms, "-") AS ContractTerms,

							IFNULL(a.RegionID, 0) AS RegionID,

							IFNULL(b.RegionType, 0) AS RegionType,

							IFNULL(c.Region, "-") AS Region,

							IFNULL(b.Province, "-") AS Province,

							IFNULL(a.EmploymentStatus, "-") AS EmploymentStatus,

							IFNULL(a.DepartmentID, 0) AS DepartmentID,

							IFNULL(d.Description, "-") AS Department,

							IFNULL(a.PositionID, 0) AS PositionID,

							IFNULL(e.Description, "-") AS Position,

							IFNULL(a.ComputerName, "-") AS ComputerName,

							IFNULL(a.isActive, 0) AS isActive,

							IFNULL(a.isWorkArrangement, 0) AS isWorkArrangement,

							IFNULL(a.isTimeSheet, 0) AS isTimeSheet,

							IFNULL(a.isAppVersion, 0) AS isAppVersion,

							IFNULL(a.RentalType, 0) AS RentalType,

							IFNULL(a.RentalTerms, 0) AS RentalTerms,

							IFNULL(a.AccountNo, 0) AS AccountNo,

							IFNULL(a.CustomerNo, 0) AS CustomerNo,
							
							IFNULL(a.ZoneID, 0) AS ZoneID

							FROM tblparticular AS a							

							LEFT JOIN tblregiondetail AS b ON a.RegionID = b.RegionID

							LEFT JOIN tblregion AS c ON b.RegionType = c.RegionID

							LEFT JOIN tbldepartment AS d ON a.DepartmentID = d.DepartmentID

							LEFT JOIN tblposition AS e ON a.PositionID = e.PositionID');



			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Get ClientID')	

		THEN

			SET v_ParticularTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ParticularName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			

			SET p_WHERE = '';

			

			IF (v_ParticularTypeID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularTypeID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ParticularTypeID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;

			

			# Particular Name		

			IF (STRCMP(v_ParticularName, "0") != 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Name = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ParticularName, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;	

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ParticularID, 0) AS ParticularID,

							IFNULL(a.`Name`, "-") AS ParticularName							

							FROM tblparticular AS a');



			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Client Dashboard Detail')	

		THEN

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);			

			

			SET p_WHERE = '';

			

			IF (v_ParticularID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ParticularID, 0) AS ParticularID,

							IFNULL(a.`Name`, "-") AS ParticularName,

							IFNULL(a.UserName, "-") AS ParticularUserName,

							IFNULL(a.UserKey, "-") AS ParticularUserKey

							FROM tblparticular AS a');



			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Particular Leave Assignment')

		THEN

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_LeaveTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';

			

			IF (v_ParticularID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;

			

			IF (v_LeaveTypeID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.LeaveTypeID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_LeaveTypeID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.LeaveNo, 0) AS LeaveNo,

							IFNULL(a.ParticularID, 0) AS ParticularID,

							IFNULL(a.LeaveTypeID, 0) AS LeaveTypeID,

							IFNULL(a.CreditLimit, 0) AS CreditLimit,

							IFNULL(a.LeaveCredit, 0) AS LeaveCredit,

							IFNULL(b.Code, "-") AS Code,

							IFNULL(b.Description, "-") AS Description,

							IFNULL(a.Remarks, "-") AS Remarks

							FROM tblleaveassignment AS a

							LEFT JOIN tblleavetype AS b ON a.LeaveTypeID = b.LeaveTypeID');



			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

		

		ELSEIF (p_SearchBy = 'Particular Leave Movement')

		THEN	

					

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';

			

			IF (v_ParticularID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;

			

			# active (tblworkarrangement)

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.LeaveNo, 0) AS LeaveNo,

							IFNULL(a.ParticularID, 0) AS ParticularID,

							IFNULL(a.LeaveTypeID, 0) AS LeaveTypeID,

							IFNULL(a.DateFrom, "-") AS DateFrom,

							IFNULL(a.DateTo, "-") AS DateTo,

							IFNULL(a.Duration, 0) AS Duration,

							IFNULL(a.ProcessedBy, "-") AS ProcessedBy,

							IFNULL(a.ProcessedDateTime, "-") AS ProcessedDateTime,

							IFNULL(a.ModifiedBy, "-") AS ModifiedBy,

							IFNULL(a.ModifiedDateTime, "-") AS ModifiedDateTime,							

							IFNULL(a.DateType, "-") AS DateType,

							IFNULL(a.Remarks, "-") AS Remarks,

							IFNULL(a.isActive, 0) AS isActive,

							IFNULL(b.Code, "-") AS LeaveCode,

							IFNULL(b.Description, "-") AS LeaveDesc,

							IFNULL(a.ReasonID, 0) AS ReasonID,

							IFNULL(c.Code, "-") AS ReasonCode,

							IFNULL(c.Description, "-") AS ReasonDesc

							FROM tblleavemovement AS a

							LEFT JOIN tblleavetype AS b ON a.LeaveTypeID = b.LeaveTypeID

							LEFT JOIN tblreason AS c ON a.ReasonID = c.ReasonID');



			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.LeaveTypeID, a.DateFrom';

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Particular Work Arrangement')

		THEN

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);		

			SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INT);

			#SET v_DateFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS DATE);

			#SET v_DateTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS DATE);

			SET p_WHERE = '';

			IF (v_ParticularID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_DepartmentID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.DepartmentID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_DepartmentID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			# active (tblworkarrangement)

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

				

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ParticularID, 0) AS ParticularID,

						IFNULL(a.WorkArrangementID, 0) AS WorkArrangementID,							

						IFNULL(b.Name, "-") AS FullName,						

						IFNULL(a.DateFrom, "-") AS DateFrom,

						IFNULL(a.DateTo, "-") AS DateTo,				

						IFNULL(a.DateType, "-") AS DateType,

						IFNULL(a.Duration, 0) AS Duration,

						IFNULL(a.Remarks, "-") AS Remarks,

						IFNULL(a.ProcessedBy, "-") AS ProcessedBy,					

						IFNULL(DATE_FORMAT(a.ProcessedDateTime, "%m-%d-%Y %h:%i %p"), "-") AS ProcessedDateTime,

						IFNULL(a.ModifiedBy, "-") AS ModifiedBy,					

						IFNULL(DATE_FORMAT(a.ModifiedDateTime, "%m-%d-%Y %h:%i %p"), "-") AS ModifiedDateTime,					

						IFNULL(b.PositionID, 0) AS PositionID,

						IFNULL(d.Description, "-") AS Position,					

						IFNULL(b.DepartmentID, 0) AS DepartmentID,

						IFNULL(c.Description, "-") AS Department,					

						IFNULL(a.WorkTypeID, 0) AS WorkTypeID,

						IFNULL(e.Code, "-") AS WorkTypeCode,

						IFNULL(e.Description, "-") AS WorkTypeDesc,

						IFNULL(b.EmploymentStatus, "-") AS EmploymentStatus

						FROM tblworkarrangement AS a

						LEFT JOIN tblparticular AS b ON a.ParticularID = b.ParticularID

						LEFT JOIN tbldepartment AS c ON b.DepartmentID = c.DepartmentID

						LEFT JOIN tblposition AS d ON b.PositionID = d.PositionID

						LEFT JOIN tblworktype AS e ON a.WorkTypeID = e.WorkTypeID');

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

					

			IF (LENGTH(p_WHERE) > 0)

			THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

			SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.WorkTypeID, a.DateFrom';

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		END IF;		

    END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewPosition` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewPosition` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewPosition`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_Active INTEGER;

	DECLARE v_Description VARCHAR(45);

	DECLARE v_DepartmentID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Position')

		THEN			

			SELECT 

			PositionID,			

			Description,

			isActive

			FROM

			tblposition

			WHERE 

			(isActive > 0)

			ORDER BY Description;

		

		ELSEIF (p_SearchBy = 'Position By Department')

		THEN

			SET v_Active = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);

			SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INT);

			

			SELECT 

			PositionID,			

			Description,

			isActive

			FROM

			tblposition

			WHERE 

			(isActive > 0 AND DepartmentID = v_DepartmentID)

			ORDER BY Description;

			

		ELSEIF (p_SearchBy = 'Position List')

		THEN

			SELECT

			PositionID,			

			Description,

			isActive

			FROM

			tblposition

			WHERE 

			(isActive > 0)

			ORDER BY Description;

		END IF;		  

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewPrivacy` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewPrivacy` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewPrivacy`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

    DECLARE v_ID INTEGER;

    DECLARE v_UserID INTEGER;

    DECLARE v_PrivacyID INTEGER;

    DECLARE v_isActive INTEGER;

    

    DECLARE p_WHERE LONGTEXT;

    DECLARE p_ORDERBY LONGTEXT;

    DECLARE p_GROUPBY LONGTEXT;

    DECLARE p_SQL LONGTEXT;	

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Privacy Detail')

		THEN

			SET v_UserID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_PrivacyID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';			

			IF (v_PrivacyID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.PrivacyID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_PrivacyID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET v_isActive = 1;

			IF (v_isActive > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive = ');

				SET p_WHERE = CONCAT(p_WHERE, v_isActive);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(a.PrivacyID) AS PrivacyID,

							IFNULL_STRING_ONLY(a.Description) AS Description,

							IFNULL_STRING_ONLY(a.Form) AS Form,

							IFNULL_NUMERIC(b.isAdd) AS isAdd,

							IFNULL_NUMERIC(b.isDelete) AS isDelete,

							IFNULL_NUMERIC(b.isUpdate) AS isUpdate,

							IFNULL_NUMERIC(b.isView) AS isView,

							IFNULL_NUMERIC(b.isPrint) AS isPrint,

							(IF(b.PrivacyID > 0, 1, 0)) AS isChecked

							FROM tblprivacymaster a

							LEFT JOIN tblprivacydetail AS b ON a.PrivacyID = b.PrivacyID AND b.UserID = ', v_UserID);	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.PrivacyID';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;		

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

		END IF;										

	END IF;

      

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewProvince` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewProvince` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewProvince`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;	

    

    IF (p_StatementType = 'View')

	THEN

		SELECT 

		IFNULL_NUMERIC(a.ProvinceID) as ProvinceID, 

		IFNULL_STRING_ONLY(a.Name) as `Name`

		FROM   tblprovince a

		ORDER BY a.Name;

    ELSEIF (p_StatementType = 'Search')

    THEN				

		IF (p_SearchBy = 'Province')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

			IFNULL_NUMERIC(a.ProvinceID) AS ProvinceID, 

			IFNULL_STRING_ONLY(a.Name) AS `Name`

			FROM        tblprovince a

			WHERE       (a.Name LIKE p_SearchValue);

        

        ELSEIF (p_SearchBy = 'Name')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

			IFNULL_NUMERIC(a.ProvinceID) AS ProvinceID, 

			IFNULL_STRING_ONLY(a.Name) AS `Name`

			FROM        tblprovince a

			WHERE       (a.Name LIKE p_SearchValue);

            

		ELSEIF (p_SearchBy = 'ProvinceID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

					IFNULL_NUMERIC(a.ProvinceID) AS ProvinceID, 

					IFNULL_STRING_ONLY(a.Name) AS `Name`

			FROM        tblprovince a

			WHERE       (a.ProvinceID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewReason` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewReason` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewReason`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

DECLARE v_ID INTEGER;

DECLARE v_ReasonID INT;

DECLARE v_ReasonDescription VARCHAR(45);

DECLARE v_Type VARCHAR(45);

DECLARE p_WHERE LONGTEXT;

DECLARE p_SQL LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN

		SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

		SET v_ReasonDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

		SET v_Type = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		

		SET p_WHERE = '';			

		IF (v_ReasonID > 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ReasonID = ');

			SET p_WHERE = CONCAT(p_WHERE, v_ReasonID);

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;

		

		IF (STRCMP(v_ReasonDescription, "0") != 0)

		THEN				

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.`Description` LIKE ');

			SET p_WHERE = CONCAT(p_WHERE, "'%", v_ReasonDescription, "%'");	

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

		END IF;

		

		IF (STRCMP(v_Type, "0") != 0)

		THEN				

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.`Type` = ');

			SET p_WHERE = CONCAT(p_WHERE, "'", v_Type, "'");	

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

		END IF;

		# Include isActive
		SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 ');
		SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

		

		SET p_SQL = '';	

		SET p_SQL = CONCAT(p_SQL,'SELECT');

		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ReasonID, 0) AS ReasonID,							

						IFNULL(a.`Code`, "-") AS `Code`,

						IFNULL(a.Description, "-") AS Description,

						IFNULL(a.`Type`, "-") AS `Type`,
						
						IFNULL(a.isInput, 0) AS isInput,
						
						IFNULL(a.FunctionID, 0) AS FunctionID

						FROM tblreason AS a');

		

		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('Before:p_SQL = ', p_SQL);

					

		IF (LENGTH(p_WHERE) > 0)

		THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

			SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

		END IF;

		SET p_SQL = REPLACE(p_SQL, '"', "'");			

		

		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

		

		SET p_ORDERBY = '';

		SET p_ORDERBY = 'a.Description ASC';

		IF (LENGTH(p_ORDERBY) > 0)

		THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

		END IF;

		

		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

		

		SET @QUERY = p_SQL;

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

							

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						ReasonID,

						`Code`,

						Description,
						
						isInput,
						
						FunctionID

			FROM        tblreason

			WHERE       (Description LIKE p_SearchValue)

			ORDER BY Description;

		

		ELSEIF (p_SearchBy = 'ReasonID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						ReasonID,

						`Code`,

						Description,
						
						isInput,
						
						FunctionID

			FROM        tblreason

			WHERE       (ReasonID = v_ID)

			ORDER BY Description;				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewReceiveFormDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewReceiveFormDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewReceiveFormDetail`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT DISTINCT 

		RequestID,

		ProductID,

		TerminalType,

		TerminalModel,

		SerialNo,

		TID,

		MID,

		AdapterSerialNo,

		SIMCardNo

		FROM   tblreceiveformdetail;

		

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'RequestID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			RequestID,

			ProductID,

			TerminalType,

			TerminalModel,

			SerialNo,

			TID,

			MID,

			AdapterSerialNo,

			SIMCardNo

			FROM        tblreceiveformdetail

			WHERE       (RequestID = v_ID);

            

		ELSEIF (p_SearchBy = 'ProductID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT DISTINCT 

			tblreceiveformmaster.ReceiveID,

			tblreceiveformmaster.ReceiveDate,

			tblreceiveformmaster.ReceivePreparedBy,

            tblreceiveformmaster.RequestID,

			tblreceiveformmaster.ClientName,

			tblreceiveformmaster.MerchantName,

			tblreceiveformmaster.FEName,

			tblreceiveformdetail.SerialNo,

			tblreceiveformdetail.TID,

			tblreceiveformdetail.MID,

			tblreceiveformdetail.AdapterSerialNo,

			tblreceiveformdetail.SIMCardNo,

            tblreceiveformdetail.StatusID,

            tblreceiveformdetail.StatusDescription

			FROM

			tblreceiveformdetail

			INNER JOIN tblreceiveformmaster ON tblreceiveformmaster.ReceiveID = tblreceiveformdetail.ReceiveID

			WHERE

			tblreceiveformdetail.ProductID = v_ID

            ORDER BY ReceiveID;

            

         END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewReceiveFormMaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewReceiveFormMaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewReceiveFormMaster`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT DISTINCT

		tblreceiveformmaster.ReceiveID,

		tblreceiveformmaster.ReceiveDate,

		tblreceiveformmaster.ReceivePreparedBy,

        tblreceiveformmaster.ReceiveDateModified,

		tblreceiveformmaster.ReceiveModifiedBy,

		tblreceiveformmaster.RequestID,

		tblreceiveformmaster.ClientID,

		tblreceiveformmaster.ClientName,

		tblreceiveformmaster.MerchantID,

		tblreceiveformmaster.MerchantName,

		tblreceiveformmaster.FEID,

		tblreceiveformmaster.FEName,

		tblreceiveformmaster.ProblemReported,

		tblreceiveformmaster.ActualProblemFound,

		tblreceiveformmaster.ActionTaken,

		tblreceiveformmaster.AnyComments,

		tblreceiveformmaster.ReceiveStatus,

        tblreceiveformmaster.ReceiveStatusDesc,

		tblreceiveformmaster.DateArrived,

		tblreceiveformmaster.TimeArrived,

		tblreceiveformmaster.StartTime,

		tblreceiveformmaster.EndTime,

		tblrequestformmaster.RequestDate,

		tblrequestformmaster.Remarks,

