			INNER JOIN tblrequestformmaster ON tblreceiveformmaster.RequestID = tblrequestformmaster.RequestID

            WHERE (MerchantID = v_ID)

			LIMIT 1;

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewRegion` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewRegion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewRegion`(  

	p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

	IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'ForDashboard')

		THEN

			SELECT 

			IFNULL(a.RegionID, 0) AS RegionID, 

			IFNULL(a.Region, "-") AS Region, 

			IFNULL(b.TAvailable, 0) AS TAvailable,

			IFNULL(b.TAllocated, 0) AS TAllocated,

			IFNULL(b.TDispatch, 0) AS TDispatch,

			IFNULL(b.TInstalled, 0) AS TInstalled,

			IFNULL(b.TNegative, 0) AS TNegative,

			IFNULL(b.TLastMonthInstalled, 0) AS TInstalledLastMonth,

			IFNULL(b.TThisMonthInstalled, 0) AS TInstalledThisMonth

			FROM

			tblregion a

			LEFT JOIN tbldashboardregion AS b ON a.RegionID = b.RegionID

			WHERE (isActive > 0)

			ORDER BY a.SequenceDisplay;			

		ELSEIF (p_SearchBy = 'RegionDetail')

		THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			

			SELECT RegionID, Province

			FROM   tblregiondetail

			WHERE (RegionType = v_ID)		

			ORDER BY Province;	
			
		ELSEIF (p_SearchBy = 'Region List')
		THEN
			SELECT RegionID, Region

			FROM   tblregion

			WHERE (isActive > 0)

			ORDER BY SequenceDisplay;
		ELSE

			SELECT RegionID, Region

			FROM   tblregion

			WHERE (isActive > 0)

			ORDER BY SequenceDisplay;

		END IF;		

	ELSEIF (p_StatementType = 'Search')

	THEN				

	IF (p_SearchBy = 'Region')

	THEN

		SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

		SELECT      DISTINCT   

			RegionID,

			Region

		FROM        tblregion

		WHERE       (Region LIKE p_SearchValue);

	ELSEIF (p_SearchBy = 'RegionID')

	THEN

		SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

		SELECT      DISTINCT   

			RegionID,

			Region

		FROM        tblregion

		WHERE       (RegionID = v_ID);				

	 END IF;

	END IF;  

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewRegionDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewRegionDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewRegionDetail`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_RegionID INT;

	DECLARE v_RegionType INT;

	DECLARE v_Province VARCHAR(45);

	DECLARE v_Region VARCHAR(45);

	

	DECLARE v_OffSetFrom INTEGER;

	DECLARE v_OffSetTo INTEGER;

	DECLARE v_OffSet INTEGER;

	

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'View')

    THEN

		IF (p_SearchBy = 'Province List')

		THEN

			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_Province = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';			

			IF (v_RegionID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.RegionID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_RegionID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_RegionType > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.RegionType = ');

				SET p_WHERE = CONCAT(p_WHERE, v_RegionType);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_Province, "0") != 0)

			THEN				

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Province LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_Province, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.RegionID, 0) AS RegionID, 

							IFNULL(a.RegionType, 0) AS RegionType, 

							IFNULL(a.Province, "-") AS Province, 

							IFNULL(b.Region, "-") AS Region

							FROM   tblregiondetail AS a

							LEFT JOIN tblregion AS b ON b.RegionID = a.RegionType');

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

			THEN	

				SET v_OffSet = 0;

				

				IF (v_OffSetFrom = 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;

				

				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Region List')

		THEN

			SET v_RegionID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_Region = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';			

			IF (v_RegionID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.RegionID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_RegionID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_RegionType > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.RegionType = ');

				SET p_WHERE = CONCAT(p_WHERE, v_RegionType);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_Region, "0") != 0)

			THEN				

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.Region LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_Region, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.RegionID, 0) AS RegionID, 

							IFNULL(a.RegionType, 0) AS RegionType, 

							IFNULL(a.Province, "-") AS Province, 

							IFNULL(b.Region, "-") AS Region

							FROM   tblregiondetail AS a

							LEFT JOIN tblregion AS b ON b.RegionID = a.RegionType');

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_GROUPBY = '';

			SET p_GROUPBY = 'b.Region';

			IF (LENGTH(p_GROUPBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

			END IF;

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'b.SequenceDisplay';

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

			THEN	

				SET v_OffSet = 0;

				

				IF (v_OffSetFrom = 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;

				

				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

		ELSE

			SELECT 

			IFNULL(a.RegionID, 0) AS RegionID, 

			IFNULL(a.RegionType, 0) AS RegionType, 

			IFNULL(a.Province, "-") AS Province, 

			IFNULL(b.Region, "-") AS Region

			FROM   tblregiondetail AS a

			LEFT JOIN tblregion AS b ON b.RegionID = a.RegionType

			ORDER BY a.Province ASC;

		END IF;

		

    ELSEIF (p_StatementType = 'Search')

    THEN				

		IF (p_SearchBy = 'Province')

		THEN			

			SELECT

			IFNULL(a.RegionID, 0) AS RegionID, 

			IFNULL(a.RegionType, 0) AS RegionType, 

			IFNULL(a.Province, "-") AS Province, 

			IFNULL(b.Region, "-") AS Region

			FROM   tblregiondetail AS a

			LEFT JOIN tblregion AS b ON b.RegionID = a.RegionType

			WHERE (a.Province = p_SearchValue);

					

		ELSEIF (p_SearchBy = 'RegionID')

		THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT

			IFNULL(a.RegionID, 0) AS RegionID, 

			IFNULL(a.RegionType, 0) AS RegionType, 

			IFNULL(a.Province, "-") AS Province, 

			IFNULL(b.Region, "-") AS Region

			FROM   tblregiondetail AS a

			LEFT JOIN tblregion AS b ON b.RegionID = a.RegionType

			WHERE (a.RegionID = v_ID);				           

		END IF;         

     END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewReport` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewReport` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewReport`(  
   p_StatementType VARCHAR(100) /* = NULL */ ,
   p_SearchBy VARCHAR(255) /* = NULL */ ,
   p_SearchValue LONGTEXT /* = NULL */
)
BEGIN	

   DECLARE v_ID INTEGER;



   DECLARE v_ReportType INTEGER;



   #Rocky billing

   DECLARE v_DateFrom VARCHAR(100);

   DECLARE v_DateTo VARCHAR(100);

   DECLARE v_Client VARCHAR(100);

   DECLARE v_JobType INTEGER;

   DECLARE v_JobTypeStatusDescription VARCHAR(100); # eg. PENDING/PROCESSING/COMPLETED

   DECLARE v_ServiceJobTypeDescription VARCHAR(100); # eg. INSTALLATION/SERVICING.... 
   
   DECLARE v_ServiceResult VARCHAR(100); # eg. SUCCESS/NEGATIVE
   
   DECLARE v_DateFilter VARCHAR(100); # eg. TODAY/RANGE

   DECLARE v_ContentType VARCHAR(100);

   DECLARE v_Temp VARCHAR(100);

   DECLARE v_RegionType INT;
   
   DECLARE v_RegionID INT;
   
   DECLARE v_ServiceNo INT;
   DECLARE v_FSRNo INT;
   DECLARE v_IRIDNo INT;
   DECLARE v_ClientID INT;
   DECLARE v_MerchantID INT;
   DECLARE v_FEID INT;
   DECLARE v_DispatcherID INT;
   
   DECLARE v_IncludeBillable VARCHAR(45);
   DECLARE v_FSRMode VARCHAR(45);
   
   DECLARE v_LocationID INT;
   DECLARE v_StatusID INT;
   
   DECLARE v_TerminalTypeID INT;
   DECLARE v_TerminalModelID INT;
   
   DECLARE v_Year VARCHAR(45);
   DECLARE v_MonthName VARCHAR(45);
   DECLARE v_CurrentMonth INT;
   DECLARE v_ActionMade VARCHAR(45);
   DECLARE v_IRNo VARCHAR(45);
   DECLARE v_JobTypeList VARCHAR(45);
   DECLARE v_DispatchID INTEGER;
   DECLARE v_ExcludePending INTEGER;
   DECLARE v_ReasonID INTEGER;
   DECLARE v_DateCondition VARCHAR(255);
   DECLARE v_IncludeType INTEGER;
   
   DECLARE p_WHERE LONGTEXT;

   DECLARE p_ORDERBY LONGTEXT;

   DECLARE p_GROUPBY LONGTEXT;

   DECLARE p_SQL LONGTEXT;

   DECLARE p_TempQuery LONGTEXT;

   DECLARE p_INSERT LONGTEXT;

	

   IF (p_StatementType = 'View')



   THEN	

		IF (p_SearchBy = 'Report')

		THEN    

				SELECT        

				ReportID, 

				ReportDesc, 

				ReportType, 

				ReportOrderDisplay

				FROM           

				tblreport

				WHERE 

				(isActive > 0)

				ORDER BY ReportOrderDisplay;

				

		ELSEIF (p_SearchBy = 'Report Admin')

		THEN    

				SELECT        

				ReportID, 

				ReportDesc, 

				ReportType, 

				ReportOrderDisplay

				FROM           

				tblreport

				WHERE 

				(isActive > 0 AND ReportType = 1)

				ORDER BY ReportOrderDisplay;

				

		ELSEIF (p_SearchBy = 'Report Operation')

		THEN    

				SELECT        

				ReportID, 

				ReportDesc, 

				ReportType, 

				ReportOrderDisplay

				FROM           

				tblreport

				WHERE 

				(isActive > 0 AND ReportType = 2)

				ORDER BY ReportOrderDisplay;	

				

		ELSEIF (p_SearchBy = 'Report Type')

		THEN	

				SET v_ReportType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

				

				SELECT        

				ReportID, 

				ReportDesc, 

				ReportType, 

				ReportOrderDisplay

				FROM           

				tblreport

				WHERE 

				(isActive > 0 AND ReportType = v_ReportType)

				ORDER BY ReportOrderDisplay;

				

		ELSEIF (p_SearchBy = 'Import Terminal')

		THEN	

				SELECT        

				a.SerialNo, 

				a.Type,

				a.Model,

				a.Brand,

				a.TerminalStatus,

				a.TerminalStatusDescription

				FROM           

				tblterminaldetailrepo a

				ORDER BY a.TerminalStatus;

				

		ELSEIF (p_SearchBy = 'Import SIM')

		THEN	

				SELECT        

				a.SerialNo,

				a.Carrier, 

				a.SimStatus,

				a.SIMStatusDescription

				FROM           

				tblsimdetailrepo a

				ORDER BY a.SimStatus;



				



		



		#ROCKY - PARTICULAR: ADD PARTICULAR DETAILS REPORT 		



		ELSEIF (p_SearchBy = 'Particular Details')

		THEN	

		

				SELECT



					IFNULL_STRING_ONLY(a.Code) AS EmployeeNo,

					IFNULL_STRING_ONLY(a.Name) AS `Name`,

					IFNULL_STRING_ONLY(a.Gender) AS Gender,

					funcGetDesc("Search","Department", a.DepartmentID) AS Department,

					funcGetDesc("Search","Position", a.PositionID) AS `Position`,	

					IFNULL_STRING_ONLY(a.JobDescription) AS JobDescription,

					a.OnBoardDate,

					a.ResignDate,

					a.BirthDate,

					IFNULL_STRING_ONLY(ParticularDescription) AS Category,

					IFNULL_STRING_ONLY(a.Accountinfo) AS `Account`,

					IFNULL_STRING_ONLY(a.TINNo) AS TINNo,

					IFNULL_STRING_ONLY(a.PhilhealthNo) AS PhilhealthNo,

					IFNULL_STRING_ONLY(a.SSSNo) AS SSSNo,

					IFNULL_STRING_ONLY(a.HDMFNo) AS HDMFNo,

					IFNULL_STRING_ONLY(a.Address) AS Address,

					IFNULL_STRING_ONLY(a.EducLevel) AS EducLevel,

					IFNULL_STRING_ONLY(a.PresentID) AS PresentID,

					IFNULL_STRING_ONLY(a.PresentIDnO) AS PresentIDnO,				

					IFNULL_STRING_ONLY(a.EmploymentStatus) AS EmploymentStatus,



					CONCAT( FLOOR(DATEDIFF(CURDATE(), a.OnBoardDate) / 365), '.',

					LPAD(FLOOR((DATEDIFF(CURDATE(), a.OnBoardDate) % 365) / 30.44), 2, '0')) AS TenureYears,

					CONCAT(FLOOR(DATEDIFF(CURDATE(), IFNULL_STRING_ONLY(a.BirthDate)) / 365),'.',

					LPAD(FLOOR((DATEDIFF(CURDATE(), IFNULL_STRING_ONLY(a.BirthDate)) % 365) / 30.44), 2, '0' )) AS Age,



					funcGetCount("Search","Gender", "MALE") AS TMale,

					funcGetCount("Search","Gender", "FEMALE") AS TFemale,



					(SELECT FORMAT(AVG(DATEDIFF(CURDATE(), BirthDate) / 365.00), 2) FROM tblparticular) AS AverageAge,

					(SELECT FORMAT(AVG(DATEDIFF(CURDATE(), OnBoardDate) / 365.00), 2)FROM tblparticular) AS AverageEmpPeriod,

					(SELECT COUNT(*) FROM tblparticular WHERE EducLevel LIKE "%DEGREE HOLDER%" OR EducLevel LIKE "%DIPLOMA%") AS TotalDegreeHolder,

					(SELECT COUNT(*) FROM tblparticular WHERE EducLevel LIKE "%MASTER%") AS TotalDegreeMaster,

					(SELECT COUNT(*) FROM tblparticular WHERE EducLevel LIKE "%PHD%") AS TotalDegreePhd,

					(SELECT COUNT(*) FROM tblparticular WHERE EducLevel LIKE "%SECOND%") AS TotalDegreeSecond,



					IFNULL_STRING_ONLY(a.SSSNo) AS SSSNo,

					IFNULL_STRING_ONLY(a.HDMFNo) AS HDMFNo,

					IFNULL_STRING_ONLY(a.Address) AS Address,

					IFNULL_STRING_ONLY(a.EducLevel) AS EducLevel,

					IFNULL_STRING_ONLY(a.NbiReq) AS NBI,

					IFNULL_STRING_ONLY(a.SchoolReq) AS SCHOOLCRED,

					IFNULL_STRING_ONLY(a.AppFormReq) AS APPFORM,

					IFNULL_STRING_ONLY(a.WaiverReq) AS WAIVER,

					

					(SELECT COUNT(*) FROM tblparticular WHERE NbiReq LIKE "-" AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS NoNbi,

					(SELECT COUNT(*) FROM tblparticular WHERE SchoolReq  LIKE "-"AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS NoSchReq,

					(SELECT COUNT(*) FROM tblparticular WHERE AppFormReq LIKE "-"AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS NoAppForm,

					(SELECT COUNT(*) FROM tblparticular WHERE WaiverReq  LIKE "-"AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS NoWaiver,

					(SELECT COUNT(*) FROM tblparticular WHERE NbiReq  NOT LIKE  "-"AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS WithNbi,

					(SELECT COUNT(*) FROM tblparticular WHERE SchoolReq  NOT LIKE "-"AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS WithSch,

					(SELECT COUNT(*) FROM tblparticular WHERE AppFormReq NOT LIKE "-"AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS WithAppForm,

					(SELECT COUNT(*) FROM tblparticular WHERE WaiverReq  NOT LIKE "-"AND OnBoardDate IS NOT NULL AND OnBoardDate <> "") AS WithWaiver



				FROM tblparticular a

				WHERE OnBoardDate IS NOT NULL AND OnBoardDate <> "";

				

		#ROCKY - BILLING: ADD BILLING MERCHANT DETAILS	



		ELSEIF (p_SearchBy = 'Security Bank Billing Report')	

		THEN

				

				SELECT



					IFNULL_FORMAT_DATE_ONLY(d.IRDate) AS `Request Date`,

					a.Merchant,

					IFNULL_STRING_ONLY(c.Address)  AS Address,

					IFNULL_STRING_ONLY(c.Address2) AS Address2,

					IFNULL_STRING_ONLY(c.Address3) AS Address3,

					a.TerminalSN AS `Serial Number`,

					a.MID,

					a.TID,

					IFNULL_STRING_ONLY(a.ServiceStatusDescription) AS `Status`,

					a.FSRDate AS `Date Installed`,

					IFNULL_STRING_ONLY(TRIM(a.ActionTaken)) AS `Remarks`,

					a.ClientName AS `Client`



				FROM tblfsrdetail a

				INNER JOIN tblparticular c ON c.ParticularID = a.MerchantID

				INNER JOIN tblirdetail d ON d.MerchantID = a.MerchantID

				WHERE a.ClientName = "SECURITY BANK" AND a.isBillable = "1"

				GROUP BY

				

					d.IRDate,

					a.Merchant,

					c.Address,

					c.Address2,

					c.Address3,

					a.TerminalSN,

					a.MID,

					a.TID,

					a.ServiceStatusDescription,

					a.FSRDate,

					a.ActionTaken

					

				ORDER BY d.IRDate DESC;

		ELSEIF (p_SearchBy = 'Leasing-Summary')	
		THEN
		
				SELECT 
					Bill_ID,
                    Request_No,
                    Brand,
					Request_Date, Requestor, Request_Type,
					Request_Prio, Pos_Setup, Pos_Type, Pos_Conn_Type,
					Target_Date, PullOut_Date_Exhibit, Rm_Instructions,
					MID, TID, Merchant_Name,
					Merchant_Address, City, Area_1,
					Area_2, Contact_Person, Contact_No,
					Bancnet_TID, Bancnet_MID,
					Alipay_TID, Alipay_MID,
					Wechat_TID, Wechat_MID,
					QR_Gcash_TID, QR_Gcash_MID,
					QR_Grab_TID, QR_Grab_MID,
					QR_UPI_TID, QR_UPI_MID,
					QR_P2M_TID, QR_P2M_MID,
					Multi_Merchant_1_Name,
					Multi_Merchant_1_TID,
					Multi_Merchant_1_MID,
					Multi_Merchant_2_Name,
					Multi_Merchant_2_TID,
					Multi_Merchant_2_MID,
					Multi_Merchant_3_Name,
					Multi_Merchant_3_TID,
					Multi_Merchant_3_MID,
					Multi_Merchant_4_Name,
					Multi_Merchant_4_TID,
					Multi_Merchant_4_MID,
					Multi_Merchant_5_Name,
					Multi_Merchant_5_TID,
					Multi_Merchant_5_MID,
					Dcc, 
					Installment, 
					Manual_Key_Entry,
					Preauth, 
					Offline_Sale, 
					Offline_Sale_Limit,
					Tip_Adjust, 
					Tip_Adjust_Limit, 
					Add_On_Device,
					Ecr_Integration, 
					Ecr_Cable, 
					Pos_Serial,
					Pos_Model,
					Contactless,
					Current_App, 
					Pos_Version, 
					Pos_Crc,
					Sim_Telco, 
					Sim_Serial, 
					Primary_Dialing,
					Secondary_Dialing, 
					Original_Installed_Date,
					Terminal_Cost,					
					Auto_Settlement,
					Auto_Settlement_Time,
					PullOut_Date
					
					
				FROM vw_net_Matrix
				WHERE Client_ID = 21
				AND 	MONTH(Coverage_Date) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
				AND 	YEAR(Coverage_Date) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH));
				
		ELSEIF (p_SearchBy = 'Leasing-Invoice')	
		THEN	
		
				SET @Records = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
				SET @DescValue = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
				SET @DiscValue = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));

				SET @ClientID = 21;

				IF @Records IS NOT NULL AND LENGTH(TRIM(@Records)) > 0 THEN

					 SET @totalRecords = JSON_LENGTH(@Records);
					 SET @i = 0;

					 WHILE @i < @totalRecords DO

						  SET @v_ID = JSON_UNQUOTE(JSON_EXTRACT(@Records, CONCAT('$[', @i, ']')));

						  INSERT INTO tblbilling_repo(Bill_ID)
						  VALUES (@v_ID);

						  -- Move to the next record
						  SET @i = @i + 1;
					 END WHILE;
					 
				END IF;

				SELECT 
					 vw.Pos_Model AS `Description`,
					 COUNT(*) AS Qty,
					 vw.Terminal_Cost AS `Price`,
					 FORMAT(SUM(vw.Terminal_Cost), 2) AS Total_Price,
					 tl.Total,
					 tl.Total_Disc_Price,
					 tl.VATSales,
					 tl.VATAmount,
					 tl.Total_Amount_Due,
					 @DescValue AS DiscDesc,
					 FORMAT(IF(@DiscValue = '' OR @DiscValue IS NULL, NULL, -COALESCE(@DiscValue, 0)), 0) AS `Discount`,
					 MAX(ci.AttentionName) AS Receiver_Name,
					 MAX(ci.AttentionTitle) AS Receiver_Address,
					 MAX(ci.BillingName) AS Client_Name,
					 MAX(ci.BillingAddress) AS Address
				FROM 
					 vw_net_matrix vw
				LEFT JOIN tblbilling_client AS ci ON ci.ClientID = @ClientID
				LEFT JOIN tblvat_details vat ON vat.Vat_ID = 3

				JOIN (
					 SELECT 
						  FORMAT(SUM(svw.Terminal_Cost), 2) AS Total,
						  IF(@DiscValue = '' OR @DiscValue IS NULL, 0, FORMAT(SUM(svw.Terminal_Cost) - COALESCE(@DiscValue, 0), 2)) AS `Total_Disc_Price`,
						  FORMAT((SUM(svw.Terminal_Cost) - COALESCE(@DiscValue, 0)) / (1 + svat.VAT_Percentage / 100), 2) AS `VATSales`,
						  FORMAT(((SUM(svw.Terminal_Cost) - COALESCE(@DiscValue, 0)) / (1 + svat.VAT_Percentage / 100)) * (svat.VAT_Percentage / 100), 2) AS `VATAmount`,
						  FORMAT((SUM(svw.Terminal_Cost) - COALESCE(@DiscValue, 0)) + (((SUM(svw.Terminal_Cost) - COALESCE(@DiscValue, 0)) / (1 + svat.VAT_Percentage / 100)) * (svat.VAT_Percentage / 100)), 2) AS `Total_Amount_Due`
					 FROM 
						  vw_net_matrix svw
					 LEFT JOIN 
						  tblvat_details svat ON svat.Vat_ID = 3
					 WHERE 
								svw.Client_ID = 21
						  AND MONTH(svw.Coverage_Date) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
						  AND YEAR(svw.Coverage_Date) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
						  AND (
								(@Records IS NOT NULL AND LENGTH(@Records) > 0 AND svw.Bill_ID NOT IN (SELECT Bill_ID FROM tblbilling_repo)) 
								OR @Records IS NULL OR LENGTH(@Records) = 0
							)
				) AS tl

				WHERE 
					 vw.Client_ID = 21
					 AND MONTH(Coverage_Date) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
					 AND YEAR(Coverage_Date) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
					 AND (
						(@Records IS NOT NULL AND LENGTH(@Records) > 0 AND vw.Bill_ID NOT IN (SELECT Bill_ID FROM tblbilling_repo)) 
						OR @Records IS NULL OR LENGTH(@Records) = 0
					 )
				GROUP BY 
					 vw.Pos_Model;

				IF @Records IS NOT NULL AND LENGTH(TRIM(@Records)) > 0 THEN
					TRUNCATE TABLE tblbilling_repo;
				END IF;

		
		ELSEIF (p_SearchBy = 'Service-Summary') THEN	
						
			SELECT
						svc.ServiceNo AS SERVICE_NO,
						svc.isBillable AS VALIDATION_ID,
						IF(svc.isBillable = 1,'BILLABLE','NON BILLABLE') AS VALIDATION_STATUS,
						NULL AS VALIDATION_REASON,
						IF(svc.isBillable = 1,'BILLABLE','NON BILLABLE') AS CITAS_REMARKS,
						IF(svc.isBillable = 1, fa.Reason, NULL) AS CITAS_REASON,
						svc.Vendor AS VENDOR,
						CONCAT('''', DATE_FORMAT(fsr.FSRDate,'%M %Y')) AS PERIOD_MONTH,
						'Expense' AS SERVICE_TYPE,
						#svc.JobType AS Category_ID,

						CASE
								WHEN pt.Name LIKE '%EXH%' OR pt.Name LIKE '%EXHIBIT%' THEN 'EXHIBIT'
								WHEN svc.JobType = 6 THEN 'MAINTENANCE'
								WHEN svc.JobType = 1 THEN 'NEW INSTALLATION'
								ELSE TRIM(REPLACE(svc.JobTypeSubDescription,'FOR',''))
						END AS CATEGORY,

						CASE
								WHEN pt.Name LIKE '%EXH%' OR pt.Name LIKE '%EXHIBIT%' THEN 'EXHIBIT'
								WHEN svc.JobType = 6 THEN 'TECHNICAL ASSISTANCE'
								ELSE TRIM(REPLACE(svc.JobTypeSubDescription,'FOR',''))
						END AS SUB_CATEGORY,

						COALESCE(attempts.TotalAttempts,0) AS TOTAL_ATTEMPTS,

						CASE
								WHEN rg.RegionID = 4 THEN 'MM'
								WHEN rg.RegionID = 5 THEN 'PROV'
								ELSE NULL
						END AS LOCATION,

						fsr.TExpenses AS EXPENSES,

						COALESCE(
								CAST(IF(svc.isBillable = 1, rg.Charge, 0) AS DECIMAL(12,2)),
								0.00
						) AS PROJECTED_CHARGE,

						COALESCE(
								CAST(IF(svc.isBillable = 1, sc.Total_Charge, 0) AS DECIMAL(12,2)),
								0.00
						) AS ACTUAL_CHARGE,

						IF(svc.IRNo = 0 OR svc.IRNo IS NULL, NULL, svc.IRNo) AS MB_REFERENCE,
						svc.IRNo AS REQUEST_ID,
						DATE_FORMAT(svc.ReqInstallationDate,'%m-%d-%Y') AS REQUEST_DATE,

						pt.Name AS MERCHANT_NAME,
						pt.Address AS ADDRESS,
						pt.ContactPerson AS REPRESENTATIVE,
						pt.ContactNumber AS CONTACT_NUMBER,

						ir.TID,
						ir.MID,
						td.Model AS TERMINAL_MODEL,
						td.TerminalSN AS TERMINAL_SERIAL,
						sd.Carrier AS SIM_CARRIER,
						sd.SIMSN AS SIM_SERIAL,

						CASE
								WHEN svc.JobType = 1 THEN svc.RMInstruction
								ELSE CONVERT(fa.ActionTaken USING utf8mb3)
						END AS MB_REMARKS_INSTRUCTIONS,

						CASE
								WHEN fa.ActionMade = 'SUCCESS' THEN 'RESOLVED'
								ELSE fa.ActionMade
						END AS STATUS,

						DATE_FORMAT(fa.FSRDate,'%m-%d-%Y') AS SERVICE_DATE,

						CONCAT(
								'TID: ', ir.TID, CHAR(10),
								'MID: ', ir.MID, CHAR(10),
								'Problem Reported: ', CONVERT(fa.ProblemReported USING utf8mb3), CHAR(10),
								'Problem Found: ', CONVERT(fa.ActualProblemReported USING utf8mb3), CHAR(10),
								'Action Taken: ', CONVERT(fa.ActionTaken USING utf8mb3)
						) AS ACTIVITY_REMARKS,

						fa.Reason,
						fa.Reason1 AS `1ST_REASON`,
						DATE_FORMAT(fa.FSRDate1,'%m-%d-%Y') AS `1ST_DATE`,
						fa.Reason2 AS `2ND_REASON`,
						DATE_FORMAT(fa.FSRDate2,'%m-%d-%Y') AS `2ND_DATE`,
						fa.Reason3 AS `3RD_REASON`,
						DATE_FORMAT(fa.FSRDate3,'%m-%d-%Y') AS `3RD_DATE`,
						fa.Reason4 AS `4TH_REASON`,
						DATE_FORMAT(fa.FSRDate4,'%m-%d-%Y') AS `4TH_DATE`

				FROM tblservicingdetail svc

				LEFT JOIN tblparticular pt      ON pt.ParticularID = svc.MerchantID
				LEFT JOIN tblterminaldetail td  ON td.TerminalID   = svc.TerminalID
				LEFT JOIN tblfsrdetail fsr      ON fsr.ServiceNo   = svc.ServiceNo
				LEFT JOIN tblsimdetail sd       ON sd.SIMID        = svc.SIMID
				LEFT JOIN tblirdetail ir        ON ir.IRIDNo       = svc.IRIDNo
				LEFT JOIN tblregion rg          ON rg.RegionID     = pt.RegionType

				LEFT JOIN (
						SELECT
								s.ServiceNo,
								CAST(
										CASE
												WHEN rg.RegionID = 7 AND s.BillingTypeID = 140 THEN 1200 + fsr.TExpenses
												WHEN rg.RegionID = 5 AND s.BillingTypeID = 140 THEN 950  + fsr.TExpenses
												WHEN rg.RegionID = 4 AND s.BillingTypeID = 140 THEN 450  + fsr.TExpenses
												ELSE rg.Charge + fsr.TExpenses
										END AS DECIMAL(12,2)
								) AS Total_Charge
						FROM tblservicingdetail s
						JOIN tblfsrdetail fsr      ON fsr.ServiceNo = s.ServiceNo
						LEFT JOIN tblparticular pt ON pt.ParticularID = s.MerchantID
						LEFT JOIN tblregion rg     ON rg.RegionID = pt.RegionType
				) sc ON sc.ServiceNo = svc.ServiceNo

				LEFT JOIN (
						SELECT IRNo, JobType, COUNT(*) AS TotalAttempts
						FROM tblfsrdetail
						GROUP BY IRNo, JobType
				) attempts
						ON attempts.IRNo = fsr.IRNo
					 AND attempts.JobType = fsr.JobType

				JOIN (
						SELECT
								f.ServiceNo,
								f.IRIDNo,
								f.JobType,
								f.IRNo,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,0,'') AS AttemptBase,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,0,'ActionTaken') AS ActionTaken,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,0,'ActionMade') AS ActionMade,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,0,'ActualProblemReported') AS ActualProblemReported,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,0,'ProblemReported') AS ProblemReported,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,0,'Reason') AS Reason,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,1,'Reason') AS Reason1,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,1,'FSRDate') AS FSRDate1,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,2,'Reason') AS Reason2,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,2,'FSRDate') AS FSRDate2,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,3,'Reason') AS Reason3,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,3,'FSRDate') AS FSRDate3,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,4,'Reason') AS Reason4,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,4,'FSRDate') AS FSRDate4,
								fnGetAttempts(f.IRIDNo,f.JobType,f.IRNo,0,'FSRDate') AS FSRDate
						FROM tblfsrdetail f
				) fa
						ON fa.ServiceNo = fsr.ServiceNo
					 AND fa.IRIDNo    = fsr.IRIDNo
					 AND fa.JobType   = fsr.JobType
					 AND fa.IRNo      = fsr.IRNo

				WHERE
						svc.JobTypeStatusDescription = 'COMPLETED'
						AND fsr.ActionMade = 'SUCCESS'
						AND MONTH(fsr.FSRDate) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
						AND YEAR(fsr.FSRDate) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH));
		
		ELSEIF (p_SearchBy = 'Service-Invoice') THEN
		
				SET @Records = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
				SET @DescValue = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
				SET @DiscValue = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
				
				SET @ClientID = 21;
					
				SELECT
					CONCAT('Servicing Billing ', DATE_FORMAT(CURDATE(), '%M %Y')) AS DESCRIPTION,
					FORMAT(SUM(COALESCE(CASE WHEN sf.Category_ID IN (3) THEN sf.Charge ELSE 0 END, 0)), 2) AS Services,
					FORMAT(SUM(COALESCE(CASE WHEN sf.Category_ID IN (1, 6, 7, 4) THEN sf.Charge ELSE 0 END, 0)), 2) AS Maintenance,
					COALESCE(@DescValue, NULL) AS DiscDesc,
					FORMAT(IF(@DiscValue = '' OR @DiscValue IS NULL, NULL, -COALESCE(@DiscValue, 0)), 2) AS `Discount`,
					FORMAT(SUM(sf.Charge), 2) AS Total,
					IF(COALESCE(NULLIF(@DiscValue, ''), 0) = 0, 0, FORMAT(SUM(sf.Charge) - COALESCE(NULLIF(@DiscValue, ''), 0), 2)) AS `Total_Disc_Price`,
					FORMAT((SUM(sf.Charge) - COALESCE(@DiscValue, 0)) / (1 + vat.VAT_Percentage / 100), 2) AS `VATSales`,
					FORMAT(((SUM(sf.Charge) - COALESCE(@DiscValue, 0)) / (1 + vat.VAT_Percentage / 100)) * (vat.VAT_Percentage / 100), 2) AS `VATAmount`,
					FORMAT((SUM(sf.Charge) - COALESCE(@DiscValue, 0)) + (((SUM(sf.Charge) - COALESCE(@DiscValue, 0)) / (1 + vat.VAT_Percentage / 100)) * (vat.VAT_Percentage / 100)), 2) AS `Total_Amount_Due`,
					ci.AttentionName  AS Receiver_Name,
					ci.AttentionTitle AS Receiver_Address,
					ci.BillingName AS Client_Name,
					ci.BillingAddress AS Address	

				FROM vw_servicing_fee sf
				LEFT JOIN tblbilling_client AS ci ON ci.ClientID = @ClientID
				LEFT JOIN tblvat_details vat ON vat.Vat_ID = 3

				WHERE MONTH(STR_TO_DATE(sf.Service_Date, '%m-%d-%Y'))	= MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
				AND YEAR(STR_TO_DATE(sf.Service_Date, '%m-%d-%Y'))  = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
				AND sf.Client_ID 	= @ClientID
				AND sf.Valid_ID = 1;
			
		
		ELSEIF (p_SearchBy = 'TLE-Summary') THEN
		
			SET @ClientID = 21;
			
			SELECT 
								Bill_ID, Request_No, Brand,
					Request_Date, Requestor, Request_Type,
					Request_Prio, Pos_Setup, Pos_Type, Pos_Conn_Type,
					Target_Date, PullOut_Date_Exhibit, Rm_Instructions,
					MID, TID, Merchant_Name,
					Merchant_Address, City, Area_1,
					Area_2, Contact_Person, Contact_No,
					Bancnet_TID, Bancnet_MID,
					Alipay_TID, Alipay_MID,
					Wechat_TID, Wechat_MID,
					QR_Gcash_TID, QR_Gcash_MID,
					QR_Grab_TID, QR_Grab_MID,
					QR_UPI_TID, QR_UPI_MID,
					QR_P2M_TID, QR_P2M_MID,
					Multi_Merchant_1_Name,
					Multi_Merchant_1_TID,
					Multi_Merchant_1_MID,
					Multi_Merchant_2_Name,
					Multi_Merchant_2_TID,
					Multi_Merchant_2_MID,
					Multi_Merchant_3_Name,
					Multi_Merchant_3_TID,
					Multi_Merchant_3_MID,
					Multi_Merchant_4_Name,
					Multi_Merchant_4_TID,
					Multi_Merchant_4_MID,
					Multi_Merchant_5_Name,
					Multi_Merchant_5_TID,
					Multi_Merchant_5_MID,
					Dcc, 
					Installment, 
					Manual_Key_Entry,
					Preauth, 
					Offline_Sale, 
					Offline_Sale_Limit,
					Tip_Adjust, 
					Tip_Adjust_Limit, 
					Add_On_Device,
					Ecr_Integration, 
					Ecr_Cable, 
					Pos_Serial,
					Pos_Model,
					Contactless,
					Current_App, 
					Pos_Version, 
					Pos_Crc,
					Sim_Telco, 
					Sim_Serial, 
					Primary_Dialing,
					Secondary_Dialing, 
					Original_Installed_Date,
					Terminal_Cost,					
					Auto_Settlement,
					Auto_Settlement_Time,
					PullOut_Date
					
				FROM vw_net_Matrix
				WHERE Client_ID = @ClientID
				AND 	MONTH(Coverage_Date) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
				AND 	YEAR(Coverage_Date) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
				AND 	(
							  -- Exclude 5.2 and lower without "ANDROID"
							  (Pos_Version > 5.2 OR Pos_Version LIKE '%ANDROID%')
						)
						 AND 
						(
							  -- Include only versions >= 6.0
							  Pos_Version >= 6.0
							  OR 
							  -- Include versions between 2.0 and 4.0 with "ANDROID"
							  (Pos_Version BETWEEN 2.0 AND 4.0 AND Pos_Version LIKE '%ANDROID%')
						);
			
		
		ELSEIF (p_SearchBy = 'TLE-Invoice') THEN
					
				SET @Records = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));
				SET @DescValue = TRIM(SPLIT_STRING(p_SearchValue, '|', 2));
				SET @DiscValue = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
					
				SET @ClientID = 21;
					
				SELECT 
					 'Terminal Line Encryption Units' AS DESCRIPTION,
					 FORMAT(COUNT(*), 0) AS Qty,
					 FORMAT(20, 2) AS Unit_Cost,
					 COALESCE(@DescValue, NULL) AS DiscDesc,
					 FORMAT(IF(@DiscValue = '' OR @DiscValue IS NULL, NULL, -COALESCE(@DiscValue, 0)), 2) AS `Discount`,
					 FORMAT(COUNT(*), 2) AS Total,
					 FORMAT(COUNT(*) - COALESCE(@DiscValue, 0), 2) AS `Total_Disc_Price`,
					 FORMAT((COUNT(*) - COALESCE(@DiscValue, 0)) / (1 + vat.VAT_Percentage / 100), 2) AS `VATSales`,
					 FORMAT(((COUNT(*) - COALESCE(@DiscValue, 0)) / (1 + vat.VAT_Percentage / 100)) * (vat.VAT_Percentage / 100), 2) AS `VATAmount`,
					 FORMAT(COUNT(*) - COALESCE(@DiscValue, 0) + 
							  (((COUNT(*) - COALESCE(@DiscValue, 0)) / (1 + vat.VAT_Percentage / 100)) * (vat.VAT_Percentage / 100)), 2) AS `Total_Amount_Due`,
					 ci.AttentionName  AS Receiver_Name,
					 ci.AttentionTitle AS Receiver_Address,
					 ci.BillingName AS Client_Name,
					 ci.BillingAddress AS Address    
				FROM 
					 vw_net_matrix nm
				LEFT JOIN tblbilling_client AS ci ON ci.ClientID = @ClientID
				LEFT JOIN tblvat_details vat ON vat.Vat_ID = 3
				WHERE 
					 Client_ID = @ClientID
					 AND MONTH(nm.Coverage_Date) = MONTH(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
					 AND YEAR(nm.Coverage_Date) = YEAR(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))
					 AND (
						  Pos_Version > 5.2 OR Pos_Version LIKE '%ANDROID%'
					 )
					 AND (
						  Pos_Version >= 6.0
						  OR 
						  (Pos_Version BETWEEN 2.0 AND 4.0 AND Pos_Version LIKE '%ANDROID%')
					 );
			
		ELSEIF(p_SearchBy = 'Billing_History') THEN
		
			SELECT 
				CASE 
				  WHEN Type_ID = 1 THEN 'Net Matrix'
				  ELSE 'Unknown'
				END AS DESCRIPTION,
				DATE_FORMAT(Coverage_Date, '%M %Y') AS Coverage,
				FORMAT(COUNT(*), 0) AS Units,
				IF(isDone = 1, 'Completed', 'Pending') AS `Status`,
				DATE_FORMAT(Created_Date, '%b %e, %Y %l:%i %p')	AS `Date`
				FROM tblbilling
			GROUP BY Coverage_Date, DESCRIPTION;
		
		
		
		ELSEIF (p_SearchBy = 'Weepay Inventory Report')

		THEN

		

			SELECT

				d.POS_TYPE,

				a.Model,

				a.TerminalSN,

				d.MerchantName,

				f.Address,

				g.Region,

				d.TID,

				d.MID,

				d.SET_UP,

				d.SIMSN,

				b.FSRDate,

				a.TerminalStatusDescription,

				a.ClientName

				

			FROM tblterminaldetail

				a



			LEFT JOIN (SELECT ServiceNo, MerchantID, TerminalID, JobTypeDescription, FSRDate 

				FROM tblfsrdetail)

				b ON b.TerminalID = a.TerminalID



			LEFT JOIN ( SELECT ParticularID, TerminalID, SIMID, TID, `MID`, SET_UP, MerchantName, POS_TYPE, SIMSN

				FROM tblirdetail)

				d ON d.TerminalID = a.TerminalID



			LEFT JOIN (SELECT ParticularID, RegionType, Address 

				FROM tblparticular)

				f ON f.ParticularID = d.ParticularID

				

			LEFT JOIN tblregion 

				g ON g.RegionID = f.RegionType

				

			WHERE  a.ClientName = 'WEEPAY'



			GROUP BY a.TerminalID;

			

		ELSEIF (p_SearchBy = 'Weepay Sim Summary Report')

		THEN

				

			SELECT

				ReceiveDate,

				SerialNo,

				Carrier,

				Allocation,

				Remarks

			FROM `vw_sim_summary`;

				

		ELSEIF (p_SearchBy = 'Weepay Sim Invoice')

		THEN			

				

				SELECT

					CONCAT('TNS SIM ', DATE_FORMAT(CURDATE(), '%M %Y')) AS DESCRIPTION,

					FORMAT(COUNT(*), 0) AS Qty,

					FORMAT(UnitPrice, 2) AS UnitCost,

					FORMAT(SUM(UnitPrice), 2) AS TotalAmount,

					FORMAT(SUM(UnitPrice / 1.12), 2) AS VatableSales,

					FORMAT(SUM(UnitPrice / 1.12) * 0.12, 2) AS VATAmount   

				FROM

					`vw_sim_summary`

				WHERE

					Carrier = 'TNS SIM' AND UnitPrice != 0;

					

					

		ELSEIF (p_SearchBy = 'FSR PDF LIST')

		THEN

		

			SELECT

			IRNo AS `Request No.`,

			ServiceNo AS `Service No.`,

			FSRNo AS `FSR No.`,

			IRIDNo AS `IrID No.`,



			Merchant AS `Merchant Name`, 

			ServiceStatusDescription AS `Status`, 



			CASE

				WHEN JobTypeDescription = 'SVC REQ INSTALLATION'  THEN CONCAT('INSTALLATION_', FSRNo)

				WHEN JobTypeDescription = 'SVC REQ REPROGRAMMING' THEN CONCAT('REPROGRAMMING_', FSRNo)

				WHEN JobTypeDescription = 'SVC REQ SERVICING'     THEN CONCAT('SERVICING_', FSRNo)

				WHEN JobTypeDescription = 'SVC REQ PULL-OUT'      THEN CONCAT('PULL-OUT_', FSRNo)

				ELSE CONCAT('Others: ', JobTypeDescription)

			END AS FileName,

				

			isPdf AS `isPdf`



			FROM tblfsrdetail

			WHERE isPdf = "0";

			

		ELSEIF (p_SearchBy = 'Service Summary Report')
		THEN
			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)); # eg. (PENDING, PROCESSING, COMPLETED...)
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER); # eg. (1=INSTALLATION, ....)
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_ServiceJobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)); # eg. (INSTALLATION, SERVICING, ...)
			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)); # eg. (SUCCESS, NEGATIVE)		
			SET v_DateFilter = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)); # eg (TODAY, RANGE)
			
			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));
			SET v_FSRMode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
			
			SET v_DispatcherID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)) AS UNSIGNED INTEGER);
			SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)) AS UNSIGNED INTEGER);
			
			SET v_DateCondition = '';
			IF v_DateFrom <> '0000-00-00' AND v_DateTo <> '0000-00-00' THEN
				SET v_DateCondition = CONCAT('(', 'fsr.FSRDate BETWEEN ', ADD_SINGLEQUOTE(v_DateFrom), ' AND ', ADD_SINGLEQUOTE(v_DateTo), ')');
			ELSE
				SET v_DateCondition = CONCAT(' 1 ');
			END IF;
			
			SET p_WHERE = '';			
			#SELECT CONCAT("v_JobTypeStatusDescription=", v_JobTypeStatusDescription);
			#SELECT CONCAT("v_JobType=", v_JobType);
			#SELECT CONCAT("v_DateFrom=", v_DateFrom);
			#SELECT CONCAT("v_ServiceJobTypeDescription=", v_ServiceJobTypeDescription);
			#SELECT CONCAT("v_ServiceResult=", v_ServiceResult);
			#SELECT CONCAT("v_DateFilter=", v_DateFilter);
			#SELECT CONCAT("v_DispatcherID=", v_DispatcherID);
			#SELECT CONCAT("v_RegionType=", v_RegionType);
										
			SET p_SQL = '';
			
			IF v_JobTypeStatusDescription = 'PENDING' || v_JobTypeStatusDescription = 'PROCESSING' THEN
				SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
				    'IFNULL_NUMERIC(st.JobType) AS JobType, ',
				    'IFNULL_STRING_ONLY(st.ServiceJobTypeDescription) AS ServiceJobTypeDescription, ',
				    'IFNULL_NUMERIC(xTable.RegionType) AS RegionType, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Region", xTable.RegionType)) AS Region, ',
				    'IFNULL_NUMERIC(xTable.TCount) AS TCount, ',
				    'IFNULL_NUMERIC(xTable.DispatchID) AS DispatchID, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", xTable.DispatchID)) AS Dispatcher, ',
				    'IFNULL_STRING_ONLY(xTable.JobTypeStatusDescription) AS JobTypeStatusDescription ',
				    'FROM tblservicetype st ',
				    'LEFT JOIN (SELECT ',
				    'svc.JobType AS JobType, ',
				    'pr.RegionType AS RegionType, ',
				    'pr.Province AS Province, ',
				    'COUNT(*) AS TCount, ',
				    'svc.JobTypeStatusDescription AS JobTypeStatusDescription, ',
				    'funcGetID("Search", "Service DispatchID", CONCAT(svc.ServiceNo, "|", svc.IRIDNo)) AS DispatchID ',
				    'FROM tblservicingdetail AS svc ',
				    'LEFT JOIN tblfsrdetail AS fsr ON svc.ServiceNo = fsr.ServiceNo ',
				    'LEFT JOIN tblparticular AS pr ON svc.MerchantID = pr.ParticularID ',
				    'LEFT JOIN tblservicetype AS stt ON svc.JobType = stt.JobType ',
				    'WHERE (svc.JobTypeStatusDescription =', ADD_SINGLEQUOTE(v_JobTypeStatusDescription), ') '
				);
			ELSEIF v_JobTypeStatusDescription = 'OVERALL PENDING' THEN
				SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
				    'IFNULL_NUMERIC(st.JobType) AS JobType, ',
				    'IFNULL_STRING_ONLY(st.ServiceJobTypeDescription) AS ServiceJobTypeDescription, ',
				    'IFNULL_NUMERIC(xTable.RegionType) AS RegionType, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Region", xTable.RegionType)) AS Region, ',
				    'IFNULL_NUMERIC(xTable.TCount) AS TCount, ',
				    'IFNULL_NUMERIC(xTable.DispatchID) AS DispatchID, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", xTable.DispatchID)) AS Dispatcher, ',
				    'IFNULL_STRING_ONLY(xTable.JobTypeStatusDescription) AS JobTypeStatusDescription ',
				    'FROM tblservicetype st ',
				    'LEFT JOIN (SELECT ',
				    'svc.JobType AS JobType, ',
				    'pr.RegionType AS RegionType, ',
				    'pr.Province AS Province, ',
				    'COUNT(*) AS TCount, ',
				    'svc.JobTypeStatusDescription AS JobTypeStatusDescription, ',
				    'funcGetID("Search", "Service DispatchID", CONCAT(svc.ServiceNo, "|", svc.IRIDNo)) AS DispatchID ',
				    'FROM tblservicingdetail AS svc ',
				    'LEFT JOIN tblfsrdetail AS fsr ON svc.ServiceNo = fsr.ServiceNo ',
				    'LEFT JOIN tblparticular AS pr ON svc.MerchantID = pr.ParticularID ',
				    'LEFT JOIN tblservicetype AS stt ON svc.JobType = stt.JobType ',
				    'WHERE (svc.JobTypeStatusDescription IN ("PENDING", "PROCESSING")', ') '
				);
			ELSE
				SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
				    'IFNULL_NUMERIC(st.JobType) AS JobType, ',
				    'IFNULL_STRING_ONLY(st.ServiceJobTypeDescription) AS ServiceJobTypeDescription, ',
				    'IFNULL_NUMERIC(xTable.RegionType) AS RegionType, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Region", xTable.RegionType)) AS Region, ',
				    'IFNULL_NUMERIC(xTable.TCount) AS TCount, ',
				    'IFNULL_NUMERIC(xTable.DispatchID) AS DispatchID, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", xTable.DispatchID)) AS Dispatcher, ',
				    'IFNULL_STRING_ONLY(xTable.JobTypeStatusDescription) AS JobTypeStatusDescription ',
				    'FROM tblservicetype st ',
				    'LEFT JOIN (SELECT ',
				    'svc.JobType AS JobType, ',
				    'pr.RegionType AS RegionType, ',
				    'pr.Province AS Province, ',
				    'COUNT(*) AS TCount, ',
				    'svc.JobTypeStatusDescription AS JobTypeStatusDescription, ',
				    'funcGetID("Search", "Service DispatchID", CONCAT(svc.ServiceNo, "|", svc.IRIDNo)) AS DispatchID ',
				    'FROM tblservicingdetail AS svc ',
				    'LEFT JOIN tblfsrdetail AS fsr ON svc.ServiceNo = fsr.ServiceNo ',
				    'LEFT JOIN tblparticular AS pr ON svc.MerchantID = pr.ParticularID ',
				    'LEFT JOIN tblservicetype AS stt ON svc.JobType = stt.JobType ',
				    'WHERE (fsr.FSRDate BETWEEN ', ADD_SINGLEQUOTE(v_DateFrom), ' AND ', ADD_SINGLEQUOTE(v_DateTo), ') '
				);
			END IF;
			

			IF v_ServiceJobTypeDescription != '[NOT SPECIFIED]' THEN
			    SET p_SQL = CONCAT(
				p_SQL,
				'AND stt.ServiceJobTypeDescription = ', ADD_SINGLEQUOTE(v_ServiceJobTypeDescription), ' '
			    );
			END IF;
			
			IF v_JobTypeStatusDescription != '[NOT SPECIFIED]' THEN
			
				IF v_JobTypeStatusDescription = 'PENDING' || v_JobTypeStatusDescription = 'PROCESSING' || v_JobTypeStatusDescription = 'OVERALL PENDING' THEN
				SET p_SQL = CONCAT(p_SQL,'');
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND svc.JobTypeStatusDescription = ', ADD_SINGLEQUOTE(v_JobTypeStatusDescription), ' '
				    );
				END IF;
			END IF;
			
			IF v_ServiceResult != '[NOT SPECIFIED]' THEN
			
				IF v_JobTypeStatusDescription = 'PENDING' || v_JobTypeStatusDescription = 'PROCESSING' || v_JobTypeStatusDescription = 'OVERALL PENDING' THEN
				SET p_SQL = CONCAT(p_SQL,'');
				ELSE
					SET p_SQL = CONCAT(
						p_SQL,
						'AND fsr.ActionMade = ', ADD_SINGLEQUOTE(v_ServiceResult), ' '
					    );  
				END IF;
			END IF;
			
			IF (LENGTH(v_IncludeBillable) > 0 && v_IncludeBillable != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_IncludeBillable, "BILLABLE") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND svc.isBillable > 0', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND svc.isBillable = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (LENGTH(v_FSRMode) > 0 && v_FSRMode != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_FSRMode, "DIGITAL FSR") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND fsr.MobileID > 0', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND fsr.MobileID = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (v_DispatcherID > 0)
			THEN
				SET p_SQL = CONCAT(
						p_SQL,
						'AND svc.DispatchID = ', v_DispatcherID, ' '
					    );  
			END IF;
			
			IF (v_RegionType > 0)
			THEN
				SET p_SQL = CONCAT(
						p_SQL,
						'AND pr.RegionType = ', v_RegionType, ' '
					    );  
			END IF;
			
			IF (v_ReasonID > 0)
			THEN
				SET p_SQL = CONCAT(
						p_SQL,
						'AND fsr.ReasonID = ', v_ReasonID, ' '
					    );  
			END IF;
			
			IF (v_JobType > 0)
			THEN
			    SET p_SQL = CONCAT(
			    p_SQL,
			    'GROUP BY svc.JobType, pr.RegionType, svc.JobTypeStatusDescription) AS xTable ',
			    'ON xTable.JobType = st.JobType ',
			    'WHERE st.isActive > 0',' ',
			    'AND st.JobType = ', v_JobType,' ',
			    'GROUP BY st.JobType, xTable.RegionType, xTable.JobTypeStatusDescription', ' '
			);
			
			ELSE	
			    SET p_SQL = CONCAT(
			    p_SQL,
			    'GROUP BY svc.JobType, pr.RegionType, svc.JobTypeStatusDescription) AS xTable ',
			    'ON xTable.JobType = st.JobType ',
			    'WHERE st.isActive > 0',' ',
			    'GROUP BY st.JobType, xTable.RegionType, xTable.JobTypeStatusDescription', ' '
			);
			END IF;
			
			# ORDER BY
			SET p_ORDERBY = 'st.SequenceDisplay';
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'ORDER BY ', p_ORDERBY, ' '
					);
			END IF;
							
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Service Detail Report')
		THEN
			SET v_JobTypeStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)); # eg. (PENDING, PROCESSING, COMPLETED...)
			SET v_JobType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER); # eg. (1=INSTALLATION, ....)
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_ServiceJobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)); # eg. (INSTALLATION, SERVICING, ...)
			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)); # eg. (SUCCESS, NEGATIVE)		
			SET v_DateFilter = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)); # eg (TODAY, RANGE)
			
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,9)) AS UNSIGNED INTEGER);
			SET v_FEID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)) AS UNSIGNED INTEGER);
			SET v_DispatcherID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,11)) AS UNSIGNED INTEGER);
			
			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,12));
			SET v_FSRMode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,13));
			
			SET v_RegionType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,14)) AS UNSIGNED INTEGER);
			
			SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,15)) AS UNSIGNED INTEGER);
			
			SET v_DateCondition = '';
			IF v_DateFrom <> '0000-00-00' AND v_DateTo <> '0000-00-00' THEN
				SET v_DateCondition = CONCAT('(', 'vw.Service_Date BETWEEN ', ADD_SINGLEQUOTE(v_DateFrom), ' AND ', ADD_SINGLEQUOTE(v_DateTo), ')');
			ELSE
				SET v_DateCondition = CONCAT(' 1 ');
