				    'IFNULL_STRING_ONLY(xTable.FSRDate) AS FSRDate, ',
				    'IFNULL_STRING_ONLY(xTable.Service_Date) AS Service_Date, ',
				    'IFNULL_STRING_ONLY(xTable.Service_Result) AS Service_Result, ',
