				    'vw.Region AS Region, ',
				    
				    'vw.Job_ID AS Job_ID, ',
				    'vw.Request_ID AS Request_ID, ',
				    'vw.Schedule_Date AS Schedule_Date, ',
				    'vw.Request_Date AS Request_Date, ',
				    'vw.Installation_Date AS Installation_Date, ',
				    'vw.Created_Date AS Created_Date, ',
				    'vw.Target_Date AS Target_Date, ',
				    'vw.Service_Date AS Service_Date, ',
