			# Set WHERE
			SET p_SQL = CONCAT(
				p_SQL,
				'WHERE', ' '
			    );
			
			# Filter Active
			SET p_SQL = CONCAT(
					p_SQL, ' ',
					'vw.isActive = 1', ' '
					);
			
			# With TerminalID
			SET p_SQL = CONCAT(
					p_SQL,
					'AND ir.TerminalID IS NOT NULL', ' '
					);
								
			IF (v_ClientID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Client_ID = ', v_ClientID, ' '
					);
			END IF;
			
			IF (v_LocationID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Loc_ID = ', v_LocationID, ' '
					);
			END IF;
			
			IF (v_StatusID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Status_ID = ', v_StatusID, ' '
					);
			END IF;
			
			IF (v_TerminalTypeID > 0) THEN
