			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Service SLA Report')
