			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_ServiceJobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)); # eg. (INSTALLATION, SERVICING, ...)
			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)); # eg. (SUCCESS, NEGATIVE)		
