			SET p_SQL = '';
			
			IF v_JobTypeStatusDescription = 'PENDING' || v_JobTypeStatusDescription = 'PROCESSING' THEN
				SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
				    'IFNULL_STRING_ONLY(xTable.ReqInstallationDate) AS RequestDate, ',
				    'IFNULL_STRING_ONLY(xTable.ServiceReqDate) AS ScheduleDate, ',
				    'IFNULL_NUMERIC(st.JobType) AS JobType, ',
				    'IFNULL_STRING_ONLY(st.ServiceJobTypeDescription) AS ServiceJobTypeDescription, ',
				    'IFNULL_NUMERIC(xTable.RegionType) AS RegionType, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Region", xTable.RegionType)) AS Region, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Region Detail", xTable.RegionID)) AS Province, ',
				    'IFNULL_NUMERIC(xTable.TCount) AS TCount, ',
				    'IFNULL_NUMERIC(xTable.DispatchID) AS DispatchID, ',
				    'IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", xTable.DispatchID)) AS Dispatcher, ',
				    'IFNULL_STRING_ONLY(xTable.JobTypeStatusDescription) AS JobTypeStatusDescription , ',
				    
				    'IFNULL_STRING_ONLY(funcGetID("Search", "SLA", CONCAT(xTable.RegionType, "|", xTable.RegionID))) AS SLA, ',
				    'IFNULL_STRING_ONLY(funcComputeTAT(xTable.ServiceReqDate, CURRENT_DATE())) AS NetworkDays, ',
				    'IFNULL_STRING_ONLY(funcComputeTAT(xTable.ServiceReqDate, CURRENT_DATE()) - funcGetID("Search", "SLA", CONCAT(xTable.RegionType, "|", xTable.RegionID))) AS DaysOverDue, ',
				    'IFNULL_STRING_ONLY(IF((funcComputeTAT(xTable.ServiceReqDate, CURRENT_DATE()) - funcGetID("Search", "SLA", CONCAT(xTable.RegionType, "|", xTable.RegionID)) > 0), "BEYOND TAT", "WITHIN TAT")) AS TATStatus '

				    'FROM tblservicetype st ',
				    'LEFT JOIN (SELECT ',
