				    'funcGetID("Search", "Service DispatchID", CONCAT(svc.ServiceNo, "|", svc.IRIDNo)) AS DispatchID, ',
				    'svc.ReqInstallationDate, ',
				    'svc.ServiceReqDate ',
				    'FROM tblservicingdetail AS svc ',
				    'LEFT JOIN tblfsrdetail AS fsr ON svc.ServiceNo = fsr.ServiceNo ',
				    'LEFT JOIN tblparticular AS pr ON svc.MerchantID = pr.ParticularID ',
				    'LEFT JOIN tblservicetype AS stt ON svc.JobType = stt.JobType ',
				    'WHERE (fsr.FSRDate BETWEEN ', ADD_SINGLEQUOTE(v_DateFrom), ' AND ', ADD_SINGLEQUOTE(v_DateTo), ') '
				);
			END IF;
			

			IF v_ServiceJobTypeDescription != '[NOT SPECIFIED]' THEN
			    SET p_SQL = CONCAT(
				p_SQL,
				'AND stt.ServiceJobTypeDescription = ', ADD_SINGLEQUOTE(v_ServiceJobTypeDescription), ' '
			    );
			END IF;
			
			IF v_JobTypeStatusDescription != '[NOT SPECIFIED]' THEN
			
				IF v_JobTypeStatusDescription = 'PENDING' || v_JobTypeStatusDescription = 'PROCESSING' || v_JobTypeStatusDescription = 'OVERALL PENDING' THEN
				SET p_SQL = CONCAT(p_SQL,'');
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND svc.JobTypeStatusDescription = ', ADD_SINGLEQUOTE(v_JobTypeStatusDescription), ' '
				    );
				END IF;
			END IF;
			
			IF v_ServiceResult != '[NOT SPECIFIED]' THEN
			
				IF v_JobTypeStatusDescription = 'PENDING' || v_JobTypeStatusDescription = 'PROCESSING' || v_JobTypeStatusDescription = 'OVERALL PENDING' THEN
				SET p_SQL = CONCAT(p_SQL,'');
				ELSE
					SET p_SQL = CONCAT(
						p_SQL,
						'AND fsr.ActionMade = ', ADD_SINGLEQUOTE(v_ServiceResult), ' '
					    );  
				END IF;
			END IF;
			
			IF (LENGTH(v_IncludeBillable) > 0 && v_IncludeBillable != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_IncludeBillable, "BILLABLE") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND svc.isBillable > 0', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND svc.isBillable = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (LENGTH(v_FSRMode) > 0 && v_FSRMode != '[NOT SPECIFIED]')
			THEN
				IF (STRCMP(v_FSRMode, "DIGITAL FSR") = 0)
				THEN
					SET p_SQL = CONCAT(
					p_SQL,
					'AND fsr.MobileID > 0', ' '
				    );
				ELSE
					SET p_SQL = CONCAT(
					p_SQL,
					'AND fsr.MobileID = 0', ' '
				    );
				END IF;
			END IF;
			
			IF (v_DispatcherID > 0)
			THEN
				IF v_JobTypeStatusDescription != 'COMPLETED' THEN
					SET p_SQL = CONCAT(
						p_SQL,
						'AND svc.FEID = ', v_DispatcherID, ' '
					    );  
				ELSE
					SET p_SQL = CONCAT(
						p_SQL,
						'AND svc.DispatchID = ', v_DispatcherID, ' '
					    );  
				END IF;
				
			END IF;
			
			IF (v_RegionType > 0)
			THEN
				SET p_SQL = CONCAT(
						p_SQL,
						'AND pr.RegionType = ', v_RegionType, ' '
					    );  
			END IF;
			
			IF (v_JobType > 0)
			THEN
			    SET p_SQL = CONCAT(
			    p_SQL,
			    'GROUP BY svc.JobType, pr.RegionType, svc.JobTypeStatusDescription, svc.ServiceReqDate) AS xTable ',
			    'ON xTable.JobType = st.JobType ',
			    'WHERE st.isActive > 0',' ',
			    'AND st.JobType = ', v_JobType,' ',
			    'GROUP BY st.JobType, xTable.RegionType, xTable.JobTypeStatusDescription, xTable.ServiceReqDate', ' '
			);
			
			ELSE	
			    SET p_SQL = CONCAT(
			    p_SQL,
			    'GROUP BY svc.JobType, pr.RegionType, svc.JobTypeStatusDescription, svc.ServiceReqDate) AS xTable ',
			    'ON xTable.JobType = st.JobType ',
			    'WHERE st.isActive > 0',' ',
			    'GROUP BY st.JobType, xTable.RegionType, xTable.JobTypeStatusDescription, xTable.ServiceReqDate', ' '
			);
			END IF;
			
			# ORDER BY
			SET p_ORDERBY = 'st.SequenceDisplay';
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'ORDER BY ', p_ORDERBY, ' '
					);
			END IF;
							
			#SELECT CONCAT('Final:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Final:p_SQL = ', p_SQL);
			
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Monthly Service Count')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_IncludeBillable = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET v_FSRMode = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			
			SET v_CurrentMonth = 1;
			SET v_Year = YEAR(CURRENT_DATE());
			
			-- Create a temporary table to store the results
			CREATE TEMPORARY TABLE IF NOT EXISTS monthly_service_results (
			month_name VARCHAR(20),
			month_index INT,
			installation_count INT,
			reprogramming_count INT,
			servicing_count INT,
			replacement_count INT,
			pullout_count INT,
			tcount INT
			);

			WHILE v_CurrentMonth <= 12 DO
			
			SET v_MonthName = MONTHNAME(STR_TO_DATE(CONCAT(v_Year, '-', v_CurrentMonth, '-01'), '%Y-%m-%d'));
			SET v_Temp = CONCAT("|", v_ClientID, "|", v_ServiceResult, "|", v_IncludeBillable, "|", v_FSRMode, "|", v_Year, "|", v_CurrentMonth);
			
			#SELECT (CONCAT("v_Temp=", v_Temp));
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(1, v_Temp), @p_outID);
			SET @installation_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(3, v_Temp), @p_outID);
			SET @reprogramming_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(6, v_Temp), @p_outID);
			SET @servicing_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(7, v_Temp), @p_outID);
			SET @replacement_count = @p_outID;
			
			SET @p_outID = 0;
			CALL spGetCount("Search", "Service Count", CONCAT(4, v_Temp), @p_outID);
			SET @pullout_count = @p_outID;
			
			SET @tcount = 0;
			SET @tcount = @installation_count + @reprogramming_count + @servicing_count + @replacement_count + @pullout_count;
			
			# Insert to temporary table
			INSERT INTO monthly_service_results (month_index, month_name, installation_count, reprogramming_count, servicing_count, replacement_count, pullout_count, tcount)
			VALUES (v_CurrentMonth, v_MonthName,
			@installation_count,
			@reprogramming_count,
			@servicing_count,
			@replacement_count,
			@pullout_count,
			@tcount
			);

			SET v_CurrentMonth = v_CurrentMonth + 1;
			END WHILE;

			# Select service count
			SELECT
			a.month_index AS month_index,
			a.month_name AS month_name,
			installation_count AS TInstallation,
			reprogramming_count AS TReprogramming,
			servicing_count AS TServicing,
			replacement_count AS TReplacement,
			pullout_count AS TPullout,
			tcount AS TCount
			FROM monthly_service_results a;

			# Drop temporary table	
			DROP TEMPORARY TABLE monthly_service_results;
			
		ELSEIF (p_SearchBy = 'Service Attempt-X')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobTypeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_ExcludePending = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
			SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
			SET @ReportStatus = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
			
			#SET v_ExcludePending = 1;
			#SELECT CONCAT("v_JobTypeList=",v_JobTypeList);
			
			# 1,3 = INSTALLATION, REPROGRAMMING (Installation Report)
			# 6,7 = SERVICING, REPLACEMENT	    (Maintenance Report)
			# 4   = PULL-OUT		    (Pull-out Report)
			IF (FIND_IN_SET('1', v_JobTypeList) AND FIND_IN_SET('3', v_JobTypeList)) THEN
				SET @JobTypeList = '1';
			ELSEIF (FIND_IN_SET('6', v_JobTypeList) AND FIND_IN_SET('7', v_JobTypeList)) THEN
				SET @JobTypeList = '2';
			ELSE
				SET @JobTypeList = '3';
			END IF;

			#SELECT CONCAT("JobTypeList=", @JobTypeList);

			SET @isReport = -1;
			IF (@ReportStatus = '[NOT SPECIFIED]') THEN
			    SET @isReport = -1;
			ELSEIF (@ReportStatus = 'INCLUDED') THEN
			    SET @isReport = 1;
			ELSEIF (@ReportStatus = 'EXCLUDED') THEN
			    SET @isReport = 0;
			END IF;

			SET @reportClause = '';

			IF (@isReport = 1) THEN
			    SET @reportClause = ' AND (a.isReport = 1)';
			ELSEIF (@isReport = 0) THEN
			    SET @reportClause = ' AND (a.isReport = 0 OR a.isReport IS NULL)';
			END IF;
			
			SET @baseQuery = '
			SELECT 
			    d.JobType, 
			    funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)) AS JobTypeDesc,
			    
			    #d.isReport AS svc_isReport,
			    #a.isReport AS fsr_isReport,
			    
			    CASE 
				    WHEN a.isReport = 1 THEN "INCLUDED"
				    WHEN a.isReport = 0 THEN "EXCLUDED"
				    ELSE "NOT YET SERVICED"
				END AS ReportStatus,	
			    			    
			    d.MerchantID,			   
			    d.ServiceNo,			    
			    d.IRIDNo,					
			    (IF(a.FSRNo > 0, a.IRNo, d.IRNo)) AS IRNo,
			    b.MID, 
			    b.TID, 					
			    c.Name AS MerchantName,
			    c.Address,
			    c.RegionType,
			    funcGetDesc("Search", "Region", c.RegionType) AS Region,
			    c.RegionID,
			    funcGetDesc("Search", "Region Detail", c.RegionID) AS Province,
			    IFNULL_STRING_ONLY2(a.FSRRefNo)  AS fsrRefNo,
			    IFNULL_STRING_ONLY2(d.ReferenceNo)  AS svcRefNo,
			    IFNULL_STRING_ONLY2(d.Requestor) AS Requestor,
			    IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Request Type"'')) AS RequestType,
			    IFNULL_FORMAT_DATE(COALESCE(d.ServiceDate, "0000-00-00")) AS RequestDate,					
			    IFNULL_FORMAT_DATE(COALESCE(d.ServiceReqDate,"0000-00-00")) AS ScheduleDate,
			    IFNULL_FORMAT_DATE(COALESCE(d.ReqInstallationDate,"0000-00-00")) AS InstallationDate,
			    IFNULL_FORMAT_DATE(COALESCE(d.ReportedDate,"0000-00-00")) AS ReportedDate,
			    
			    funcGetDesc("Search", "Service Status", b.IRStatus) AS Service_Status,
			    funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))) AS ServiceStatus_,
			    
			    b.TerminalSN,
			    funcGetDesc("Search", "TerminalID Model", a.TerminalID) AS TerminalModel,	
			    b.SIMSN,
			    funcGetDesc("Search", "SIMID Carrier", a.SIMID) AS Telco,
			    a.MerchantRepresentative AS MechantRepresentative,
			    a.MerchantRepresentativePosition  AS MechantPosition,
			    a.MerchantContactNo  AS MechantContactNo,
			    a.MerchantRepresentativeEmail  AS MechantEmail,
			    funcGetDesc("Search", "Particular", d.FEID) AS FEName,
			    funcGetDesc("Search", "AreaCode", d.DispatchID) AS AreaCode,
			    funcGetDesc("Search", "Particular", d.DispatchID) AS Dispatcher,
			    IFNULL_STRING_ONLY2(a.ActionTaken) AS ActionTaken,
			    funcGetDesc("Search", "Reason", a.ReasonID) AS Reason,
			    b.AppVersion  AS AppVersion,
			    b.AppCRC  AS AppCRC,
			    "X-----------------------X" AS ExportInclusionStartHere_,	
			    funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)) AS Job_Type_Desc_,	    
			    CONCAT(funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)), " ", "(", funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))), ")") AS ServiceType_
			    ';
			    
			#SELECT @baseQuery; -- Debugging: Print the generated query
			
			IF @JobTypeList = '1' THEN
				    SET @extraFields = ',					
					#IFNULL_STRING_ONLY2(IF(MAX(a.FSRNo) > 0, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
					#IFNULL_STRING_ONLY2(IF(MAX(d.JobType) = 1, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
					IFNULL_STRING_ONLY2(MAX(d.IRNo)) AS RequestID_,
					IFNULL_STRING_ONLY2(MAX(d.Vendor)) AS Vendor_,
					IFNULL_FORMAT_DATE(COALESCE(MAX(d.ReqInstallationDate), d.ServiceReqDate)) AS RequestDate_,
					IFNULL_STRING_ONLY2(MAX(d.Requestor)) AS RequestedBy_,
					
					CASE
					WHEN (d.JobType = 3 OR (d.JobType = 7 AND a.ReasonID IN (60))) THEN
						"REPROGRAMMING"
					ELSE
						IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Request Type"''))

					END AS Request_Type_,
					
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Request Prioritization"'')) AS Request_Prioritization_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Setup"'')) AS POS_Setup_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Type"'')) AS POS_Type_,		
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Connection Type"'')) AS POS_Connection_Type_,	
					IFNULL_FORMAT_DATE(COALESCE(MAX(a.FSRDate),d.ReqInstallationDate)) AS Target_Installation_Date_,					
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Pullout date  (applicable only to exhibit POS Request type)"'')) AS PullOutDateApplicableToExhibitPOS_Req_Type_,
					#IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."RM Instruction / Remarks"'')) AS RM_Instruction_Remarks_,	
					IFNULL_STRING_ONLY2(MAX(d.RMInstruction)) AS RM_Instruction_Remarks_,	
					IFNULL_STRING_ONLY2(MAX(b.MID)) AS Merchant_I_D_,
					IFNULL_STRING_ONLY2(MAX(b.TID)) AS Terminal_I_D_,					
					IFNULL_STRING_ONLY2(c.Name) AS Merchant_DBA_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Address"'')) AS Address_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."City"'')) AS City_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Area 1 (Metro Manila / Provincial)"'')) AS Area_1_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Area 2 (Region/Zone/Area code)"'')) AS Area_2_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Merchant Group"'')) AS Merchant_Group_,				
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Contact Person"'')) AS Contact_Person_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Contact Number"'')) AS Contact_Number_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Bancnet TID"'')) AS Bancnet_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Bancnet MID"'')) AS Bancnet_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Alipay TID"'')) AS Alipay_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Alipay MID"'')) AS Alipay_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Wechat TID"'')) AS Wechat_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Wechat MID"'')) AS Wechat_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Gcash (TID)"'')) AS QR_GCash_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Gcash (mid)"'')) AS QR_GCash_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (TID)"'')) AS QR_Grab_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (MID)"'')) AS QR_Grab_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (TID)"'')) AS QR_UPI_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (MID)"'')) AS QR_UPI_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (TID)"'')) AS QR_P2M_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (MID)"'')) AS QR_P2M_M_I_D_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - Name"'')) AS Multi_merchant_1_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - TID"'')) AS Multi_merchant_1_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - MID"'')) AS Multi_merchant_1_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - Name"'')) AS Multi_merchant_2_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - TID"'')) AS Multi_merchant_2_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - MID"'')) AS Multi_merchant_2_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - Name"'')) AS Multi_merchant_3_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - TID"'')) AS Multi_merchant_3_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - MID"'')) AS Multi_merchant_3_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - Name"'')) AS Multi_merchant_4_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - TID"'')) AS Multi_merchant_4_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - MID"'')) AS Multi_merchant_4_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - Name"'')) AS Multi_merchant_5_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - TID"'')) AS Multi_merchant_5_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - MID"'')) AS Multi_merchant_5_M_I_D_,						

					fnJsonExtract(b.profile_info,''$."DCC (Yes/No)"'') AS DCC_,
					fnJsonExtract(b.profile_info,''$."Installment (Yes/No)"'') AS Installment_,
					fnJsonExtract(b.profile_info,''$."Manual Key Entry (MKE) (Yes/No)"'') AS MKE_,
					fnJsonExtract(b.profile_info,''$."Preauth (Yes/No)"'') AS Preauth_,
					fnJsonExtract(b.profile_info,''$."Offline Sale (Yes/No)"'') AS Offline_Sale_,
					fnJsonExtract(b.profile_info,''$."Offline Sale Limit (To be specified)"'') AS Offline_Sale_Limit_,
					fnJsonExtract(b.profile_info,''$."Tip Adjust (Yes/No)"'') AS Tip_Adjust_,
					fnJsonExtract(b.profile_info,''$."Tip Adjust Limit (To be specified)"'') AS Tip_Adjust_Limit_,
					fnJsonExtract(b.profile_info,''$."Add-on Device  (To be specified)"'') AS Add_On_Device_,
					fnJsonExtract(b.profile_info,''$."ECR Integration (Yes/No)"'') AS ECR_Integration_,
					fnJsonExtract(b.profile_info,''$."ECR Cable Type"'') AS ECR_Cable_Type_
					
				    ';
				ELSE
				    SET @extraFields = ',							
							"-" AS Urgency_,
							"-" AS ScheduleByMerch_,
							
							#IFNULL_STRING_ONLY2(IF(MAX(a.FSRNo) > 0, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
							#IFNULL_STRING_ONLY2(IF(MAX(d.JobType) = 1, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
							IFNULL_STRING_ONLY2(MAX(d.IRNo)) AS RequestID_,
							IFNULL_STRING_ONLY2(MAX(d.Requestor)) AS RequestedBy_,
							
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", MAX(d.SourceID))) AS Source_,
							IFNULL_FORMAT_DATE(COALESCE(MAX(d.ReqInstallationDate), d.ServiceReqDate)) AS RequestDate_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", MAX(d.CategoryID))) AS Category_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", MAX(d.SubCategoryID))) AS SubCategory_,
							
							IFNULL_STRING_ONLY2(MAX(d.ProblemReported)) AS ProblemReported_,
							IFNULL_STRING_ONLY2(MAX(d.Vendor)) AS Vendor_,
							
							IFNULL_STRING_ONLY2(MAX(b.MID)) AS Merchant_I_D_,
							IFNULL_STRING_ONLY2(MAX(b.TID)) AS Terminal_I_D_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.MerchantID))) AS MerchantName_,
							IFNULL_STRING_ONLY2(MAX(c.Address)) AS MerchantAddress_,
							funcGetDesc("Search", "Region", MAX(c.RegionType)) AS Location_,
							IFNULL_STRING_ONLY2(MAX(c.ContactPerson)) AS ContactPerson_,
							IFNULL_STRING_ONLY2(MAX(c.ContactNumber)) AS ContactNumber_,
							IFNULL_STRING_ONLY2(MAX(d.TerminalSN)) AS SerialNumberOptional_							
							';
				END IF;

				IF @JobTypeList = '1' THEN
					SET @addFields = ',
							funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))) AS Status_,
							IFNULL_FORMAT_DATE(MAX(a.FSRDate)) AS Installation_Date_,							
							(funcGetGeneralActionTaken(a.JobType,a.IRIDNo,a.IRNo)) AS Installation_Remarks_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS Status_Reason_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS LatestAttemptReason_,
							funcGetDesc("Search", "Type", MAX(a.DependencyID)) AS Dependency_,
							IFNULL_STRING_ONLY2(MAX(a.TerminalSN)) AS POS_Serial_Number_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "TerminalID Model", MAX(a.TerminalID))) AS POS_Model_,
							IFNULL_STRING_ONLY2(MAX(b.AppVersion)) AS POS_Version_,
							IFNULL_STRING_ONLY2(MAX(b.AppCRC)) AS POS_CRC_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentative)) AS Mechant_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentativePosition)) AS Mechant_Representative_Position_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.FEID))) AS Vendor_Representative_,														
							funcGetDesc("Search", "SIMID Carrier", MAX(a.SIMID)) AS Telco_							
							';
				ELSE
					SET @addFields = ',
							funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))) AS Status_,
							IFNULL_FORMAT_DATE(MAX(a.FSRDate)) AS Date_,
							(funcGetGeneralActionTaken(a.JobType,a.IRIDNo,a.IRNo)) AS Remarks_,							
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS Reason_,
							IFNULL_STRING_ONLY2(MAX(a.AnyComments)) AS AdditionalRemarksIfNecessary_1_,
							funcGetDesc("Search", "Type", MAX(a.DependencyID)) AS Dependency_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS LastAttemptReason_
							';							
				END IF;
				
				SET @addFields = CONCAT(@addFields, ',
							
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason1"'') AS 1stAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate1"'') AS 1stAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable1"'') AS 1stAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason1"'') AS 1stAttemptBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks1"'') AS 1stAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade1"'') AS 1stAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason2"'') AS 2ndAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate2"'') AS 2ndAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable2"'') AS 2ndAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason2"'') AS 2ndAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks2"'') AS 2ndAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade2"'') AS 2ndAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason3"'') AS 3rdAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate3"'') AS 3rdAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable3"'') AS 3rdAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason3"'') AS 3rdAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks3"'') AS 3rdAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade3"'') AS 3rdAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason4"'') AS 4thAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate4"'') AS 4thAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable4"'') AS 4thAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason4"'') AS 4thAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks4"'') AS 4thAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade4"'') AS 4thAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason5"'') AS 5thAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate5"'') AS 5thAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable5"'') AS 5thAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason5"'') AS 5thAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks5"'') AS 5thAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade5"'') AS 5thAttemptActionMade_,

							"-" AS Beyond5thAttemptReason_,
							"-" AS Beyond5thAttemptDate_,
							"-" AS Beyond5thAttemptBillable_,
							"-" AS Beyond5thAttemptReason_,
							"-" AS Beyond5thAttemptRemarks_,
							"-" AS Beyond5thAttemptActionMade_
							') ;
				
				IF (@JobTypeList = '2' OR @JobTypeList = '3') THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.FEID))) AS Vendor_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentative)) AS Mechant_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentativePosition)) AS Mechant_Representative_Position_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantContactNo)) AS Mechant_Representative_ContactNo_
							
							') ;
				END IF;
				
				IF @JobTypeList = '2' THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(
							    MAX(
								CASE 
								    WHEN a.JobType = 7 THEN b.TerminalSN
								    ELSE a.TerminalSN
								END
							    )
							) AS UpdatedSerialNo_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "TerminalID Model", MAX(a.TerminalID))) AS POS_Model_,
							IFNULL_STRING_ONLY2(MAX(b.AppCRC)) AS POS_CRC_,
							IFNULL_STRING_ONLY2(MAX(b.AppVersion)) AS POS_Version_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT(MAX(d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
				ELSEIF @JobTypeList = '3' THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(MAX(a.TerminalSN)) AS ActualSerialNoPulledOut_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT(MAX(d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
					
				END IF;
				
				SET @addFields = CONCAT(@addFields, ',
							#"-" AS BeyondReasonIfApplicable_,
							IFNULL_STRING_ONLY2(MIN(a.BeyondReason)) AS BeyondReasonIfApplicable_,
							"-" AS AdditionalRemarks_,
							funcGetDesc("Search", "AreaCode", MAX(d.DispatchID)) AS Area_,
							funcGetDesc("Search", "Particular", MAX(d.DispatchID)) AS HandlingTL_
							') ;
				
				IF @JobTypeList = '1' THEN
					SET @addFields = CONCAT(@addFields, ',
							funcGetDesc("Search", "Additional Remarks 2", CONCAT(MAX(d.JobType), "|", MAX(d.ServiceNo))) AS AdditionalRemarksIfNecessary_2_
							') ;		
				END IF;
				
				SET @addFields = CONCAT(@addFields, ',
							"-" AS CourierTrackingNumber_,
							"-" AS DateShipped_,
							"-" AS DateArrived_,
							"-" AS TodaDaysHandledByCourier_,
							
							funcGetDesc("Search", "Service Ticket Status", (d.TicketStatus)) AS TicketStatus_,
							IFNULL_FORMAT_DATE((d.TicketDateTime)) AS DateClosed_,
							funcGetDesc("Search", "Particular", (d.TicketID)) AS DispatchersName_
							') ;
				
				IF @JobTypeList = '1' THEN
					SET @addFields = CONCAT(@addFields, ',
							#"-" AS DateReportedToBank_,
							IFNULL_FORMAT_DATE(MAX(d.ReportedDate)) AS DateReportedToBank_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT(MAX(d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
				ELSE
					SET @addFields = CONCAT(@addFields, ',
							"-" AS BankRemarksIfApplicable_,
							funcGetDesc("Search", "Additional Remarks 2", CONCAT(MAX(d.JobType), "|", MAX(d.ServiceNo))) AS AdditionalRemarksIfNecessary_2_,
							#"-" AS DateReportedToBank_,
							IFNULL_FORMAT_DATE(MAX(d.ReportedDate)) AS DateReportedToBank_,
							"-" AS BillingStatus_,
							"-" AS ValidationReason_,
							"-" AS RemarksIfNecessary_
							') ;
				END IF;
				
						
				#SELECT @extraFields; -- Debugging: Print the generated query
				
				SET @fromClause = '
				FROM 
				    tblservicingdetail d 				    
				    LEFT JOIN tblfsrdetail a ON a.ServiceNo = d.ServiceNo
				    LEFT JOIN tblirdetail b ON d.IRIDNo = b.IRIDNo
				    LEFT JOIN tblparticular c ON d.MerchantID = c.ParticularID';
				
				SET @whereBaseClause = '';
				
				IF (@JobTypeList = '1') THEN
				    SET @whereBaseClause = '
					WHERE
					    d.ClientID = ? 
					    AND (FIND_IN_SET(d.JobType, ?))
					    AND (d.IRIDNo = ? OR ? = 0)
					    AND (d.IRNo = ? OR ? = ''0'')
					    AND (a.ReasonID = ? OR ? = 0)
					    AND (
						    -- FSR date condition
						    (a.FSRDate BETWEEN ? AND ?)
						    
						 OR -- ReqInstallationDate + status condition
						    (
							d.ReqInstallationDate BETWEEN ? AND ?
							AND d.ServiceStatus IN (8,9,10)
							AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')
						    )
						 OR -- JobType 7 + Reason 60 must still follow date/status conditions
						    (
							d.JobType = 7
							AND a.ReasonID = 60
							AND (
							    (a.FSRDate BETWEEN ? AND ?)
							    OR (
								d.ReqInstallationDate BETWEEN ? AND ?
								AND d.ServiceStatus IN (8,9,10)
								AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')
							    )
							)
						    )
						)
					    AND d.isActive > 0';
				ELSEIF (@JobTypeList = '2') THEN
					SET @whereBaseClause = '
					   WHERE
					    d.ClientID = ? 
					    AND FIND_IN_SET(d.JobType, ?) 
					    AND (d.IRIDNo = ? OR ? = 0)
					    AND (d.IRNo = ? OR ? = ''0'')
					    AND (a.ReasonID = ? OR ? = 0)
					    AND ((a.FSRDate BETWEEN ? AND ?) OR ((d.ReqInstallationDate BETWEEN ? AND ?) AND d.ServiceStatus IN (8,9,10) AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')) AND (a.ReasonID > 0 AND a.ReasonID NOT IN (60)))				    
					    AND (d.isActive > 0)';
				ELSE
					SET @whereBaseClause = '
					   WHERE
					    d.ClientID = ? 
					    AND FIND_IN_SET(d.JobType, ?) 
					    AND (d.IRIDNo = ? OR ? = 0)
					    AND (d.IRNo = ? OR ? = ''0'')
					    AND (a.ReasonID = ? OR ? = 0)
					    AND ((a.FSRDate BETWEEN ? AND ?) OR ((d.ReqInstallationDate BETWEEN ? AND ?) AND d.ServiceStatus IN (8,9,10) AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')))				    
					    AND (d.isActive > 0)';
				END IF;
				
				-- Append Report Filter
				SET @whereBaseClause = CONCAT(@whereBaseClause, @reportClause);

				#SELECT CONCAT("@whereBaseClause=",@whereBaseClause); -- Debugging: Print the generated query
				
				SET @whereClause = '';  
				SET @whereClause = CONCAT(@whereBaseClause);
				
				#SELECT CONCAT("@whereMaxClause=",@whereMaxClause); -- Debugging: Print the generated query
				
				SET @orderClause = '';
				SET @orderClause = '
				ORDER BY d.ReqInstallationDate, d.IRNo';
				
				SET @groupClause = '';				
				SET @groupClause = '
				GROUP BY d.IRNo';				
				
				#SELECT @fromClause; -- Debugging: Print the generated query
				
				SET @finalQuery = CONCAT(@baseQuery, @extraFields, @addFields, @fromClause, @whereClause);
				
				SET @whereUnionClause = '';
				SET @whereUnionClause = '
				   WHERE
				    d.ClientID = ? 
				    AND FIND_IN_SET(d.JobType, ?) 
				    AND (a.IRIDNo = ? OR ? = 0)
				    AND (a.IRNo = ? OR ? = ''0'')
				    AND (a.ReasonID = ? OR ? = 0)
				    AND ((d.ReqInstallationDate BETWEEN ? AND ?) OR (? = ''0000-00-00'' AND ? = ''0000-00-00''))
				    AND (d.isActive > 0)
				    AND (d.JobTypeStatusDescription IN (''PENDING'', ''PROCESSING''))
				    AND (a.isReport IS NULL OR a.isReport = 1)';
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				
				IF (v_ExcludePending > 0) THEN
					SET @finalQuery = @finalQuery;
				ELSE
					SET @finalQuery = CONCAT(@finalQuery, '
							UNION ALL 
							',
				                        @baseQuery, @extraFields, @addFields, @fromClause, @whereUnionClause);
				END IF;
				
				SET @finalQuery = CONCAT(@finalQuery, ' ', @groupClause, ' ', @orderClause, ';');
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				#SELECT CONCAT("@finalQuery=",@finalQuery); -- Debugging: Print the generated query
				
				SET @TempJobTypeList = @JobTypeList; # hold variable value
				
				SET @ClientID = v_ClientID;
				SET @JobTypeList = v_JobTypeList;
				SET @IRIDNo = v_IRIDNo;
				SET @IRNo = v_IRNo;
				SET @DateFrom = v_DateFrom;
				SET @DateTo = v_DateTo;
				SET @ReasonID = v_ReasonID;

				PREPARE stmt FROM @finalQuery;
				
				IF v_ExcludePending > 0 THEN			
				    IF (@TempJobTypeList = '1') THEN
					EXECUTE stmt USING 
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @ReasonID, @ReasonID, @DateFrom, @DateTo, @DateFrom, @DateTo, @DateFrom, @DateTo, @DateFrom, @DateTo;
				    ELSE
					EXECUTE stmt USING 
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @ReasonID, @ReasonID, @DateFrom, @DateTo, @DateFrom, @DateTo;
				    END IF;
				    
				ELSE
				    EXECUTE stmt USING 
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @ReasonID, @ReasonID, @DateFrom, @DateTo, @DateFrom, @DateTo,
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @DateFrom, @DateTo, @DateFrom, @DateTo;
				END IF;

				DEALLOCATE PREPARE stmt;
			
		ELSEIF (p_SearchBy = 'Unclosed Service Ticket')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_DispatchID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			
			SET @baseQuery = '
			SELECT 
			    a.ServiceNo AS ServiceNo_,
			    a.JobType, 
			    funcGetDesc("Search", "Service JobType Description", a.JobType) AS JobTypeDesc,
			    CONCAT(funcGetDesc("Search", "Service JobType Description", (d.JobType)), " ", "(", funcGetDesc("Search", "Daily Service Status", CONCAT((d.ServiceStatus),"|",(a.ActionMade))), ")") AS ServiceType_,
			    a.MerchantID, 
			    c.RegionType,
			    a.IRIDNo,
			    IFNULL_STRING_ONLY(c.Name) AS MerchantName,
			    IFNULL_STRING_ONLY(b.TID) AS TID, 		
			    IFNULL_STRING_ONLY(b.MID) AS MID, 			    			
			    IFNULL_STRING_ONLY(a.IRNo) AS RequestID,
			    IFNULL_STRING_ONLY(c.Name) AS Merchant_Name_,
			    IFNULL_STRING_ONLY(b.TID) AS TID_,
			    IFNULL_STRING_ONLY(b.MID) AS MID_,
			    funcGetDesc("Search", "Region", c.RegionType) AS Region_, 	
			    funcGetDesc("Search", "Region Detail", c.RegionID) AS Province_,
			    IFNULL_STRING_ONLY(c.Address) AS Address,
			    funcGetDesc("Search", "Region", c.RegionType) AS Region,
			    funcGetDesc("Search", "Region Detail", c.RegionID) AS Province,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", d.FEID)) AS FEName,
			    IFNULL_STRING_ONLY(d.ReqInstallationDate) AS RequestDate,
			    IFNULL_STRING_ONLY(d.ReqInstallationDate) AS Request_Date_,
			    IFNULL_STRING_ONLY(d.ServiceReqDate) AS ScheduleDate,
			    IFNULL_STRING_ONLY(d.ServiceReqDate) AS Schedule_Date_,
			    IFNULL_STRING_ONLY(a.FSRDate) AS CompletionDate,
			    IFNULL_STRING_ONLY(a.ActionMade) AS Service_Result_,
			    funcGetDesc("Search", "Daily Service Status", CONCAT((d.ServiceStatus),"|",(a.ActionMade))) AS Status_,
			    IFNULL_STRING_ONLY(a.MerchantRepresentative) AS MerchantRepresentative_,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", a.FEID)) AS VendorRepresentative_,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Particular", d.DispatchID)) AS DispatcherRepresentative_,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "AreaCode", d.DispatchID)) AS AreaCode_,
			    IFNULL_STRING_ONLY(DATE_FORMAT(a.FSRDate,"%M")) AS Month_,
			    IFNULL_STRING_ONLY(DATE_FORMAT(a.FSRDate,"%Y")) AS Year_,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Billable", d.isBillable)) AS Billable
			    
			';

			#SELECT @baseQuery; -- Debugging: Print the generated query
			
			SET @fromClause = '
			FROM 
			    tblfsrdetail a 
			    LEFT JOIN tblirdetail b ON a.IRIDNo = b.IRIDNo
			    LEFT JOIN tblparticular c ON a.MerchantID = c.ParticularID
			    LEFT JOIN tblservicingdetail d ON a.ServiceNo = d.ServiceNo
			WHERE
			    a.ClientID = ? 
			    AND (a.ServiceNo = ? OR ? = 0)
			    AND (a.IRIDNo = ? OR ? = 0)
			    AND (d.DispatchID = ? OR ? = 0)
			    AND ((a.FSRDate BETWEEN ? AND ?) OR (? = ''0000-00-00'' AND ? = ''0000-00-00''))
			    AND d.TicketStatus = 0
			    AND a.FSRNo > 0
			    AND a.isActive > 0
			ORDER BY a.ServiceNo
			';

			#SELECT @fromClause; -- Debugging: Print the generated query
			
			SET @finalQuery = CONCAT(@baseQuery, @fromClause);
			
			#SELECT @finalQuery; -- Debugging: Print the generated query

			SET @ClientID = v_ClientID;
			SET @ServiceNo = v_ServiceNo;
			SET @IRIDNo = v_IRIDNo;
			SET @DispatchID = v_DispatchID;
			SET @DateFrom = v_DateFrom;
			SET @DateTo = v_DateTo;

			PREPARE stmt FROM @finalQuery;
			EXECUTE stmt USING @ClientID, @ServiceNo, @ServiceNo, @IRIDNo, @IRIDNo, @DispatchID, @DispatchID, @DateFrom, @DateTo, @DateFrom, @DateTo;
			DEALLOCATE PREPARE stmt;
			
		ELSEIF (p_SearchBy = 'Report Data Storage')
		THEN
			# update total
			CALL spUpdateCollectionDetail("Update", p_SearchBy, "");
			
			SET @YearPercent = CONCAT(YEAR(NOW()), '%');
			
			SELECT
			    xTable.StorageType,			  
			    CASE
				WHEN (xTable.StorageType = 1 AND xTable.Title NOT IN ('NEGATIVE/UNSUCCESSFUL ACTIVITY', 'GRAND TOTAL')) OR
				     (xTable.StorageType = 2 AND xTable.Title NOT IN (CONCAT('OVERALL REQUESTS ',@YearPercent), 'GRAND TOTAL')) THEN
					UPPER(xTable.Description)				
				ELSE
					UPPER(xTable.Title)
			    END AS Title,
			    CASE
				WHEN (xTable.StorageType = 1 AND xTable.Title NOT IN ('NEGATIVE/UNSUCCESSFUL ACTIVITY', 'GRAND TOTAL')) OR
				     (xTable.StorageType = 2 AND xTable.Title NOT IN (CONCAT('OVERALL REQUESTS ',@YearPercent) , 'GRAND TOTAL')) THEN
					'-'
				ELSE
					UPPER(xTable.Description)
			    END AS DESCRIPTION,
			    
				IFNULL(UPPER(xTable.January), 0) AS January,
				IFNULL(UPPER(xTable.February), 0) AS February,
				IFNULL(UPPER(xTable.March), 0) AS March,
				IFNULL(UPPER(xTable.April), 0) AS April,
				IFNULL(UPPER(xTable.May), 0) AS May,
				IFNULL(UPPER(xTable.June), 0) AS June,
				IFNULL(UPPER(xTable.July), 0) AS July,
				IFNULL(UPPER(xTable.August), 0) AS August,
				IFNULL(UPPER(xTable.September), 0) AS September,
				IFNULL(UPPER(xTable.October), 0) AS October,
				IFNULL(UPPER(xTable.November), 0) AS November,
				IFNULL(UPPER(xTable.December), 0) AS December,
			    
				CASE
				    WHEN xTable.StorageType = 1 AND xTable.Title = 'NEGATIVE/UNSUCCESSFUL ACTIVITY' THEN 
					'Total'
				    
				    WHEN xTable.StorageType = 7 THEN
					CASE 
					    WHEN xTable.Title = 'CURRENT SLA %' THEN 'YTD'	
					    WHEN xTable.Title = 'GRAND TOTAL' THEN
						CONCAT(
						    ROUND(
							(
							    COALESCE(January, 0) +
							    COALESCE(February, 0) +
							    COALESCE(March, 0) +
							    COALESCE(April, 0) +
							    COALESCE(May, 0) +
							    COALESCE(June, 0) +
							    COALESCE(July, 0) +
							    COALESCE(August, 0) +
							    COALESCE(September, 0) +
							    COALESCE(October, 0) +
							    COALESCE(November, 0) +
							    COALESCE(December, 0)
							) / NULLIF(
							    (CASE WHEN COALESCE(January, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(February, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(March, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(April, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(May, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(June, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(July, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(August, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(September, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(October, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(November, 0) > 0 THEN 1 ELSE 0 END) +
							    (CASE WHEN COALESCE(December, 0) > 0 THEN 1 ELSE 0 END)
							, 0),
						    0), '%')
					    ELSE 
						CONCAT(
						    ROUND(
							(
							    COALESCE(REPLACE(January, '%', '') + 0, 0) +
							    COALESCE(REPLACE(February, '%', '') + 0, 0) +
							    COALESCE(REPLACE(March, '%', '') + 0, 0) +
							    COALESCE(REPLACE(April, '%', '') + 0, 0) +
							    COALESCE(REPLACE(May, '%', '') + 0, 0) +
							    COALESCE(REPLACE(June, '%', '') + 0, 0) +
							    COALESCE(REPLACE(July, '%', '') + 0, 0) +
							    COALESCE(REPLACE(August, '%', '') + 0, 0) +
							    COALESCE(REPLACE(September, '%', '') + 0, 0) +
							    COALESCE(REPLACE(October, '%', '') + 0, 0) +
							    COALESCE(REPLACE(November, '%', '') + 0, 0) +
							    COALESCE(REPLACE(December, '%', '') + 0, 0)
							) / NULLIF(
							    (CASE WHEN REPLACE(January, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(February, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(March, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(April, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(May, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(June, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(July, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(August, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(September, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(October, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(November, '%', '') != '' THEN 1 ELSE 0 END) +
							    (CASE WHEN REPLACE(December, '%', '') != '' THEN 1 ELSE 0 END),
							0), 0), '%')
					END
				    
				    WHEN (xTable.StorageType = 2 AND xTable.Title = CONCAT('OVERALL REQUESTS ',@YearPercent)) 
					OR (xTable.StorageType = 3 AND xTable.Title = 'OVERALL REQUESTS') 
					OR (xTable.StorageType = 4 AND xTable.Title = 'REQUEST WITHIN SLA')
					OR (xTable.StorageType = 6 AND xTable.Title = 'REQUEST PER TEAM LEAD') THEN
					'Count'

				    ELSE 
					xTable.January + xTable.February + xTable.March + xTable.April + 
					xTable.May + xTable.June + xTable.July + xTable.August + 
					xTable.September + xTable.October + xTable.November + xTable.December
				END AS TCount
			    #xTable.TTotal
			FROM
			(
			    SELECT  
				a.StorageType,
				a.Title, 

				CASE 
				    WHEN a.Description IN ('PENDING_', 'PENDING__') THEN 'PENDING'
				    WHEN a.Description IN ('RESOLVED_', 'RESOLVED__') THEN 'RESOLVED'
				    WHEN a.Description IN ('NEGATIVE_', 'NEGATIVE__') THEN 'NEGATIVE'
				    ELSE a.Description 
				END AS DESCRIPTION,

				-- January
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 						
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'January'), '%')
					    ELSE 
						CONCAT(
						    FLOOR((
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('4','|',a.Title,'|','January')) /
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('3','|',a.Title,'|','January'))
						    ) * 100), 
						    '%'
						)
					END
				    WHEN (a.StorageType IN (2, 3, 4) AND a.Description = 'TOTAL') OR a.Title = 'GRAND TOTAL' THEN 
					funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT(a.StorageType,'|',a.Title,'|','January'))
				    ELSE a.January 
				END AS January,

				-- February
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'February'), '%')
					    ELSE 
						CONCAT(
						    FLOOR((
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('4','|',a.Title,'|','February')) /
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('3','|',a.Title,'|','February'))
						    ) * 100), 
						    '%'
						)
					END
				    WHEN (a.StorageType IN (2, 3, 4) AND a.Description = 'TOTAL') OR a.Title = 'GRAND TOTAL' THEN 
					funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT(a.StorageType,'|',a.Title,'|','February'))
				    ELSE a.February 
				END AS February,

				-- March
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'March'), '%')
					    ELSE 
