						    FLOOR((
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('4','|',a.Title,'|','March')) /
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('3','|',a.Title,'|','March'))
						    ) * 100), 
