						)
					END
				    WHEN (a.StorageType IN (2, 3, 4) AND a.Description = 'TOTAL') OR a.Title = 'GRAND TOTAL' THEN 
					funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT(a.StorageType,'|',a.Title,'|','March'))
				    ELSE a.March 
				END AS March,

				-- April
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'April'), '%')
					    ELSE 
						CONCAT(
						    FLOOR((
