						)
					END
				    WHEN (a.StorageType IN (2, 3, 4) AND a.Description = 'TOTAL') OR a.Title = 'GRAND TOTAL' THEN 
					funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT(a.StorageType,'|',a.Title,'|','May'))
				    ELSE a.May 
				END AS May,

				-- June
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'June'), '%')
					    ELSE 
						CONCAT(
						    FLOOR((
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('4','|',a.Title,'|','June')) /
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('3','|',a.Title,'|','June'))
						    ) * 100), 
						    '%'
						)
					END
				    WHEN (a.StorageType IN (2, 3, 4) AND a.Description = 'TOTAL') OR a.Title = 'GRAND TOTAL' THEN 
					funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT(a.StorageType,'|',a.Title,'|','June'))
				    ELSE a.June 
				END AS June,

				-- July
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'July'), '%')
					    ELSE 
						CONCAT(
						    FLOOR((
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('4','|',a.Title,'|','July')) /
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('3','|',a.Title,'|','July'))
						    ) * 100), 
