				    ELSE a.July 
				END AS July,

				-- August
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'August'), '%')
					    ELSE 
