						    FLOOR((
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('4','|',a.Title,'|','August')) /
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('3','|',a.Title,'|','August'))
