						)
					END
				    WHEN (a.StorageType IN (2, 3, 4) AND a.Description = 'TOTAL') OR a.Title = 'GRAND TOTAL' THEN 
					funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT(a.StorageType,'|',a.Title,'|','October'))
				    ELSE a.October 
				END AS October,

				-- November
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'November'), '%')
					    ELSE 
						CONCAT(
						    FLOOR((
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('4','|',a.Title,'|','November')) /
							funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT('3','|',a.Title,'|','November'))
						    ) * 100), 
						    '%'
						)
					END
				    WHEN (a.StorageType IN (2, 3, 4) AND a.Description = 'TOTAL') OR a.Title = 'GRAND TOTAL' THEN 
					funcGetDesc('Search', 'Compute Report Data Storage Total', CONCAT(a.StorageType,'|',a.Title,'|','November'))
				    ELSE a.November 
				END AS November,

				-- December
				CASE 
				    WHEN a.StorageType = 7 AND a.TCount > 0 THEN
					CASE 
					    WHEN a.Title = 'GRAND TOTAL' THEN 
						CONCAT(funcGetDesc('Search', 'Compute Grand Total SLA', 'December'), '%')
					    ELSE 
