		ELSEIF (p_SearchBy = 'Detail Service Attempt-X')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobTypeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_ExcludePending = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
			SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
			
			#SET v_ExcludePending = 1;
			#SELECT CONCAT("v_JobTypeList=",v_JobTypeList);
			
			# 1,3 = INSTALLATION, REPROGRAMMING (Installation Report)
			# 6,7 = SERVICING, REPLACEMENT	    (Maintenance Report)
			# 4   = PULL-OUT		    (Pull-out Report)
			SET @reasonCondition = '';
			IF (FIND_IN_SET('1', v_JobTypeList) AND FIND_IN_SET('3', v_JobTypeList)) THEN
				SET @JobTypeList = '1';
				SET @reasonCondition = 'AND (a.ReasonID > 0 OR a.ReasonID IN (60) OR a.ReasonID IS NULL) ';
			ELSEIF (FIND_IN_SET('6', v_JobTypeList) AND FIND_IN_SET('7', v_JobTypeList)) THEN
				SET @JobTypeList = '2';
				SET @reasonCondition = 'AND (a.ReasonID NOT IN (60) OR a.ReasonID IS NULL) ';
			ELSE
				SET @JobTypeList = '3';
			END IF;

			#SELECT CONCAT("JobTypeList=", @JobTypeList);
			
			SET @baseQuery = '
			SELECT 
			    d.JobType, 
			    funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)) AS JobTypeDesc,
			    
			    #a.isReport AS isReport_FSR,
			    #d.isReport AS isReport_SVC,	
			    
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Get TAT Status 2", funcGetDesc("Search", "Get DaysOverDue 2", CONCAT(d.MerchantID,"|",d.ServiceNo)))) AS TAT_Status_,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Get DaysOverDue 2", CONCAT(d.MerchantID,"|",d.ServiceNo))) AS Days_Over_Due_,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Get NetworkDays 2", d.ServiceNo)) AS Network_Days_,
			    IFNULL_FORMAT_DATE2(d.ReqInstallationDate) AS Request_Date_,
			    IFNULL_FORMAT_DATE2(IF(d.JobType = 1, b.InstallationDate, d.ServiceReqDate)) AS Target_Date_,
			    IFNULL_FORMAT_DATE2(d.ServiceReqDate) AS Schedule_Date_,
			    IFNULL_FORMAT_DATE2(a.FSRDate) AS Serviced_Date_,
			    IFNULL_STRING_ONLY(funcGetDesc("Search", "Get SLA 2", CONCAT(d.MerchantID,"|",d.ServiceNo))) AS SLA_,
			    
			    d.ServiceNo,		    
			    d.MerchantID,			    
			    d.IRIDNo,					
			    (IF(a.FSRNo > 0, a.IRNo, d.IRNo)) AS IRNo,
			    b.MID, 
			    b.TID, 					
			    c.Name AS MerchantName,
			    c.Address,
			    c.RegionType,
			    funcGetDesc("Search", "Region", c.RegionType) AS Region,
			    c.RegionID,
			    funcGetDesc("Search", "Region Detail", c.RegionID) AS Province,
			    IFNULL_STRING_ONLY2(a.FSRRefNo)  AS fsrRefNo,
			    IFNULL_STRING_ONLY2(d.ReferenceNo)  AS svcRefNo,
			    IFNULL_STRING_ONLY2(d.Requestor) AS Requestor,
			    IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Request Type"'')) AS RequestType,
			    
			    IFNULL_FORMAT_DATE2(COALESCE(d.ServiceDate, "0000-00-00")) AS RequestDate,				   			
			    IFNULL_FORMAT_DATE2(COALESCE(d.ServiceReqDate,"0000-00-00")) AS ScheduleDate,
			    IFNULL_FORMAT_DATE2(COALESCE(d.ReqInstallationDate,"0000-00-00")) AS InstallationDate,
			    IFNULL_FORMAT_DATE2(COALESCE(a.FSRDate,"0000-00-00")) AS ServicedDate,
			    IFNULL_FORMAT_DATE2(COALESCE(d.ReportedDate,"0000-00-00")) AS ReportedDate,
			    
			    funcGetDesc("Search", "Service Status", b.IRStatus) AS Service_Status,
			    funcGetDesc("Search", "Daily Service Status", CONCAT(d.ServiceStatus,"|",IFNULL(a.ActionMade, ""))) AS ServiceStatus_,
			    
			    b.TerminalSN,
			    funcGetDesc("Search", "TerminalID Model", a.TerminalID) AS TerminalModel,	
			    b.SIMSN,
			    funcGetDesc("Search", "SIMID Carrier", a.SIMID) AS Telco,
			    a.MerchantRepresentative AS MechantRepresentative,
			    a.MerchantRepresentativePosition  AS MechantPosition,
			    a.MerchantContactNo  AS MechantContactNo,
			    a.MerchantRepresentativeEmail  AS MechantEmail,
			    funcGetDesc("Search", "Particular", d.FEID) AS FEName,
			    funcGetDesc("Search", "AreaCode", d.DispatchID) AS AreaCode,
			    funcGetDesc("Search", "Particular", d.DispatchID) AS Dispatcher,
			    IFNULL_STRING_ONLY2(a.ActionTaken) AS ActionTaken,
			    funcGetDesc("Search", "Reason", a.ReasonID) AS Reason,
			    b.AppVersion  AS AppVersion,
			    b.AppCRC  AS AppCRC,
			    "X-----------------------X" AS ExportInclusionStartHere_,	
			    funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)) AS Job_Type_Desc_,	    
			    CONCAT(
				    funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)), 
				    " (", 
				    funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus), "|", IFNULL(MAX(a.ActionMade), ""))), 
				    ")"
				) AS ServiceType_

			    ';

			#SELECT @baseQuery; -- Debugging: Print the generated query
			
			IF @JobTypeList = '1' THEN
				    SET @extraFields = ',					
					#IFNULL_STRING_ONLY2(IF((a.FSRNo) > 0, (a.IRNo), (d.IRNo))) AS RequestID_,
					#IFNULL_STRING_ONLY2(IF((d.JobType) = 1, (a.IRNo), (d.IRNo))) AS RequestID_,
					IFNULL_STRING_ONLY2(d.IRNo) AS RequestID_,
					IFNULL_STRING_ONLY2((d.Vendor)) AS Vendor_,
					IFNULL_FORMAT_DATE(COALESCE((d.ReqInstallationDate), d.ServiceReqDate)) AS RequestDate_,
					IFNULL_STRING_ONLY2((d.Requestor)) AS RequestedBy_,
					
					CASE
						WHEN (d.JobType = 3 OR (d.JobType = 7 AND a.ReasonID IN (60))) THEN
							"REPROGRAMMING"
						ELSE
							funcGetDesc("Search", "Type", b.RequestTypeID)
						
					END AS Request_Type_,
					
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Request Prioritization"'')) AS Request_Prioritization_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Setup"'')) AS POS_Setup_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Type"'')) AS POS_Type_,		
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Connection Type"'')) AS POS_Connection_Type_,	
					IFNULL_FORMAT_DATE(COALESCE((a.FSRDate),d.ReqInstallationDate)) AS Target_Installation_Date_,						
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Pullout date  (applicable only to exhibit POS Request type)"'')) AS PullOutDateApplicableToExhibitPOS_Req_Type_,	
					#IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."RM Instruction / Remarks"'')) AS RM_Instruction_Remarks_,		
					IFNULL_STRING_ONLY2(d.RMInstruction) AS RM_Instruction_Remarks_,
					IFNULL_STRING_ONLY2((b.MID)) AS Merchant_I_D_,
					IFNULL_STRING_ONLY2((b.TID)) AS Terminal_I_D_,					
					IFNULL_STRING_ONLY2(c.Name) AS Merchant_DBA_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Address"'')) AS Address_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."City"'')) AS City_,
					#IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Area 1 (Metro Manila / Provincial)"'')) AS Area_1_,
					funcGetDesc("Search", "Region", (c.RegionType)) AS Area_1_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Area 2 (Region/Zone/Area code)"'')) AS Area_2_					
				    ';
				    
				    SET @extraFields = ',					
					#IFNULL_STRING_ONLY2(IF((a.FSRNo) > 0, (a.IRNo), (d.IRNo))) AS RequestID_,
					#IFNULL_STRING_ONLY2(IF((d.JobType) = 1, (a.IRNo), (d.IRNo))) AS RequestID_,
					IFNULL_STRING_ONLY2(d.IRNo) AS RequestID_,
					IFNULL_STRING_ONLY2((d.Vendor)) AS Vendor_,
					IFNULL_FORMAT_DATE(COALESCE((d.ReqInstallationDate), d.ServiceReqDate)) AS RequestDate_,
					IFNULL_STRING_ONLY2((d.Requestor)) AS RequestedBy_,
					
					CASE
						WHEN (d.JobType = 3 OR (d.JobType = 7 AND a.ReasonID IN (60))) THEN
							"REPROGRAMMING"
						ELSE
							funcGetDesc("Search", "Type", b.RequestTypeID)
						
					END AS Request_Type_,
					
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Request Prioritization"'')) AS Request_Prioritization_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Setup"'')) AS POS_Setup_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Type"'')) AS POS_Type_,		
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Connection Type"'')) AS POS_Connection_Type_,	
					IFNULL_FORMAT_DATE(COALESCE((a.FSRDate),d.ReqInstallationDate)) AS Target_Installation_Date_,					
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Pullout date  (applicable only to exhibit POS Request type)"'')) AS PullOutDateApplicableToExhibitPOS_Req_Type_,	
					#IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."RM Instruction / Remarks"'')) AS RM_Instruction_Remarks_,	
					IFNULL_STRING_ONLY2(d.RMInstruction) AS RM_Instruction_Remarks_,	
					IFNULL_STRING_ONLY2((b.MID)) AS Merchant_I_D_,
					IFNULL_STRING_ONLY2((b.TID)) AS Terminal_I_D_,					
					IFNULL_STRING_ONLY2(c.Name) AS Merchant_DBA_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Address"'')) AS Address_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."City"'')) AS City_,
					#IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Area 1 (Metro Manila / Provincial)"'')) AS Area_1_,
					funcGetDesc("Search", "Region", (c.RegionType)) AS Area_1_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Area 2 (Region/Zone/Area code)"'')) AS Area_2_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Merchant Group"'')) AS Merchant_Group_,				
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Contact Person"'')) AS Contact_Person_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Contact Number"'')) AS Contact_Number_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Bancnet TID"'')) AS Bancnet_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Bancnet MID"'')) AS Bancnet_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Alipay TID"'')) AS Alipay_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Alipay MID"'')) AS Alipay_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Wechat TID"'')) AS Wechat_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Wechat MID"'')) AS Wechat_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Gcash (TID)"'')) AS QR_GCash_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Gcash (mid)"'')) AS QR_GCash_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (TID)"'')) AS QR_Grab_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (MID)"'')) AS QR_Grab_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (TID)"'')) AS QR_UPI_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (MID)"'')) AS QR_UPI_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (TID)"'')) AS QR_P2M_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (MID)"'')) AS QR_P2M_M_I_D_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - Name"'')) AS Multi_merchant_1_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - TID"'')) AS Multi_merchant_1_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - MID"'')) AS Multi_merchant_1_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - Name"'')) AS Multi_merchant_2_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - TID"'')) AS Multi_merchant_2_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - MID"'')) AS Multi_merchant_2_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - Name"'')) AS Multi_merchant_3_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - TID"'')) AS Multi_merchant_3_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - MID"'')) AS Multi_merchant_3_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - Name"'')) AS Multi_merchant_4_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - TID"'')) AS Multi_merchant_4_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - MID"'')) AS Multi_merchant_4_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - Name"'')) AS Multi_merchant_5_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - TID"'')) AS Multi_merchant_5_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - MID"'')) AS Multi_merchant_5_M_I_D_,						

					fnJsonExtract(b.profile_info,''$."DCC (Yes/No)"'') AS DCC_,
					fnJsonExtract(b.profile_info,''$."Installment (Yes/No)"'') AS Installment_,
					fnJsonExtract(b.profile_info,''$."Manual Key Entry (MKE) (Yes/No)"'') AS MKE_,
					fnJsonExtract(b.profile_info,''$."Preauth (Yes/No)"'') AS Preauth_,
					fnJsonExtract(b.profile_info,''$."Offline Sale (Yes/No)"'') AS Offline_Sale_,
					fnJsonExtract(b.profile_info,''$."Offline Sale Limit (To be specified)"'') AS Offline_Sale_Limit_,
					fnJsonExtract(b.profile_info,''$."Tip Adjust (Yes/No)"'') AS Tip_Adjust_,
					fnJsonExtract(b.profile_info,''$."Tip Adjust Limit (To be specified)"'') AS Tip_Adjust_Limit_,
					fnJsonExtract(b.profile_info,''$."Add-on Device  (To be specified)"'') AS Add_On_Device_,
					fnJsonExtract(b.profile_info,''$."ECR Integration (Yes/No)"'') AS ECR_Integration_,
					fnJsonExtract(b.profile_info,''$."ECR Cable Type"'') AS ECR_Cable_Type_
					
				    ';
				    
				ELSE
				    SET @extraFields = ',							
							"-" AS Urgency_,
							"-" AS ScheduleByMerch_,
							
							#IFNULL_STRING_ONLY2(IF((a.FSRNo) > 0, (a.IRNo), (d.IRNo))) AS RequestID_,
							#IFNULL_STRING_ONLY2(IF((d.JobType) = 1, (a.IRNo), (d.IRNo))) AS RequestID_,
							IFNULL_STRING_ONLY2(d.IRNo) AS RequestID_,
							IFNULL_STRING_ONLY2((d.Requestor)) AS RequestedBy_,
							
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", (d.SourceID))) AS Source_,
							IFNULL_FORMAT_DATE(COALESCE((d.ReqInstallationDate), d.ServiceReqDate)) AS RequestDate_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", (d.CategoryID))) AS Category_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", (d.SubCategoryID))) AS SubCategory_,
							
							IFNULL_STRING_ONLY2((d.ProblemReported)) AS ProblemReported_,
							IFNULL_STRING_ONLY2((d.Vendor)) AS Vendor_,
							
							IFNULL_STRING_ONLY2((b.MID)) AS Merchant_I_D_,
							IFNULL_STRING_ONLY2((b.TID)) AS Terminal_I_D_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", (d.MerchantID))) AS MerchantName_,
							IFNULL_STRING_ONLY2((c.Address)) AS MerchantAddress_,
							funcGetDesc("Search", "Region", (c.RegionType)) AS Location_,
							IFNULL_STRING_ONLY2((c.ContactPerson)) AS ContactPerson_,
							IFNULL_STRING_ONLY2((c.ContactNumber)) AS ContactNumber_,
							IFNULL_STRING_ONLY2(d.TerminalSN) AS SerialNumberOptional_
							';
				END IF;

				IF @JobTypeList = '1' THEN
					SET @addFields = ',
							funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))) AS Status_,
							IFNULL_FORMAT_DATE(MAX(a.FSRDate)) AS Installation_Date_,							
							(funcGetGeneralActionTaken(a.JobType,a.IRIDNo,a.IRNo)) AS Installation_Remarks_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS Status_Reason_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS LatestAttemptReason_,
							funcGetDesc("Search", "Type", (a.DependencyID)) AS Dependency_,
							IFNULL_STRING_ONLY2((a.TerminalSN)) AS POS_Serial_Number_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "TerminalID Model", (a.TerminalID))) AS POS_Model_,
							IFNULL_STRING_ONLY2((b.AppVersion)) AS POS_Version_,
							IFNULL_STRING_ONLY2((b.AppCRC)) AS POS_CRC_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentative)) AS Mechant_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentativePosition)) AS Mechant_Representative_Position_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.FEID))) AS Vendor_Representative_,														
							funcGetDesc("Search", "SIMID Carrier", MAX(a.SIMID)) AS Telco_							
							';
				ELSE
					SET @addFields = ',
							funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))) AS Status_,
							IFNULL_FORMAT_DATE(MAX(a.FSRDate)) AS Date_,
							(funcGetGeneralActionTaken(a.JobType,a.IRIDNo,a.IRNo)) AS Remarks_,							
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS Reason_,
							IFNULL_STRING_ONLY2((a.AnyComments)) AS AdditionalRemarksIfNecessary_1_,
							funcGetDesc("Search", "Type", (a.DependencyID)) AS Dependency_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS LastAttemptReason_
							';							
				END IF;
				
				
				SET @addFields = CONCAT(@addFields, ',
							
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason1"'') AS 1stAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate1"'') AS 1stAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable1"'') AS 1stAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason1"'') AS 1stAttemptBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks1"'') AS 1stAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade1"'') AS 1stAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason2"'') AS 2ndAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate2"'') AS 2ndAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable2"'') AS 2ndAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason2"'') AS 2ndAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks2"'') AS 2ndAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade2"'') AS 2ndAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason3"'') AS 3rdAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate3"'') AS 3rdAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable3"'') AS 3rdAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason3"'') AS 3rdAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks3"'') AS 3rdAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade3"'') AS 3rdAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason4"'') AS 4thAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate4"'') AS 4thAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable4"'') AS 4thAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason4"'') AS 4thAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks4"'') AS 4thAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade4"'') AS 4thAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason5"'') AS 5thAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate5"'') AS 5thAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable5"'') AS 5thAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason5"'') AS 5thAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks5"'') AS 5thAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade5"'') AS 5thAttemptActionMade_,

							"-" AS Beyond5thAttemptReason_,
							"-" AS Beyond5thAttemptDate_,
							"-" AS Beyond5thAttemptBillable_,
							"-" AS Beyond5thAttemptReason_,
							"-" AS Beyond5thAttemptRemarks_,
							"-" AS Beyond5thAttemptActionMade_
							') ;
				
				IF (@JobTypeList = '2' OR @JobTypeList = '3') THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.FEID))) AS Vendor_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentative)) AS Mechant_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentativePosition)) AS Mechant_Representative_Position_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantContactNo)) AS Mechant_Representative_ContactNo_
							
							') ;
				END IF;
				
				IF @JobTypeList = '2' THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(
							    CASE 
								WHEN a.JobType = 7 THEN b.TerminalSN
								ELSE a.TerminalSN
							    END
							) AS UpdatedSerialNo_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "TerminalID Model", (a.TerminalID))) AS POS_Model_,
							IFNULL_STRING_ONLY2((b.AppCRC)) AS POS_CRC_,
							IFNULL_STRING_ONLY2((b.AppVersion)) AS POS_Version_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT((d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
				ELSEIF @JobTypeList = '3' THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2((a.TerminalSN)) AS ActualSerialNoPulledOut_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT((d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
					
				END IF;
				
				SET @addFields = CONCAT(@addFields, ',
							#"-" AS BeyondReasonIfApplicable_,
							IFNULL_STRING_ONLY2(a.BeyondReason) AS BeyondReasonIfApplicable_,
							"-" AS AdditionalRemarks_,
							funcGetDesc("Search", "AreaCode", (d.DispatchID)) AS Area_,
							funcGetDesc("Search", "Particular", (d.DispatchID)) AS HandlingTL_
							') ;
				
				IF @JobTypeList = '1' THEN
					SET @addFields = CONCAT(@addFields, ',
							funcGetDesc("Search", "Additional Remarks 2", CONCAT((d.JobType), "|", (d.ServiceNo))) AS AdditionalRemarksIfNecessary_2_
							') ;		
				END IF;
				
				SET @addFields = CONCAT(@addFields, ',
							"-" AS CourierTrackingNumber_,
							"-" AS DateShipped_,
							"-" AS DateArrived_,
							"-" AS TodaDaysHandledByCourier_,
							
							funcGetDesc("Search", "Service Ticket Status", MAX(d.TicketStatus)) AS TicketStatus_,
							IFNULL_FORMAT_DATE(MAX(d.TicketDateTime)) AS DateClosed_,
							funcGetDesc("Search", "Particular", MAX(d.TicketID)) AS DispatchersName_
							') ;
				
				IF @JobTypeList = '1' THEN
					SET @addFields = CONCAT(@addFields, ',
							#"-" AS DateReportedToBank_,
							IFNULL_FORMAT_DATE(d.ReportedDate) AS DateReportedToBank_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT((d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
				ELSE
					SET @addFields = CONCAT(@addFields, ',
							"-" AS BankRemarksIfApplicable_,
							funcGetDesc("Search", "Additional Remarks 2", CONCAT((d.JobType), "|", (d.ServiceNo))) AS AdditionalRemarksIfNecessary_2_,
							#"-" AS DateReportedToBank_,
							IFNULL_FORMAT_DATE((d.ReportedDate)) AS DateReportedToBank_,
							"-" AS BillingStatus_,
							"-" AS ValidationReason_,
							"-" AS RemarksIfNecessary_
							') ;
				END IF;
				
						
				#SELECT @extraFields; -- Debugging: Print the generated query
				
				SET @fromClause = '
				FROM 
				    tblservicingdetail d 				    
				    LEFT JOIN tblfsrdetail a ON a.ServiceNo = d.ServiceNo
				    LEFT JOIN tblirdetail b ON d.IRIDNo = b.IRIDNo
				    LEFT JOIN tblparticular c ON d.MerchantID = c.ParticularID';
				
				SET @whereBaseClause = '';
				
				# used always is ReqInstallationDate
				/*
				SET @whereBaseClause = CONCAT('
								   WHERE
								      d.ClientID = ?
								      AND d.isActive > 0
								      AND (FIND_IN_SET(d.JobType, ?) OR (a.ReasonID = 60))
								      AND ((d.ReqInstallationDate BETWEEN ? AND ?) OR (? = ''0000-00-00'' AND ? = ''0000-00-00''))
								      ', @reasonCondition, '								      
								      AND (
									    funcGetDesc("Search", "Daily Service Status", CONCAT(d.ServiceStatus, "|", IFNULL(a.ActionMade, "")))
									    IN ("CANCELLED", "HOLD", "PENDING", "NEGATIVE", "RESOLVED")
									)
								      AND (a.isReport IS NULL OR a.isReport = 1)

								');
				*/
				SET @whereBaseClause = CONCAT('
							    WHERE
								d.ClientID = ?
								AND d.isActive > 0
								AND (
								      FIND_IN_SET(d.JobType, ?)
								      OR (', @JobTypeList, ' <> 3 AND a.ReasonID = 60)
								    )
								AND (
								      (d.ReqInstallationDate BETWEEN ? AND ?)
								      OR (a.FSRDate BETWEEN ? AND ?)
								      OR (? = ''0000-00-00'' AND ? = ''0000-00-00'')
								    )
								', @reasonCondition, '
								AND (
								    funcGetDesc(
									"Search",
									"Daily Service Status",
									CONCAT(d.ServiceStatus, "|", IFNULL(a.ActionMade, ""))
								    )
								    IN ("CANCELLED", "HOLD", "PENDING", "NEGATIVE", "RESOLVED")
								)
								AND (a.isReport IS NULL OR a.isReport = 1)
							');

				#SELECT CONCAT("@whereBaseClause=",@whereBaseClause); -- Debugging: Print the generated query
				
				SET @whereClause = '';  
				SET @whereClause = CONCAT(@whereBaseClause);
				
				#SELECT CONCAT("@whereMaxClause=",@whereMaxClause); -- Debugging: Print the generated query
				
				SET @orderClause = '';
				SET @orderClause = '
				ORDER BY d.ReqInstallationDate, d.IRNo';
				
				SET @groupClause = '';				
				SET @groupClause = '
				GROUP BY d.IRNo';				
				
				#SELECT @fromClause; -- Debugging: Print the generated query
				
				SET @finalQuery = CONCAT(@baseQuery, @extraFields, @addFields, @fromClause, @whereClause);
				
				SET @whereUnionClause = '';
				SET @whereUnionClause = '
				   WHERE
				    d.ClientID = ? 
				    AND FIND_IN_SET(d.JobType, ?) 
				    AND ((d.ReqInstallationDate BETWEEN ? AND ?) OR (? = ''0000-00-00'' AND ? = ''0000-00-00'') AND (d.ServiceNo > 0 OR a.ServiceNo IS NULL))				   
				    AND (d.isActive > 0)
				    AND (d.JobTypeStatusDescription IN (''PENDING'', ''PROCESSING''))';
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				
				IF (v_ExcludePending > 0) THEN
					SET @finalQuery = @finalQuery;
				ELSE
					SET @finalQuery = CONCAT(@finalQuery, '
							UNION ALL 
							',
				                        @baseQuery, @extraFields, @addFields, @fromClause, @whereUnionClause);
				END IF;
				
				SET @finalQuery = CONCAT(@finalQuery, ' ', @groupClause, ' ', @orderClause, ';');
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				#SELECT CONCAT("@finalQuery=",@finalQuery); -- Debugging: Print the generated query
				
				SET @ClientID = v_ClientID;
				SET @JobTypeList = v_JobTypeList;
				SET @IRIDNo = v_IRIDNo;
				SET @IRNo = v_IRNo;
				SET @DateFrom = v_DateFrom;
				SET @DateTo = v_DateTo;
				SET @ReasonID = v_ReasonID;

				PREPARE stmt FROM @finalQuery;
				
				EXECUTE stmt USING @ClientID, @JobTypeList, @DateFrom, @DateTo, @DateFrom, @DateTo, @DateFrom, @DateTo;

				DEALLOCATE PREPARE stmt;
		
		ELSEIF (p_SearchBy = 'Helpdesk-Breakdown-Report')
		THEN		
			SET @Flag = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			
			SELECT 
			    MONTHNAME(hd.CreatedDate) AS `Month`,
			    IFNULL(SUM(CASE WHEN hd.Status = 'PENDING' THEN 1 ELSE 0 END), 0) AS `PENDING`,
			    IFNULL(SUM(CASE WHEN hd.Status = 'SUCCESS' THEN 1 ELSE 0 END), 0) AS `RESOLVED`,
			    IFNULL(SUM(CASE WHEN hd.Status = 'NEGATIVE' THEN 1 ELSE 0 END), 0) AS `NEGATIVE`,
			    IFNULL(COUNT(*), 0) AS `TOTAL`
			FROM tblhddetail hd
			JOIN tblhdmaster hdm ON hdm.AssistNo = hd.AssistNo
			JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
			LEFT JOIN tblparticular pt ON pt.ParticularID = hd.HelpdeskID
			WHERE ir.ClientID = @ClientID
			AND (
			    (@Flag = 'RANGE' AND @DateFrom IS NOT NULL AND @DateFrom != '' 
				AND @DateTo IS NOT NULL AND @DateTo != '' 
				AND DATE(hd.CreatedDate) BETWEEN @DateFrom AND @DateTo)
			    OR (@Flag = 'TODAY' AND DATE(hd.CreatedAt) = CURDATE())
			    OR (@Flag <> 'RANGE' AND @Flag <> 'TODAY')
			)
			GROUP BY MONTH(CreatedDate)
			ORDER BY MONTH(CreatedDate);

		ELSEIF (p_SearchBy = 'Helpdesk-Resolution-Report')
		THEN	
		
			SET @Flag = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);		
			
			-- HELPDESK
			SELECT 
				hd.Name AS Helpdesk_Name,
				IFNULL(hd.Tickets_Resolved, 0) AS Resolved_Tickets,
				IFNULL(CAST(SEC_TO_TIME(hd.Avg_Resolution_Seconds) AS CHAR), 0) AS Avg_Resolution_Time,
				IFNULL(CONCAT(ROUND(hd.FCR_Rate_Numeric, 2), '%'), 0) AS FCR_Rate,
				IFNULL(hd.Backlog, 0) AS Pending_Tickets,
				IFNULL(hd.Total, 0) AS Total
			FROM (
				SELECT
				pt.Name, 
				hd.HelpdeskID,
				SUM(CASE WHEN hd.Status = 'SUCCESS' THEN 1 ELSE 0 END) AS Tickets_Resolved,
				AVG(CASE WHEN hd.Status = 'SUCCESS' THEN TIMESTAMPDIFF(SECOND, hd.TimeStart, hd.TimeEnd) ELSE NULL END) AS Avg_Resolution_Seconds,
				ROUND(SUM(CASE WHEN hd.Status = 'SUCCESS' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0), 2) AS FCR_Rate_Numeric,
				SUM(CASE WHEN hd.Status = 'PENDING' THEN 1 ELSE 0 END) AS Backlog,
				COUNT(*) AS Total
				FROM tblhddetail hd
				JOIN tblhdmaster hdm ON hdm.AssistNo = hd.AssistNo
				JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
				LEFT JOIN tblparticular pt ON pt.ParticularID = hd.HelpdeskID
				WHERE ir.ClientID = @ClientID
				AND (
				    (@Flag = 'RANGE' AND @DateFrom IS NOT NULL AND @DateFrom != '' 
					AND @DateTo IS NOT NULL AND @DateTo != '' 
					AND DATE(hd.CreatedDate) BETWEEN @DateFrom AND @DateTo)
				    OR (@Flag = 'TODAY' AND DATE(hd.CreatedAt) = CURDATE())
				    OR (@Flag <> 'RANGE' AND @Flag <> 'TODAY')
				)
				GROUP BY hd.HelpdeskID
			     ) hd

			UNION ALL

			-- TEAM AVERAGE
			SELECT 
				'TEAM AVERAGE' AS Helpdesk_Name,
				IFNULL(SUM(ta.Tickets_Resolved), 0) AS Resolved_Tickets,
				IFNULL(CAST(SEC_TO_TIME(ta.Avg_Resolution_Seconds) AS CHAR), 0) AS Avg_Resolution_Time,
				IFNULL(CONCAT(ROUND(AVG(ta.FCR_Rate_Numeric), 2), '%'), 0) AS FCR_Rate,
				IFNULL(SUM(ta.Backlog), 0) AS Pending_Tickets,
				IFNULL(SUM(ta.Total), 0) AS Total
			FROM (
				SELECT 
				hd.HelpdeskID,
				SUM(CASE WHEN hd.Status = 'SUCCESS' THEN 1 ELSE 0 END) AS Tickets_Resolved,
				AVG(CASE WHEN hd.Status = 'SUCCESS' THEN TIMESTAMPDIFF(SECOND, hd.TimeStart, hd.TimeEnd) ELSE NULL END) AS Avg_Resolution_Seconds,
				ROUND(SUM(CASE WHEN hd.Status = 'SUCCESS' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0), 2) AS FCR_Rate_Numeric,
				SUM(CASE WHEN hd.Status = 'PENDING' THEN 1 ELSE 0 END) AS Backlog,
				COUNT(*) AS Total
				FROM tblhddetail hd
				JOIN tblhdmaster hdm ON hdm.AssistNo = hd.AssistNo
				JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
				LEFT JOIN tblparticular pt ON pt.ParticularID = hd.HelpdeskID
				WHERE ir.ClientID = @ClientID
				AND (
				    (@Flag = 'RANGE' AND @DateFrom IS NOT NULL AND @DateFrom != '' 
					AND @DateTo IS NOT NULL AND @DateTo != '' 
					AND DATE(hd.CreatedDate) BETWEEN @DateFrom AND @DateTo)
				    OR (@Flag = 'TODAY' AND DATE(hd.CreatedAt) = CURDATE())
				    OR (@Flag <> 'RANGE' AND @Flag <> 'TODAY')
				)
				GROUP BY hd.HelpdeskID
			) ta;
					
		ELSEIF (p_SearchBy = 'Helpdesk-ActualProblem-Report')
		THEN		
			SET @Flag = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
		
			SELECT 
			hd.ActualProblem AS `ACTUAL PROBLEM FOUND`,
			IFNULL(SUM(CASE WHEN hd.Status = 'SUCCESS' THEN 1 ELSE 0 END), 0) AS RESOLVED,
			IFNULL(SUM(CASE WHEN hd.Status = 'NEGATIVE' THEN 1 ELSE 0 END), 0) AS NEGATIVE
		    FROM tblhddetail hd
		    LEFT JOIN tblhdmaster hdm ON hdm.AssistNo = hd.AssistNo
		    LEFT JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
		    WHERE ir.ClientID = @ClientID
		    AND (
			(
			    @Flag = 'RANGE' 
			    AND @DateFrom IS NOT NULL AND @DateFrom != '' 
			    AND @DateTo IS NOT NULL AND @DateTo != '' 
			    AND DATE(hd.CreatedAt) BETWEEN @DateFrom AND @DateTo
			)
			OR (
			    @Flag = 'TODAY' 
			    AND DATE(hd.CreatedAt) = CURDATE()
			)
			OR (
			    @Flag = 'ALL'
			    AND YEAR(hd.CreatedAt) = YEAR(CURDATE())
			)
		    )
		    GROUP BY hd.ProblemID

		    UNION ALL

		    SELECT 
			'TOTAL' AS `ACTUAL PROBLEM FOUND`,
			IFNULL(SUM(CASE WHEN hd.Status = 'SUCCESS' THEN 1 ELSE 0 END), 0) AS RESOLVED,
			IFNULL(SUM(CASE WHEN hd.Status = 'NEGATIVE' THEN 1 ELSE 0 END), 0) AS NEGATIVE
		    FROM tblhddetail hd
		    LEFT JOIN tblhdmaster hdm ON hdm.AssistNo = hd.AssistNo
		    LEFT JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
		    WHERE ir.ClientID = @ClientID
		    AND (
			(
			    @Flag = 'RANGE' 
			    AND @DateFrom IS NOT NULL AND @DateFrom != '' 
			    AND @DateTo IS NOT NULL AND @DateTo != '' 
			    AND DATE(hd.CreatedAt) BETWEEN @DateFrom AND @DateTo
			)
			OR (
			    @Flag = 'TODAY' 
			    AND DATE(hd.CreatedAt) = CURDATE()
			)
			OR (
			    @Flag = 'ALL'
			    AND YEAR(hd.CreatedAt) = YEAR(CURDATE())
			)
		    );
			
		ELSEIF (p_SearchBy = 'Helpdesk-Detailed-Report')
		THEN
			SET @Flag = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET @DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET @DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
			SET @ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET @ReportStatus = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

			SET @isReport = -1;
			IF (@ReportStatus = '[NOT SPECIFIED]') THEN
			    SET @isReport = -1;
			ELSEIF (@ReportStatus = 'INCLUDED') THEN
			    SET @isReport = 1;
			ELSEIF (@ReportStatus = 'EXCLUDED') THEN
			    SET @isReport = 0;
			END IF;
			
			SELECT 
				 hdd.RequestID AS `REQUEST ID`, 
				 hdd.RequestedBy AS `REQUEST BY`,
				 src.Description AS SOURCE,  				 
				 IFNULL_GET_DATE(svc.ReqInstallationDate) AS `REQUEST DATE`,
				 ctg.Description AS `CATEGORY`, 
				 sctg.Description AS `SUB CATEGORY`, 
				 hdd.RemarksHelpDesk AS `REMARKS`, 
				 hdd.ProblemReported AS `PROBLEM REPORTED`, 
				 'CITAS' AS VENDOR,
				 ir.MID,
				 ir.TID, 
				 pt.Name AS `MERCHANT NAME`,
				 pt.Address AS `MERCHANT ADDRESS`,
				 pt.Province AS `MERCHANT LOCATION`,
				 hdd.ContactPerson AS `CONTACT PERSON`,
				 hdd.ContactNo AS `CONTACT NUMEBR`,
				 hdd.TerminalSN AS `TERMINAL SERIAL`,
				 hdd.Status AS `STATUS`,			 
				 IF(hdd.CreatedAt = '0000-00-00 00:00:00', NULL, hdd.CreatedAt) AS `DATE CREATED`, 				 
				 hdd.RemarksService AS `REMARKS`,
				 rs.Description AS REASON,
				 hdd.ActualProblem AS `ACTUAL PROBLEM`,
				 hd.Name AS `HELPDESK NAME`,		 						 
				 IFNULL_GET_DATE(hdd.TimeStart) AS `CALL START DATE`,
				 IFNULL_GET_DATE(hdd.TimeEnd) AS `CALL END DATE`,				 
				 CAST(NULLIF(TIME(hdd.TimeStart), '00:00:00') AS CHAR) AS `CALL START TIME`,
				 CAST(NULLIF(TIME(hdd.TimeEnd), '00:00:00') AS CHAR) AS `CALL END TIME`,
				 (
				  SELECT CAST(MIN(NULLIF(TIME(hdd2.TimeStart), '00:00:00')) AS CHAR)
				  FROM tblhddetail hdd2
				  WHERE hdd2.AssistNo = hdd.AssistNo
				 ) AS `FIRST CALL TIME`,

				 (
				  SELECT CAST(MAX(NULLIF(TIME(hdd2.TimeEnd), '00:00:00')) AS CHAR)
				  FROM tblhddetail hdd2
				  WHERE hdd2.AssistNo = hdd.AssistNo
				 ) AS `LAST CALL TIME`,
				 
				 hdd.Representative AS `REPRESENTATIVE`,
				
				 CASE
				  WHEN IFNULL(svc.TicketStatus, 0) = 1 THEN 'CLOSE TICKET'
				  ELSE 'OPEN TICKET'
				 END AS `TICKET STATUS`,
				 
				 CASE
				  WHEN IFNULL(svc.TicketStatus, 0) = 1
				       AND IFNULL_STRING_ONLY(svc.TicketDateTime) NOT IN ('-', '0', '', '0000-00-00 00:00:00')
				  THEN IFNULL_STRING_ONLY(svc.TicketDateTime)
				  ELSE '-'
				 END AS `DATE CLOSED`,
				 
				(
				    SELECT IFNULL_STRING_ONLY2(funcGetDesc('Search', 'Type', NULLIF(hdd.IssueCategoryID, 0)))
				) AS `ISSUE CATEGORY`

			FROM tblhdmaster hdm
			LEFT JOIN tblhddetail hdd ON hdd.AssistNo = hdm.AssistNo
			LEFT JOIN tbltype src ON src.TypeID = SourceID
			LEFT JOIN tbltype ctg ON ctg.TypeID = CategoryID
			LEFT JOIN tbltype sctg ON sctg.TypeID = SubCategoryID
			LEFT JOIN tbltype rs ON rs.TypeID = hdd.ReasonID
			LEFT JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
			LEFT JOIN tblparticular pt ON pt.ParticularID = ir.MerchantID
			LEFT JOIN tblparticular hd ON hd.ParticularID = hdd.HelpdeskID
			LEFT JOIN tblservicingdetail svc ON hdd.AssistNo = svc.AssistNo
			LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo

			WHERE ir.ClientID = @ClientID
			 			AND (@isReport = -1 OR fsr.isReport = @isReport)			
			-- AND (fsr.isReport = @isReport)
			AND (
			    (
				@Flag = 'RANGE' 
				AND @DateFrom IS NOT NULL AND @DateFrom != '' 
				AND @DateTo IS NOT NULL AND @DateTo != '' 
				AND DATE(hdd.CreatedAt) BETWEEN @DateFrom AND @DateTo
			    )
			    OR (
				@Flag = 'TODAY' 
				AND DATE(hdd.CreatedAt) = CURDATE()
			    )
			    OR (
				@Flag = 'ALL'
				AND YEAR(hdd.CreatedAt) = YEAR(CURDATE())
			    )
			)

			GROUP BY hdd.ProblemNo;
			
		ELSEIF (p_SearchBy = 'Helpdesk-Summary-Report')
		THEN		
		    SET @Flag = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
		    SET @DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		    SET @DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));
		    SET @ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED);
		    SET @ReportStatus = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

		    SET @isReport = -1;
		    IF (@ReportStatus = '[NOT SPECIFIED]') THEN
			SET @isReport = -1;
		    ELSEIF (@ReportStatus = 'INCLUDED') THEN
			SET @isReport = 1;
	            ELSEIF (@ReportStatus = 'EXCLUDED') THEN
			SET @isReport = 0;
		    END IF;
				
		    -- FLAGS
		    SET @IsRange = (@Flag = 'RANGE');
		    SET @IsToday = (@Flag = 'TODAY');
		    SET @IsAll   = (@Flag = 'ALL');

		    -- ===============================
		    -- 1. PER NAME + STATUS
		    -- ===============================
		    SELECT 
			pt.Name AS `NAME`,
			s.Status,

			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=1  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS JANUARY,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=2  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS FEBRUARY,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=3  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS MARCH,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=4  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS APRIL,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=5  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS MAY,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=6  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS JUNE,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=7  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS JULY,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=8  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS AUGUST,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=9  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS SEPTEMBER,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=10 AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS OCTOBER,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=11 AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS NOVEMBER,
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=12 AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0) AS DECEMBER,

			COALESCE(SUM(
			    CASE 
				WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE())
				AND hdd.CreatedDate <= CURDATE()
				THEN 1 ELSE 0 
			    END
			),0) AS TOTAL

		    FROM (
			SELECT DISTINCT hdd.HelpdeskID, pt.Name
			FROM tblhddetail hdd
			JOIN tblhdmaster hdm ON hdm.AssistNo = hdd.AssistNo
			JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
			JOIN tblparticular pt ON pt.ParticularID = hdd.HelpdeskID
			WHERE hdd.HelpdeskID IS NOT NULL
		    ) pt

		    CROSS JOIN (
			SELECT 'TOTAL' AS STATUS
			UNION ALL SELECT 'NEGATIVE'
			UNION ALL SELECT 'RESOLVED'
			UNION ALL SELECT 'PENDING'
		    ) s

		    LEFT JOIN tblhddetail hdd 
			ON hdd.HelpdeskID = pt.HelpdeskID
			AND (
			    (s.Status = 'TOTAL')
			    OR (s.Status = 'RESOLVED' AND hdd.Status = 'SUCCESS')
			    OR (s.Status = 'NEGATIVE' AND hdd.Status = 'NEGATIVE')
			    OR (s.Status = 'PENDING' AND hdd.Status = 'PENDING')
			)

		    LEFT JOIN tblhdmaster hdm ON hdm.AssistNo = hdd.AssistNo
		    LEFT JOIN tblirdetail ir 
		    ON ir.IRIDNo = hdm.IRIDNo
		    AND ir.ClientID = @ClientID
		    AND (
			(@IsRange AND DATE(hdd.CreatedDate) BETWEEN @DateFrom AND @DateTo)
			OR (@IsToday AND DATE(hdd.CreatedDate) = CURDATE())
			OR (@IsAll AND YEAR(hdd.CreatedDate) = YEAR(CURDATE()))
		    )

		    WHERE (ir.ClientID = @ClientID OR ir.ClientID IS NULL)

		    GROUP BY pt.HelpdeskID, s.Status

		    UNION ALL

		    -- ===============================
		    -- 2. GRAND TOTAL
		    -- ===============================
		    SELECT 
			'GRAND TOTAL',
			'TOTAL',

			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=1  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=2  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=3  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=4  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=5  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=6  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=7  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=8  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=9  AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=10 AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=11 AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),
			COALESCE(SUM(CASE WHEN YEAR(hdd.CreatedDate)=YEAR(CURDATE()) AND MONTH(hdd.CreatedDate)=12 AND hdd.CreatedDate <= CURDATE() THEN 1 ELSE 0 END),0),

			COUNT(*)

		    FROM tblhddetail hdd
		    JOIN tblhdmaster hdm ON hdm.AssistNo = hdd.AssistNo
		    JOIN tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
		    LEFT JOIN tblservicingdetail svc ON hdd.AssistNo = svc.AssistNo
		    LEFT JOIN tblfsrdetail fsr ON svc.ServiceNo = fsr.ServiceNo
		    WHERE ir.ClientID = @ClientID
		    AND (fsr.isReport = @isReport)
		    AND (
			(@IsRange AND DATE(hdd.CreatedDate) BETWEEN @DateFrom AND @DateTo)
			OR (@IsToday AND DATE(hdd.CreatedDate) = CURDATE())
			OR (@IsAll AND YEAR(hdd.CreatedDate) = YEAR(CURDATE()))
		    )

		    ORDER BY
			CASE WHEN NAME = 'GRAND TOTAL' THEN 2 ELSE 1 END,
			NAME,
			FIELD(STATUS, 'TOTAL', 'NEGATIVE', 'RESOLVED', 'PENDING');
		
		ELSEIF (p_SearchBy = 'Helpdesk-Service-Report')
		THEN		
			SET @ProbNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			
			SELECT 
			 #Header
			 hd.ProblemNo,
			 hd.AssistNo,
			 
			 #Client
			 ir.ClientName,
			 cl.Name AS MerchantName,
			 cl.Address,
			 IF(cl.ContactNumber = NULL, cl.TelNo, cl.Mobile) AS ContactNumber,
			 cl.ContactPerson,
			 cl.Province,
			 cl.Region,
			 
			 #Service
			 DATE_FORMAT(hd.CreatedDate, '%b-%d-%Y') AS CreatedDate,
			 hd.ProblemNo,
			 CASE WHEN 6 THEN 'SERVICING'ELSE hdm.JobType END AS ServiceType,
			 DATE_FORMAT(hd.RequestDate, '%b-%d-%Y') AS RequestDate,
			 hd.RequestID,
			 
			 #Additional
			 hdm.ReferenceNo,
			 hd.RequestedBy,
			 hd.ContactNo, 
			 ir.TID,
			 ir.MID,
			 ir.PrimaryNum,
			 ir.SecondaryNum,
			 hd.AppVersion,
			 hd.AppCRC,
			 
			 #Details
			 DATE_FORMAT(hd.CreatedAt, '%b-%d-%Y') AS CreatedAt,
			 TIME(hd.TimeAssisted) AS TimeAssisted,
			 TIME(hd.TimeStart) AS TimeStart,
			 TIME(hd.TimeEnd) AS TimeEnd,
			 td.Type,
			 td.Model,
			 td.Brand,
			 td.TerminalSN,
			 sd.SIMSN,
			 sd.Carrier,
			 
			 #Remarks
			 hd.ProblemReported,
			 hd.ActualProblem,
			 hd.RemarksService AS ActionMade,
			 hd.RemarksHelpdesk AS HelpdeskRemarks,
			 
			 #Person
			 hd.Representative,
			 hn.Name AS HelpdeskName,
			 tl.Name AS TeamLeader
			 
			 
			FROM 
			 tblhddetail hd

			JOIN 
			 tblhdmaster hdm ON hdm.AssistNo = hd.AssistNo
			LEFT JOIN 
			 tblirdetail ir ON ir.IRIDNo = hdm.IRIDNo
			JOIN
			 tblparticular cl ON cl.ParticularID = ir.MerchantID
			 JOIN
			 tblparticular hn ON hn.ParticularID = hd.HelpdeskID
			 JOIN
			 tblparticular tl ON tl.ParticularID = hd.TeamLeadID
			LEFT JOIN
			 tblreason rs ON rs.ReasonID = hd.ReasonID
			LEFT JOIN
			 tblreason pb ON pb.ReasonID = hd.ProblemID
			JOIN
			 tblterminaldetail td ON td.TerminalID = hd.TerminalID
			JOIN
			 tblsimdetail sd ON sd.SIMID = hd.SIMID

			WHERE hd.ProblemNo = @ProbNo;
			
		# New template(Detail tab)    
		ELSEIF (p_SearchBy = 'Detail Service Attempt')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobTypeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_ExcludePending = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
			SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
			SET @ReportStatus = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
			SET @ReportType = COALESCE(TRIM(SPLIT_STRING(p_SearchValue, '|' ,10)),0);
			
			#SET v_ExcludePending = 1;
			#SELECT CONCAT("v_JobTypeList=",v_JobTypeList);
			
			# 1,3 = INSTALLATION, REPROGRAMMING (Installation Report)
			# 6,7 = SERVICING, REPLACEMENT	    (Maintenance Report)
			# 4   = PULL-OUT		    (Pull-out Report)
			SET @reasonCondition = '';
			IF (FIND_IN_SET('1', v_JobTypeList) AND FIND_IN_SET('3', v_JobTypeList)) THEN
				SET @JobTypeList = '1';
				SET @reasonCondition = 'AND (a.ReasonID > 0 OR a.ReasonID IN (60) OR a.ReasonID IS NULL) ';
			ELSEIF (FIND_IN_SET('6', v_JobTypeList) AND FIND_IN_SET('7', v_JobTypeList)) THEN
				SET @JobTypeList = '2';
				SET @reasonCondition = 'AND (a.ReasonID NOT IN (60) OR a.ReasonID IS NULL) ';
			ELSE
				SET @JobTypeList = '3';
			END IF;

			#SELECT CONCAT("JobTypeList=", @JobTypeList);
			
			SET @isReport = -1;
			IF (@ReportStatus = '[NOT SPECIFIED]') THEN
			    SET @isReport = -1;
			ELSEIF (@ReportStatus = 'INCLUDED') THEN
			    SET @isReport = 1;
			ELSEIF (@ReportStatus = 'EXCLUDED') THEN
			    SET @isReport = 0;
			END IF;
			
			SET @reportClause = '';
			
			IF (@isReport = 1) THEN
			    SET @reportClause = ' AND (a.isReport = 1)';
			ELSEIF (@isReport = 0) THEN
			    SET @reportClause = ' AND (a.isReport = 0 OR a.isReport IS NULL)';
			END IF;
			
			# +++++++++++++++++++++++++++++++++++++++++++++++++++++++++
			# Create repository table			
			# +++++++++++++++++++++++++++++++++++++++++++++++++++++++++
			DROP TABLE IF EXISTS tmplatestservice;

			CREATE TABLE tmplatestservice
			(
			    IRIDNo                  INT, 
			    IRNo                    VARCHAR(50),
			    ServiceNo               INT,
			    ClientID                INT,
			    MerchantID              INT,
			    JobType                 INT,
			    JobTypeDescription      VARCHAR(30),
			    ServiceDate             DATE,
			    ReqInstallationDate     DATE,
			    ServiceStatus           INT,
			    JobTypeStatusDescription VARCHAR(50),

			    ActionMade              VARCHAR(30),
			    ReasonID                INT,
			    Reason                  TEXT,
			    FSRDate                 DATE,

			    RegionType              VARCHAR(100),
			    RegionID                INT,
			    ZoneID                  INT,
			    
			    RequestDate             DATE,
			    ScheduleDate            DATE,
			    CompletionDate          DATE,
			    
			    RequestType             VARCHAR(30),
			    ServiceResult	    VARCHAR(30),
			    TATStatus	            VARCHAR(30),
			    DaysOverDue	            VARCHAR(30),
			    NetworkDays	            VARCHAR(30),
			    SLA		            VARCHAR(30),
			    
			    DispatchID              INT,  
			    Dispatcher 		    VARCHAR(50),
			    
			    TServiceNos		    INT,
			    ServiceNos		    TEXT,
			    TIRNos		    INT,
			    IRNos		    TEXT,
			    
			    TOverallIR		    INT,	
			    OverallIRNos	    TEXT,
			    OverallServiceNos	    TEXT,	
			    
			    LatestIRCount	    INT,
			    LatestIRNos		    TEXT,
			    LatestServiceNos	    TEXT,			
			    
			    isIncludedOverallRequest  TINYINT(1)	
			    
			);
			# +++++++++++++++++++++++++++++++++++++++++++++++++++++++++
			# Create repository table			
			# +++++++++++++++++++++++++++++++++++++++++++++++++++++++++
			
			SET @select = 'SELECT ';
			
			#SELECT @baseQuery; -- Debugging: Print the generated query
			
			SET @newTemplateRequestFields = '';
			SET @newTemplateMerchantFields = '';
			SET @newTemplatePOSFields = '';
			SET @newTemplateLastFields = '';

			# ============================================================
			# INSTALLATION / REPROGRAMMING
			# ============================================================

			IF @JobTypeList = '1' THEN

				SET @newTemplateRequestFields = ',

					CASE
					    WHEN d.JobType = 3 OR (d.JobType = 7 AND a.ReasonID IN (60))
					    THEN "REPROGRAMMING"
					    WHEN funcGetDesc("Search", "Type", b.RequestTypeID) = "-"
					    THEN "UNKNOWN"
					    ELSE funcGetDesc("Search", "Type", b.RequestTypeID)
					END AS Request_Type_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."Request Prioritization"'')
					) AS Request_Prioritization_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."POS Setup"'')
					) AS POS_Setup_SUB_CATEGORY_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."POS Type"'')
					) AS POS_Type_SUB_CATEGORY_2_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."POS Connection Type"'')
					) AS POS_Connection_Type_,

					IFNULL_FORMAT_DATE(COALESCE(MAX(d.ServiceReqDate),"0000-00-00")) AS Target_Installation_date_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(
							b.rawdata_info,
							''$.Values."Pullout date  (applicable only to exhibit POS Request type)"''
						)
					) AS Pullout_date_applicable_only_to_exhibit_POS_Request_type_
				';


				SET @newTemplateMerchantFields = ',

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."Address"'')
					) AS Address_,

					/*
					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."City"'')
					) AS City_,
					*/
					
					funcGetDesc("Search", "Region Detail", c.RegionID) AS City_,

					funcGetDesc(
						"Search","Region",c.RegionType
					) AS Area_1_Metro_Manila_Provincial_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(
							b.rawdata_info,
							''$.Values."Area 2 (Region/Zone/Area code)"''
						)
					) AS Area_2_RegionZoneArea_code_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."Merchant Group"'')
					) AS Merchant_Group_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."Contact Person"'')
					) AS Contact_Person_,

					IFNULL_STRING_ONLY2(
						fnJsonExtract(b.rawdata_info,''$.Values."Contact Number"'')
					) AS Contact_Number_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Bancnet TID"'')) AS Bancnet_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Bancnet MID"'')) AS Bancnet_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Alipay TID"'')) AS Alipay_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Alipay MID"'')) AS Alipay_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Wechat TID"'')) AS Wechat_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Wechat MID"'')) AS Wechat_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Gcash (TID)"'')) AS QRGcash_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Gcash (mid)"'')) AS QRGcash_mid_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (TID)"'')) AS QRGrab_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (MID)"'')) AS QRGrab_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (TID)"'')) AS QRUPI_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (MID)"'')) AS QRUPI_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (TID)"'')) AS QRP2M_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (MID)"'')) AS QRP2M_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - Name"'')) AS Multimerchant_1_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - TID"'')) AS Multimerchant_1_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 1 - MID"'')) AS Multimerchant_1_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - Name"'')) AS Multimerchant_2_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - TID"'')) AS Multimerchant_2_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - MID"'')) AS Multimerchant_2_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - Name"'')) AS Multimerchant_3_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - TID"'')) AS Multimerchant_3_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - MID"'')) AS Multimerchant_3_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - Name"'')) AS Multimerchant_4_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - TID"'')) AS Multimerchant_4_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - MID"'')) AS Multimerchant_4_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - Name"'')) AS Multimerchant_5_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - TID"'')) AS Multimerchant_5_TID_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - MID"'')) AS Multimerchant_5_MID_,

					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."DCC (Yes/No)"'')) AS DCC_YesNo_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Installment (Yes/No)"'')) AS Installment_YesNo_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Manual Key Entry (MKE) (Yes/No)"'')) AS Manual_Key_Entry_MKE_YesNo_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Preauth (Yes/No)"'')) AS Preauth_YesNo_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Offline Sale (Yes/No)"'')) AS Offline_Sale_YesNo_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Offline Sale Limit (To be specified)"'')) AS Offline_Sale_Limit_To_be_specified_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Tip Adjust (Yes/No)"'')) AS Tip_Adjust_YesNo_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Tip Adjust Limit (To be specified)"'')) AS Tip_Adjust_Limit_To_be_specified_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."Add-on Device  (To be specified)"'')) AS AddOn_Device_To_be_specified_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."ECR Integration (Yes/No)"'')) AS ECR_Integration_YesNo_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.profile_info,''$."ECR Cable Type"'')) AS ECR_Cable_Type_
				';


				SET @newTemplatePOSFields = ',
					IFNULL_STRING_ONLY2(a.TerminalSN) AS POS_Serial_Number_
				';


			# ============================================================
			# MAINTENANCE / PULL-OUT
			# ============================================================

			ELSE

				SET @newTemplateRequestFields = ',

					funcGetDesc("Search", "Service JobType Description", d.JobType) AS Request_Type_,

					"-" AS Request_Prioritization_,
					"-" AS POS_Setup_SUB_CATEGORY_,
					"-" AS POS_Type_SUB_CATEGORY_2_,
					"-" AS POS_Connection_Type_,

					IFNULL_FORMAT_DATE(
						d.ServiceReqDate
					) AS Target_Installation_date_,

					"-" AS Pullout_date_applicable_only_to_exhibit_POS_Request_type_
				';


				SET @newTemplateMerchantFields = ',

					IFNULL_STRING_ONLY2(c.Address) AS Address_,

					funcGetDesc(
						"Search","Region Detail",c.RegionID
					) AS City_,

					funcGetDesc(
						"Search","Region",c.RegionType
					) AS Area_1_Metro_Manila_Provincial_,

					funcGetDesc(
						"Search","AreaCode",d.DispatchID
					) AS Area_2_RegionZoneArea_code_,

					"-" AS Merchant_Group_,

					IFNULL_STRING_ONLY2(c.ContactPerson) AS Contact_Person_,
					IFNULL_STRING_ONLY2(c.ContactNumber) AS Contact_Number_,

					"-" AS Bancnet_TID_,
					"-" AS Bancnet_MID_,
					"-" AS Alipay_TID_,
					"-" AS Alipay_MID_,
					"-" AS Wechat_TID_,
					"-" AS Wechat_MID_,
					"-" AS QRGcash_TID_,
					"-" AS QRGcash_mid_,
					"-" AS QRGrab_TID_,
					"-" AS QRGrab_MID_,
					"-" AS QRUPI_TID_,
					"-" AS QRUPI_MID_,
					"-" AS QRP2M_TID_,
					"-" AS QRP2M_MID_,

					"-" AS Multimerchant_1_Name_,
					"-" AS Multimerchant_1_TID_,
					"-" AS Multimerchant_1_MID_,
					"-" AS Multimerchant_2_Name_,
					"-" AS Multimerchant_2_TID_,
					"-" AS Multimerchant_2_MID_,
					"-" AS Multimerchant_3_Name_,
					"-" AS Multimerchant_3_TID_,
					"-" AS Multimerchant_3_MID_,
					"-" AS Multimerchant_4_Name_,
					"-" AS Multimerchant_4_TID_,
					"-" AS Multimerchant_4_MID_,
					"-" AS Multimerchant_5_Name_,
					"-" AS Multimerchant_5_TID_,
					"-" AS Multimerchant_5_MID_,

					"-" AS DCC_YesNo_,
					"-" AS Installment_YesNo_,
					"-" AS Manual_Key_Entry_MKE_YesNo_,
					"-" AS Preauth_YesNo_,
					"-" AS Offline_Sale_YesNo_,
					"-" AS Offline_Sale_Limit_To_be_specified_,
					"-" AS Tip_Adjust_YesNo_,
					"-" AS Tip_Adjust_Limit_To_be_specified_,
					"-" AS Addon_Device_To_be_specified_,
					"-" AS ECR_Integration_YesNo_,
					"-" AS ECR_Cable_Type_
				';


				SET @newTemplatePOSFields = ',

					IFNULL_STRING_ONLY2(
						CASE
							WHEN a.JobType = 7 THEN b.TerminalSN
							ELSE a.TerminalSN
						END
					) AS POS_Serial_Number_
				';

				/*
				SET @newTemplateLastFields = ',
					IFNULL_STRING_ONLY2(
						funcGetDesc("Search","Type",d.CategoryID)
					) AS Issue_Category_
				';
				*/

			END IF;
			
			SET @newTemplateFields = CONCAT('

					/*	
					"X---Dev-Check---X" AS Dev_Check_Start_Here_,
					IFNULL_STRING_ONLY(funcGetDesc("Search", "Service JobType Description", d.JobType)) AS pDevServiceType_,
					IFNULL_NUMERIC(d.JobType) AS pDevJobType_,					
					IFNULL_NUMERIC(d.ServiceNo) AS pDevServiceNo_,					
					IFNULL_NUMERIC(a.FSRNo) AS pDevFSRNo_,
					IFNULL_NUMERIC(c.ZoneID) AS pDevZoneID_,
					IFNULL_NUMERIC(a.ReasonID) AS pDevReasonID_,
					IFNULL_STRING_ONLY(funcGetDesc("Search","Reason",a.ReasonID)) AS pDevReason,
					IFNULL_NUMERIC(d.TicketStatus) AS pDevTicketStatus_,
					IFNULL_NUMERIC(d.MerchantID) AS pDevMerchantID_,
					IFNULL_NUMERIC(d.IRIDNo) AS pDevIRIDNo_,
					IFNULL_NUMERIC(d.DispatchID) AS pDevDispatchID_,
					IFNULL_NUMERIC(d.FEID) AS pDevFEID_,
					
					(
					    SELECT COUNT(*)
					    FROM tblservicingdetail s
					    WHERE s.IRNo = d.IRNo
					      AND s.isActive > 0
					) AS pDevServiceCount_,
					
					(
					    SELECT GROUP_CONCAT(
						s.ServiceNo
						ORDER BY s.ServiceNo
						SEPARATOR " | "
					    )
					    FROM tblservicingdetail s
					    WHERE s.IRNo = d.IRNo
					      AND s.isActive > 0
					) AS pDevServiceNos_,
					
					(
					    SELECT GROUP_CONCAT(
						CONCAT(
						    s.ServiceNo,
						    ":",
						    s.IRIDNo,
						    ":",
						    s.IRNo
						)
						ORDER BY s.ServiceNo
						SEPARATOR " | "
					    )
					    FROM tblservicingdetail s
					    WHERE s.IRNo = d.IRNo
					      AND s.isActive > 0
					) AS pDevServiceHistory_,

					(
					    SELECT GROUP_CONCAT(
						CONCAT(s.ServiceNo, ":", f.ActionMade)
						ORDER BY s.ServiceNo
						SEPARATOR " | "
					    )
					    FROM tblservicingdetail s
					    INNER JOIN tblfsrdetail f
						ON f.ServiceNo = s.ServiceNo
					    WHERE s.IRNo = d.IRNo
					) AS pDevActionHistory_,
					
					(
					    SELECT GROUP_CONCAT(
						CONCAT(
						    s.ServiceNo,
						    ":",
						    f.ActionMade,
						    "(",
						    funcGetDesc("Search","Reason",f.ReasonID),
						    ")"
						)
						ORDER BY s.ServiceNo
						SEPARATOR " | "
					    )
					    FROM tblservicingdetail s
					    INNER JOIN tblfsrdetail f
						ON f.ServiceNo = s.ServiceNo
					    WHERE s.IRNo = d.IRNo
					) AS pDevHistory_,
					*/
					
					#"X---New-Template---X" AS New_Template_Start_Here_,
					IFNULL_STRING_ONLY(funcGetTATStatus("Search","TAT Status",d.ServiceNo)) AS TAT_Status_,
					IFNULL_STRING_ONLY(funcGetDaysOverDue("Search","Days OverDue",d.ServiceNo)) AS Days_Overdue_,
					IFNULL_STRING_ONLY(funcGetNetworkDays("Search","Network Days",d.ServiceNo)) AS Network_Days_,
					IFNULL_STRING_ONLY(funcGetSLA("Search","SLA-Region",d.ServiceNo)) AS SLA_,

					IFNULL_STRING_ONLY2(d.IRNo) AS Request_ID_,
					IFNULL_STRING_ONLY2(d.Vendor) AS Vendor_,
					
					IFNULL_FORMAT_DATE2(COALESCE(d.ServiceDate, "0000-00-00")) AS Request_Date_,				   			
				        #IFNULL_FORMAT_DATE2(COALESCE(d.ServiceReqDate,"0000-00-00")) AS Schedule_Date_,
				        #IFNULL_FORMAT_DATE2(COALESCE(d.ReqInstallationDate,"0000-00-00")) AS Installation_Date_,
				        #IFNULL_FORMAT_DATE2(COALESCE(a.FSRDate,"0000-00-00")) AS Serviced_Date_,
				        #IFNULL_FORMAT_DATE2(COALESCE(d.ReportedDate,"0000-00-00")) AS Reported_Date_,
			    
					IFNULL_STRING_ONLY2(d.Requestor) AS Requestor_

					',

					@newTemplateRequestFields,

					',

					#IFNULL_STRING_ONLY2(d.RMInstruction) AS RM_Instruction_Remarks_,	
					funcGetDesc("Search", "Service Remarks", d.ServiceNo) AS RM_Instruction_Remarks_,				
					IFNULL_STRING_ONLY2(b.MID) AS Merchant_ID_MID_,
					IFNULL_STRING_ONLY2(b.TID) AS Terminal_ID_TID_,
					IFNULL_STRING_ONLY2(c.Name) AS Merchant_LocationDBA_Name_

					',

					@newTemplateMerchantFields,

					',
								
					IFNULL_STRING_ONLY2(z.CityMunicipal) AS CITY_PROVINCE_,
					IFNULL_STRING_ONLY2(z.Region) AS REGION_,
					IFNULL_STRING_ONLY2(z.Area) AS AREA_,
					IFNULL_STRING_ONLY2(z.ZoneName) AS ZONE_,

					funcGetDesc(
						"Search",
						"Daily Service Status",
						CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.JobTypeStatusDescription)
					) AS Status_,

					IFNULL_FORMAT_DATE(MAX(a.FSRDate)) AS INSTALLATION_DATE_,
					funcGetGeneralActionTaken(a.JobType,a.IRIDNo,a.IRNo) AS INSTALLATION_REMARKS_,

					IFNULL_STRING_ONLY2(
						funcGetDesc("Search","Reason",MAX(a.ReasonID))
					) AS STATUS_REASON_,

					IFNULL_STRING_ONLY2(
						funcGetDesc("Search","Reason",MAX(a.ReasonID))
					) AS LATEST_ATTEMPT_REASON_,

					funcGetDesc("Search","Type",a.DependencyID) AS DEPENDENCY_,
					IFNULL_FORMAT_DATE(d.ReportedDate) AS Date_Reported_to_Bank_

					',

					@newTemplatePOSFields,

					',

					IFNULL_STRING_ONLY2(
						funcGetDesc("Search","TerminalID Model",a.TerminalID)
					) AS POS_Model_,

					IFNULL_STRING_ONLY2(b.AppVersion) AS POS_Version_,
					IFNULL_STRING_ONLY2(b.AppCRC) AS POS_CRC_,

					IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentative))
						AS Merchant_Representative_Recipient_,

					IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentativePosition))
						AS Position_of_Representative_Recipient_Designation_,

					IFNULL_STRING_ONLY2(MAX(a.MerchantContactNo))
						AS Merchant_Representative_Contact_Number_,

					IFNULL_STRING_ONLY2(
						funcGetDesc("Search","Particular",MAX(d.FEID))
					) AS Vendor_Representative_CSE_,

					funcGetDesc(
						"Search","SIMID Carrier",MAX(a.SIMID)
					) AS Telco_,

					/* ================= ATTEMPT 1 ================= */

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."Reason1"''
					) AS 1ST_ATTEMPT_REASON_,

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."FSRDate1"''
					) AS 1ST_ATTEMPT_DATE_,

					"-" AS 1ST_ATTEMPT_DEPENDENCY_,

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."isBillable1"''
					) AS 1ST_ATTEMPT_Zone_Fee_BillableNon_Billable_,

					/* ================= ATTEMPT 2 ================= */

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."Reason2"''
					) AS 2ND_ATTEMPT_REASON_,

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."FSRDate2"''
					) AS 2ND_ATTEMPT_DATE_,

					"-" AS 2ND_ATTEMPT_DEPENDENCY_Leave_blank_if_prev_dependency_is_Not_Applicable_,

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."isBillable2"''
					) AS 2ND_ATTEMPT_Zone_Fee_BillableNon_Billable_,

					/* ================= ATTEMPT 3 ================= */

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."Reason3"''
					) AS 3RD_ATTEMPT_REASON_,

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."FSRDate3"''
					) AS 3RD_ATTEMPT_DATE_,

					"-" AS 3RD_ATTEMPT_DEPENDENCY_Leave_blank_if_prev_dependencies_has_Not_Applicable_,

					fnJsonExtract(
						funcGetJSON(
							"Search","Service Attempt",
							CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
						),
						''$."isBillable3"''
					) AS 3RD_ATTEMPT_Zone_Fee_BillableNon_Billable_,

					/* ================= BEYOND 3 ================= */

					COALESCE(
						fnJsonExtract(
							funcGetJSON(
								"Search","Service Attempt",
								CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
							),
							''$."Reason5"''
						),
						fnJsonExtract(
							funcGetJSON(
								"Search","Service Attempt",
								CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
							),
							''$."Reason4"''
						)
					) AS BEYOND_3_ATTEMPTS_REASON_,

					COALESCE(
						fnJsonExtract(
							funcGetJSON(
								"Search","Service Attempt",
								CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
							),
							''$."FSRDate5"''
						),
						fnJsonExtract(
							funcGetJSON(
								"Search","Service Attempt",
								CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
							),
							''$."FSRDate4"''
						)
					) AS BEYOND_3_ATTEMPTS_LATEST_DATE_,

					"-" AS BEYOND_3_ATTEMPT_LATEST_DEPENDENCY_Leave_blank_if_prev_dependencies_has_Not_Applicable_,

					COALESCE(
						fnJsonExtract(
							funcGetJSON(
								"Search","Service Attempt",
								CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
							),
							''$."isBillable5"''
						),
						fnJsonExtract(
							funcGetJSON(
								"Search","Service Attempt",
								CONCAT(a.JobType,"|",a.IRIDNo,"|",a.IRNo)
							),
							''$."isBillable4"''
						)
					) AS BEYOND_3_ATTEMPTS_Zone_Fee_BillableNon_Billable_,

					"-" AS Addtl_Billable_Attempts_If_Beyond_3_Attempts_Manual_Entry_,

					/* ================= COURIER ================= */

					"-" AS COURIER_TRACKING_NUMBER_,
					"-" AS DATE_SHIPPED_,
					"-" AS DATE_ARRIVED_,
					"-" AS Total_Days_Handled_by_Courier_,

					IFNULL_STRING_ONLY2(
						COALESCE(
							DATE_FORMAT(d.ReqInstallationDate,"%M"),
							"0000-00-00"
						)
					) AS Month_,

					funcGetDesc(
						"Search",
						"Service Ticket Status",
						CONCAT(
							d.TicketStatus,
							"|",
							d.ServiceStatus,
							"|",
							IFNULL(a.ActionMade, "")
						)
					) AS Ticket_Status_,
					
					IFNULL_FORMAT_DATE(d.TicketDateTime) AS Date_Closed_,

					funcGetDesc(
						"Search","Particular",d.DispatchID
					) AS Dispatchers_Name_,
					
					IFNULL_STRING_ONLY2(
						funcGetDesc("Search","Type",a.IssueCategoryID)
					) AS Issue_Category_

					',

					@newTemplateLastFields

				);
				
				#SELECT @extraFields; -- Debugging: Print the generated query
				
				SET @fromClause = '
				    FROM tblservicingdetail d

				    INNER JOIN (
					SELECT
					    IRNo,
					    MAX(ServiceNo) AS ServiceNo
					FROM tblservicingdetail
					WHERE isActive > 0
					GROUP BY IRNo
				    ) latest
					ON latest.IRNo = d.IRNo
				       AND latest.ServiceNo = d.ServiceNo

				    LEFT JOIN tblfsrdetail a
					ON a.ServiceNo = d.ServiceNo

				    LEFT JOIN tblirdetail b
					ON d.IRIDNo = b.IRIDNo

				    LEFT JOIN tblparticular c
					ON d.MerchantID = c.ParticularID

				    LEFT JOIN tblzoning z
					ON z.ZoneID = c.ZoneID
					
				     LEFT JOIN tblregion r
					ON r.RegionID = c.RegionType	
				';
				
				SET @whereBaseClause = '';
				SET @whereBaseClause = CONCAT('
				    WHERE
					d.ClientID = ?
					AND d.isActive > 0
					AND (
					    FIND_IN_SET(d.JobType, ?)
					    OR (', @JobTypeList, ' <> 3 AND a.ReasonID = 60)
					)
					AND (
					    (
						', IF(@ReportType = 1, 'a.FSRDate', 'd.ServiceDate'), ' BETWEEN ? AND ?
					    )
					    OR (? = ''0000-00-00'' AND ? = ''0000-00-00'')
					)
					', @reasonCondition, '
					AND (
					    a.ServiceNo IS NULL
					    OR
					    funcGetDesc(
						"Search",
						"Daily Service Status",
						CONCAT(
						    d.ServiceStatus,
						    "|",
						    a.ActionMade,
						    "|",
						    d.ServiceNo
						)
					    ) IN (
						"CANCELLED",
						"HOLD",
						"PENDING",
						"NEGATIVE",
						"RESOLVED"
					    )
					)
				');

				-- Append Report Filter
				SET @whereBaseClause = CONCAT(@whereBaseClause, @reportClause);
				
				#SELECT CONCAT("@whereBaseClause=",@whereBaseClause); -- Debugging: Print the generated query
				
				SET @whereClause = '';  
				SET @whereClause = CONCAT(@whereBaseClause);
				
				#SELECT CONCAT("@whereMaxClause=",@whereMaxClause); -- Debugging: Print the generated query
				
				SET @orderClause = '';
				SET @orderClause = '
				ORDER BY d.ServiceDate, d.IRNo';
				
				SET @groupClause = '';				
				SET @groupClause = '
				GROUP BY d.IRNo';				
				
				#SELECT @fromClause; -- Debugging: Print the generated query
				
				#SET @finalQuery = CONCAT(@baseQuery, @extraFields, @addFields, @fromClause, @whereClause);
				SET @finalQuery = CONCAT(
					@select,
					#@baseQuery,
					@newTemplateFields,
					@fromClause,
					@whereClause
				);
				
				SET @whereUnionClause = '';
				SET @whereUnionClause = CONCAT('
				    WHERE
					d.ClientID = ?
					AND FIND_IN_SET(d.JobType, ?)
					AND (
					    (', IF(@ReportType = 1, 'a.FSRDate', 'd.ServiceDate'), ' BETWEEN ? AND ?)
					    OR (? = ''0000-00-00'' AND ? = ''0000-00-00'')
					)
					AND (d.isActive > 0)
					AND (d.JobTypeStatusDescription IN (''PENDING'', ''PROCESSING''))
				');
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				
				IF (v_ExcludePending > 0) THEN
					SET @finalQuery = @finalQuery;
				ELSE
					/*
					SET @finalQuery = CONCAT(@finalQuery, '
							UNION ALL 
							',
				                        @baseQuery, @extraFields, @addFields, @fromClause, @whereUnionClause);
				        */
				        SET @finalQuery = CONCAT(
						@select,
						#@baseQuery,
						@newTemplateFields,
						@fromClause,
						@whereClause,

						' UNION ALL ',

						@select,
						#@baseQuery,
						@newTemplateFields,
						@fromClause,
						@whereUnionClause
					);
				END IF;
				
				SET @finalQuery = CONCAT(@finalQuery, ' ', @groupClause, ' ', @orderClause, ';');
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				#SELECT CONCAT("@finalQuery=",@finalQuery); -- Debugging: Print the generated query
				
				SET @ClientID = v_ClientID;
				SET @JobTypeList = v_JobTypeList;
				SET @IRIDNo = v_IRIDNo;
				SET @IRNo = v_IRNo;
				SET @DateFrom = v_DateFrom;
				SET @DateTo = v_DateTo;
				SET @ReasonID = v_ReasonID;

				PREPARE stmt FROM @finalQuery;
				
				# debugging
				/*
				SELECT
				    "Report Debugging",
				    @ClientID    AS ClientID,
				    @JobTypeList AS JobTypeList,
				    @DateFrom    AS DateFrom,
				    @DateTo      AS DateTo,
				    @fromClause    AS fromClause,
				    @whereClause    AS whereClause,
				    @groupClause    AS groupClause,
				    @orderClause    AS orderClause;

				SELECT CONCAT("Report:@finalQuery=", @finalQuery);
				*/
				# debugging
				
				EXECUTE stmt USING @ClientID, @JobTypeList, @DateFrom, @DateTo, @DateFrom, @DateTo;

				DEALLOCATE PREPARE stmt;
				
				# ++++++++++++++++++++++++++++++++++++++++++++++++++++
				# Insert on repository table
				# ++++++++++++++++++++++++++++++++++++++++++++++++++++
				SET @finalQuery = CONCAT(
				'
				INSERT INTO tmplatestservice
				(
				    IRIDNo, 
				    IRNo,
				    ServiceNo,
				    ClientID,
				    MerchantID,
				    JobType,
				    JobTypeDescription,
				    ServiceDate,
				    ReqInstallationDate,
				    ServiceStatus,
				    JobTypeStatusDescription,
				    ActionMade,
				    ReasonID,
				    Reason,
				    FSRDate,
				    RegionType,
				    RegionID,
				    ZoneID,
				    RequestDate,
				    ScheduleDate,
				    CompletionDate,
				    RequestType,
				    ServiceResult,
				    TATStatus,
				    DaysOverDue,
				    NetworkDays,
				    SLA,
				    DispatchID,
				    Dispatcher,
				    TServiceNos,	
				    ServiceNos,	    
				    TIRNos,
				    IRNos,
				    TOverallIR,
				    OverallIRNos,
				    OverallServiceNos,
				    LatestIRCount,
				    LatestIRNos,
				    LatestServiceNos,
				    isIncludedOverallRequest
				)

				SELECT
				    
				    d.IRIDNo,	
				    d.IRNo,
				    d.ServiceNo,
				    d.ClientID,
				    d.MerchantID,
				    d.JobType,
				    funcGetDesc("Search", "Service JobType Description", d.JobType),
				    d.ServiceDate,
				    d.ReqInstallationDate,
				    d.ServiceStatus,
				    d.JobTypeStatusDescription,

				    a.ActionMade,
				    a.ReasonID,
				    funcGetDesc("Search", "Reason", MAX(a.ReasonID)),
				    a.FSRDate,

				    r.Region,
				    c.RegionID,
				    c.ZoneID,
				    
				    d.ServiceDate,
				    d.ReqInstallationDate,
				    a.FSRDate,
				    
				    CASE
					    WHEN d.JobType = 3
						 OR (d.JobType = 7 AND a.ReasonID IN (60))
					    THEN "REPROGRAMMING"
					    WHEN funcGetDesc("Search", "Type", b.RequestTypeID) = "-"
					    THEN "UNKNOWN"
					    ELSE funcGetDesc("Search", "Type", b.RequestTypeID)
				    END AS RequestType,
					
				    #funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.ServiceNo)),
				    
				    funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.JobTypeStatusDescription)) AS ServiceResult,
				    
				    funcGetTATStatus("Search","TAT Status",d.ServiceNo),
				    funcGetDaysOverDue("Search","Days OverDue",d.ServiceNo),
				    funcGetNetworkDays("Search","Network Days",d.ServiceNo),
				    funcGetSLA("Search","SLA-Region",d.ServiceNo),
				    
				    d.DispatchID,
				    funcGetDesc("Search", "Particular", d.DispatchID),
				    
				    (
					    SELECT COUNT(*)
					    FROM tblservicingdetail s
					    WHERE s.ServiceNo = a.ServiceNo
					      AND s.isActive > 0
				     ),
				     
				     (
					    SELECT GROUP_CONCAT(
						s.ServiceNo
						ORDER BY s.ServiceNo
						SEPARATOR " | "
					    )
					    FROM tblservicingdetail s
					    WHERE s.IRNo = d.IRNo
					      AND s.isActive > 0
				      ),
				     
				     (
					    SELECT COUNT(*)
					    FROM tblservicingdetail s
					    WHERE s.IRNo = d.IRNo
					      AND s.isActive > 0
				     ),
				     
				     (
					    SELECT GROUP_CONCAT(
						s.IRNo
						ORDER BY s.IRNo
						SEPARATOR " | "
					    )
					    FROM tblservicingdetail s
					    WHERE s.IRNo = d.IRNo
					      AND s.isActive > 0
				      ),
				      
				      (
					    SELECT COUNT(DISTINCT s.IRNo)
					    FROM tblservicingdetail s
					    WHERE s.MerchantID = d.MerchantID
					      AND DATE(s.ServiceDate) = DATE(d.ServiceDate)
					      AND s.isActive > 0
					) AS TOverallIR,
					
					(
					    SELECT GROUP_CONCAT(DISTINCT s.IRNo
						ORDER BY s.IRNo
						SEPARATOR " | ")
					    FROM tblservicingdetail s
					    WHERE s.MerchantID = d.MerchantID
					      AND DATE(s.ServiceDate) = DATE(d.ServiceDate)
					      AND s.isActive > 0
					) AS OverallIRNos,
					
					(
					    SELECT GROUP_CONCAT(DISTINCT s.ServiceNo
						ORDER BY s.ServiceNo
						SEPARATOR " | ")
					    FROM tblservicingdetail s
					    WHERE s.MerchantID = d.MerchantID
					      AND DATE(s.ServiceDate) = DATE(d.ServiceDate)
					      AND s.isActive > 0
					) AS OverallServiceNos,
					
					(
					    SELECT COUNT(*)
					    FROM (
						SELECT s.IRNo
						FROM tblservicingdetail s
						WHERE s.MerchantID = d.MerchantID
						  AND DATE(s.ServiceDate) = DATE(d.ServiceDate)
						  AND s.isActive > 0						  
						  AND s.ServiceNo = (
							SELECT MAX(s2.ServiceNo)
							FROM tblservicingdetail s2
							WHERE s2.IRNo = s.IRNo
							  AND s2.isActive > 0
						  )
						GROUP BY s.IRNo
					    ) x
					) AS TLatestIR,
					
					(
					    SELECT GROUP_CONCAT(x.IRNo ORDER BY x.IRNo SEPARATOR " | ")
					    FROM (
						SELECT s.IRNo
						FROM tblservicingdetail s
						WHERE s.MerchantID = d.MerchantID
						  AND DATE(s.ServiceDate) = DATE(d.ServiceDate)
						  AND s.isActive > 0						  
						  AND s.ServiceNo = (
							SELECT MAX(s2.ServiceNo)
							FROM tblservicingdetail s2
							WHERE s2.IRNo = s.IRNo
							  AND s2.isActive > 0
						  )
						GROUP BY s.IRNo
					    ) x
					) AS LatestIRNos,
					
					(
					    SELECT GROUP_CONCAT(x.ServiceNo ORDER BY x.ServiceNo SEPARATOR " | ")
					    FROM (
						SELECT s.IRNo, s.ServiceNo
						FROM tblservicingdetail s
						WHERE s.MerchantID = d.MerchantID
						  AND DATE(s.ServiceDate) = DATE(d.ServiceDate)
						  AND s.isActive > 0						  
						  AND s.ServiceNo = (
							SELECT MAX(s2.ServiceNo)
							FROM tblservicingdetail s2
							WHERE s2.IRNo = s.IRNo
							  AND s2.isActive > 0
						  )
					    ) x
					) AS LatestServiceNos,
				      
				      CASE

					    /* ==========================
					       ADDITIONAL POS
					       ========================== */

					    -- Exclude first-time negative
					    WHEN funcGetDesc("Search", "Type", b.RequestTypeID) = "ADDITIONAL POS"
					     AND funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.ServiceNo)) = "NEGATIVE"
					     AND (
						    SELECT COUNT(*)
						    FROM tblservicingdetail s
						    WHERE s.IRNo = d.IRNo
						      AND s.isActive > 0
						 ) = 1
					    THEN 0

					    -- Exclude repeat successful reprogramming
					    WHEN funcGetDesc("Search", "Type", b.RequestTypeID) = "ADDITIONAL POS"
					     AND d.JobType = 3
					     AND funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.ServiceNo)) = "RESOLVED"
					     AND (
						    SELECT COUNT(*)
						    FROM tblservicingdetail s
						    WHERE s.IRNo = d.IRNo
						      AND s.isActive > 0
						 ) > 1
					    THEN 0


					    /* ==========================
					       NEW INSTALLATION
					       ========================== */

					    -- Exclude repeat successful servicing
					    WHEN funcGetDesc("Search", "Type", b.RequestTypeID) = "NEW INSTALLATION"
					     AND funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.ServiceNo)) = "RESOLVED"
					     AND (
						    SELECT COUNT(*)
						    FROM tblservicingdetail s
						    WHERE s.IRNo = d.IRNo
						      AND s.isActive > 0
						 ) > 1
					    THEN 0


					    /* ==========================
					       POS SWAPPING
					       ========================== */

					    -- Exclude repeat successful servicing
					    WHEN funcGetDesc("Search", "Type", b.RequestTypeID) = "POS SWAPPING"
					     AND funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.ServiceNo)) = "RESOLVED"
					     AND (
						    SELECT COUNT(*)
						    FROM tblservicingdetail s
						    WHERE s.IRNo = d.IRNo
						      AND s.isActive > 0
						 ) > 1
					    THEN 0


					    /* ==========================
					       REPROGRAMMING
					       ========================== */

					    -- Exclude first-time negative
					    WHEN d.JobType = 3
					     AND funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.ServiceNo)) = "NEGATIVE"
					     AND (
						    SELECT COUNT(*)
						    FROM tblservicingdetail s
						    WHERE s.IRNo = d.IRNo
						      AND s.isActive > 0
						 ) = 1
					    THEN 0

					    -- Exclude repeat successful reprogramming
					    WHEN d.JobType = 3
					     AND funcGetDesc("Search","Daily Service Status",CONCAT(d.ServiceStatus,"|",a.ActionMade,"|",d.ServiceNo)) = "RESOLVED"
					     AND (
						    SELECT COUNT(*)
						    FROM tblservicingdetail s
						    WHERE s.IRNo = d.IRNo
						      AND s.isActive > 0
						 ) > 1
					    THEN 0

					    ELSE 1

					END			      				    
				',
				@fromClause,
				@whereClause,
				@groupClause
				);
				
				#SELECT CONCAT("TempTable:@finalQuery=",@finalQuery); -- Debugging: Print the generated query
				
				# debugging	
				/*		
				SELECT
				    "TempTable Debugging",
				    @ClientID    AS ClientID,
				    @JobTypeList AS JobTypeList,
				    @DateFrom    AS DateFrom,
				    @DateTo      AS DateTo,
				    @fromClause    AS fromClause,
				    @whereClause    AS whereClause,
				    @groupClause    AS groupClause,
				    @orderClause    AS orderClause;

				SELECT CONCAT("TempTable:@finalQuery=", @finalQuery);
				*/
				# debugging
				
				PREPARE stmt FROM @finalQuery;

				EXECUTE stmt USING
				    @ClientID,
				    @JobTypeList,
				    @DateFrom,
				    @DateTo,
				    @DateFrom,
				    @DateTo;

				DEALLOCATE PREPARE stmt;
				# ++++++++++++++++++++++++++++++++++++++++++++++++++++
				# Insert on repository table
				# ++++++++++++++++++++++++++++++++++++++++++++++++++++	
		
		# New template(Active POS)		
		ELSEIF (p_SearchBy = 'Active Detail Terminal')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_StatusID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
			SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
			
			
			
			SET p_WHERE = '';
			SET p_SQL = '';
			
			SET p_SQL = CONCAT(
				    p_SQL,
				    'SELECT ',
					'IFNULL_NUMERIC(vw.Type_ID) AS TerminalTypeID, ',
					'IFNULL_NUMERIC(vw.Model_ID) AS TerminalModelID, ',
					'IFNULL_NUMERIC(vw.Terminal_ID) AS TerminalID, ',
					'funcGetDesc("Search", "Terminal Detail", ir.TerminalID) AS TerminalSN, ',
					'funcGetDesc("Search", "TerminalID Type", ir.TerminalID) AS TerminalType, ',
					'funcGetDesc("Search", "TerminalID Model", ir.TerminalID) AS TerminalModel, ',
					'funcGetDesc("Search", "SIM Detail", ir.SIMID) AS SIMSN, ',
					'funcGetDesc("Search", "SIMID Carrier", ir.SIMID) AS SIMCarrier, ',
					'IFNULL_NUMERIC(ir.MerchantID) AS MerchantID, ',
					'IFNULL_STRING_ONLY2(ir.IRNo) AS Request_No_, ',
					'IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", ir.MerchantID)) AS MerchantName, ',
					'IFNULL_STRING_ONLY2(ir.TID) AS TID, ',
					'IFNULL_STRING_ONLY2(ir.MID) AS MID, ',
					'IFNULL_NUMERIC(pr.RegionType) AS RegionType, ',
					'IFNULL_STRING_ONLY2(funcGetDesc("Search", "Region", pr.RegionType)) AS Region, ',
					'IFNULL_NUMERIC(pr.RegionID) AS RegionID, ',
					'IFNULL_STRING_ONLY2(funcGetDesc("Search", "Region Detail", pr.RegionID)) AS Province, ',
					'IFNULL_STRING_ONLY2(pr.Address) AS Address, ',
					'IFNULL_STRING_ONLY2(pr.ContactPerson) AS ContactPerson, ',
					'IFNULL_STRING_ONLY2(pr.ContactPosition) AS ContactPosition, ',
					'IFNULL_STRING_ONLY2(pr.ContactNumber) AS ContactNumber, ',
					'IFNULL_STRING_ONLY2(funcGetDesc("Search", "Merchant 1st Installation Date", CONCAT(vw.Client_ID, "|", "1", "|", ir.IRIDNo))) AS ServiceDate, ',
					'IF(vw.Terminal_ID = ir.TerminalID, "MATCH", "NOT MATCH") AS isMatch, ',
					
		
					'"X-----------------------X" AS ExportInclusionStartHere_, ',								
					'IFNULL_STRING_ONLY2(ir.IRNo) AS Request_ID_,', 
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."Vendor"''))) AS Vendor_,',				
					'IFNULL_STRING_ONLY2(ir.IRDate) AS Request_Date_,', 
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."Requestor"''))) AS Requestor_,',
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."Request Type"''))) AS Request_Type_,',
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."Request Prioritization"''))) AS Request_Prioritization_,',
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."POS Setup"''))) AS POS_Setup_,',
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."POS Type"''))) AS POS_Type_,',
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."POS Connection Type"''))) AS POS_Connection_Type_,',
					'IFNULL_STRING_ONLY2(ir.InstallationDate) AS Target_Installation_Date_,', 					
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."Pullout date  (applicable only to exhibit POS Request type)"''))) AS PullOutDateApplicableToExhibitPOS_Req_Type_,',
					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(ir.rawdata_info,''$.Values."RM Instruction / Remarks"''))) AS RM_Instruction_Remarks_,',

					'IFNULL_STRING_ONLY2(ir.MID) AS Merchant_M_I_D_,',
					'IFNULL_STRING_ONLY2(ir.TID) AS Terminal_T_I_D_,',									
					'IFNULL_STRING_ONLY2(pr.Name) AS Merchant_DBA_Name_, ',
					'IFNULL_STRING_ONLY2(pr.Address) AS Address_, ',					
					'IFNULL_STRING_ONLY2(funcGetDesc("Search", "Region Detail", pr.RegionID)) AS City_Province_Validated_ZipCode_Area_, ',
					
