					'IFNULL_STRING_ONLY2(JSON_UNQUOTE(JSON_EXTRACT(funcGetJSON("Search", "Profile Config Info", vw.Client_ID), ''$.Values."SettleTime"''))) AS Auto_Settlement_Time_,',
					
					'"-" AS NMX_, ',							
					'"Billable" AS POS_Leasing_, ',
