					'FROM ',
					'vw_terminal_info vw ',					
					'LEFT JOIN tblirdetail ir ON vw.Terminal_ID = ir.TerminalID', ' ',
					'LEFT JOIN tblparticular pr ON ir.MerchantID = pr.ParticularID', ' '
					);
			
			
			SET p_SQL = CONCAT(
				p_SQL,
				'WHERE', ' '
			    );
			
			
			SET p_SQL = CONCAT(
					p_SQL, ' ',
					'vw.isActive = 1', ' '
					);
			
			
			SET p_SQL = CONCAT(
					p_SQL,
					'AND ir.TerminalID IS NOT NULL', ' '
					);
								
			IF (v_ClientID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Client_ID = ', v_ClientID, ' '
					);
			END IF;
			
			IF (v_LocationID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Loc_ID = ', v_LocationID, ' '
					);
			END IF;
			
			IF (v_StatusID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Status_ID = ', v_StatusID, ' '
					);
			END IF;
			
			IF (v_TerminalTypeID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Type_ID = ', v_TerminalTypeID, ' '
					);
			END IF;
			
			IF (v_TerminalModelID > 0) THEN
				SET p_SQL = CONCAT(
					p_SQL,
					'AND vw.Model_ID = ', v_TerminalModelID, ' '
					);
			END IF;
			
			SET p_SQL = CONCAT(p_SQL, ';');
			
			
			
			
			SET @QUERY = p_SQL;
			
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'Service Attempt')
		THEN
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_JobTypeList = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
			SET v_IRIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_IRNo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));
			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));
			SET v_ExcludePending = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INTEGER);
			SET v_ReasonID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,8)) AS UNSIGNED INTEGER);
			SET @ReportStatus = TRIM(SPLIT_STRING(p_SearchValue, '|' ,9));
			
			#SET v_ExcludePending = 1;
			#SELECT CONCAT("v_JobTypeList=",v_JobTypeList);
			
			# 1,3 = INSTALLATION, REPROGRAMMING (Installation Report)
			# 6,7 = SERVICING, REPLACEMENT	    (Maintenance Report)
			# 4   = PULL-OUT		    (Pull-out Report)
			IF (FIND_IN_SET('1', v_JobTypeList) AND FIND_IN_SET('3', v_JobTypeList)) THEN
				SET @JobTypeList = '1';
			ELSEIF (FIND_IN_SET('6', v_JobTypeList) AND FIND_IN_SET('7', v_JobTypeList)) THEN
				SET @JobTypeList = '2';
			ELSE
				SET @JobTypeList = '3';
			END IF;

			#SELECT CONCAT("JobTypeList=", @JobTypeList);

			SET @isReport = -1;
			IF (@ReportStatus = '[NOT SPECIFIED]') THEN
			    SET @isReport = -1;
			ELSEIF (@ReportStatus = 'INCLUDED') THEN
			    SET @isReport = 1;
			ELSEIF (@ReportStatus = 'EXCLUDED') THEN
			    SET @isReport = 0;
			END IF;

			SET @reportClause = '';

			IF (@isReport = 1) THEN
			    SET @reportClause = ' AND (a.isReport = 1)';
			ELSEIF (@isReport = 0) THEN
			    SET @reportClause = ' AND (a.isReport = 0 OR a.isReport IS NULL)';
			END IF;
			
			SET @baseQuery = '
			SELECT 
			    d.JobType, 
			    #funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)) AS JobTypeDesc,
			    
			    #d.isReport AS svc_isReport,
			    #a.isReport AS fsr_isReport,
			    
			    #CASE 
				   # WHEN a.isReport = 1 THEN "INCLUDED"
				    #WHEN a.isReport = 0 THEN "EXCLUDED"
				   # ELSE "NOT YET SERVICED"
				#END AS ReportStatus,	
			    			    
			    d.MerchantID,			   
			    d.ServiceNo,			    
			    d.IRIDNo,					
			    (IF(a.FSRNo > 0, a.IRNo, d.IRNo)) AS IRNo,
			    b.MID, 
			    b.TID, 					
			    c.Name AS MerchantName,
			    c.Address,
			    c.RegionType,
			    funcGetDesc("Search", "Region", c.RegionType) AS Region,
