			    funcGetDesc("Search", "Region Detail", c.RegionID) AS Province,			    
			    IFNULL_STRING_ONLY2(a.FSRRefNo)  AS fsrRefNo,
			    IFNULL_STRING_ONLY2(d.ReferenceNo)  AS svcRefNo,
			    IFNULL_STRING_ONLY2(d.Requestor) AS Requestor,
			    IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Request Type"'')) AS RequestType,
			    IFNULL_FORMAT_DATE(COALESCE(d.ServiceDate, "0000-00-00")) AS RequestDate,					
			    IFNULL_FORMAT_DATE(COALESCE(d.ServiceReqDate,"0000-00-00")) AS ScheduleDate,
			    IFNULL_FORMAT_DATE(COALESCE(d.ReqInstallationDate,"0000-00-00")) AS InstallationDate,
			    IFNULL_FORMAT_DATE(COALESCE(d.ReportedDate,"0000-00-00")) AS ReportedDate,
			    IFNULL_STRING_ONLY2(z.CityMunicipal) AS City_Province_,
