			    IFNULL_STRING_ONLY2(z.Area) AS Zone_Area_,
			    IFNULL_STRING_ONLY2(z.ZoneName) AS Zone_Name_,

			    #IFNULL_FORMAT_DATE(COALESCE(a.FSRDate,"0000-00-00")) AS CompletionDate,
			    
			    IFNULL_STRING_ONLY(funcGetDaysOverDue("Search", "Days OverDue", d.ServiceNo)) AS DaysOverDue_,
			    IFNULL_STRING_ONLY(funcGetNetworkDays("Search", "Network Days", d.ServiceNo)) AS NetworkDays_,
			    IFNULL_STRING_ONLY(funcGetTATStatus("Search", "TAT Status", d.ServiceNo)) AS TATStatus_,
			    IFNULL_STRING_ONLY(funcGetSLA("Search", "SLA-Region", d.ServiceNo)) AS SLA_,
			    
			    funcGetDesc("Search", "Service Status", b.IRStatus) AS Service_Status,
		            #funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))) AS ServiceStatus_,

		            #a.ActionMade AS TicketStatus,
			    #funcGetDesc("Search", "Particular", d.DispatchID) AS DispatcherName,
			    
			    #funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))) AS ServiceStatus_,
			    
			    b.TerminalSN,
			    funcGetDesc("Search", "TerminalID Model", a.TerminalID) AS TerminalModel,	
			    b.SIMSN,
			    funcGetDesc("Search", "SIMID Carrier", a.SIMID) AS Telco,
			    a.MerchantRepresentative AS MechantRepresentative,
			    a.MerchantRepresentativePosition  AS MechantPosition,
			    a.MerchantContactNo  AS MechantContactNo,
			    a.MerchantRepresentativeEmail  AS MechantEmail,
			    funcGetDesc("Search", "Particular", d.FEID) AS FEName,
			    funcGetDesc("Search", "AreaCode", d.DispatchID) AS AreaCode,
			    funcGetDesc("Search", "Particular", d.DispatchID) AS Dispatcher,
			    IFNULL_STRING_ONLY2(a.ActionTaken) AS ActionTaken,
			    funcGetDesc("Search", "Reason", a.ReasonID) AS Reason,
			    b.AppVersion  AS AppVersion,
			    b.AppCRC  AS AppCRC,			    
			    "X-----------------------X" AS ExportInclusionStartHere_	
			    #funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)) AS Job_Type_Desc_,	    
			    #CONCAT(funcGetDesc("Search", "Service JobType Description", MAX(d.JobType)), " ", "(", funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(IFNULL(a.ActionMade, "")))), ")") AS ServiceType_
			    ';
			    
			#SELECT @baseQuery; -- Debugging: Print the generated query
			
			IF @JobTypeList = '1' THEN
				    SET @extraFields = ',					
					#IFNULL_STRING_ONLY2(IF(MAX(a.FSRNo) > 0, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
					#IFNULL_STRING_ONLY2(IF(MAX(d.JobType) = 1, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
