					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Setup"'')) AS POS_Setup_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Type"'')) AS POS_Type_,		
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."POS Connection Type"'')) AS POS_Connection_Type_,	
					IFNULL_FORMAT_DATE(COALESCE(MAX(a.FSRDate),d.ReqInstallationDate)) AS Target_Installation_Date_,					
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Pullout date  (applicable only to exhibit POS Request type)"'')) AS PullOutDateApplicableToExhibitPOS_Req_Type_,
					#IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."RM Instruction / Remarks"'')) AS RM_Instruction_Remarks_,	
