					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (TID)"'')) AS QR_Grab_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-Grab (MID)"'')) AS QR_Grab_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (TID)"'')) AS QR_UPI_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-UPI (MID)"'')) AS QR_UPI_M_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (TID)"'')) AS QR_P2M_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."QR-P2M (MID)"'')) AS QR_P2M_M_I_D_,

