					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - TID"'')) AS Multi_merchant_2_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 2 - MID"'')) AS Multi_merchant_2_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - Name"'')) AS Multi_merchant_3_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - TID"'')) AS Multi_merchant_3_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 3 - MID"'')) AS Multi_merchant_3_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - Name"'')) AS Multi_merchant_4_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - TID"'')) AS Multi_merchant_4_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 4 - MID"'')) AS Multi_merchant_4_M_I_D_,					

					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - Name"'')) AS Multi_merchant_5_Name_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - TID"'')) AS Multi_merchant_5_T_I_D_,
					IFNULL_STRING_ONLY2(fnJsonExtract(b.rawdata_info,''$.Values."Multi-merchant 5 - MID"'')) AS Multi_merchant_5_M_I_D_,						

					fnJsonExtract(b.profile_info,''$."DCC (Yes/No)"'') AS DCC_,
					fnJsonExtract(b.profile_info,''$."Installment (Yes/No)"'') AS Installment_,
					fnJsonExtract(b.profile_info,''$."Manual Key Entry (MKE) (Yes/No)"'') AS MKE_,
					fnJsonExtract(b.profile_info,''$."Preauth (Yes/No)"'') AS Preauth_,
					fnJsonExtract(b.profile_info,''$."Offline Sale (Yes/No)"'') AS Offline_Sale_,
					fnJsonExtract(b.profile_info,''$."Offline Sale Limit (To be specified)"'') AS Offline_Sale_Limit_,
					fnJsonExtract(b.profile_info,''$."Tip Adjust (Yes/No)"'') AS Tip_Adjust_,
					fnJsonExtract(b.profile_info,''$."Tip Adjust Limit (To be specified)"'') AS Tip_Adjust_Limit_,
					fnJsonExtract(b.profile_info,''$."Add-on Device  (To be specified)"'') AS Add_On_Device_,
					fnJsonExtract(b.profile_info,''$."ECR Integration (Yes/No)"'') AS ECR_Integration_,
					fnJsonExtract(b.profile_info,''$."ECR Cable Type"'') AS ECR_Cable_Type_
					
				    ';
				ELSE
				    SET @extraFields = ',							
							"-" AS Urgency_,
							"-" AS ScheduleByMerch_,
							
							#IFNULL_STRING_ONLY2(IF(MAX(a.FSRNo) > 0, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
							#IFNULL_STRING_ONLY2(IF(MAX(d.JobType) = 1, MAX(a.IRNo), MAX(d.IRNo))) AS RequestID_,
							IFNULL_STRING_ONLY2(MAX(d.IRNo)) AS RequestID_,
							IFNULL_STRING_ONLY2(MAX(d.Requestor)) AS RequestedBy_,
							
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", MAX(d.SourceID))) AS Source_,
							IFNULL_FORMAT_DATE(COALESCE(MAX(d.ReqInstallationDate), d.ServiceReqDate)) AS RequestDate_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", MAX(d.CategoryID))) AS Category_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", MAX(d.SubCategoryID))) AS SubCategory_,
							
							IFNULL_STRING_ONLY2(MAX(d.ProblemReported)) AS ProblemReported_,
							IFNULL_STRING_ONLY2(MAX(d.Vendor)) AS Vendor_,
							
							IFNULL_STRING_ONLY2(MAX(b.MID)) AS Merchant_I_D_,
							IFNULL_STRING_ONLY2(MAX(b.TID)) AS Terminal_I_D_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.MerchantID))) AS MerchantName_,
							IFNULL_STRING_ONLY2(MAX(c.Address)) AS MerchantAddress_,
							funcGetDesc("Search", "Region", MAX(c.RegionType)) AS Location_,
							IFNULL_STRING_ONLY2(MAX(c.ContactPerson)) AS ContactPerson_,
							IFNULL_STRING_ONLY2(MAX(c.ContactNumber)) AS ContactNumber_,
							IFNULL_STRING_ONLY2(MAX(d.TerminalSN)) AS SerialNumberOptional_							
							';
				END IF;

				IF @JobTypeList = '1' THEN
					SET @addFields = ',							
							funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(a.ActionMade), "|",MAX(d.JobTypeStatusDescription))) AS Status_,
							IFNULL_FORMAT_DATE(MAX(a.FSRDate)) AS Installation_Date_,							
							(funcGetGeneralActionTaken(a.JobType,a.IRIDNo,a.IRNo)) AS Installation_Remarks_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS Status_Reason_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS LatestAttemptReason_,
							funcGetDesc("Search", "Type", MAX(a.DependencyID)) AS Dependency_,
							IFNULL_STRING_ONLY2(MAX(a.TerminalSN)) AS POS_Serial_Number_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "TerminalID Model", MAX(a.TerminalID))) AS POS_Model_,
							IFNULL_STRING_ONLY2(MAX(b.AppVersion)) AS POS_Version_,
							IFNULL_STRING_ONLY2(MAX(b.AppCRC)) AS POS_CRC_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentative)) AS Mechant_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentativePosition)) AS Mechant_Representative_Position_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantContactNo)) AS Mechant_Representative_ContactNo_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.FEID))) AS Vendor_Representative_,														
							funcGetDesc("Search", "SIMID Carrier", MAX(a.SIMID)) AS Telco_							
							';
				ELSE
					SET @addFields = ',
							funcGetDesc("Search", "Daily Service Status", CONCAT(MAX(d.ServiceStatus),"|",MAX(a.ActionMade), "|",MAX(d.JobTypeStatusDescription))) AS Status_,
							IFNULL_FORMAT_DATE(MAX(a.FSRDate)) AS Date_,
							(funcGetGeneralActionTaken(a.JobType,a.IRIDNo,a.IRNo)) AS Remarks_,							
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS Reason_,
							IFNULL_STRING_ONLY2(MAX(a.AnyComments)) AS AdditionalRemarksIfNecessary_1_,
							funcGetDesc("Search", "Type", MAX(a.DependencyID)) AS Dependency_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Reason", MAX(a.ReasonID))) AS LastAttemptReason_
							';							
				END IF;
				
				SET @addFields = CONCAT(@addFields, ',
							
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason1"'') AS 1stAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate1"'') AS 1stAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable1"'') AS 1stAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason1"'') AS 1stAttemptBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks1"'') AS 1stAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade1"'') AS 1stAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason2"'') AS 2ndAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate2"'') AS 2ndAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable2"'') AS 2ndAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason2"'') AS 2ndAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks2"'') AS 2ndAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade2"'') AS 2ndAttemptActionMade_,

							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason3"'') AS 3rdAttemptReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate3"'') AS 3rdAttemptDate_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable3"'') AS 3rdAttemptBillable_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason3"'') AS 3rdAttempttBillingStatusReason_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks3"'') AS 3rdAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade3"'') AS 3rdAttemptActionMade_,

							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason4"'') AS 4thAttemptReason_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate4"'') AS 4thAttemptDate_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable4"'') AS 4thAttemptBillable_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason4"'') AS 4thAttempttBillingStatusReason_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks4"'') AS 4thAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade4"'') AS 4thAttemptActionMade_,

							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Reason5"'') AS 5thAttemptReason_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."FSRDate5"'') AS 5thAttemptDate_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."isBillable5"'') AS 5thAttemptBillable_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."StatusReason5"'') AS 5thAttempttBillingStatusReason_,
							#fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."Remarks5"'') AS 5thAttemptRemarks_,
							fnJsonExtract(funcGetJSON("Search", "Service Attempt", CONCAT( a.JobType, "|", a.IRIDNo, "|", a.IRNo)),''$."ActionMade5"'') AS 5thAttemptActionMade_,

							#"-" AS Beyond5thAttemptReason_,
							#"-" AS Beyond5thAttemptDate_,
							#"-" AS Beyond5thAttemptBillable_,
							##"-" AS Beyond5thAttemptReason_,
							#"-" AS Beyond5thAttemptRemarks_,
							"-" AS Beyond5thAttemptActionMade_
							') ;
				
				IF (@JobTypeList = '2' OR @JobTypeList = '3') THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Particular", MAX(d.FEID))) AS Vendor_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentative)) AS Mechant_Representative_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantRepresentativePosition)) AS Mechant_Representative_Position_,
							IFNULL_STRING_ONLY2(MAX(a.MerchantContactNo)) AS Mechant_Representative_ContactNo_
							
							') ;
				END IF;
				
				IF @JobTypeList = '2' THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(
							    MAX(
								CASE 
								    WHEN a.JobType = 7 THEN b.TerminalSN
								    ELSE a.TerminalSN
								END
							    )
							) AS UpdatedSerialNo_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "TerminalID Model", MAX(a.TerminalID))) AS POS_Model_,
							IFNULL_STRING_ONLY2(MAX(b.AppCRC)) AS POS_CRC_,
							IFNULL_STRING_ONLY2(MAX(b.AppVersion)) AS POS_Version_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT(MAX(d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
				ELSEIF @JobTypeList = '3' THEN
					SET @addFields = CONCAT(@addFields, ',
							IFNULL_STRING_ONLY2(MAX(a.TerminalSN)) AS ActualSerialNoPulledOut_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT(MAX(d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_
							') ;
					
				END IF;
				
				#SET @addFields = CONCAT(@addFields, ',
							#"-" AS BeyondReasonIfApplicable_,
							#IFNULL_STRING_ONLY2(MIN(a.BeyondReason)) AS BeyondReasonIfApplicable_,
							#"-" AS AdditionalRemarks_,
							#funcGetDesc("Search", "AreaCode", MAX(d.DispatchID)) AS Area_,
							#funcGetDesc("Search", "Particular", MAX(d.DispatchID)) AS HandlingTL_
							# ') ;
				
				IF @JobTypeList = '1' THEN
					SET @addFields = CONCAT(@addFields, ',
							funcGetDesc("Search", "Additional Remarks 2", CONCAT(MAX(d.JobType), "|", MAX(d.ServiceNo))) AS AdditionalRemarksIfNecessary_2_
							') ;		
				END IF;
				
				SET @addFields = CONCAT(@addFields, ',
							"-" AS CourierTrackingNumber_,
							"-" AS DateShipped_,
							"-" AS DateArrived_,
							"-" AS TodaDaysHandledByCourier_,
							
							#funcGetDesc("Search", "Service Ticket Status", MAX(d.TicketStatus)) AS TicketStatus_,
							IFNULL_FORMAT_DATE(MAX(d.TicketDateTime)) AS DateClosed_
							#funcGetDesc("Search", "Particular", MAX(d.DispatchID)) AS DispatchersName_
							
							') ;
				
				IF @JobTypeList = '1' THEN
					SET @addFields = CONCAT(@addFields, ',
							#"-" AS DateReportedToBank_,
							#IFNULL_FORMAT_DATE(MAX(d.ReportedDate)) AS DateReportedToBank_,
							IFNULL_STRING_ONLY2(COALESCE(DATE_FORMAT(MAX(d.ReqInstallationDate), "%M"), "0000-00-00")) AS Month_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", NULLIF(MAX(a.IssueCategoryID), 0))) AS IssueCategory_
							#IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", NULLIF(MAX(a.StatusReasonID), 0))) AS StatusReason_
							') ;
				ELSE
					SET @addFields = CONCAT(@addFields, ',
							"-" AS BankRemarksIfApplicable_,
							#funcGetDesc("Search", "Additional Remarks 2", CONCAT(MAX(d.JobType), "|", MAX(d.ServiceNo))) AS AdditionalRemarksIfNecessary_2_,
							#"-" AS DateReportedToBank_,
							#IFNULL_FORMAT_DATE(MAX(d.ReportedDate)) AS DateReportedToBank_,
							"-" AS BillingStatus_,
							"-" AS ValidationReason_,
							"-" AS RemarksIfNecessary_,
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", NULLIF(MAX(a.IssueCategoryID), 0))) AS IssueCategory_,						
							IFNULL_STRING_ONLY2(funcGetDesc("Search", "Type", NULLIF(MAX(a.StatusReasonID), 0))) AS StatusReason_
							') ;
				END IF;
				
						
				#SELECT @extraFields; -- Debugging: Print the generated query
				
				SET @fromClause = '
				FROM 
			        tblservicingdetail d
			       LEFT JOIN tblfsrdetail a ON a.ServiceNo = d.ServiceNo
			       LEFT JOIN tblirdetail b ON d.IRIDNo = b.IRIDNo
			       LEFT JOIN tblparticular c ON d.MerchantID = c.ParticularID
			       LEFT JOIN tblzoning z ON z.ZoneID = c.ZoneID';
				
				SET @whereBaseClause = '';
				
				IF (@JobTypeList = '1') THEN
				    SET @whereBaseClause = '
					WHERE
					    d.ClientID = ? 
					    AND (FIND_IN_SET(d.JobType, ?))
					    AND (d.IRIDNo = ? OR ? = 0)
					    AND (d.IRNo = ? OR ? = ''0'')
					    AND (a.ReasonID = ? OR ? = 0)
					    AND (
						    -- FSR date condition
						    (a.FSRDate BETWEEN ? AND ?)
						    
						 OR -- ReqInstallationDate + status condition
						    (
							d.ReqInstallationDate BETWEEN ? AND ?
							AND d.ServiceStatus IN (8,9,10)
							AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')
						    )
						 OR -- JobType 7 + Reason 60 must still follow date/status conditions
						    (
							d.JobType = 7
							AND a.ReasonID = 60
							AND (
							    (a.FSRDate BETWEEN ? AND ?)
							    OR (
								d.ReqInstallationDate BETWEEN ? AND ?
								AND d.ServiceStatus IN (8,9,10)
								AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')
							    )
							)
						    )
						)
					    AND d.isActive > 0';
				ELSEIF (@JobTypeList = '2') THEN
					SET @whereBaseClause = '
					   WHERE
					    d.ClientID = ? 
					    AND FIND_IN_SET(d.JobType, ?) 
					    AND (d.IRIDNo = ? OR ? = 0)
					    AND (d.IRNo = ? OR ? = ''0'')
					    AND (a.ReasonID = ? OR ? = 0)
					    AND ((a.FSRDate BETWEEN ? AND ?) OR ((d.ReqInstallationDate BETWEEN ? AND ?) AND d.ServiceStatus IN (8,9,10) AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')) AND (a.ReasonID > 0 AND a.ReasonID NOT IN (60)))				    
					    AND (d.isActive > 0)';
				ELSE
					SET @whereBaseClause = '
					   WHERE
					    d.ClientID = ? 
					    AND FIND_IN_SET(d.JobType, ?) 
					    AND (d.IRIDNo = ? OR ? = 0)
					    AND (d.IRNo = ? OR ? = ''0'')
					    AND (a.ReasonID = ? OR ? = 0)
					    AND ((a.FSRDate BETWEEN ? AND ?) OR ((d.ReqInstallationDate BETWEEN ? AND ?) AND d.ServiceStatus IN (8,9,10) AND d.JobTypeStatusDescription IN (''PENDING'', ''COMPLETED'')))				    
					    AND (d.isActive > 0)';
				END IF;
				
				-- Append Report Filter
				SET @whereBaseClause = CONCAT(@whereBaseClause, @reportClause);

				#SELECT CONCAT("@whereBaseClause=",@whereBaseClause); -- Debugging: Print the generated query
				
				SET @whereClause = '';  
				SET @whereClause = CONCAT(@whereBaseClause);
				
				#SELECT CONCAT("@whereMaxClause=",@whereMaxClause); -- Debugging: Print the generated query
				
				SET @orderClause = '';
				SET @orderClause = '
				ORDER BY d.ReqInstallationDate, d.IRNo';
				
				SET @groupClause = '';				
				SET @groupClause = '
				GROUP BY d.IRNo';				
				
				#SELECT @fromClause; -- Debugging: Print the generated query
				
				SET @finalQuery = CONCAT(@baseQuery, @extraFields, @addFields, @fromClause, @whereClause);
				
				SET @whereUnionClause = '';
				SET @whereUnionClause = '
				   WHERE
				    d.ClientID = ? 
				    AND FIND_IN_SET(d.JobType, ?) 
				    AND (a.IRIDNo = ? OR ? = 0)
				    AND (a.IRNo = ? OR ? = ''0'')
				    AND (a.ReasonID = ? OR ? = 0)
				    AND ((d.ReqInstallationDate BETWEEN ? AND ?) OR (? = ''0000-00-00'' AND ? = ''0000-00-00''))
				    AND (d.isActive > 0)
				    AND (d.JobTypeStatusDescription IN (''PENDING'', ''PROCESSING''))
				    AND (a.isReport IS NULL OR a.isReport = 1)';
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				
				IF (v_ExcludePending > 0) THEN
					SET @finalQuery = @finalQuery;
				ELSE
					SET @finalQuery = CONCAT(@finalQuery, '
							UNION ALL 
							',
				                        @baseQuery, @extraFields, @addFields, @fromClause, @whereUnionClause);
				END IF;
				
				SET @finalQuery = CONCAT(@finalQuery, ' ', @groupClause, ' ', @orderClause, ';');
				
				#SELECT CONCAT("@whereUnionClause=",@whereUnionClause); -- Debugging: Print the generated query
				#SELECT CONCAT("@finalQuery=",@finalQuery); -- Debugging: Print the generated query
				
				SET @TempJobTypeList = @JobTypeList; # hold variable value
				
				SET @ClientID = v_ClientID;
				SET @JobTypeList = v_JobTypeList;
				SET @IRIDNo = v_IRIDNo;
				SET @IRNo = v_IRNo;
				SET @DateFrom = v_DateFrom;
				SET @DateTo = v_DateTo;
				SET @ReasonID = v_ReasonID;

				PREPARE stmt FROM @finalQuery;
				
				IF v_ExcludePending > 0 THEN			
				    IF (@TempJobTypeList = '1') THEN
					EXECUTE stmt USING 
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @ReasonID, @ReasonID, @DateFrom, @DateTo, @DateFrom, @DateTo, @DateFrom, @DateTo, @DateFrom, @DateTo;
				    ELSE
					EXECUTE stmt USING 
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @ReasonID, @ReasonID, @DateFrom, @DateTo, @DateFrom, @DateTo;
				    END IF;
				    
				ELSE
				    EXECUTE stmt USING 
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @ReasonID, @ReasonID, @DateFrom, @DateTo, @DateFrom, @DateTo,
					    @ClientID, @JobTypeList, @IRIDNo, @IRIDNo, @IRNo, @IRNo, @DateFrom, @DateTo, @DateFrom, @DateTo;
				END IF;

				DEALLOCATE PREPARE stmt;	
			
		ELSEIF (p_SearchBy = 'Zoning-List-Report') THEN
                SELECT
                    a.ZoneID,
                    a.Cluster,
                    a.Region,
                    a.Area,
                    a.CityMunicipal,
                    a.ZoneName,
                    a.SLA,
                    a.DateTimeStamp
                FROM tblzoning AS a
                ORDER BY
                    a.ZoneName,
                    a.CityMunicipal;

		ELSEIF (p_SearchBy = 'Zoning-Alias-List-Report') THEN
		    SELECT
			a.AliasID,
			a.AliasName,
			a.OfficialName,
			a.Priority
		    FROM tblzoningalias AS a
		    ORDER BY
			a.Priority,
			a.AliasName;
		
    ELSEIF (p_SearchBy = 'Expenses-Report') THEN
        SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)) AS UNSIGNED INTEGER);
        SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)) AS UNSIGNED INTEGER);

        SELECT
            IFNULL_NUMERIC(expt.ServiceNo) AS ServiceNo,
            IFNULL_STRING_ONLY(funcGetDesc('Search', 'Particular', svc.ClientID)) AS `Client`,
            IFNULL_STRING_ONLY(pt.Name) AS MerchantName,
            IFNULL_STRING_ONLY(pt.Address) AS MerchantAddress,
            IFNULL_DECIMAL(expm.TotalAmount) AS TotalAmount,
            IFNULL_FORMAT_DATE(fsr.FSRDate) AS ServiceDate,
            IFNULL_STRING_ONLY(expm.Location) AS LocationFrom,
            IFNULL_STRING_ONLY(funcGetDesc('Search', 'Region Detail', pt.RegionID)) AS LocationTo,
            IFNULL_STRING_ONLY(svc.FEName) AS FieldEngineer,
            IFNULL_STRING_ONLY(svc.DispatchBy) AS Dispatcher,
            IFNULL_FORMAT_DATE(expt.ExpensesDate) AS ExpensesDate,
            IFNULL_STRING_ONLY(expt.Remarks) AS Remarks,
            IFNULL_STRING_ONLY(expt.ExpensesReferenceNo) AS ExpenseID,
            IFNULL_DECIMAL(expt.Amount) AS Amount,
            IFNULL_STRING_ONLY(funcGetDesc('Search', 'ExpenseDesc', expt.ExpensesID)) AS ExpenseType,
            CONCAT(expt.ServiceNo, '_', expt.ExpensesID, '_', DATE_FORMAT(expt.ExpensesDate, '%Y%m%d'), '_') AS ImageFilePrefix,
            0 AS ReceiptCount

        FROM tblexpensestransdetail AS expt

        INNER JOIN tblexpensestransmaster AS expm ON expm.ServiceNo = expt.ServiceNo

        INNER JOIN tblservicingdetail AS svc ON svc.ServiceNo = expt.ServiceNo

        LEFT JOIN tblfsrdetail AS fsr ON fsr.ServiceNo = expt.ServiceNo

        LEFT JOIN tblparticular AS pt ON pt.ParticularID = svc.MerchantID

        WHERE expt.ServiceNo = v_ServiceNo
        AND svc.MerchantID = v_MerchantID

        ORDER BY expt.ExpensesDate, expt.DetailID;

    ELSEIF (p_SearchBy = 'Expenses-Receipt-Report') 
	THEN 
        SET @ExpensesNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));        
        
        SELECT
		b.MerchantName,
		a.ReferenceNo,
		IFNULL_FORMAT_DATE_ONLY(b.ExpensesDate) AS ExpensesDate,
		b.Amount,
		c.Description,
		b.Remarks,
		b.ReceiptFileName
		FROM
		tblexpensestransmaster a
		LEFT JOIN tblexpensestransdetail b ON a.ExpensesNo = b.ExpensesNo
		LEFT JOIN tblexpenses c ON b.ExpensesID = c.ExpensesID
		WHERE
		a.ExpensesNo = @ExpensesNo;
		
     ELSEIF (p_SearchBy = 'Expenses-Trans-Report') 
	THEN 
        SET @ExpensesNo = TRIM(SPLIT_STRING(p_SearchValue, '|', 1));        
        
        SELECT
                a.ExpensesNo,
                IFNULL_FORMAT_DATE_ONLY(a.ExpensesDate) AS ExpensesDate,
                funcGetDesc("Search", "Particular", a.FEID) AS FEName,
                a.TotalAmount,
                a.CreatedBy,
                a.CreatedDate,
                a.UpdatedBy,
                a.UpdatedDate,
		b.MerchantName,
		a.ReferenceNo,
		IFNULL_FORMAT_DATE_ONLY(b.ExpensesDate) AS ExpensesDate,
		b.Amount,
		c.Description,
		b.Remarks,
		b.ReceiptFileName
		FROM
		tblexpensestransmaster a
		LEFT JOIN tblexpensestransdetail b ON a.ExpensesNo = b.ExpensesNo
		LEFT JOIN tblexpenses c ON b.ExpensesID = c.ExpensesID
		WHERE
		a.ExpensesNo = @ExpensesNo;
            
     END IF;

END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewRequestFormDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewRequestFormDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewRequestFormDetail`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT DISTINCT 

		RequestID,

		ProductID,

		TerminalType,

		TerminalModel,

		SerialNo,

		TID,

		MID,

		AdapterSerialNo,

		SIMCardNo

		FROM   tblrequestformdetail;

		

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'RequestID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			RequestID,

			ProductID,

			TerminalType,

			TerminalModel,

			SerialNo,

			TID,

			MID,

			AdapterSerialNo,

			SIMCardNo

			FROM        tblrequestformdetail

			WHERE       (RequestID = v_ID);

            

		ELSEIF (p_SearchBy = 'ProductID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT DISTINCT 

			tblrequestformmaster.RequestID,

			tblrequestformmaster.RequestDate,

			tblrequestformmaster.PreparedBy,

			tblrequestformmaster.ClientName,

			tblrequestformmaster.MerchantName,

			tblrequestformmaster.FEName,

			tblrequestformdetail.SerialNo,

			tblrequestformdetail.TID,

			tblrequestformdetail.MID,

			tblrequestformdetail.AdapterSerialNo,

			tblrequestformdetail.SIMCardNo

			FROM

			tblrequestformdetail

			INNER JOIN tblrequestformmaster ON tblrequestformmaster.RequestID = tblrequestformdetail.RequestID

			WHERE

			tblrequestformdetail.ProductID = v_ID;

            

         END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewRequestFormMaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewRequestFormMaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewRequestFormMaster`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT DISTINCT 

		RequestID,

		ClientID,

		MerchantID,

		FEID,

		ReqStatus,

		RequestNo,

		RequestDate,

		PreparedBy,

		ClientName,

		MerchantName,

		FEName,

		Remarks,

		ReqStatusDesc,

        RequestDateModified,

        ModifiedBy

		FROM   tblrequestformmaster

		ORDER BY RequestID;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'RequestID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT DISTINCT

			tblrequestformmaster.RequestID,

			tblrequestformmaster.ClientID,

			tblrequestformmaster.MerchantID,

			tblrequestformmaster.FEID,

			tblrequestformmaster.ReqStatus,

			tblrequestformmaster.RequestNo,

			tblrequestformmaster.RequestDate,

			tblrequestformmaster.PreparedBy,

			tblrequestformmaster.ClientName,

			tblrequestformmaster.MerchantName,

			tblrequestformmaster.FEName,

			tblrequestformmaster.Remarks,

			tblrequestformmaster.ReqStatusDesc,

			tblrequestformmaster.RequestDateModified,

			tblrequestformmaster.ModifiedBy,

			tblmerchant.Address AS MAddress,

			tblclient.Address AS CAddress

			FROM

			tblrequestformmaster

			INNER JOIN tblmerchant ON tblrequestformmaster.MerchantID = tblmerchant.MerchantID

			INNER JOIN tblclient ON tblrequestformmaster.ClientID = tblclient.ClientID

			WHERE       (RequestID = v_ID)

			LIMIT 1 ;

         

		ELSEIF (p_SearchBy = 'ClientID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			RequestID,

			ClientID,

			MerchantID,

			FEID,

			ReqStatus,

			RequestNo,

			RequestDate,

			PreparedBy,

			ClientName,

			MerchantName,

			FEName,

			Remarks,

			ReqStatusDesc,

            RequestDateModified,

			ModifiedBy

			FROM        tblrequestformmaster

			WHERE       (ClientID = v_ID)

            LIMIT 1;

         

		ELSEIF (p_SearchBy = 'MerchantID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

			RequestID,

			ClientID,

			MerchantID,

			FEID,

			ReqStatus,

			RequestNo,

			RequestDate,

			PreparedBy,

			ClientName,

			MerchantName,

			FEName,

			Remarks,

			ReqStatusDesc,

            RequestDateModified,

			ModifiedBy

			FROM        tblrequestformmaster

			WHERE       (MerchantID = v_ID)

            LIMIT 1;

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewServiceCall` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewServiceCall` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewServiceCall`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_TAIDNo INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Service Call Detail')

		THEN

			SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT

			IFNULL(a.SCNo, 0) AS SCNo,

			IFNULL(a.TAIDNo, 0) AS TAIDNo,

			IFNULL(a.ClientID, 0) AS ClientID,

			IFNULL(a.MerchantID, 0) AS MerchantID, 

			IFNULL(a.ClientName, "-") AS ClientName,

			IFNULL(a.MerchantName, "-") AS MerchantName,

			IFNULL(a.IRIDNo, 0) AS IRIDNo,

			IFNULL(a.IRNo, "-") AS IRNo,

			IFNULL(a.TerminalID, 0) AS TerminalID,

			IFNULL(a.TerminalSN, "-") AS TerminalSN,

			IFNULL(a.SIMID, 0) AS SIMID,

			IFNULL(a.SIMSerialNo, "-") AS SIMSerialNo,

			IFNULL(a.AttemptNo, "0") AS AttemptNo,

			IFNULL(a.ReferralID, "0") AS ReferralID,

			IFNULL(DATE_FORMAT(a.SCDateTime, "%m-%d-%Y %r"), "-") AS SCDateTime,

			IFNULL(DATE_FORMAT(a.SCDate, "%m-%d-%Y"), "-") AS SCDate,

			IFNULL(DATE_FORMAT(a.SCTime, "%r"), "-") AS SCTime,

			IFNULL(DATE_FORMAT(a.SCReqDate, "%m-%d-%Y"), "-") AS SCReqDate,

			IFNULL(a.SCReqTime, "-") AS SCReqTime,

			IFNULL(DATE_FORMAT(a.SCShipDate, "%m-%d-%Y"), "-") AS SCShipDate,

			IFNULL(a.SCShipTime, "-") AS SCShipTime,

			IFNULL(a.CustomerName, "-") AS CustomerName,

			IFNULL(a.CustomerContactNo, "-") AS CustomerContactNo,

			IFNULL(a.ReportedProblem, "-") AS ReportedProblem,

			IFNULL(a.ArrangementMade, "-") AS ArrangementMade,

			IFNULL(a.TrackingNo, "-") AS TrackingNo,

			IFNULL(a.SCStatus, "-") AS SCStatus

					

			FROM   

			tblservicecalldetail a

			WHERE TAIDNo = v_TAIDNo		

			ORDER BY SCNo DESC;           

		

		END IF;

		

    END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewServiceProvider` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewServiceProvider` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewServiceProvider`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT ProviderID, NAME, Address, TelNo,  Mobile, Fax, Email, ContractTerms

		FROM   tblserviceprovider

		ORDER BY NAME;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Name')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						ProviderID,

						NAME,

						Address,

                        TelNo,

                        Mobile,

                        Fax,

                        Email,

                        ContractTerms

			FROM        tblserviceprovider

			WHERE       (NAME LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'ProviderID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						ProviderID,

						NAME,

						Address,

                        TelNo,

                        Mobile,

                        Fax,

                        Email,

                        ContractTerms

			FROM        tblserviceprovider

			WHERE       (ProviderID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewServiceType` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewServiceType` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewServiceType`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(255) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE V_ServiceTypeID INTEGER;

	DECLARE v_Description VARCHAR(255);

	DECLARE v_Code VARCHAR(255);

	DECLARE v_ServiceStatus VARCHAR(255);

	DECLARE v_ServiceStatusDescription VARCHAR(255);

	DECLARE v_JobTypeDescription VARCHAR(255);

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_SQL LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Service Type Active')

		THEN

			SELECT ServiceTypeID, Description, `Code`, ServiceStatus, ServiceStatusDescription, JobType, JobTypeDescription, ServiceJobTypeDescription

			FROM   tblservicetype	

			WHERE  ServiceTypeActive > 0		

			ORDER BY SequenceDisplay;

		

		ELSEIF (p_SearchBy = 'Service Type Enrollment')

		THEN

			SELECT ServiceTypeID, Description, `Code`, ServiceStatus, ServiceStatusDescription, JobType, JobTypeDescription, ServiceJobTypeDescription

			FROM   tblservicetype	

			WHERE  ServiceStatus IN (1, 2, 3, 4, 5)		

			ORDER BY SequenceDisplay;

				

		ELSEIF (p_SearchBy = 'Service Status Active')

		THEN

			SELECT ServiceTypeID, Description, `Code`, ServiceStatus, ServiceStatusDescription, JobType, JobTypeDescription, ServiceJobTypeDescription

			FROM   tblservicetype	

			WHERE  ServiceStatusActive > 0		

			ORDER BY SequenceDisplay;

			

		ELSEIF (p_SearchBy = 'Service Status TA')

		THEN

			SELECT ServiceTypeID, Description, `Code`, ServiceStatus, ServiceStatusDescription, JobType, JobTypeDescription, ServiceJobTypeDescription

			FROM   tblservicetype	

			WHERE  ServiceStatus IN (1)		

			ORDER BY SequenceDisplay;

			

		ELSEIF (p_SearchBy = 'Import FSR')

		THEN

			SELECT ServiceTypeID, Description, `Code`, ServiceStatus, ServiceStatusDescription, JobType, JobTypeDescription, ServiceJobTypeDescription

			FROM   tblservicetype	

			WHERE  `Code` IN ('2222', '3333', '5555', '7777')		

			ORDER BY SequenceDisplay;

			

		ELSEIF (p_SearchBy = "FSR For Client")

		THEN

			SELECT

			xTable.JobType,

			xTable.JobTypeDescription,

			MAX(xTable.cntSuccess) AS cntSuccess,

			MAX(xTable.cntNegative) AS cntNegative

			FROM

			(

			SELECT

			a.JobType,

			a.JobTypeDescription,

			(IF(b.ActionMade = "SUCCESS", COUNT(*), 0)) AS cntSuccess,

			(IF(b.ActionMade = "NEGATIVE", COUNT(*), 0)) AS cntNegative

			FROM

			tblservicetype a

			LEFT JOIN tblfsrclient b ON a.JobType = b.JobType

			WHERE a.isActive > 0

			GROUP BY a.JobType, a.JobTypeDescription, b.ActionMade

			)AS xTable

			GROUP BY xTable.JobType, xTable.JobTypeDescription;

		ELSEIF (p_SearchBy = 'Service Type Status Category')
		THEN
			SELECT ServiceTypeID, Description, `Code`, ServiceStatus, ServiceStatusDescription, JobType, JobTypeDescription, ServiceJobTypeDescription
			FROM   tblservicetype	
			WHERE  ServiceStatus IN (9, 10) # Hold, Cancelled
			ORDER BY SequenceDisplay;
				

		ELSE

			SELECT ServiceTypeID, Description, `Code`, ServiceStatus, ServiceStatusDescription, JobType, JobTypeDescription, ServiceJobTypeDescription

			FROM   tblservicetype			

			ORDER BY SequenceDisplay;

		END IF;

		

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Info')

		THEN

			SET v_ServiceTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);						

			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_Code = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

			

			SET p_WHERE = '';

			IF (v_ServiceTypeID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceTypeID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ServiceTypeID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_ServiceStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ServiceStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_Description, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Description = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_Description, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_Code, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.`Code` = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_Code, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_ServiceStatusDescription, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceStatusDescription = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceStatusDescription, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

            			

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ServiceTypeID, 0) AS ServiceTypeID, 

							IFNULL(a.Description, "-") AS Description,

							IFNULL(a.`Code`, "-") AS Code,							

							IFNULL(a.ServiceStatus, 0) AS ServiceStatus,														

							IFNULL(a.ServiceStatusDescription, "-") AS ServiceStatusDescription,

							IFNULL(a.JobType, 0) AS JobType,

							IFNULL(a.JobTypeDescription, "-") AS JobTypeDescription,

							IFNULL(a.ServiceJobTypeDescription, "-") AS ServiceJobTypeDescription													

							FROM tblservicetype AS a');	

							

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

            

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

								

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Description')

		THEN

			#SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						ServiceTypeID,

						Description,

			`Code`,

			ServiceStatus, 

			ServiceStatusDescription

			FROM        tblservicetype

			WHERE       (Description = p_SearchValue);

		ELSEIF (p_SearchBy = 'ServiceTypeID')

		THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						ServiceTypeID,

						Description,

			`Code`,

			ServiceStatus, 

			ServiceStatusDescription

			FROM        tblservicetype

			WHERE       (ServiceTypeID = v_ID);

			

		ELSEIF (p_SearchBy = 'JobTypeDescription')

		THEN	

			SET v_JobTypeDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			

			SET p_WHERE = '';

			IF (LENGTH(v_JobTypeDescription) > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.JobTypeDescription = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_JobTypeDescription, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

            			

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ServiceStatus, 0) AS ServiceStatus													

							FROM tblservicetype AS a');	

							

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

            

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

								

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewServicingDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewServicingDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewServicingDetail`(  
    p_StatementType VARCHAR(30) /* = NULL */ ,
	p_SearchBy VARCHAR(50) /* = NULL */ ,
	p_SearchValue VARCHAR(255) /* = NULL */
)
BEGIN
	DECLARE v_ID INTEGER;
	DECLARE v_ServiceNo INTEGER;	
	DECLARE v_TAIDNo INTEGER;
	DECLARE v_MerchantID INTEGER;
	DECLARE v_ClientID INTEGER;
	DECLARE v_FEID INTEGER;
	DECLARE v_TerminalID INTEGER;
	DECLARE v_SIMID INTEGER;
	DECLARE v_DockID INTEGER;
	DECLARE v_IRIDNo INTEGER;
	DECLARE v_RequestNo VARCHAR(45);
	DECLARE v_ServiceStatus INTEGER;
	DECLARE v_ServiceStatusDescription VARCHAR(45);
	DECLARE v_TID VARCHAR(45);
	DECLARE v_MID VARCHAR(45);
	DECLARE v_DateFrom VARCHAR(45);
	DECLARE v_DateTo VARCHAR(45);
	DECLARE v_ServiceCode VARCHAR(45);
	DECLARE v_JobType INTEGER;
	DECLARE v_JobTypeDescription VARCHAR(500);
	DECLARE v_JobTypeStatusDescription VARCHAR(500);
	DECLARE v_OffSetFrom INTEGER;
	DECLARE v_OffSetTo INTEGER;
	DECLARE v_OffSet INTEGER;
	DECLARE v_isPrimary INTEGER;
	DECLARE v_TableName VARCHAR(45);
	DECLARE p_SearchQuery VARCHAR(100);
	DECLARE p_WHERE LONGTEXT;
	DECLARE p_ORDERBY LONGTEXT;
	DECLARE p_GROUPBY LONGTEXT;
	DECLARE p_LIMIT LONGTEXT;
	DECLARE p_SQL LONGTEXT;
    
    IF (p_StatementType = 'View')
	THEN
		IF (p_SearchBy = 'Servicing Detail')
		THEN
			SET v_ServiceNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
			SET v_TAIDNo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);
			SET v_ServiceStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
			SET v_ServiceStatusDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));
			SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);
			SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);
			SET v_TID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));
			SET v_MID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,8));
			
			SET p_WHERE = '';
			IF (v_ServiceNo > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ServiceNo = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_ServiceNo, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;	
			
			IF (v_TAIDNo > 0)
			THEN
