				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;

			

			IF (LENGTH(v_MID) > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'xTable.MID = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_MID, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			
			SET p_SQL = '';	
			SET p_SQL = CONCAT(p_SQL,'SELECT');
			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(xTable.ServiceNo) AS ServiceNo,							
							IFNULL_NUMERIC(xTable.IRIDNo) AS IRIDNo,
							IFNULL_NUMERIC(xTable.TAIDNo) AS TAIDNo,
							IFNULL_NUMERIC(xTable.ClientID) AS ClientID,
							IFNULL_NUMERIC(xTable.FEID) AS FEID,
							IFNULL_NUMERIC(xTable.MerchantID) AS MerchantID,
							IFNULL_NUMERIC(xTable.RegionID) AS RegionID,
							IFNULL_NUMERIC(xTable.RegionType) AS RegionType,
							IFNULL_STRING(xTable.RequestNo) AS RequestNo,
							IFNULL_STRING(xTable.ReferenceNo) AS ReferenceNo,							
							IFNULL_STRING(xTable.ServiceDateTime) AS ServiceDateTime,
							IFNULL_STRING(xTable.ServiceDate) AS ServiceDate,
							IFNULL_STRING(xTable.ServiceTime) AS ServiceTime,
							IFNULL_STRING(xTable.ServiceReqDate) AS ServiceReqDate,
							IFNULL_STRING(xTable.ServiceReqTime) AS ServiceReqTime,
							IFNULL_STRING(xTable.JobTypeDescription) AS JobTypeDescription,
							IFNULL_STRING(xTable.ServiceJobTypeDescription) AS ServiceJobTypeDescription,
							IFNULL_STRING(xTable.JobTypeStatusDescription) AS JobTypeStatusDescription,
							IFNULL_NUMERIC(xTable.ServiceStatus) AS ServiceStatus,
							IFNULL_STRING(xTable.ServiceStatusDescription) AS ServiceStatusDescription,
							IFNULL_STRING(xTable.IRNo) AS IRNo,
							IFNULL_STRING(xTable.MerchantName) AS MerchantName,
							IFNULL_STRING(xTable.TID) AS TID,
							IFNULL_STRING(xTable.`MID`) AS `MID`,
							IFNULL_STRING(xTable.TerminalSN) AS TerminalSN,
							IFNULL_STRING(xTable.SIMSN) AS SIMSN,
							IFNULL_STRING(xTable.ReplaceTerminalSN) AS ReplaceTerminalSN,
							IFNULL_STRING(xTable.ReplaceSIMSN) AS ReplaceSIMSN,
							IFNULL_NUMERIC(xTable.FSRNo) AS FSRNo,
							IFNULL_STRING(xTable.ActionMade) AS ActionMade,
							IFNULL_STRING(xTable.PrimaryNum) AS PrimaryNum,
							IFNULL_STRING(xTable.SecondaryNum) AS SecondaryNum,
							IFNULL_STRING(xTable.ProcessedBy) AS ProcessedBy,
							IFNULL_STRING(xTable.ProcessedDateTime) AS ProcessedDateTime,
							IFNULL_STRING(xTable.ModifiedBy) AS ModifiedBy,
							IFNULL_STRING(xTable.ModifiedDateTime) AS ModifiedDateTime,
							IFNULL_NUMERIC(xTable.MobileID) AS MobileID,
							IFNULL_STRING(xTable.Reason) AS Reason,
							IFNULL_STRING(xTable.Dependency) AS Dependency,
							IFNULL_STRING(xTable.StatusReason) AS StatusReason,
							IFNULL_NUMERIC(xTable.ZoneID) AS ZoneID
							FROM
							(
							SELECT
							a.ServiceNo,							
							a.IRIDNo,
							a.TAIDNo,
							a.ClientID,
							a.FEID,
							a.MerchantID,
							a.RegionID,
							a.RegionType,
							a.RequestNo,
							a.ReferenceNo,
							a.ServiceDateTime,
							a.ServiceDate,
							a.ServiceTime,
							a.ServiceReqDate,
							a.ServiceReqTime,
							a.JobTypeDescription,
							d.ServiceJobTypeDescription,
							a.JobTypeStatusDescription,
							a.ServiceStatus,
							a.ServiceStatusDescription,
							a.IRNo,
							b.MerchantName,
							b.TID,
							b.`MID`,
							
							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.TerminalID)) AS TerminalSN,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.SIMID)) AS SIMSN,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "Terminal Detail", a.ReplaceTerminalID)) AS ReplaceTerminalSN,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "SIM Detail", a.ReplaceSIMID)) AS ReplaceSIMSN,

							(CONCAT(IFNULL_STRING(a.IRNo), "^", 
							IFNULL_STRING(a.IRIDNo), "^",
							IFNULL_STRING(b.MerchantName), "^", 
							IFNULL_STRING(b.TID), "^", 
					
							IFNULL_STRING(a.TerminalSN), "^", 
							IFNULL_STRING(a.SIMSerialNo))) AS sFields,
							a.isPrimary,
							c.FSRNo,
							c.ActionMade,
							b.PrimaryNum,
							b.SecondaryNum,
							a.ProcessedBy,
							IFNULL_FORMAT_DATETIME(a.ProcessedDateTime) AS ProcessedDateTime,
							a.ModifiedBy,							
							IFNULL_FORMAT_DATETIME(a.ModifiedDateTime) AS ModifiedDateTime,
							c.MobileID,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "Reason", c.ReasonID)) AS Reason,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "Type", c.DependencyID)) AS Dependency,
							IFNULL_STRING_ONLY(funcGetDesc("Search", "Type", c.StatusReasonID)) AS StatusReason,	
							e.ZoneID			
							FROM
							tblservicingdetail a
							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo AND a.MerchantID = b.MerchantID 
							LEFT JOIN tblfsrdetail AS c ON a.IRIDNo = c.IRIDNo AND a.TAIDNo = c.TAIDNo AND a.ServiceNo = c.ServiceNo
							LEFT JOIN tblservicetype AS d ON a.JobType = d.JobType
							LEFT JOIN tblparticular AS e ON a.MerchantID = e.ParticularID
							) AS xTable');
							
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
				
			IF (LENGTH(p_WHERE) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
			END IF;
			SET p_SQL = REPLACE(p_SQL, '"', "'");
			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('After:p_SQL = ', p_SQL);	
			
			IF (v_OffSetTo > 0)
			THEN	
				SET v_OffSet = 0;
				
				IF (v_OffSetFrom <= 1)
				THEN
					SET v_OffSet = 0;
				ELSE
					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;
				END IF;
				
				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');
				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);
			END IF;
			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT(':p_SQL = ', p_SQL);
			
			SET p_ORDERBY = '';
			SET p_ORDERBY = 'xTable.ServiceNo';
			
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
			END IF;
			
			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT(':p_SQL = ', p_SQL);
				
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;
			
		ELSEIF (p_SearchBy = 'ServiceNo')
		THEN
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
			
			SELECT
			IFNULL_NUMERIC(ServiceNo) AS ServiceNo,      
			IFNULL_NUMERIC(TAIDNo) AS TAIDNo,
			IFNULL_NUMERIC(IRIDNo) AS IRIDNo,
			IFNULL_STRING(IRNo) AS IRNo,
			IFNULL_NUMERIC(ClientID) AS ClientID,
			IFNULL_NUMERIC(MerchantID) AS MerchantID,	
			IFNULL_STRING(RequestNo) AS RequestNo,
			IFNULL_STRING(IRNo) AS IRNo,
			ServiceDateTime,
			ServiceDate,
			ServiceTime,
			ServiceReqDate,
			ServiceReqTime,	
			IFNULL_STRING(ReferenceNo) AS ReferenceNo,	
			IFNULL_STRING(CustomerName) AS CustomerName,
			IFNULL_STRING(CustomerContactNo) AS CustomerContactNo,
			IFNULL_STRING(Remarks) AS Remarks,
			IFNULL_NUMERIC(TerminalID) AS TerminalID,
			IFNULL_STRING(TerminalSN) AS TerminalSN,
			IFNULL_NUMERIC(SIMID) AS SIMID,
			IFNULL_STRING(SIMSerialNo) AS SIMSN,
			IFNULL_NUMERIC(ReplaceTerminalID) AS ReplaceTerminalID,
			IFNULL_STRING(ReplaceTerminalSN) AS ReplaceTerminalSN,
			IFNULL_NUMERIC(ReplaceSIMID) AS ReplaceSIMID,
			IFNULL_STRING(ReplaceSIMSN) AS ReplaceSIMSN,
			IFNULL_STRING(AppVersion) AS AppVersion,
			IFNULL_STRING(AppCRC) AS AppCRC
			FROM        
			tblservicingdetail
			WHERE       
			(ServiceNo = v_ID);
			
		ELSEIF (p_SearchBy = 'Last Servicing Requested By')
		THEN
			SET v_TableName = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);	
			
			IF (v_TableName = 'Servicing')
			THEN
				SELECT	
				IFNULL_NUMERIC(ServiceNo) AS ServiceNo,				
				IFNULL_STRING(CustomerName) AS CustomerName,
				IFNULL_STRING(CustomerContactNo) AS CustomerContactNo,
				IFNULL_STRING(Remarks) AS Remarks
				FROM        
				tblservicingdetail
				WHERE       
				(TAIDNo = v_ID)
				ORDER BY ServiceNo DESC
				LIMIT 1;
			
			ELSEIF (v_TableName = 'FSR')
			THEN
				SELECT	
				IFNULL_NUMERIC(ServiceNo) AS ServiceNo,				
				IFNULL_STRING(CustomerName) AS CustomerName,
				IFNULL_STRING(CustomerContactNo) AS CustomerContactNo,
				IFNULL_STRING(Remarks) AS Remarks
				FROM        
				tblservicingdetail
				WHERE       
				(ServiceNo = v_ID)
				ORDER BY ServiceNo DESC
				LIMIT 1;
			END IF;
			
		ELSEIF (p_SearchBy = 'Service History')
		THEN						
			SET v_MerchantID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	
						
			SET p_WHERE = '';
			IF (v_MerchantID > 0)
			THEN
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'xTable.MerchantID = ');
				SET p_WHERE = CONCAT(p_WHERE, "'", v_MerchantID, "'");
				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
			END IF;
			
			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));
			#SELECT CONCAT('p_WHERE = ', p_WHERE);
			
			SET p_SQL = '';	
			SET p_SQL = CONCAT(p_SQL,'SELECT');
			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL_NUMERIC(xTable.ServiceNo) AS ServiceNo,							
							IFNULL_NUMERIC(xTable.IRIDNo) AS IRIDNo,
							IFNULL_NUMERIC(xTable.TAIDNo) AS TAIDNo,
							IFNULL_NUMERIC(xTable.ClientID) AS ClientID,
							IFNULL_NUMERIC(xTable.FEID) AS FEID,
							IFNULL_NUMERIC(xTable.MerchantID) AS MerchantID,
							IFNULL_NUMERIC(xTable.RegionID) AS RegionID,
							IFNULL_NUMERIC(xTable.RegionType) AS RegionType,
							IFNULL_STRING(xTable.RequestNo) AS RequestNo,
							IFNULL_STRING(xTable.ReferenceNo) AS ReferenceNo,							
							IFNULL_STRING(xTable.ServiceDateTime) AS ServiceDateTime,
							IFNULL_STRING(xTable.ServiceDate) AS ServiceDate,
							IFNULL_STRING(xTable.ServiceTime) AS ServiceTime,
							IFNULL_STRING(xTable.ServiceReqDate) AS ServiceReqDate,
							IFNULL_STRING(xTable.ServiceReqTime) AS ServiceReqTime,
							IFNULL_STRING(xTable.JobTypeDescription) AS JobTypeDescription,
							IFNULL_STRING(xTable.JobTypeStatusDescription) AS JobTypeStatusDescription,
							IFNULL_NUMERIC(xTable.ServiceStatus) AS ServiceStatus,
							IFNULL_STRING(xTable.ServiceStatusDescription) AS ServiceStatusDescription,
							IFNULL_STRING(xTable.IRNo) AS IRNo,
							IFNULL_STRING(xTable.Name) AS MerchantName,
							IFNULL_STRING(xTable.TID) AS TID,
							IFNULL_STRING(xTable.`MID`) AS `MID`,
							IFNULL_STRING(xTable.TerminalSN) AS TerminalSN,
							IFNULL_STRING(xTable.SIMSN) AS SIMSN,
							IFNULL_STRING(xTable.ReplaceTerminalSN) AS ReplaceTerminalSN,
							IFNULL_STRING(xTable.ReplaceSIMSN) AS ReplaceSIMSN,
							IFNULL_NUMERIC(xTable.FSRNo) AS FSRNo,
							IFNULL_STRING(xTable.FSRDate) AS FSRDate,
							IFNULL_STRING(xTable.FSRTime) AS FSRTime,
							IFNULL_STRING(xTable.TimeArrived) AS TimeArrived,
							IFNULL_STRING(xTable.TimeStart) AS TimeStart,
							IFNULL_STRING(xTable.TimeEnd) AS TimeEnd
							FROM
							(
							SELECT
							a.ServiceNo,							
							a.IRIDNo,
							a.TAIDNo,
							a.ClientID,
							a.FEID,
							a.MerchantID,
							a.RegionID,
							a.RegionType,
							a.RequestNo,
							a.ReferenceNo,
							a.ServiceDateTime,
							a.ServiceDate,
							a.ServiceTime,
							a.ServiceReqDate,
							a.ServiceReqTime,
							a.JobTypeDescription,
							a.JobTypeStatusDescription,
							a.ServiceStatus,
							a.ServiceStatusDescription,
							a.IRNo,
							d.Name,
							b.TID,
							b.`MID`,
							a.TerminalSN,
							a.SIMSerialNo AS SIMSN,
							a.ReplaceTerminalSN,
							a.ReplaceSIMSN,
							(CONCAT(IFNULL_STRING(a.IRNo), "^", 
							IFNULL_STRING(a.RequestNo), "^",
							IFNULL_STRING(a.ReferenceNo), "^", 
							IFNULL_STRING(a.JobTypeDescription), "^", 
							IFNULL_STRING(a.JobTypeStatusDescription), "^", 
							IFNULL_STRING(b.MerchantName), "^", 
							IFNULL_STRING(b.TID), "^", 
							IFNULL_STRING(b.MID), "^", 
							IFNULL_STRING(a.TerminalSN), "^", 
							IFNULL_STRING(a.SIMSerialNo))) AS sFields,
							a.isPrimary,
							c.FSRNo,
							IFNULL(DATE_FORMAT(c.FSRDate, "%m-%d-%Y"), "-") AS FSRDate,
							IFNULL(c.FSRTime, "-") AS FSRTime,
							IFNULL(c.TimeArrived, "-") AS TimeArrived,
							IFNULL(c.TimeStart, "-") AS TimeStart,
							IFNULL(c.TimeEnd, "-") AS TimeEnd
							FROM
							tblservicingdetail a
							LEFT JOIN tblirdetail AS b ON a.IRIDNo = b.IRIDNo
							LEFT JOIN tblfsrdetail AS c ON a.IRIDNo = c.IRIDNo AND a.TAIDNo = c.TAIDNo AND a.ServiceNo = c.ServiceNo
							LEFT JOIN tblparticular AS d ON a.MerchantID = d.ParticularID AND d.ParticularTypeID = 1
							) AS xTable');
							
			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('Before:p_SQL = ', p_SQL);
				
			IF (LENGTH(p_WHERE) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
			END IF;
			SET p_SQL = REPLACE(p_SQL, '"', "'");
			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT('After:p_SQL = ', p_SQL);	
				
			SET p_ORDERBY = '';
			SET p_ORDERBY = 'xTable.ServiceNo';
			
			IF (LENGTH(p_ORDERBY) > 0)
			THEN
				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
			END IF;
			
			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));
			#SELECT CONCAT(':p_SQL = ', p_SQL);
			
				
			SET @QUERY = p_SQL;
			# Execute Query 
			PREPARE QUERY FROM @QUERY;
			EXECUTE QUERY;	
						
		END IF;
		
    END IF;    
END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewSIMDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewSIMDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewSIMDetail`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(100) /* = NULL */ ,

	p_SearchValue VARCHAR(100) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_SIMID INTEGER;

	DECLARE v_SIMStatus INTEGER;

	DECLARE v_SIMSN VARCHAR(45);	

	DECLARE v_SIMCarrier VARCHAR(45);

	DECLARE v_Description VARCHAR(45);	

	DECLARE v_Location VARCHAR(45);

	DECLARE v_DateFrom VARCHAR(45);

	DECLARE v_DateTo VARCHAR(45);

	DECLARE v_LocationID INTEGER;

	DECLARE v_SearchString VARCHAR(255);



	DECLARE v_OffSetFrom INTEGER;

	DECLARE v_OffSetTo INTEGER;

	DECLARE v_OffSet INTEGER;

	

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'View')

    THEN

		IF (p_SearchBy = 'Inventory Detail')

		THEN

			SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);		

			SET v_SIMSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_SIMStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

			SET v_Location = TRIM(SPLIT_STRING(p_SearchValue, '|' ,5));

			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,6));

			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,7));

			

			SET p_WHERE = '';

			

			# SIMID		

			IF (v_SIMID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SIMID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;	



			# SIM SerialNo		

			IF (STRCMP(v_SIMSN, "0") != 0 && LENGTH(v_SIMSN) > 0 && STRCMP(v_SIMSN, "-") != 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMSN, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;	

			

			IF (STRCMP(v_SIMCarrier, "0") != 0 && LENGTH(v_SIMCarrier) > 0 && STRCMP(v_SIMCarrier, "-") != 0 && STRCMP(v_SIMCarrier, "[NOT SPECIFIED]") != 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Carrier = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMCarrier, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;

			

			IF (v_SIMStatus > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SIMStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;	

			

			IF (STRCMP(v_Location, "0") != 0 && LENGTH(v_Location) > 0 && STRCMP(v_Location, "-") != 0 && STRCMP(v_Location, "[NOT SPECIFIED]") != 0)

			THEN		

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.Description = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_Location, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	

			

			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.DeliveryDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			SET p_SQL = '';	
			SET p_SQL = CONCAT(p_SQL,'SELECT');
			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.SIMID, 0) AS SIMID,							
							IFNULL(a.SerialNo, "-") AS SerialNo,
							IFNULL(a.Carrier, "-") AS Carrier,
							IFNULL(a.SIMStatus, 0) AS SIMStatus,
							IFNULL(a.SIMStatusDescription, 0) AS SIMStatusDescription,
							IFNULL(a.DeliveryDate, "-") AS DeliveryDate,	
							IFNULL(a.ReleaseDate, "-") AS ReleaseDate,						
							IFNULL(b.Description, "-") AS Location,
							IFNULL(a.Allocation, "-") AS Allocation,							
							IFNULL(a.Remarks, "-") AS Remarks,							
							IFNULL(c.IRNo, "-") AS RequestID_,
							IFNULL(c.IRDate, "-") AS RequestDate_,
							IFNULL(c.InstallationDate, "-") AS InstallationDate_,
							IFNULL(c.TID, "-") AS TID_,
							IFNULL(c.MID, "-") AS MID_,
							IFNULL(d.Name, "-") AS MerchantName_,
							funcGetDesc("Search", "Region", d.RegionType) AS Region_,
							funcGetDesc("Search", "Region Detail", d.RegionID) AS Province_,
							funcGetDesc("Search", "SIM 1st Installation Date", CONCAT(c.ClientID,"|",1,"|",c.IRIDNo,"|",c.SIMID)) AS InstalledDate_						
							FROM tblsimdetail AS a
							LEFT JOIN tbllocation b ON a.LocationID = b.LocationID
							LEFT JOIN tblirdetail c ON a.SIMID = c.SIMID
						        LEFT JOIN tblparticular d ON c.MerchantID = d.ParticularID AND d.ParticularTypeID = 1');

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;



			SET p_SQL = REPLACE(p_SQL, '"', "'");			



			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.SIMStatusDescription';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);



			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Inventory Summary')

		THEN

			SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);					

			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			

			SET p_WHERE = '';

						

			IF (v_LocationID > 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.LocationID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_LocationID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	

			END IF;

			

			IF (STRCMP(v_SIMCarrier, "0") != 0 && LENGTH(v_SIMCarrier) > 0 && STRCMP(v_SIMCarrier, "-") != 0 && STRCMP(v_SIMCarrier, "[NOT SPECIFIED]") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Carrier = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMCarrier, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

											   

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.LocationID, 0) AS LocationID,							

							IFNULL(b.Description, "-") AS Location,

							IFNULL(a.TypeID, "-") AS TypeID,

							IFNULL(a.Carrier, "-") AS Carrier,

							IFNULL(SUM(a.TAvailable), 0) AS TAvailable,

							IFNULL(SUM(a.TInstalled), 0) AS TInstalled,

							IFNULL(SUM(a.TAllocated), 0) AS TAllocated,

							IFNULL(SUM(a.TDispatch), 0) AS TDispatch,

							IFNULL(SUM(a.TPullout), 0) AS TPullout,

							IFNULL(SUM(a.TBorrow), 0) AS TBorrow,

							IFNULL(SUM(a.TLost), 0) AS TLost,

							IFNULL(SUM(a.TDefective), 0) AS TDefective,

							IFNULL(SUM(a.TTotal), 0) AS TTotal						

							FROM tblsimsummary AS a

							LEFT JOIN tbllocation b ON a.LocationID = b.LocationID');





			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;



			SET p_SQL = REPLACE(p_SQL, '"', "'");			



			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_GROUPBY = '';

			SET p_GROUPBY = 'a.TypeID';



			IF (LENGTH(p_GROUPBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

			END IF;

				

			SET p_ORDERBY = '';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);	



			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Release Summary')

		THEN				

			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			

			SET p_WHERE = '';

			

			IF (LENGTH(v_SIMCarrier) > 0 && STRCMP(v_SIMCarrier, "[NOT SPECIFIED]") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Carrier = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SIMCarrier);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	

			END IF;

			

			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ReleaseDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			# Additional condition

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 AND LENGTH(a.ReleaseDate) > 0');			

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

											   

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'b.Description AS Location,

							IFNULL_FORMAT_DATE_WEEKDAY(a.ReleaseDate) AS ReleaseDate,

							a.Carrier AS Carrier,

							IFNULL_NUMERIC(COUNT(*)) AS TTotal

							FROM 

							tblsimdetail a

							LEFT JOIN tbllocation b ON a.LocationID = b.LocationID');





			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;



			SET p_SQL = REPLACE(p_SQL, '"', "'");			



			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_GROUPBY = '';

			SET p_GROUPBY = 'a.Carrier, a.ReleaseDate, b.Description';



			IF (LENGTH(p_GROUPBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

			END IF;

				

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.ReleaseDate';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);	



			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSEIF (p_SearchBy = 'Release Detail')

		THEN				

			SET v_SIMCarrier = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			

			SET p_WHERE = '';

			

			IF (LENGTH(v_SIMCarrier) > 0 && STRCMP(v_SIMCarrier, "[NOT SPECIFIED]") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Carrier = ');

				SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_SIMCarrier));

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	

			END IF;

			

			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ReleaseDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			# Additional condition

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 AND LENGTH(a.ReleaseDate) > 0');			

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

				

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

											   

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'b.Description AS Location,

							IFNULL_FORMAT_DATE_WEEKDAY(a.ReleaseDate) AS ReleaseDate,

							IFNULL_FORMAT_DATE_WEEKDAY(a.ReceiveDate) AS ReceiveDate,							

							a.SerialNo AS SIMSN,

							a.Carrier AS Carrier				

							FROM 

							tblsimdetail a

							LEFT JOIN tbllocation b ON a.LocationID = b.LocationID');





			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;



			SET p_SQL = REPLACE(p_SQL, '"', "'");			



			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_GROUPBY = '';

			#SET p_GROUPBY = 'a.Carrier, a.ReleaseDate';



			IF (LENGTH(p_GROUPBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

			END IF;

				

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.ReleaseDate';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);	



			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'Release Movement Master')

		THEN

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_SearchString = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

			SET v_OffSetFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);

			SET v_OffSetTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';

			

			IF (v_ID > 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TransNo = ');

				SET p_WHERE = CONCAT(p_WHERE, v_ID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	

			END IF;	

			

			IF ((LENGTH(v_SearchString > 0)) && (STRCMP(v_SearchString, "0") != 0))

			THEN

				# RequestNo			

				SET p_WHERE = CONCAT(p_WHERE, ' ', '(', 'a.RequestNo LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');

				

				# ReferenceNo			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ReferenceNo LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');

				

				# Remarks			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.Remarks LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'OR');

				

				# ProcessedBy			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ProcessedBy LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_SearchString, "%'", ')');	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_DateFrom, "0000-00-00") != 0 && STRCMP(v_DateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TransDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_DateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_DateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

											   

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'a.TransNo,

							a.TransDate,

							a.TransTime,

							a.ReleaseDate,

							a.RequestNo,

							a.ReferenceNo,

							a.Remarks,

							a.ProcessedBy,

							a.ProcessedDateTime,

							a.ModifiedBy,

							a.ModifiedDateTime,

							a.UserID,

							a.FromLocationID,

							(SELECT xTable.Description FROM tbllocation xTable WHERE xTable.LocationID = a.FromLocationID) AS FromLocation,

							a.ToLocationID,

							(SELECT xTable.Description FROM tbllocation xTable WHERE xTable.LocationID = a.ToLocationID) AS ToLocation

							FROM

							tblsimmovementmaster a');



			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;



			SET p_SQL = REPLACE(p_SQL, '"', "'");			



			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_GROUPBY = '';

			IF (LENGTH(p_GROUPBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

			END IF;

				

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.TransNo';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);

			

			IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))

			THEN	

				SET v_OffSet = 0;

				

				IF (v_OffSetFrom = 1)

				THEN

					SET v_OffSet = 0;

				ELSE

					SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;

				END IF;

				

				SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');

				SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);

			END IF;	

			

			#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Final p_SQL = ', p_SQL);



			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'Service History')

		THEN	

			SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT

			a.SIMID,

			a.StatusDescription as ServiceStatusDescription,

			a.OperationDescription,

			IFNULL_STRING_ONLY((SELECT `TID` FROM tblirdetail xTable WHERE xTable.IRNo = a.IRNo)) AS `TID`,

			IFNULL_STRING_ONLY((SELECT `MID` FROM tblirdetail xTable WHERE xTable.IRNo = a.IRNo)) AS `MID`,

			IFNULL_STRING_ONLY((SELECT `Name` FROM tblparticular xTable WHERE xTable.ParticularID = a.ParticularID)) AS ParticularName,

			Remarks,

			a.`Date`,

			a.`Time`,

			a.ProcessedBy,

			a.ProcessedDateTime,

			IFNULL_STRING_ONLY((SELECT IRNo FROM tblservicingdetail xTable WHERE xTable.ServiceNo = a.ServiceNo)) AS IRNo

			FROM

			tblsimactivity a

			WHERE a.SIMID = v_ID

			ORDER BY a.RecID;

		

		END IF; 

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'SIM Detail')

		THEN

			SET v_SIMID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);		

			SET v_SIMSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));



			SET p_WHERE = '';

			

			# SIMID		

			IF (v_SIMID > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SIMID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SIMID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');		

			END IF;	



			# SIM SerialNo		

			IF (STRCMP(v_SIMSN, "0") != 0 && LENGTH(v_SIMSN) > 0)

			THEN	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SIMSN, "'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;	



			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE



			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.SIMID, 0) AS SIMID,							

							IFNULL(a.SerialNo, "-") AS SIMSerialNo,

							IFNULL(a.Carrier, "-") AS SIMCarrier,

							IFNULL(a.SIMStatus, 0) AS SIMStatus,

							IFNULL(a.SIMStatusDescription, 0) AS SIMStatusDescription

							FROM tblsimdetail AS a');





			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;



			SET p_SQL = REPLACE(p_SQL, '"', "'");			



			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);



			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

		END IF;   	    	

    END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewStatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewStatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewStatus`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT StatusID, Description

		FROM   tblstatus

		ORDER BY Description;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						StatusID,

						Description

			FROM        tblstatus

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'StatusID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						StatusID,

						Description

			FROM        tblstatus

			WHERE       (StatusID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewSystem` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewSystem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewSystem`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;
	DECLARE v_Name VARCHAR(45);
    

    IF (p_StatementType = 'View')
	THEN
		IF (p_SearchBy = 'Publish')
		THEN
			SET v_Name = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));
			
			SELECT 
			SysID, 
			PublishDate, 
			PublishVersion
			FROM   
			tblsystem
			WHERe 
			AppsName = v_Name;           

		END IF;	

    END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewTerminalBrand` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewTerminalBrand` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewTerminalBrand`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		SELECT TerminalBrandID, Description

		FROM   tblterminalbrand

		ORDER BY Description;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						TerminalBrandID,

						Description

			FROM        tblterminalbrand

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'TerminalBrandID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						TerminalBrandID,

						Description

			FROM        tblterminalbrand

			WHERE       (TerminalBrandID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewTerminalDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewTerminalDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewTerminalDetail`(  
   p_StatementType VARCHAR(30) /* = NULL */ ,
p_SearchBy VARCHAR(100) /* = NULL */ ,
p_SearchValue VARCHAR(100) /* = NULL */ )
BEGIN
DECLARE v_ID INTEGER;
DECLARE v_TerminalID INTEGER;
DECLARE v_TerminalStatus INTEGER;
DECLARE v_TerminalSN VARCHAR(45);	
DECLARE v_Description VARCHAR(45);	
DECLARE v_TerminalTypeID INTEGER;
DECLARE v_TerminalModelID INTEGER;
DECLARE v_TerminalBrandID INTEGER;
DECLARE v_LocationID INTEGER;
DECLARE v_Location VARCHAR(45);
DECLARE v_AssetType VARCHAR(45);
DECLARE v_DateFrom VARCHAR(45);
DECLARE v_DateTo VARCHAR(45);
DECLARE v_SearchString VARCHAR(255);
DECLARE v_ClientID INTEGER;

DECLARE v_OffSetFrom INTEGER;
DECLARE v_OffSetTo INTEGER;
DECLARE v_OffSet INTEGER;
DECLARE p_WHERE LONGTEXT;
DECLARE p_GROUPBY LONGTEXT;
DECLARE p_ORDERBY LONGTEXT;
DECLARE p_SQL LONGTEXT;
   
   IF (p_StatementType = 'View')
   THEN
	IF (p_SearchBy = 'Inventory Detail')
	THEN
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);		
		SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);	
