		END IF;
			
		SET p_ORDERBY = '';
		SET p_ORDERBY = 'a.TransNo';
		
		IF (LENGTH(p_ORDERBY) > 0)
		THEN
			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
		END IF;
		
		#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));
		#SELECT CONCAT('Final p_SQL = ', p_SQL);
		
		IF ((v_OffSetFrom > 0) AND (v_OffSetTo > 0))
		THEN	
			SET v_OffSet = 0;
			
			IF (v_OffSetFrom = 1)
			THEN
				SET v_OffSet = 0;
			ELSE
				SET v_OffSet = (v_OffSetFrom * v_OffSetTo) - v_OffSetTo;
			END IF;
			
			SET p_SQL = CONCAT(p_SQL, ' ', 'LIMIT');
			SET p_SQL = CONCAT(p_SQL, ' ', v_OffSet, ",", v_OffSetTo);
		END IF;	
		
		#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));
		#SELECT CONCAT('Final p_SQL = ', p_SQL);	
		SET @QUERY = p_SQL;
		# Execute Query 
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
					
	ELSEIF (p_SearchBy = 'Service History')
	THEN
		SET v_ID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);
		
		SELECT
		a.TerminalID,
		a.StatusDescription as ServiceStatusDescription,
		a.OperationDescription,
		IFNULL_STRING_ONLY((SELECT `TID` FROM tblirdetail xTable WHERE xTable.IRNo = a.IRNo LIMIT 1)) AS `TID`,
		IFNULL_STRING_ONLY((SELECT `MID` FROM tblirdetail xTable WHERE xTable.IRNo = a.IRNo LIMIT 1)) AS `MID`,
		IFNULL_STRING_ONLY((SELECT `Name` FROM tblparticular xTable WHERE xTable.ParticularID = a.ParticularID LIMIT 1)) AS ParticularName,
		Remarks,
		a.`Date`,
		a.`Time`,
		a.ProcessedBy,
		a.ProcessedDateTime,
		IFNULL_STRING_ONLY((SELECT IRNo FROM tblservicingdetail xTable WHERE xTable.ServiceNo = a.ServiceNo)) AS IRNo
		FROM
		tblterminalactivity a
		WHERE a.TerminalID = v_ID
		ORDER BY a.RecID;
		
	ELSEIF (p_SearchBy = 'Inventory Terminal Summary')
	THEN
		SET v_LocationID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);					
		SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);	
		SET v_TerminalModelID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INTEGER);
		SET v_ClientID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);
		
		SET p_WHERE = '';
					
		IF (v_LocationID > 0)
		THEN			
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.LocationID = ');
			SET p_WHERE = CONCAT(p_WHERE, v_LocationID);
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
		END IF;
		
		IF (v_TerminalTypeID > 0)
		THEN			
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalTypeID = ');
			SET p_WHERE = CONCAT(p_WHERE, v_TerminalTypeID);
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
		END IF;
		
		IF (v_TerminalModelID > 0)
		THEN			
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalModelID = ');
			SET p_WHERE = CONCAT(p_WHERE, v_TerminalModelID);
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
		END IF;
		
		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
										   
		SET p_SQL = '';	
		SET p_SQL = CONCAT(p_SQL,'SELECT');
		SET p_SQL = CONCAT(p_SQL, ' ', '
						"0" AS LocationID,
						"-" AS Location,
						IFNULL(a.TerminalTypeID, "-") AS TerminalTypeID,
						IFNULL(a.TerminalType, "-") AS TerminalType,
						IFNULL(a.TerminalModelID, "-") AS TerminalModelID,
						IFNULL(a.TerminalModel, "-") AS TerminalModel,
						IFNULL(SUM(a.TAvailable), 0) AS TAvailable,
						IFNULL(SUM(a.TInstalled), 0) AS TInstalled,
						IFNULL(SUM(a.TAllocated), 0) AS TAllocated,
						IFNULL(SUM(a.TDispatch), 0) AS TDispatch,
						IFNULL(SUM(a.TPullout), 0) AS TPullout,
						IFNULL(SUM(a.TBorrow), 0) AS TBorrow,
						IFNULL(SUM(a.TLost), 0) AS TLost,
						IFNULL(SUM(a.TDefective), 0) AS TDefective,
						IFNULL(SUM(a.TTotal), 0) AS TTotal						
						FROM tblterminalsummary AS a');
		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
		#SELECT CONCAT('Before:p_SQL = ', p_SQL);
					
		IF (LENGTH(p_WHERE) > 0)
		THEN
			SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
			SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
		END IF;
		SET p_SQL = REPLACE(p_SQL, '"', "'");			
		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));
		#SELECT CONCAT('After:p_SQL = ', p_SQL);
		
		SET p_GROUPBY = '';
		SET p_GROUPBY = 'a.TerminalTypeID, a.TerminalModelID';
		IF (LENGTH(p_GROUPBY) > 0)
		THEN
			SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');
			SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);
		END IF;
			
		SET p_ORDERBY = '';
		
		IF (LENGTH(p_ORDERBY) > 0)
		THEN
			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');
			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);
		END IF;
		
		#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));
		#SELECT CONCAT('Final p_SQL = ', p_SQL);	
		SET @QUERY = p_SQL;
		# Execute Query 
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
		
	END IF;
   ELSEIF (p_StatementType = 'Search')
   THEN
	IF (p_SearchBy = 'Terminal Detail')
	THEN
		SET v_TerminalID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);		
		SET v_TerminalSN = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));
		SET p_WHERE = '';
		
		# TerminalID
		IF (v_TerminalID > 0)
		THEN			
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalID = ');
			SET p_WHERE = CONCAT(p_WHERE, v_TerminalID);
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	
		END IF;		
		# Terminal SerialNo	
		IF (STRCMP(v_TerminalSN, "0") != 0 && LENGTH(v_TerminalSN) > 0)
		THEN		
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SerialNo = ');
			SET p_WHERE = CONCAT(p_WHERE, "'", v_TerminalSN, "'");	
			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');
		END IF;				
		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE
		SET p_SQL = '';	
		SET p_SQL = CONCAT(p_SQL,'SELECT');
		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TerminalID, 0) AS TerminalID,							
						IFNULL(a.SerialNo, "-") AS SerialNo,
						IFNULL(a.TerminalTypeID, "-") AS TerminalTypeID,
						IFNULL(a.TerminalModelID, "-") AS TerminalModelID,
						IFNULL(a.TerminalBrandID, "-") AS TerminalBrandID,
						IFNULL(b.Description, "-") AS TerminalType,
						IFNULL(c.Description, "-") AS TerminalModel,
						IFNULL(d.Description, "-") AS TerminalBrand,
						IFNULL(a.TerminalStatus, 0) AS TerminalStatus,
						IFNULL(a.TerminalStatusDescription, 0) AS TerminalStatusDescription
						FROM tblterminaldetail AS a
						LEFT JOIN tblterminaltype AS b ON a.TerminalTypeID = b.TerminalTypeID
						LEFT JOIN tblterminalmodel AS c ON a.TerminalModelID = c.TerminalModelID
						LEFT JOIN tblterminalbrand AS d ON a.TerminalBrandID = d.TerminalBrandID');
		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));
		#SELECT CONCAT('Before:p_SQL = ', p_SQL);
					
		IF (LENGTH(p_WHERE) > 0)
		THEN
			SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');
			SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);
		END IF;
		SET p_SQL = REPLACE(p_SQL, '"', "'");			
		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));
		#SELECT CONCAT('After:p_SQL = ', p_SQL);
		SET @QUERY = p_SQL;
		# Execute Query 
		PREPARE QUERY FROM @QUERY;
		EXECUTE QUERY;
		
	END IF;   	   
   END IF;    
   END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewTerminalModel` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewTerminalModel` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewTerminalModel`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_TerminalTypeID INT;

	DECLARE v_TerminalModelID INT;

	DECLARE v_TerminalStatus INT;

	DECLARE v_TerminalDescription VARCHAR(45);

	DECLARE p_SQL LONGTEXT;	

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'For Dashboard')

		THEN		

			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_TerminalDescription = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			

			IF (v_TerminalDescription = 'MP200')

			THEN				

				SET p_SQL = '';	

				SET p_SQL = CONCAT(p_SQL,'SELECT');

				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TerminalModelID, 0) AS TerminalModelID, 

								IFNULL(a.Description, "-") AS Description,

								IFNULL((SELECT IFNULL(COUNT(*), 0)

								FROM tblterminalmodel a1

								LEFT JOIN tblterminaldetail AS b1 ON a1.TerminalModelID = b1.TerminalModelID

								WHERE b1.TerminalTypeID = ', v_TerminalTypeID, ' ', 'AND a1.TerminalModelID = a.TerminalModelID GROUP BY a1.TerminalModelID), 0) AS TOriginalStock

								FROM   tblterminalmodel a

								LEFT JOIN tblterminaldetail AS b ON a.TerminalModelID = b.TerminalModelID

								WHERE a.Description IN("MOBILE") AND a.TerminalModelID = b.TerminalModelID

								GROUP BY a.TerminalModelID

								ORDER BY a.Description');

								

				SET p_SQL = REPLACE(p_SQL, '"', "'");

				SET @QUERY = p_SQL;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;				

				

			ELSEIF (v_TerminalDescription = 'V3 NT' OR v_TerminalDescription = 'V3 TOUCH' OR v_TerminalDescription = 'V5S')

			THEN

				SET p_SQL = '';	

				SET p_SQL = CONCAT(p_SQL,'SELECT');

				SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TerminalModelID, 0) AS TerminalModelID, 

								IFNULL(a.Description, "-") AS Description,

								IFNULL((SELECT IFNULL(COUNT(*), 0)

								FROM tblterminalmodel a1

								LEFT JOIN tblterminaldetail AS b1 ON a1.TerminalModelID = b1.TerminalModelID

								WHERE b1.TerminalTypeID = ', v_TerminalTypeID, ' ', 'AND a1.TerminalModelID = a.TerminalModelID GROUP BY a1.TerminalModelID), 0) AS TOriginalStock

								FROM   tblterminalmodel a

								LEFT JOIN tblterminaldetail AS b ON a.TerminalModelID = b.TerminalModelID

								WHERE a.Description IN("DESKTOP", "MOBILE") AND a.TerminalModelID = b.TerminalModelID

								GROUP BY a.TerminalModelID

								ORDER BY a.Description');				

								

				SET p_SQL = REPLACE(p_SQL, '"', "'");

				SET @QUERY = p_SQL;

				

				# Execute Query 

				PREPARE QUERY FROM @QUERY;

				EXECUTE QUERY;				

			END IF;

			

		ELSEIF (p_SearchBy = 'Terminal Model By Terminal Type')

		THEN			

			SET v_TerminalTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);

			

			SELECT 

			b.TerminalModelID AS TerminalModelID, 

			b.Description AS Description, 

			a.TerminalTypeID AS TerminalTypeID, 

			a.Description AS TerminalTypeDescription

			FROM

			tblterminaltype a

			LEFT JOIN tblterminalmodel AS b ON b.TerminalTypeID = a.TerminalTypeID

			WHERE b.isActive > 0 AND a.TerminalTypeID = v_TerminalTypeID

			ORDER BY b.Description;

		ELSE			

			SELECT b.TerminalModelID AS TerminalModelID, 

			b.Description AS Description, 

			a.TerminalTypeID AS TerminalTypeID, 

			a.Description AS TerminalTypeDescription

			FROM

			tblterminaltype a

			LEFT JOIN tblterminalmodel AS b ON b.TerminalTypeID = a.TerminalTypeID

			ORDER BY b.Description;

		END IF;

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						TerminalModelID,

						Description

			FROM        tblterminalmodel

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'TerminalModelID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						TerminalModelID,

						Description

			FROM        tblterminalmodel

			WHERE       (TerminalModelID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewTerminalStatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewTerminalStatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewTerminalStatus`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(255) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_Description VARCHAR(45);

	DECLARE v_TerminalStatusType INTEGER;

	DECLARE v_isStatus INTEGER;

	DECLARE v_isFSR INTEGER;

	DECLARE v_JobType VARCHAR(45);

	DECLARE v_ServiceResult VARCHAR(45);

	DECLARE v_isCurrent INTEGER;

	DECLARE v_ReportID INTEGER;

	

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Total')

		THEN

			SELECT TerminalStatusID, Description, TerminalStatusType

			FROM   tblterminalstatus

			WHERE (ShowInTotal > 0)

			ORDER BY SequenceDisplay;

		

		ELSEIF (p_SearchBy = 'Description')

		THEN

			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			

			SELECT TerminalStatusID, Description, TerminalStatusType

			FROM   tblterminalstatus

			WHERE Description = v_Description;

			

		ELSEIF (p_SearchBy = 'Status List')

		THEN

			SET v_TerminalStatusType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_isStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

		

			SET p_WHERE = '';			

			IF (v_TerminalStatusType > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalStatusType = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalStatusType);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_isStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_isStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_Description, "0") != 0)

			THEN				

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.`Description` LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_Description, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TerminalStatusID, 0) AS TerminalStatusID,							

							IFNULL(a.Description, "-") AS `Description`,

							IFNULL(a.TerminalStatusType, 0) AS TerminalStatusType															

							FROM tblterminalstatus AS a');

			

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.SequenceDisplay';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'Status List For FSR')

		THEN

			SET v_TerminalStatusType = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_isStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			SET v_Description = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_isFSR = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS UNSIGNED INTEGER);

		

			SET p_WHERE = '';			

			IF (v_TerminalStatusType > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TerminalStatusType = ');

				SET p_WHERE = CONCAT(p_WHERE, v_TerminalStatusType);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_isStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_isStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_isFSR > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isFSR = ');

				SET p_WHERE = CONCAT(p_WHERE, v_isFSR);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_Description, "0") != 0)

			THEN				

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.`Description` LIKE ');

				SET p_WHERE = CONCAT(p_WHERE, "'%", v_Description, "%'");	

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');			

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TerminalStatusID, 0) AS TerminalStatusID,							

							IFNULL(a.Description, "-") AS `Description`,

							IFNULL(a.TerminalStatusType, 0) AS TerminalStatusType															

							FROM tblterminalstatus AS a');

			

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.SequenceDisplay';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'Status List For Service')

		THEN

			# filter for isService

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isService > 0 ');

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TerminalStatusID, 0) AS TerminalStatusID,							

							IFNULL(a.Description, "-") AS `Description`,

							IFNULL(a.TerminalStatusType, 0) AS TerminalStatusType															

							FROM tblterminalstatus AS a');

			

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

						

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");			

			

			#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.SequenceDisplay';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'FSR SN Status By Job Type')

		THEN	

			SET v_JobType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			SET v_ServiceResult = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_isCurrent = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			

			IF (STRCMP(v_JobType, "SVC REQ PULL-OUT") = 0)

			THEN

				IF (STRCMP(v_ServiceResult, "SUCCESS") = 0)

				THEN

					SELECT

					TerminalStatusID,

					`Description`,

					TerminalStatusType

					FROM

					tblterminalstatus

					WHERE `Description` in('AVAILABLE', 'DEFECTIVE', 'LOST')

					ORDER BY

					SequenceDisplay;

					

				ELSEIF (STRCMP(v_ServiceResult, "NEGATIVE") = 0)

				THEN

					SELECT

					TerminalStatusID,

					`Description`,

					TerminalStatusType

					FROM

					tblterminalstatus

					WHERE `Description` IN('INSTALLED')

					ORDER BY

					SequenceDisplay;	

				END IF;

				

			ELSEIF (STRCMP(v_JobType, "SVC REQ INSTALLATION") = 0)

			THEN

				IF (STRCMP(v_ServiceResult, "SUCCESS") = 0)

				THEN

					SELECT

					TerminalStatusID,

					`Description`,

					TerminalStatusType

					FROM

					tblterminalstatus

					WHERE `Description` IN('INSTALLED')

					ORDER BY

					SequenceDisplay;

					

				ELSEIF (STRCMP(v_ServiceResult, "NEGATIVE") = 0)

				THEN

					SELECT

					TerminalStatusID,

					`Description`,

					TerminalStatusType

					FROM

					tblterminalstatus

					WHERE `Description` IN('AVAILABLE', 'ALLOCATED', 'DEFECTIVE', 'LOST')

					ORDER BY

					SequenceDisplay;	

				END IF;

			

			ELSEIF (STRCMP(v_JobType, "SVC REQ SERVICING") = 0 OR STRCMP(v_JobType, "SVC REQ REPROGRAMMING") = 0)

			THEN

					SELECT

					TerminalStatusID,

					`Description`,

					TerminalStatusType

					FROM

					tblterminalstatus

					WHERE `Description` IN('INSTALLED')

					ORDER BY

					SequenceDisplay;

					

				

			ELSEIF (STRCMP(v_JobType, "SVC REQ REPLACEMENT") = 0)

			THEN

				IF (v_isCurrent > 0) #For current terminal status

				THEN

					IF (STRCMP(v_ServiceResult, "SUCCESS") = 0)

					THEN												

						SELECT

						TerminalStatusID,

						`Description`,

						TerminalStatusType

						FROM

						tblterminalstatus

						WHERE `Description` IN('AVAILABLE', 'DEFECTIVE', 'LOST', 'INSTALLED')

						ORDER BY

						SequenceDisplay;

					ELSEIF (STRCMP(v_ServiceResult, "NEGATIVE") = 0)

					THEN

						SELECT

						TerminalStatusID,

						`Description`,

						TerminalStatusType

						FROM

						tblterminalstatus

						WHERE `Description` IN('INSTALLED')

						ORDER BY

						SequenceDisplay;	

					END IF;

				ELSE # For replace terminal status

					IF (STRCMP(v_ServiceResult, "SUCCESS") = 0)

					THEN												

						SELECT

						TerminalStatusID,

						`Description`,

						TerminalStatusType

						FROM

						tblterminalstatus























































						# Rocky - Issue Fix For Status of Replacement. added new Status







						WHERE `Description` IN('AVAILABLE', 'DEFECTIVE', 'LOST', 'INSTALLED')

						ORDER BY

						SequenceDisplay;

						

					ELSEIF (STRCMP(v_ServiceResult, "NEGATIVE") = 0)

					THEN

						SELECT

						TerminalStatusID,

						`Description`,

						TerminalStatusType

						FROM

						tblterminalstatus

						WHERE `Description` IN('AVAILABLE', 'ALLOCATED', 'DEFECTIVE', 'LOST', 'INSTALLED')

						ORDER BY

						SequenceDisplay;

							

					END IF;				

				END IF;

				

			END IF;

			

		ELSEIF (p_SearchBy = 'Status By Report ID')

		THEN

			SET v_ReportID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);	

			

			IF (v_ReportID = 1) #TERMINAL DETAIL INVENTORY REPORT

			THEN

				SELECT

				TerminalStatusID,

				`Description`,

				TerminalStatusType

				FROM

				tblterminalstatus

				WHERE `Description` IN('AVAILABLE', 'ALLOCATED', 'DEFECTIVE', 'LOST', 'LOAN/BORROW', 'INSTALLED', 'DISPATCH')

				ORDER BY

				SequenceDisplay;

			ELSEIF (v_ReportID = 3) #SIM DETAIL INVENTORY REPORT

			THEN

				SELECT

				TerminalStatusID,

				`Description`,

				TerminalStatusType

				FROM

				tblterminalstatus

				WHERE `Description` IN('AVAILABLE', 'ALLOCATED', 'DEFECTIVE', 'LOST', 'LOAN/BORROW', 'INSTALLED', 'DISPATCH')

				ORDER BY

				SequenceDisplay;

			ELSEIF (v_ReportID = 9) #INSTALLATION REQUEST REPORT

			THEN

				SELECT

				TerminalStatusID,

				`Description`,

				TerminalStatusType

				FROM

				tblterminalstatus

				WHERE `Description` IN('AVAILABLE', 'ALLOCATED', 'INSTALLED', 'DISPATCH')

				ORDER BY

				SequenceDisplay;

			ELSEIF (v_ReportID = 18) #CLIENT SERVICING REPORT

			THEN

				SELECT

				TerminalStatusID,

				`Description`,

				TerminalStatusType

				FROM

				tblterminalstatus

				WHERE `Description` IN('INSTALLED')

				ORDER BY

				SequenceDisplay;

			ELSEIF (v_ReportID = 19) #TERMINAL SUMMARY INVENTORY REPORT

			THEN

				SELECT

				TerminalStatusID,

				`Description`,

				TerminalStatusType

				FROM

				tblterminalstatus

				WHERE `Description` IN('AVAILABLE', 'ALLOCATED', 'DEFECTIVE', 'LOST', 'LOAN/BORROW', 'INSTALLED', 'DISPATCH')

				ORDER BY

				SequenceDisplay;

			ELSEIF (v_ReportID = 20) #SIM SUMMARY INVENTORY REPORT

			THEN

				SELECT

				TerminalStatusID,

				`Description`,

				TerminalStatusType

				FROM

				tblterminalstatus

				WHERE `Description` IN('AVAILABLE', 'ALLOCATED', 'DEFECTIVE', 'LOST', 'LOAN/BORROW', 'INSTALLED', 'DISPATCH')

				ORDER BY

				SequenceDisplay;

			END IF;		

		

		ELSEIF (p_SearchBy = 'Enrollment')

		THEN

			SELECT 

			IFNULL(TerminalStatusID, 0) AS TerminalStatusID, 

			IFNULL(Description, "-") AS Description, 

			IFNULL(TerminalStatusType, 0) AS TerminalStatusType

			FROM   tblterminalstatus			

			ORDER BY SequenceDisplay;								

		ELSE

			SELECT TerminalStatusID, Description, TerminalStatusType

			FROM   tblterminalstatus

			WHERE Description IN('AVAILABLE', 'ALLOCATED', 'FOR REPAIR', 'DEFECTIVE', 'LOSS', 'LOAN/BORROW', 'INSTALLED', 'DISPATCH')

			ORDER BY SequenceDisplay;

		END IF;	

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

		THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						TerminalStatusID,

						Description,

						TerminalStatusType

			FROM        tblterminalstatus

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'StatusID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						TerminalStatusID,

						Description,

						TerminalStatusType

			FROM        tblterminalstatus

			WHERE       (TerminalStatusID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewTerminalType` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewTerminalType` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewTerminalType`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'ForDashboard')

		THEN

			SELECT 

			IFNULL(a.TypeDescription, "-") AS TypeDescription,

			IFNULL(a.ModelDescription, "-") AS ModelDescription,

			IFNULL(a.TOriginalStock, 0) AS TOriginalStock,

			IFNULL(a.TAvailableStock, 0) AS TAvailableStock,

			IFNULL(a.TInstalled, 0) AS TInstalled,

			IFNULL(a.TAllocated, 0) AS TAllocated,

			IFNULL(a.TDispatch, 0) AS TDispatch,

			IFNULL(a.TRepair, 0) AS TRepair,

			IFNULL(a.TLoanBorrow, 0) AS TLoanBorrow,

			IFNULL(a.TDefective, 0) AS TDefective,

			IFNULL(a.TNegative, 0) AS TNegative,

			IFNULL(a.TLastMonthInstalled, 0) AS TLastMonthInstalled,

			IFNULL(a.TThisMonthInstalled, 0) AS TThisMonthInstalled

			FROM   

			tbldashboardterminal a			

			ORDER BY a.TypeDescription;

		ELSEIF (p_SearchBy = 'Terminal Base')
		THEN
			SELECT TerminalTypeID, Description
			FROM   tblterminaltype
			WHERE 
			(isActive > 0)
			AND (`Type` in  (2, 3, 4))
			ORDER BY Description;
		ELSE

			SELECT TerminalTypeID, Description

			FROM   tblterminaltype

			WHERE (isActive > 0)

			ORDER BY Description;

		END IF;	

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Description')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						TerminalTypeID,

						Description

			FROM        tblterminaltype

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'TerminalTypeID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						TerminalTypeID,

						Description

			FROM        tblterminaltype

			WHERE       (TerminalTypeID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewTimeSheet` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewTimeSheet` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewTimeSheet`(  



    p_StatementType VARCHAR(30) /* = NULL */ ,



	p_SearchBy VARCHAR(50) /* = NULL */ ,



	p_SearchValue VARCHAR(50) /* = NULL */



)
BEGIN







DECLARE v_ID INTEGER;



DECLARE v_ParticularID INT;



DECLARE v_DepartmentID INT;



DECLARE v_PositionID INT;



DECLARE v_DateFrom DATE;



DECLARE v_DateTo DATE;



DECLARE v_TerminalID VARCHAR(10);



DECLARE v_MissingTimeSheet INT;



DECLARE v_TTime INT;



DECLARE v_CountryID INT;



DECLARE v_OrderType INT;







DECLARE p_WHERE LONGTEXT;



DECLARE p_GROUPBY LONGTEXT;



DECLARE p_ORDERBY LONGTEXT;



DECLARE p_SQL LONGTEXT;







IF (p_StatementType = 'View')



THEN



	IF (p_SearchBy = 'TimeSheet')



	THEN



		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);



		SET v_TerminalID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));



		SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INT);



		SET v_DateFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS DATE);



		SET v_DateTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS DATE);



		SET v_MissingTimeSheet = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INT);







		SET p_WHERE = '';



		IF (v_ParticularID > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');



			SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		IF (STRCMP(v_TerminalID, "0") != 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TSTerminalIDList LIKE ');



			SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalID, "%'");



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		IF (v_DepartmentID > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.DepartmentID = ');



			SET p_WHERE = CONCAT(p_WHERE, v_DepartmentID);



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		SET v_OrderType = 0;



		IF (v_MissingTimeSheet > 0)



		THEN



			IF (v_MissingTimeSheet = 98)



			THEN



				SET v_OrderType = 1;



			ELSE



				SET v_TTime = 8;



				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TTime < ');



				SET p_WHERE = CONCAT(p_WHERE, v_TTime);



				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');







				# Work Type / Leave Type



				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.WorkTypeID = 0');			



				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');	







			END IF;



							



			



		END IF;



		



		IF (v_OrderType > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', "a.TimeIn != '00:00:00' OR a.TimeOut != '00:00:00'");



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



			



		END IF;



		



		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE



		#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));



		#SELECT CONCAT('p_WHERE = ', p_WHERE);



			



		SET p_SQL = '';	



		SET p_SQL = CONCAT(p_SQL,'SELECT');



		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TSID, 0) AS TimeSheetID,



					IFNULL(a.ParticularID, 0) AS ParticularID,							



					IFNULL(a.FullName, "-") AS FullName,



					IFNULL(d.Code, "-") AS `Code`,



					IFNULL(a.TSID, 0) AS TSID,



					IFNULL(a.TSDate, "-") AS OrderByDate,



					UPPER(IFNULL(DATE_FORMAT(a.TSDate, "%a, %b. %e, %Y"), "-"))AS TSDate,



					(IF(a.TimeIn = "00:00:00", "-", DATE_FORMAT(a.TimeIn, "%h:%i %p"))) AS TimeIn,



					(IF(a.TimeOut = "00:00:00", "-", DATE_FORMAT(a.TimeOut, "%h:%i %p"))) AS TimeOut,



					IFNULL(a.THours, "-") AS THours,



					IFNULL(a.TTime, 0) AS TTime,



					IFNULL(a.TimeStatus, "-") AS TimeStatus,



					IFNULL(a.Holiday, 0) AS Holiday,



					IFNULL(a.PositionID, 0) AS PositionID,



					IFNULL(c.Description, "-") AS Position,



					IFNULL(b.Description, "-") AS Department,



					IFNULL(b.DepartmentID, 0) AS DepartmentID,



					IFNULL(a.WorkTypeID, 0) AS WorkTypeID,



					IFNULL(a.WorkType, "-") AS WorkType,



					IFNULL(d.EmploymentStatus, "-") AS EmploymentStatus,



					IFNULL(a.DeviceIn, "-") AS DeviceIn,



					IFNULL(a.DeviceOut, "-") AS DeviceOut,



					IFNULL(a.ProcessedBy, "-") AS ProcessedBy,

					

					IFNULL_FORMAT_DATETIME_AMPM(a.ProcessedDateTime) AS ProcessedDateTime



					FROM tbltimesheetdetailtemp AS a



					LEFT JOIN tbldepartment AS b ON a.DepartmentID = b.DepartmentID



					LEFT JOIN tblposition AS c ON a.PositionID = c.PositionID



					LEFT JOIN tblparticular AS d ON a.ParticularID = d.ParticularID');







		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('Before:p_SQL = ', p_SQL);



				



		IF (LENGTH(p_WHERE) > 0)



		THEN



		SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');



		SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);



		END IF;



		SET p_SQL = REPLACE(p_SQL, '"', "'");			







		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('After:p_SQL = ', p_SQL);







		SET p_ORDERBY = '';



		



		IF (v_OrderType > 0)



		THEN



			SET p_ORDERBY = 'a.TimeSheetID DESC';



		ELSE



			SET p_ORDERBY = 'a.TSDate, a.FullName';



		END IF;







		IF (LENGTH(p_ORDERBY) > 0)



		THEN



			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');



			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);



		END IF;







		#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('Final p_SQL = ', p_SQL);







		SET @QUERY = p_SQL;



		# Execute Query 



		PREPARE QUERY FROM @QUERY;



		EXECUTE QUERY;



		



	ELSEIF (p_SearchBy = 'TimeSheet Log')



	THEN



		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);



		SET v_DateFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS DATE);







		SET p_WHERE = '';



		IF (v_ParticularID > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');



			SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		IF (LENGTH(v_DateFrom) > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.`Date` = ');



			SET p_WHERE = CONCAT(p_WHERE, ADD_SINGLEQUOTE(v_DateFrom));



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE



		#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));



		#SELECT CONCAT('p_WHERE = ', p_WHERE);



			



		SET p_SQL = '';	



		SET p_SQL = CONCAT(p_SQL,'SELECT');



		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TimeSheetID, 0) AS TimeSheetID,



						IFNULL(a.ParticularID, 0) AS ParticularID,



						UPPER(IFNULL(DATE_FORMAT(a.`Date`, "%a, %b. %e, %Y"), "-"))AS TimeSheetDate,



						(IF(a.TimeIn = "00:00:00", "-", DATE_FORMAT(a.TimeIn, "%h:%i %p"))) AS TimeIn,



						(IF(a.TimeOut = "00:00:00", "-", DATE_FORMAT(a.TimeOut, "%h:%i %p"))) AS TimeOut,



						IFNULL(a.ComputerName, "-") AS ComputerName,



						IFNULL(a.LocalIP, "-") AS LocalIP,



						IFNULL(a.TerminalID, "-") AS TerminalID,



						IFNULL(a.TerminalName, "-") AS TerminalName,



						IFNULL(DATE_FORMAT(a.ProcessedDateTime, "%m-%d-%Y %h:%i %p"), "-") AS ProcessedDateTime,



						IFNULL(a.ProcessedBy, "-") AS ProcessedBy



						FROM tbltimesheetdetail AS a');







		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('Before:p_SQL = ', p_SQL);



				



		IF (LENGTH(p_WHERE) > 0)



		THEN



		SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');



		SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);



		END IF;



		SET p_SQL = REPLACE(p_SQL, '"', "'");			







		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('After:p_SQL = ', p_SQL);







		SET p_ORDERBY = '';



		SET p_ORDERBY = 'a.`Date`';







		IF (LENGTH(p_ORDERBY) > 0)



		THEN



			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');



			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);



		END IF;







		#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('Final p_SQL = ', p_SQL);







		SET @QUERY = p_SQL;



		# Execute Query 



		PREPARE QUERY FROM @QUERY;



		EXECUTE QUERY;



		



	ELSEIF (p_SearchBy = 'TimeSheet By Country')



	THEN



		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);



		SET v_TerminalID = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));



		SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS UNSIGNED INT);



		SET v_DateFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS DATE);



		SET v_DateTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS DATE);



		SET v_MissingTimeSheet = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,6)) AS UNSIGNED INT);



		SET v_CountryID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,7)) AS UNSIGNED INT);







		SET p_WHERE = '';



		IF (v_ParticularID > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');



			SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		IF (STRCMP(v_TerminalID, "0") != 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TSTerminalIDList LIKE ');



			SET p_WHERE = CONCAT(p_WHERE, "'%", v_TerminalID, "%'");



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		IF (v_DepartmentID > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.DepartmentID = ');



			SET p_WHERE = CONCAT(p_WHERE, v_DepartmentID);



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		IF (v_MissingTimeSheet > 0)



		THEN



			SET v_TTime = 8;



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.TTime < ');



			SET p_WHERE = CONCAT(p_WHERE, v_TTime);



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



			



			# Work Type / Leave Type



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.WorkTypeID = 0');			



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');					



			



		END IF;



		



		IF (v_CountryID > 0)



		THEN



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.CountryID = ');



			SET p_WHERE = CONCAT(p_WHERE, v_CountryID);



			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');



		END IF;



		



		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE



		#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));



		#SELECT CONCAT('p_WHERE = ', p_WHERE);



			



		SET p_SQL = '';	



		SET p_SQL = CONCAT(p_SQL,'SELECT');



		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.TSID, 0) AS TimeSheetID,



					IFNULL(a.ParticularID, 0) AS ParticularID,							



					IFNULL(a.FullName, "-") AS FullName,



					IFNULL(a.TSID, 0) AS TSID,



					IFNULL(a.TSDate, "-") AS OrderByDate,



					UPPER(IFNULL(DATE_FORMAT(a.TSDate, "%a, %b. %e, %Y"), "-"))AS TSDate,



					(IF(a.TimeIn = "00:00:00", "-", DATE_FORMAT(a.TimeIn, "%h:%i %p"))) AS TimeIn,



					(IF(a.TimeOut = "00:00:00", "-", DATE_FORMAT(a.TimeOut, "%h:%i %p"))) AS TimeOut,



					IFNULL(a.THours, "-") AS THours,



					IFNULL(a.TTime, 0) AS TTime,



					IFNULL(a.TimeStatus, "-") AS TimeStatus,



					IFNULL(a.Holiday, 0) AS Holiday,



					IFNULL(a.PositionID, 0) AS PositionID,



					IFNULL(c.Description, "-") AS Position,



					IFNULL(b.Description, "-") AS Department,



					IFNULL(b.DepartmentID, 0) AS DepartmentID,



					IFNULL(a.WorkTypeID, 0) AS WorkTypeID,



					IFNULL(a.WorkType, "-") AS WorkType,



					IFNULL(d.EmploymentStatus, "-") AS EmploymentStatus,



					IFNULL(a.DeviceIn, "-") AS DeviceIn,



					IFNULL(a.DeviceOut, "-") AS DeviceOut,



					IFNULL(a.ProcessedBy, "-") AS ProcessedBy,



					IFNULL(DATE_FORMAT(a.ProcessedDateTime, "%m-%d-%Y %h:%i %p"), "-") AS ProcessedDateTime



					FROM tbltimesheetdetailtemp AS a



					LEFT JOIN tbldepartment AS b ON a.DepartmentID = b.DepartmentID



					LEFT JOIN tblposition AS c ON a.PositionID = c.PositionID



					LEFT JOIN tblparticular AS d ON a.ParticularID = d.ParticularID');







		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('Before:p_SQL = ', p_SQL);



				



		IF (LENGTH(p_WHERE) > 0)



		THEN



		SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');



		SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);



		END IF;



		SET p_SQL = REPLACE(p_SQL, '"', "'");			







		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('After:p_SQL = ', p_SQL);







		SET p_ORDERBY = '';



		SET p_ORDERBY = 'a.TSDate, a.FullName';







		IF (LENGTH(p_ORDERBY) > 0)



		THEN



			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');



			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);



		END IF;







		#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));



		#SELECT CONCAT('Final p_SQL = ', p_SQL);







		SET @QUERY = p_SQL;



		# Execute Query 



		PREPARE QUERY FROM @QUERY;



		EXECUTE QUERY;	







	END IF;	



    



END IF;    



END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewTotal` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewTotal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewTotal`(  

    IN p_StatementType VARCHAR(30) /* = NULL */ ,

    IN p_SearchBy VARCHAR(255) /* = NULL */ ,

    IN p_SearchValue VARCHAR(255) /* = NULL */ ,

    OUT p_outTotal DECIMAL(12, 2)

)
BEGIN

DECLARE v_Total DECIMAL(12, 2);

DECLARE v_TTotal DECIMAL(12, 2);

DECLARE v_SystemDate VARCHAR(45);

DECLARE v_SearchQuery VARCHAR(200);

DECLARE v_ParticularID INT;

DECLARE v_LeaveTypeID INT;

DECLARE p_WHERE LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

DECLARE p_TempQuery LONGTEXT;

DECLARE p_INSERT LONGTEXT;

    

SET v_Total = 0;

SET v_SystemDate = CURDATE();

IF (p_StatementType = 'Search')

THEN

	IF (p_SearchBy = 'ERM Temp Detail Total Trxn Count')

	THEN

			SELECT COUNT(IFNULL(FSRNo, 0)) INTO v_Total FROM tblermdetailtemp;

			

	ELSEIF (p_SearchBy = 'ERM Temp Detail Total Amt Count')

	THEN

			SELECT CAST(SUM(IFNULL(TxnAmt, 0)) AS DECIMAL(12,2)) INTO v_Total FROM tblermdetailtemp;

			

	ELSEIF (p_SearchBy = 'ERM Temp Detail Total Trxn Count By Type')

	THEN

			SET v_SearchQuery = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

			

			SET p_WHERE = '';

			IF (STRCMP(v_SearchQuery, "0") != 0 AND LENGTH(v_SearchQuery) > 0)

			THEN					

				SET v_SearchQuery = LEFT(v_SearchQuery, LENGTH(v_SearchQuery) - 1); # Remove ^ from END of v_SearchQuery CLAUSE			

				SET v_SearchQuery = REPLACE(v_SearchQuery, "^", "|"); # Replace ^ to |

				

				SET p_WHERE = CONCAT(p_WHERE, ' ', ' WHERE Merchant REGEXP ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SearchQuery, "'");					

			END IF;

						

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

			

			SET p_SQL = CONCAT("SELECT COUNT(IFNULL(FSRNo, 0)) AS v_Count FROM tblermdetailtemp", p_WHERE);

			

			#SELECT CONCAT('Length(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);

			

			# Save count to temporary table

			DROP TEMPORARY TABLE IF EXISTS tbltemp;

			SET p_TempQuery = '';

			SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltemp (xCount VARCHAR(45) NOT NULL)');

			SET @QUERY = p_TempQuery;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			SET p_INSERT = '';

			SET p_INSERT = 'INSERT INTO tbltemp (xCount)';

			SET @QUERY = '';	

			SET @QUERY = CONCAT(p_INSERT, p_SQL);

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			SELECT xCount INTO v_Total 

			FROM tbltemp;

						

	ELSEIF (p_SearchBy = 'ERM Temp Detail Total Trxn Amt By Type')

	THEN

			SET v_SearchQuery = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));

						

			SET p_WHERE = '';

			IF (STRCMP(v_SearchQuery, "0") != 0 AND LENGTH(v_SearchQuery) > 0)

			THEN					

				SET v_SearchQuery = LEFT(v_SearchQuery, LENGTH(v_SearchQuery) - 1); # Remove ^ from END of v_SearchQuery CLAUSE			

				SET v_SearchQuery = REPLACE(v_SearchQuery, "^", "|"); # Replace ^ to |

				

				SET p_WHERE = CONCAT(p_WHERE, ' ', ' WHERE Merchant REGEXP ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_SearchQuery, "'");				

			END IF;

						

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

			

			SET p_SQL = CONCAT("SELECT CAST(SUM(IFNULL(TxnAmt, 0)) AS DECIMAL(12,2)) AS v_Count FROM tblermdetailtemp", p_WHERE);

			

			#SELECT CONCAT('Length(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('p_SQL = ', p_SQL);

			

			# Save count to temporary table

			DROP TEMPORARY TABLE IF EXISTS tbltemp;

			SET p_TempQuery = '';

			SET p_TempQuery = CONCAT('CREATE TEMPORARY TABLE tbltemp (xCount VARCHAR(45) NOT NULL)');

			SET @QUERY = p_TempQuery;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			SET p_INSERT = '';

			SET p_INSERT = 'INSERT INTO tbltemp (xCount)';

			SET @QUERY = '';	

			SET @QUERY = CONCAT(p_INSERT, p_SQL);

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

			SELECT xCount INTO v_Total 

			FROM tbltemp;

			

	ELSEIF (p_SearchBy = 'Particular Leave Count')

	THEN	

			SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_LeaveTypeID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INTEGER);

			

			SELECT IFNULL(FORMAT(SUM(Duration),2), 0.00) INTO v_TTotal

			FROM tblleavemovement

			WHERE ParticularID = v_ParticularID AND LeaveTypeID = v_LeaveTypeID AND isActive > 0;					

			

			SET v_Total = v_TTotal;			

															

	END IF;

	

	#SELECT CONCAT("Out::v_Count=", v_Count);

	

	IF (v_Total > 0)

	THEN

		SET p_outTotal = v_Total;

	ELSE

		SET p_outTotal = 0;

	END IF;

		

END IF;

        

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewType` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewType` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewType`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_Type INTEGER;

    

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'Type')

		THEN

			SET v_Type = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			

			SELECT 

			IFNULL_NUMERIC(TypeID) as TypeID, 

			"-" AS `Code`,

			IFNULL_STRING_ONLY(Description) as Description,

			IFNULL_STRING_ONLY(Remarks) as Remarks,

			(QueryString) as QueryString,

			IFNULL_NUMERIC(TypeValue) AS TypeValue

			FROM   tbltype

			WHERE (`Type` = v_Type AND Active > 0)

			ORDER BY DESCRIPTION;

			

		ELSEIF (p_SearchBy = 'WorkType')

		THEN

			SELECT 

			IFNULL_NUMERIC(a.WorkTypeID) as WorkTypeID,

			IFNULL_STRING_ONLY(a.`Code`) as `Code`,

			IFNULL_STRING_ONLY(a.Description) AS Description,

			"-" as Remarks,

			"-" as QueryString,

			"0" as TypeValue

			FROM

			tblworktype a

			WHERE(a.isActive > 0)

			ORDER BY a.DisplaySequence;

			

		ELSEIF (p_SearchBy = 'Type List')

		THEN

			SELECT 

			IFNULL_NUMERIC(TypeID) AS TypeID, 

			"-" AS `Code`,

			IFNULL_STRING_ONLY(Description) AS Description,

			IFNULL_STRING_ONLY(Remarks) AS Remarks,

			IFNULL_STRING_ONLY(QueryString) AS QueryString,

			IFNULL_NUMERIC(TypeValue) AS TypeValue

			FROM   tbltype

			WHERE (Active > 0)

			ORDER BY TypeID;

			

		ELSEIF (p_SearchBy = 'Rental Fee List')

		THEN			

			SELECT

			IFNULL_NUMERIC(RentalFeeID) AS TypeID,

			"-" AS `Code`,

			Description AS Description,

			"-" AS Remarks,

			"-" as QueryString,

			IFNULL_DECIMAL(RentalFee) as TypeValue 

			FROM

			tblpr_rentalfee

			WHERE (isActive > 0)

			ORDER BY Description;

		ELSE			

			SELECT 

			IFNULL_NUMERIC(TypeID) AS TypeID, 

			"-" AS `Code`,

			IFNULL_STRING_ONLY(Description) AS Description,

			IFNULL_STRING_ONLY(Remarks) AS Remarks,

			IFNULL_STRING_ONLY(QueryString) AS QueryString,

			IFNULL_NUMERIC(TypeValue) AS TypeValue

			FROM   tbltype			

			WHERE (Active > 0)

			ORDER BY Description;


		END IF;

		

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'Type')

        THEN

			SET p_SearchValue = CONCAT(p_SearchValue, '%', '');

			SELECT      DISTINCT   

						TypeID,

						Description,

						Remarks,

						QueryString,

						TypeValue

			FROM        tbltype

			WHERE       (Description LIKE p_SearchValue);

		

		ELSEIF (p_SearchBy = 'TypeID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);

			SELECT      DISTINCT   

						TypeID,

						Description,

						Remarks,

						QueryString,

						TypeValue

			FROM        tbltype

			WHERE       (TypeID = v_ID);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewUser` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewUser` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewUser`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

	DECLARE v_ID INTEGER;

	DECLARE v_UserID INTEGER;

	DECLARE v_UserType VARCHAR(45);

	DECLARE v_LogDateFrom VARCHAR(45);

	DECLARE v_LogDateTo VARCHAR(45);

	DECLARE v_UserAction VARCHAR(45);

	DECLARE v_SessionStatus INTEGER;

   

	DECLARE p_WHERE LONGTEXT;

	DECLARE p_ORDERBY LONGTEXT;

	DECLARE p_GROUPBY LONGTEXT;

	DECLARE p_SQL LONGTEXT;	

	

    IF (p_StatementType = 'View')

	THEN

		IF (p_SearchBy = 'User Log')

		THEN

			SET v_UserID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INTEGER);

			SET v_UserType = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));

			SET v_LogDateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,3));

			SET v_LogDateTo = TRIM(SPLIT_STRING(p_SearchValue, '|' ,4));

			SET v_SessionStatus = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,5)) AS UNSIGNED INTEGER);

			

			SET p_WHERE = '';

			IF (v_UserID > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.UserID = ');

				SET p_WHERE = CONCAT(p_WHERE, v_UserID);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_UserType, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.UserType = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_UserType, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;	

			

			IF (STRCMP(v_LogDateFrom, "0000-00-00") != 0 && STRCMP(v_LogDateTo, "0000-00-00") != 0)

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.LogDate', ' ', 'BETWEEN', ' ');

				SET p_WHERE = CONCAT(p_WHERE, 'CAST(', "'", v_LogDateFrom, "'", ' AS DATE)', ' ', 'AND', ' ', 'CAST(', "'", v_LogDateTo, "'", ' AS DATE)');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (v_SessionStatus > 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.SessionStatus = ');

				SET p_WHERE = CONCAT(p_WHERE, v_SessionStatus);

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

		    

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(b.UserID, 0) AS UserID,

							IFNULL(b.UserName, "-") AS UserName,											

							IFNULL(b.FullName, "-") AS FullName,

							IFNULL(b.UserType, "-") AS UserType,

							IFNULL(a.LogID, 0) AS LogID,							

							IFNULL(a.ComputerIP, "-") AS ComputerIP,

							IFNULL(a.ComputerName, "-") AS ComputerName,

							IFNULL(a.SessionStatus, 0) AS SessionStatus,

							IFNULL(a.SessionStatusDescription, "-") AS SessionStatusDescription,													

							IFNULL(DATE_FORMAT(a.LogDate, "%m-%d-%Y"), "-") AS LogInDate,

							IFNULL(DATE_FORMAT(a.LogDate, "%h:%i %p"), "-") AS LogInTime,

							IFNULL(DATE_FORMAT(a.LogOutDate, "%m-%d-%Y"), "-") AS LogOutDate,

							IFNULL(DATE_FORMAT(a.LogOutDate, "%h:%i %p"), "-") AS LogOutTime,

							IFNULL(a.PublishVersion, 0) AS PublishVersion

							FROM tbluserlog AS a

							LEFT JOIN tbluser AS b ON a.UserID = b.UserID');	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);	

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.LogID';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;	

			

		ELSEIF (p_SearchBy = 'Who Is Online')

		THEN				

			SET v_LogDateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|' ,1));	

			SET v_UserAction = TRIM(SPLIT_STRING(p_SearchValue, '|' ,2));	

			

			SET p_WHERE = '';						

			IF (STRCMP(v_LogDateFrom, "0000-00-00"))

			THEN			

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'SUBSTR(a.LogDate,1,10)', ' ', '=', ' ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_LogDateFrom, "'", ' ');

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			IF (STRCMP(v_UserAction, "0") != 0)

			THEN

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.UserAction = ');

				SET p_WHERE = CONCAT(p_WHERE, "'", v_UserAction, "'");

				SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

			END IF;

			

			SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

			#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

			#SELECT CONCAT('p_WHERE = ', p_WHERE);

		    

			SET p_SQL = '';	

			SET p_SQL = CONCAT(p_SQL,'SELECT');

			SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(b.UserID, 0) AS UserID,

							IFNULL(b.UserName, "-") AS UserName,											

							IFNULL(b.FullName, "-") AS FullName,

							IFNULL(b.UserType, "-") AS UserType,

							IFNULL(a.LogID, 0) AS LogID,							

							IFNULL(a.ComputerIP, "-") AS ComputerIP,

							IFNULL(a.ComputerName, "-") AS ComputerName,							

							IFNULL(DATE_FORMAT(a.LogDate, "%h:%i %p"), "-") AS LogInTime							

							FROM tbluserlog AS a

							LEFT JOIN tbluser AS b ON a.UserID = b.UserID');	

			#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('Before:p_SQL = ', p_SQL);

			

			IF (LENGTH(p_WHERE) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

				SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

			END IF;

			SET p_SQL = REPLACE(p_SQL, '"', "'");

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_GROUPBY = '';

			SET p_GROUPBY = 'a.UserID';

			IF (LENGTH(p_GROUPBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'GROUP BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_GROUPBY);

			END IF;	

				

			#SELECT CONCAT('After:Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT('After:p_SQL = ', p_SQL);

			

			SET p_ORDERBY = '';

			SET p_ORDERBY = 'a.LogID';

			

			IF (LENGTH(p_ORDERBY) > 0)

			THEN

				SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

				SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

			END IF;

			

			#SELECT CONCAT(':Len(p_SQL) = ', LENGTH(p_SQL));

			#SELECT CONCAT(':p_SQL = ', p_SQL);

			

			SET @QUERY = p_SQL;

			# Execute Query 

			PREPARE QUERY FROM @QUERY;

			EXECUTE QUERY;

			

		ELSE

			SELECT   
			a.UserID AS UserID,
			a.ParticularID AS ParticularID,
			a.UserName AS UserName,
			a.FullName AS FullName,
			a.`Password` AS `Password`,			
			a.MD5Password AS MD5Password,
			a.UserType AS UserType,
			IFNULL(b.isActive, 0) AS isActive,
			IFNULL(b.isAppVersion, 0) AS isAppVersion,
			IFNULL(a.MobileID, 0) AS MobileID,
			IFNULL(c.TerminalID, "-") AS MobileTerminalID,
			IFNULL(c.TerminalName, "-") AS MobileTerminalName
			FROM        tbluser a		
			LEFT JOIN tblparticular AS b ON a.ParticularID = b.ParticularID
			LEFT JOIN tblterminal AS c ON a.MobileID = c.TID			
			WHERE a.isActive > 0
			ORDER BY a.FullName;

		END IF;	

    ELSEIF (p_StatementType = 'Search')

    THEN

		IF (p_SearchBy = 'UserName')
        THEN
			SET p_SearchValue = p_SearchValue;
			
			SELECT   
			a.UserID AS UserID,
			a.ParticularID AS ParticularID,
			a.UserName AS UserName,
			a.FullName AS FullName,
			a.`Password` AS `Password`,		
			a.MD5Password AS MD5Password,
			a.UserType AS UserType,
			IFNULL(b.isActive, 0) AS isActive,
			IFNULL(b.isAppVersion, 0) AS isAppVersion,
			a.MobileID AS MobileID,
			c.TerminalID AS MobileTerminalID,
			c.TerminalName AS MobileTerminalName
			FROM        tbluser a
			LEFT JOIN tblparticular AS b ON a.ParticularID = b.ParticularID
			LEFT JOIN tblterminal AS c ON a.MobileID = c.TID
			WHERE       (a.UserName = p_SearchValue)
			AND (a.isActive = 1)
			AND (b.isActive = 1);

		ELSEIF (p_SearchBy = 'UserID')

        THEN

			SET v_ID = CAST(p_SearchValue AS UNSIGNED INTEGER);
			
			SELECT
			a.UserID AS UserID,
			a.ParticularID AS ParticularID,
			a.UserName AS UserName,
			a.FullName AS FullName,
			a.`Password` AS `Password`,	
			a.MD5Password AS MD5Password,
			a.UserType AS UserType,
			IFNULL(b.isActive, 0) AS isActive,
			IFNULL(b.isAppVersion, 0) AS isAppVersion,
			a.MobileID AS MobileID,
			c.TerminalID AS MobileTerminalID,
			c.TerminalName AS MobileTerminalName
			FROM        tbluser a
			LEFT JOIN tblparticular AS b ON a.ParticularID = b.ParticularID
			LEFT JOIN tblterminal AS c ON a.MobileID = c.TID
			WHERE       (a.UserID = v_ID);

		ELSEIF (p_SearchBy = 'User Time Logger')

        THEN
			SET p_SearchValue = p_SearchValue;
			
			SELECT
			a.UserID AS UserID,
			a.ParticularID AS ParticularID,
			a.UserName AS UserName,
			a.FullName AS FullName,
			a.`Password` AS `Password`,			
			a.MD5Password AS MD5Password,
			a.UserType AS UserType,			
			IFNULL(b.isTimeSheet, 0) AS isTimeSheet,
			IFNULL(b.isWorkArrangement, 0) AS isWorkArrangement,
			IFNULL(a.TimeZone, "Asia/Taipei") AS TimeZone,
			a.MobileID AS MobileID,
			c.TerminalID as MobileTerminalID,
			c.TerminalName AS MobileTerminalName
			FROM        tbluser AS a
			LEFT JOIN tblparticular AS b ON a.ParticularID = b.ParticularID
			LEFT JOIN tblterminal AS c ON a.MobileID = c.TID
			WHERE       (a.UserName = p_SearchValue);				

            

		 END IF;

         

	END IF;    

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewUserReport` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewUserReport` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewUserReport`(
    p_StatementType VARCHAR(30) /* = NULL */,
    p_SearchBy VARCHAR(50) /* = NULL */,
    p_SearchValue VARCHAR(255) /* = NULL */
)
BEGIN

    DECLARE v_DepartmentID INTEGER;
    DECLARE v_ParticularID INTEGER;
    DECLARE v_DateFrom VARCHAR(45);
    DECLARE v_DateTo VARCHAR(45);

    IF (p_StatementType = 'View')
    THEN

        IF (p_SearchBy = 'User Log Report')
        THEN

            SET v_DepartmentID = CAST(IFNULL(NULLIF(TRIM(SPLIT_STRING(p_SearchValue, '|', 1)), ''), '0') AS UNSIGNED INTEGER);
            SET v_ParticularID = CAST(IFNULL(NULLIF(TRIM(SPLIT_STRING(p_SearchValue, '|', 2)), ''), '0') AS UNSIGNED INTEGER);
            SET v_DateFrom = TRIM(SPLIT_STRING(p_SearchValue, '|', 3));
            SET v_DateTo = TRIM(SPLIT_STRING(p_SearchValue, '|', 4));

            SELECT
                CAST(IFNULL(NULLIF(usr.UserName, ''), IFNULL(usrlog.UserName, '-')) AS CHAR(100)) AS UserName,
                CAST(IFNULL(NULLIF(usr.FullName, ''), IFNULL(usrlog.FullName, '-')) AS CHAR(150)) AS FullName,
                CAST(IFNULL(usr.UserType, '-') AS CHAR(50)) AS UserType,
                CAST(IFNULL(usrlog.LogID, 0) AS SIGNED) AS LogID,
                CAST(IFNULL(usrlog.ComputerIP, '-') AS CHAR(50)) AS ComputerIP,
                CAST(IFNULL(usrlog.ComputerName, '-') AS CHAR(100)) AS ComputerName,
                CAST(IFNULL(usrlog.UserAction, '-') AS CHAR(100)) AS UserAction,
                CAST(IFNULL(usrlog.SessionStatusDescription, '-') AS CHAR(100)) AS SessionStatusDescription,
                CAST(IFNULL(DATE_FORMAT(usrlog.LogDate, '%m-%d-%Y'), '-') AS CHAR(20)) AS LogInDate,
                CAST(IFNULL(DATE_FORMAT(usrlog.LogDate, '%h:%i %p'), '-') AS CHAR(20)) AS LogInTime,
                CAST(IFNULL(DATE_FORMAT(usrlog.LogOutDate, '%m-%d-%Y'), '-') AS CHAR(20)) AS LogOutDate,
                CAST(IFNULL(DATE_FORMAT(usrlog.LogOutDate, '%h:%i %p'), '-') AS CHAR(20)) AS LogOutTime
            FROM tbluserlog usrlog
            LEFT JOIN tbluser usr
                ON usr.UserID = usrlog.UserID
            LEFT JOIN tblparticular pt
                ON pt.ParticularID = usr.ParticularID
            WHERE NULLIF(v_DateFrom, '') IS NOT NULL
              AND NULLIF(v_DateTo, '') IS NOT NULL
              AND usrlog.LogDate >= STR_TO_DATE(v_DateFrom, '%Y-%m-%d')
              AND usrlog.LogDate < DATE_ADD(STR_TO_DATE(v_DateTo, '%Y-%m-%d'), INTERVAL 1 DAY)
              AND (v_DepartmentID = 0 OR pt.DepartmentID = v_DepartmentID)
              AND (v_ParticularID = 0 OR usr.ParticularID = v_ParticularID)
            ORDER BY usrlog.LogDate DESC, usrlog.LogID DESC;

        END IF;

    END IF;

END */$$
DELIMITER ;

/* Procedure structure for procedure `spViewWorkArrangement` */

/*!50003 DROP PROCEDURE IF EXISTS  `spViewWorkArrangement` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `spViewWorkArrangement`(  

    p_StatementType VARCHAR(30) /* = NULL */ ,

	p_SearchBy VARCHAR(50) /* = NULL */ ,

	p_SearchValue VARCHAR(50) /* = NULL */

)
BEGIN

DECLARE v_ID INTEGER;

DECLARE v_ParticularID INT;

DECLARE v_DepartmentID INT;

DECLARE v_PositionID INT;

DECLARE v_DateFrom DATE;

DECLARE v_DateTo DATE;

DECLARE v_TerminalID VARCHAR(10);

DECLARE p_WHERE LONGTEXT;

DECLARE p_GROUPBY LONGTEXT;

DECLARE p_ORDERBY LONGTEXT;

DECLARE p_SQL LONGTEXT;

IF (p_StatementType = 'View')

THEN

	IF (p_SearchBy = 'Work Arrangement')

	THEN

		SET v_ParticularID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,1)) AS UNSIGNED INT);		

		SET v_DepartmentID = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,2)) AS UNSIGNED INT);

		#SET v_DateFrom = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,3)) AS DATE);

		#SET v_DateTo = CAST(TRIM(SPLIT_STRING(p_SearchValue, '|' ,4)) AS DATE);

		SET p_WHERE = '';

		IF (v_ParticularID > 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.ParticularID = ');

			SET p_WHERE = CONCAT(p_WHERE, v_ParticularID);

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;

		

		IF (v_DepartmentID > 0)

		THEN

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'c.DepartmentID = ');

			SET p_WHERE = CONCAT(p_WHERE, v_DepartmentID);

			SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		END IF;

		

		# active (tblparticular)

		SET p_WHERE = CONCAT(p_WHERE, ' ', 'b.isActive > 0 ');

		SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		

		# active (tblworkarrangement)

		SET p_WHERE = CONCAT(p_WHERE, ' ', 'a.isActive > 0 ');

		SET p_WHERE = CONCAT(p_WHERE, ' ', 'AND');

		

		SET p_WHERE = LEFT(p_WHERE, LENGTH(p_WHERE) - 4); # Remove AND from END of WHERE CLAUSE

		#SELECT CONCAT('Length(p_WHERE) = ', LENGTH(p_WHERE));

		#SELECT CONCAT('p_WHERE = ', p_WHERE);

			

		SET p_SQL = '';	

		SET p_SQL = CONCAT(p_SQL,'SELECT');

		SET p_SQL = CONCAT(p_SQL, ' ', 'IFNULL(a.ParticularID, 0) AS ParticularID,

					IFNULL(a.WorkArrangementID, 0) AS WorkArrangementID,							

					IFNULL(b.Name, "-") AS FullName,

					CONCAT(UPPER(IFNULL(DATE_FORMAT(a.DateFrom, "%a, %b %e, %Y"), "-")), " - ", UPPER(IFNULL(DATE_FORMAT(a.DateTo, "%a, %b %e, %Y"), "-"))) AS DateFromTo,					

					IFNULL(a.DateType, "-") AS DateType,

					IFNULL(a.Duration, 0) AS Duration,

					IFNULL(a.Remarks, "-") AS Remarks,

					IFNULL(a.ProcessedBy, "-") AS ProcessedBy,					

					IFNULL(DATE_FORMAT(a.ProcessedDateTime, "%m-%d-%Y %h:%i %p"), "-") AS ProcessedDateTime,

					IFNULL(a.ModifiedBy, "-") AS ModifiedBy,					

					IFNULL(DATE_FORMAT(a.ModifiedDateTime, "%m-%d-%Y %h:%i %p"), "-") AS ModifiedDateTime,					

					IFNULL(b.PositionID, 0) AS PositionID,

					IFNULL(d.Description, "-") AS Position,					

					IFNULL(b.DepartmentID, 0) AS DepartmentID,

					IFNULL(c.Description, "-") AS Department,					

					IFNULL(a.WorkTypeID, 0) AS WorkTypeID,

					IFNULL(e.Code, "-") AS WorkTypeCode,

					IFNULL(e.Description, "-") AS WorkTypeDesc,

					IFNULL(b.EmploymentStatus, "-") AS EmploymentStatus

					FROM tblworkarrangement AS a

					LEFT JOIN tblparticular AS b ON a.ParticularID = b.ParticularID

					LEFT JOIN tbldepartment AS c ON b.DepartmentID = c.DepartmentID

					LEFT JOIN tblposition AS d ON b.PositionID = d.PositionID

					LEFT JOIN tblworktype AS e ON a.WorkTypeID = e.WorkTypeID');

		#SELECT CONCAT('Before:Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('Before:p_SQL = ', p_SQL);

				

		IF (LENGTH(p_WHERE) > 0)

		THEN

		SET p_SQL = CONCAT(p_SQL, ' ', 'WHERE');

		SET p_SQL = CONCAT(p_SQL, ' ', p_WHERE);

		END IF;

		SET p_SQL = REPLACE(p_SQL, '"', "'");			

		#SELECT CONCAT('Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('After:p_SQL = ', p_SQL);

		SET p_ORDERBY = '';

		SET p_ORDERBY = 'b.Name, a.DateFrom';

		IF (LENGTH(p_ORDERBY) > 0)

		THEN

			SET p_SQL = CONCAT(p_SQL, ' ', 'ORDER BY');

			SET p_SQL = CONCAT(p_SQL, ' ', p_ORDERBY);

		END IF;

		#SELECT CONCAT('Final Len(p_SQL) = ', LENGTH(p_SQL));

		#SELECT CONCAT('Final p_SQL = ', p_SQL);

		SET @QUERY = p_SQL;

		# Execute Query 

		PREPARE QUERY FROM @QUERY;

		EXECUTE QUERY;

	

	END IF;

	   

 

END IF;    

END */$$
DELIMITER ;

