/*View structure for view vw_installation_info */

/*!50001 DROP TABLE IF EXISTS `vw_installation_info` */;
/*!50001 DROP VIEW IF EXISTS `vw_installation_info` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_installation_info` AS select `ir`.`IRIDNo` AS `IR_ID`,`ir`.`IRDate` AS `Created_Date`,`ir`.`InstallationDate` AS `Target_Date`,`ir`.`IRNo` AS `Request_No`,`ir`.`IRStatus` AS `Status_ID`,`ir`.`IRStatusDescription` AS `Status`,`ir`.`TID` AS `TID`,`ir`.`MID` AS `MID`,coalesce(`ti`.`Model_ID`,0) AS `Model_ID`,coalesce(`ti`.`Model`,0) AS `Model_Name`,coalesce(`ti`.`Terminal_ID`,0) AS `Terminal_ID`,coalesce(`ti`.`Terminal_SN`,0) AS `Terminal_SN`,`ti`.`Location` AS `Terminal_Loc`,`ti`.`Status_ID` AS `Term_Stat_ID`,`ti`.`Status` AS `Terminal_Status`,`si`.`Carrier_ID` AS `Carrier_ID`,`si`.`Carrier` AS `Carrier`,coalesce(`si`.`Sim_ID`,0) AS `Sim_ID`,coalesce(`si`.`Sim_SN`,0) AS `Sim_SN`,`si`.`Location` AS `Sim_Loc`,`si`.`Status_ID` AS `SimStatID`,`si`.`Status` AS `Sim_Status`,`ir`.`MerchantID` AS `Merchant_ID`,`ir`.`MerchantName` AS `Merchant`,`mi`.`Address` AS `Address`,`ir`.`REQUESTOR` AS `Requestor`,`mi`.`Contact_Person` AS `Contact_Person`,`mi`.`Contact_No` AS `Contact_No`,`mi`.`Tel_No` AS `Tel_No`,`mi`.`Mobile_No` AS `Mobile_No`,`mi`.`Fax_No` AS `Fax_No`,`mi`.`Email` AS `Email`,`mi`.`Region_ID` AS `Region_ID`,`mi`.`Region` AS `Region`,`mi`.`Province_ID` AS `Province_ID`,`mi`.`Province` AS `Province`,`mi`.`Charge` AS `Charge`,coalesce(`ir`.`AppVersion`,0) AS `App_Version`,coalesce(`ir`.`AppCRC`,0) AS `App_Crc`,if((`ir`.`PrimaryNum` in (0,'-','')),NULL,`ir`.`PrimaryNum`) AS `Primary_Num`,if((`ir`.`SecondaryNum` in (0,'-','')),NULL,`ir`.`SecondaryNum`) AS `Secondary_Num`,coalesce(`tp`.`Base_Price`,0) AS `Terminal_Cost`,coalesce(`tp`.`Rent_Price`,0) AS `Rental_Cost`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."POS Connection Type"') AS `Conn_Type`,`ir`.`POS_TYPE` AS `Pos_Type`,if((`ir`.`SET_UP` in (0,'-','')),NULL,`ir`.`SET_UP`) AS `Setup`,if((`ir`.`REQUEST_FOR` in (0,'-','')),NULL,`ir`.`REQUEST_FOR`) AS `Request_For`,`ir`.`OTHER_SPECIAL_INSTRUCTION` AS `Special_Instruction`,`ir`.`profile_info` AS `profile_info`,`ir`.`rawdata_info` AS `rawdata_info`,`ir`.`ClientID` AS `Client_ID`,`ir`.`ClientName` AS `Client`,`ir`.`IRActive` AS `isActive` from ((((`tblirdetail` `ir` left join `vw_terminal_info` `ti` on((`ti`.`Terminal_ID` = `ir`.`TerminalID`))) left join `vw_sim_info` `si` on((`si`.`Sim_ID` = `ir`.`SIMID`))) left join `vw_merchant_info` `mi` on((`mi`.`Merchant_ID` = `ir`.`MerchantID`))) left join `tblterminalpricing` `tp` on(((`tp`.`Model_ID` = `ti`.`Model_ID`) and (`tp`.`Client_ID` = `ir`.`ClientID`) and (`ir`.`InstallationDate` between `tp`.`Start_Date` and `tp`.`End_Date`)))) where (`ir`.`IRActive` = 1) */;

/*View structure for view vw_ir_info */

/*!50001 DROP TABLE IF EXISTS `vw_ir_info` */;
/*!50001 DROP VIEW IF EXISTS `vw_ir_info` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_ir_info` AS select `ir`.`IRIDNo` AS `IRIDNo`,`ir`.`ClientID` AS `Client_ID`,`funcGetDesc`('Search','Particular',`ir`.`ClientID`) AS `Client_Name`,`ir`.`IRNo` AS `IRNo`,`ir`.`IRDate` AS `IRDate`,`ir`.`InstallationDate` AS `InstallationDate`,`ir`.`TerminalID` AS `TerminalID`,`funcGetDesc`('Search','Terminal Detail',`ir`.`TerminalID`) AS `TerminalSN`,`ir`.`SIMID` AS `SIMID`,`funcGetDesc`('Search','SIM Detail',`ir`.`SIMID`) AS `SIMSN`,`ir`.`profile_info` AS `profile_info`,`ir`.`rawdata_info` AS `rawdata_info`,`ir`.`IRStatus` AS `IRStatus`,`ir`.`IRStatusDescription` AS `IRStatusDescription`,`pt`.`ParticularID` AS `Merchant_ID`,`funcGetDesc`('Search','Particular',`ir`.`MerchantID`) AS `Merchant_Name`,`ir`.`TID` AS `TID`,`ir`.`MID` AS `MID`,nullif(`pt`.`Address`,'-') AS `Address`,nullif(`pt`.`Address2`,'-') AS `Address_2`,nullif(`pt`.`Address3`,'-') AS `Address_3`,nullif(`pt`.`Address4`,'-') AS `Address_4`,`rd`.`RegionID` AS `Region_ID`,nullif(`rd`.`Province`,'-') AS `Province`,`rg`.`RegionID` AS `Province_ID`,nullif(`rg`.`Region`,'-') AS `Region`,`rg`.`Charge` AS `Charge`,nullif(`pt`.`ContactPerson`,'-') AS `Contact_Person`,nullif(`pt`.`ContactNumber`,'-') AS `Contact_No`,nullif(`pt`.`TelNo`,'-') AS `Tel_No`,nullif(`pt`.`Mobile`,'-') AS `Mobile_No`,nullif(`pt`.`Fax`,'-') AS `Fax_No`,nullif(`pt`.`Email`,'-') AS `Email` from (((((`tblirdetail` `ir` left join `tblparticular` `pt` on((`pt`.`ParticularID` = `ir`.`MerchantID`))) left join `tblregiondetail` `rd` on((`rd`.`RegionID` = `pt`.`RegionID`))) left join `tblregion` `rg` on((`rg`.`RegionID` = `rd`.`RegionType`))) left join `tblterminaldetail` `td` on((`td`.`TerminalID` = `ir`.`TerminalID`))) left join `tblsimdetail` `tm` on((`tm`.`SIMID` = `ir`.`SIMID`))) where ((`pt`.`ParticularTypeID` in ('1','2')) and (`ir`.`IRStatus` > 0)) */;

