/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_merchant_info` AS select `pt`.`ParticularID` AS `Merchant_ID`,`pt`.`Name` AS `Merchant_Name`,nullif(`pt`.`Address`,'-') AS `Address`,nullif(`pt`.`Address2`,'-') AS `Address_2`,nullif(`pt`.`Address3`,'-') AS `Address_3`,nullif(`pt`.`Address4`,'-') AS `Address_4`,`rd`.`RegionID` AS `Region_ID`,nullif(`rd`.`Province`,'-') AS `Region`,`rg`.`RegionID` AS `Province_ID`,nullif(`rg`.`Region`,'-') AS `Province`,`rg`.`Charge` AS `Charge`,nullif(`pt`.`ContactPerson`,'-') AS `Contact_Person`,nullif(`pt`.`ContactNumber`,'-') AS `Contact_No`,nullif(`pt`.`TelNo`,'-') AS `Tel_No`,nullif(`pt`.`Mobile`,'-') AS `Mobile_No`,nullif(`pt`.`Fax`,'-') AS `Fax_No`,nullif(`pt`.`Email`,'-') AS `Email`,nullif(`pt`.`profile_config_info`,'-') AS `prof_config`,nullif(`pt`.`isActive`,'0') AS `isActive` from ((`tblparticular` `pt` left join `tblregiondetail` `rd` on((`rd`.`RegionID` = `pt`.`RegionID`))) left join `tblregion` `rg` on((`rg`.`RegionID` = `rd`.`RegionType`))) where (`pt`.`ParticularTypeID` in ('1','2')) */;

/*View structure for view vw_monitoring_jobs */

/*!50001 DROP TABLE IF EXISTS `vw_monitoring_jobs` */;
/*!50001 DROP VIEW IF EXISTS `vw_monitoring_jobs` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_monitoring_jobs` AS select `svc`.`ServiceNo` AS `Job_ID`,`svc`.`ServiceNo` AS `ServiceNo`,`fsr`.`FSRNo` AS `FSRNo`,`svc`.`ClientID` AS `ClientID`,`svc`.`MerchantID` AS `MerchantID`,`svc`.`IRIDNo` AS `IRIDNo`,`svc`.`ServiceDate` AS `Request_Date`,`svc`.`ServiceReqDate` AS `Schedule_Date`,`svc`.`ReqInstallationDate` AS `Installation_Date`,if((`svc`.`JobType` = '1'),`ir`.`IRDate`,`svc`.`ServiceReqDate`) AS `Created_Date`,if((`svc`.`JobType` = '1'),`ir`.`InstallationDate`,`svc`.`ServiceReqDate`) AS `Target_Date`,if((`svc`.`ServiceStatus` = '2'),'WAITING',coalesce(`fsr`.`FSRDate`,'PENDING FSR')) AS `Service_Date`,`fsr`.`FSRDate` AS `FSRDate`,timestampdiff(DAY,`svc`.`ProcessedDateTime`,now()) AS `Days`,`svc`.`IRIDNo` AS `Request_ID`,`svc`.`IRNo` AS `Request_No`,`svc`.`ReferenceNo` AS `Reference_No`,`svc`.`RequestNo` AS `RequestNo`,`svc`.`JobTypeSubDescription` AS `Request`,`svc`.`JobTypeStatusDescription` AS `Request_Status`,`svc`.`ServiceStatusDescription` AS `Service_Status`,if((`svc`.`ServiceStatus` = '2'),'WAITING',coalesce(`fsr`.`ActionMade`,'PENDING FSR')) AS `Service_Result`,`pt`.`ParticularID` AS `Merchant_ID`,`svc`.`MerchantName` AS `Merchant_Name`,`pt`.`Address` AS `Address`,`pt`.`RegionID` AS `Reg_ID`,`pt`.`Region` AS `Region`,`pt`.`RegionType` AS `Prov_ID`,`pt`.`RegionType` AS `RegionType`,`pt`.`RegionID` AS `RegionID`,`pt`.`Province` AS `Province`,`ir`.`MID` AS `MID`,`ir`.`TID` AS `TID`,`ir`.`profile_info` AS `profile_info`,`ir`.`rawdata_info` AS `rawdata_info`,`td`.`TerminalID` AS `Old_TSID`,`svc`.`TerminalSN` AS `Old_TSN`,`svc`.`ReplaceTerminalID` AS `New_TSID`,`svc`.`ReplaceTerminalSN` AS `New_TSN`,ifnull(nullif(`svc`.`ReplaceTerminalID`,''),`td`.`TerminalID`) AS `Terminal_ID`,ifnull(nullif(`svc`.`ReplaceTerminalSN`,''),`svc`.`TerminalSN`) AS `Terminal_SN`,`sd`.`SIMID` AS `Old_SSID`,`svc`.`SIMSerialNo` AS `Old_SSN`,`svc`.`ReplaceSIMID` AS `New_SSID`,`svc`.`ReplaceSIMSN` AS `New_SSN`,ifnull(nullif(`svc`.`ReplaceSIMID`,''),`sd`.`SIMID`) AS `Sim_ID`,ifnull(nullif(`svc`.`ReplaceSIMSN`,''),`svc`.`SIMSerialNo`) AS `Sim_SN`,`td`.`Model` AS `Model`,`td`.`Type` AS `Type`,`td`.`Brand` AS `Brand`,`svc`.`AppVersion` AS `AppVersion`,`svc`.`AppCRC` AS `AppCRC`,`td`.`Location` AS `Location`,`svc`.`FEName` AS `FE_Name`,`svc`.`ClientName` AS `ClientName`,`st`.`ServiceTypeID` AS `ServiceTypeID`,`st`.`JobType` AS `JobType`,`st`.`ServiceStatus` AS `ServiceStatus`,`st`.`ServiceStatusDescription` AS `ServiceStatusDescription`,`st`.`JobTypeDescription` AS `JobTypeDescription`,`st`.`ServiceJobTypeDescription` AS `ServiceJobTypeDescription`,`fsr`.`MerchantRepresentative` AS `MerchantRepresentative`,`fsr`.`FEName` AS `VendorRepresentative`,`fsr`.`ActualProblemReported` AS `ActualProblemReported`,`fsr`.`ActionTaken` AS `ActionTaken`,`fsr`.`AnyComments` AS `AnyComments`,`fsr`.`Remarks` AS `fsrRemarks`,`fsr`.`Reason` AS `fsrReason`,`fsr`.`FSRRefNo` AS `fsrRefNo`,`fsr`.`MobileID` AS `MobileID`,`svc`.`TicketStatus` AS `TicketStatus`,`svc`.`FEID` AS `FEID`,`svc`.`DispatchID` AS `DispatchID`,`svc`.`isBillable` AS `isBillable`,`svc`.`SourceID` AS `SourceID`,`svc`.`CategoryID` AS `CategoryID`,`svc`.`SubCategoryID` AS `SubCategoryID`,`svc`.`ProblemReported` AS `ProblemReported`,`svc`.`Vendor` AS `Vendor`,`svc`.`Requestor` AS `Requestor`,`ir`.`REQUEST_FOR` AS `Request_For`,`ir`.`POS_TYPE` AS `POS_Type`,`fsr`.`ReasonID` AS `ReasonID`,`svc`.`RMInstruction` AS `RMInstruction` from (((((((((`tblservicingdetail` `svc` left join `tblfsrdetail` `fsr` on((`fsr`.`ServiceNo` = `svc`.`ServiceNo`))) left join `tblirdetail` `ir` on((`ir`.`IRIDNo` = `svc`.`IRIDNo`))) left join `tblterminaldetail` `td` on((`svc`.`TerminalID` = `td`.`TerminalID`))) left join `tblsimdetail` `sd` on((`sd`.`SIMID` = `svc`.`SIMID`))) left join `tblservicetype` `st` on((`svc`.`JobType` = `st`.`JobType`))) left join `tblparticular` `pt` on((`pt`.`ParticularID` = `svc`.`MerchantID`))) left join `tblregiondetail` `rd` on((`pt`.`RegionID` = `rd`.`RegionID`))) left join `tblregion` `rg` on((`rd`.`RegionType` = `rg`.`RegionID`))) left join `tblreason` `rs` on((`rs`.`ReasonID` = `fsr`.`ReasonID`))) */;

