/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_monitoring_jobs2` AS select `svc`.`ServiceNo` AS `Job_ID`,`svc`.`ServiceNo` AS `ServiceNo`,`fsr`.`FSRNo` AS `FSRNo`,`svc`.`ClientID` AS `ClientID`,`svc`.`MerchantID` AS `MerchantID`,`svc`.`IRIDNo` AS `IRIDNo`,`svc`.`ServiceDate` AS `Request_Date`,`svc`.`ServiceReqDate` AS `Schedule_Date`,`svc`.`ReqInstallationDate` AS `Installation_Date`,(case when (`svc`.`JobType` = '1') then `ir`.`IRDate` else `svc`.`ServiceReqDate` end) AS `Created_Date`,(case when (`svc`.`JobType` = '1') then `ir`.`InstallationDate` else `svc`.`ServiceReqDate` end) AS `Target_Date`,(case when (`svc`.`ServiceStatus` = '2') then 'WAITING' else coalesce(`fsr`.`FSRDate`,'PENDING FSR') end) AS `Service_Date`,`fsr`.`FSRDate` AS `FSRDate`,timestampdiff(DAY,`svc`.`ProcessedDateTime`,now()) AS `Days`,`svc`.`IRIDNo` AS `Request_ID`,`svc`.`IRNo` AS `Request_No`,`svc`.`ReferenceNo` AS `Reference_No`,`svc`.`RequestNo` AS `RequestNo`,`svc`.`JobTypeSubDescription` AS `Request`,`svc`.`JobTypeStatusDescription` AS `Request_Status`,`svc`.`ServiceStatusDescription` AS `Service_Status`,(case when (`svc`.`ServiceStatus` = '2') then 'WAITING' else coalesce(`fsr`.`ActionMade`,'PENDING FSR') end) AS `Service_Result`,`pt`.`ParticularID` AS `Merchant_ID`,`svc`.`MerchantName` AS `Merchant_Name`,`pt`.`Address` AS `Address`,`pt`.`RegionID` AS `Reg_ID`,`pt`.`Region` AS `Region`,`pt`.`RegionType` AS `Prov_ID`,`pt`.`RegionType` AS `RegionType`,`pt`.`RegionID` AS `RegionID`,`pt`.`Province` AS `Province`,`ir`.`MID` AS `MID`,`ir`.`TID` AS `TID`,`ir`.`profile_info` AS `profile_info`,`ir`.`rawdata_info` AS `rawdata_info`,`td`.`TerminalID` AS `Old_TSID`,`svc`.`TerminalSN` AS `Old_TSN`,`svc`.`ReplaceTerminalID` AS `New_TSID`,`svc`.`ReplaceTerminalSN` AS `New_TSN`,(case when (`svc`.`ReplaceTerminalID` in ('0','-','',NULL)) then `td`.`TerminalID` else `svc`.`ReplaceTerminalID` end) AS `Terminal_ID`,(case when (`svc`.`ReplaceTerminalSN` in ('0','-','',NULL)) then `svc`.`TerminalSN` else `svc`.`ReplaceTerminalSN` end) AS `Terminal_SN`,`sd`.`SIMID` AS `Old_SSID`,`svc`.`SIMSerialNo` AS `Old_SSN`,`svc`.`ReplaceSIMID` AS `New_SSID`,`svc`.`ReplaceSIMSN` AS `New_SSN`,(case when (`svc`.`ReplaceSIMID` in ('0','-','',NULL)) then `sd`.`SIMID` else `svc`.`ReplaceSIMID` end) AS `Sim_ID`,(case when (`svc`.`ReplaceSIMSN` in ('0','-','',NULL)) then `svc`.`SIMSerialNo` else `svc`.`ReplaceSIMSN` end) AS `Sim_SN`,`td`.`Model` AS `Model`,`td`.`Type` AS `Type`,`td`.`Brand` AS `Brand`,`svc`.`AppVersion` AS `AppVersion`,`svc`.`AppCRC` AS `AppCRC`,`td`.`Location` AS `Location`,`svc`.`FEName` AS `FE_Name`,`svc`.`ClientName` AS `ClientName`,`st`.`ServiceTypeID` AS `ServiceTypeID`,`st`.`JobType` AS `JobType`,`st`.`ServiceStatus` AS `ServiceStatus`,`st`.`ServiceStatusDescription` AS `ServiceStatusDescription`,`st`.`JobTypeDescription` AS `JobTypeDescription`,`st`.`ServiceJobTypeDescription` AS `ServiceJobTypeDescription`,`fsr`.`MerchantRepresentative` AS `MerchantRepresentative`,`fsr`.`FEName` AS `VendorRepresentative`,`fsr`.`ActualProblemReported` AS `ActualProblemReported`,`fsr`.`ActionTaken` AS `ActionTaken`,`fsr`.`AnyComments` AS `AnyComments`,`fsr`.`Remarks` AS `fsrRemarks`,`fsr`.`Reason` AS `fsrReason`,`fsr`.`FSRRefNo` AS `fsrRefNo`,`fsr`.`MobileID` AS `MobileID`,`svc`.`TicketStatus` AS `TicketStatus`,`svc`.`FEID` AS `FEID`,`svc`.`DispatchID` AS `DispatchID`,`svc`.`isBillable` AS `isBillable`,`svc`.`SourceID` AS `SourceID`,`svc`.`CategoryID` AS `CategoryID`,`svc`.`SubCategoryID` AS `SubCategoryID`,`svc`.`ProblemReported` AS `ProblemReported`,`svc`.`Vendor` AS `Vendor`,`svc`.`Requestor` AS `Requestor`,`svc`.`RMInstruction` AS `RMInstruction` from ((((((((`tblservicingdetail` `svc` left join `tblterminaldetail` `td` on((`svc`.`TerminalSN` = `td`.`TerminalSN`))) left join `tblservicetype` `st` on((`svc`.`JobType` = `st`.`JobType`))) left join `tblterminalmodel` `tm` on((`tm`.`TerminalModelID` = `td`.`TerminalModelID`))) left join (select `tblirdetail`.`MID` AS `MID`,`tblirdetail`.`TID` AS `TID`,`tblirdetail`.`IRIDNo` AS `IRIDNo`,`tblirdetail`.`IRDate` AS `IRDate`,`tblirdetail`.`InstallationDate` AS `InstallationDate`,`tblirdetail`.`profile_info` AS `profile_info`,`tblirdetail`.`rawdata_info` AS `rawdata_info` from `tblirdetail`) `ir` on((`ir`.`IRIDNo` = `svc`.`IRIDNo`))) left join (select `fs`.`FSRDate` AS `FSRDate`,`fs`.`ActionMade` AS `ActionMade`,`fs`.`ServiceNo` AS `ServiceNo`,`fs`.`FSRNo` AS `FSRNo`,`fs`.`MerchantRepresentative` AS `MerchantRepresentative`,`fs`.`FEName` AS `FEName`,`fs`.`ProblemReported` AS `ProblemReported`,`fs`.`ActualProblemReported` AS `ActualProblemReported`,`fs`.`ActionTaken` AS `ActionTaken`,`fs`.`AnyComments` AS `AnyComments`,`fs`.`Remarks` AS `Remarks`,`rs`.`Description` AS `Reason`,`fs`.`FSRRefNo` AS `FSRRefNo`,`fs`.`MobileID` AS `MobileID` from (`tblfsrdetail` `fs` left join `tblreason` `rs` on((`rs`.`ReasonID` = `fs`.`ReasonID`)))) `fsr` on((`fsr`.`ServiceNo` = `svc`.`ServiceNo`))) left join (select `pr`.`ParticularID` AS `ParticularID`,`rd`.`Province` AS `Province`,`rg`.`Region` AS `Region`,`pr`.`RegionType` AS `RegionType`,`pr`.`RegionID` AS `RegionID`,`pr`.`Address` AS `Address` from ((`tblparticular` `pr` left join `tblregiondetail` `rd` on((`pr`.`RegionID` = `rd`.`RegionID`))) left join `tblregion` `rg` on((`rd`.`RegionType` = `rg`.`RegionID`)))) `pt` on((`pt`.`ParticularID` = `svc`.`MerchantID`))) left join `tblregion` `rg` on((`rg`.`RegionID` = `pt`.`RegionType`))) left join (select `ts`.`SIMID` AS `SIMID` from `tblsimdetail` `ts`) `sd` on((`sd`.`SIMID` = `svc`.`SIMID`))) */;

