wdata_info`,'$.Values."QR-P2M (TID)"') AS `QR_P2M_TID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."QR-P2M (MID)"') AS `QR_P2M_MID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 1 - Name"') AS `Multi_Merchant_1_Name`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 1 - TID"') AS `Multi_Merchant_1_TID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 1 - MID"') AS `Multi_Merchant_1_MID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 2 - Name"') AS `Multi_Merchant_2_Name`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 2 - TID"') AS `Multi_Merchant_2_TID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 2 - MID"') AS `Multi_Merchant_2_MID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 3 - Name"') AS `Multi_Merchant_3_Name`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 3 - TID"') AS `Multi_Merchant_3_TID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 3 - MID"') AS `Multi_Merchant_3_MID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 4 - Name"') AS `Multi_Merchant_4_Name`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 4 - TID"') AS `Multi_Merchant_4_TID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 4 - MID"') AS `Multi_Merchant_4_MID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 5 - Name"') AS `Multi_Merchant_5_Name`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 5 - TID"') AS `Multi_Merchant_5_TID`,`fnJsonExtract`(`ir`.`rawdata_info`,'$.Values."Multi-merchant 5 - MID"') AS `Multi_Merchant_5_MID`,`fnJsonExtract`(`ir`.`profile_info`,'$."DCC (Yes/No)"') AS `Dcc`,`fnJsonExtract`(`ir`.`profile_info`,'$."Installment (Yes/No)"') AS `Installment`,`fnJsonExtract`(`ir`.`profile_info`,'$."Manual Key Entry (MKE) (Yes/No)"') AS `Manual_Key_Entry`,coalesce(`fnJsonExtract`(`ir`.`profile_info`,'$."Preauth (Yes/No)"'),'NO') AS `Preauth`,coalesce(`fnJsonExtract`(`ir`.`profile_info`,'$."Offline Sale (Yes/No)"'),'NO') AS `Offline_Sale`,coalesce(`fnJsonExtract`(`ir`.`rawdata_info`,'$."Offline Sale Limit (To be specified)"'),'NO') AS `Offline_Sale_Limit`,coalesce(`fnJsonExtract`(`ir`.`profile_info`,'$."Tip Adjust (Yes/No)"'),'NO') AS `Tip_Adjust`,coalesce(`fnJsonExtract`(`ir`.`rawdata_info`,'$."Tip Adjust Limit (To be specified)"'),'NO') AS `Tip_Adjust_Limit`,coalesce(`fnJsonExtract`(`ir`.`profile_info`,'$."Add-on Device (To be specified)"'),'NO') AS `Add_On_Device`,coalesce(`fnJsonExtract`(`ir`.`profile_info`,'$."ECR Integration (Yes/No)"'),'NO') AS `Ecr_Integration`,coalesce(`fnJsonExtract`(`ir`.`profile_info`,'$."ECR Cable Type"'),'NO') AS `Ecr_Cable`,`ti`.`Terminal_SN` AS `Pos_Serial`,`ti`.`Model` AS `Pos_Model`,if((`fnJsonExtract`(`mi`.`prof_config`,'$.Values."Contactless"') = 1),'Y','N') AS `Contactless`,`ir`.`SET_UP` AS `Current_App`,`ir`.`AppVersion` AS `Pos_Version`,`ir`.`AppCRC` AS `Pos_Crc`,`si`.`Carrier` AS `Sim_Telco`,`si`.`Sim_SN` AS `Sim_Serial`,`ir`.`PrimaryNum` AS `Primary_Dialing`,`ir`.`SecondaryNum` AS `Secondary_Dialing`,date_format(`jo`.`First_Date`,'%b %d, %Y') AS `Original_Installed_Date`,coalesce(`tp`.`Base_Price`,0) AS `Terminal_Cost`,if((`fnJsonExtract`(`mi`.`prof_config`,'$.Values."AutoSettlement"') = 1),'ENABLED','DISABLED') AS `Auto_Settlement`,`fnJsonExtract`(`mi`.`prof_config`,'$.Values."SettleTime"') AS `Auto_Settlement_Time`,if((`bh`.`Status_ID` = 11),date_format(`bh`.`Service_Date`,'%b %d, %Y'),NULL) AS `PullOut_Date`,`bh`.`Client_ID` AS `Client_ID`,`bh`.`Coverage_Date` AS `Coverage_Date` from (((((((`tblbilling_temp` `bh` left join `tblirdetail` `ir` on((`ir`.`IRIDNo` = `bh`.`Ir_ID`))) left join `vw_merchant_info` `mi` on((`mi`.`Merchant_ID` = `bh`.`Merchant_ID`))) left join `vw_terminal_info` `ti` on((`ti`.`Terminal_ID` = `bh`.`Terminal_ID`))) left join `vw_sim_info` `si` on((`si`.`Sim_ID` = `bh`.`Sim_ID`))) left join (select `tblservicingdetail`.`ServiceNo` AS `ServiceNo`,`tblservicingdetail`.`IRNo` AS `IR