/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_service_info` AS select `svc`.`ServiceNo` AS `Job_ID`,`fsr`.`FSRNo` AS `Serv_ID`,`ir`.`IRIDNo` AS `Req_ID`,`svc`.`ServiceDate` AS `Created_Date`,if((`svc`.`JobType` = 1),`ir`.`InstallationDate`,`svc`.`ServiceReqDate`) AS `Target_Date`,`fsr`.`Attempt` AS `Attempt`,`svc`.`ReqInstallationDate` AS `Request_Date`,if((`svc`.`ServiceStatus` = 2),'WAITING',coalesce(`fsr`.`FSRDate`,'PENDING FSR')) AS `Service_Date`,timestampdiff(DAY,`svc`.`ServiceDate`,now()) AS `No_Days`,(case when (`mc`.`Province_ID` = 4) then 3 when (`mc`.`Province_ID` = 5) then 7 else 7 end) AS `SLA`,coalesce((((timestampdiff(DAY,`svc`.`ReqInstallationDate`,coalesce(`fsr`.`FSRDate`,now())) + 1) - (((timestampdiff(DAY,`svc`.`ReqInstallationDate`,coalesce(`fsr`.`FSRDate`,now())) + 1) DIV 7) * 2)) - (case when (weekday(`svc`.`ReqInstallationDate`) in (5,6)) then (case when (weekday(coalesce(`fsr`.`FSRDate`,now())) = 5) then 2 else 1 end) when (weekday(coalesce(`fsr`.`FSRDate`,now())) in (5,6)) then 1 else 0 end)),0) AS `Days`,(case when ((`mc`.`Province_ID` = 4) and ((((timestampdiff(DAY,`svc`.`ReqInstallationDate`,coalesce(`fsr`.`FSRDate`,now())) + 1) - (((timestampdiff(DAY,`svc`.`ReqInstallationDate`,coalesce(`fsr`.`FSRDate`,now())) + 1) DIV 7) * 2)) - (case when (weekday(`svc`.`ReqInstallationDate`) in (5,6)) then (case when (weekday(coalesce(`fsr`.`FSRDate`,now())) = 5) then 2 else 1 end) when (weekday(coalesce(`fsr`.`FSRDate`,now())) in (5,6)) then 1 else 0 end)) > 3)) then 'Beyond TAT' when ((`mc`.`Province_ID` = 5) and ((((timestampdiff(DAY,`svc`.`ReqInstallationDate`,coalesce(`fsr`.`FSRDate`,now())) + 1) - (((timestampdiff(DAY,`svc`.`ReqInstallationDate`,coalesce(`fsr`.`FSRDate`,now())) + 1) DIV 7) * 2)) - (case when (weekday(`svc`.`ReqInstallationDate`) in (5,6)) then (case when (weekday(coalesce(`fsr`.`FSRDate`,now())) = 5) then 2 else 1 end) when (weekday(coalesce(`fsr`.`FSRDate`,now())) in (5,6)) then 1 else 0 end)) > 7)) then 'Beyond' else 'Within' end) AS `TAT_Status`,`svc`.`JobType` AS `Type_ID`,`svc`.`JobTypeSubDescription` AS `Request`,`svc`.`IRNo` AS `Request_No`,if((`svc`.`JobTypeStatusDescription` = 'PROCESSING'),`svc`.`JobTypeStatusDescription`,convert(coalesce(`fsr`.`ActionMade`,'ASSIGNED') using utf8mb3)) AS `Request_Status`,if((`fsr`.`ActionMade` is null),`svc`.`ServiceStatus`,`svc`.`ServiceStatus`) AS `Status_ID`,`svc`.`ServiceStatusDescription` AS `Service_Status`,if((`svc`.`ServiceStatus` = 2),'WAITING',if((`fsr`.`ActionMade` = 'SUCCESS'),'COMPLETED',coalesce(`fsr`.`ActionMade`,'PENDING'))) AS `Service_Result`,`ir`.`MID` AS `MID`,`ir`.`TID` AS `TID`,`mc`.`Merchant_ID` AS `Merchant_ID`,`mc`.`Merchant_Name` AS `Merchant_Name`,`mc`.`Address` AS `Address`,`fsr`.`MerchantRepresentative` AS `Representative`,`fsr`.`MerchantRepresentativePosition` AS `Position`,`fsr`.`MerchantContactNo` AS `Contact`,`fsr`.`MerchantRepresentativeEmail` AS `Email`,`mc`.`Region_ID` AS `Reg_ID`,`mc`.`Region` AS `Region`,`mc`.`Province_ID` AS `Prov_ID`,`mc`.`Province` AS `Province`,`mc`.`Charge` AS `Charge`,coalesce(if((`svc`.`ReplaceTerminalID` in ('0','-','',NULL)),`td`.`Terminal_ID`,`rtd`.`Terminal_ID`),0) AS `Terminal_ID`,coalesce(if((`svc`.`ReplaceTerminalSN` in ('0','-','',NULL)),`td`.`Terminal_SN`,`rtd`.`Terminal_SN`),0) AS `Terminal_SN`,coalesce(if((`svc`.`ReplaceTerminalID` in ('0','-','',NULL)),`td`.`Model_ID`,`rtd`.`Model_ID`),0) AS `Model_ID`,coalesce(if((`svc`.`ReplaceTerminalSN` in ('0','-','',NULL)),`td`.`Model`,`rtd`.`Model`),0) AS `Model_Name`,coalesce(if((`svc`.`ReplaceTerminalID` in ('0','-','',NULL)),`td`.`Type`,`rtd`.`Type`),0) AS `Model_Type`,coalesce(if((`svc`.`ReplaceTerminalSN` in ('0','-','',NULL)),`td`.`Brand`,`rtd`.`Brand`),0) AS `Model_Brand`,`ir`.`AppVersion` AS `App_Version`,`ir`.`AppCRC` AS `App_CRC`,coalesce(if(((`svc`.`JobType` in (1,7)) and (`svc`.`ServiceStatus` = 7) and (`fsr`.`ActionMade` = 'SUCCESS')),if((`svc`.`ReplaceTerminalID` in ('0','-','',NULL)),`tp`.`Base_Price`,`rtp`.`Base_Price`),0),0) AS `Price`,coalesce(if(((`svc`.`JobType` in (1,7)) and (`svc`.`ServiceStatus` = 7) and (`fsr`.`ActionMade` = 'SUCCESS')),if((`svc`.`ReplaceTerminalID` in ('0','-','',NULL)),`tp`.`Rent_Price`,`rtp`.`Rent_Price`),0),0) AS `Rental`,coalesce(if((`svc`.`ReplaceSIMID` in ('0','-','',NULL)),`sd`.`Carrier_ID`,`std`.`Carrier_ID`),0) AS `Carrier_ID`,coalesce(if((`svc`.`ReplaceSIMSN` in ('0','-','',NULL)),`sd`.`Carrier`,`std`.`Carrier`),0) AS `Carrier`,coalesce(if((`svc`.`ReplaceSIMID` in ('0','-','',NULL)),`sd`.`Sim_ID`,`std`.`Sim_ID`),0) AS `Sim_ID`,coalesce(if((`svc`.`ReplaceSIMSN` in ('0','-','',NULL)),convert(`svc`.`SIMSerialNo` using utf8mb3),convert(`std`.`Sim_SN` using utf8mb3)),0) AS `Sim_SN`,coalesce(`td`.`Terminal_ID`,0) AS `Old_TD`,coalesce(`td`.`Terminal_SN`,0) AS `Old_TN`,`td`.`Model` AS `Old_Model`,coalesce(`sd`.`Sim_ID`,0) AS `Old_SID`,coalesce(`sd`.`Sim_SN`,0) AS `Old_SN`,`sd`.`Carrier` AS `Old_Carrier`,`fsr`.`FSRTime` AS `FSR_Time`,`fsr`.`FEID` AS `FE_ID`,`fsr`.`FEName` AS `FE_Name`,`fsr`.`geoAddress` AS `FE_Location`,`fsr`.`TimeArrived` AS `FE_Time_Arrived`,`fsr`.`TimeStart` AS `FE_Time_Start`,`fsr`.`TimeEnd` AS `FE_Time_End`,`fsr`.`Reason` AS `Reason`,`fsr`.`ProblemReported` AS `Problem`,`fsr`.`ActualProblemReported` AS `Actual_Problem`,`fsr`.`ActionTaken` AS `Resolved_Via`,`fsr`.`Remarks` AS `Remarks`,`svc`.`ProcessedBy` AS `Processed_By`,`svc`.`ProcessedDateTime` AS `Processed_Date_Time`,if((`pd`.`ParticularID` in ('','-',NULL)),NULL,`pd`.`ParticularID`) AS `Dispatcher_ID`,if((`pd`.`Name` in ('','-',NULL)),'-',`pd`.`Name`) AS `Dispatch_By`,if((`svc`.`DispatchDateTime` in ('','-',NULL)),'-',`svc`.`DispatchDateTime`) AS `Dispatch_Date_Time`,`svc`.`ModifiedBy` AS `Modified_By`,`svc`.`ModifiedDateTime` AS `Modified_Date_Time`,if((`fsr`.`ProcessedDateTime` in ('','-',NULL)),'-',`fsr`.`ProcessedDateTime`) AS `Completion_Date_Time`,coalesce(`fsr`.`isDiagnostic`,0) AS `Diagnostic_ID`,if((`fsr`.`isDiagnostic` = 1),'YES','NO') AS `Diagnostic`,coalesce(`fsr`.`isPDF`,0) AS `PDF_ID`,if((`fsr`.`isPDF` = 1),'YES','NO') AS `PDF`,`svc`.`TicketStatus` AS `Ticket_ID`,if((`svc`.`TicketStatus` = 1),'CLOSED','OPEN') AS `Ticket`,`svc`.`isBillable` AS `Bill_ID`,if((`svc`.`isBillable` = 1),'YES','NO') AS `Billable`,`svc`.`ClientID` AS `Client_ID`,`svc`.`ClientName` AS `Client_Name` from ((((((((((`tblservicingdetail` `svc` left join `tblirdetail` `ir` on((`ir`.`IRIDNo` = `svc`.`IRIDNo`))) left join `vw_terminal_info` `td` on((`td`.`Terminal_ID` = `svc`.`TerminalID`))) left join `vw_merchant_info` `mc` on((`mc`.`Merchant_ID` = `svc`.`MerchantID`))) left join `vw_sim_info` `sd` on((`sd`.`Sim_ID` = `svc`.`SIMID`))) left join `tblfsrdetail` `fsr` on((`fsr`.`ServiceNo` = `svc`.`ServiceNo`))) left join `tblterminalpricing` `tp` on(((`tp`.`Model_ID` = `td`.`Model_ID`) and (`tp`.`Client_ID` = `ir`.`ClientID`) and (`fsr`.`FSRDate` between `tp`.`Start_Date` and `tp`.`End_Date`)))) left join `tblparticular` `pd` on((`pd`.`ParticularID` = `svc`.`DispatchID`))) left join `vw_terminal_info` `rtd` on((`rtd`.`Terminal_ID` = `svc`.`ReplaceTerminalID`))) left join `vw_sim_info` `std` on((`std`.`Sim_ID` = `svc`.`ReplaceSIMID`))) left join `tblterminalpricing` `rtp` on(((`rtp`.`Model_ID` = `rtd`.`Model_ID`) and (`tp`.`Client_ID` = `ir`.`ClientID`) and (`fsr`.`FSRDate` between `tp`.`Start_Date` and `tp`.`End_Date`)))) */;

