/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_servicing_fee` AS select `svc`.`ServiceNo` AS `Service_No`,`svc`.`isBillable` AS `Valid_ID`,if((`svc`.`isBillable` = 1),'BILLABLE','NON BILLABLE') AS `Validation_Status`,'' AS `Reasons`,'' AS `Citas_Status`,'' AS `Remarks`,`td`.`Brand` AS `Vendor`,concat('\'',date_format(`fsr`.`FSRDate`,'%M %Y')) AS `Period_Month`,'Expense' AS `Service_Type`,`svc`.`JobType` AS `Category_ID`,trim(replace(`svc`.`JobTypeSubDescription`,'FOR','')) AS `Category`,(case when ((`pt`.`Name` like '%EXH%') or (`pt`.`Name` like '%EXHIBIT%')) then 'EXHIBIT' when (`svc`.`JobType` = 6) then 'MAINTENANCE' else trim(replace(`svc`.`JobTypeSubDescription`,'FOR','')) end) AS `Sub_Category`,`rg`.`Charge` AS `Charge`,coalesce(`sc`.`Total_Charge`,0) AS `Total_Charge`,`svc`.`IRNo` AS `MB_Reference_No`,date_format(`svc`.`ReqInstallationDate`,'%m-%d-%Y') AS `Request_Date`,`pt`.`Name` AS `Merchant_Name`,`ir`.`TID` AS `TID`,`ir`.`MID` AS `MID`,`svc`.`TerminalSN` AS `Pos_Serial`,`sd`.`SIMSN` AS `Sim_Serial`,`svc`.`RMInstruction` AS `RM_Instruction`,(case when (`rg`.`RegionID` = 4) then 'MM' when (`rg`.`RegionID` = 5) then 'PROV' else 'Unknown' end) AS `Location`,'' AS `Status`,date_format(`fsr`.`FSRDate`,'%m-%d-%Y') AS `Service_Date`,`fsr`.`ActionTaken` AS `Activity_Remarks`,`fsr`.`Reason` AS `Reason`,`1_try`.`Reason` AS `1st_Attempt`,date_format(`1_try`.`FSRDate`,'%m-%d-%Y') AS `1st_Date`,`2_try`.`Reason` AS `2nd_Attempt`,date_format(`2_try`.`FSRDate`,'%m-%d-%Y') AS `2nd_Date`,`3_try`.`Reason` AS `3rd_Attempt`,date_format(`3_try`.`FSRDate`,'%m-%d-%Y') AS `3rd_Date`,`4_try`.`Reason` AS `4th_Attempt`,date_format(`4_try`.`FSRDate`,'%m-%d-%Y') AS `4th_Date`,`ir`.`ClientID` AS `Client_ID`,`ir`.`ClientName` AS `Client` from (((((((((((`tblservicingdetail` `svc` left join `tblparticular` `pt` on((`pt`.`ParticularID` = `svc`.`MerchantID`))) left join `tblterminaldetail` `td` on((`td`.`TerminalID` = `svc`.`TerminalID`))) left join `tblfsrdetail` `fsr` on((`fsr`.`ServiceNo` = `svc`.`ServiceNo`))) left join `tblsimdetail` `sd` on((`sd`.`SIMID` = `svc`.`SIMID`))) left join `tblirdetail` `ir` on((`ir`.`IRIDNo` = `svc`.`IRIDNo`))) left join `tblregion` `rg` on((`rg`.`RegionID` = `pt`.`RegionType`))) left join (select `sv`.`ServiceNo` AS `ServiceNo`,`sv`.`JobType` AS `JobType`,`fs`.`IRNo` AS `IRNo`,`fs`.`TID` AS `TID`,`fs`.`TerminalID` AS `TerminalID`,`fs`.`Reason` AS `Reason`,`fs`.`ActionMade` AS `ActionMade`,`fs`.`Attempt` AS `Attempt`,`fs`.`FSRDate` AS `FSRDate` from (`tblfsrdetail` `fs` left join `tblservicingdetail` `sv` on((`sv`.`ServiceNo` = `fs`.`ServiceNo`)))) `1_try` on(((`1_try`.`TID` = `ir`.`TID`) and (`1_try`.`JobType` = `svc`.`JobType`) and (`1_try`.`TerminalID` = `svc`.`TerminalID`) and (`1_try`.`Attempt` = 1)))) left join (select `sv`.`ServiceNo` AS `ServiceNo`,`sv`.`JobType` AS `JobType`,`fs`.`IRNo` AS `IRNo`,`fs`.`TID` AS `TID`,`fs`.`TerminalID` AS `TerminalID`,`fs`.`Reason` AS `Reason`,`fs`.`ActionMade` AS `ActionMade`,`fs`.`Attempt` AS `Attempt`,`fs`.`FSRDate` AS `FSRDate` from (`tblfsrdetail` `fs` left join `tblservicingdetail` `sv` on((`sv`.`ServiceNo` = `fs`.`ServiceNo`)))) `2_try` on(((`2_try`.`TID` = `ir`.`TID`) and (`2_try`.`JobType` = `svc`.`JobType`) and (`2_try`.`TerminalID` = `svc`.`TerminalID`) and (`2_try`.`Attempt` = 2)))) left join (select `sv`.`ServiceNo` AS `ServiceNo`,`sv`.`JobType` AS `JobType`,`fs`.`IRNo` AS `IRNo`,`fs`.`TID` AS `TID`,`fs`.`TerminalID` AS `TerminalID`,`fs`.`Reason` AS `Reason`,`fs`.`ActionMade` AS `ActionMade`,`fs`.`Attempt` AS `Attempt`,`fs`.`FSRDate` AS `FSRDate` from (`tblfsrdetail` `fs` left join `tblservicingdetail` `sv` on((`sv`.`ServiceNo` = `fs`.`ServiceNo`)))) `3_try` on(((`3_try`.`TID` = `ir`.`TID`) and (`3_try`.`JobType` = `svc`.`JobType`) and (`3_try`.`TerminalID` = `svc`.`TerminalID`) and (`3_try`.`Attempt` = 3)))) left join (select `sv`.`ServiceNo` AS `ServiceNo`,`sv`.`JobType` AS `JobType`,`fs`.`IRNo` AS `IRNo`,`fs`.`TID` AS `TID`,`fs`.`TerminalID` AS `TerminalID`,`fs`.`Reason` AS `Reason`,`fs`.`ActionMade` AS `ActionMade`,`fs`.`Attempt` AS `Attempt`,`fs`.`FSRDate` AS `FSRDate` from (`tblfsrdetail` `fs` left join `tblservicingdetail` `sv` on((`sv`.`ServiceNo` = `fs`.`ServiceNo`)))) `4_try` on(((`4_try`.`TID` = `ir`.`TID`) and (`4_try`.`JobType` = `svc`.`JobType`) and (`4_try`.`TerminalID` = `svc`.`TerminalID`) and (`4_try`.`Attempt` = 4)))) left join (select `svc`.`ServiceNo` AS `ServiceNo`,`svc`.`JobTypeSubDescription` AS `JobTypeSubDescription`,(case when ((`svc`.`JobType` = 4) and ((`pt`.`Name` like '%EXH%') or (`pt`.`Name` like '%EXHIBIT%'))) then 0 when (`rg`.`RegionID` = 5) then (case when (count(`svc`.`MerchantID`) between 1 and 3) then `rg`.`Charge` when (count(`svc`.`MerchantID`) between 4 and 6) then (`rg`.`Charge` * 2) when (count(`svc`.`MerchantID`) between 7 and 9) then (`rg`.`Charge` * 3) when (count(`svc`.`MerchantID`) >= 10) then (`rg`.`Charge` * 4) else `rg`.`Charge` end) else `rg`.`Charge` end) AS `Total_Charge`,`svc`.`IRNo` AS `Request_No`,`svc`.`ReqInstallationDate` AS `Request_Date`,`ir`.`TID` AS `TID`,`svc`.`TerminalID` AS `TerminalID`,`sd`.`SIMID` AS `SIMID`,`fsr`.`FSRDate` AS `FSRDate` from ((((((`tblservicingdetail` `svc` left join `tblparticular` `pt` on((`pt`.`ParticularID` = `svc`.`MerchantID`))) left join `tblterminaldetail` `td` on((`td`.`TerminalID` = `svc`.`TerminalID`))) left join `tblfsrdetail` `fsr` on((`fsr`.`ServiceNo` = `svc`.`ServiceNo`))) left join `tblsimdetail` `sd` on((`sd`.`SIMID` = `svc`.`SIMID`))) left join `tblirdetail` `ir` on((`ir`.`IRIDNo` = `svc`.`IRIDNo`))) left join `tblregion` `rg` on((`rg`.`RegionID` = `pt`.`RegionType`))) where (`svc`.`JobTypeStatusDescription` = 'COMPLETED') group by `svc`.`JobType`,`svc`.`MerchantID`,`rg`.`RegionID`,`fsr`.`FSRDate`) `sc` on((`sc`.`ServiceNo` = `svc`.`ServiceNo`))) where (`svc`.`JobTypeStatusDescription` = 'COMPLETED') */;

